UPDATE public.questions SET analysis = '正确答案为A,B,D。根据《中华人民共和国食品安全法》及相关法规标准规定，A、食品生产企业建立食品添加剂和食品工业用加工助剂的使用制度；B、生产设备上可能直接或间接接触食品的活动部件使用食用油脂润滑；D、除清洁消毒必需和工艺需要，不应在生产场所使用和存放可能污染食品的化等选项符合法规要求。' WHERE id = '0aacc00c-e091-4c75-821a-6efb294fdd4b';
UPDATE public.questions SET analysis = '正确答案为A,B。根据《中华人民共和国食品安全法》及相关法规标准规定，苯甲酸及其钠盐；山梨酸及其钠盐等选项符合法规要求。' WHERE id = '0aad72ff-15bc-4b6f-9f22-96ceafdfc00c';
UPDATE public.questions SET analysis = '《反食品浪费法》规定，餐饮服务经营者应引导消费者按需适量点餐，提供小份餐等不同规格选择。' WHERE id = '0abfc623-7afe-4e1f-afb8-945440b7bac7';
UPDATE public.questions SET analysis = '正确答案为C。根据《中华人民共和国食品安全法》及相关法规标准规定，县级人民政府食品安全监督管理部门。其他选项不符合相关法规要求。' WHERE id = '0ad6fd48-be94-4a01-9937-9df9a7409262';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第六十三条，食品生产企业召回已经上市销售的食品，应当通知相关生产经营者和消费者，并记录召回和通知情况。因此题目说法错误。' WHERE id = '0ad99895-33b2-4235-ac7c-dbd702f3e46e';
UPDATE public.questions SET analysis = '根据《乳品质量安全监督管理条例》第三十六条，乳制品生产企业发现其生产的乳制品不符合标准、存在危害人体健康危险的，应当立即停止生产，报告主管部门并告知销售者、消费者，召回已出厂销售的乳制品，并记录召回情况。四项全选。' WHERE id = '0af50553-1946-4db2-bfce-db9b048294b2';
UPDATE public.questions SET analysis = '根据《学校食品安全与营养健康管理规定》第二十五条，学校食堂食品加工、贮存、陈列、转运等设施设备应当定期维护、清洗、消毒；保温设施及冷藏冷冻设施应当定期清洗、校验。' WHERE id = '0af65b34-8980-48cb-b4c0-bdebd27b3307';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第七十四条，国家对保健食品等特殊食品实行严格监督管理。销售保健食品必须遵守食品安全法的各项规定。' WHERE id = '0afea997-26fe-4994-a523-ffb7d254513b';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第6.4.2条，应制定和执行虫害控制措施，在生产经营场所配置纱帘、纱网、防鼠板、防蝇灯、风幕等装置，防止鼠类昆虫等侵入。' WHERE id = '0b02f867-4073-4cba-8612-0f2bc387e5d3';
UPDATE public.questions SET analysis = '根据GB 14881-2013，分隔是指通过设置物理阻断如墙壁、卫生屏障、遮罩或独立房间/区域等方式进行隔离，而非仅在物品、设施、区域之间留有一定空间。题目说法错误。' WHERE id = '0b10925c-f5c7-4ad5-8a73-7e8d176037ef';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第8.4.3条，食品生产企业应采取设置筛网、捕集器、磁铁、金属检查器等有效措施，降低金属或其他异物污染食品的风险。' WHERE id = '0b322e98-0b65-4f12-a334-f2043d46cb36';
UPDATE public.questions SET analysis = '根据《食品生产许可分类目录》，茶制品的申证类别编号确为1402，包括茶叶、茶粉、茶浓缩液等产品。' WHERE id = '0b4d80ce-adb4-4237-a46c-fa685a4d8463';
UPDATE public.questions SET analysis = '根据《保健食品注册与备案管理办法》第五十七条，保健食品通用名不得含有：已注册药品通用名（除原料命名或注册在先外）、保健功能名称、易产生误导的原料简写名称、营养素补充剂产品配方中部分维生素或矿物质。四项全选。' WHERE id = '0b71f40d-022b-4635-bd75-b76964e35707';
UPDATE public.questions SET analysis = '根据《食品安全法》第八十八条，复检机构由申请人从公布的复检机构名录中随机选择，而非由监督管理部门指定；复检机构与初检机构不得为同一机构；复检结论为最终检验结论。因此A、B、D表述不正确。' WHERE id = '0b97ef16-765a-4e86-8aa4-99dbcc0a9231';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第六十三条，食品生产经营者应当对召回的食品采取无害化处理、销毁等措施，防止其再次流入市场。废弃和填埋不属于法定处置方式。选B、C。' WHERE id = '0b9c1ccc-5e6d-4586-8829-7fb5863dde0f';
UPDATE public.questions SET analysis = '根据《餐饮服务食品安全操作规范》及GB 14881要求，从业人员切配即食食品（如水果）前必须佩戴口罩、帽子，并洗手消毒，防止交叉污染和微生物污染。' WHERE id = '0b9cfa55-bcb0-4d30-9046-1a72e9ac7909';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第五十三条，食品经营者采购食品，应当查验供货者的许可证和食品出厂检验合格证或者其他合格证明。' WHERE id = '0bcce2b5-0de3-4eb8-98e6-c99579ca0e99';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 预包装食品标签通则》（GB 7718-2011）第4.1.5.7条，同一预包装内含有多个单件预包装食品时，大包装应标示净含量和规格。因此题目说法错误。' WHERE id = '0bd0a02b-9429-4b5b-9607-9f6dbeca091f';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第三十八条，生产经营的食品中不得添加药品，但是可以添加按照传统既是食品又是中药材的物质。因此题目说法错误。' WHERE id = '0be17964-5127-46b4-95ec-0db454cba8dc';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第四十四条，食品生产经营企业的主要负责人应当对本企业的食品安全工作全面负责。选D。' WHERE id = '0be2d32d-a470-4a25-a614-b93f13e0de34';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第三十三条，食品生产经营企业应当配备食品安全管理人员，加强对其培训和考核。选C。' WHERE id = '0c0321f6-2c2a-4a8f-aff0-114ca469ba5d';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）及食用油生产相关规定，加强原辅料控制、生产过程控制、标签说明书管理和设施设备管理，都是提升食用油质量安全水平的有效措施。四项全选。' WHERE id = '0c195e4b-7078-4ce1-a7fd-d4896047a5c1';
UPDATE public.questions SET analysis = '根据GB 24154-2015，对于添加了肌酸的产品应在标签中标示''孕妇、哺乳期妇女、儿童及婴幼儿不适宜食用''，而非添加牛磺酸的产品。因此题目说法错误。' WHERE id = '0c2d08f9-a5a6-4fc4-8f05-7b1692ce1bdf';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第六十三条，食品经营者应当向所在地县级人民政府食品安全监督管理部门报告召回和处理情况，而非向乡镇政府（街道）报告。因此题目说法错误。' WHERE id = '0c31327f-da1a-4529-b3bb-513edb2aac2d';
UPDATE public.questions SET analysis = '根据《学校食品安全与营养健康管理规定》第十条，学校在食品采购、食堂管理等重大事项上，应当以适当方式听取家长委员会、学生代表大会、教职工代表大会意见。选A、B、C。' WHERE id = '0c32d483-7641-41ae-aca1-1cf7fad0ba42';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第六十七条，专供婴幼儿和其他特定人群的主辅食品，其标签还应当标明主要营养成分及其含量。选B。' WHERE id = '0c37a6d7-6534-44bf-a139-d8413d3abecf';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第七十条，食品添加剂的标签、说明书应当载明使用范围、用量、''食品添加剂''字样等内容。因此选D（以上都是）。' WHERE id = '0c3ff6f6-b30a-4fbd-94a3-5901b657ffae';
UPDATE public.questions SET analysis = '根据《婴幼儿配方乳粉产品配方注册管理办法》第五十二条，未如实标明原料具体来源的，由食品药品监督管理部门责令改正，并处1万元以上3万元以下罚款。选B。' WHERE id = '0c41553b-ac21-4977-9de8-da2617411408';
UPDATE public.questions SET analysis = '根据《食品生产经营监督检查管理办法》第三条，食品生产经营监督检查是市场监管部门实施监督管理的重要手段，是加强食品安全事中事后监管工作的具体形式。' WHERE id = '0c4f2241-b27f-44fa-ab39-39b77a456a1b';
UPDATE public.questions SET analysis = '根据《婴幼儿配方乳粉产品配方注册管理办法》第三十三条，审评机构应当自受理复审申请之日起30个工作日内作出复审决定。选C。' WHERE id = '0c5e51bc-7503-493b-8614-36535a521495';
UPDATE public.questions SET analysis = '根据冷冻饮品生产许可审查细则及GB 14881要求，灌装工序属于直接暴露环节，应纳入清洁作业区管理。选C。' WHERE id = '0c7c7e13-1ec5-41c8-91b6-5e0e16bc61cf';
UPDATE public.questions SET analysis = '根据GB 2762-2022，豆沙馅属于豆类制品范畴，适用豆类制品的污染物限量要求。因此题目说法错误。' WHERE id = '0c86ced5-cbc3-4ef2-b941-b941707f6065';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 包装饮用水》（GB 19298-2014），当包装饮用水中添加食品添加剂时，应在产品名称的邻近位置标示''添加食品添加剂用于调节口味''等类似字样。' WHERE id = '0c977250-0641-43f2-9839-14d1382a5750';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013），同一食品品种不同包装的产品，不受包装规格和包装形式影响的检验项目可以一并检验，以减少重复检测。' WHERE id = '0c9f7b40-5a7e-4eb3-89ff-2a4ec15f273d';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第三条，食品生产经营企业主要负责人是指承担全面领导责任的法定代表人、实际控制人等主要决策人。' WHERE id = '0cbdca85-af9a-4d3a-b355-ce927a6b5c51';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第14.1.1条，食品生产企业应重视产品研发管理，对新工艺、新产品应进行安全性验证，确保符合食品安全标准。' WHERE id = '0cd6d61f-f0f8-4471-bacf-d96b939086a3';
UPDATE public.questions SET analysis = '根据GB 14881-2013第4.2.3条，车间隔墙与地面连接处应呈弧形，便于清洁，防止污垢积存；顶棚应不利于冷凝水垂直滴下；地面应无毒、无味、不渗透、耐腐蚀、平坦防滑。因此A选项表述不正确。' WHERE id = '0ce8b2b8-17d7-435f-8530-7a0be7d6f663';
UPDATE public.questions SET analysis = '根据《方便面》国家标准及生产许可分类，方便面包括油炸方便面和非油炸方便面两大类。选A。' WHERE id = '0d022b1e-5490-41c6-9f5b-c3e89b2438ed';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第六条，食品安全总监职责包括：组织拟定食品安全管理制度、风险防控措施、事故处置方案，管理督促食品安全员工作等。四项全选。' WHERE id = '0d1ad297-fd77-4431-b1c3-8a474ec84677';
UPDATE public.questions SET analysis = '根据《食品生产经营监督检查管理办法》第十四条，飞行检查是指市场监督管理部门根据监督管理工作需要以及问题线索等，对食品生产经营者依法开展的不预先告知的监督检查。选B。' WHERE id = '0d2f91fc-0692-4e50-89d0-3719db4128eb';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第六十三条，食品经营者发现其经营的食品不符合食品安全标准的，应当立即停止经营，通知相关生产经营者和消费者，召回已经上市销售的食品。选D。' WHERE id = '0d34c708-9770-40f0-a569-5cf33d4b3176';
UPDATE public.questions SET analysis = '根据《食品安全抽样检验管理办法》及检验检测机构资质认定相关规定，食品检验机构依据食品补充检验方法出具具有法律效力的检验数据和结果时，必须取得检验检测机构资质认定（CMA）。' WHERE id = '0d3db2e1-6f12-4fb8-aa4d-d1aeb2bd35dd';
UPDATE public.questions SET analysis = '根据《学校食品安全与营养健康管理规定》第二十五条，学校食堂在加工前应当检查待加工的食品及原料，发现不符合要求情形的不得加工或使用，用水应符合国家规定的生活饮用水卫生标准。' WHERE id = '0d6ce38f-9e7d-44d9-a13a-9c75f12d3166';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）及HACCP原理，食品生产经营企业可通过严格原料进货查验避免从污染区域采购原料，降低原料带来的化学性危害。' WHERE id = '0d74502f-5162-4980-a2fc-39b8c01ddf44';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第三条，制定和实施合规、合理的食品安全管理制度，是企业承担食品安全主体责任的重要体现和具体要求。' WHERE id = '0d82456e-6cbf-4518-98fd-a58f1d680ccc';
UPDATE public.questions SET analysis = '根据豆制品生产相关标准，干豆腐（豆腐干薄片）的含水量应在35%～65%之间，具有一定的弹性和韧性。选A。' WHERE id = '0d8adcdc-85e0-4940-8f6e-7e9317a6ded4';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第四十七条，食品生产企业应当建立食品安全自查制度，定期对食品安全状况进行检查评价。选A。' WHERE id = '0d8e3288-74c0-49da-8b57-44cb24c37035';
UPDATE public.questions SET analysis = '根据《食品经营许可管理办法》及《食品安全国家标准 食品生产通用卫生规范》（GB 14881），食品销售场所和食品贮存场所应当与生活区分（隔）开，防止交叉污染。' WHERE id = '0d8fee02-7999-47ff-ae9f-893cddca44b9';
UPDATE public.questions SET analysis = '根据《食品安全法》第六十八条，食品经营者销售散装食品，应当在散装食品的容器、外包装上标明食品的名称、生产日期或生产批号、保质期、生产经营者名称等内容。因此题目说法错误。' WHERE id = '0d97e40d-4941-4b1c-b868-f6a3950f194a';
UPDATE public.questions SET analysis = '根据《食品生产许可分类目录》及炒货食品相关标准，炒货食品及坚果制品按加工工艺可分为烘炒类、油炸类和其他类。选项A表述为''选项全是''即涵盖了所有分类。选A。' WHERE id = '0d99ea53-2fbb-4dc1-b085-ebf05f01b09b';
UPDATE public.questions SET analysis = '乳制品加工过程微生物监控程序包括生产环境监控和过程产品监控，不包括产品出厂微生物检验（属于出厂检验环节）。选C。' WHERE id = '0d9c156d-167d-4557-9edf-dd7036e77207';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 预包装食品标签通则》（GB 7718），对特殊群体易造成危害的、经电离辐射处理过的、属于转基因食品的以及按规定应当标注其他中文说明的，均应在标识上标注中文说明。四项全选。' WHERE id = '0dc0f5f0-8002-4275-9dad-36c11eb11257';
UPDATE public.questions SET analysis = '根据《婴幼儿配方乳粉产品配方注册管理办法》第二十三条，婴幼儿配方乳粉产品配方注册号格式为：国食注字YP＋4位年代号＋4位顺序号。选B。' WHERE id = '0dd2b7ce-4078-429a-9bb0-1754ed9ffe02';
UPDATE public.questions SET analysis = '根据《蔬菜干制品》相关标准，原味非油炸水果、蔬菜脆片是指以水果、蔬菜为原料，采用非油炸脱水工艺制成的口感酥脆的干制品。选A。' WHERE id = '0de07e0a-0e73-4366-b7f6-805ab76defd7';
UPDATE public.questions SET analysis = '根据《食品经营许可管理办法》第二十六条，餐饮服务提供者应当在经营场所的显著位置悬挂、摆放纸质食品经营许可证正本或者展示其电子证书。选D。' WHERE id = '0de8409d-65c4-4dc1-81f7-fe1569d85c5d';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》，连锁食品销售企业总部应当对总部自身、仓储（配送中心）、加工中心（中央厨房）和门店等各环节开展食品安全自查。四项全选。' WHERE id = '0de9a574-21bb-414b-ac37-5aac63b69b09';
UPDATE public.questions SET analysis = '根据《豆制品》相关标准，豆浆是指大豆经加水研磨、加热等使蛋白质溶出，除去豆渣后所得总固形物含量在6%以上的乳状液。选C。' WHERE id = '0ded99f1-43fa-46c6-8675-96e5c27394ff';
UPDATE public.questions SET analysis = '根据《特殊医学用途配方食品注册管理办法》第九条，申请注册应提交产品标签说明书样稿、试验样品检验报告、研发生产检验能力证明材料、产品标准要求等。四项全选。' WHERE id = '0df8cbf5-86b4-479e-a90b-805510b477df';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第十一条，连锁食品销售企业总部应当对企业各环节、各位点开展食品安全自查，确保全链条食品安全。' WHERE id = '0e3147e0-3401-4e1e-9352-07601db550f7';
