UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第三十三条，食品的贮存和运输必须遵守食品安全法的规定，包括容器、工具、条件等要求。因此题目说法错误。' WHERE id = '0e44f513-afe5-4708-b6f3-14a1caf8a1d7';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）及食用油贮存相关规定，应按品种等级分别贮存、配备温控设施、运输工具符合标准要求。因此选D（以上都对）。' WHERE id = '0e4ca089-1247-4a30-b2f5-76a8e20b92c4';
UPDATE public.questions SET analysis = '根据《食品生产经营监督检查管理办法》第十四条，飞行检查是指市场监督管理部门根据监督管理工作需要以及问题线索等，对食品生产经营者依法开展的不预先告知的监督检查。' WHERE id = '0e50e948-9dfd-478e-a54c-fc7c4a41fb40';
UPDATE public.questions SET analysis = '根据《糕点生产许可证审查细则》及GB 14881，糕点生产车间应划分为清洁作业区、准清洁作业区和一般作业区，一般作业区应与其他区域有效分隔，防止交叉污染。' WHERE id = '0e61c744-ece0-4679-bee6-feec8663426e';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第七十条，食品添加剂应当有标签、说明书和包装，标签上应载明''食品添加剂''字样。禁止生产无标签的预包装食品和食品添加剂。因此题目说法错误。' WHERE id = '0e8de5a2-f3b9-4d8b-95d5-b5844f7a0f04';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第三十条，国家鼓励食品生产企业制定严于食品安全国家标准或者地方标准的企业标准，在本企业适用，并报省、自治区、直辖市人民政府卫生行政部门备案。' WHERE id = '0e96cb25-fa73-4789-9b7d-209801b5b087';
UPDATE public.questions SET analysis = '根据《食品安全法》第六十三条，食品召回应先向所在地县级食品安全监督管理部门报告，再对召回食品进行无害化处理或销毁。C选项顺序颠倒，表述不正确。选C。' WHERE id = '0e98873f-034e-4f3b-b512-dda32d462bb4';
UPDATE public.questions SET analysis = '根据《中华人民共和国标准化法》第二条，对满足基础通用、与强制性国家标准配套、对各有关行业起引领作用等需要的技术要求，可以制定推荐性国家标准。选D。' WHERE id = '0eb052b9-b0d4-4f01-a9be-5edf7a68d5db';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第五条，国务院设立食品安全委员会，其职责由国务院规定，而非全国人大规定。因此题目说法错误。' WHERE id = '0ece37c5-699a-47f5-bcd1-deefc5788db3';
