UPDATE public.questions SET analysis = '根据《食品安全法实施条例》第七十五条，对故意实施违法行为、违法行为性质恶劣、违法行为造成严重后果的情形，可以对单位的法定代表人、主要负责人等''处罚到人''。选A、B、C。' WHERE id = '0f8a0b85-77e8-4815-a392-5788e93935f8';
