UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第四十五条，患有有碍食品安全疾病的人员治愈后，需重新办理健康证明方可恢复从事接触直接入口食品的工作。因此题目说法错误。' WHERE id = '1196e35e-84f2-4041-a26b-1aaac69dfca7';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第三十五条，仅销售预包装食品的，应当报所在地县级以上地方食品安全监督管理部门备案。选C。' WHERE id = '11b201a9-0b6e-45dd-8e9f-40c50923b8e8';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第十九条，因食品安全犯罪被判处有期徒刑以上刑罚的人员，终身不得担任食品安全总监、食品安全员。因此题目说法错误。' WHERE id = '11b589df-f736-480e-90e2-c30eb8805cf2';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第7.2.5条，食品原料不得与有毒、有害物品同时装运，避免污染食品原料。' WHERE id = '11b80e39-8635-4dcd-b9ba-d0248ba5bb7e';
UPDATE public.questions SET analysis = '根据《餐饮服务食品安全操作规范》，餐饮服务企业应建立食品安全培训制度（非考核制度），组织对各岗位从业人员进行食品安全知识培训。因此题目说法错误。' WHERE id = '11d18f81-d0ad-4b55-99a1-6cb904ce1fb8';
UPDATE public.questions SET analysis = '根据《食品生产经营监督检查管理办法》第十三条，日常监督检查指市级、县级市场监督管理部门按照年度监督检查计划，对本行政区域内食品生产经营者开展的常规性检查。' WHERE id = '11d2c3bd-7e15-428a-b564-c1a5f34a480b';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第十二条，企业主要负责人应当对当月食品安全管理工作进行总结，对下个月重点工作作出调度安排。选B。' WHERE id = '11edbb15-f866-45ff-b7fd-32b9a3d7c5f2';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第五十条，进货查验记录应如实记录食品的名称、规格、数量、生产日期、供货者名称、地址、联系方式等内容。' WHERE id = '1208e05f-e9d9-4ea0-8199-39e9afaf3a62';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第四十五条，患有国务院卫生行政部门规定的有碍食品安全疾病的人员，不得从事接触直接入口食品的工作。选B。' WHERE id = '120a0d62-1fb0-4325-a687-2cc29c22ce3b';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 酱油》（GB 2717），不得生产经营标示为''配制酱油''''配制食醋''的产品。因此题目说法错误。' WHERE id = '120c8abc-827b-434a-ab31-6280169e721c';
UPDATE public.questions SET analysis = '根据《坚果炒货食品生产许可证审查细则》，核桃属于坚果；花生、大豆属于油料作物；蚕豆属于豆类。选C。' WHERE id = '12270d13-484e-4a86-8cd3-35d3033b76b6';
UPDATE public.questions SET analysis = '根据《保健食品注册与备案管理办法》第二十二条，作出准予注册或不予注册决定后，应由受理机构向注册申请人发出注册证书或不予注册决定。选B。' WHERE id = '122cb336-42ce-4386-b5d5-5e8ee8a85f36';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第四十五条，从事接触直接入口食品工作的食品生产人员必须取得有效健康证明后方可上岗，健康证过期不得继续从事食品生产活动。因此题目说法错误。' WHERE id = '1232a4b9-8ce6-42e3-ac58-ace3668cb133';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 速冻面米与调制食品》（GB 19295），速冻调制食品是以一种或多种原料，配以馅料或辅料，经调制、加工、成型等速冻而成的食品。选C。' WHERE id = '1273d697-c6a6-4348-9305-99cd3b3b3a6a';
UPDATE public.questions SET analysis = '食品补充检验方法和食品快速检测方法均可在国家市场监督管理总局食品安全抽检监测司网站查询。因此题目说法错误。' WHERE id = '127d7759-347e-4698-a86a-a765d9d9baa1';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品添加剂使用标准》（GB 2760）及乳制品生产相关规定，生产过程中不允许超范围或超限量使用食品添加剂。选A、B。' WHERE id = '128467d1-4dcc-4ab3-86ac-d8da27c86b42';
UPDATE public.questions SET analysis = '根据《食品经营许可管理办法》及《食品安全国家标准 食品经营过程卫生规范》（GB 31621），鼓励在售卖场所使用非敞开式冷藏冷冻设施设备，以保证食品贮存安全。选B。' WHERE id = '12867228-eebd-4a7b-b787-293421eda7d0';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第一百四十八条，消费者因食用不符合食品安全标准的食品受到损害，可以向生产者或经营者要求赔偿，生产者应实行首负责任制，先行赔付。因此题目说法错误。' WHERE id = '128bd3a9-8298-4451-aad2-62b4a80e6ff8';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第四十四条，食品生产经营企业应当配备食品安全管理人员，加强培训和考核，经考核不具备食品安全管理能力的不得上岗，监管部门应随机抽查考核并公布情况。' WHERE id = '12982677-a5b0-48c5-a2c0-e0ab9f5c2bca';
UPDATE public.questions SET analysis = '根据《食品经营许可管理办法》第十二条，利用自动设备从事餐饮服务的，申请人应当提交每台设备的具体放置地点、食品经营许可证展示方法、食品安全风险管控方案等材料。' WHERE id = '129a0d7d-175d-4c53-b397-b12ed433219f';
UPDATE public.questions SET analysis = '根据《饮料酒术语和分类》（GB/T 17204），发酵酒是以粮谷、水果、乳类等为主要原料，经发酵或部分发酵酿制而成的饮料酒。' WHERE id = '12a7e788-8ac0-430c-8ff9-942afeb182fd';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第三条，企业主要负责人是指承担全面领导责任的法定代表人、实际控制人等主要决策人；直接负责的主管人员包括食品安全总监；其他直接责任人员包括食品安全员。' WHERE id = '12c45096-9dba-4195-8a19-976120bdc484';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第一百三十五条，被吊销许可证的食品生产企业及其法定代表人、直接负责的主管人员和其他直接责任人员，自处罚决定作出之日起五年内不得申请食品生产经营许可或从事食品安全管理工作。因此题目说法错误。' WHERE id = '12c53089-dcaa-4178-b137-497e80237e83';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食醋》（GB 2719），食醋中菌落总数的限量表示为n=5，c=2，m=1000（CFU/mL)，M=10000（CFU/mL)。选A。' WHERE id = '12c63a4b-be0e-4448-9df9-93335ef71082';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第三十三条，食品生产企业应当具有合理的设备布局和工艺流程，防止交叉污染，避免食品接触有毒物、不洁物。' WHERE id = '12dc41c8-6608-4f05-9ba2-f9b1aecb94ce';
