UPDATE public.questions SET analysis = '根据GB 7718-2011第3.2条，日期标示不得另外加贴、补印或篡改，生产日期应清晰标示在标签上。因此题目说法错误。' WHERE id = '12e2139a-b241-4219-a6d7-3fa4e37fa8ea';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 酱油》（GB 2717），酱油生产许可仅包括酿造酱油，不再包括配制酱油。因此题目说法错误。' WHERE id = '12e874c4-3690-449b-9cab-373bdcf525c8';
UPDATE public.questions SET analysis = '根据《食品生产许可分类目录》，调味茶产品分为加料调味茶、加香调味茶、混合调味茶、袋泡调味茶和紧压调味茶。选B。' WHERE id = '12f5a493-ade6-48d0-8eb5-e06f97b94aa6';
UPDATE public.questions SET analysis = '根据《薯类食品生产许可证审查细则》，甘薯干、甘薯片的生产工艺包括鲜薯验收、清洗去皮、切分成型、蒸煮、干制、包装等。选A。' WHERE id = '12ffd03b-86d2-41c3-bce3-d382b7bfff39';
