UPDATE public.questions SET analysis = '根据《食品安全抽样检验管理办法》第十四条，现场抽样时，抽样人员可以从食品经营者的经营场所、仓库以及食品生产者的成品库待销产品中随机抽取样品。选A、B、C。' WHERE id = '13065f88-bbbe-458b-87fd-04d5fa1c9ded';
UPDATE public.questions SET analysis = '根据《食品安全抽样检验管理办法》第十六条，食品生产经营者应当依法配合市场监督管理部门组织实施的食品安全抽样检验工作，不得拒绝提供样品。' WHERE id = '1313b718-f450-4b56-921d-1bffecad6e54';
