UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第6.4.1条，虫害是指由昆虫、鸟类、啮齿类动物等生物（包括苍蝇、蟑螂、麻雀、老鼠等）造成的不良影响。四项全选。' WHERE id = '1340d9c3-ff00-4d06-8264-d6802ed1e09a';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第三条，食品生产经营企业主要负责人是指在本企业生产经营中承担全面领导责任的法定代表人、实际控制人等主要决策人。' WHERE id = '13609a22-5b05-4210-8411-2922a6d04839';
UPDATE public.questions SET analysis = '根据GB 2733-2015《食品安全国家标准 鲜、冻动物性水产品》，以水产动物内脏、卵、皮等非肌肉组织作为水产制品原料的，应符合GB 2733的要求。选B。' WHERE id = '13624ae8-edc9-4f0b-bb20-a00b7879a69f';
