UPDATE public.questions SET analysis = '根据《食品安全国家标准 巧克力、代可可脂巧克力及其制品》（GB 9678.2），巧克力制品中巧克力成分不得低于25%（质量分数）。选A。' WHERE id = '13882692-9ee5-4cf7-923c-1053acde8681';
