UPDATE public.questions SET analysis = '根据可可制品检验方法，检测可可液块、可可饼块的水分及挥发物需要分析天平（0.0001g）、干燥箱和干燥器，不需要电热板。选A、B、D。' WHERE id = '13d266df-7dcd-450f-bc2a-eda4e9b629a9';
UPDATE public.questions SET analysis = '水分及挥发物检验需要干燥箱、干燥器和分析天平，马弗炉用于灰分测定而非水分测定。选D。' WHERE id = '13df9d74-92f5-40ab-9497-b1583a0a4cc9';
