UPDATE public.questions SET analysis = '根据GB 14881-2013第5.1.8条和第6.5.1条，应配备废弃物存放专用设施，设施应设计合理、防止渗漏、易于清洁，标识清晰并及时处理；设施设备应定期清洁、校准、维护。' WHERE id = '13ea5a66-ac24-4ec9-adef-eb11028df1a7';
UPDATE public.questions SET analysis = '根据《新食品原料安全性审查管理办法》第六条，新食品原料生产单位应当按照公告要求进行生产，保证新食品原料的食用安全。' WHERE id = '13f28fef-ffa7-4b7f-bd36-f2ceb73cb6a5';
UPDATE public.questions SET analysis = '根据《食品经营许可管理办法》第四十八条，餐饮服务提供者未按规定申请变更的，逾期不改的处一千元以上一万元以下罚款。选C。' WHERE id = '13f72523-0a0b-472a-b656-1b7141a64c00';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第六十八条，散装食品贮存位置应标明名称、生产日期或批号、保质期等，成分或配料表不是散装食品必须标明的内容。选C。' WHERE id = '1404665b-05de-4346-b92a-c935d1a956ec';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第8.1.2条，鼓励采用危害分析与关键控制点（HACCP）体系对生产过程进行食品安全控制。' WHERE id = '1404a7fd-e418-43ad-a143-52d7580a4af7';
UPDATE public.questions SET analysis = '根据《淀粉及淀粉制品生产许可审查细则》，次氯酸钠氧化淀粉属于变性淀粉，不在淀粉及淀粉制品生产许可范围内。选D。' WHERE id = '140963f4-f0c4-441b-8696-d1e2936db17a';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第5.2.1条，盛装食品原料的容器应符合食品安全标准，木桶不易清洁消毒、易滋生微生物，不宜使用。选D。' WHERE id = '14143479-9da7-4bfa-8d70-2ed8e11357b5';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第三十四条，禁止在食品加工中添加非食用化学物质和其他可能危害人体健康的物质。' WHERE id = '143d636f-9741-42b6-81c2-9017f60d2c4c';
UPDATE public.questions SET analysis = '根据《网络食品安全违法行为查处办法》第十三条，网络食品交易第三方平台提供者应在信息查询、数据提取、停止服务等方面为监管部门提供技术支持。' WHERE id = '14407129-3a87-4fd1-8d9c-e276c7cee929';
UPDATE public.questions SET analysis = '根据《冷冻饮品》国家标准，冷冻饮品应在冷冻条件下销售，陈列柜温度应≤-15℃。选A。' WHERE id = '1448520b-b575-4a5d-959a-1d9bc635c712';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 方便面》（GB 17400），方便面的色泽要求为具有产品应有的色泽。' WHERE id = '146ce611-2366-4c55-b9f9-7bad19049a93';
UPDATE public.questions SET analysis = '根据《关于办理危害食品安全刑事案件适用法律若干问题的解释》第一条，含有严重超标致病性微生物、病死畜禽肉类、国家明令禁止生产销售、婴幼儿食品营养成分严重不达标等情形，均应认定为''足以造成严重食物中毒事故''。四项全选。' WHERE id = '149691f7-52b2-4bad-a09f-596b828758ef';
UPDATE public.questions SET analysis = '根据《食品安全法》第五十条及《畜禽肉生产许可审查细则》，生产畜禽肉罐头使用的猪肉应有检验检疫合格证明和肉品品质检验合格证。选B、C。' WHERE id = '14a0af89-6527-4b8e-9d21-554bffc15bd5';
UPDATE public.questions SET analysis = '根据《餐饮服务食品安全操作规范》，应采取清洁消毒、加热灭菌、低温贮存、添加防腐剂等措施建立不利于微生物生存繁殖的环境。选D。' WHERE id = '14af2cec-9285-4cae-aaf1-86252a0643d2';
UPDATE public.questions SET analysis = '根据《食品安全法实施条例》第七十五条，对故意实施违法行为、性质恶劣、造成严重后果的情形，可对法定代表人、主要负责人等处以罚款。若食品安全总监、食品安全员已依法履职尽责则不适用。选A、B、D。' WHERE id = '14bb6cce-d0a6-4334-9968-0950fe9e2ac8';
UPDATE public.questions SET analysis = '根据《膨化食品生产许可证审查细则》，直接挤压型膨化食品的工艺流程包括配料、混料、挤压膨化、整形、烘焙、赋味、包装等。选B。' WHERE id = '14cba9a9-52a1-49be-b98d-ba79cdf0fc64';
UPDATE public.questions SET analysis = '根据GB 22570-2014，辅食营养补充品适用人群为6～60月龄儿童，不包括0～6月龄婴儿。选B、C、D。' WHERE id = '14d18bc1-648c-4d86-b920-d122a7328518';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第四十五条，从事接触直接入口食品工作的食品生产经营人员应当每年进行健康检查，取得健康证明后方可上岗。选A。' WHERE id = '14dc3131-b994-406f-a50e-e2fd62e54033';
UPDATE public.questions SET analysis = '根据GB 14881-2013第5.1.8条，清洁剂、消毒剂等应与原料成品分隔放置；原料等贮存物品不应贴墙放置，应与墙壁保持适当距离。因此C选项表述不正确。选C。' WHERE id = '14ef0c5e-ed0b-4e68-8d9a-98f92434f76d';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第五十条，进货查验记录保存期限不得少于产品保质期满后六个月，没有明确保质期的，保存期限不得少于二年。选C。' WHERE id = '14f23dc3-d5a1-4278-9a31-995a73fab0fe';
UPDATE public.questions SET analysis = '根据GB 14881-2013第6.3.2条，食品生产人员进入生产车间前应当洗手、穿戴清洁的工作衣、帽，这是强制性要求，企业无权自行决定。因此题目说法错误。' WHERE id = '1502a206-8ad3-4590-a382-801020e83dd2';
UPDATE public.questions SET analysis = '根据《餐饮服务食品安全操作规范》，烹饪后需要冷冻（藏）的易腐食品应及时冷却，可采取切小块、搅拌、冷水浴或使用速冷设备等措施。' WHERE id = '150a83bd-b0da-45b4-93b2-5d753e9160d9';
UPDATE public.questions SET analysis = '根据《食品安全法》第六十三条，食品经营者发现其经营的食品不符合食品安全标准的，应当立即停止经营并召回，而非实施补救措施恢复经营。因此题目说法错误。' WHERE id = '150df4c8-d405-4081-befd-fbdff37cbe71';
UPDATE public.questions SET analysis = '根据《婴幼儿配方乳粉产品配方注册管理办法》第二十五条，国家食品药品监督管理总局应自批准之日起20个工作日内公布注册目录信息。选C。' WHERE id = '15124c20-5971-4b58-b857-48e684c4f329';
UPDATE public.questions SET analysis = '根据GB 14881-2013第14.2条，食品生产企业应建立文件管理制度，确保各相关场所使用的文件均为有效版本。' WHERE id = '1523fa01-2242-452f-b580-061999f3ee1c';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第一百二十二条，食品经营许可证不得出租、出借，否则将面临处罚。因此题目说法错误。' WHERE id = '15259c26-4efe-49b2-8142-e8697eef6b1b';
UPDATE public.questions SET analysis = '根据食品安全相关知识，水产品原料中的胺类物质在适宜条件下与亚硝酸根反应可生成N-亚硝胺类化合物，具有致癌风险。选A。' WHERE id = '1529f0a1-9f42-4112-8914-9dfb9b46eda9';
UPDATE public.questions SET analysis = '根据《食品生产经营监督检查管理办法》第二十一条，食品生产经营者应开放场所、回答询问、提供合同票据账簿等材料、协助现场检查和抽样检验。四项全选。' WHERE id = '1531d5d7-cc4f-4b7a-ab5c-715d321ee59b';
UPDATE public.questions SET analysis = '根据《食用农产品市场销售质量安全监督管理办法》第二十六条，记录和凭证保存期限不得少于六个月。选B。' WHERE id = '153a5024-9338-42b5-a804-60003a4f540c';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品经营过程卫生规范》（GB 31621），冷库温度记录和显示设备应放置在冷库外便于查看的位置，而非冷库内。因此题目说法错误。' WHERE id = '154c2140-17cd-4bd6-9ccc-3c8b61eaef5b';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第四十六条，食品生产企业应就原料采购验收投料、生产工序设备贮存包装、原料检验半成品检验成品出厂检验、运输和交付等方面制定并实施控制要求。四项全选。' WHERE id = '15572813-2429-4837-b482-97524ad7d6e3';
UPDATE public.questions SET analysis = '根据GB 14881-2013及《预包装食品标签通则》，使用辐照原料应在产品标签中说明。选B。' WHERE id = '155efe8f-5edc-46b9-af93-abf4a7b66845';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第六条，食品安全总监、食品安全员发现有食品安全事故潜在风险的，有权提出停止相关食品生产经营活动等否决建议。因此题目说法错误。' WHERE id = '1563e030-2b99-4dba-bf2c-00fb550d6051';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第七十一条，保健食品之外的食品标签、说明书不得声称具有保健功能。' WHERE id = '156f7f4b-c9ed-4b35-bce0-bee351801b0a';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第四十六条，食品生产企业应当就原料采购验收投料、检验控制、生产关键环节控制、运输和交付控制等事项制定并实施控制要求。四项全选。' WHERE id = '1575f1ec-06a7-4470-b55c-8dbc2208c184';
UPDATE public.questions SET analysis = '根据《食品生产许可分类目录》，速冻调制食品生产许可包括速冻调制食品熟制品和速冻调制食品生制品。选A、D。' WHERE id = '157847d3-d485-467b-b859-4e5e7484e733';
UPDATE public.questions SET analysis = '根据《葡萄酒及果酒生产许可审查细则》，葡萄酒及果酒的基本生产流程包括破碎（压榨）、澄清处理、分离等，不包括糖化发酵（糖化是啤酒生产的工序）。选C。' WHERE id = '157a5a07-bcc2-4921-84a5-258813e25a0c';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第八十七条，市场监督管理部门进行抽样检验时购买样品并支付费用，不得向食品生产经营者收取检验费和其他费用。因此题目说法错误。' WHERE id = '157c6fee-5179-455c-99be-91881f227005';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 罐头食品生产卫生规范》，罐头食品生产加工用水的水质应符合《生活饮用水卫生标准》（GB 5749）。选B。' WHERE id = '15814cee-51b5-4ba4-811a-f77baa0312b3';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 鲜、冻动物性水产品》（GB 2733）及相关规定，使用带有病毒、致病菌、寄生虫及虫卵的水产原料，可能导致人体感染。' WHERE id = '15837004-dbfa-4722-a539-0ffe6d58adce';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第五十四条，保健食品经营者应当定期检查库存食品，及时清理变质或者超过保质期的食品。' WHERE id = '159c747a-f8c8-4c52-bc4b-f737e837aba5';
UPDATE public.questions SET analysis = '根据《餐饮服务食品安全操作规范》，中央厨房是指由食品经营企业建立，具有独立场所和设施设备，集中完成食品成品或半成品加工制作，配送给本单位连锁门店的经营主体。选A、B、C。' WHERE id = '15a90472-aa95-47f5-a0c5-d011f49ec98f';
UPDATE public.questions SET analysis = '根据《食品生产经营监督检查管理办法》第三条，食品生产经营监督检查是市场监管部门实施监督管理的重要手段，是加强食品安全事中事后监管工作的具体形式。' WHERE id = '15bacfb2-9b0c-46ad-8ef1-4dd86af8cf89';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品中污染物限量》（GB 2762-2022），熏、烧、烤肉类苯并[a]芘限量指标为5.0μg/kg。选A。' WHERE id = '15bb0818-c3e6-4b6a-ae82-88e6e7def1b7';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第七十五条，保健食品原料目录和允许保健食品声称的保健功能目录，由国务院食品安全监督管理部门会同国务院卫生行政部门、国家中医药管理部门制定、调整并公布。选A。' WHERE id = '15f9b97f-1c31-42f0-affe-7b19815ff7cc';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第三十五条，国家对食品生产经营实行许可制度。选B。' WHERE id = '1604bfeb-b95c-4413-b0e3-ecdcffd7d188';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第五十三条，食品经营企业应建立进货查验记录制度，如实记录食品名称、规格、数量、生产批号、保质期、供货者名称及联系方式、进货日期等。四项全选。' WHERE id = '1604dd4e-b17e-4ecc-9e13-387708966677';
UPDATE public.questions SET analysis = '根据《食品中可能违法添加的非食用物质名单》，吊白块（甲醛次硫酸氢钠）属于非食用物质，不得作为食品原料使用。选A。' WHERE id = '16252d2e-72d8-4679-9cc8-d6061139ac4d';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》第四十五条，患有痢疾、伤寒、甲型病毒性肝炎等消化道传染病的人员不得从事接触直接入口食品的工作，慢性胃炎不在此列。选D。' WHERE id = '164b028e-ae2d-43ab-9493-b1f227faeaa2';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 速冻面米与调制食品》（GB 19295），其中食品添加剂的使用应符合GB 2760《食品安全国家标准 食品添加剂使用标准》的规定。选A。' WHERE id = '1657e798-9a58-4a28-b712-8696cb233b59';
UPDATE public.questions SET analysis = '《中华人民共和国食品安全法实施条例》第八十一条明确了食品安全监管部门与公安机关的协作配合机制，规定了案件移送、信息共享及行政拘留与其他行政处罚的衔接程序，确保执法有效衔接。' WHERE id = '1658815f-a71f-4047-9c33-ad5fdc4128c2';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。《食盐质量安全监督管理办法》规定，禁止销售散装食盐，禁止销售掺假掺杂、混有异物、无标签或标签不符合规定的食盐，以及其他不符合食品安全标准的食盐。上述四类食盐均不得销售。' WHERE id = '165d0210-568a-4577-a749-b003a16051de';
UPDATE public.questions SET analysis = '答案C正确。GB 14880《食品安全国家标准 食品营养强化剂使用标准》规定食品营养强化剂的使用原则、允许强化的食品类别和使用量。GB 2760为食品添加剂标准，GB 29921为致病菌限量标准，GB 14881为生产卫生规范。' WHERE id = '165d0d15-a174-4534-a322-31f257716bfc';
UPDATE public.questions SET analysis = '答案A,B,C正确。《保健食品标注警示用语指南》要求经营保健食品应建立健全食品安全管理制度，划定专区或专柜销售并设立提示牌，在显要位置标注"保健食品不是药物"等消费提示。' WHERE id = '16610327-5389-4486-bbfb-eb411f397cd5';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品添加剂使用标准》(GB 2760)规定，食品添加剂包括天然食品添加剂和人工合成食品添加剂两大类，并非全部是人工合成的。' WHERE id = '16b205db-6362-42b3-86f1-d4010c87f9d2';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。《食品生产经营监督检查管理办法》规定，对食品销售环节日常监督检查主要事项包括食品销售者资质、从业人员健康管理、经营过程控制、进货查验结果等。' WHERE id = '16cbc1dc-112e-4d88-8076-265338f7f6b2';
UPDATE public.questions SET analysis = '答案D正确。GB/T 31114《冷冻饮品》规定冷冻饮品的感官要求包括色泽、滋味、气味和状态四个方面，综合评定产品的感官品质。选项D最全面完整。' WHERE id = '16d68971-b28e-4639-b6e0-a6a970d2b68b';
UPDATE public.questions SET analysis = '答案A正确。《食品安全法》第七十六条规定，保健食品声称功能应列入功能目录。使用原料目录外原料应注册而非备案；首次进口保健食品(补充维生素矿物质除外)应注册。' WHERE id = '1701211b-a577-42f5-9b36-5a500ee8b989';
UPDATE public.questions SET analysis = '答案B,C正确。蛋制品生产过程中，卫生条件不达标(B)、生产人员不洗手(C)均可能造成微生物污染。标签瑕疵(A)属于标识问题，金探仪不工作(D)可能导致物理性危害。' WHERE id = '170944c6-8d80-4519-9672-cf9d1aa2763b';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。《婴幼儿配方乳粉经营管理办法》要求，经营者应及时清理发现包装破损、腐败、变质、超过保质期的婴幼儿配方乳粉，立即停止经营、登记造册，并依法采取无害化处理或销毁等方式处置。' WHERE id = '170aca40-1b40-4a53-b2ac-44210438d4f5';
UPDATE public.questions SET analysis = '《食品安全国家标准 预包装食品标签通则》(GB 7718)及《食品标识管理规定》要求，食品名称应准确反映食品真实属性。面包产品取名"酸奶草莓"易使消费者误解其真实配料和属性。' WHERE id = '1731a20d-e86a-4c7c-9c87-b82caaa50a52';
UPDATE public.questions SET analysis = '答案D正确。《食品安全法》第三十五条规定，国家对食品生产经营实行许可制度。从事食品生产、食品销售和餐饮服务，应当依法取得许可。销售食用农产品和仅销售预包装食品的除外。' WHERE id = '17543223-8101-4941-a0a8-20107a5788ac';
UPDATE public.questions SET analysis = '答案C正确。《企业落实食品安全主体责任监督管理规定》明确，食品安全员从事食品安全管理具体工作，对食品安全总监或主要负责人负责。主要负责人承担全面责任，食品安全总监负责统筹协调。' WHERE id = '1759184c-c3cc-4fcd-852a-6b0a41e8b85c';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》(GB 14881)要求，不同清洁要求的同一设备不同部位应分开清洁，使用不同的清洁工器具，防止交叉污染，确保食品安全。' WHERE id = '176dde5c-ef65-4329-82ba-c6f3b7fea534';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。食醋生产原料处理通常包括除杂、清洗、压片、粉碎等工序，以去除杂质并使原料达到适合发酵的粒度状态，为后续糖化、酒精发酵、醋酸发酵创造条件。' WHERE id = '177ed1b1-e598-4433-97ee-646fafeb8ca5';
UPDATE public.questions SET analysis = '答案B正确。《食品安全法》第七十六条规定，保健食品声称的保健功能应当列入保健食品功能目录。使用原料目录以外原料的应注册而非备案；首次进口保健食品（补充维生素矿物质除外）应注册；保健食品注册由国务院市场监管部门负责。' WHERE id = '17909daf-cd1b-4c9a-b952-7a4ee5e83dc4';
UPDATE public.questions SET analysis = '答案A正确。除常见危害外，食品生产经营还存在因经济利益驱动导致的掺杂使假、以次充好、假冒伪劣及蓄意破坏等人为故意造成的食品安全风险。' WHERE id = '17a48713-d674-48fd-9a5e-12f77d41e3fb';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，患有有碍食品安全疾病的人员不得从事接触直接入口食品的工作，应调离岗位而非直接开除。' WHERE id = '17ae8905-f7a5-4961-951d-6d9b630f1d40';
UPDATE public.questions SET analysis = '答案C正确。《食品生产经营监督检查管理办法》规定，体系检查是以风险防控为导向，对特殊食品、高风险大宗食品生产企业和大型食品经营企业等的质量管理体系执行情况依法开展的系统性监督检查。' WHERE id = '17c0cbc9-319e-499f-a9f4-c21caee87600';
UPDATE public.questions SET analysis = '《食品安全法实施条例》鼓励食品生产经营者委托有资质的第三方专业机构对食品安全状况进行评价，借助专业力量提升食品安全管理水平，符合社会共治原则。' WHERE id = '17cc91b3-50ff-4950-af1b-09c0124763d4';
UPDATE public.questions SET analysis = '答案A正确。方便面包装材料中的塑化剂(如邻苯二甲酸酯类)可能向食品迁移，GB 9685对塑化剂有严格限量。' WHERE id = '17d63971-f765-4371-9dcf-145f7e3a7325';
UPDATE public.questions SET analysis = '答案C正确。《企业落实食品安全主体责任监督管理规定》明确，食品安全员从事食品安全管理具体工作，对食品安全总监或主要负责人负责。企业主要负责人承担全面领导责任，食品安全总监负责统筹协调。' WHERE id = '17d66766-6710-4ddf-b597-281ac38390d8';
UPDATE public.questions SET analysis = '答案C正确。GB 2715《食品安全国家标准 粮食》规定木薯粉总氢氰酸含量应≤10mg/kg。氢氰酸是木薯中的天然毒素，限量控制对保障食品安全至关重要。' WHERE id = '17d70f06-7f4d-40e2-812d-8792ca80a19b';
UPDATE public.questions SET analysis = '答案A,B,C正确。酒类产品化学性危害主要包括生物毒素(如黄曲霉毒素)、农药残留(原料带入)、塑化剂(生产接触材料迁移)等，原料(D)本身不属于化学性危害类别。' WHERE id = '17f6499f-72ab-4786-8d7c-04fb1d1558e3';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。《食品安全法》第五十三条规定，进货查验记录应如实记录食品的名称、规格、数量、生产日期或批号、保质期、进货日期等内容。' WHERE id = '180c3cc0-8b4a-4faf-b46c-efe3d54f862a';
UPDATE public.questions SET analysis = '答案B正确。《餐饮服务食品安全操作规范》要求，从业人员认真揉搓双手至少20秒，确保清洗双手所有皮肤，包括指背、指尖和指缝。' WHERE id = '180ea48b-9a2f-4e0a-9550-cc0533dfcbe4';
UPDATE public.questions SET analysis = '《中华人民共和国反食品浪费法》规定，餐饮服务经营者应在引导消费者按需适量点餐，提升餐饮供给质量，提供小份餐等不同规格选择，减少食品浪费。' WHERE id = '1813475f-4481-4425-92e2-de4aeba84676';
UPDATE public.questions SET analysis = '答案A正确。GB 10769《食品安全国家标准 婴幼儿谷类辅助食品》明确规定不应使用经辐照处理过的原料。辐照可能影响食品的营养成分，对婴幼儿健康存在潜在风险。' WHERE id = '1824544a-854b-4d58-8987-a006c1b2238b';
UPDATE public.questions SET analysis = '答案C正确。GB 2763《食品安全国家标准 食品中农药最大残留限量》规定大豆农药残留的测定部位为整粒，该标准对不同农产品的测定部位有明确规定。' WHERE id = '1824b8f4-227f-4acc-8512-356982a762e3';
UPDATE public.questions SET analysis = '答案A,B,C正确。散装食品售货工具应定时清洁消毒，消毒后的工具应放入防尘、防蝇、防污染的专用密闭保洁设施内，不得直接放置在散装食品容器内。' WHERE id = '1843c7e1-ba10-409a-a345-bbf40b563bc7';
UPDATE public.questions SET analysis = '《食品安全法》第四条规定，食品生产经营者对其生产经营食品的安全负责，应依照法律法规和食品安全标准从事生产经营活动。' WHERE id = '184ce452-eab8-4a13-99b5-9c86774a0e79';
UPDATE public.questions SET analysis = '答案C正确。《食品安全法》第三十三条规定，食品生产经营场所应保持环境整洁，个人生活用品不得与食品混放。有毒有害物品不得与食品同库房贮存；未经清洗的鸡蛋和食品添加剂可以按规定存放。' WHERE id = '184e0c8a-3c74-4ad1-a43c-b0b3d9a9e2bb';
UPDATE public.questions SET analysis = '《学校食品安全与营养健康管理规定》鼓励学校配备营养专业人员，但并未作强制性统一要求。学校可根据实际情况配备专(兼)职营养健康管理人员。' WHERE id = '1866f458-fb94-4538-ad7b-5265fb94e73b';
UPDATE public.questions SET analysis = '《食品安全国家标准 餐饮服务通用卫生规范》(GB 31654)规定，除中央厨房和集体用餐配送单位外，餐饮服务提供者冷却直接入口易腐食品和分装、分切等操作，应在专间或专用操作区进行。' WHERE id = '186f8d0b-cfe8-4f26-a582-bf8c282f94c8';
UPDATE public.questions SET analysis = '答案B,D正确。六六六、三氯杀螨醇属于国家明令禁止在茶叶上使用的农药，具有高残留、高毒性特征。GB 2763《食品安全国家标准 食品中农药最大残留限量》对茶叶农药残留有严格规定。' WHERE id = '187175cb-c7fe-4745-a486-5f671f844e8a';
UPDATE public.questions SET analysis = '答案C正确。《食品安全法》第四十七条规定，食品生产企业有发生食品安全事故潜在风险的，应立即停止食品生产活动，并向所在地食品安全监督管理部门报告。' WHERE id = '188d7e2e-c955-41e4-a8b8-d54d5c7d8e25';
UPDATE public.questions SET analysis = '《食品安全法》第四十四条规定，食品生产经营企业应当建立健全食品安全管理制度，对职工进行食品安全知识培训。各岗位从业人员应根据企业培训制度参加食品安全知识培训。' WHERE id = '18ac4d7d-ac0b-4d44-96c0-7e18d9e084ef';
UPDATE public.questions SET analysis = '答案B,C正确。《产品质量法》第四十九条规定，生产、销售不符合保障人体健康和人身、财产安全的国家标准、行业标准的产品的，应责令停止生产销售。' WHERE id = '18b8b4d7-bfbd-437a-88f2-27a12357037a';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。GB 14881要求食品生产企业墙面应使用无毒、无味的防渗透材料建造，不易积累污垢、易于清洁，涂料应不易脱落，防止对食品造成污染。' WHERE id = '18ccf4a1-96c5-4213-8758-1baa92474380';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条第四款规定，食品生产经营者采取召回措施的，应当承担消费者因食品被召回支出的必要费用，保障消费者合法权益不受损害。' WHERE id = '18df56d7-7487-49ab-b662-304ccf59249e';
UPDATE public.questions SET analysis = 'GB 19302规定风味发酵乳是以80%以上生牛(羊)乳或乳粉为原料，添加其他原料经杀菌、接种发酵制成的产品，不是70%以上。' WHERE id = '18e38a86-978a-4208-a991-6933b3195433';
UPDATE public.questions SET analysis = '《食品召回管理办法》规定，食品经营者知悉食品生产者召回不安全食品后，应立即采取停止购进、销售，封存不安全食品，在经营场所醒目位置张贴召回公告等措施，配合食品生产者开展召回工作。' WHERE id = '18e3a91e-bd49-447c-87e6-ea16f6b77dd3';
UPDATE public.questions SET analysis = '答案A,B,C正确。《企业落实食品安全主体责任监督管理规定》要求建立日管控、周排查、月调度工作机制，排查消除风险隐患。' WHERE id = '191e7eed-eeca-4731-a6ca-8d747ccc9820';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品添加剂使用标准》(GB 2760)规定，食品添加剂使用原则之一是在达到预期效果前提下尽可能降低在食品中的使用量，而非增加，以保障消费者健康。' WHERE id = '1925f7e5-7a2d-4e4d-9216-1ddfb3f8e3bc';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》实行一企一证原则，同一食品生产者只需申请一个食品生产许可证，不同食品类别在许可证上载明即可。' WHERE id = '194a1bfd-03aa-406a-b600-c283465bde7a';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，设备上使用润滑油应防止滴落或泄漏污染食品，应使用食品级润滑油，严禁使用工业油脂润滑直接接触食品的设备部件。' WHERE id = '194b0fce-6515-46b9-adfb-ee1900697ec9';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品添加剂使用标准》(GB 2760)允许硫酸铝钾、硫酸铝铵在淀粉制品中按生产需要适量使用。企业应规范管理、准确计量、混合均匀，确保铝残留量符合标准要求。' WHERE id = '194ba008-8b6d-4ee5-a042-18fb27473f02';
UPDATE public.questions SET analysis = '答案B正确。保健食品注册号格式为国食健字G+4位年代号+4位顺序号(国产)或J+4位年代号+4位顺序号(进口)。G表示国产，J表示进口。' WHERE id = '197c6c84-04b5-471c-ad47-a2b39863a36f';
UPDATE public.questions SET analysis = '答案A,B正确。GB 14881要求从业人员穿戴清洁工作衣帽、头发不外露。不得留长指甲涂指甲油，饰物不得外露。' WHERE id = '19844de4-54f2-4eb3-80a4-28beed1ccfb7';
UPDATE public.questions SET analysis = '答案B,C,D正确。《食品安全法实施条例》规定，风险监测发现隐患的，食品生产经营者自查确认后应停止生产经营、实施召回并向监管部门报告，不得继续销售。' WHERE id = '1985dea3-0b9b-45d5-81b3-5232ac1a6841';
UPDATE public.questions SET analysis = '答案B正确。GB 10770规定婴幼儿罐装辅助食品可使用冷冻原料(确保安全条件下)，不应使用辐照原料、氢化油脂和香辛料。' WHERE id = '1994999f-9b30-4590-8cb1-9cdfbddfa0ad';
UPDATE public.questions SET analysis = '答案A正确。GB 2762《食品安全国家标准 食品中污染物限量》规定豆类中镉含量不超过0.2mg/kg。镉是重金属污染物，长期摄入对人体有害，国标对此有严格限量要求。' WHERE id = '19991d13-e011-4ce6-8c0b-b5d3623a1c3e';
UPDATE public.questions SET analysis = '答案A,B正确。《农产品质量安全法》规定，农产品生产企业和农民专业合作社应根据质量安全控制要求自行或委托检测机构对农产品质量安全进行检测。' WHERE id = '199e2a8e-bfe6-4dc5-be14-2ac891f8bb9d';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。《食品安全法》要求食品生产企业如实记录加工过程、产品贮存、原料进货查验、产品检验等内容，建立完善的记录管理制度，确保食品安全可追溯。' WHERE id = '199e7dea-24bf-4986-9d0a-584f1cd0ad68';
UPDATE public.questions SET analysis = '《食品安全法》第二十五条明确规定，食品安全标准是强制执行的标准。除食品安全标准外，不得制定其他食品强制性标准。企业必须严格执行食品安全标准，不得自愿选择是否采纳。' WHERE id = '19a2d8e6-5fbd-4672-a5c0-bfa7cbfac4c4';
UPDATE public.questions SET analysis = '答案B正确。《保健食品注册与备案管理办法》规定，不得使用同一名称注册或备案不同配方的保健食品，防止消费者混淆。' WHERE id = '19a6c71f-fd6e-40d4-b1df-68539ec340c4';
UPDATE public.questions SET analysis = '答案B,C,D正确。志贺氏菌、金黄色葡萄球菌、大肠埃希氏菌是水产品非自身原有细菌，主要来源于环境污染、加工污染等外源性途径。单核细胞增生李斯特菌可在水产品中天然存在。' WHERE id = '19aa5bba-f6c4-40aa-94b1-e89f525329e0';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，使用的洗涤剂、消毒剂应当对人体安全、无害。采用物理、化学或生物制剂进行虫害消杀处理时，不应当影响食品安全，不应当污染食品接触表面、设备、工具及包装材料。' WHERE id = '19bafee5-91d8-4555-9e41-2cb30cef070b';
UPDATE public.questions SET analysis = '答案C正确。《食品生产经营风险分级管理办法》将风险等级分为A、B、C、D四级，对特殊食品及C、D级企业实施重点监督检查。' WHERE id = '19c74896-16dc-44b7-ab7e-9a67f11147e3';
UPDATE public.questions SET analysis = '答案A,C,D正确。《食品安全法》第六十三条规定，食品经营者发现经营的食品不符合标准的，应停止销售、通知相关方、记录停止经营和通知情况。' WHERE id = '1a21a598-7570-40b3-a08a-2eb2b9a1153c';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品添加剂使用标准》(GB 2760)规定，食品添加剂包括天然食品添加剂和人工合成食品添加剂两大类，并非全部是人工合成的。' WHERE id = '1a343516-81fb-433a-9392-35d88a1b51cd';
UPDATE public.questions SET analysis = '答案B正确。《食品安全法》第五十条规定，食品、食品添加剂进货查验记录应当真实，保存期限不得少于产品保质期满后六个月；没有明确保质期的，保存期限不得少于二年。' WHERE id = '1a36c394-7e39-47ca-9727-1da80b91fd34';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。可可粉、可可脂、可可液块、可可饼块的生产均需经过壳仁分离工艺去除外壳获取可可仁。' WHERE id = '1a3b5c1e-c97b-4d92-879e-bdd3ed5469dc';
