UPDATE public.questions SET analysis = '答案A,B,C,D正确。《反食品浪费法》规定，餐饮服务经营者应建立健全采购储存管理制度、主动提示提醒、提升供给质量、合理配置菜品等措施防止食品浪费。' WHERE id = '1a41e6bf-cdd1-4b9b-b0e3-c37468ef642a';
UPDATE public.questions SET analysis = '《食品安全法》第五条规定，国务院设立食品安全委员会，其职责由国务院规定。食品安全委员会负责统筹协调全国食品安全工作，而非由全国人大规定。' WHERE id = '1a421761-0898-48e0-921d-ca48e79578d0';
UPDATE public.questions SET analysis = '答案D正确。GB 7718《食品安全国家标准 预包装食品标签通则》规定了预包装食品标签的基本要求、标示内容等，是食品标签管理的基础标准。' WHERE id = '1a4c1f49-f2cd-44fa-8102-e6812f0a6ab8';
UPDATE public.questions SET analysis = '答案B正确。《食品安全国家标准 食品经营过程卫生规范》(GB 31621)规定，冷藏冷冻食品应分类、分架存放，与墙壁、地面保持10cm以上距离，利于空气流通和温度均匀。' WHERE id = '1a58cfdd-7c02-49f6-9d74-cc1bfa1246b0';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品中污染物限量》(GB 2762)对铅含量有限量要求。生产设备或包装材料中的铅可能迁移到食品中导致超标，企业应选用符合食品级要求的设备和材料。' WHERE id = '1a638daf-504c-4312-9d8f-6eeff4de45eb';
UPDATE public.questions SET analysis = '答案A,B,C正确。《企业落实食品安全主体责任监督管理规定》要求，大中型餐饮服务企业、用餐人数300人以上的托幼机构食堂、用餐人数500人以上的学校食堂、供餐人数超过1000人的单位应配备食品安全总监。' WHERE id = '1a6ca29f-047b-4772-b652-32006c5d9e2b';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，食品经营者应当将张贴的日常监督检查结果记录表保持至下次日常监督检查，以便消费者了解企业食品安全状况，保障公众知情权。' WHERE id = '1a8f5829-fb8f-4d03-84c7-4ea356925ee0';
UPDATE public.questions SET analysis = '答案A正确。《食品生产经营监督检查管理办法》规定，日常监督检查(含"双随机"抽查检查)是市、县级市场监管部门按照年度监督检查计划，对本行政区域内食品生产经营者开展的常规性检查。' WHERE id = '1a9a65ca-e5cd-4c66-836a-162c09d43d58';
UPDATE public.questions SET analysis = '答案C正确。《食品安全法》第十七条规定，国务院卫生行政部门组织开展食品安全风险监测和风险评估，会同国务院食品安全监督管理部门制定并公布食品安全国家标准。' WHERE id = '1a9c6b10-1a5c-4453-b0e8-40840679f2ad';
UPDATE public.questions SET analysis = '答案D正确。GB 2762《食品安全国家标准 食品中污染物限量》规定发酵型豆制品中黄曲霉毒素B1限量为5.0μg/kg。黄曲霉毒素B1是强致癌物，主要来源于霉变原料。' WHERE id = '1aa19832-6681-46ee-ab28-9688e0715691';
UPDATE public.questions SET analysis = '答案B正确。《食品安全国家标准 食品冷链物流卫生规范》(GB 31605)规定，冷藏冷冻食品装卸期间食品温度升高幅度不超过3℃，严格控制温度波动保障食品安全。' WHERE id = '1aa219a6-d356-4484-bd3b-e6858c972b36';
UPDATE public.questions SET analysis = '答案C正确。《食盐专营办法》规定，国家实行食盐定点批发制度。非食盐定点批发企业不得经营食盐批发业务，保障食盐质量安全和市场供应稳定。' WHERE id = '1ab5a985-c0f2-4b85-a6b2-590d89d616db';
UPDATE public.questions SET analysis = '《食品安全法》及《生猪屠宰管理条例》规定，畜、禽产品应具有动物检疫合格证明，猪肉还应具有肉品品质检验合格证。进口畜、禽产品应有入境货物检验检疫证明。' WHERE id = '1ac5d32a-bb51-4a8e-a603-66b17936afcc';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。《企业落实食品安全主体责任监督管理规定》要求企业配备食品安全管理人员、健全食品安全责任体系、建立风险防控制度、明确法律责任。照搬其他企业制度不符合实际管理要求。' WHERE id = '1acc32d9-e859-4617-9974-3c4c5d2a59d1';
UPDATE public.questions SET analysis = '答案D正确。粮食加工品是指以谷物为原料加工制作未经熟制或不完全熟制的食品，如大米、小麦粉、杂粮等。GB 2715《食品安全国家标准 粮食》对此有明确规定。' WHERE id = '1acc9b29-ffa6-4894-839f-346af4af24f9';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。设置筛网、捕集器、磁铁、金属检查器等装置可有效降低金属或其他异物污染食品的风险。' WHERE id = '1ad25e67-c15f-4086-95f7-089a039f29ad';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》(GB 14881)要求，生产设备上直接接触食品的活动部件应避免使用水银温度计，防止破损后造成玻璃异物及汞化学污染，应采用安全的温度监测方式。' WHERE id = '1ae63013-74da-40d3-9c74-e04fb9de4aaa';
UPDATE public.questions SET analysis = '答案B,C,D正确。对鲜蛋应定期检测农兽药残留、重金属和非食用物质等指标，防止污染物通过饲料、环境等途径进入蛋品中，确保鲜蛋质量安全和消费者健康。' WHERE id = '1b0270ec-3d47-45dd-989c-ac401702a40c';
UPDATE public.questions SET analysis = '《网络食品安全违法行为查处办法》规定，通过网络从事食品经营活动的，应当按照法律法规规定落实各项食品安全主体责任，包括进货查验、食品贮存、运输等要求，保障食品安全。' WHERE id = '1b241213-ff2d-40d0-a659-0b9d26fb9651';
UPDATE public.questions SET analysis = '答案C正确。GB 14881《食品安全国家标准 食品生产通用卫生规范》要求，保持食品包装、贮存容器的密闭性良好，防止在加工、贮存、销售等环节的虫害侵入和污染。' WHERE id = '1b382ad6-b0a1-49ab-b09c-dc111114bdce';
UPDATE public.questions SET analysis = '答案A,B,C正确。利用自动售货设备从事食品销售的，应提交设备产品合格证明、具体放置地点、经营者信息、食品经营许可证公示方法等。设备说明书不是法定提交材料。' WHERE id = '1b4a0211-1142-4a9e-bdf4-581f7e90b6da';
UPDATE public.questions SET analysis = '答案A,B,D正确。《食品安全法》第七十三条规定，食品广告不得含有虚假内容，不得涉及疾病预防、治疗功能。生产许可证编号是标签应标示内容。' WHERE id = '1b64f0d3-a041-4acf-a118-d9ccb9f8f3fa';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》(GB 14881)规定，食品加工过程的微生物监控应包括致病菌监控和指示菌监控，通过系统监控及时发现控制微生物污染风险。' WHERE id = '1b70d9f7-d6e0-43f6-a5b6-41c53fba891d';
UPDATE public.questions SET analysis = '《食品安全法》第二十五条明确规定，食品安全标准是强制执行的标准。除食品安全标准外，不得制定其他食品强制性标准。企业必须严格执行食品安全标准，不得自愿选择是否采纳。' WHERE id = '1b713046-5a46-461a-8175-594ac4c524af';
UPDATE public.questions SET analysis = '答案A,B正确。《食品生产许可分类目录》中，实施食品生产许可的水果制品分为蜜饯和水果制品两大类，果酱、果糕属于蜜饯的子类别。' WHERE id = '1b73b8c1-d87e-425d-b084-7c4f8c5ca83a';
UPDATE public.questions SET analysis = '答案A,B,C正确。GB 2714规定酱腌菜大肠菌群限量(n=5,c=2,m=10,M=1000CFU/g)，致病菌限量应符合GB 29921中即食果蔬制品规定，大肠菌群限量不适用于非灭菌发酵型产品。' WHERE id = '1b73c3cc-3f2f-441f-851f-cc22b2e12c05';
UPDATE public.questions SET analysis = '答案A正确。GB 2757《食品安全国家标准 蒸馏酒及其配制酒》规定白酒中甲醇限量为≤0.6g/L(以100%vol酒精度计)。甲醇是酿酒过程中产生的有害物质，过量摄入可导致中毒。' WHERE id = '1b772050-d72c-411e-a376-2ac2e65d4825';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。根据《关于办理危害食品安全刑事案件适用法律若干问题的解释》，致人死亡或重度残疾、三人以上重伤、十人以上轻伤、三十人以上严重食物中毒等情形均应认定为"后果特别严重"。' WHERE id = '1b85a638-5e76-4b45-ba92-ef23c5e88183';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。食用油风险包括原料风险(黄曲霉毒素等)、生产加工过程风险(苯并芘等)、故意违法风险(地沟油、掺假)及油料存储不当产生真菌毒素的风险。' WHERE id = '1ba1a565-1288-485c-a743-9a683d45de9b';
UPDATE public.questions SET analysis = '答案B正确。GB 10769《食品安全国家标准 婴幼儿谷类辅助食品》规定，婴幼儿谷类辅助食品中谷物应占干物质组成的25%以上，确保产品营养属性和食品类别特征。' WHERE id = '1bcb22a2-0050-484c-ab6b-31b94a0c3461';
UPDATE public.questions SET analysis = '答案A正确。蜂产品存在超范围使用食品添加剂风险，主要是香精和着色剂，不法商贩添加这些物质改善外观和风味，以假充真。' WHERE id = '1bdb7acb-653c-4490-83df-b55a551845aa';
UPDATE public.questions SET analysis = '《食品安全法》及《食品生产经营监督检查管理办法》规定，食品生产经营者针对不合格食品产生的原因，应制定整改措施并限期完成整改，向市场监管部门提交整改报告。' WHERE id = '1bdf0532-bd89-4569-bfcc-d831cb783e88';
UPDATE public.questions SET analysis = '答案D正确。《食品安全法》第三十三条规定，申请许可应具备相适应的场所、设备、工艺流程、卫生条件及法律法规规定的其他条件。' WHERE id = '1be95336-1ba0-456b-838b-9011276e3ab6';
UPDATE public.questions SET analysis = '答案C正确。蛋制品生产安全要求，暂存蛋液必须在24小时内进行下一步处理，防止蛋液因长时间存放导致微生物繁殖和品质劣变，确保蛋制品食品安全。' WHERE id = '1bfb6ad9-79f9-447d-a1a9-d23ae8802800';
UPDATE public.questions SET analysis = '答案A,B正确。《食品安全抽样检验管理办法》规定，复检机构确定后，复检申请人与初检机构协商确定递送方式，确保复检样品的真实性和完整性。' WHERE id = '1c01292f-cb25-454b-8faa-507f2404e9f2';
UPDATE public.questions SET analysis = '《食品安全法》第四十条规定，食品添加剂应当在技术上确有必要且经过风险评估证明安全可靠，方可列入允许使用的范围。食品生产企业应当按照食品安全国家标准使用食品添加剂。' WHERE id = '1c053c19-833e-451b-be8b-cbde6fe1d64c';
UPDATE public.questions SET analysis = '咖啡粉生产工艺通常包括清理、调配、焙炒、冷却、磨粉、包装等工序，该表述符合咖啡粉的实际生产工艺流程。' WHERE id = '1c15c832-88df-4bb1-ab8a-f86d3bf5dde6';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第七十六条规定，食品生产经营者主动采取停止生产经营、召回和处置不安全食品措施，消除或减轻危害后果的，依法从轻或减轻处罚；违法情节轻微并及时纠正，没有造成危害后果的，不予行政处罚。' WHERE id = '1c254c00-cb11-407e-9530-a156bd1b21f9';
UPDATE public.questions SET analysis = '答案C正确。《食品安全法》第五条规定，国务院设立食品安全委员会，其职责由国务院规定，统筹协调全国食品安全工作。' WHERE id = '1c3c48f3-7d99-4189-aca7-575c09c9e3a3';
UPDATE public.questions SET analysis = '答案B正确。罐头食品加工中，加工用水、冷却用水不符合要求，或预煮、杀菌的温度和时间不够，都容易造成杀菌不彻底，导致微生物污染和产品腐败变质。' WHERE id = '1c4cb827-4bbc-457f-a989-f50b43941293';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。《食品安全法》第五十三条规定从事食品批发业务的企业应建立食品销售记录制度，记录食品名称、规格、数量、批号、保质期等内容。' WHERE id = '1c51fe2a-c570-4ef8-97d3-e7f6d9ac6263';
UPDATE public.questions SET analysis = '答案A正确。GB/T 20705规定出厂检验项目包括可可脂、细度、灰分等，折光指数不是出厂检验项目。' WHERE id = '1c6ea531-de6c-4dd7-a86b-6afc37ab822a';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，食品生产经营企业应配合监督检查工作，为检查人员提供必要的工作条件而非生活条件，配合检查是企业的法定义务。' WHERE id = '1c82174e-d746-4d96-b50e-4357d23d7c1d';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》(GB 14881)规定，厂区不应选择对食品有显著污染的区域，如某地对食品安全存在明显不利影响且无法通过措施改善的，应避免在该地址建厂。' WHERE id = '1c82d1f5-fa0a-47a6-863a-a5cc4260f96a';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。按照食品安全法律法规、规章、标准和规范性文件建立管理制度，是落实企业食品安全主体责任的基本要求。' WHERE id = '1c87e863-42fc-4a4f-b785-c261b9e9581c';
UPDATE public.questions SET analysis = '答案A,C,D正确。GB 2760规定不应以掺杂、掺假、伪造为目的使用食品添加剂，不得掩盖食品质量缺陷。' WHERE id = '1cafc41a-5364-4875-8e3d-852dd40d9608';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。GB 31654规定食品处理区地面铺设材料应无毒、无异味、不透水、耐腐蚀，结构应有利于排污和清洗，防止积水和污垢积累。' WHERE id = '1cb71d72-a12a-4bb8-969e-adf61ed40061';
UPDATE public.questions SET analysis = '《食品安全法》第九十七条规定，进口的预包装食品、食品添加剂应当有中文标签。进口预包装食品标签必须包含中文标注，符合中国法律法规和食品安全国家标准要求。' WHERE id = '1cb84dc7-4c40-4a97-8e8e-92b8294cc841';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，从事食品批发业务的经营企业应当建立食品销售记录制度，食品零售经营者不需建立食品销售记录，但应做好进货查验。' WHERE id = '1ccb29ff-e668-404b-b1f1-624676180ff4';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。食品安全管理员对从业人员健康管理职责包括建立健康档案、督促健康检查、对患有有碍食品安全疾病的人员提出岗位调整意见并督促落实、加强人员健康状况检查等。' WHERE id = '1cf55f26-d0b2-4926-a003-481e9ac6e8e2';
UPDATE public.questions SET analysis = '《食品安全法》及《食品召回管理办法》要求，食品生产经营者对召回的食品采取无害化处理、销毁等措施的，应当提前向所在地县级人民政府食品安全监督管理部门报告时间、地点。' WHERE id = '1cf628c8-80e5-4cf6-9b6f-4d527f015066';
UPDATE public.questions SET analysis = '《食品安全法》及《食品经营过程卫生规范》(GB 31621)规定，不得未采取任何防护措施销售直接入口的散装食品，直接接触食品的从业人员应持有有效健康证明。' WHERE id = '1cfc2a4e-694b-4c62-92b1-6ab60b00b6fd';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，食品生产经营企业应配合监督检查工作，为检查人员提供必要的工作条件而非生活条件，配合检查是企业的法定义务。' WHERE id = '1d02e64a-da00-49ec-b70c-05c89aea4dab';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。膨化食品微生物超标可能由环境卫生条件控制不严格、生产人员个人卫生不达标、工艺控制不严格、包装设施消毒不彻底等因素造成，应全面加强防控。' WHERE id = '1d1e0e2a-0604-4116-b135-276da0cbd4a6';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。《食品召回管理办法》规定，对召回食品应无害化处理或销毁；标签瑕疵可补救的继续销售；需销毁的提前报告时间地点；处置情况应记录保存。' WHERE id = '1d3f109a-2d25-46f9-a02e-a6833fbec816';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第二十四条规定，食品经营者应严格按照食品标签标示或相关规定要求贮存、运输食品，对有温度要求的食品必须在相应温度条件下贮存和运输，不得视情况决定。' WHERE id = '1d682550-897e-4bcb-8c57-d51ea78a4539';
UPDATE public.questions SET analysis = '答案A,B,C正确。食品安全管理制度应与工艺技术水平、食品种类特性、生产规模相适应，照搬其他企业制度不符合实际。' WHERE id = '1d693800-a7e4-41cf-83f0-0e5e39fbc220';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条及GB 14881要求，食品生产企业应配备与生产能力相适应的生产设备，按工艺流程有序排列，避免引起交叉污染。' WHERE id = '1d845b98-c356-4005-96ed-0ea0d9828631';
UPDATE public.questions SET analysis = '答案A,B正确。《标准化法》第二十七条规定，企业应当公开其执行的强制性标准、推荐性标准、团体标准或者企业标准的编号和名称，保障消费者的知情权。' WHERE id = '1da30cd0-95db-4a8a-bfc1-5e729c33d2ef';
UPDATE public.questions SET analysis = '答案A,B,D正确。《食用农产品市场销售质量安全监督管理办法》规定，市场开办者应查验并留存入场销售者的社会信用代码证或身份证复印件、产地证明或购货凭证、合格证明文件等。银行账户及担保证明不是法定查验文件。' WHERE id = '1db53aa3-8e9b-4772-9697-653022e72a7c';
UPDATE public.questions SET analysis = '《食品安全法》第八十九条规定，食品生产企业可以自行对生产的食品进行检验，也可以委托符合规定的食品检验机构进行检验。具备检验能力的企业可自行检验。' WHERE id = '1db59dfc-1925-49c3-a091-672750f94378';
UPDATE public.questions SET analysis = '答案A正确。化学性危害的防控有时比生物性危害更困难，特别是来自动植物原料及其种养殖环境、加工过程的危害，如农药残留、兽药残留、重金属和天然毒素等。' WHERE id = '1dbe4338-46d7-4f7e-8a25-0aacdd529ece';
UPDATE public.questions SET analysis = '答案A正确。使用保健食品原料目录以外原料的保健食品应经注册而非备案；首次进口保健食品(补充维生素、矿物质等营养物质除外)应经注册。保健食品声称功能应列入保健食品功能目录。' WHERE id = '1dc0bda9-b034-4b00-8190-fee69545586e';
UPDATE public.questions SET analysis = '《网络食品安全违法行为查处办法》规定，无实体门店经营的互联网食品销售者也应当具有与经营的食品品种、数量相适应的固定的食品经营场所，贮存场所视同经营场所。' WHERE id = '1dd068ae-77d8-439b-ab3a-535d795c9b8a';
UPDATE public.questions SET analysis = '答案A正确。2016年7月1日以后，保健食品注册号格式调整为"国食健注G/J+4位年代号+4位顺序号"，以适应新的注册管理要求。' WHERE id = '1dd54cca-59d4-44a7-a362-5e782312aab3';
UPDATE public.questions SET analysis = '《学校食品安全与营养健康管理规定》要求，学校食堂变更经营形式的，应在变化后五个工作日内向原发证的市场监督管理部门报告。' WHERE id = '1de98a8d-2505-466d-82a8-4faac337976d';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。速冻食品生产关键环节防控措施包括原辅料管理、冻结等生产过程控制、食品添加剂使用、冷却包装等环节控制，确保全程冷链和食品安全。' WHERE id = '1e0589eb-2752-4a86-aeb7-3cf630508d49';
UPDATE public.questions SET analysis = '答案C正确。酱油类生产企业一般应有原辅料预处理设备、种曲、制曲设备、发酵酿造设施、淋油或压榨设备等。制曲是酱油酿造的核心工序，直接影响产品质量。' WHERE id = '1e12494e-6cf5-407b-9d86-9911773f9c33';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，从事接触直接入口食品工作的食品生产经营人员应每年进行健康检查，取得健康证明后方可上岗，而非每两年。' WHERE id = '1e1974b5-5a2c-4fe5-b6c4-55f28adffd45';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》(GB 14881)规定，对食品添加剂以及清洁剂、消毒剂、润滑剂等明确标示、分类管理、妥善保存，可有效防范加工过程中的化学性危害。' WHERE id = '1e3ad2a1-b765-4dda-8cd7-7248a86dfa4d';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。餐饮服务提供者禁止采购亚硝酸盐、未经加工的河鲀整鱼、野生河鲀、长江流域非法捕捞渔获物等。' WHERE id = '1e661aef-f027-4465-b49e-d7fe1470846a';
UPDATE public.questions SET analysis = '答案D正确。《企业落实食品安全主体责任监督管理规定》明确，食品安全员从事食品安全管理具体工作，对食品安全总监或主要负责人负责。企业主要负责人承担全面领导责任，食品安全总监负责统筹协调。' WHERE id = '1e72392d-006b-4f47-a253-63cf92a67979';
UPDATE public.questions SET analysis = '答案C正确。《食品安全法》第九十七条规定，进口预包装食品应标示原产地、境内代理商名称地址及中文标签，可不标示境外生产企业具体名称地址。' WHERE id = '1e738ce2-de88-46dc-80cd-aae84c0f2fb4';
UPDATE public.questions SET analysis = '答案B,C正确。茶叶产品主要食品安全风险包括农药残留超标和污染物(如铅、稀土)超标。致病菌不是茶叶产品的主要风险点，超出保质期属于经营环节管理问题。' WHERE id = '1e7b5a30-1e71-4434-b6f5-7a47d56af59e';
UPDATE public.questions SET analysis = '答案B正确。《婴幼儿配方乳粉产品配方注册管理办法》规定，特殊情况下需延长审评时间的，经审评机构负责人同意，可以延长30个工作日，并书面告知申请人。' WHERE id = '1e902973-e0f5-4484-a3e1-03c78931c18e';
UPDATE public.questions SET analysis = '答案C正确。GB 17399《食品安全国家标准 糖果》规定微生物指标包括菌落总数、大肠菌群等。菌落总数是糖果产品的重要卫生指标，反映产品的卫生状况。' WHERE id = '1ea85275-ffb9-4c69-bee2-fa27915c69a6';
UPDATE public.questions SET analysis = '答案B正确。《食品生产许可管理办法》规定，需要变更许可事项的，食品生产者应在变化后10个工作日内向原发证部门提出变更申请。' WHERE id = '1eae83ee-ccdc-47e8-bbc6-7fb7fc50cce7';
UPDATE public.questions SET analysis = '答案D正确。鼓励散装熟食制品标明保存条件和温度，保质期不超过72小时的应标注到小时(采用24小时制标注)。' WHERE id = '1eb39733-4997-4830-9ba6-0c6c9ebef3c7';
UPDATE public.questions SET analysis = '答案B正确。GB 7718规定，酒精度≥10%vol的饮料酒可免除标示保质期。无醇啤酒酒精度低于10%vol，应当标示保质期；葡萄酒及≥10%vol的发酵酒、配制酒可免标示。' WHERE id = '1ec189b3-930d-45e5-99b5-7ba548ce4747';
UPDATE public.questions SET analysis = '《食品安全法》第四十四条规定，食品生产经营企业应当配备食品安全管理人员，加强对其培训和考核。经考核不具备食品安全管理能力的，不得上岗，不得先上岗再培训。' WHERE id = '1ed8db30-70f6-49e1-a861-6cf642142501';
UPDATE public.questions SET analysis = '《食品安全法》第五十二条规定，食品生产企业应当建立食品出厂检验记录制度，查验出厂食品的检验合格证和安全状况。企业应严格产品检验，避免不合格产品流入市场。' WHERE id = '1ede88f9-7070-4d85-9d2d-ee5d6cb4896f';
UPDATE public.questions SET analysis = '答案D正确。《食品生产经营风险分级管理办法》规定，食品生产企业风险等级分为A、B、C、D四个等级，根据静态风险因素、动态风险因素和通用风险因素量化评分确定。' WHERE id = '1ee0e40a-e9d2-4e0f-aaf6-4067390d57db';
UPDATE public.questions SET analysis = '答案对正确。《食品安全法》第三十五条规定，国家对食品生产经营实行许可制度，从事食品生产、食品销售和餐饮服务均应依法取得许可，销售食用农产品和仅销售预包装食品的除外。' WHERE id = '1eec6b26-a094-4ce6-a6cc-4234673799a4';
UPDATE public.questions SET analysis = '答案A正确。《企业落实食品安全主体责任监督管理规定》要求，食品生产经营企业应收集食品安全风险信息，建立基于风险防控的动态管理机制，落实主体责任。' WHERE id = '1f2c7eb6-7426-4b35-82ff-610ac15cd762';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。花生、芝麻、植物原油、油茶籽均可作为食用植物油原料。GB 2716《食品安全国家标准 植物油》对各类植物油的原料和质量要求有明确规定。' WHERE id = '1f3344db-2d4d-4d7f-8633-1108841ae8ec';
UPDATE public.questions SET analysis = '答案B,C正确。β-胡萝卜素在蜜饯中用作着色剂，三氯蔗糖用作甜味剂。GB 2760对食品添加剂的使用范围和限量有明确规定。' WHERE id = '1f36a993-072c-4243-9d53-88c9f2da138e';
UPDATE public.questions SET analysis = '答案D正确。根据膨化食品生产许可审查细则，焙烤型膨化食品工艺流程包括制粉→蒸练→成型→一次干燥→熟成→二次干燥→焙烤→调味→包装等工序。蒸练使淀粉糊化。' WHERE id = '1f507ecf-642e-4b10-b59d-acbdb8b6adb4';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》(GB 14881)规定，检验室应与生产区域分隔，防止检验活动对生产造成污染，也避免生产环境干扰检验结果。' WHERE id = '1f5cba08-8eb4-4962-8bf1-8ca9fdee242d';
UPDATE public.questions SET analysis = '答案A,B,C正确。《标准化法》规定推荐性国家标准、行业标准、地方标准的技术要求不得低于强制性国家标准。' WHERE id = '1f7cfa22-2066-43a2-99eb-729b24af10a2';
UPDATE public.questions SET analysis = '答案D正确。《食品安全法》第六十三条规定，食品经营者发现经营的食品不符合标准或可能危害人体健康的，应停止销售、通知相关方、召回已上市食品。' WHERE id = '1f7dce3a-b491-4963-b5fb-de66087a2904';
UPDATE public.questions SET analysis = '答案A,C正确。《农产品质量安全法》规定，农产品批发市场发现不符合农产品质量安全标准的，应要求停止销售并向市场监管部门和农业农村部门报告。' WHERE id = '1f8f21fc-f23f-4ed9-8b8d-ff52800b2f27';
UPDATE public.questions SET analysis = '答案B,C正确。《餐饮服务食品安全操作规范》规定，手部清洗后的消毒方法包括消毒液浸泡、涂擦消毒剂等。干手机烘干和热水冲洗不属于规范的消毒方法。' WHERE id = '1f9c9f3f-f7a2-436a-a03b-6a8aee7cba5a';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。《行政许可法》规定，行政机关应将许可的事项、依据、条件、数量、程序、期限、需要提交的全部材料目录及申请书示范文本等在办公场所公示。' WHERE id = '1fa73141-761c-4a7a-8d5c-4c5816409fa3';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。《食品安全法实施条例》规定，涉及货值2万元以上、持续3个月以上、造成食源性疾病死亡、受处罚后1年内再犯等情节严重者，公安机关可对责任人处5-15日拘留。' WHERE id = '1fb930c7-e76a-477a-b2bf-f751556cd631';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食品添加剂包括营养强化剂。GB 14880《食品营养强化剂使用标准》是食品添加剂标准体系的重要组成部分。' WHERE id = '200a45d6-dbb9-43dc-828d-e0b4911839a8';
UPDATE public.questions SET analysis = '《反食品浪费法》第七条规定，餐饮服务经营者应在引导消费者按需适量点餐，提升餐饮供给质量，提供小份餐等不同规格选择，减少食品浪费行为。' WHERE id = '2014d381-0555-4250-972c-6c37d97064d3';
UPDATE public.questions SET analysis = '答案B,D正确。《食品安全法》第十二条规定，消费者协会和其他消费者组织对违反食品安全法规定、损害消费者合法权益的行为，依法进行社会监督。' WHERE id = '20205d51-9cf6-4165-8aa1-67bdd305e538';
UPDATE public.questions SET analysis = '答案B正确。飞行检查是市场监管部门根据监督管理工作需要及问题线索等，对食品生产经营者依法开展的不预先告知的监督检查，具有随机性和突击性特点。' WHERE id = '2047cd68-3ba1-478e-a5de-d9c97f3b1bf8';
UPDATE public.questions SET analysis = '答案A,C正确。天然肠衣主要包括盐渍肠衣和干制肠衣两大类，按加工工艺和保存状态分类。卷绕肠衣和套缩肠衣属于人造肠衣的类型。' WHERE id = '2068f3e5-57e1-4309-b949-09f2abe6e008';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，被许可人以欺骗、贿赂等不正当手段取得食品经营许可的，由原发证部门撤销许可，并处1万元以上3万元以下罚款，营造公平竞争的市场环境。' WHERE id = '206e5190-7b76-470c-8965-2b2102a38523';
UPDATE public.questions SET analysis = '答案C正确。辅食营养补充品的基本生产工艺包括原料处理、配料混合、包装等，成型工序主要用于片剂等固体制剂，不是所有辅食营养补充品都必须经过的工序。' WHERE id = '20738756-f9d0-45fb-96e8-93e5b618d5cd';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。《食品安全法》第三十三条规定申请许可应具备合理设备布局、防止交叉污染、避免食品接触有毒物等条件。' WHERE id = '20b53546-f03c-41d7-b6d4-9c6aa0807be7';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。《食品安全法》第五十三条规定从事食品批发的企业应建立销售台账，记录名称、规格、数量、生产批号、生产日期、保质期、购货者信息及销售日期。' WHERE id = '20bf010e-e567-47ae-b551-f166901b35b1';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。按皮色大豆可分为黄大豆、青大豆、黑大豆及其他大豆，这是GB 1352《大豆》中的分类方法。' WHERE id = '20e379f1-50d8-4fef-b353-ae05b449edeb';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。黄鳝、鳌虾、河蟹、贝类等鲜活水产品死亡后易腐败变质产生有害物质，不得作为食品加工原料。' WHERE id = '20ea532d-d40f-457c-a9db-fa805e8798c3';
UPDATE public.questions SET analysis = '《食品安全法》第四条规定，食品生产经营者对其生产经营食品的安全负责。腌渍食用菌生产企业作为食品生产经营者，应对其生产的食品安全负责。' WHERE id = '2101d981-e261-4705-863d-5e107fca04de';
UPDATE public.questions SET analysis = '《网络餐饮服务食品安全监督管理办法》鼓励外卖包装封签，防止配送过程中食品受到污染。鼓励在容器或包装上标注食用时限，提醒消费者收到后尽快食用，确保食品安全。' WHERE id = '2103919c-73da-4329-90de-6c475544e60a';
UPDATE public.questions SET analysis = '答案B正确。《餐饮服务食品安全操作规范》要求，餐饮服务场所与外界直接相通的通风口、换气窗外，应加装不小于16目的防虫筛网，防止虫害侵入。' WHERE id = '210c5839-bc97-402d-8781-795c5468a913';
UPDATE public.questions SET analysis = '《食品安全法》第十七条明确规定，食品安全风险评估不得向生产经营者收取费用，采集样品应当按照市场价格支付费用，评估经费列入政府财政预算。' WHERE id = '2120930a-0f29-44bd-b85c-f8919f5fafdd';
UPDATE public.questions SET analysis = '答案A,B,C,D正确。《食品安全法》第五十三条规定从事食品批发的企业应如实记录批发食品的名称、规格、数量、批号、保质期、购货者信息、销售日期并保留销售票据。' WHERE id = '2123ee26-4e00-4126-88d7-510b7916aa50';
UPDATE public.questions SET analysis = '答案D正确。《食品生产经营风险分级管理办法》规定，市场监督管理部门要根据上一年度风险等级以及规定的条件，对食品生产经营企业下一年度的风险等级相应进行动态调整。' WHERE id = '2126d557-f4a7-4532-9839-8c8ae260fa84';
UPDATE public.questions SET analysis = '《食品安全法》第三十八条规定，生产经营的食品中不得添加药品，但可以添加按照传统既是食品又是中药材的物质。' WHERE id = '21292d5a-c878-4c94-91f6-30cc15948542';
UPDATE public.questions SET analysis = '《食品安全法》第一百二十条之一规定，任何单位和个人不得编造、散布虚假食品安全信息。县级以上人民政府食品安全监督管理部门发现可能误导消费者和社会舆论的食品安全信息，应当立即组织核实、分析，并及时公布结果。' WHERE id = '214f36ce-23be-489a-a115-36534b0d2126';
UPDATE public.questions SET analysis = '答案A正确。GB 2762《食品安全国家标准 食品中污染物限量》规定酱腌菜中亚硝酸盐限量为≤20mg/kg。腌制过程中产生的亚硝酸盐需严格控制。' WHERE id = '21598a1e-d860-41e3-ad61-94af4f6e7f99';
UPDATE public.questions SET analysis = '答案A正确。GB 2760《食品安全国家标准 食品添加剂使用标准》规定了发酵型果酒中山梨酸的使用范围和最大使用量，食品中食品添加剂的使用应符合GB 2760的规定。' WHERE id = '216420e6-1bcd-48c1-9a39-46e1443039b8';
UPDATE public.questions SET analysis = '《食品安全法》第四十二条规定，食品生产经营者应当依照本法的规定，建立食品安全追溯体系，保证食品可追溯。国家鼓励食品生产经营者采用信息化手段采集、留存生产经营信息。' WHERE id = '216aa48c-2d86-4943-8ec2-cfeb27d51250';
UPDATE public.questions SET analysis = '答案A,B正确。《食品安全法》第五十条规定，记录保存期限不少于食品保质期满后六个月；没有明确保质期的不少于二年。' WHERE id = '216c3ab7-a9af-46b1-b70d-13e8476b4431';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，食品生产经营者应配合食品安全抽样工作，不得拒绝或阻挠，拒绝阻挠抽样的应依法处理。' WHERE id = '2172fe9a-aa08-435d-9624-582a521093b1';
UPDATE public.questions SET analysis = '答案A正确。GB 2760《食品安全国家标准 食品添加剂使用标准》规定了糕点中允许使用的食品添加剂品种、使用范围和最大使用量，糕点生产中应严格按GB 2760执行。' WHERE id = '217d5113-38f0-47f1-9ec4-cca08c473237';
UPDATE public.questions SET analysis = '答案B,C,D正确。《食品安全法》第七十四条规定特殊食品包括保健食品、特殊医学用途配方食品和婴幼儿配方食品。' WHERE id = '2181614a-f1ec-4300-8e72-5254ef76506b';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品冷链物流卫生规范》(GB 31605)规定，需冷冻的食品运输过程温度、贮存环境温度应不高于-18℃，确保冷冻食品的品质和安全。' WHERE id = '21938544-dee0-4049-a69e-a58b00da9b00';
UPDATE public.questions SET analysis = '答案D正确。《食品安全法》第四十四条规定，食品生产经营企业应对食品安全知识培训、考核情况予以记录，存档备查，确保培训工作可追溯、可检查。' WHERE id = '2193daea-bc47-4395-9068-d1f200499da0';
UPDATE public.questions SET analysis = '答案C,D正确。《学校食品安全与营养健康管理规定》要求中小学、幼儿园建立集中用餐陪餐制度，每餐均应有学校相关负责人与学生共同用餐，及时发现和解决问题。' WHERE id = '21a0c6bc-93b8-4287-bfe0-90ae6150c0d4';
