UPDATE public.questions SET analysis = '答案D正确。《食品安全法》第三十三条、第四十四条规定，食品生产经营企业应建立健全食品安全管理制度，对职工进行食品安全知识培训，加强食品检验工作。' WHERE id = '21dd29fd-2965-4669-9930-5c78ce6be126';
