UPDATE public.questions SET analysis = '答案A,B,C,D正确。虫害包括苍蝇、蟑螂、麻雀、老鼠等有害生物，食品生产经营场所应采取有效防治措施。' WHERE id = '221e8dae-ee17-4b91-878c-8fb049921ff6';
