UPDATE public.questions SET analysis = '稻谷在储存过程中易受黄曲霉毒素污染，小麦在田间和储存期间易受镰刀菌产生的脱氧雪腐镰刀菌烯醇(DON，又称呕吐毒素)污染。这是谷物原料常见的真菌毒素风险，企业应加强原料检验。' WHERE id = '2299ab6d-eca9-4ebf-ab93-c5845eae9557';
