UPDATE public.questions SET analysis = '炒货食品及坚果制品生产加工中使用霉变原料，会导致黄曲霉毒素等真菌毒素污染风险。花生、核桃、瓜子等原料在储存不当时易滋生黄曲霉产生毒素。' WHERE id = '276e9720-b329-4dc3-a189-1ed1e2979dd8';
UPDATE public.questions SET analysis = '正确答案为A,B,C,D。根据《食品安全法》及相关食品生产法规标准要求，这些选项均符合题意，其余选项不符合法律规定或标准规范要求。' WHERE id = '2781fd93-46be-4c13-a887-f19c726dc46f';
UPDATE public.questions SET analysis = '《食品安全法》第一百一十条规定，县级以上人民政府食品安全监督管理部门有权查封违法从事食品生产经营活动的场所。但刑拘由公安机关执行，限制人员活动、撤销企业领导职务均非监管部门权限。' WHERE id = '27ac131a-fa48-43e9-bddb-05c58783b1a1';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，市级、县级市场监督管理部门按照年度监督检查计划对本行政区域食品生产经营者开展的常规性检查属于日常监督检查（含''双随机''抽查检查）。' WHERE id = '27baf8d0-49dc-49fc-83a1-c7b59229b6df';
UPDATE public.questions SET analysis = '《农产品质量安全法》规定，农产品销售企业对其销售的农产品，应当建立健全进货检查验收制度，查验农产品质量安全状况和合格证明。个人销售者、生产企业和合作社的要求有所不同。' WHERE id = '27bca703-7ecf-4d06-ac59-40d23cdaa9d7';
UPDATE public.questions SET analysis = '含茶制品生产过程中存在超范围超限量使用食品添加剂的风险，包括着色剂（改变色泽）、抗氧化剂（延长保质期）、防腐剂（防止变质）、甜味剂（增加甜度）等。' WHERE id = '27de8656-be5c-45b0-876f-73e7edc6559f';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十五条规定，因食品安全犯罪被判处有期徒刑以上刑罚的，终身不得从事食品生产经营管理工作，也不得担任食品生产经营企业食品安全管理人员。' WHERE id = '27e0ef1f-86e9-49fc-ac7b-c00cac926091';
UPDATE public.questions SET analysis = '采购特殊食品应查验供货者的许可证、产品批准证明文件（注册证或备案凭证）、同批次产品出厂检验合格证或检验报告等，三项均需查验并留存复印件，索取有效进货凭证。' WHERE id = '27f73655-8342-4582-9414-bd619d13a69c';
UPDATE public.questions SET analysis = '蜂花粉是蜜蜂采集植物花粉后用唾液和花蜜黏合形成的花粉团，核心成分是植物花粉而非蜜蜂自身分泌的物质。题目表述''蜜蜂采集花粉，用唾液和花蜜混合后形成的物质''虽有一定道理但定义不够准确严谨。' WHERE id = '280589b7-7186-47cc-baaf-c9e4af4bc190';
UPDATE public.questions SET analysis = '水果干制品的典型生产工艺包括选料、清洗、去皮（或不去皮）、切分（或整果）、干燥、包装等。护色和软化属于部分特定产品的可选工艺，并非水果干制品的通用必备工艺。' WHERE id = '280824de-065a-4a8a-8660-a6604bdd24bb';
UPDATE public.questions SET analysis = '正确答案为A,B,C。根据《食品安全法》及相关餐饮法规标准要求，这些选项均符合题意，其余选项不符合法律规定或标准规范要求。' WHERE id = '2814905f-4357-4dd5-9955-d13c9b8de49e';
UPDATE public.questions SET analysis = 'GB 2730《食品安全国家标准 腌腊肉制品》规定，火腿中三甲胺氮的限量值为≤2.5mg/100g。三甲胺氮是反映肉制品蛋白质分解程度和新鲜度的重要化学指标。' WHERE id = '28187e1d-3722-484a-8926-7d83d05f3fca';
UPDATE public.questions SET analysis = 'GB/T 20706-2023《可可粉质量要求》规定，可可粉水分应控制在≤5g/100g。水分含量过高会导致产品易霉变、结块，影响保质期和品质。' WHERE id = '2823b6de-0cbd-424d-b6c1-d056624569bc';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营应当具有与生产经营的食品品种、数量相适应的场所，保持场所环境整洁，并与有毒、有害场所以及其他污染源保持规定的距离。' WHERE id = '284f508e-6975-493d-b43b-d0ce70d0931b';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营人员应保持个人卫生，生产经营食品时应将手洗净、穿戴清洁的工作衣帽，防止污染食品。' WHERE id = '2856c4db-1efc-44d7-948c-605ceb333aae';
UPDATE public.questions SET analysis = '根据《食品经营过程卫生规范》和散装食品管理要求，散装食品贮存位置应标明名称、生产者名称及联系方式、生产日期或生产批号、保质期等。营养成分表非散装食品强制标示项目。' WHERE id = '2869ac33-79b5-4d9a-9674-09673e10a551';
UPDATE public.questions SET analysis = 'GB 14881规定，食品生产企业厂区应合理布局，各功能区域划分明显并有适当的分离或分隔措施；应有适当的排水系统；生活区应与生产区保持适当距离或分隔。厂区内空地可以铺设草坪绿化。' WHERE id = '28794db1-8730-4ac6-90bd-1f739bfb9ec6';
UPDATE public.questions SET analysis = '正确答案为A,C,D。根据《食品安全法》及相关食品流通法规标准要求，这些选项均符合题意，其余选项不符合法律规定或标准规范要求。' WHERE id = '287cb293-fcb8-4b80-9673-b67f1cd8af79';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十五条规定，因食品安全犯罪被判处有期徒刑以上刑罚的，终身不得从事食品生产经营管理工作，也不得担任食品生产经营企业食品安全管理人员。' WHERE id = '28af6221-ac34-489f-b9bf-3f892a8e678c';
UPDATE public.questions SET analysis = '《食品安全法》第四条强调食品生产经营者是食品安全第一责任人，应当落实主体责任，强化诚信意识，推动食品安全多方主体主动参与的治理模式转变。' WHERE id = '28be0bed-639d-420c-b529-30493941c81e';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，用餐人数超过1000人的单位食堂应配备食品安全员和食品安全总监，落实''日管控、周排查、月调度''工作机制。' WHERE id = '28c680c5-2e97-4bd0-9d6d-c8184c1cd656';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，餐饮服务工作人员上厕所后应洗净手部，接触直接入口食品的人员还应消毒手部，以防止病原体通过手部传播污染食品。' WHERE id = '28d3073f-78a7-4668-8912-2ff5d41b1b3d';
UPDATE public.questions SET analysis = 'GB 14881《食品安全国家标准 食品生产通用卫生规范》规定，记录和文件可采用纸质形式，也鼓励采用先进技术手段（如电子计算机信息系统）进行记录和文件管理，但应确保数据安全可追溯。' WHERE id = '28d61520-bb07-421e-a5f8-fd41010b4f7a';
UPDATE public.questions SET analysis = '食品添加剂在改善食品的色、香、味等感官品质以及防腐、保鲜、加工工艺等方面起到重要作用。GB 2760规定了各类食品添加剂的使用范围和最大使用量。' WHERE id = '28eb7176-eadb-4cc8-9f4d-14c0ca0e9522';
UPDATE public.questions SET analysis = '《最高人民法院关于审理食品安全民事纠纷案件适用法律若干问题的解释》规定，经营者承诺的赔偿标准高于法定赔偿标准的，消费者有权主张按承诺标准赔偿，人民法院应予支持。' WHERE id = '29070af8-7cf3-4c80-90bb-5f3bc3b5abdd';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，市场监督管理部门收到监督抽检不合格检验结论后，应在5个工作日内将检验报告和抽样检验结果通知书送达被抽检食品生产经营者，告知其权利和义务。' WHERE id = '290c50da-9aa7-4a5a-aa8a-a488f89bedaa';
UPDATE public.questions SET analysis = '《食品安全法》第三十八条规定，生产经营的食品中不得添加药品，但可以添加按照传统既是食品又是中药材的物质。食品不得标识、宣传具有疾病预防或治疗功能。' WHERE id = '292d07f9-1a44-42bf-86c7-f451d585e9b8';
UPDATE public.questions SET analysis = 'GB 10770《食品安全国家标准 婴幼儿罐装辅助食品》规定，畜肉和禽肉类、鱼类原料应去掉刺、骨、鳞等不适宜婴幼儿食用的物质，以防婴幼儿食用时发生卡喉等安全事故。' WHERE id = '2933c974-abc7-4a2e-8fa9-98196321e1f8';
UPDATE public.questions SET analysis = '《网络餐饮服务食品安全监督管理办法》规定，外卖配送中直接入口食品和非直接入口食品、需低温保存的食品和热食品应分隔存放，防止交叉污染，并保证食品温度符合要求。' WHERE id = '294303b2-f678-44eb-a459-bb96719c1032';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》明确了食品安全员的具体职责，包括督促落实过程控制、检查管理制度执行情况、对问题食品采取整改措施并报告、管理从业人员健康和卫生状况等。' WHERE id = '294ff3da-b664-4b51-af5e-654002e33f72';
UPDATE public.questions SET analysis = 'GB 2762《食品安全国家标准 食品中污染物限量》定义，食品污染物是指食品从生产、加工、包装、贮存、运输、销售直至食用等过程中产生的或由环境污染带入的、非有意加入的化学性危害物质。' WHERE id = '295a68af-8487-4aca-8d47-6a4143f7086d';
UPDATE public.questions SET analysis = '《食品安全法》第七十四条规定，特殊食品包括保健食品、特殊医学用途配方食品和婴幼儿配方食品。绿色食品、无公害食品、有机食品为认证类别，非特殊食品。' WHERE id = '2969ff99-87ba-497d-9af3-7957d273107a';
UPDATE public.questions SET analysis = '《食用农产品市场销售质量安全监督管理办法》规定，因标签等原因被召回的食用农产品，在采取补救措施且能保证质量安全的情况下可继续销售，但应向消费者明示补救措施。' WHERE id = '297383c9-d5ed-4d7e-834e-59ec0a0b1254';
UPDATE public.questions SET analysis = '《食品安全法》第一百零二条规定，食品生产企业应当制定食品安全事故处置方案，定期检查本企业各项食品安全防范措施的落实情况，及时消除事故隐患，确保应急响应有效。' WHERE id = '2973f5d4-c8d1-470d-ae71-468fdc47f296';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》规定，市场监管部门在现场监督检查中可以依法对企业食品安全管理人员随机进行监督抽查考核，考核不合格的应调离岗位。' WHERE id = '297c688f-be75-4e1d-b4b5-4bc12ccf6eed';
UPDATE public.questions SET analysis = '《网络餐饮服务食品安全监督管理办法》第四条规定，入网餐饮服务提供者应当具有实体经营门店，依法取得食品经营许可证。不具有实体门店的不得从事网络餐饮服务。' WHERE id = '297e83ea-50d2-4d7f-88fc-f8b94b9c3365';
UPDATE public.questions SET analysis = 'GB 14881规定，食品生产企业选址不应选择对食品安全有明显不利影响且无法改善的地址，不应选择污染源不能有效清除的地址，不宜选择易发生洪涝灾害的地区。对原料产区距离无强制性要求。' WHERE id = '29840d9e-4fdb-4394-b30b-6d67f8aa19ad';
UPDATE public.questions SET analysis = '正确答案为B,C。根据《食品安全法》及相关食品生产法规标准要求，这些选项均符合题意，其余选项不符合法律规定或标准规范要求。' WHERE id = '29878f21-09fe-4669-a18c-0ed40f64bd71';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，纱帘、纱网、防鼠板、防蝇灯、风幕等装置是防控虫害危害的重要措施，能有效阻止苍蝇、老鼠、蟑螂等有害生物进入生产经营场所。' WHERE id = '2998ed08-be58-4504-806c-4729c4ea7321';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，被包装材料、容器、运输工具等污染的食品、食品添加剂不得使用和销售。被污染食品应予以销毁或采取其他无害化处理措施。' WHERE id = '29a470f5-36a4-4e87-910c-4db5b421e9e4';
UPDATE public.questions SET analysis = '《食品安全法》第五十条规定，食品相关产品生产者应建立进货查验制度，验明供货者营业执照、相关许可证件、产品合格证明和产品标识，确保采购的原料和辅料符合食品安全标准。' WHERE id = '29ac02ca-ed76-4e56-bb1c-023275379f18';
UPDATE public.questions SET analysis = '《食品安全法》第九十七条规定，进口预包装食品应有中文标签；依法应有说明书的还应有中文说明书；标签和说明书应符合我国法律法规和食品安全国家标准要求，并载明原产地及境内代理商信息。' WHERE id = '29c6dc72-632a-46b7-9de1-0048a5c54d8d';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营企业应建立进货查验记录制度，如实记录食品名称、规格、数量、生产日期或批号、保质期、进货日期及供货者信息，并保存相关凭证。' WHERE id = '29cc0cfa-7b66-4b1f-9f7f-5eaed38d7a42';
UPDATE public.questions SET analysis = '根据饼干产品生产工艺，饼干可在熟制前或熟制后在表面或内部添加果酱等配料，以丰富产品风味和品种。这是饼干生产的常规工艺，符合食品安全要求。' WHERE id = '29e37ceb-d941-4ad3-86f4-3dbd672603b9';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十条规定，集中交易市场开办者、柜台出租者、展销会举办者允许未依法取得许可的食品经营者进入市场或未尽检查报告义务，使消费者权益受损的，应与食品经营者承担连带责任。' WHERE id = '29ee42dd-bc8b-4e5c-b521-36daed3caae7';
UPDATE public.questions SET analysis = '根据《食品生产许可分类目录》，谷物粉类制成品包括生湿面制品、生干面制品、米粉制品等。大米粉属于谷物碾磨加工品，非粉类制成品。' WHERE id = '29f6e5ce-0037-4777-833a-55029706ca19';
UPDATE public.questions SET analysis = '根据饮料相关标准定义，饮料是指经过定量包装、可直接饮用或用水冲调饮用、乙醇含量不超过质量分数0.5%的制品。超过0.5%的属于酒类，而非饮料。' WHERE id = '29f8564f-6c8e-461d-a590-530708f9cf88';
UPDATE public.questions SET analysis = '《食品安全法》第二十五条规定，食品安全标准是强制性标准。除食品安全标准外，不得制定其他食品强制性标准。食品安全标准分为国家标准、地方标准和企业标准。' WHERE id = '29fbbe8c-01eb-4519-bf53-650e60ccfa38';
UPDATE public.questions SET analysis = 'GB 14881《食品安全国家标准 食品生产通用卫生规范》规定，食品生产企业微生物监控程序应包括微生物监控指标、取样和检测方法、取样点与监控频率、评判原则和整改措施等内容。' WHERE id = '2a00034e-aff7-4b26-82f6-69d0cc8b23ea';
UPDATE public.questions SET analysis = '《食品安全法》第六十一条规定，集中交易市场开办者应依法审查入场经营者许可证，明确食品安全管理责任，定期检查经营环境和条件，发现违法行为及时制止并报告。' WHERE id = '2a096aea-2661-42af-9730-b66d6c030da5';
UPDATE public.questions SET analysis = 'GB 17404《膨化食品》规定，膨化食品使用的挤压设备螺杆、套筒应符合食品安全要求（通常为食品级不锈钢），并应监控设备磨损情况，防止金属碎屑混入产品造成物理性危害。' WHERE id = '2a84cd6f-1b6b-4e4c-b4c6-12b348972edc';
UPDATE public.questions SET analysis = '《食品安全法》第四十七条规定，食品生产经营者自查时发现生产经营条件发生变化不再符合食品安全要求的，应立即采取整改措施；有发生食品安全事故潜在风险的，应立即停止经营并向监管部门报告。' WHERE id = '2a940d97-fe1c-4b95-ae14-60ae53a4a1e8';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营人员应保持个人卫生，生产经营食品时应将手洗净、穿戴清洁的工作衣帽；销售无包装直接入口食品时，应使用无毒清洁的容器和售货工具。' WHERE id = '2a96baed-16b8-4f09-8780-ec9ae9ded13c';
UPDATE public.questions SET analysis = '正确答案为A,B,C,D。根据《食品安全法》及相关食品流通法规标准要求，这些选项均符合题意，其余选项不符合法律规定或标准规范要求。' WHERE id = '2aac5d99-7dd3-4ea1-8767-adb90f10f9c7';
