UPDATE public.questions SET analysis = 'GB 24154-2015《食品安全国家标准 运动营养食品》规定，运动人群是指每周参加体育锻炼3次及以上、每次持续时间30分钟及以上、每次运动强度达到中等及以上的人群。' WHERE id = '2ad1698a-7065-491f-b6c2-c7439884c857';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，食品烹饪、冷却、餐用具清洗消毒等区域天花板涂覆或装修材料应不吸水、耐高温、耐腐蚀，以保证易于清洁且不易脱落污染食品。' WHERE id = '2ade7af5-57f1-4a9e-8f30-fbde5c4dcb8f';
UPDATE public.questions SET analysis = 'GB 14881《食品安全国家标准 食品生产通用卫生规范》定义，污染是在食品生产过程中发生的生物、化学、物理污染因素传入的过程。食品生产通用卫生规范旨在全面防控三类污染。' WHERE id = '2ae43866-d819-4d81-93c4-85c36d176ecb';
UPDATE public.questions SET analysis = 'GB 10769规定，婴幼儿辅助食品生产企业应定期（而非不定期）对主要原辅料生产商或供应商的质量体系进行现场审核评估，并形成审核报告。不定期审核不符合标准要求。' WHERE id = '2ae84900-b151-46ae-9d34-135f46376b8e';
