UPDATE public.questions SET analysis = '《学校食品安全与营养健康管理规定》要求，学校应将食品安全作为学校安全工作的重要内容，建立健全食品安全管理制度，定期组织开展食品安全隐患排查，及时消除食品安全风险。' WHERE id = '2b13d621-01cf-4ce6-826e-76ab46d7316d';
UPDATE public.questions SET analysis = '《网络餐饮服务食品安全监督管理办法》规定，送餐人员应保持个人卫生，配送箱（包）应定期清洗消毒。要求是''定期''而非''每个月''，一般应根据使用频次每周或每两周进行清洗消毒。' WHERE id = '2b15334f-aa54-454c-92ac-d1ad6a4d5dec';
