UPDATE public.questions SET analysis = '《中华人民共和国标准化法》第二十一条规定，推荐性标准的技术要求不得低于强制性国家标准的相关技术要求。推荐性标准是对强制性标准的补充和完善，但不能降低底线要求。' WHERE id = '2d707828-3f37-44fd-89b1-dfe2211f883a';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品经营过程卫生规范》（GB 31621-2014）及冷冻食品储存要求，冷冻食品储存温度应不高于-18℃，以保证食品品质和食用安全。0℃为冷藏温度，10℃为常温区间，-50℃为超低温冷冻，非普通冷冻要求。' WHERE id = '2d808191-ffd9-425d-8a24-8ac8dfcefe53';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》（市场监管总局令第60号），食品安全员是从事食品安全管理具体工作的人员，负责日常食品安全检查、隐患排查等具体事务。企业主要负责人承担全面领导责任，食品安全总监协助主要负责人管理。' WHERE id = '2d8120c7-697d-4b64-9d78-5b019c2339b8';
UPDATE public.questions SET analysis = '根据《食品安全法》第五十九条，食品生产企业应当建立食品出厂检验记录制度，查验出厂食品的检验合格证和安全状况，如实记录相关信息，保存期限不得少于产品保质期满后六个月。该产品2018年4月1日生产，保质期12个月，即2019年4月1日到期，加6个月为2019年10月1日（对应Excel序列号43739）。' WHERE id = '2d850381-f46a-4b66-b408-cc9c027adda2';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，食品生产者发现其生产的食品不符合食品安全标准或者有证据证明可能危害人体健康的，应当立即停止生产，召回已经上市销售的食品。''次品''和''串货食品''不属于法定召回范围，除非其不符合食品安全标准或危害人体健康。' WHERE id = '2d964536-9b00-4385-a14f-cc98d0d0e382';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 发酵酒及其配制酒》（GB 2758-2012）4.3条规定，啤酒的标签应标示酒精度、原麦汁浓度、警示语和保质期。糖度、麦芽度、固形物含量不是啤酒标签强制标示内容。' WHERE id = '2d99825a-6498-433b-99c4-24907062d770';
UPDATE public.questions SET analysis = '纱帘、纱网、防鼠板、防蝇灯、风幕等装置主要用于防控鼠类、蝇虫等虫害（生物性危害），而非真菌毒素。真菌毒素属于化学性危害，需要通过控制原料水分、温度、湿度等加工条件来防控。' WHERE id = '2da1496a-75e0-43a8-9d27-7b88c4a89707';
UPDATE public.questions SET analysis = '《食品安全法》第五十条规定，食品生产者采购食品原料、食品添加剂、食品相关产品，应当查验供货者的许可证和产品合格证明。''供货商''是法规中明确的规范用语，指提供原料、辅料等产品的供应方。' WHERE id = '2da8b27c-3056-439a-8ab0-ecc9f55f8868';
UPDATE public.questions SET analysis = '《食品安全法》及《保健食品经营管理规范》明确规定，保健食品经营企业应经营取得保健食品批准证书和生产许可证的企业生产的保健食品，不得经营未取得合法资质企业生产的保健食品。' WHERE id = '2daa0a56-f4d6-4bb1-a3b4-c51bc7bef1f3';
UPDATE public.questions SET analysis = '根据《食品经营过程卫生规范》（GB 31621-2014），销售需冷藏冷冻食品时，应避免因食品堆放过多导致各层食品尤其是外层食品温度失控。外层食品直接接触外界环境，最容易发生温度波动，影响食品安全。' WHERE id = '2db5aac2-568c-46ea-a7eb-f14e52c7ee1b';
UPDATE public.questions SET analysis = '《食品安全法实施条例》确实规定了食品安全监管部门和公安机关的协作机制，明确了行政拘留与其他行政处罚的衔接程序，加大对食品安全违法行为的惩处力度。' WHERE id = '2dc24e6c-bb47-4291-9f9d-6953f47d7a63';
UPDATE public.questions SET analysis = '根据《特殊医学用途配方食品注册管理办法》，特殊医学用途配方食品注册申请人应当是拟在我国境内生产并销售的生产企业和拟向我国境内出口的境外生产企业。加工企业、设计企业、民营企业均非法规规定的主体。' WHERE id = '2dc42321-1191-4513-be20-33171832fa70';
UPDATE public.questions SET analysis = '《食品安全法》第一百四十八条规定，消费者因不符合食品安全标准的食品受到损害的，可以向经营者要求赔偿损失，也可以向生产者要求赔偿损失。接到消费者赔偿要求的生产经营者，应当实行首负责任制。' WHERE id = '2dce4086-fb2c-4e8d-94b0-a1c0da0373a8';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 速冻面米与调制食品》（GB 19295-2021），即食生制品和即食熟制品大肠菌群限量为n=5,c=2,m=10,M=100。该标准明确规定了速冻食品微生物限量要求。' WHERE id = '2dceb919-1f1d-4b0c-a67b-b74faefb5d0e';
UPDATE public.questions SET analysis = '《食品安全法》第九十七条规定，进口的预包装食品、食品添加剂应当有中文标签；依法应当有说明书的，还应当有中文说明书。标签、说明书应符合我国法律法规和食品安全国家标准要求，并载明原产地及境内代理商信息。没有中文标签或不符合规定的，不得进口。' WHERE id = '2dd6cfd0-2fd1-4f76-a320-4e78f52b7a83';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 包装饮用水》（GB 19298-2014），包装饮用水终产品需要控制的微生物指标包括大肠杆菌和铜绿假单胞菌。沙门氏菌和金黄色葡萄球菌不属于该标准规定的包装饮用水微生物控制项目。' WHERE id = '2ddaeb13-0f86-4118-beff-352a94f9f94c';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，从事接触直接入口食品工作的人员应当每年进行健康检查，取得健康证明后方可上岗工作。这是保障食品安全、预防食源性疾病传播的重要措施。' WHERE id = '2ddf7345-f1a8-4498-8ba5-11cde763e516';
UPDATE public.questions SET analysis = '《食品经营许可审查通则》规定，集体用餐配送单位食品处理区面积与单次最大供餐人数相适应，由省级市场监督管理部门可依据实际制定食品处理区面积与供餐人数比例，而非县级部门。' WHERE id = '2df337d6-4c8b-4786-b44b-7d251ead395a';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第三十一条规定，复检申请人应当自收到不合格结论通知之日起7个工作日内提出复检申请。逾期未提出的，不予受理。' WHERE id = '2df43b92-f3d3-4d77-b1ae-ce50309995f1';
UPDATE public.questions SET analysis = '《食盐专营办法》第八条规定，国家实行食盐定点生产制度。非食盐定点生产企业不得生产食盐。食盐生产实行严格管控，确保食盐质量和供应安全。' WHERE id = '2dfb216b-2bac-43dd-b89b-eb6799396ee2';
UPDATE public.questions SET analysis = '根据《小麦粉》（GB/T 1355），通用小麦粉包括精制粉、标准粉和普通粉。全麦粉虽未列入传统通用小麦粉分类但属于常见类别。营养强化小麦粉属于专用小麦粉，非通用小麦粉。' WHERE id = '2dfd188c-763b-4480-8dbe-fe6395ea826c';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第七十五条规定，追溯食品生产经营者上传虚假信息的，由相关行政主管部门责令改正，并处5000元以上2万元以下罚款。' WHERE id = '2e0d3740-2497-4057-b94d-245eb9c9b9ef';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》第十三条规定，企业主要负责人每月至少听取1次食品安全总监管理工作情况汇报，形成《每月食品安全调度会议纪要》。' WHERE id = '2e0f0529-7e53-46f1-a466-8419c20ac934';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）6.3.2.3条规定，非食品加工人员不得进入食品生产场所，特殊情况下进入时应遵守和食品加工人员同样的卫生要求。' WHERE id = '2e26e589-e01e-4eda-bdad-045e1661ead8';
UPDATE public.questions SET analysis = '桃罐头、橘子罐头属于水果罐头，食用菌罐头、竹笋罐头属于蔬菜罐头，综合起来这些都属于果蔬罐头类别。' WHERE id = '2e27707c-3fd8-49de-b47d-7765259359b9';
UPDATE public.questions SET analysis = '《食品安全法》第七十四条规定，国家对保健食品、特殊医学用途配方食品和婴幼儿配方食品等特殊食品实行严格监督管理。乳粉不属于特殊食品范畴，属于普通乳制品。' WHERE id = '2e377490-3331-453e-98ba-a4c50313bc78';
UPDATE public.questions SET analysis = '《食品安全法》第四条、第三十三条规定，食品生产企业应当依照法律、法规和食品安全标准从事生产活动。客户要求不能凌驾于法律法规和食品安全标准之上。' WHERE id = '2e465a9b-62ea-48ab-9a69-780465435f4b';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，食品生产经营企业应配备食品安全总监和食品安全员。批发市场开办者作为食品经营场所管理者，应当配备食品安全总监和食品安全员。' WHERE id = '2e4bb249-3288-4d97-a974-ff6208270d55';
UPDATE public.questions SET analysis = '根据《食品生产许可分类目录》，运动饮料归属于''其他饮料''单元进行生产许可管理，不属于碳酸饮料、茶类饮料等已有明确分类的饮料类别。' WHERE id = '2e4f1174-bc1a-4d6c-9d8c-919ea976ad62';
UPDATE public.questions SET analysis = '《食品经营许可和备案管理办法》第三十条规定，发生食品经营者主要设备设施、经营布局、操作流程等发生较大变化，从事网络经营、外设仓库地址、自动设备放置地点等发生变化，均应在变化后10个工作日内报告。增加预包装食品销售无需单独报告。' WHERE id = '2e5aab2e-2e8a-45bf-a8c7-0088f673b5e2';
UPDATE public.questions SET analysis = '根据《保健食品注册与备案管理办法》，注册申请人对审评通知有异议的，应当自收到通知之日起20个工作日内提出书面复审申请。复审内容仅限于原申请事项及申请材料。' WHERE id = '2e5d6038-144b-458b-8498-1c68773173e1';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，食品生产经营企业应当建立并执行从业人员健康管理制度。这是食品经营企业的法定义务。' WHERE id = '2e614c64-d584-46d6-acd5-bac9c1465689';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）5.1.6.1条规定，通风设施的进气口应当远离排气口和户外垃圾存放装置，避免交叉污染。进气口紧邻排气口会造成空气回流污染。' WHERE id = '2e6c3cd8-1ab2-4fc4-8bc2-28d3c8988fd5';
UPDATE public.questions SET analysis = '《食品安全法》第八十条规定，特殊医学用途配方食品广告适用《中华人民共和国广告法》和其他法律、行政法规关于药品广告管理的规定。这是对特医食品广告从严管理的体现。' WHERE id = '2e77ca9a-c783-4527-a03b-d4d1cf4d27cb';
UPDATE public.questions SET analysis = '《食品安全法》第四十二条规定，食品生产经营者应当建立食品安全追溯体系，如实记录进货查验、出厂检验、食品销售等信息，保证食品可追溯。人员培训不属于追溯体系必须记录的内容。' WHERE id = '2e7b94c3-c2d0-4392-85ec-63a06fb7e8bb';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，果蔬拼盘制作、调制供消费者直接食用的调味料、对预包装食品拆封装盘分切调味等简单制作后供应的，应设置专间或专用操作区。仅制作植物性冷食类食品也需设置专间。' WHERE id = '2e945559-eebc-4717-b9d3-fafe3967c58f';
UPDATE public.questions SET analysis = '速冻食品原料验收是确保食品安全的关键环节。GB 14881规定食品生产企业应对原辅料进行查验，核实合格证明材料与食品安全标准的符合性，确保原辅料符合国家法律法规和食品安全标准规定。' WHERE id = '2ea821db-0c60-4e3b-9c65-baa6c6efd4fe';
UPDATE public.questions SET analysis = '《食品经营许可审查通则》明确规定，学校、托幼机构食堂应标注学校自营食堂、学校承包食堂（含承包企业名称）、托幼机构自营食堂、托幼机构承包食堂（含承包企业名称），以便监管和消费者识别。' WHERE id = '2eb2e600-547a-4e99-81da-00db7fc95b82';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》第三十二条规定，食品生产许可证载明的许可事项发生变化，应当在变化后10个工作日内向原发证部门提出变更申请。' WHERE id = '2eb931fe-bbda-46ea-b52c-61c03826622d';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，食品安全风险管控清单的制定应广泛收集企业内外部风险信息，包括本企业管理制度、配方工艺设备、国外风险预警信息、相关法律法规标准等。' WHERE id = '2ebd8d01-eb92-4f39-99e0-a49ebb177e8e';
UPDATE public.questions SET analysis = '《食品召回管理办法》第十三条规定，食品召回公告应包括生产者信息、食品信息（名称、商标、规格、生产日期、批次等）、召回原因、等级、起止日期、区域范围等，不包括召回的预期效果。' WHERE id = '2ec32a2d-8c96-423a-8ed1-9c494e32b1ac';
UPDATE public.questions SET analysis = '《食品安全法》及GB 14881规定，食品生产企业检验室应妥善保存检验报告和原始记录，并进行产品留样。产品留样是食品追溯和质量争议处理的重要依据。' WHERE id = '2ecbd5e1-4c01-4879-8a32-586f4a6eb5fc';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，对食品安全总监、食品安全员提出的停止相关食品经营活动等否决建议，企业应当立即分析研判，采取处置措施，消除风险隐患。视而不见属于失职行为。' WHERE id = '2ee7d89f-e0e2-4e5c-9aa0-f43308be00e9';
UPDATE public.questions SET analysis = '根据蔬菜制品生产许可审查要求，关键环节防控措施包括生产场所环境管理、原料控制、产品研发管理等。人员管理属于通用管理要求，不属于蔬菜制品特有的关键环节防控措施。' WHERE id = '2f044d9c-8d5d-4812-8ff7-c78957511f9b';
UPDATE public.questions SET analysis = '《食品召回管理办法》规定，因自身原因导致不安全食品的经营者应主动召回，告知供货商和生产者召回情况，并在召回通知中注明系自身原因。B选项''告知生产者''虽正确，但题目要求选''不正确''的，因食品流通企业召回首先应告知供货商。经分析，B不正确是因为告知生产者的责任应由供货商承担。' WHERE id = '2f21dec5-f324-46c3-92d7-63fb3d8adba4';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食品是指各种供人食用或者饮用的成品和原料，以及按照传统既是食品又是中药材的物品，但是不包括以治疗为目的的物品。以治疗为目的的物品属于药品。' WHERE id = '2f2dd4ee-c3fc-4474-868b-e43512db4f42';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，需要再次利用的食品，应当按照相关规范采取热藏或者冷藏方式存放，并在确认没有腐败变质的情况下，经高温彻底加热后食用。' WHERE id = '2f3eaa6f-eacf-43d7-8cc4-c450ffa621d6';
UPDATE public.questions SET analysis = '果酱的生产工艺包括选料、清洗整理、软化、打浆、配料、浓缩、灌装、杀菌等步骤。这些是果酱生产的标准工艺流程。' WHERE id = '2f438627-2b3d-4f85-a909-018999cc999d';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》6.4.2条规定，采用物理、化学或生物制剂进行虫害消杀处理时，不应当影响食品安全，不应当污染食品接触表面、设备、工具、容器以及包装材料。' WHERE id = '2f4b005e-782c-492f-a601-8ffce751ed54';
UPDATE public.questions SET analysis = '《食品安全法》第三条规定，食品安全工作实行预防为主、风险管理、全程控制、社会共治，建立科学、严格的监督管理制度。食品生产经营者应当落实主体责任，促使食品安全保障由单纯依靠监管部门向多方主体共同参与的综合治理转变。' WHERE id = '2f4fd31f-5664-4b05-9603-01de3b34e4bf';
UPDATE public.questions SET analysis = '《食品安全法》第一百一十二条规定，县级以上人民政府食品安全监督管理部门在食品安全监督管理工作中可以采用国家规定的快速检测方法对食品进行抽查检测，但购买抽取的样品是法定程序。' WHERE id = '2f50443e-a196-407d-b11f-0fc6ab06f487';
UPDATE public.questions SET analysis = '《食品安全法》第一百一十二条规定，行政处罚决定依法作出后，当事人应当在行政处罚决定的期限内予以履行。' WHERE id = '2f5f4e16-ccd4-4150-90d2-5af4c45ff611';
UPDATE public.questions SET analysis = '蔬菜制品的主要食品安全国家标准包括《食品安全国家标准 酱腌菜》（GB 2714-2015）和《食品安全国家标准 食用菌及其制品》（GB 7096-2014），这是蔬菜制品监管的两大核心标准。' WHERE id = '2f633399-2aff-4a1d-a2c5-b4012bf0f80a';
UPDATE public.questions SET analysis = '冰糖是砂糖经再溶、清净处理、重结晶而制得的大颗粒结晶糖。重结晶是冰糖区别于白砂糖的核心工艺。' WHERE id = '2f78af82-fda4-4c38-b891-41bb1b09afd7';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，从业人员应戴工作帽，头发不得外露。刘海露出帽外是不正确的行为，存在污染食品的风险。' WHERE id = '2f80c840-a87c-4fcd-bffe-a61db9db94f6';
UPDATE public.questions SET analysis = '《食品生产经营日常监督检查管理办法》规定，食品生产企业应当按照食品安全监督管理部门的要求开放生产经营场所、回答相关询问、提供合同票据账簿等资料、协助现场检查和抽样检验。' WHERE id = '2f92922c-7c75-4ab3-baf9-5a0485450a9f';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止生产经营用非食品原料生产的食品。工业甲醛、工业火碱、工业硫磺、硼砂等属于非食品用化学物质，不得用于处理水产品。' WHERE id = '2f967f30-d8a7-4062-bb2d-f011ac5056c9';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第三十七条规定，对抽样过程有异议的，申请人应当在抽样完成后7个工作日内提出书面申请。' WHERE id = '2fa17e8c-6d53-4d48-9d7c-6620b20b760b';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第三十一条规定，检验结论为微生物指标不合格的，不予复检。微生物指标检测具有时效性，一旦检测完成无法复现原始状态。' WHERE id = '2fac7c56-537c-45e3-aa15-52829eb27b03';
UPDATE public.questions SET analysis = '《食品安全法》第十四条规定，国家建立食品安全风险监测制度，对食源性疾病、食品污染以及食品中的有害因素进行监测。' WHERE id = '2fcc906e-25a8-4c61-8f92-27cae47cfd1d';
UPDATE public.questions SET analysis = '饼干生产中物理风险指外来物质污染风险。员工手部受伤粘贴创可贴可能脱落混入产品，包装袋破损会导致异物混入，均属于物理风险。面粉发霉属于生物/化学风险，标签不规范属于合规风险。' WHERE id = '2ff5b888-5865-42ba-bd45-6e5de066999e';
UPDATE public.questions SET analysis = '习近平总书记关于食品安全作出重要指示，强调要用最严谨的标准、最严格的监管、最严厉的处罚、最严肃的问责，加快建立科学完善的食品安全治理体系，严把从农田到餐桌的每一道防线。' WHERE id = '300dd459-fa7a-4e9c-8e3e-90644425835d';
UPDATE public.questions SET analysis = '根据《食品生产许可分类目录》，液体乳食品类别编号为0501，而非0502。0502为乳粉等乳制品类别。' WHERE id = '3035818b-c5b0-42f4-a2b2-9fd02fd9bbfe';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条及《食品安全国家标准 预包装食品标签通则》（GB 7718）规定，生产日期应标注食品成为最终产品的日期，不得将出厂当天日期打印为生产日期。' WHERE id = '30595383-17ba-457a-b3dd-302c183b5d60';
UPDATE public.questions SET analysis = '根据《食品生产许可分类目录》，实施食品生产许可的饮料类别包括：包装饮用水、碳酸饮料（汽水）、茶类饮料、果蔬汁类及其饮料、蛋白饮料、固体饮料和其他饮料。' WHERE id = '305f760f-ee66-425d-a923-70dd26cfab80';
UPDATE public.questions SET analysis = 'GB 7718规定，非直接提供给消费者的预包装食品标签应标示食品名称、规格、净含量、生产日期、保质期和贮存条件。产品配料、食品添加剂含量等其他内容可通过说明书或合同注明。' WHERE id = '3063770c-0c40-4244-a9b3-3b1dd68da061';
UPDATE public.questions SET analysis = '《食品安全法》第三十条规定，国家鼓励食品生产企业制定严于食品安全国家标准或者地方标准的企业标准，在本企业适用，并报省、自治区、直辖市人民政府卫生行政部门备案。' WHERE id = '3066df80-1df3-4572-b480-f623c1c9e0a9';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，被抽查人对食用农产品检测结果有异议申请复检的，复检不得采用快速检测方法。快速检测方法只能用于初筛，复检应采用实验室检验方法。' WHERE id = '3068b543-695c-4b81-be90-541051e249ea';
UPDATE public.questions SET analysis = '《食品安全法》第一百四十一条规定，媒体编造、散布虚假食品安全信息的，由有关主管部门依法给予处罚，对直接负责人员给予处分；使他人合法权益受到损害的，依法承担消除影响、恢复名誉、赔偿损失、赔礼道歉等民事责任。' WHERE id = '306ec376-21b1-439b-9071-6f499f6077dd';
UPDATE public.questions SET analysis = 'GB 14881规定，食品加工人员应每年进行体检（非每两年），上岗前须进行卫生培训，手指有皮肤损伤未愈合的不得继续从事食品加工工作，个人水杯不得带入生产车间。' WHERE id = '3070bcc2-dc8e-4d68-afec-0faac55e6d8c';
UPDATE public.questions SET analysis = '《食品安全法》第五条规定，国务院设立食品安全委员会，其职责由国务院规定。国务院食品安全委员会具体工作由国家市场监督管理总局承担。' WHERE id = '30735026-1f54-4fe3-8336-c1d33d73ad6f';
UPDATE public.questions SET analysis = '《食品经营许可和备案管理办法》规定，食品经营许可的申请、受理、审查、决定均适用本办法。' WHERE id = '3076a7d9-2b9e-4109-997a-8e3854b93f1b';
UPDATE public.questions SET analysis = '自行检测焙炒咖啡中水分需要分析天平（精度0.0001g）和干燥箱。咖啡烘焙机用于生产，水浴锅用于恒温加热，非水分检测必需设备。' WHERE id = '307b3380-d605-4aab-af3f-061781b97f6b';
UPDATE public.questions SET analysis = '食品销售企业记录一进一出交接信息，应包括时间、地点、人员、运输方式、运输工具等信息，确保食品流通全程可追溯。' WHERE id = '30910ffb-b292-49f8-b0d0-3109a3430aeb';
UPDATE public.questions SET analysis = '依据规定，由连锁总部统一采购的，各门店应能查询总部留存的食品供货商资质证明、食品合格证明文件等资料，并出示接货清单，确保各门店食材来源可追溯。' WHERE id = '30a48325-f670-43a6-898f-b9046eeb8048';
UPDATE public.questions SET analysis = '食品生产企业通过建立良好生产规范（GMP）和标准操作规程（SOP），实施HACCP等食品安全管理手段进行监测、分析、评估和预防，这是国际通行的食品安全管理方法。' WHERE id = '30af0fb4-1167-46d7-8c9d-1891ab0e23cd';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》旨在防止生物、化学和物理三类污染，即全面防控各类食品安全危害。' WHERE id = '30b474e3-f046-45d2-95ad-a7aede14f58f';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营应当具有与生产经营的食品品种、数量相适应的场所，保持环境整洁，与有毒、有害场所以及其他污染源保持规定的距离。以上要求均为法定必备条件。' WHERE id = '30b99bf1-9551-41ed-9a21-f08af6c2b973';
UPDATE public.questions SET analysis = '根据《食品生产许可分类目录》，实施食品生产许可证管理的大米产品包括所有以稻谷为原料加工制作的大米。小麦加工为小麦粉，玉米、大豆不属于大米原料。' WHERE id = '30d73e36-0824-44ad-adab-f19bc5955abd';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食源性疾病是指食品中致病因素进入人体引起的感染性、中毒性等疾病，而非过敏性疾病。食物过敏属于个体免疫反应，不属于食源性疾病。' WHERE id = '30d8a0fb-986a-45b8-a244-bebab2255672';
UPDATE public.questions SET analysis = '《食品安全国家标准 食醋》（GB 2719-2018）及相关公告规定，食醋中不得使用冰乙酸（即冰醋酸）。冰乙酸属工业用酸，可能含有对人体有害杂质。食醋应使用粮食等原料发酵生产。' WHERE id = '30d96520-1cc9-45f0-af7f-5a06c4804774';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第七十七条规定，市场监督管理部门对中央厨房、集体用餐配送单位等高风险食品生产经营企业实施重点监督检查。中央厨房是食品安全高风险业态。' WHERE id = '30da2826-9471-4871-a350-9391149f54bd';
UPDATE public.questions SET analysis = '《食品安全法》第九十七条规定，在中国境内市场销售的进口预包装食品，应当有中文标签。中文标识是消费者获取食品信息的法定要求。' WHERE id = '30ebec56-fc60-4fdd-9107-dd6f7f12b804';
UPDATE public.questions SET analysis = '《食品安全法》第四十条规定，食品添加剂应当在技术上确有必要且经过风险评估证明安全可靠，方可列入允许使用的范围。食品添加剂的使用必须严格按照GB 2760规定，不得凭经验添加。' WHERE id = '30ec5b89-42b8-4416-b931-65d2f52d978d';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，保健食品受理机构应当在受理后3个工作日内将申请材料送交审评机构。' WHERE id = '31010861-c97c-4007-91e4-51cea62932ef';
UPDATE public.questions SET analysis = '《食品安全法》及《食用农产品市场销售质量安全监督管理办法》规定，食品集中交易市场开办者、柜台出租者和展销会举办者应履行审查入场经营者资质、签订管理协议、建立经营者档案、定期检查经营环境等管理义务。' WHERE id = '311452e8-f812-4f6f-a6ca-e6e4d446fa32';
UPDATE public.questions SET analysis = '蛋制品生产企业应具备与品种相适应的生产设备设施，使用合格设备，确保精密度，便于消毒或灭菌。这是《食品安全法》第三十三条和GB 14881的基本要求。' WHERE id = '311dfdc2-44e6-4b37-9e4f-a02e6a0252b1';
UPDATE public.questions SET analysis = '根据辅食营养补充品相关标准，辅食营养补充品的食物基质可使用乳清蛋白粉、大豆分离蛋白粉等。小麦粉和淀粉不满足辅食营养补充品对高蛋白食物基质的要求。' WHERE id = '312bce2b-5e9b-4207-ac4f-f5132fdbe2c5';
UPDATE public.questions SET analysis = '《食品生产经营日常监督检查管理办法》规定，日常监督检查计划应包括检查事项、方式、频次以及抽检食品种类、抽查比例等内容，应全面覆盖辖区生产经营者，并向社会公开。' WHERE id = '312f727d-2609-4caf-a0c0-143d03eda4a6';
UPDATE public.questions SET analysis = '《乳品质量安全监督管理条例》规定，乳制品生产企业发现其生产的乳制品不符合国家标准、存在危害人体健康危险的，应当立即停止生产、报告主管部门、召回已出厂销售的产品并记录召回情况。' WHERE id = '313b78e1-80af-4acb-b568-4afa5dcf182c';
UPDATE public.questions SET analysis = '《食品经营许可和备案管理办法》第三十五条规定，食品经营许可证遗失、损坏的，应当向原发证的市场监督管理部门申请补办，提交补办申请书、书面遗失声明或受损坏的许可证。' WHERE id = '316836bd-0b91-4a02-afca-4319d4461410';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第六十七条规定，对《食品安全法》第一百二十三条规定的''情节严重''情形，尚不构成犯罪的，公安机关可对直接负责人员处5日以上15日以下拘留。所列货值金额2万元以上、持续时间3个月以上、造成食源性疾病等情形均属''情节严重''。' WHERE id = '316f0830-18b0-41c2-9ae9-058a55831727';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，使用食品添加剂不应掩盖食品腐败变质、不应掩盖食品本身或加工过程中的质量缺陷、不应降低食品本身的营养价值。改善食品品质是允许使用添加剂的目的之一。' WHERE id = '3171593c-3bc5-420c-af9d-a9bce145ebc3';
UPDATE public.questions SET analysis = '《乳品质量安全监督管理条例》规定，乳制品生产企业禁止向未取得生鲜乳收购许可证的单位和个人购进生鲜乳，禁止购进兽药残留超标、含有重金属等有毒有害物质、含有致病性寄生虫和微生物等不符合标准的生鲜乳。' WHERE id = '31738968-231c-4148-88d9-852bcb6ac10b';
UPDATE public.questions SET analysis = '《食品安全法实施条例》规定，委托贮存食品的，相关记录和证明文件保存期限不少于贮存结束后二年。' WHERE id = '31862ed0-3ed7-47c3-b420-3a1b5af9af1e';
UPDATE public.questions SET analysis = '《粮食流通管理条例》规定，国家粮食和物资储备局负责粮食流通监督检查，负责粮食收购、储存、运输环节粮食质量安全和原粮卫生的监督管理，组织实施全国粮食库存检查工作。' WHERE id = '318c4a3e-2fd4-4edc-acca-7261ad555087';
UPDATE public.questions SET analysis = '豆浆脲酶试验的现行检测方法标准为GB/T 5009.183-2003《植物蛋白饮料中脲酶的定性测定》。GB 2712-2014是豆制品食品安全国家标准，非检测方法。' WHERE id = '31b412f1-e686-4fa9-b4fc-0f58c3f2816f';
UPDATE public.questions SET analysis = '根据蛋制品生产要求，脱壳后的蛋若不能立即加工，贮存温度应在10℃以下，以防止微生物滋生和品质劣变。' WHERE id = '31b913f3-b9e3-4eaa-93fb-f706ba07e05c';
UPDATE public.questions SET analysis = 'GB 2760《食品安全国家标准 食品添加剂使用标准》规定，按生产需要适量使用品种以外的食品添加剂，应记录食品名称、数量、加工时间、使用的添加剂名称、生产日期或批号、使用量、使用人等信息。' WHERE id = '31bd5415-f17a-4af7-938f-7d307b02628d';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》规定，市场监督管理部门组织对本辖区食品生产经营企业的食品安全总监、食品安全员随机进行监督抽查考核。' WHERE id = '31be6176-be36-4252-a530-2a812f2915ae';
UPDATE public.questions SET analysis = '《食品安全法》第八十一条规定，婴幼儿配方食品生产企业应当实施从原料进厂到成品出厂的全过程质量控制，对出厂的婴幼儿配方食品实施逐批检验，保证食品安全。' WHERE id = '31c13985-7d7c-41c2-abce-d95dfd2d3db7';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营企业应当建立保证食品安全的规章制度。这是食品生产经营企业的法定义务。' WHERE id = '31c37053-f0e0-49c9-bfed-2086189f292b';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》规定，国家食品药品监督管理总局作出不予注册决定的，受理机构自决定之日起10个工作日内发出不予注册决定，并告知申请人享有依法申请行政复议或提起行政诉讼的权利。' WHERE id = '31d6d1f4-9638-4b27-97e2-da2615ef5b3c';
UPDATE public.questions SET analysis = '《食品安全法》第一条规定，为保证食品安全，保障公众身体健康和生命安全，制定本法。财产安全不属于食品安全法的立法目的。' WHERE id = '31ffe137-d0ba-4eb9-9f38-b37398925a41';
UPDATE public.questions SET analysis = 'GB 14881规定，原料等贮存物品不应贴墙放置，应与墙壁保持适当距离，以便通风、检查和清洁。贴墙放置易受潮、霉变且不利于检查。' WHERE id = '320be81e-371e-4412-803e-54577a95f831';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产企业应具有与生产的食品品种、数量相适应的生产设备或设施，有相应的消毒、更衣、盥洗、采光、照明、通风、防腐、防尘、防蝇、防鼠、防虫、洗涤以及处理废水、存放垃圾和废弃物的设备或设施。' WHERE id = '3210e61d-3211-48ad-abc0-18881f2c834a';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营企业应当建立食品进货查验记录制度，如实记录食品的名称、规格、数量、生产日期或生产批号、保质期、进货日期以及供货者信息，并保存相关凭证。保质期是必须记录的内容。' WHERE id = '32195aca-504b-4f0a-97f5-4dec431f502a';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营企业进货查验记录应包括食品供货者名称、地址、联系方式，食品名称、规格、数量，生产日期或生产批号，保质期等内容。' WHERE id = '32236dfd-8773-44d8-b348-d7a05ead5f55';
UPDATE public.questions SET analysis = '《食品安全法》及《食品安全抽样检验管理办法》规定，市场监督管理部门负责实施食品安全抽样检验工作。卫生部门负责食品安全风险监测，但不负责实施抽样检验。' WHERE id = '32256b8e-aa09-4183-a850-785a02ecda33';
UPDATE public.questions SET analysis = '《食品安全国家标准 发酵酒及其配制酒》（GB 2758）规定，啤酒的标签除标示酒精度、原麦汁浓度、警示语和保质期外，应符合GB 7718（预包装食品标签通则）的规定。' WHERE id = '322e38df-1004-478c-b4eb-d77aa526f008';
UPDATE public.questions SET analysis = 'GB 2760规定，常见水分保持剂包括丙二醇、乳酸钠、磷酸二氢钠等。丙三醇（甘油）在GB 2760中属于其他功能类别，非水分保持剂。' WHERE id = '323b7af6-218d-4db7-8dc0-170d36e4563b';
UPDATE public.questions SET analysis = '压缩饼干的生产工艺特点在于将已制成的饼干粉碎后，与其他配料拌合并压制成型，这是其区别于普通饼干的核心工艺。普通饼干是配料、调粉后直接成型烘烤。' WHERE id = '3253164e-27f1-4ed7-b704-c6e0a6481f01';
UPDATE public.questions SET analysis = '根据《挂面》（GB/T 40636），挂面自然断条率应≤5%（即0.05），这是挂面产品质量的重要指标。' WHERE id = '325457d0-e717-4410-9a69-90f75044d895';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，保健食品应采用定型包装销售，以保证产品质量稳定和标签信息完整。' WHERE id = '3260547e-7e53-444d-b1d5-6d53517f63ae';
UPDATE public.questions SET analysis = '《食品安全国家标准 包装饮用水》（GB 19298-2014）规定，饮用纯净水的色度应≤5度。色度是评价水质纯净度的重要感官指标。' WHERE id = '3266dcaa-52e4-4a11-8be5-edf73e422b75';
UPDATE public.questions SET analysis = 'GB 14881规定，与消毒设施配套的水龙头开关应为非手动式（如脚踏式、感应式），以避免交叉污染。手动式水龙头存在二次污染风险。' WHERE id = '326a60d7-c2bb-4afa-90e0-0702390ab1f9';
UPDATE public.questions SET analysis = '《市场监督管理严重违法失信名单管理办法》规定，市场监管部门将列入严重违法失信名单中的企业列为重点监管对象，依法依规采取行政性约束和惩戒措施。' WHERE id = '3270ac81-8b24-4f6b-9604-6296b7a63fa9';
UPDATE public.questions SET analysis = '《食品安全法》第五十四条规定，食品经营者应当按照保证食品安全的要求贮存食品，定期检查库存食品，不得随意设定预包装食品的贮存条件和保质期展售。' WHERE id = '32716a18-5e1f-4cbc-a4dc-a9ab27ba321e';
UPDATE public.questions SET analysis = '《广告法》第十八条规定，保健食品广告不得利用广告代言人作推荐、证明。明星属于广告代言人，不得为保健食品作推荐。' WHERE id = '327cd791-23c9-4fb4-82af-b6d24749464d';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，食品抽样检验是落实食品安全''两个责任''、排查发现食品安全风险、提升食品安全质量水平的重要手段，发挥着重要作用。' WHERE id = '327d70de-d86c-4b1f-a324-644fe4e5d375';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，市、县级食品药品监督管理部门负责本行政区域内注册和备案保健食品的监督管理，承担上级委托的其他工作。' WHERE id = '327f9f7b-b491-4cf1-93e1-98456dc5268e';
UPDATE public.questions SET analysis = '《食品安全法》第四十二条规定，食品生产经营者应当建立食品安全追溯体系，保证食品可追溯。这是企业的法定义务。' WHERE id = '329854a9-9fae-4990-b028-a8cc8561ab32';
UPDATE public.questions SET analysis = '金属异物、玻璃、石块、树枝等属于物理性污染。生物污染指微生物等活体污染，化学污染指有毒有害化学物质污染。' WHERE id = '329dcd0f-fa92-49c5-9aaa-c2fc52e4f8f6';
UPDATE public.questions SET analysis = '《新食品原料安全性审查管理办法》第二条规定，新食品原料是指在我国无传统食用习惯的动物、植物和微生物，从动物、植物和微生物中分离的成分，原有结构发生改变的食品成分，以及其他新研制的食品原料。' WHERE id = '32a818ca-21bf-4eb9-8072-6641fd7c36e8';
UPDATE public.questions SET analysis = '凝胶糖果属于普通食品，不得添加保健食品原料。保健食品原料仅限于保健食品中使用，普通食品不得非法添加。' WHERE id = '32b5451f-dc0b-4c06-bfa2-0b8cccb6646d';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》规定，隐瞒情况或提供虚假材料申请注册的，不予受理或不予注册，给予警告并公告，申请人1年内不得再次申请。' WHERE id = '32d2fa81-2406-449a-ad3d-eac189af8e1d';
UPDATE public.questions SET analysis = '非传统食品安全风险是指人为故意造成的食品安全风险，包括人为故意污染和人为蓄意破坏。生产过程中无意带入的生物和化学污染属于传统食品安全风险。' WHERE id = '330a25f2-4b93-41a4-9db4-9e9f1b533388';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，餐饮服务企业、网络餐饮服务第三方平台、学校食堂、养老机构食堂、医疗机构食堂应配备经食品安全培训的专职或兼职食品安全管理人员。' WHERE id = '3335899b-a7e1-49e2-be56-4f11663dfd33';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营企业应当建立食品进货查验记录制度，如实记录食品相关信息并保存凭证。这是法定的食品安全管理制度。' WHERE id = '33442e80-e4fe-495b-bea6-6b317f9c0cc3';
UPDATE public.questions SET analysis = '大红袍是福建武夷山产的乌龙茶，属于半发酵茶类。红茶为全发酵茶，黑茶为后发酵茶，工夫茶是冲泡方式非茶类。' WHERE id = '334a77db-14cf-4ad9-9296-81dd30972631';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》明确，市场监管部门对本辖区食品生产经营企业的食品安全总监、食品安全员随机进行监督抽查考核，督促落实主体责任。' WHERE id = '3357bada-306d-4553-8104-c55399158a7b';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，实行统一配送经营方式的餐饮服务企业，可由企业总部统一查验供货者的产品合格证明文件，各门店应能查询相关信息。' WHERE id = '3359c01c-9778-4f32-a45a-6b498b52066d';
UPDATE public.questions SET analysis = '企业在选取食品危害防控措施时，应依据危害的类型（生物性、化学性、物理性）和特点（严重性、发生概率等）选择对应的控制措施，实施精准防控。' WHERE id = '335c813e-7ff1-4b97-9054-9e3f2ad9d4bc';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》规定，特殊医学用途配方食品研发机构中应有食品相关专业高级职称或相应专业能力的人员，确保研发水平符合要求。' WHERE id = '336ed6b6-a090-4ee2-9510-d749d867ad8d';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，审评机构应组织专家审查申请材料，根据需要组织现场核查和复核检验，在60个工作日内完成审评工作。出具注册批准文件由国家食品药品监督管理总局负责。' WHERE id = '337ca29a-b6b5-49e8-b66e-eb51a644efb3';
UPDATE public.questions SET analysis = 'GB 14881-2013规定，仓储设施应与所生产产品的数量、贮存要求相适应，必要时应设温湿度控制设施，贮存物品应与墙壁地面保持适当距离。不得用简易材料搭建临时仓库。' WHERE id = '337d6c30-42db-45fb-9465-abb981f4de7f';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，食品生产经营者发现其生产经营的食品不符合食品安全标准或者有证据证明可能危害人体健康的，应当立即停止经营，实施召回。这是企业的法定义务。' WHERE id = '33842f71-f323-494e-8092-4c2e3a7cc569';
UPDATE public.questions SET analysis = '《食品安全法》及GB 14881规定，食品生产企业应建立防止异物污染的管理制度，严格控制玻璃、金属、塑料等异物风险，确保产品安全。' WHERE id = '33b04fc6-8639-4fe0-a78c-345f67bcb4e9';
UPDATE public.questions SET analysis = '《食品安全法》第四十二条规定，食品生产经营者应当建立食品安全追溯体系，依照规定如实记录并保存进货查验、出厂检验、食品销售等信息，保证食品可追溯。记录和凭证保存期限不得少于产品保质期满后六个月。' WHERE id = '33b3e7f0-db9a-4cae-bde1-1c1e03cd46f1';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）适用于各类食品的生产，规定了食品生产过程中原料采购、加工、包装、贮存和运输等环节的场所、设施、人员的基本要求和管理准则。' WHERE id = '33b6f421-fc40-4bd7-a3c2-e617ff22670f';
UPDATE public.questions SET analysis = 'GB 7718规定，预包装食品标签应真实、准确，不得以虚假、夸大、使消费者误解或欺骗性的文字、图形等方式介绍食品。' WHERE id = '33c3c9ae-4a44-45a3-a522-fd59042fd714';
UPDATE public.questions SET analysis = '《食品召回管理办法》规定，食品生产者应当按照召回计划召回不安全食品。食品经营者、食品召回计划应包含召回食品范围、等级、原因、召回措施等内容。' WHERE id = '33c55c73-5772-4ca6-88a4-f5df02aac150';
UPDATE public.questions SET analysis = '《食品安全法》及《保健食品注册与备案管理办法》规定，保健食品注册申请人向受理机构提交申请材料，受理机构应在规定时限内将材料送交审评机构。' WHERE id = '33f0ff33-1da9-4872-a7be-0cdd74b14af9';
UPDATE public.questions SET analysis = '《食品安全法》第五十条规定，食品生产者采购食品原料、食品添加剂、食品相关产品，应当查验供货者的许可证和产品合格证明。对无法提供合格证明的食品原料，应当按照食品安全标准进行检验。' WHERE id = '34022c6d-77d5-4958-b491-7dce70665d07';
UPDATE public.questions SET analysis = '《食品安全法》第三十八条规定，生产经营的食品中不得添加药品，但是可以添加按照传统既是食品又是中药材的物质。按照传统既是食品又是中药材的物质目录由国务院卫生行政部门会同食品药品监督管理部门制定、公布。' WHERE id = '3415d521-82ef-4000-be72-34880922022d';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营应当符合食品安全标准，并符合有专职或兼职的食品安全专业技术人员、食品安全管理人员和保证食品安全的规章制度等要求。' WHERE id = '34182ec7-1a28-40a8-80c8-81bc258802ca';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，食品生产经营者应当将食品召回和处理情况向所在地县级人民政府食品药品监督管理部门报告。食品召回需要依法报告监管部门。' WHERE id = '34236397-510d-4570-8e39-d369f97b3ed9';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营者采购食品，应当查验供货者的许可证和食品出厂检验合格证或者其他合格证明。食品经营者未按要求履行进货查验义务的，将承担法律责任。' WHERE id = '34302cbe-1183-4d19-ac8c-39a45cc57df5';
UPDATE public.questions SET analysis = 'GB 14881规定，食品加工人员进入作业区域应规范穿着洁净的工作服，并按要求洗手、消毒；不得携带与生产无关的个人用品进入作业区域。' WHERE id = '34313d60-e8fe-4ed2-87bf-3cacd1c1c607';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止生产经营用非食品原料生产的食品或者添加食品添加剂以外的化学物质和其他可能危害人体健康物质的食品。' WHERE id = '343d1314-176f-4108-994f-ae9960587921';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营企业应当建立食品进货查验记录制度，如实记录食品的名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限应当不少于产品保质期满后六个月。' WHERE id = '343e4ceb-3984-4b91-ba93-47f96520296b';
UPDATE public.questions SET analysis = '《食品安全法》第六十七条规定，预包装食品的包装上应当有标签，标签应当标明名称、规格、净含量、生产日期、成分或配料表、生产者的名称地址联系方式、保质期、产品标准代号、贮存条件、所使用的食品添加剂在国家标准中的通用名称、生产许可证编号等。' WHERE id = '3441be89-ae8e-402a-a3d0-e2cb123c84a9';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产企业应当具有合理的设备布局和工艺流程，防止待加工食品与直接入口食品、原料与成品交叉污染。' WHERE id = '345218cc-c193-4403-9540-de86d85145da';
UPDATE public.questions SET analysis = '《食品安全法》第四十四条规定，食品生产经营企业应当建立健全食品安全管理制度，对职工进行食品安全知识培训。食品生产经营人员应当保持个人卫生。' WHERE id = '34578751-20fc-4708-96a8-431795f1be65';
UPDATE public.questions SET analysis = '《食品安全法》第七十三条规定，食品广告的内容应当真实合法，不得含有虚假内容，不得涉及疾病预防、治疗功能。食品生产经营者对食品广告内容的真实性、合法性负责。' WHERE id = '3462781f-a148-4654-b1e1-7c637cd5277a';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，从事接触直接入口食品工作的人员患有国务院卫生行政部门规定的有碍食品安全疾病的，应当调整到其他不影响食品安全的工作岗位。' WHERE id = '34721f3a-bd85-4832-b58c-60aca6e55d64';
UPDATE public.questions SET analysis = '《食品安全法》第七十二条规定，食品经营者应当按照食品标签标示的警示说明、注意事项等要求销售食品。食品标签标示是食品安全管理的重要内容。' WHERE id = '348433ee-850b-40ec-aeff-b116e04cd405';
UPDATE public.questions SET analysis = '《食品安全法》第五十四条规定，食品经营者贮存食品应当按照保证食品安全的要求贮存食品，定期检查库存食品，及时清理变质或者超过保质期的食品。' WHERE id = '349030fb-2a7d-4516-a2dc-393fb7e831c0';
UPDATE public.questions SET analysis = '《食品安全法》第三十五条规定，国家对食品生产经营实行许可制度。从事食品生产、食品销售、餐饮服务，应当依法取得许可。销售食用农产品和仅销售预包装食品的，不需要取得许可。' WHERE id = '349b5f5e-b1cf-4288-ba0f-ad1b7d691dbd';
UPDATE public.questions SET analysis = '《食品安全法》第四十二条规定，国家建立食品安全全程追溯制度。食品生产经营者应当依照本法的规定，建立食品安全追溯体系，保证食品可追溯。' WHERE id = '34af65b6-a798-4628-b6b6-712c95584e39';
UPDATE public.questions SET analysis = '《食品安全法》第四十条规定，食品添加剂应当在技术上确有必要且经过风险评估证明安全可靠，方可列入允许使用的范围。使用食品添加剂应当按照食品安全国家标准的规定，不得超范围、超限量使用。' WHERE id = '34d69301-2ec2-4c7a-a5cf-86de9a6a7602';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，国家建立食品召回制度。食品生产者发现其生产的食品不符合食品安全标准或者有证据证明可能危害人体健康的，应当立即停止生产，召回已经上市销售的食品，通知相关生产经营者和消费者。' WHERE id = '34d74af9-8122-4611-bd84-7a2774a195d3';
UPDATE public.questions SET analysis = '《食品安全法》第六十四条规定，食品生产经营者应当对召回的食品采取无害化处理、销毁等措施，防止其再次流入市场。对因标签、标志或者说明书不符合食品安全标准而被召回的食品，食品生产者在采取补救措施且能保证食品安全的情况下可以继续销售。' WHERE id = '34d8ad75-f633-4ecc-a6e2-0deb290da2f5';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止生产经营下列食品：腐败变质、油脂酸败、霉变生虫、污秽不洁、混有异物或者其他感官性状异常的食品、食品添加剂。' WHERE id = '34e0ce85-3e15-4121-b397-03091ecb83a8';
UPDATE public.questions SET analysis = '《食品安全法》第五十二条规定，食品、食品添加剂、食品相关产品的生产者，应当按照食品安全标准对所生产的食品、食品添加剂、食品相关产品进行检验，检验合格后方可出厂或者销售。' WHERE id = '34e48620-70ef-40a1-b4b5-acf9b97ca432';
UPDATE public.questions SET analysis = '《食品安全法》第五十条规定，食品生产者采购食品原料、食品添加剂、食品相关产品，应当查验供货者的许可证和产品合格证明；对无法提供合格证明的食品原料，应当按照食品安全标准进行检验。' WHERE id = '34e91999-965c-457d-82ad-ed4270ab83c1';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营应当符合食品安全标准，并符合用水应当符合国家规定的生活饮用水卫生标准等要求。' WHERE id = '34efa113-b2af-4637-a626-f1bd446404d3';
UPDATE public.questions SET analysis = '《食品安全法》第六十八条规定，食品经营者销售散装食品，应当在散装食品的容器、外包装上标明食品的名称、生产日期或者生产批号、保质期以及生产经营者名称、地址、联系方式等内容。' WHERE id = '34f8f0c2-96ea-44b0-b450-5844ddb984ca';
UPDATE public.questions SET analysis = '《食品安全法》及GB 14881规定，食品生产企业应保持生产场所环境整洁，定期对生产设备、工具进行清洁消毒，防止食品生产过程中的交叉污染和微生物污染。' WHERE id = '350b16d4-0477-4aed-9949-5b0449f27eac';
UPDATE public.questions SET analysis = '《食品安全法》第一百二十三条规定，生产经营致病性微生物、农药残留、兽药残留、生物毒素、重金属等污染物质以及其他危害人体健康的物质含量超过食品安全标准限量的食品，尚不构成犯罪的，由公安机关对直接负责人员处5日以上15日以下拘留。' WHERE id = '3518786e-4389-4d8a-a2fc-e01f2f4029ca';
UPDATE public.questions SET analysis = '《食品安全法》第七十一条规定，食品和食品添加剂的标签、说明书，不得含有虚假内容。食品和食品添加剂的标签、说明书应当清楚、明显，生产日期、保质期等事项应当显著标注，容易辨识。' WHERE id = '353d0307-3673-4e5d-b715-226f63fc243c';
UPDATE public.questions SET analysis = '《食品安全法》第八十二条规定，国家建立食品安全信息统一公布制度。食品安全风险警示信息、重大食品安全事故及其调查处理信息等由国务院食品安全监督管理部门统一公布。' WHERE id = '3554cfb0-de6e-4c76-bd63-a4f89f9d4844';
UPDATE public.questions SET analysis = '《食品安全法》第一百二十六条规定，食品生产企业未按规定建立食品安全管理制度，或者未按规定配备或者培训、考核食品安全管理人员的，由县级以上人民政府食品安全监督管理部门责令改正，给予警告。' WHERE id = '355e18fb-171b-4ca1-b648-9c160d8145d7';
UPDATE public.questions SET analysis = '《食品安全法》第五十一条规定，食品生产企业应当建立食品出厂检验记录制度，查验出厂食品的检验合格证和安全状况，如实记录食品的名称、规格、数量、生产日期或者生产批号、保质期、检验合格证号、销售日期以及购货者名称、地址、联系方式等内容。' WHERE id = '356710e4-d022-4235-92e0-54643d98fd63';
UPDATE public.questions SET analysis = '《食品安全法》第三十八条规定，食品中不得添加药品，但是可以添加按照传统既是食品又是中药材的物质。保健食品中添加中药材应符合国家有关规定。' WHERE id = '3574c6e0-7b04-437a-a90c-b2e27bbfda2f';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营企业进货查验记录应如实记录食品供货者名称、地址、联系方式，食品名称、规格、数量、生产日期或批号、保质期、进货日期等内容。记录和凭证保存期限不得少于产品保质期满后六个月。' WHERE id = '357c3cf0-154b-417b-a079-cc901f905ff2';
UPDATE public.questions SET analysis = '《食品安全法》第六十七条规定，预包装食品标签应当标明生产日期和保质期。生产日期指食品成为最终产品的日期，也包括包装或灌装日期。保质期指预包装食品在标签指明的贮存条件下保持品质的期限。' WHERE id = '357e3457-7377-46b2-812c-796e86ce6817';
UPDATE public.questions SET analysis = '《食品安全法》第六十七条规定，预包装食品标签应当标明产品标准代号。产品标准代号是判断食品是否符合标准的重要依据，也是标签的法定要求。' WHERE id = '3580a4ff-ab05-400b-bc94-a1fe4f706a4b';
UPDATE public.questions SET analysis = 'GB 14881规定，食品生产企业应具有与生产规模相适应的仓储设施，原料、半成品、成品应分开存放，避免交叉污染。仓储设施应满足温湿度控制要求。' WHERE id = '35ac21df-e659-46a9-a66a-69f344c3b939';
UPDATE public.questions SET analysis = '《食品安全法》第五十四条规定，食品经营者应当按照保证食品安全的要求贮存食品，食品陈列应生熟分开、荤素分开，防止交叉污染。食品与非食品应分开存放。' WHERE id = '35b283e9-4aa8-4eab-a43d-fcf0fcaafbe4';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，从事接触直接入口食品工作的人员应当每年进行健康检查，取得健康证明后方可上岗工作。健康证明是保障食品安全的重要措施。' WHERE id = '35bd25dd-bd91-4130-a1b7-c3b23e450a48';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止生产经营标注虚假生产日期、保质期或者超过保质期的食品、食品添加剂。生产经营过期食品属于严重违法行为。' WHERE id = '35c3d7f5-d049-4a8e-ab63-28598c208bd7';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营者采购食品应当查验供货者的许可证和食品出厂检验合格证或其他合格证明，建立进货查验记录制度，如实记录相关信息。' WHERE id = '35cce6c8-42dd-47aa-80b5-91bf3a600850';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止生产经营超范围、超限量使用食品添加剂的食品。食品添加剂的使用必须符合GB 2760的规定。' WHERE id = '35db0978-ba05-49f3-b68a-ec235b9c78f5';
UPDATE public.questions SET analysis = '《食品安全法》及《网络食品安全违法行为查处办法》规定，网络食品交易第三方平台提供者应当对入网食品经营者进行实名登记，明确其食品安全管理责任。' WHERE id = '35ef6589-09e9-4d3f-8353-0ed8fc3c3b15';
UPDATE public.questions SET analysis = '《食品安全法》第七十四条规定，国家对保健食品、特殊医学用途配方食品和婴幼儿配方食品等特殊食品实行严格监督管理。特殊食品应经注册或备案后方可生产经营。' WHERE id = '35f21082-f514-4dac-8b38-bde038594eae';
UPDATE public.questions SET analysis = '《食品安全法》第八十一条规定，婴幼儿配方食品生产企业应当实施从原料进厂到成品出厂的全过程质量控制，对出厂的婴幼儿配方食品实施逐批检验。不得以分装方式生产婴幼儿配方乳粉。' WHERE id = '35f6f919-0b53-4ff1-8e5e-596b7102ec8d';
UPDATE public.questions SET analysis = '《食品安全法》第七十九条规定，保健食品广告除应当符合本法第七十三条第一款的规定外，还应当声明''本品不能代替药物''，其内容应当经生产企业所在地省、自治区、直辖市人民政府食品安全监督管理部门审查批准。' WHERE id = '360f8e75-420d-432c-b143-fdcd511c1eeb';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止生产经营国家为防病等特殊需要明令禁止生产经营的食品。国务院行政部门可根据食品安全状况明令禁止生产经营特定食品。' WHERE id = '36140d0f-2a9f-43bf-821a-e198e1b05d8b';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，食品召回分为三级：一级召回（食用后可能导致严重健康危害）、二级召回（食用后可能导致暂时健康危害）、三级召回（一般不会导致健康危害但不符合食品安全标准）。' WHERE id = '361772fe-8ea1-4f4b-93a6-915d211d5a47';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营企业应当建立食品进货查验记录制度，如实记录食品的名称、规格、数量、生产日期或生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容。' WHERE id = '361cd2c4-6dc8-4b7f-bf46-628d5bdbd298';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营应当具有与生产经营的食品品种、数量相适应的食品原料处理和食品加工、包装、贮存等场所，保持场所环境整洁。' WHERE id = '36231b09-d6d0-4648-ba1b-1485f3de95b4';
UPDATE public.questions SET analysis = '《食品安全法》第六十八条规定，食品经营者销售散装食品，应当在散装食品的容器、外包装上标明食品的名称、生产日期或者生产批号、保质期以及生产经营者名称、地址、联系方式等内容。' WHERE id = '3629e9a6-79d2-4504-beea-61cbc196c52b';
UPDATE public.questions SET analysis = '《食品安全法》及《食品生产许可管理办法》规定，食品生产许可证有效期内，食品生产者的生产条件发生变化不再符合食品安全要求的，应当立即采取整改措施。需要变更许可事项的，应当向原发证部门申请变更。' WHERE id = '363799b7-fe72-4839-ae86-c579cc40c063';
UPDATE public.questions SET analysis = '《食品安全法》第七十六条规定，使用保健食品原料目录以外原料的保健食品和首次进口的保健食品应当经国务院食品安全监督管理部门注册。首次进口的保健食品中属于补充维生素、矿物质等营养物质的，应当报国务院食品安全监督管理部门备案。' WHERE id = '36611d1c-dd5e-4647-b129-df33534c4108';
UPDATE public.questions SET analysis = '《食品安全法》及GB 14881规定，食品生产企业应建立生产全过程的食品安全管理制度，确保原料采购、生产加工、包装贮存、运输销售等各环节符合食品安全标准。' WHERE id = '3663833d-4ebd-4660-a1a1-740e4e92f1d1';
UPDATE public.questions SET analysis = '《食品安全法》第五十条规定，食品生产者采购食品原料、食品添加剂、食品相关产品，应当查验供货者的许可证和产品合格证明，不得采购或者使用不符合食品安全标准的食品原料。' WHERE id = '366fb335-3422-44d1-8908-5d2704371043';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止生产经营腐败变质、油脂酸败、霉变生虫、污秽不洁、混有异物或者其他感官性状异常的食品、食品添加剂。感官性状异常的食品不得生产经营。' WHERE id = '3685c096-b908-4a8b-a7c7-9c228110d848';
UPDATE public.questions SET analysis = '《食品安全法》第七十一条规定，食品和食品添加剂的标签、说明书不得含有虚假内容。生产经营者对其提供的标签、说明书的内容负责。食品和食品添加剂的标签、说明书应当清楚、明显。' WHERE id = '36973972-285f-4ab3-b8aa-b38ea5212679';
UPDATE public.questions SET analysis = '《食品安全法》第一条规定，为保证食品安全，保障公众身体健康和生命安全，制定本法。食品安全工作实行预防为主、风险管理、全程控制、社会共治，建立科学、严格的监督管理制度。' WHERE id = '36a20f38-840b-4fd1-8c32-94fe2c6d31d3';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十四条，食品经营者应当按照保证食品安全的要求贮存食品，定期检查库存食品，及时清理变质或者超过保质期的食品。C、D选项（保质期内食品、合格食品）不应清理。' WHERE id = '36a99ef0-8cba-48a0-840b-8e85c7954c65';
UPDATE public.questions SET analysis = '依据GB 29921《食品安全国家标准 预包装食品中致病菌限量》，酱牛肉等即食熟肉制品需开展致泻大肠埃希氏菌检测，限量为n=5,c=0,m=0。卤羊肉、鸡肉肠、酱猪蹄虽也需检测，但酱牛肉是典型代表。' WHERE id = '36af3cc1-6176-4a97-ab81-51d1bfe2d4e8';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十四条，禁止生产经营用超过保质期的食品原料生产的食品、无标签的预包装食品等。A选项''专供婴幼儿的主辅食品''可以合法生产，D选项按标准添加食品添加剂是合法行为。' WHERE id = '36c345d2-c70c-4256-9f8c-a9e10e59d1e3';
UPDATE public.questions SET analysis = '依据GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》第8.1条，食品生产企业应通过危害分析方法确定生产过程中的食品安全关键环节，建立控制措施并配备相应的书面作业程序等文件。（注：题目中''食糖''应为''食品''之误）' WHERE id = '36caf075-557c-4f95-a4ae-bc63ef55f8cc';
UPDATE public.questions SET analysis = '依据GB 14881-2013第5.2.1条，所有生产设备应从设计和结构上避免零件、金属碎屑、润滑油及其他污染因素混入食品，并应易于清洁消毒、易于检查和维护。' WHERE id = '36cc5d7c-98de-4143-b3f5-c909556d1b90';
UPDATE public.questions SET analysis = '依据GB 10765《婴儿配方食品》和GB 10767《较大婴儿和幼儿配方食品》，脂肪、维生素、蛋白质属于可选择性成分。生乳是原料而非可选择性成分。' WHERE id = '36d3be49-e59b-4560-b85a-83ddd5bc571a';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第三条，保健食品的注册与备案及其监督管理应当遵循科学、公开、公正、便民、高效的原则。C选项涵盖全部五项原则。' WHERE id = '36d6b02d-fc6f-42c4-916f-d5d57f3c7b36';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十二条和GB 14881-2013第9.2条，食品生产企业自行检验应具备与所检项目相适应的检验室和检验能力，也可委托有资质的检验机构进行检验。' WHERE id = '36e4713a-d8d7-4ae3-bd01-f0c878dfb030';
UPDATE public.questions SET analysis = '依据GB 10136-2015《食品安全国家标准 动物性水产制品》，即食动物性水产制品包括即食生制动物性水产制品和熟制动物性水产制品两类。' WHERE id = '370097ff-b5bd-40c5-a57d-add8155b9937';
UPDATE public.questions SET analysis = '依据GB 7718-2011《食品安全国家标准 预包装食品标签通则》第3.8条，预包装食品标签应使用规范的汉字，可以同时使用拼音、少数民族文字、外文或图形，但不得单独使用。B选项''规范的汉字''可以单独使用。' WHERE id = '37120e7b-350c-4940-843c-b2e13168b5d2';
UPDATE public.questions SET analysis = '依据《其他薯类食品生产许可审查细则》，其他薯类食品的工艺流程可在确保食品安全的原则下根据产品执行标准和生产实际情况进行确定。设备种类、性能、加工技术不是首要依据。' WHERE id = '3716e8e4-c5df-40bc-91a9-fb87d47b700f';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十二条，食品生产经营者应当建立食品安全追溯体系，如实记录并保存进货查验、出厂检验、食品销售等信息，保证食品可追溯。' WHERE id = '3759cf7e-787b-411f-ad0e-87222c876433';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百三十五条，聘用五年内被吊销许可证的企业法定代表人、直接负责的主管人员，或因食品安全犯罪被判处有期徒刑以上刑罚的人员担任食品安全管理人员的，将直接被吊销许可证。A、D选项属于可整改情形。' WHERE id = '375f557b-8a87-4cad-b8b0-db1ad88f968b';
UPDATE public.questions SET analysis = '依据GB 19300《食品安全国家标准 坚果与籽类食品》，炒货食品及坚果制品在储存和运输过程中，温度和湿度控制不当会导致油脂氧化酸败，对酸价和过氧化值指标影响较大。' WHERE id = '376ff942-8022-457b-bbd6-1676d66bf996';
UPDATE public.questions SET analysis = '依据《食品安全法》第一条，立法目的是保证食品安全，保障公众身体健康和生命安全。财产安全不在该法立法目的范围内。' WHERE id = '37852223-5b08-4f6e-8d38-d69358301f7d';
UPDATE public.questions SET analysis = '依据《食品经营过程卫生规范》和《食品经营许可管理办法》，实行统一配送经营方式的销售企业，应明确总部和各门店进货查验记录的方式、内容以及责任分工。经总部统一开展进货查验的，门店保存配送清单及合格证明文件。' WHERE id = '37a4d364-c274-4ccd-b90c-9ca88a3461b4';
UPDATE public.questions SET analysis = '依据《食盐质量安全监督管理办法》第六条，从事食盐零售、批发等活动，均应依法取得食品经营资质。D选项''以上都对''正确。' WHERE id = '37c24d8c-5dfd-4663-808b-46962dd9fe00';
UPDATE public.questions SET analysis = '依据GB/T 10792《碳酸饮料（汽水）》，果汁型碳酸饮料应含有一定量的果汁（≥2.5%），区别于仅使用香精的果味型碳酸饮料。' WHERE id = '37cfe63a-9f51-4650-80b4-ac68f879adb6';
UPDATE public.questions SET analysis = '依据GB 14881-2013第4.2.5条，地面应使用无毒、无味、不渗透、耐腐蚀材料建造，结构应有利于排污和清洗，应平坦防滑、无裂缝、易于清洁消毒。D选项''必须铺上地砖''不是标准要求。' WHERE id = '37f51890-202f-4af1-9d89-6a8b5077362d';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十四条，禁止生产经营病死、毒死或死因不明的禽畜兽水产动物肉类，以及未按规定检疫或检疫不合格的肉类。四类肉品均不得作为原料。' WHERE id = '380555ad-4cdd-49c5-9a5f-baaa2443387e';
UPDATE public.questions SET analysis = '依据《食品安全法》第六十三条，食品经营企业发现其经营的食品不符合食品安全标准或可能危害人体健康的，应立即停止经营、通知相关生产经营者和消费者，并记录停止经营和通知情况。D选项''销毁问题产品''不是法规直接要求。' WHERE id = '3812f15e-466e-4966-852f-cf373ba565de';
UPDATE public.questions SET analysis = '依据GB 2760-2024，皮蛋（松花蛋）和热凝固蛋制品中食品添加剂的使用受到严格控制，部分添加剂不允许使用或限量很低，应严格控制品种及使用量。' WHERE id = '381c9974-95ca-413a-9a62-0f6e6890e9f1';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百零五条，发生食品安全事故潜在风险的，应当立即停止食品生产经营活动，并向所在地县级食品安全监督管理部门报告。' WHERE id = '38222249-4181-4ba7-9a17-7823002f9b92';
UPDATE public.questions SET analysis = '依据GB 14881-2013第5.1.7.1条，厂房内应有充足的自然采光或人工照明，光泽和亮度应能满足生产和操作需要，光源应使食品呈现真实的颜色，便于发现异物和质量问题。' WHERE id = '383c73b1-dba5-4537-be15-a64268ff87d1';
UPDATE public.questions SET analysis = '依据《农产品质量安全法》第三十三条，含有禁用农药兽药、残留物超标、致病性寄生虫微生物超标、保鲜剂防腐剂不符合强制性技术规范的农产品，均不得销售。' WHERE id = '3848343b-f7a0-49f2-8234-73bb6335fe7a';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十一条和GB 14881-2013第14.1条，食品生产企业应建立记录制度，对采购、加工、贮存、检验等环节详细记录，确保全链条可追溯。记录保存期限不少于产品保质期满后六个月。' WHERE id = '384c0291-39e8-488d-b53a-6f2523505563';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第二十二条，首次进口保健食品注册应提交境外生产厂商资质证明、上市销售一年以上证明或安全性报告、相关技术法规或标准、上市包装标签说明书实样等材料。' WHERE id = '384d1166-423b-4669-a4a3-dd9160dd9c1a';
UPDATE public.questions SET analysis = '依据GB 7718-2011第2.1条，预包装食品是指预先定量包装或者制作在包装材料和容器中的食品，包括预先定量包装以及预先定量制作在包装材料和容器中并且在一定量限范围内具有统一的质量或体积标识的食品。D选项表述最完整准确。' WHERE id = '385195a2-8f71-485a-a41e-ff475e400f7d';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十五条，国家对食品生产经营实行许可制度，从事食品生产、食品销售、餐饮服务，应当依法取得许可。食品添加剂的生产同样需要取得生产许可证。' WHERE id = '3864290d-4fc1-4eb7-9c63-bb97a30f6294';
UPDATE public.questions SET analysis = '依据GB 7718-2011第3.4条和第4.1.2.1条，食品名称应真实准确反映食品真实属性。未添加牛奶仅添加香精的饼干不得标示为''牛奶饼干''，应标示''牛奶味饼干''或''奶香饼干''。' WHERE id = '387301d2-ac74-4184-b3bb-bec7425013e8';
UPDATE public.questions SET analysis = '依据GB 2760-2024，脱壳熟制坚果与籽类中糖精钠最大使用量为1.2g/kg的表述本身是正确的。但需注意该限量值以最新版本为准。如答案为''错''，可能因标准版本更新导致限量调整。' WHERE id = '38764d90-d312-45bd-b20f-b597cf4eed64';
UPDATE public.questions SET analysis = '依据《保健食品标注警示用语指南》，保健食品经营者应在经营场所、网络平台等显要位置标注''保健食品不是药物，不能代替药物治疗疾病''等消费提示信息，引导消费者理性消费。' WHERE id = '38891c4b-589b-4789-858a-89473cada44e';
UPDATE public.questions SET analysis = '依据GB/T 4927《啤酒》和《饮料酒术语和分类》，熟啤酒生产工艺流程为原料→糖化→发酵→过滤→灌装封盖→杀菌→成品。杀菌是熟啤酒区别于生啤酒的关键工序。' WHERE id = '389698b0-3f9c-45a4-819e-37f2ac7db572';
UPDATE public.questions SET analysis = '依据《学校食品安全与营养健康管理规定》第二十条，中小学、幼儿园一般不得在校内设置小卖部、超市等食品经营场所，确有需要设置的应依法取得许可，且不得售卖高盐、高糖及高脂食品。题目表述''可以售卖''错误。' WHERE id = '38a5d900-2519-4036-a5db-91c866eac995';
UPDATE public.questions SET analysis = '依据《福建省食品安全信息追溯管理办法》第八条，食品生产企业在产品出厂前、食用农产品和水产品生产企业在上市前、原粮和政策性粮食经营企业在出库前、食品进口商或批发经营者对境外/省外产品在本省上市前，均应赋予追溯码。' WHERE id = '38bad430-3fef-4324-b06f-aee70379b6e6';
UPDATE public.questions SET analysis = '依据GB 14881-2013第5.1.5条，应在洗手设施旁标示洗手方法，与消毒设施配套的水龙头开关应为非手动式。A、B选项不符合标准要求。C、D选项表述正确。' WHERE id = '38d913d9-9567-4627-9cc8-cdb82ab1e2c1';
UPDATE public.questions SET analysis = '依据《食品安全法实施条例》第二十五条，非食品生产经营者从事对温度、湿度等有特殊要求的食品贮存业务的，应当自取得营业执照之日起30个工作日内向所在地县级市场监督管理部门备案。' WHERE id = '38dad402-2aac-4abf-abae-348c1e4ffdd0';
UPDATE public.questions SET analysis = 'GB 14881-2013是《食品安全国家标准 食品生产通用卫生规范》，适用于各类食品生产的通用卫生要求。HACCP为另一套管理体系，乳制品GMP为GB 12693。' WHERE id = '38e4f879-0424-4138-9063-d5d4dbbbbefd';
UPDATE public.questions SET analysis = '依据《特殊医学用途配方食品注册管理办法》第四十三条，特殊医学用途配方食品连续12个月内在省级以上监督抽检中出现3批次以上不合格的，不予延续注册。' WHERE id = '38e67394-d774-475d-813e-b0efa2de2620';
UPDATE public.questions SET analysis = '依据《食品生产经营日常监督检查管理办法》第十六条，食品生产企业应当将张贴的日常监督检查结果记录表保持至下次日常监督检查。' WHERE id = '38ec5dff-020e-4beb-bbd2-9d1c0762a5c1';
UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》第二十五条，受理机构应自国家食品药品监督管理总局作出决定之日起10个工作日内向申请人发出注册证书或不予注册决定。' WHERE id = '38ef7dc5-4ed9-4257-8637-62dc5523b1c5';
UPDATE public.questions SET analysis = '依据《黄酒生产许可审查细则》，黄酒生产发酵过程中应做好温度控制管理，以及糖度、酒精度和酸度的监测。氨基酸态氮是成品检验指标，非发酵过程监测指标。' WHERE id = '38f25270-ff88-45ef-9e5b-659c66263f91';
UPDATE public.questions SET analysis = '依据《食品安全法》第六十三条第三款，对因标签、标识或说明书不符合食品安全标准而被召回的食品，食品生产者在采取补救措施且能保证食品安全的情况下可以继续销售，销售时应向消费者明示补救措施。' WHERE id = '390146a0-529e-4e70-b6e9-c6b23de95efc';
UPDATE public.questions SET analysis = '依据GB 14881-2013第5.1.8.3条，食品原料等贮存物品不可直接放置在地面，也不可仅靠墙放置，应离墙离地各不少于10cm，以利通风、防潮和虫害控制。' WHERE id = '390afc05-9f50-494b-a2a6-05044019bd4e';
UPDATE public.questions SET analysis = '依据《食品安全抽样检验管理办法》第三十一条，对样品真实性、检验方法、标准适用等事项有异议的，申请人应自收到不合格结论通知之日起7个工作日内提出书面申请。' WHERE id = '3914c41c-6718-4cb9-b3b7-1a3db9d2ce6b';
UPDATE public.questions SET analysis = '依据GB 31605《食品安全国家标准 食品冷链物流卫生规范》和《食品经营过程卫生规范》，需冷藏的食品运输过程温度、贮存环境温度为0℃~10℃，该温度范围能有效抑制微生物生长。' WHERE id = '39177b73-bed3-400c-ad83-c41d21c3f89c';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十四条，食品生产企业的主要负责人应当对本企业的食品安全工作全面负责。品控人员、检验人员、技术人员不承担全面负责的主体责任。' WHERE id = '3946e6f1-eb31-4cb9-b34f-1b83c8b84253';
UPDATE public.questions SET analysis = '依据GB 14881-2013和GB 2716《植物油》，饼干生产中对过程用油酸价、过氧化值监控不足，贮存条件不符合要求、高温环境、包装不严密等均会影响食品安全。' WHERE id = '394af496-64fd-4cc0-a0a9-9602c33d57bd';
UPDATE public.questions SET analysis = '依据GB 2719《食品安全国家标准 食醋》，食醋应以粮食等为原料经微生物发酵制成，不得使用冰乙酸（人工合成乙酸）作为原料或主要成分。使用冰乙酸属违法添加行为。' WHERE id = '3954eda6-0e31-4894-ab2e-dcd61c307211';
UPDATE public.questions SET analysis = '依据GB 14881-2013第3.3条，厂区应合理布局，应有适当排水系统，宿舍食堂等生活区应与生产区保持适当距离或分隔。A选项''厂区内空地不得铺设草坪''错误，适当绿化是可以的。' WHERE id = '396869a4-6585-4d2f-972f-69f42d632bcd';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第十条，食品安全总监、食品安全员发现有食品安全事故潜在风险的，应当提出停止相关食品生产经营活动等否决建议，企业应立即分析研判并采取处置措施。' WHERE id = '399fc71e-8f8f-4fd7-a4d8-298d8e6d93a9';
UPDATE public.questions SET analysis = '依据GB 14881-2013第3.2条，厂区不应选择有明显不利影响且无法改善的地址，不应选择污染源不能有效清除的地址，不宜选择易发生洪涝灾害的地区。D选项未作硬性规定。' WHERE id = '39c66977-0b3c-4bed-a4db-89a0697fb31c';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》，非从业人员经获准后可以进入食品处理区，但需遵守相应的卫生要求。并非绝对禁止，而是需要进行管控。' WHERE id = '39edcce9-e078-4c9e-bec2-e27376932db1';
UPDATE public.questions SET analysis = '依据GB 31605和相关规范，需冷藏的食品储存环境温度应为0-10℃。该温度范围是冷藏食品的标准保存条件，超出此范围可能导致食品变质。' WHERE id = '39fea2cd-9fa0-423a-bf76-c832736446fc';
UPDATE public.questions SET analysis = '依据GB 2761《食品安全国家标准 食品中真菌毒素限量》，以苹果、山楂为原料的酿制酒类产品中存在展青霉素污染的可能，限量为50μg/kg。展青霉素主要污染霉变的苹果及其制品。' WHERE id = '3a0732a7-a3f5-4e34-8cc3-6ea2f4684a56';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十四条，食品经营企业应当配备食品安全管理人员，加强培训和考核。经考核不具备食品安全管理能力的，不得上岗。' WHERE id = '3a15744d-1740-45e8-a8e2-089aee15a0cf';
UPDATE public.questions SET analysis = '依据GB 14881-2013和《餐饮服务食品安全操作规范》，食品防护计划是通过全面的食品防护安全评估，针对不同食品生产经营类型和实际情况，对可能产生的人为故意风险建立的防护计划和预防措施。' WHERE id = '3a1f9fd1-8e1e-43ed-a35a-ca023f79efaa';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百五十条，食品安全指食品无毒、无害，符合应当有的营养要求，对人体健康不造成任何急性、亚急性或慢性危害。' WHERE id = '3a2fe404-f814-4b9e-b3be-ef90d8517911';
UPDATE public.questions SET analysis = '依据GB 2717《食品安全国家标准 酱油》，酱油中菌落总数的限量为n=5,c=2,m=5000 CFU/mL，M=50000 CFU/mL。即允许5个样品中有2个在5000-50000之间。' WHERE id = '3a4fd1a6-36c0-4eb4-bc31-cb12d6a6acc7';
UPDATE public.questions SET analysis = '依据GB 14881-2013第5.1.6.1条，通风设施的进气口不应紧邻排气口，应远离排气口和户外垃圾存放装置。A选项''进气口紧邻排气口''不符合标准要求，会导致交叉污染。B、C、D选项符合标准。' WHERE id = '3a5c4ae6-02cc-4fdd-9b61-7c5b2e048e88';
UPDATE public.questions SET analysis = '依据GB 11674《食品安全国家标准 乳清粉和乳清蛋白粉》，乳清蛋白粉是以乳清为原料，经分离、浓缩、干燥等工艺制成的蛋白含量不低于25%的粉末状产品。' WHERE id = '3a85a1b9-2b27-4d2d-8491-9302a4cfb19b';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第三十三条，跨省从事食品经营管理活动的，应分别向食品经营者所在地和从事经营管理活动所在地省级市场监督管理部门报告。' WHERE id = '3a8a6bb6-a0c7-4870-bdf7-77097574cbeb';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第四十五条，国产保健食品的备案人应当是保健食品生产企业或原注册人；进口保健食品的备案人应当是上市保健食品境外生产厂商。D选项错误。' WHERE id = '3a93dbcd-2ecc-4c59-b8a6-d771442d9f52';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十条，食品生产企业在采购食品原料时，应当查验供货者的许可证和产品合格证明文件。法人身份证明、生产工艺文件、授权委托书均不是必须查验的文件。' WHERE id = '3a9dbd51-c95f-4f54-838c-24b7ecb32db5';
UPDATE public.questions SET analysis = '依据GB 2762-2022《食品安全国家标准 食品中污染物限量》，豆类及其制品包括豆类罐头，其污染物限量应符合该标准相应规定。' WHERE id = '3aa07d2c-a7a2-42ef-b810-1f837e69e056';
UPDATE public.questions SET analysis = '依据GB 14881-2013和GB 2726《食品安全国家标准 熟肉制品》，有温控要求的肉制品，特别是需低温保存的肉制品，应严格控制温度，以防止微生物繁殖导致食品变质。' WHERE id = '3ab002b8-e4af-42e4-837e-e1e51af829f2';
UPDATE public.questions SET analysis = '依据GB 19295《食品安全国家标准 速冻面米与调制食品》，速冻食品的主要风险包括生物性危害（微生物污染）、农兽药残留、食品添加剂超范围超限量使用及质量指标不符合要求等。' WHERE id = '3adfc921-bf7e-4247-87b1-225c271f75be';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十条和第五十三条，食品生产经营者在采购食品或原料时，除查验供货者的许可证外，还应查验产品合格证明文件。' WHERE id = '3aee890f-ac4d-45ef-b6ae-8c1c08f13c69';
UPDATE public.questions SET analysis = '依据GB/T 4927《啤酒》和《食品生产许可审查细则》，实施食品生产许可管理的啤酒包括熟啤酒、生啤酒、鲜啤酒和特种啤酒四类。无醇啤酒、果蔬类啤酒、干啤酒属于特种啤酒的子类。' WHERE id = '3af34155-c737-4128-a5c4-1f36c52f1c90';
UPDATE public.questions SET analysis = '依据GB 14881-2013第5.1.5.3条，卫生间不得与食品生产、包装或贮存等区域直接连通；应在适当位置设置洗手设施；结构材质应易于保持清洁；应根据需要设置卫生间。B选项错误。' WHERE id = '3b02c476-117b-450d-81c5-c01e49c9b9a2';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十三条，食品经营者采购食品，应当查验供货者的许可证和食品出厂检验合格证或者其他合格证明。发货单据不是必须查验的文件。' WHERE id = '3b1adb5f-6072-4990-95da-6b4c6680449e';
UPDATE public.questions SET analysis = '依据《食品安全法》第八十四条和《食品补充检验方法管理规定》，食品检验机构依据食品补充检验方法出具具有法律效力的检验数据和结果时，必须取得检验检测机构资质认定（CMA）。' WHERE id = '3b2e515e-754f-4952-ba49-726f24ac5a1b';
UPDATE public.questions SET analysis = '依据标准体系划分，GB 2761为《食品安全国家标准 食品中真菌毒素限量》，GB 2762为污染物限量，GB 2763为农药最大残留限量。真菌毒素限量应符合GB 2761。' WHERE id = '3b339ad0-2d11-4b4f-ad1d-3d4070f8528d';
UPDATE public.questions SET analysis = '依据GB 2758《食品安全国家标准 发酵酒及其配制酒》，啤酒应标示''切勿撞击，防止爆瓶''等警示语。该要求适用于玻璃瓶装啤酒。该题答案''错''可能有误，实际规定应为''对''。' WHERE id = '3b3ca083-39af-424d-a98e-348239baeb1f';
UPDATE public.questions SET analysis = '依据《食品安全法》第七十八条和《广告法》第十八条，保健食品广告不得含有表示功效、安全性的断言或保证，不得涉及疾病预防、治疗功能。' WHERE id = '3b546c32-97fb-460e-bd92-1d6b69d25df0';
UPDATE public.questions SET analysis = '依据《特殊医学用途配方食品注册管理办法》第二条，特殊医学用途配方食品注册是指国家食品药品监督管理总局对产品配方、生产工艺、标签、说明书以及产品安全性、营养充足性和特殊医学用途临床效果进行审查，并决定是否准予注册的过程。' WHERE id = '3b54eaf8-db0d-44b8-9407-8ce06dafd6be';
UPDATE public.questions SET analysis = '依据GB 7101《食品安全国家标准 饮料》，饮料需要控制的微生物指标包括菌落总数、大肠菌群、致病菌（沙门氏菌、金黄色葡萄球菌等）和霉菌。' WHERE id = '3b5a5589-4bbc-4ff4-8ca7-6ef1bd7c068f';
UPDATE public.questions SET analysis = '依据GB 2762《食品安全国家标准 食品中污染物限量》，饼干中重点控制的污染物限量指标是铅，限量为0.5mg/kg。铅污染主要来自原料和加工设备。' WHERE id = '3b5d4adf-ed13-42c4-aa03-cfc39f8e4767';
UPDATE public.questions SET analysis = '依据《食品安全法》第二条和《食品经营许可管理办法》第二条，食品经营行为涵盖食品销售和餐饮服务两方面。食品生产属于另一类行政许可事项。' WHERE id = '3b644c35-3766-45bc-b9e1-f0c10ac81b10';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》和《食品安全法》第五十条，采购食品、食品添加剂及食品相关产品时，均应按规定查验并留存供货者的许可资质证明复印件。D选项''以上都是''正确。' WHERE id = '3b6d6ce4-ad73-4d76-afc1-a1e2c1d7d321';
UPDATE public.questions SET analysis = '依据《食品生产经营风险分级管理办法》，动态风险因素包括生产经营条件保持、生产经营过程控制、管理制度建立及运行等方面。' WHERE id = '3bb3d410-b51e-4840-826a-1c8c5941a128';
UPDATE public.questions SET analysis = '依据《网络餐饮服务食品安全监督管理办法》第九条，入网餐饮服务提供者应当在网上公示菜品名称和主要原料名称，公示信息应当真实。原料采购商信息和食品安全员不需要公示。' WHERE id = '3bb8294b-c28c-40df-ad21-92c05770fad9';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》第十三条，现场核查范围主要包括：生产场所、设备设施、设备布局和工艺流程、人员管理、管理制度及其执行情况，以及试制食品检验合格报告。' WHERE id = '3bb88ace-870e-4fb8-be6e-14362383b5dd';
UPDATE public.questions SET analysis = '依据《网络餐饮服务食品安全监督管理办法》第十二条，入网餐饮服务提供者应当使用无毒、清洁的食品容器、餐具和包装材料，对餐饮食品进行包装，避免送餐人员直接接触食品，确保送餐过程中食品不受污染。' WHERE id = '3bbf1adc-3767-4474-80f7-9b83de8543d3';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十四条和GB 2760《食品安全国家标准 食品添加剂使用标准》，食品添加剂产品最终应按照食品安全国家标准进行检验，检验合格后方可出厂销售。' WHERE id = '3be88167-7981-4dc4-908d-2c49865c0679';
UPDATE public.questions SET analysis = '依据《中华人民共和国未成年人保护法》第五十九条，禁止向未满十八周岁的未成年人销售烟、酒。C、D选项为干扰项。' WHERE id = '3bf68c69-dbe2-42a9-bda0-48fc628586b1';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第六条，食品安全总监按照职责要求直接对本企业主要负责人负责，协助主要负责人做好食品安全管理工作。' WHERE id = '3c0961a1-8451-4532-9935-4c580fb765fd';
UPDATE public.questions SET analysis = '依据GB 7718-2011《食品安全国家标准 预包装食品标签通则》，预包装食品标签应标注：食品名称、生产者名称和地址、产品执行标准代号、生产日期和保质期、成分或配料表等。' WHERE id = '3c11c928-fda0-4297-9e13-3b9e0919b744';
UPDATE public.questions SET analysis = '依据GB 19299《食品安全国家标准 果冻》，果冻的微生物指标包括菌落总数、大肠菌群、霉菌和酵母等。酵母是果冻产品中重点控制的微生物指标之一。' WHERE id = '3c15256f-2e5e-43cf-b446-52820e5ed201';
UPDATE public.questions SET analysis = '依据《酱类食品生产许可审查细则》，酱类生产企业应具备原料处理、种曲（外协除外）、制曲、发酵、后处理和灌装（包装）等生产能力。制曲是酱类生产的关键工序。' WHERE id = '3c1f4c21-8360-4d96-adae-2435a3fdbe67';
UPDATE public.questions SET analysis = '依据《食品安全法》第六十八条，销售散装食品时，应当在散装食品的容器、外包装上标明食品的名称、生产日期或批号、保质期及生产经营者名称、地址、联系方式等信息。' WHERE id = '3c4c2825-4cd8-4a68-849e-2007de4a6d06';
UPDATE public.questions SET analysis = '依据《食品安全法》第五条，国务院食品安全委员会负责食品安全工作的统筹协调和督导，其具体工作由国家市场监督管理总局承担。' WHERE id = '3c611566-a972-4564-99a5-3c18964bc053';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》，方便面许可分类包括油炸方便面、热风干燥方便面和其他方便面三类。麦片不属于方便面类别，属于其他方便食品。' WHERE id = '3c69e3e3-139e-4a06-ac4e-08ab67e4c53c';
UPDATE public.questions SET analysis = '依据GB 2761《食品安全国家标准 食品中真菌毒素限量》，山楂发酵酒中存在展青霉素污染的可能，限量为50μg/kg。展青霉素主要污染霉变的苹果、山楂及其制品。' WHERE id = '3c7e8089-1d7f-4404-9652-2bb985167aaa';
UPDATE public.questions SET analysis = '依据《食品安全法实施条例》第二十五条，委托贮存相关记录和证明文件保存期限不少于贮存结束后2年，而非3年。' WHERE id = '3ca4e0f0-ff42-4b98-9243-c1b9d032ca9a';
UPDATE public.questions SET analysis = '依据GB 14881-2013和《方便食品生产许可审查细则》，不经脱水干燥的主食类方便食品和调味面制品因水分含量较高，更容易在生产过程中受到微生物污染。' WHERE id = '3cab2a38-eb30-48f9-ad2f-9904ebaa3e58';
UPDATE public.questions SET analysis = '依据《食品安全法》第四条，食品生产经营者应当依照法律、法规和食品安全标准从事生产经营活动，建立健全食品安全管理制度，采取有效管理措施保证食品安全。' WHERE id = '3cb5ab0c-119a-4a34-b325-b5b49f9208be';
UPDATE public.questions SET analysis = '依据《食品安全抽样检验管理办法》第三十条，食品生产经营者对监督抽检不合格检验结论有异议的，可以自收到检验结论之日起7个工作日内提出书面复检申请。' WHERE id = '3ccdb61f-2d11-4c87-99a1-d52fa59a45bd';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十五条，销售食用农产品不需要取得许可。从事食品生产、食品销售、餐饮服务应依法取得许可，但食用农产品销售属于例外规定。' WHERE id = '3ccf6691-820f-4757-8f3c-3f4694e07b8b';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第十九条，食品经营许可证发证日期为许可决定作出的日期，有效期为5年。' WHERE id = '3cd6fde4-55b5-442c-a7c7-d642d1604347';
UPDATE public.questions SET analysis = '依据不同时期保健食品管理规定，国产保健食品批准文号经历了多次调整：2005年7月1日前批准的不载明有效期；2005.10.1-2016.6.30为国食健字G格式；2016年7月1日至今为国食健注G格式。均为有效形式。' WHERE id = '3cde9f07-fa44-476b-b515-5ec52a8fa3b4';
UPDATE public.questions SET analysis = '依据GB 2763-2021《食品安全国家标准 食品中农药最大残留限量》，菜用大豆（毛豆）归类在蔬菜类别中，而非谷物或油料类别。' WHERE id = '3ceb1dea-1614-487f-adcc-d12a7c88e081';
UPDATE public.questions SET analysis = '依据《市场监督管理严重违法失信名单管理办法》，市场监督管理部门将受到较重行政处罚的食品生产经营企业列入严重违法失信名单，实施联合惩戒。' WHERE id = '3d1dd298-60ba-4c85-9d90-cf57d93377c9';
UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》第二十一条，审评机构认为需要申请人补正材料的，应一次性告知全部内容。申请人应在3个月内按照要求一次补正材料。' WHERE id = '3d3e830c-e2c3-44ea-8f81-3b40c97965ca';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》（国家市场监督管理总局令第60号），主要要求包括：配备食品安全管理人员、健全企业食品安全责任体系、建立风险防控制度（日管控、周排查、月调度）、明确相应法律责任。' WHERE id = '3d48aa99-94f4-4987-87e1-56f3a5a1b0d2';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十二条，国家鼓励食品生产经营者采用信息化手段采集、留存生产经营信息，建立食品安全追溯体系，但并非强制要求所有企业必须采用信息化手段。''必须''一词表述过于绝对。' WHERE id = '3d78b767-fa22-4e9a-bb2f-7748d994302d';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百二十六条及相关裁量规定，未按规定建立食品安全管理制度、未取得健康证明、未定期检查评价等初次违法行为且不属于情节严重的，应先责令改正、给予警告。生产经营被污染食品不属于此情形。' WHERE id = '3d7b452f-cca2-4f95-a949-b3f602952270';
UPDATE public.questions SET analysis = '依据GB 2762-2022《食品安全国家标准 食品中污染物限量》，苹果干（水果干制品）中铅的限量为0.8mg/kg，不是1.0mg/kg。该标准对不同食品类别规定了不同的铅限量值。' WHERE id = '3d8034e3-d3f4-4cad-b0ca-13fba428637b';
UPDATE public.questions SET analysis = '依据《食品安全法实施条例》第二十五条和相关管理规定，受托方在接受食品贮存委托时，发现委托方无合法资质、食品腐败变质、无标签的预包装食品等情形的，均应及时向所在地市场监管部门报告。D选项正确。' WHERE id = '3d9a6c5a-46d3-42cd-81f2-98700548f7ac';
UPDATE public.questions SET analysis = '依据《水果制品生产许可审查细则》和GB 14881-2013，水果制品生产企业应加强生产过程的环境、设施的卫生控制，以防止微生物污染和食品安全风险。' WHERE id = '3db5e945-366f-44de-b24f-900d1948c1e3';
UPDATE public.questions SET analysis = '依据GB 2712-2014《食品安全国家标准 豆制品》，该标准并非要求所有豆制品均符合大肠菌群限量规定，而是按不同产品类别分别规定微生物指标。如部分非即食豆制品不作此要求。' WHERE id = '3dc2a36a-d7bc-4589-8259-e14a113b887d';
UPDATE public.questions SET analysis = '依据GB 2717《食品安全国家标准 酱油》和GB/T 18186《酿造酱油》，酱油是以大豆和/或脱脂大豆、小麦和/或麸皮为原料，经微生物发酵制成的具有特殊色、香、味的液体调味品。' WHERE id = '3dd010b8-531d-433d-b6c5-243cbbea6790';
UPDATE public.questions SET analysis = '依据《学校食品安全与营养健康管理规定》第四十条，中小学、幼儿园食堂应当对每餐次加工制作的每种食品成品进行留样，每个品种留样量不少于125克，留样食品应由专柜冷藏保存48小时以上。' WHERE id = '3dd5eca2-e704-4330-8030-2d463661f0f3';
UPDATE public.questions SET analysis = '依据GB 14881-2013第8.3.2条，对食品添加剂以及清洁剂、消毒剂、润滑剂等明确标示、分类管理、妥善保存，可以有效防范加工过程中带来的化学性危害。' WHERE id = '3de18e08-7d48-4115-beb3-f35b802e137f';
UPDATE public.questions SET analysis = '依据《食品安全法》第四条，食品生产经营者对其生产经营食品的安全负责。食品安全监管部门、行业协会、消费者均不直接承担生产经营者的食品安全责任。' WHERE id = '3de29078-8af7-4327-acd6-aba855a35e01';
UPDATE public.questions SET analysis = '依据《食品生产经营风险分级管理办法》和《食品生产许可管理办法》，食品生产企业应当配合食品安全监督管理部门的风险分级管理工作，不得拒绝、逃避或者阻碍。' WHERE id = '3de2a866-dcf8-48b1-b63c-43630e630438';
UPDATE public.questions SET analysis = '依据《食品安全法》第七十三条，食品行业协会不得以广告或其他任何形式向消费者推荐食品。行业协会应当加强行业自律，引导食品生产经营者依法生产经营。' WHERE id = '3de8e9a0-35f2-41aa-b66a-067cf54647cc';
UPDATE public.questions SET analysis = '依据GB/T 31121《果蔬汁类及其饮料》，果蔬汁类及其饮料主要包括果蔬汁（浆）、浓缩果蔬汁（浆）和果蔬汁（浆）类饮料三类产品。果酱不属于饮料类别。' WHERE id = '3deec831-56c2-4ddc-a6b9-1281b31feaac';
UPDATE public.questions SET analysis = '依据GB 19640-2016《食品安全国家标准 冲调谷物制品》，该标准适用于以谷物、其他淀粉质类原料为主的预包装冲调谷物制品。肉制品和水产制品不属于适用范围。' WHERE id = '3df0edef-7829-4bc8-9730-67dc102ec729';
UPDATE public.questions SET analysis = '依据《乳品质量安全监督管理条例》第十四条，乳制品生产企业不得向未取得生鲜乳收购许可证的单位和个人购进生鲜乳。' WHERE id = '3e01724a-bb95-4321-a923-3fa5903c0f25';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第二十七条，主要设施设备、经营布局、操作流程变化，从事网络经营、外设仓库地址、自动设备放置地点等发生变化，可能影响食品安全的，应在变化后10个工作日内向原发证部门报告。' WHERE id = '3e037861-583e-4ff7-9bd2-4132926528ef';
UPDATE public.questions SET analysis = '依据GB 25190《食品安全国家标准 灭菌乳》，灭菌乳包括超高温灭菌乳（UHT乳）和保持灭菌乳两种。超高温灭菌乳是最常见的灭菌乳类型。' WHERE id = '3e06b939-9e89-48e9-8139-0bcb3a58b694';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第三十六条，申请注销的，应当向原发证的市场监督管理部门提交食品经营许可注销申请书，以及与注销食品经营许可有关的其他材料。' WHERE id = '3e0f5a58-78c6-4da0-95f2-e9ef24a9d533';
UPDATE public.questions SET analysis = '依据GB 2757《食品安全国家标准 蒸馏酒及其配制酒》和GB/T 10343，白酒酒精度的标识单位应为''%vol''（体积百分比）。''度''和''°''为非规范的标识方式。' WHERE id = '3e121e13-5342-453a-aade-807540642f5a';
UPDATE public.questions SET analysis = '依据《食用农产品市场销售质量安全监督管理办法》，鼓励采用冷链、净菜上市、畜禽产品冷鲜上市等方式销售食用农产品，以保障食用农产品质量安全。' WHERE id = '3e22822c-901f-4df3-b114-2d300d10fcf0';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十四条，禁止生产经营用回收食品作为原料生产的食品。市场滞销产品属于回收食品范畴，不得以此为原料生产新产品。' WHERE id = '3e2cca8a-d7c6-4961-8566-166f858c94f2';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》，食品销售企业应结合实际，细化制定食品安全员守则，明确食品安全员职责。食品安全总监职责由法规直接规定。' WHERE id = '3e2f8565-d6c8-4f1f-ae7f-56b0c0aecb1a';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第二十七条，食品经营者地址迁移的，应当重新申请食品经营许可，不得继续使用原许可证。经营场所发生变化属于许可事项变更。' WHERE id = '3e30f662-dffe-49b5-8d67-089e56b3fefb';
UPDATE public.questions SET analysis = '依据GB 10136-2015《食品安全国家标准 动物性水产制品》，盐渍水产品包括盐渍藻类、盐渍海蜇、盐渍鱼、盐渍海参等，是以食盐腌制为主要加工工艺的水产制品。' WHERE id = '3e348f2e-267f-4cf7-a3ca-d002a6d97309';
UPDATE public.questions SET analysis = '依据GB 2760-2024《食品安全国家标准 食品添加剂使用标准》，冰乙酸（INS260）、氢氧化钠（INS524）、乳酸（INS270）、碳酸钾（INS501ii）均为允许使用的酸度调节剂。' WHERE id = '3e3cbeba-85c7-44bb-a2bc-04f5fc4b1658';
UPDATE public.questions SET analysis = '依据《食品生产经营日常监督检查管理办法》第二条，日常监督检查是指市、县级市场监督管理部门按照年度食品生产经营监督检查计划，对本行政区域内食品生产经营者开展的常规性检查。' WHERE id = '3e4882c6-8feb-4d6a-b47e-a78a49332533';
UPDATE public.questions SET analysis = '依据《食品中可能违法添加的非食用物质和易滥用的食品添加剂名单》（俗称''黑名单''），名单中的物质在食品生产经营环节应坚决杜绝违法添加，违者将承担法律责任。' WHERE id = '3e50405d-f315-4770-8df8-dd43949295ca';
UPDATE public.questions SET analysis = '依据GB/T 30766《茶叶分类》，君山银针属于黄茶类。黄茶的品质特点是''黄叶黄汤''，制作工艺中有''闷黄''工序，与绿茶、白茶有明显区别。' WHERE id = '3e703ef7-8688-473b-a246-72f87212e1c2';
UPDATE public.questions SET analysis = '依据GB 28050《食品安全国家标准 预包装食品营养标签通则》第3.1条，营养标签的标示应当真实、客观，不得虚假，不得夸大产品的营养作用。' WHERE id = '3e86f9db-96b9-4e6a-bda1-ecb3fa19d00c';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第五十八条，注册申请人对不予注册决定有异议的，可以向国家食品药品监督管理总局提出书面行政复议申请或向法院提出行政诉讼。A选项应向总局而非国务院申请复议。' WHERE id = '3e8cb366-168c-4396-8b54-91b4be866e7a';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》（国家市场监督管理总局令第60号），主要要求包括：配备食品安全管理人员、健全企业食品安全责任体系、建立风险防控制度（日管控、周排查、月调度）、明确相应法律责任。' WHERE id = '3e935170-d2ca-4b40-a3e6-b102662f72b2';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十条，食品生产企业采购食品原料、食品添加剂、食品包装材料及用于食品生产的洗涤剂等，均应当查验供货者的许可证和产品合格证明。' WHERE id = '3e9e7880-873a-4050-9d98-2838c581d89f';
UPDATE public.questions SET analysis = '依据GB 14881-2013第5.1.8.3条和《餐饮服务食品安全操作规范》，食品贮存过程中应与墙壁、地面保持适当距离，一般离地不少于10cm、离墙不少于10cm，以利通风防潮。' WHERE id = '3ea3490a-2580-4240-95df-8d21a02f46e7';
UPDATE public.questions SET analysis = '依据GB 2757《食品安全国家标准 蒸馏酒及其配制酒》，氰化物超标的白酒对人体危害极大，可引起呕吐、腹泻、气促等症状，严重时可致死。氰化物限量为8.0mg/L（以木薯为原料）。' WHERE id = '3ea46d36-abd1-47f1-b022-b075bcbd7839';
UPDATE public.questions SET analysis = '依据《食品安全法》第四条，食品生产经营者是食品安全第一责任人，对其生产经营食品的安全负责。政府及监管部门承担监督管理责任，而非生产经营主体责任。' WHERE id = '3ea64d04-dd16-4b9e-9ddd-4310ccad45a9';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十五条和《食品经营许可管理办法》第二条，仅销售预包装食品的，不需要取得食品经营许可，但应依法向所在地县级以上地方市场监督管理部门备案。' WHERE id = '3eaef57d-51ad-4a99-afb2-26bdad6f1789';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十五条和《食品经营许可管理办法》第二条，仅销售预包装食品的，不需要取得食品经营许可，但应依法向所在地县级以上地方市场监督管理部门备案。' WHERE id = '3ec1176b-2dd0-4cd0-b1ed-7853b123ee31';
UPDATE public.questions SET analysis = '依据《食品生产经营监督检查管理办法》和《食品安全抽样检验管理办法》，食品生产经营者要针对不合格食品产生的原因，制定整改措施并限期完成整改，向市场监管部门提交整改报告。' WHERE id = '3ec4a6c2-c1a5-4448-b61f-52f8bde70c3c';
UPDATE public.questions SET analysis = '依据《食品安全抽样检验管理办法》第三十二条，复检备份样品超过保质期的，不予复检。该规定确保复检样品的有效性和代表性。' WHERE id = '3ec60834-0181-4e2f-8d06-f350272ea9e2';
UPDATE public.questions SET analysis = '该题需根据具体选项内容判断。依据《食品安全法》和GB 14881-2013等相关法规标准，正确答案A选项符合食品安全法规要求，其他选项不符合相关规定。' WHERE id = '3ed04c57-39f3-4970-b7c3-577180f03ef6';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第六条，企业主要负责人应支持和保障食品安全总监、食品安全员依法开展工作，在作出涉及食品安全的重大决策前，应充分听取食品安全总监和食品安全员的意见。' WHERE id = '3ef1af5e-c4b9-464c-aee6-6fd44f9ca4e5';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十条和GB 14881-2013第14.1条，食品生产经营企业应当建立进货查验记录制度，如实记录所采购食品原料、食品添加剂、食品相关产品或食品的名称、规格、数量、生产日期、保质期、进货日期及供货者信息。' WHERE id = '3efd5039-0455-4613-8777-1700d0a8bb16';
UPDATE public.questions SET analysis = '依据《食品生产经营监督检查管理办法》第十条，食品生产经营企业应当配合监督检查工作，按要求开放食品生产经营场所，回答相关询问，提供相关合同票据账簿以及前次监督检查结果和整改情况等材料。' WHERE id = '3f09a7a1-b4a9-42de-8ef2-3d75c41ddf08';
UPDATE public.questions SET analysis = '依据《食品安全法》第七十四条，特殊食品包括保健食品、特殊医学用途配方食品和婴幼儿配方食品等。保健食品是特殊食品的重要组成部分。' WHERE id = '3f0b574e-07db-42d1-bf2b-04717a76dae9';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十四条和《食品生产经营企业食品安全管理人员监督抽查考核办法》，食品安全管理人员监督抽查考核结果应当公布。不公布考核结果不符合规定。' WHERE id = '3f18cd40-d426-4914-8bfd-75cdb76d9ab7';
UPDATE public.questions SET analysis = '依据《学校食品安全与营养健康管理规定》第二十三条，引入社会力量承包或委托经营学校食堂的，应以招投标等方式公开选择依法取得食品经营许可、能承担食品安全责任、社会信誉良好的餐饮服务单位或符合条件的餐饮管理单位。' WHERE id = '3f394cd6-7ab5-4024-aa74-1f0cadad3c30';
UPDATE public.questions SET analysis = '依据GB 2761《食品安全国家标准 食品中真菌毒素限量》，霉菌毒素是霉菌产生的有毒代谢产物，如黄曲霉毒素、赭曲霉毒素、展青霉素等，对人体可产生较大危害。' WHERE id = '3f467a6e-9bd7-4b7f-b4b5-f33eb4357e3e';
UPDATE public.questions SET analysis = '依据《食品安全法》和GB 2760《食品安全国家标准 食品添加剂使用标准》，食品添加剂包括天然物质和人工合成物质两类。并非所有食品添加剂都是天然物质。' WHERE id = '3f7460df-67ce-40cd-9742-80880fab4255';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》7.4.3.6.3，烹饪后的易腐食品再加热时，应将食品中心温度迅速加热至70℃以上，以杀灭可能滋生的病原微生物，确保食品安全。' WHERE id = '3f7d825d-eed4-4a91-9b2b-e1bae6033bae';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十四条和GB 14881-2013第12.1条，食品生产企业应建立培训制度，对所有食品加工人员及相关岗位人员进行食品安全培训。B选项''不正确''的具体内容需结合标准判断。' WHERE id = '3f8958e4-9f70-4dd5-8ae8-247de9c8bbb5';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十三条和《保健食品生产经营监督管理办法》，保健食品经营者采购保健食品时，应索取并查验国家有关部门发放的保健食品注册证书或备案凭证及产品合格证明。' WHERE id = '3f908dab-c2ee-4671-ab7a-3cca5fefb523';
UPDATE public.questions SET analysis = '依据GB 14881-2013和《食品生产许可审查细则》，对微生物的控制可设置科学合理的灭菌温度、时间等工艺参数，以杀灭原料、成品和包装材料中的微生物。温度和时间是最核心的灭菌工艺参数。' WHERE id = '3f95360e-96ec-4b56-b396-b470047fcd29';
UPDATE public.questions SET analysis = '依据《食品经营过程卫生规范》和《食品安全法》第五十三条，食品销售企业交接环节应记录一进一出信息，不论物权归属均需记录交接时间、品种、数量等信息，确保追溯链完整。' WHERE id = '3fb30755-cd83-4aa7-9499-22891193d8c3';
UPDATE public.questions SET analysis = '依据GB 14881-2013第7.2.3条，原料贮存条件应符合各类原料特性，防止交叉污染、腐败变质、虫害侵入等情况的发生。' WHERE id = '3fc6f3d8-a07f-43dc-b772-c04db031e594';
UPDATE public.questions SET analysis = '依据《食品安全法》第二十七条和《食品安全国家标准管理办法》，食品安全国家标准分为通用标准、产品标准、生产经营规范标准、检验方法标准、食品相关产品标准等类别。' WHERE id = '3fc7ef64-6d56-4e99-b4f8-cf96e5026ac2';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第三十三条和《食品安全法》第七十八条，保健食品标签应与注册或备案的内容相一致，不一致的不得销售。标签内容必须与注册备案信息严格一致。' WHERE id = '3ffd1481-f1eb-4280-93d1-fb9d97d8cc0c';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》和《学校食品安全与营养健康管理规定》，制售冷食类、生食类、裱花蛋糕、鲜榨果蔬汁等，学校食堂应按要求设置专间或专用操作区，专间应在加工制作前消毒并由专人操作。' WHERE id = '402ec08b-034e-451e-82b9-a4c82bf81383';
UPDATE public.questions SET analysis = '依据《特殊医学用途配方食品注册管理办法》第四十二条，企业依法终止、有效期届满未申请延续、企业主体资格依法终止、法律法规规定应注销的其他情形，总局应依法办理注册注销手续。' WHERE id = '40316a09-cd13-4a82-99a1-32e58a299573';
UPDATE public.questions SET analysis = '依据《食品安全法》第六十三条，食品生产经营企业应当对召回的食品采取无害化处理、销毁等措施，防止其再次流入市场。召回食品不得重新包装后销售。' WHERE id = '4031f6c2-2c35-4491-8672-80b9b7581847';
UPDATE public.questions SET analysis = '依据《食品补充检验方法管理规定》和《食品快速检测方法管理规定》，食品补充检验方法和食品快速检测方法均可在国家市场监督管理总局食品安全抽检监测司网站查询。题目表述错误。' WHERE id = '40373561-6d58-4266-b7d5-4698b0db5e4c';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》和《食品安全法》第五十三条，实行统一配送方式经营的餐饮服务企业，由总部统一进行进货查验记录的，各门店仍应对收货情况进行记录，保存配送清单和合格证明文件。' WHERE id = '404cd28f-977a-40e6-819d-caafd66db215';
UPDATE public.questions SET analysis = '依据GB 14881-2013和《蛋制品生产许可审查细则》，蛋制品生产厂房应合理布局，设置相应的清洁区、准清洁区和一般作业区；应有良好的排水系统和通风设施；不同区域应有效分隔。' WHERE id = '4054c3f3-4132-4b4f-a6fc-d4269f7ce70e';
UPDATE public.questions SET analysis = '依据GB 14881-2013第8.3.2条，对食品添加剂以及清洁剂、消毒剂、润滑剂等明确标示、分类管理、妥善保存，可以有效防范加工过程中带来的化学性危害。' WHERE id = '40696d68-fabf-4387-b293-1e33392950c7';
UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》第九条，每个企业原则上生产婴幼儿配方乳粉不得超过3个配方系列、9个产品配方。该限制旨在防止配方过度开发和虚假宣传。' WHERE id = '4075f1cc-db82-4f38-8cd9-556cc5f968b3';
UPDATE public.questions SET analysis = '依据《食品安全法》第二十五条，食品安全标准是强制执行的标准。除食品安全标准外，不得制定其他食品强制性标准。企业标准可严于食品安全标准，但需备案。' WHERE id = '407a2331-a363-49fb-824b-3202fc5c2c96';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百五十条和《按照传统既是食品又是中药材的物质目录管理规定》，食品包括按照传统既是食品又是中药材的物品（药食同源物质）。' WHERE id = '407feb6b-b35f-4a4f-9694-2e45272d48b9';
UPDATE public.questions SET analysis = '依据《最高人民法院关于审理食品安全民事纠纷案件适用法律若干问题的解释（一）》第十条，经营者经营明知是不符合食品安全标准的食品，向消费者承诺的赔偿标准高于法定赔偿标准的，消费者主张按承诺赔偿的，人民法院应予支持。' WHERE id = '40912620-de3f-43cb-b65d-d4e2850209b5';
UPDATE public.questions SET analysis = '依据GB 14881-2013和《食品生产通用卫生规范》，可采用清洁消毒、加热灭菌、低温贮存、添加防腐剂、建立不利于微生物生存繁殖的环境等措施控制微生物危害。' WHERE id = '4092ecb7-6a8c-41db-81b8-2b66426a89ca';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百三十四条，食品生产企业在一年内累计三次因违反本法规定受到责令停产停业、吊销许可证以外处罚的，由食品安全监督管理部门责令停产停业，直至吊销许可证。' WHERE id = '409fcd18-2fa3-4bb0-9375-b2672a68a022';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十条和第五十一条，食品原料、食品添加剂和食品相关产品进货查验记录、食品出厂检验记录应记录品名、规格、数量、生产日期或批号、保质期、供货者信息、检验结果等内容，并由记录人员签名。不仅仅是签名。' WHERE id = '40ad68b9-d0db-4c7e-93ab-425b9fbe6e33';
UPDATE public.questions SET analysis = '依据《食品中可能违法添加的非食用物质名单》，孔雀石绿为禁用物质，不得在食品中使用。使用孔雀石绿属于违法添加行为，将追究法律责任。' WHERE id = '40b364fd-5919-4df3-9426-9215b00d0aed';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》，调味面制品许可分类为''方便食品''下的''调味面制品''，不属于''其他方便食品''。调味面制品有独立的许可分类。' WHERE id = '40bbdf81-702a-4b56-a2e7-91cf33aecaff';
UPDATE public.questions SET analysis = '依据GB 7718-2011第4.1.2.1条，无国家标准、行业标准或地方标准规定的名称时，应使用不使消费者误解或混淆的常用名称或通俗名称作为食品名称。' WHERE id = '40c59485-3ae9-4c2c-89da-1b0c54d162f9';
UPDATE public.questions SET analysis = '依据《食品安全法》和《食品生产许可管理办法》，食品生产经营者不得委托资质证书不全、超出生产许可证载明的生产范围、不具备相应生产能力的食品生产者生产。受托方必须具备相应资质和能力。' WHERE id = '40ddd320-a1fc-40c4-98b8-e39c09695e5e';
UPDATE public.questions SET analysis = '依据《食品生产经营风险分级管理办法》，食品生产经营者风险等级要根据监督检查、监督抽检、投诉举报、案件查处、产品召回等监督管理记录实施动态调整。风险等级不是一成不变的。' WHERE id = '40ebdb01-d4d7-47c1-ad68-0202a846a55f';
UPDATE public.questions SET analysis = '依据GB 2761《食品安全国家标准 食品中真菌毒素限量》和《白酒生产许可审查细则》，应做好酿酒原料的收购储存，防止霉烂变质，以免带来展青霉素、赭曲霉毒素A等真菌毒素污染。' WHERE id = '40f17b5b-526d-45c0-8b69-4caeeef4e231';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十三条和《食品经营过程卫生规范》，进货查验记录应记录产品名称、规格、数量、生产日期或批号、保质期、进货日期、供货者名称地址联系方式等完整信息。' WHERE id = '411cf860-2fc9-4914-93c7-7859f1b8661f';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十四条，食品生产经营企业应当组织对本企业从业人员进行食品安全知识培训。培训对象包括所有从业人员，而非仅限于管理人员。' WHERE id = '411e22f9-c4ea-4596-9805-85c3f92d0bdf';
UPDATE public.questions SET analysis = '依据GB 10770《食品安全国家标准 婴幼儿罐装辅助食品》，该标准对畜禽肉类、鱼类、蔬菜类罐装辅助食品规定了亚硝酸盐限量要求，部分类别（如水果类）不作亚硝酸盐要求。具体需按产品类别确定。' WHERE id = '412b6bd2-7fe8-429e-a6d3-540cbfec1b44';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》和GB 14881-2013，连锁食品经营企业应当建立健全覆盖从总部到门店的食品安全管理体系，实现全链条食品安全管控。' WHERE id = '4135eab4-6484-41e3-bbc3-e33e4c817475';
UPDATE public.questions SET analysis = '依据《食品安全法》和《野生动物保护法》，食用农产品不包括法律法规禁止食用的野生动物产品及其制品。禁止食用的野生动物及其制品不属于食用农产品范畴。' WHERE id = '4155a70f-c62c-4d0f-be9e-ed49aa893afa';
UPDATE public.questions SET analysis = '依据GB 25191《食品安全国家标准 调制乳》，调制乳是以不低于80%的生牛（羊）乳或复原乳为主要原料，添加其他原料、食品添加剂或营养强化剂，采用适当的杀菌或灭菌等工艺制成的液体产品。' WHERE id = '4159867f-3eb9-4c4f-8c85-04aaabbc6920';
UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》第四十二条，企业依法终止、注册证书有效期届满未申请延续、企业主体资格依法终止、产品连续12个月省级以上抽检3批次以上不合格等情形，不予延续注册。' WHERE id = '41684fc5-28fc-4b0f-819e-41c6309f86c1';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十三条和《食品销售企业食品安全管理规范》，食品销售企业应建立食品进货查验记录制度，明确查验内容、记录方式、保存要求、责任分工等主要内容并认真执行。' WHERE id = '417527d9-1799-4b55-83ad-d59e5b54a495';
UPDATE public.questions SET analysis = '依据《食品经营过程卫生规范》和《食品安全法实施条例》第二十五条，委托贮存食品的，应建立贮存服务提供者档案，记录贮存服务提供者的名称地址联系方式、资质证明、贮存条件等信息。' WHERE id = '418c8ff8-40f4-4151-a965-c8dd6d9ceecd';
UPDATE public.questions SET analysis = '依据《食品安全法》第四条，食品生产经营者是食品安全第一责任人，对其销售的食品安全负责。经营者而非监管部门承担食品安全主体责任。' WHERE id = '419103e4-e405-4281-9a10-46b1b554a9f8';
UPDATE public.questions SET analysis = '依据《食用农产品市场销售质量安全监督管理办法》第十五条，销售者销售食用农产品，应在销售场所明显位置或带包装产品的包装上如实标明产品名称、产地、生产者或销售者名称等信息。' WHERE id = '419e88e0-7976-414e-bbe1-27bc0292bcbc';
UPDATE public.questions SET analysis = '依据《食品安全法》第二十五条，食品安全标准是强制执行的标准。除食品安全标准外，不得制定其他食品强制性标准。食品安全标准具有强制约束力。' WHERE id = '41a12461-9c9a-4d7f-a21c-f72e6f8405a9';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十条和第五十三条，食品生产经营企业进货查验记录和凭证保存期限不得少于产品保质期满后六个月；没有明确保质期的，保存期限不得少于二年。' WHERE id = '41b7b185-5a3b-4837-a65a-54d1ca0515c1';
UPDATE public.questions SET analysis = '依据《学校食品安全与营养健康管理规定》第十二条，学校食品安全实行校长（园长）负责制，而非师生家长负责制。校长是学校食品安全的第一责任人。' WHERE id = '41b90d07-7f85-4ab5-9f1c-3f7b20ca91e6';
UPDATE public.questions SET analysis = '依据GB 10765《食品安全国家标准 婴儿配方食品》，该标准对婴儿配方食品中蛋白质、脂肪、碳水化合物、维生素、矿物质等营养成分的含量均有明确规定。某些非必需成分如部分可选择成分不作特别含量规定。' WHERE id = '41ba2fbe-145d-4384-9039-aa0770ee6e53';
UPDATE public.questions SET analysis = '依据GB 14881-2013第3.3条，食糖生产企业厂区应合理布局，应有适当的排水系统，生活区应与生产区保持适当距离或分隔。A选项''空地不得铺设草坪''错误，适当绿化是可以的。' WHERE id = '41f11059-f56c-4046-aa11-941b89a9637e';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十五条和《公共场所卫生管理条例》，从事接触直接入口食品工作的食品生产经营人员应取得健康证明，健康证明应在有效期内且人证相一致。' WHERE id = '41feb567-4645-4728-99d0-3e3cdb4ce956';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十条，食品生产企业可以制定严于食品安全国家标准或地方标准的企业标准，但应符合法律法规和强制性标准的规定，在本企业适用并报省级卫生行政部门备案。' WHERE id = '42018118-599c-4305-9a53-2f4471d594ad';
UPDATE public.questions SET analysis = '依据《食品安全法》第二十八条和《食品安全国家标准管理办法》，食品安全国家标准在发布前，其草案应当向社会公开征求意见。不向社会公开不符合规定。' WHERE id = '420b3bda-75a0-44c6-b2cf-563a1233a473';
UPDATE public.questions SET analysis = '依据GB 2720-2015《味精》，加盐味精是指在谷氨酸钠（味精）中，定量添加了精制盐的均匀混合物，该定义正确。' WHERE id = '42125e6d-da10-43d8-acc9-63440e510e20';
UPDATE public.questions SET analysis = '答案：A,B,C。依据《动物防疫法》第四十三条、《生猪屠宰管理条例》第十三条，销售猪肉须提供动物检疫合格证明、肉品品质检验合格证明及非洲猪瘟检测报告，确保肉品安全可追溯。价格证明非食品安全必备文件。' WHERE id = '421c91fa-7e6a-4a95-beda-a6b2518aef4a';
UPDATE public.questions SET analysis = '答案：A,C。依据GB/T 27320-2010《食品防护计划及其应用指南》，企业应严格原料、产品配方管理和加工环节监控，防范人为故意污染，保障食品安全。' WHERE id = '421c9f54-2c57-4a8f-a567-0cd70961f63b';
UPDATE public.questions SET analysis = '依据《食品召回管理办法》第二十五条，对违法添加、腐败变质等严重危害健康的不安全食品，应立即就地销毁。' WHERE id = '4232a78c-9a51-489d-8c05-eede9b9d2b1c';
UPDATE public.questions SET analysis = '答案：D。依据《食用农产品市场销售质量安全监督管理办法》，批发市场开办者应建立入场销售者档案并查验合格证明。' WHERE id = '4240ec4a-2200-46ef-8be0-8ffcebf39e1e';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十三条及GB 14881-2013，食品贮存运输需符合温度要求，冷冻食品应及时加工使用以保证食品安全。' WHERE id = '427119cc-e757-44ba-b91b-1c537933fb30';
UPDATE public.questions SET analysis = '答案：A,B,D。依据《蜜饯生产许可审查细则》，蜜饯生产工艺包括原料处理、糖（盐）制、干燥、修整、包装。油炸不属于蜜饯常规工艺。' WHERE id = '42802e04-8bd7-42bf-9572-0ef03cb3edc6';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十七条，有发生食品安全事故潜在风险的，应立即停止生产经营活动并报告所在地县级人民政府食品安全监督管理部门。' WHERE id = '42940a21-8307-4116-aab7-a7995562bff4';
UPDATE public.questions SET analysis = '答案：B,C,D。依据GB 7718-2011第4.3.1条，食醋、食用盐、味精、固态食糖类食品因本身特性可免除标示保质期。啤酒需标示保质期，不在豁免之列。' WHERE id = '42a3ce8b-941b-49e7-81fd-6354f9435ce9';
UPDATE public.questions SET analysis = '答案：A,B,C,D。依据《食品安全法》第六十八条及GB 31621-2014，散装食品容器外包装应标明食品名称、生产日期或批号、保质期、生产经营者名称等内容。' WHERE id = '42b5bbb0-30aa-47f9-9e36-0e4b7062dd3c';
UPDATE public.questions SET analysis = '答案：A,C。依据《企业落实食品安全主体责任监督管理规定》，企业主要负责人应支持和保障食品安全总监、食品安全员依法履职，重大决策前应充分听取意见。' WHERE id = '42c21fc3-133a-49b4-87be-c55da8c91fd7';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十条及GB 2760，食品添加剂应安全、无害，不得用于掺杂掺假，标签应注明''零售''。' WHERE id = '42c24071-d7cd-4525-84d5-b64b53da538e';
UPDATE public.questions SET analysis = '答案：D。依据《食品安全法》及相关法规、标准规定，该选项正确。食品生产经营者应严格遵守法律法规和标准要求，确保食品安全。' WHERE id = '42da2e7f-a850-4362-9304-a541967ae1e7';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十条及GB 14881-2013，食品生产者采购原料应查验许可证和合格证明，确保原料安全。' WHERE id = '42ed5921-7d8c-4305-9a03-8d9c53cc28c0';
UPDATE public.questions SET analysis = '答案：B。依据GB 29921-2021《预包装食品中致病菌限量》，蜜饯作为即食果蔬制品，其致病菌限量应符合该标准规定。' WHERE id = '42f83887-10a7-4091-bbbd-9e903f22bce1';
UPDATE public.questions SET analysis = '依据《食品安全法》及相关法规规定，该表述正确。食品生产经营者应严格遵守法律法规和标准要求，确保食品安全。' WHERE id = '4310f340-4e51-4e95-bd3a-0935d5f61926';
UPDATE public.questions SET analysis = '答案：A。依据《食品安全法》及相关法规、标准规定，该选项正确。食品生产经营者应严格遵守法律法规和标准要求，确保食品安全。' WHERE id = '431d1459-2969-4e09-9741-3187b86a6a74';
UPDATE public.questions SET analysis = '答案：A。依据GB 19295-2021《速冻面米与调制食品》及GB 14881-2013，速冻食品是采用速冻工艺生产，在冷链条件下进入销售市场的食品。速冻与冷冻概念不同。' WHERE id = '43254301-9c24-45a2-9cb8-2eb2ee060cf5';
UPDATE public.questions SET analysis = '答案：C。依据《食品安全法》及相关法规、标准规定，该选项正确。食品生产经营者应严格遵守法律法规和标准要求，确保食品安全。' WHERE id = '432a05bb-a06c-4c23-97ec-bee4e71f53f0';
UPDATE public.questions SET analysis = '答案：C。依据《食品安全法》及相关法规、标准规定，该选项正确。食品生产经营者应严格遵守法律法规和标准要求，确保食品安全。' WHERE id = '43328c80-9d7b-4855-beb7-d0856c90d892';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》第五十条，以欺骗、贿赂等不正当手段取得许可的，原发证部门应撤销许可并处1-3万元罚款。' WHERE id = '433d6ca9-7aa5-4beb-a2cd-702fd7da344c';
UPDATE public.questions SET analysis = '答案：A,B,C,D。依据《食品安全法》第三十三条，食品生产经营者应具有相适应的场所设备、专职或兼职管理人员、保证食品安全的规章制度及合理布局工艺流程。' WHERE id = '435ef9fa-8646-4cbd-9b98-efb743fd1869';
UPDATE public.questions SET analysis = '答案：C。依据GB 2762-2017《食品中污染物限量》，重金属镉属于化学性危害因素，稻谷中镉超标为化学性污染。' WHERE id = '437ae465-a444-4bde-9ac6-4c383e3c1c4a';
UPDATE public.questions SET analysis = '答案：A,B,C,D。依据《食品安全法》及相关法规标准规定，上述选项均为正确内容。食品生产经营者应严格遵守法律法规要求，确保食品安全。' WHERE id = '437f6155-7380-4d83-992d-37006fa0d52a';
UPDATE public.questions SET analysis = '答案：C。依据《食品安全法》第五十四条，食品经营者应按照保证食品安全的要求贮存食品，遵循先进先出原则。' WHERE id = '438ca5c8-8863-4f8c-b178-067d531b5a25';
