UPDATE public.questions SET analysis = '依据《餐饮服务通用卫生规范》（GB 31654-2021），餐饮服务提供者应建立并不断完善原料控制、食品安全自查、进货查验和记录、食品留样、场所及设施设备清洁消毒和维修保养等方面的食品安全管理制度。' WHERE id = '4eba6ef9-423a-47d6-8a5f-fb7a94b47a55';
UPDATE public.questions SET analysis = '依据《餐饮服务通用卫生规范》（GB 31654-2021），专间和专用操作区的工作服应与其他区域工作服在外观上有明显区分，以防止交叉污染，保障食品安全。' WHERE id = '4ec2fa60-3163-4a27-b6a6-3e7fde7549e3';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品中污染物限量》（GB 2762-2022），白酒中铅的限量值为0.5mg/L（以Pb计）。该限量是保障消费者健康的重要指标。' WHERE id = '4ec5ca4b-6abd-4ae5-8f18-3c32b3d88eeb';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 包装饮用水》（GB 19298-2014），微生物限量指标包括大肠菌群和铜绿假单胞菌。该标准取消了菌落总数指标，金黄色葡萄球菌和沙门氏菌不是该标准规定的指标。' WHERE id = '4ec5f131-7a4c-4593-a451-4a0a5a6ecd7f';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品添加剂使用标准》（GB 2760）及口香糖生产工艺要求，胶基的主要成分包括天然橡胶、树脂、乳化剂和软化剂等，赋予口香糖咀嚼性和弹性。' WHERE id = '4ec97c84-6b0a-4ce7-81dc-2a9bb3e8fc20';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品添加剂使用标准》（GB 2760），二氧化硫及其盐类可作为漂白剂和防腐剂使用。若超量使用含二氧化硫物质处理水果，会导致终产品中二氧化硫残留超标，违反食品安全标准。' WHERE id = '4edf56d8-a208-4a38-9be5-e425e6b06b6d';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百二十条及第一百四十一条，任何单位和个人不得编造、散布虚假食品安全信息。食品广告内容应当真实合法，不得含有虚假内容。' WHERE id = '4eee889d-fb92-4c67-955d-dca0c60684fb';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 预包装食品标签通则》（GB 7718）第3章基本要求，预包装食品标签应清晰醒目持久、通俗易懂准确、不得虚假误导消费者、不得暗示性混淆产品。四项描述均为标准要求。' WHERE id = '4efa2b60-3998-4493-88ca-0fc9b430eb06';
UPDATE public.questions SET analysis = '依据《食品安全法》第三条，食品安全工作实行预防为主、风险管理、全程控制、社会共治的原则。"过程控制"不属于法定四个基本原则，正确表述应为"全程控制"。' WHERE id = '4efd89ca-e415-4630-b67e-1d36394af26b';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十条，国家鼓励食品生产企业制定严于食品安全国家标准或者地方标准的企业标准，在本企业适用，并报省、自治区、直辖市人民政府卫生行政部门备案。' WHERE id = '4f028b6d-36e2-4983-aaf6-5369d1fa13fe';
UPDATE public.questions SET analysis = '依据《食品安全法实施条例》第三十六条，医疗机构、药品零售企业销售特定全营养配方食品的，不需要取得食品经营许可，但应当遵守食品安全法和本条例关于食品销售的规定。' WHERE id = '4f04676d-8c40-4ccd-93e7-34935782eb02';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品添加剂使用标准》（GB 2760），食品生产企业在设计配方时，应明确产品在GB 2760中的食品类别定位，据此确定允许使用的食品添加剂品种和最大使用量。' WHERE id = '4f16e233-2c69-4228-af89-c6d4a0b37832';
UPDATE public.questions SET analysis = '依据《食品生产经营监督检查管理办法》第三条，飞行检查是指市场监督管理部门根据监督管理工作需要以及问题线索等，对食品生产经营者依法开展的不预先告知的监督检查。' WHERE id = '4f2246c9-fc71-4846-a2b0-bf15cddd9957';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十八条，生产经营的食品中不得添加药品，但是可以添加按照传统既是食品又是中药材的物质。食品添加剂在GB 2760允许范围内可以使用。' WHERE id = '4f305b91-7757-4da7-92f6-0f5ef6491444';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第六条，县级以上地方食品药品监督管理部门负责本行政区域内的食品经营许可管理工作，而非"县级以下"。' WHERE id = '4f413376-62c3-4ea9-99ac-e5c4e3dc4b3d';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十四条及《企业落实食品安全主体责任监督管理规定》，食品生产经营企业"应当"建立健全食品安全管理制度，而非"根据需要"建立，这是法定义务。' WHERE id = '4f5adf79-5700-45e0-91a8-18c7236607bc';
UPDATE public.questions SET analysis = '依据《学校食品安全与营养健康管理规定》第二十五条，学校食堂从业人员不得在食堂内吸烟，应保持良好的个人卫生习惯，防止食品污染。' WHERE id = '4f5c2880-eda4-45e9-b24b-3703b40d119d';
UPDATE public.questions SET analysis = '依据《食品安全法实施条例》第三十九条及特殊食品经营管理规定，普通食品、特殊食品、药品不得混放销售，应有明显隔离标识或保持一定距离摆放，防止误导消费者。' WHERE id = '4f5c6cc2-ef97-4c1c-a551-4772442f010c';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十五条，从事接触直接入口食品工作的食品生产经营人员应当每年进行健康检查，取得健康证明后方可上岗工作。' WHERE id = '4f7a10f6-d369-4d41-b868-e6dfcc3b4caa';
UPDATE public.questions SET analysis = '肉毒梭菌主要存在于土壤和水中，不属于水产品自身细菌；霍乱弧菌是肠道致病菌，也不是水产品自身固有细菌。水产品常见细菌包括弧菌属某些种和沙门氏菌等。' WHERE id = '4f83278b-b5ac-486d-8fe1-bdc49d7600ea';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013），不得使用非食品级润滑油接触食品。设备上直接接触食品的活动部件必须使用食品级润滑油润滑，即使是应急情况也不得例外。' WHERE id = '4f99d7a3-ec86-4b9d-9300-212ed1337491';
UPDATE public.questions SET analysis = '依据食品经营过程管理规范，食品交接记录应根据物权归属确定记录义务。不是所有交接环节的一进一出都需记录保质期和温度信息，仅对归属本企业物权的食品负有记录义务。' WHERE id = '4f9e9d86-994b-4cc6-b9cc-7d85aa9df1e8';
UPDATE public.questions SET analysis = '饼干主要原料包括面粉、乳、蛋等。面粉可能受铅镉等重金属和真菌毒素污染，乳和蛋可能存在抗生素超标风险。四项均为饼干原料中常见的食品安全风险因素。' WHERE id = '4fa00610-c3aa-4259-b398-2a4df030ff6d';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百五十条，食品保质期是指在标明的贮存条件下保持品质的期限。该定义明确了保质期与贮存条件的关联性。' WHERE id = '4fd9f255-80b1-4ccf-8ef8-aa51629ee722';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十三条及《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013），贮存、运输和装卸食品的容器、工器具和设备应当安全无害、保持清洁。' WHERE id = '5002fe14-d2f0-498f-bef9-29a81bea3b67';
UPDATE public.questions SET analysis = '依据《罐头食品生产许可审查细则》及GB 7098，罐头食品是以水果、蔬菜、食用菌、畜禽肉、水产动物等为原料，经加工处理、装罐、密封、加热杀菌等工序加工而成的产品。' WHERE id = '5009ff1c-0f67-4074-9fe1-87d5cd48abbf';
UPDATE public.questions SET analysis = '依据《餐饮服务通用卫生规范》（GB 31654-2021）4.2.3，需经常冲洗的场所应铺设1.5m以上、浅色、不吸水、易清洗的墙裙，以防止墙面污染。' WHERE id = '5028f87a-20ed-44f0-8d49-047be85a4788';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》及《企业落实食品安全主体责任监督管理规定》，餐饮服务管理企业应具备与规模相适应的人员和食品安全管理能力，配备专职食品安全管理人员，建立统一的管理制度。' WHERE id = '5032dd3e-fd81-4245-af29-cef624ac2c43';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 预包装食品营养标签通则》（GB 28050-2011）2.7，营养声称包括含量声称和比较声称两类。功能声称属于营养成分功能声称，不属于营养声称。' WHERE id = '50359dd8-8892-4187-a57b-cfc3a0b3e38f';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第十四条，企业及其主要负责人无正当理由未采纳食品安全总监、食品安全员依法提出的否决建议的，属于故意实施违法行为的情形；已履职尽责的食品安全管理人员不予处罚。' WHERE id = '503925d2-39de-43d9-9e28-69f63723acb0';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）5.1.1.2，食品加工用水的水质应符合GB 5749《生活饮用水卫生标准》的规定。' WHERE id = '503be41a-cccf-4ed6-b1e2-442bc2311b48';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 预包装食品标签通则》（GB 7718）2.2，食品标签包括食品包装上的文字、图形、符号及一切说明物。' WHERE id = '504307e4-3ffd-4840-9004-b41e092e4d33';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 预包装食品营养标签通则》（GB 28050-2011）2.6，NRV（Nutrient Reference Values）是营养素参考值的英文缩写，用于比较食品营养成分含量的参考标准。' WHERE id = '50476531-dfb5-4334-9243-3b8dfbdfebed';
UPDATE public.questions SET analysis = '依据《市场监督管理严重违法失信名单管理办法》第九条，对违反法律法规、性质恶劣、情节严重、社会危害较大的食品生产经营企业，应列入严重违法失信名单。' WHERE id = '504d0fba-99c7-415c-ad4d-7c56543f22f3';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十七条，食品生产经营者应当建立食品安全自查制度，定期对食品安全状况进行检查评价。自查发现经营条件不再符合食品安全要求的，应立即采取整改措施。' WHERE id = '505c3172-a6b0-4c0f-a40c-528cf579a0e2';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十九条，国家对食品添加剂生产实行许可制度，但对食品添加剂经营不实行许可制度，仅要求经营者建立进货查验记录制度。' WHERE id = '50720029-1755-48d1-bde2-0d657a0e9056';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 蒸馏酒及其配制酒》（GB 2757）及《饮料酒术语和分类》（GB/T 17204），发酵酒是以粮谷、水果、乳类等为主要原料，经发酵或部分发酵酿制而成的饮料酒。' WHERE id = '507e3345-b05f-42a7-bf20-129a317eb6f5';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百一十一条及《食品安全法实施条例》第六十三条，对可能掺杂掺假的食品，现有标准方法无法检验的，国务院食品安全监督管理部门可以制定补充检验项目和检验方法。' WHERE id = '508b7465-b35d-4baf-a614-55af885edf8c';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 发酵乳》（GB 19302-2010），发酵乳按照生产工艺分为凝固型发酵乳和搅拌型发酵乳两种类型。' WHERE id = '5098a39c-e207-40e1-abfa-82920a0d7b12';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百四十八条，消费者因不符合食品安全标准的食品受到损害的，可以向经营者要求赔偿损失，接到赔偿要求的生产经营者应实行首负责任制，先行赔付，不得推诿。' WHERE id = '509994ba-aecf-4331-bc3a-c9257df4b9fc';
UPDATE public.questions SET analysis = '依据《食品召回管理办法》第十四条，知悉食品生产者召回不安全食品的，食品经营者应在经营场所醒目位置张贴召回公告，配合食品生产者开展召回工作。' WHERE id = '509cc280-29ef-42de-bf64-93d1f8702eea';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十三条，食品生产企业应具有与生产的食品品种、数量相适应的生产设备或设施，以及相应的消毒、更衣、盥洗、采光、照明、通风、防腐、防尘、防蝇、防鼠、防虫、洗涤以及处理废水、存放垃圾和废弃物的设备或设施。' WHERE id = '509d0d3e-7745-428e-9710-f6f77905ebbc';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）及HACCP原理，企业对微生物危害可采用清洁消毒、加热灭菌、低温贮存、添加防腐剂、控制环境条件等措施，也可从源头控制降低风险。' WHERE id = '50a27a35-9125-4f13-bc5e-ba087951fee6';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十三条、第四十四条，食品生产经营企业"应当"配备食品安全管理人员，而非"可以"配备。这是法律强制性义务。' WHERE id = '50a9786f-2916-4e58-b837-e8aa809ec2ab';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百五十条，食品保质期是指食品在标明的贮存条件下保持品质的期限。该法律定义强调了保质期与贮存条件的关联性。' WHERE id = '50aa6f8d-4739-4321-a776-7fc704d4810e';
UPDATE public.questions SET analysis = '依据《电子商务法》第十二条，电子商务经营者从事经营活动，依法需要取得相关行政许可的，应当依法取得行政许可。食品网络销售需遵守此规定。' WHERE id = '50ce620d-10f3-4a44-8f70-cb6fe17ce4ed';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百三十五条及《企业落实食品安全主体责任监督管理规定》第六条，因食品安全犯罪被判处有期徒刑以上刑罚的人员，终身不得担任食品安全总监、食品安全员。' WHERE id = '50e57b91-faaa-41a0-b8b0-2ab84f049e07';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十五条，仅销售预包装食品的，应当报所在地县级以上地方人民政府食品安全监督管理部门备案，不需要取得食品经营许可。' WHERE id = '5103043e-2d34-4c03-b4c2-266e5c904f6e';
UPDATE public.questions SET analysis = '依据《酱油生产许可审查细则》，酱油生产企业应具备与生产能力相适应的厂房、原辅材料仓库、成品仓库和实验室，生产用厂房应能满足原料处理、种曲、制曲、发酵、淋油、调配、灭菌和灌装（包装）的工艺要求。' WHERE id = '511e132d-19c0-4ae8-bf58-4a730a145852';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》第二十七条，食品生产许可证分为正本、副本，正本、副本具有同等法律效力。' WHERE id = '5127e49e-b0dc-48ca-9767-6f50b86113db';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十三条及《食用农产品市场销售质量安全监督管理办法》，有关部门出具的食用农产品质量安全合格证明或销售者自检合格证明等可以作为合格证明文件。' WHERE id = '513798f6-a54f-4af0-b91a-3fbe15d5fb55';
UPDATE public.questions SET analysis = '依据《食品安全法》第十七条，国家建立食品安全风险评估制度，运用科学方法对食品、食品添加剂、食品相关产品中生物性、化学性和物理性危害因素进行风险评估。' WHERE id = '513be824-d666-4958-a878-9b686273d801';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）7.5，食品原料、食品添加剂和食品包装材料等进入生产区域时应有一定的缓冲区域或外包装清洁措施，以降低污染风险。' WHERE id = '513ff103-bf55-4f92-9db2-d7ffbe27074b';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 冷冻饮品和制作料》（GB 2759-2015），冷冻饮品中铅的限量为≤0.3mg/kg（以Pb计），而非1.0mg/kg。' WHERE id = '51403f56-f38e-450f-9433-ce16de19c8e8';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十三条，食品生产经营者申请许可应具备合理的设备布局和工艺流程，防止交叉污染，避免食品接触有毒物、不洁物，以及具备法律法规规定的其他条件。' WHERE id = '5148da18-8c9d-40b1-a267-a52d48d1365e';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第十八条，监督抽查考核不合格的食品安全管理人员，不再符合食品生产经营要求的，企业应当立即采取整改措施。' WHERE id = '5164fb99-305e-4354-89d8-53b57a20f022';
UPDATE public.questions SET analysis = '依据《食用农产品市场销售质量安全监督管理办法》第二十条，实行统一配送销售方式的食用农产品销售企业，可以由企业总部统一建立进货查验记录制度。' WHERE id = '516a6cda-735f-4615-9122-bcfdc855b141';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 豆制品》（GB 2712-2014），豆制品是以大豆或杂豆为主要原料，经加工制成的食品，包括发酵豆制品、非发酵豆制品和大豆蛋白类制品。' WHERE id = '516fc00d-642e-44c2-b5bc-400bdcd1c508';
UPDATE public.questions SET analysis = '依据《食盐专营办法》第十六条，食盐零售单位应当从食盐定点批发企业购进食盐，确保食盐来源可追溯。' WHERE id = '5188979c-23c1-45a4-be3c-9d7dede9225e';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 蒸馏酒及其配制酒》（GB 2757-2012），啤酒中甲醛限量标准为≤2.0mg/L，而非0.20mg/L。' WHERE id = '51999732-2fb0-4908-8332-30c95dbb993e';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十条，食品生产者采购食品原料，应当依照《食品安全法》的规定查验供货者的许可证和产品合格证明。' WHERE id = '51a0d76f-4d40-40d9-8987-0eec5d69d59b';
UPDATE public.questions SET analysis = '依据《食品安全抽样检验管理办法》，食品抽样检验是食品安全监管的重要手段，对推动落实食品安全"两个责任"、排查风险、提升食品质量安全水平具有重要作用。' WHERE id = '51bdc37e-8adf-4905-937e-0c8dc75f935f';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》及《食品安全法》第五十三条，实行统一配送的餐饮服务企业，总部统一进行进货查验记录的，各门店仍应对收货情况进行记录，确保全程可追溯。' WHERE id = '51ca1066-4b1c-449c-8fa1-da9f0feb9f48';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第二十七条，食品经营许可证日常监督管理人员发生变化的，可以通过签章的方式在许可证上变更。' WHERE id = '51edec0a-7cd1-4628-b1b7-88aec5068d93';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第二十六条，食品经营者应当在经营场所显著位置悬挂、摆放纸质食品经营许可证正本或展示其电子证书。' WHERE id = '5206df97-afb8-49b6-89e0-f6915f2e32e8';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十条，食品生产企业应当对食品原料、食品添加剂、食品相关产品和食品进行进货查验，并留存记录，确保来源可追溯。' WHERE id = '520d1d39-3da3-43f6-8d74-6019415ad418';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十五条，从事接触直接入口食品工作的人员应每年进行一次健康检查，取得健康证明后方可上岗。' WHERE id = '520f2a20-1028-4249-ad02-3276ea4a4135';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第四十三条，保健食品审评机构应组织审评申请材料，并根据科学依据的充足程度明确产品保健功能声称的限定用语。' WHERE id = '5232de36-8bcd-4e73-8a9c-eaf46df25939';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品中真菌毒素限量》（GB 2761-2017），小麦粉中脱氧雪腐镰刀菌烯醇（DON）的限量要求为≤1000μg/kg。' WHERE id = '523c9466-eb0f-480d-af24-807154379793';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013），对于内包装材料使用的清洁消毒方法，食品生产企业应验证其效果，确保消毒有效性。选项A所述"不必验证"是错误的。' WHERE id = '5242bb5c-fc5b-462a-a063-65e83880e609';
UPDATE public.questions SET analysis = '依据《白酒工业术语》（GB/T 15109-2021）及《饮料酒术语和分类》（GB/T 17204），白酒包括固态法白酒、液态法白酒和固液法白酒。调香白酒属于配制酒，不属于白酒。' WHERE id = '525c64fc-ffce-41f8-b55b-7e21dee02beb';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）4.1.3，清洁作业区的对外出入口可装设能自动关闭的门，以防止外部污染物进入。' WHERE id = '525fb233-2783-44de-bd5e-51dc49dd7088';
UPDATE public.questions SET analysis = '依据《食品安全法》第二十七条，食品中农药残留、兽药残留的限量规定及其检验方法与规程由国务院卫生行政部门、国务院农业行政部门会同国务院食品安全监督管理部门制定。' WHERE id = '526360f9-0205-47f3-b613-3a2ab1c03d72';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）4.2.3，车间隔墙与地面连接处应呈弧形，而非直角，以防止污垢积聚，便于清洁。' WHERE id = '527bfed5-6675-421e-8bec-7d2967caa5c3';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十七条，食品生产经营者应当建立食品安全自查制度，定期对食品安全状况进行检查评价，这是法定义务。' WHERE id = '528abd1b-eda7-4e31-b169-861dfbe83e86';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百三十五条，因食品安全犯罪被判处有期徒刑以上刑罚的人员，终身不得担任食品安全总监、食品安全员，也不得从事食品生产经营管理工作。' WHERE id = '528bdd83-ee70-4b30-92ab-f9fb8d8283ef';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食糖》（GB 13104-2014），绵白糖是以甜菜或甘蔗为原料，经提取糖汁、清净处理、煮炼结晶、离心分蜜等工艺制成的晶粒细小、颜色洁白、质地绵软的糖。' WHERE id = '52908451-a815-4c03-8e9a-830ba0410892';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百五十条，食品安全是指食品无毒、无害，符合应当有的营养要求，对人体健康不造成任何急性、亚急性或者慢性危害。' WHERE id = '529b8c96-c493-4b01-99be-622aaa5d7fd6';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十条及相关规定，食品生产企业对报备的企业标准负责，是企业标准的第一责任人，应确保企业标准严于食品安全国家标准或地方标准。' WHERE id = '52d215ce-817d-4701-b22a-38edac104f3d';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 婴幼儿谷类辅助食品》（GB 10769-2010），婴幼儿谷类辅助食品中不得添加蜂蜜。蜂蜜可能含有肉毒梭菌芽孢，对婴幼儿存在安全风险。' WHERE id = '52d68b7a-b10a-4004-a921-782bc3f282ca';
UPDATE public.questions SET analysis = '依据《食品安全法》第八十七条，市场监督管理部门进行抽样检验应当购买抽取的样品，并不得向食品生产经营者收取检验费和其他费用，所需费用由财政列支。' WHERE id = '52de9dfb-c6b1-45da-8bf8-714110c69b74';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十三条，从事食品生产活动应当具备更衣、盥洗、采光、照明、处理废水、存放垃圾和废弃物、防蝇、防鼠、防虫等设备设施。' WHERE id = '52e7c67f-d43a-407c-b6ee-d091f55f5792';
UPDATE public.questions SET analysis = '过氧乙酸熏蒸属于化学杀菌方法，利用化学消毒剂杀灭微生物。流通蒸汽、巴氏低温消毒和湿热灭菌均属于利用热能杀灭微生物的物理杀菌方法。' WHERE id = '5311a4fc-d50f-4438-bc6a-c95ac1d85af1';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第四十七条，保健食品受让方除提交规定的注册申请材料外，还应当提交经公证的转让合同，以确保转让行为的真实性和合法性。' WHERE id = '53196ad7-024a-4a70-9d6f-3bc52f26161d';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第六条，国家食品药品监督管理总局行政受理机构负责受理保健食品注册和接收相关进口保健食品备案材料。' WHERE id = '5330d3b8-ea59-4a90-8a45-5ef9baf7c906';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百三十五条，被吊销许可证的食品生产企业及其法定代表人、直接负责的主管人员和其他直接责任人员，自处罚决定作出之日起五年内不得从事食品生产管理工作。2017年被吊销，2020年不满五年。' WHERE id = '53387ab5-abe6-48ce-bd9e-e01fb1b402c5';
UPDATE public.questions SET analysis = '依据《食品安全抽样检验管理办法》第十五条，监督抽检中的样品分为检验样品和复检备份样品，分别用于检验和复检，以保障被抽检单位的复检权利。' WHERE id = '535ab2f7-ef1a-4e75-a1c4-a858983e21bd';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 包装饮用水》（GB 19298-2014），包装饮用水中余氯（游离氯）应控制在≤0.05mg/L。' WHERE id = '5372c5d3-2124-4d37-bbb9-77ba637be070';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百一十四条，食品生产过程中存在食品安全隐患，未及时采取措施消除的，县级以上人民政府食品安全监督管理部门可以对食品生产企业的法定代表人或主要负责人进行责任约谈。' WHERE id = '5375a68e-4002-47c9-ab4c-292ab68b41a2';
UPDATE public.questions SET analysis = '依据《食品安全法》第六十二条，网络食品交易第三方平台提供者应当对入网食品经营者进行实名登记，明确其食品安全管理责任。' WHERE id = '53884ca1-f05e-4e18-a267-9d1f37de0648';
UPDATE public.questions SET analysis = '依据食品安全风险评估数据，已知鱼体和贝类中有50多种寄生虫会引起人类疾病，包括异尖线虫、华支睾吸虫等，有些会造成严重的健康危害。充分加热是预防措施。' WHERE id = '538ae1c3-d247-43f1-b63d-130d01378267';
UPDATE public.questions SET analysis = '依据《电子商务法》第十二条，电子商务经营者从事经营活动，依法需要取得相关行政许可的，应当依法取得行政许可。食品网络经营者需遵守此规定。' WHERE id = '53986a39-fa36-4100-9e82-976cead82d14';
UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》第二十三条，婴幼儿配方乳粉产品配方注册证书有效期为5年。' WHERE id = '53a4bf26-748d-4a8d-94f9-a6e1ea84a8fd';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百三十四条，食品生产企业在一年内累计三次因违反食品安全法规定受到责令停产停业、吊销许可证以外处罚的，由食品安全监督管理部门责令停产停业，直至吊销许可证。' WHERE id = '53aaa7fa-cfa3-4d42-ade0-26cacc012110';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第三条，企业主要负责人对本企业食品安全工作全面负责，承担食品安全第一责任人职责。' WHERE id = '53af98bb-8070-4167-a728-78d6db179483';
UPDATE public.questions SET analysis = '依据GB 2760及水果保鲜技术规范，原料水果为防腐、保鲜，常在贮存和储运过程中使用含有二氧化硫的化学物质处理，加工环节则按生产需要控制使用。' WHERE id = '53c03b28-2b3e-4ced-a6b5-8e5b09913d65';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》及餐饮服务许可审查规范，餐饮服务包括热食类、冷食类、生食类、半成品和自制饮品制售等，其中半成品制售仅限中央厨房申请。' WHERE id = '53c14451-7229-46ff-a7b8-4e28225c2923';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十六条，食品生产企业应当就原料采购、原料验收、投料等原料控制，生产工序、设备、贮存、包装等关键环节控制，检验控制以及运输和交付控制事项制定并实施控制要求。' WHERE id = '53cf743d-8e01-48ad-b23e-f093975477f2';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百三十五条，因食品安全犯罪被判处有期徒刑以上刑罚的人员，终身不得从事食品生产经营管理工作，也不得担任食品生产经营企业食品安全管理人员。' WHERE id = '53cfaaf9-bf32-4cf3-9b0c-63fc1a0f47dc';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第二十七条，食品经营许可证载明的许可事项发生变化的，食品经营者应当在变化后10个工作日内向原发证部门申请变更经营许可。' WHERE id = '53ddf19a-a05c-4dab-8169-a8b0efbec427';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十条，食品原料、食品添加剂、食品相关产品进货查验记录应当真实，保存期限不得少于产品保质期满后六个月；没有明确保质期的，保存期限不得少于二年。' WHERE id = '53e31c8a-31a4-4dd3-978b-ab9dca8e6298';
UPDATE public.questions SET analysis = '依据《蜂产品生产许可审查细则》及蜂产品制品相关标准，蜂产品制品中的蜂产品成分含量应大于50%，确保产品具有蜂产品的本质属性。' WHERE id = '53e84c7b-3257-4a77-9967-bd13c5f07c5b';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百二十三条，用非食品原料生产食品尚不构成犯罪的，由县级以上人民政府食品安全监督管理部门没收违法所得、违法生产的食品以及用于违法生产的工具、设备、原料等。' WHERE id = '53ed238c-dd28-47a4-a3e4-6d2bd8924746';
UPDATE public.questions SET analysis = '依据《食品生产经营监督检查管理办法》及食品销售日常监督检查要点，日常监督检查主要事项包括食品销售者资质、从业人员健康管理、经营过程控制和进货查验结果等。' WHERE id = '53f4369f-fdb5-487a-9a90-3a1553645c26';
UPDATE public.questions SET analysis = '依据《食品安全法》第六十九条及《食品安全国家标准 预包装食品标签通则》（GB 7718），仅转基因食品需按规定标示；非转基因食品不应显著标示，以避免误导消费者。' WHERE id = '53fd9985-7f09-4655-8c7e-d038a0a17761';
UPDATE public.questions SET analysis = '铅属于重金属污染物。依据《食品安全国家标准 食品中污染物限量》（GB 2762），食用油、油脂及其制品中铅超标属于重金属污染风险。' WHERE id = '5408b47b-3d5e-4f67-80b3-c7eae20b1c9b';
UPDATE public.questions SET analysis = '依据《蛋制品生产许可审查细则》及《食品安全国家标准 蛋与蛋制品》（GB 2749），蛋制品巴氏杀菌工艺的加热温度和时间应足以杀灭沙门氏菌等致病菌，确保产品安全。' WHERE id = '54175170-ae9b-4885-b850-07e3343a8573';
UPDATE public.questions SET analysis = '依据《食品安全法》第八十八条及《食品安全抽样检验管理办法》，食品安全风险监测结果表明存在食品安全隐患的，接到通知的食品生产经营者应当立即进行自查。' WHERE id = '54230def-aa68-4354-9d13-ec80002a1f9e';
UPDATE public.questions SET analysis = '低温、隔氧、干燥等环境条件可以控制寄生虫的生长繁殖，但不能完全实现对寄生虫的控制。寄生虫卵在不良环境中可能长期存活，充分加热等才是有效控制措施。' WHERE id = '5436a04b-b1d5-4c9b-a287-351da8d388cb';
UPDATE public.questions SET analysis = '依据《食品生产经营监督检查管理办法》第三十五条，日常监督检查结果为基本符合的食品生产企业应按期进行整改，并将整改情况报告食品安全监督管理部门。' WHERE id = '54447813-fae6-4484-b467-f2b7255c433c';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品中农药最大残留限量》（GB 2763-2021），异狄氏剂在大豆中的最大残留量为0.01mg/kg，在豆类蔬菜中为0.05mg/kg。' WHERE id = '5448a5e4-ec99-49bf-8f53-34a04b39f97f';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品中污染物限量》（GB 2762-2022），可可制品中总砷限量为0.5mg/kg，该限量有助于控制砷摄入风险。' WHERE id = '544d3b65-7a67-4aad-afdc-0678b6d4c84c';
UPDATE public.questions SET analysis = '依据《餐饮服务通用卫生规范》（GB 31654-2021），餐饮服务从业人员洗手消毒应在流动水下淋湿双手，按照六步洗手法规范洗手。非流动水不符合卫生要求。' WHERE id = '5452bb97-8b9a-49bd-aa6a-64b202a00678';
UPDATE public.questions SET analysis = '依据《学校食品安全与营养健康管理规定》及餐饮服务操作规范，学校食堂用于加工动物性食品原料、植物性食品原料、水产品原料、半成品或成品的容器、工具应明显区分，防止交叉污染。' WHERE id = '5453d7f7-2eb0-4710-9067-7bd4627caa6a';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十四条，食品经营者应当按照保证食品安全的要求贮存食品，定期检查库存食品，及时清理变质或者超过保质期的食品。' WHERE id = '5457f111-e501-4871-856e-7b7618c95c85';
UPDATE public.questions SET analysis = '依据《糖果制品生产许可审查细则》，糖果的甜味主要原料有糖浆、甜味剂和食糖等。麦芽糊精主要用作填充剂和增稠剂，不是主要甜味来源。' WHERE id = '5469c231-4cb6-42dd-9ba0-4e70b03d81b4';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》及相关审查细则，其他粮食加工品包括谷物加工品、谷物粉类制成品和谷物碾磨加工品。挂面属于小麦粉制品，单独分类管理。' WHERE id = '5478bd98-33d9-48a0-a986-50dd007fed68';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品中污染物限量》（GB 2762），肉制品中重金属可通过环境（土壤、水源）、加工设备、用具和容器等途径直接或间接富集到原料中。' WHERE id = '549e9b67-6e62-4d81-a4f4-5dcc10da0e5e';
UPDATE public.questions SET analysis = '依据《农产品质量安全法》第三条，农产品生产经营者应当对其生产经营的农产品质量安全负责，这是生产经营者的法定义务。' WHERE id = '54b0325d-a6f7-482f-b19c-a59596ce33c7';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十三条，食品生产企业选择生产场所时应与有毒有害场所及其他污染源保持规定距离，具有与生产食品品种、数量相适应的原料处理、加工、包装和贮存场所。' WHERE id = '54b19c11-b04a-47c8-b55f-a1a6eaeb630b';
UPDATE public.questions SET analysis = '依据《食品安全法实施条例》第十三条，食品安全标准公布后，食品生产经营者可以在食品安全标准规定实施日期之前实施并公开提前实施情况，鼓励企业提前采用更严格的标准。' WHERE id = '54d6febf-87d3-4591-85ab-739ee48b3baa';
UPDATE public.questions SET analysis = '食品流通标准体系是以系统科学和标准化原理为指导，将食品流通过程要素、环节及其控制所涉及的标准，按内在联系形成的系统、科学、合理且可行的有机整体。' WHERE id = '54dc9561-147c-4ff9-9433-f5ed087488ef';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）5.2.1，直接接触食品的设备或工具应使用无毒、无味、不易脱落、抗腐蚀的材料。' WHERE id = '54ea5758-931e-4c8e-b918-408a0ffc9878';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十八条及《食品生产通用卫生规范》（GB 14881），企业可按照生产卫生规范（GMP）及HACCP体系对生产过程进行食品安全控制，预防危害风险。' WHERE id = '54f053a4-0b4b-4936-adc8-4f0712bacdc8';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十三条、第四十四条，食品生产经营企业应当配备食品安全管理人员，加强对其培训和考核，这是法定义务。' WHERE id = '55005654-706e-4d63-a99d-1db7e549afc5';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》及小麦粉相关标准，专用小麦粉包括面包用小麦粉、面条用小麦粉、蛋糕用小麦粉以及小麦胚（胚片、胚粉）等特定用途产品。' WHERE id = '5503ef5c-9f34-4937-9d67-6bfae00e81df';
UPDATE public.questions SET analysis = '依据《代用茶》（GH/T 1091-2014）及相关标准，果实类代用茶包括柠檬干、山楂干等果实干燥制品。苦丁茶属于叶类，牛蒡属于根茎类，甘草属于根茎类。' WHERE id = '556f3da9-bdf8-4efb-9bb9-d03655acb75b';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》及食品生产通用卫生规范，同一食品品种不同包装的产品，不受包装规格和包装形式影响的检验项目可以一并检验，提高检验效率。' WHERE id = '55787337-99ef-4815-8aca-c67f4ea32d0b';
UPDATE public.questions SET analysis = '依据《餐饮服务通用卫生规范》（GB 31654-2021），经过初加工的食品应当做好防护防止污染，易腐食品应及时使用或冷藏冷冻，防止微生物繁殖。' WHERE id = '557bbe50-3887-4317-9087-250dbde48af8';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 植物油》（GB 2716-2018），植物原油是以食用植物油料为原料制取的用于加工食用植物油的原料油，不得直接食用，需经精炼处理后方可食用。' WHERE id = '5585535a-f1f0-4163-82d7-eb8933f8d778';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第十条，食品安全总监职责包括：组织拟定食品安全管理制度、风险防控措施、事故处置方案，定期评估企业食品安全状况并向主要负责人报告等。' WHERE id = '558699d3-c465-489d-b604-d80e017203fe';
UPDATE public.questions SET analysis = '依据《中华人民共和国反食品浪费法》第七条，餐饮服务经营者应当采取措施防止食品浪费，包括提醒消费者适量点餐、提供小份菜等。' WHERE id = '5587252a-cfab-462d-a0dc-5f7a9227d59b';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十条，企业标准在本企业适用，并报省、自治区、直辖市人民政府卫生行政部门备案。' WHERE id = '558b75e3-0763-449f-b541-28bddaf8e148';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十条及《食品生产通用卫生规范》（GB 14881），进货查验应当记录供应商名称、地址、联系方式等内容，确保来源可追溯。' WHERE id = '559c8fdb-bdac-4c01-8552-60a1ab6aae7c';
UPDATE public.questions SET analysis = '依据《食品安全法》第九十二条，进口的食品应当符合我国食品安全国家标准，而非"地方标准"。我国食品安全标准实行全国统一，不存在地方标准对进口食品的要求。' WHERE id = '55b8858e-ff7f-432e-add3-a9788a77d4e5';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十七条及《企业落实食品安全主体责任监督管理规定》，食品经营企业应定期进行食品安全自查，发现问题及时整改，保存自查记录，发现潜在风险应停止经营并报告监管部门。' WHERE id = '55bfa3a0-41b1-4e4e-9167-16b13d2888c7';
UPDATE public.questions SET analysis = '依据《特殊医学用途配方食品注册管理办法》第四十八条，适用于1岁以上人群的特殊医学用途配方食品，包括全营养配方食品、特定全营养配方食品和非全营养配方食品。' WHERE id = '55c2d676-029d-439f-ab34-6d384fa4eb20';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十条，国家鼓励食品生产企业制定严于食品安全国家标准或者地方标准的企业标准，在本企业适用，推动行业整体质量提升。' WHERE id = '5619f3e0-b966-4d47-aa84-560cf4130aca';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 速冻面米与调制食品》（GB 19295-2021），该标准适用于速冻面米和速冻调制食品，规定了相关定义、微生物限量，产品贮存销售温度应控制在-18℃或以下。' WHERE id = '5622b76a-d49c-4c40-bb2e-1565028e5361';
UPDATE public.questions SET analysis = '超范围使用食品添加剂属于化学性污染或违规添加问题，不属于生物污染。生物污染是指微生物（细菌、病毒等）和寄生虫等生物性因素造成的污染。' WHERE id = '563338c3-3144-42b3-a0c8-e4f38db4487e';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 蒸馏酒及其配制酒》（GB 2757-2012）及相关研究，白酒生产过程中使用塑料容器、管道等储存、输送酒液，可能会导致塑化剂（邻苯二甲酸酯类）迁移污染。' WHERE id = '5638b6d4-1fbd-4d97-a55e-dd719c317ab3';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品添加剂使用标准》（GB 2760）及餐饮服务操作规范，食品添加剂存在感官性状异常、超过保质期等情形的，应当及时清理，不得继续使用。' WHERE id = '5641c9dc-256a-47f0-8678-2647253369fc';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）8.5，食品生产企业使用包装材料时应核对标识，避免误用，如实记录包装材料的使用情况。' WHERE id = '564d8588-3689-4ec7-8ab4-0c32d97a88cb';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品营养强化剂使用标准》（GB 14880-2012），糖果（胶基糖果除外）中可营养强化的维生素种类有限制，不能添加任一维生素。营养强化剂的使用应符合标准规定的范围和限量。' WHERE id = '56636e37-dc28-403d-8cfe-82282114298f';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第三条，特殊食品经营企业主要负责人应当全面负责本企业的特殊食品质量安全管理工作，建立并落实食品安全责任制。' WHERE id = '566ccc63-4805-4aff-bfd5-11767d85204a';
UPDATE public.questions SET analysis = '依据《薯类产品生产许可审查细则》，薯粉类产品工艺流程包括：原料验收、清洗去皮、蒸煮、冷却、干燥、粉碎、包装等工序。' WHERE id = '567b18ce-cf97-4354-9c0d-bc88b2ee6752';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》，其他食品是指无法归入目录中具体食品类别的食品品种，需单独申请食品生产许可。' WHERE id = '5696cc29-2f44-46a7-b8a7-0e6bf2ceaee7';
UPDATE public.questions SET analysis = '依据《食品安全法》第二十七条，食品中农药残留、兽药残留的限量规定及其检验方法与规程由国务院卫生行政部门、国务院农业行政部门会同国务院食品安全监督管理部门制定。' WHERE id = '56d05382-cea4-4259-8376-1c10ed1af5ad';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》及白酒生产许可审查细则，白酒生产许可类别包括白酒、白酒（液态）和白酒（原酒）。调香白酒属于配制酒类别。' WHERE id = '56d0b0e1-8ed6-4344-90f5-85f8881069af';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）4.1.3，食糖加工的不同清洁作业区之间应采取有效分隔，防止交叉污染。' WHERE id = '56d1c15e-1006-48b3-9641-e39b9f676dc4';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百四十八条及《食品安全法实施条例》，生产不符合食品安全标准的食品或经营明知是不符合标准的食品，消费者可要求价款十倍或损失三倍的赔偿金，不足一千元的为一千元。' WHERE id = '56db7ca9-ab07-4a07-ad81-2421434db0ef';
UPDATE public.questions SET analysis = '绿色食品是指产自优良生态环境、按照绿色食品标准生产、实行全程质量控制并获得绿色食品标志使用权的安全、优质食用农产品及相关产品。"绿色"体现生态环境保护理念。' WHERE id = '56f25e0c-1784-4829-8b7d-2d6b58937f81';
UPDATE public.questions SET analysis = '依据《食品安全法》第五条，国务院设立食品安全委员会，作为国务院食品安全工作的高层次议事协调机构，统筹协调全国食品安全工作。' WHERE id = '56fd5cb6-ca80-4ebe-8436-7299071b0989';
UPDATE public.questions SET analysis = '依据《食品安全法》第二十五条，食品安全标准是强制性标准。GB 7718《预包装食品标签通则》属于食品安全国家标准，具有强制性。' WHERE id = '57019a50-b387-4ae3-8dbb-6d122b35551c';
UPDATE public.questions SET analysis = '依据《市场监管总局关于规范食品快速检测使用的意见》（国市监食检规〔2023〕1号），市场监管部门、销售食品的市场开办者可将食品快检用于食用农产品、散装食品、餐饮食品、现场制售食品等的抽查检测。' WHERE id = '5702ba7e-27cf-4d9e-9d9b-e74ece948591';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百二十四条，使用超过保质期的原料生产经营食品、标注虚假生产日期、未通过安全性评估使用新原料、采购使用不符合标准的原料等行为，情节严重的可吊销许可证。' WHERE id = '57197057-5e4f-4091-ad27-b5e227e3865c';
UPDATE public.questions SET analysis = '茶叶发霉变质属于生物性危害（微生物污染），不属于化学性危害。茶叶常见化学性危害包括砖茶氟含量超标、重金属铅超标和农药残留超标等。' WHERE id = '5720b8dc-2b89-4879-9482-5bbb62e238df';
UPDATE public.questions SET analysis = '依据《生猪屠宰管理条例》第二条，从事生猪产品销售、肉食品生产加工的单位和个人以及餐饮服务经营者、集中用餐单位生产经营的生猪产品，应当是经检疫和肉品品质检验合格的生猪产品。' WHERE id = '5752a9b9-f791-49e1-9dca-dbd0468298dc';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十三条及餐饮服务操作规范，散装直接入口食品的销售人员应当在操作前对手部进行消毒，防止微生物污染食品。' WHERE id = '577745f4-6430-4ce1-aebd-74706f37cd51';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十四条，禁止生产经营污秽不洁、混有异物、掺假掺杂、感官性状异常的食品，用非食品原料生产的食品，以及超过保质期的食品。临近保质期食品不属于禁止生产经营范围。' WHERE id = '578b409c-18fe-419e-a0b7-3cab41cce666';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第十条，企业主要负责人每月至少听取1次食品安全总监管理工作情况汇报，形成《每月食品安全调度会议纪要》。' WHERE id = '5792cf21-87f8-4aef-a876-965a6adf9dbf';
UPDATE public.questions SET analysis = '依据《食品安全法》第八十八条，食品安全风险监测结果表明存在食品安全隐患的，食品生产经营者应当立即自查，发现食品不符合食品安全标准或有证据证明可能危害人体健康的，应依法召回。' WHERE id = '579fdd4f-c525-401b-8e8c-bac91f186565';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十五条及《食品生产通用卫生规范》（GB 14881-2013），食品加工人员取得健康证明后还应经过卫生培训方可上岗，培训内容包括个人卫生、食品安全知识等。' WHERE id = '57b5f23b-c49d-4ff9-a3c0-f50c0abd0cb2';
UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》第四十二条，工作人员滥用职权、玩忽职守作出准予注册决定的，总局可以撤销婴幼儿配方乳粉产品配方注册。' WHERE id = '57b6bd16-efeb-4d9c-8042-19f70565fa8f';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）6.4，在生产经营场所配置纱帘、纱网、防鼠板、防蝇灯、风幕等装置，是对虫害危害的主要防控措施。' WHERE id = '57b70106-3b32-4684-9051-167910fc3228';
UPDATE public.questions SET analysis = '依据《特殊医学用途配方食品注册管理办法》第七十二条，伪造、涂改、倒卖、出租、出借、转让特殊医学用途配方食品注册证书的，情节严重的处1万元以上3万元以下罚款。' WHERE id = '57b8f3c4-91e2-44fc-aa2c-d1079866d49c';
UPDATE public.questions SET analysis = '依据《消费者权益保护法》第二十条，经营者应当标明其真实名称和标记，向消费者提供有关商品或服务的质量、性能、用途、有效期限等信息。' WHERE id = '57d33b48-d214-4109-be09-129d85db1dfc';
UPDATE public.questions SET analysis = '依据《食品召回管理办法》第三条，食品召回的主体是食品生产者和食品经营者。因食品经营者原因造成食品不符合标准或有证据证明可能危害人体健康的，应由食品经营者召回。' WHERE id = '57ef13e6-2cfa-4133-9a71-be7bceabe6ea';
UPDATE public.questions SET analysis = '依据《食品安全抽样检验管理办法》第十五条，食品安全监督抽检采用食品安全标准规定的检验项目和检验方法，确保检验结果的科学性和公正性。' WHERE id = '580063d4-a5db-4c61-86c8-147dbdf53109';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十五条，从事散装食品销售和餐饮服务应当依法取得食品经营许可。仅销售预包装食品的只需备案，食品运输不需食品经营许可。' WHERE id = '58110286-9879-4983-9029-d8247ee8c66e';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）6.3，食品生产人员进入作业区域时应将手洗净、穿着清洁的工作衣和帽，不得将个人物品带入作业区域。' WHERE id = '581ec104-8a5f-453a-bbd1-8c24f7b0fa5e';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第十九条，县级以上市场监督管理部门应组织对餐饮服务单位的食品安全管理人员进行监督抽查考核，并公布考核结果。' WHERE id = '5828dcb3-ef63-44fd-a8ac-efc1e5b17386';
UPDATE public.questions SET analysis = '食用油、油脂及其制品中污染物限量应符合《食品安全国家标准 食品中污染物限量》（GB 2762），该标准规定了各类食品中铅等重金属的限量要求。' WHERE id = '5836fc1d-f013-4c76-97b7-75d8f7396802';
UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》第九条，婴幼儿配方乳粉产品配方是指生产婴幼儿配方乳粉使用的食品原料、食品添加剂及其使用量、营养成分的含量等。' WHERE id = '58629251-db58-45cc-8104-05677775a410';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第二十八条，餐饮服务提供者地址迁移不在原许可经营场所从事餐饮服务活动的，应当重新申请食品经营许可，而非申请变更许可。' WHERE id = '58652432-1a5a-4c26-8731-c5b8c849372c';
UPDATE public.questions SET analysis = '依据《食品安全法》第七十九条及《保健食品广告审查暂行规定》，保健食品广告应显著标明"保健食品不是药物，不能代替药物治疗疾病"，并显著标明保健食品标志、适宜人群和不适宜人群。' WHERE id = '58799e54-b04a-4002-ab20-590bf13fcc61';
UPDATE public.questions SET analysis = '依据《中华人民共和国刑法》第一百四十四条，在生产、销售的食品中掺入有毒、有害的非食品原料的，处五年以下有期徒刑，并处罚金；对人体健康造成严重危害的，处五年以上十年以下有期徒刑。' WHERE id = '587fca86-35a4-4cd0-bd3a-5348845396ab';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》及网络餐饮服务食品安全要求，外卖箱或外卖包应保持整洁无污染，需定期清洁和消毒，防止食品在配送过程中受到污染。' WHERE id = '58abc380-5042-4272-b1be-5ca183855c3f';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第三条，食品生产经营企业应当建立基于食品安全风险防控的动态管理机制，而非静态管理机制。食品安全风险是动态变化的。' WHERE id = '58ac0939-104a-44b3-934a-c197f9e431a2';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》及相关规定，利用自动设备从事销售活动的，设备放置地点应当与许可申请材料或备案信息中标明的地点一致，确保经营场所与许可相符。' WHERE id = '58b58cae-721a-4abf-ad4d-e25833be3446';
UPDATE public.questions SET analysis = '依据《食品安全法》及散装食品经营管理规范，在充分评估并能保障食品安全的前提下，可将附有保护性包装的食品拆分重新包装，分装后的食品按散装食品管理。' WHERE id = '58b84a1e-cce6-4be7-8157-08d929a49229';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品用香精》（GB 30616-2020），食品用香精是由食品用香料与食品用香精辅料组成的用来起香味作用的浓缩调配混合物。' WHERE id = '58c09e10-cc31-435a-8593-449b4aab2d79';
UPDATE public.questions SET analysis = '依据《食品安全法》第六十三条，食品生产者发现其生产的食品不符合食品安全标准或者有证据证明可能危害人体健康的，应当立即停止生产，召回已上市销售的食品。' WHERE id = '58f4984a-8c60-4718-a2bd-134c27d59988';
UPDATE public.questions SET analysis = '依据《罐头食品生产许可审查细则》，罐头食品生产的封口操作人员、杀菌操作人员和检验人员均应经过技术培训后方可上岗，确保关键工序的操作质量。' WHERE id = '590c4b37-9aaf-44cd-9aee-3cec9446a38b';
UPDATE public.questions SET analysis = '根据GB/T 30766-2014《茶叶分类》及《食品生产许可分类目录》，普洱茶（熟茶）散茶属于黑茶类。黑茶是以茶树鲜叶和嫩梢为原料，经杀青、揉捻、渥堆、干燥等加工工艺制成的产品。选项A正确。' WHERE id = '590d9bab-b686-405c-b211-f6dd04372afc';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第五十七条，保健食品名称不得含有虚假、夸大或绝对化词语，不得明示或暗示预防治疗功能，不得使用人体组织器官等词语。''R''符号（注册商标）可标注。选项D正确，A、B、C均为禁用内容。' WHERE id = '590e6bbf-cd62-436a-b198-6df95db326f8';
UPDATE public.questions SET analysis = '依据《食品生产经营风险分级管理办法》规定，正确答案为A,B,C,D。选项A（A、A级）, 选项B（B、B级）, 选项C（C、C级）, 选项D（D、D级）均符合法规要求。' WHERE id = '5928ba6e-bb14-44c1-81d5-2e5f05d566ef';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》及GB 2730《腌腊肉制品》，发酵火腿制品经过发酵成熟可直接食用，而腌腊肉灌制品、腊肉制品、腌腊火腿制品需加热后食用。选项D正确。' WHERE id = '59333634-9f9d-4fe9-aacc-72609ce91942';
UPDATE public.questions SET analysis = '依据GB 2760-2014《食品安全国家标准 食品添加剂使用标准》及《食品安全法》第三十四条，干制薯类产品不得使用漂白剂。部分不法企业违规使用漂白剂（如硫磺、亚硫酸盐等）提高产品色泽，属超范围使用食品添加剂的违法行为。选项B正确。' WHERE id = '593655a0-005e-4b54-a26c-74e511e2af5c';
UPDATE public.questions SET analysis = '依据《食品经营许可和备案管理办法》第六十二条，利用自动设备仅销售预包装食品的，应提交每台设备的具体放置地点、备案编号展示方法、食品安全风险管控方案等材料。该表述正确。' WHERE id = '593e7b0c-d111-4cda-b801-9d10d63a31d5';
UPDATE public.questions SET analysis = '依据GB 14881-2013第8.3条，食品加工过程的微生物监控应包括致病菌监控和指示菌监控，以验证清洁作业区环境控制措施的有效性。该表述正确。' WHERE id = '594af16a-e680-4344-b9be-8c4e46914fb7';
UPDATE public.questions SET analysis = '《学校食品安全与营养健康管理规定》规定，供餐对象为中小学生的学校食堂不得申请生食类食品制售、冷荤类食品制售、冷加工糕点制售等高风险项目。选项A、B、C正确。' WHERE id = '594caedd-eefa-423e-b94e-7a0b45fea480';
UPDATE public.questions SET analysis = '依据GB 29921《食品安全国家标准 食品中致病菌限量》，致病菌包括沙门氏菌、金黄色葡萄球菌、单核细胞增生李斯特氏菌等。大肠菌群、酵母、霉菌属于微生物指标但不属于致病菌范畴。选项D正确。' WHERE id = '5958e789-5264-4d23-910f-c364bb971239';
UPDATE public.questions SET analysis = '《食品安全法》第四十七条规定，食品生产经营者应当建立食品安全自查制度，定期（非不定期）对食品安全状况进行检查评价。该表述错误。' WHERE id = '599a477a-1352-4aed-980b-0319acb9e4cc';
UPDATE public.questions SET analysis = '依据GB 7718-2011第4.1.5条，预包装食品应标示净含量，液态食品应使用体积单位（mL/L）。选项C''净含量：250mL''标示正确。A单位不规范，B用''规格''不当，D数值错误。' WHERE id = '599fbe47-6a65-40c6-b320-993b07302da1';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食品安全事故指食源性疾病、食品污染等源于食品，对人体健康有危害或者可能有危害的事故。该表述正确。' WHERE id = '59a47ed5-ce21-4bd8-99ba-590210441ec2';
UPDATE public.questions SET analysis = '依据《食品召回管理办法》第十三条，一级召回：可能导致严重健康损害甚至死亡的；二级召回：可能导致一般健康损害的；三级召回：标签标识存在虚假标注的。该表述正确。' WHERE id = '59b9be22-5f77-4768-bc73-eca69c2a7a58';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》及相关法规标准规定，正确答案为A,B,C,D。选项A（明示或者暗示具有预防、治疗疾病作用）, 选项B（非保健食品明示或者暗示具有保健作用）, 选项C（以欺骗或者误导的方式描述或者介绍食品）, 选项D（使用国旗、国徽或者人民币等进行标注）均符合法规要求。' WHERE id = '59bbffda-7e06-4645-b2cf-1fcbfdff6c73';
UPDATE public.questions SET analysis = '依据GB 14881-2013及相关食品安全管理体系要求，通过建立良好生产规范（GMP）和标准操作规程（SOP），实施HACCP等管理手段进行监测、分析、评估和预防。选项C正确。' WHERE id = '59d695ee-6f45-4f1d-899f-98859a6b6a69';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》及相关法规标准规定，正确答案为A,B,C,D。选项A（保持）, 选项B（控制）, 选项C（建立）, 选项D（运行）均符合法规要求。' WHERE id = '59d8ce02-f3c3-4942-bfdf-b92f98ca453b';
UPDATE public.questions SET analysis = '依据GB 10767-2010及《婴幼儿配方乳粉产品配方注册管理办法》，幼儿配方乳粉为3段，适用12-36月龄。1段为0-6月龄，2段为6-12月龄。选项D正确。' WHERE id = '59e2ece8-67c6-4e08-a38f-fbe07c687f58';
UPDATE public.questions SET analysis = '依据GB 21710-2016《食品安全国家标准 蛋与蛋制品生产卫生规范》，蛋液暂存温度不应高于7°C，以防止微生物滋生。选项B正确。' WHERE id = '59ee9131-8197-4f8f-9d54-d0121634527e';
UPDATE public.questions SET analysis = '依据《食品安全法》《餐饮服务通用卫生规范》（GB 31654-2021）规定，正确答案为A,B,C,D。选项A（原料采购）, 选项B（过程控制）, 选项C（卫生管理）, 选项D（检验管理）均符合法规要求。' WHERE id = '59f5f9c0-6480-42b5-bdab-6533590472fa';
UPDATE public.questions SET analysis = '依据水产制品生产许可审查细则，干制水产品常规工艺为：原料处理→煮制→干燥→包装。干燥是关键工序，降低水分活度延长保质期。选项B正确。' WHERE id = '5a5594a8-e812-4fa1-8d51-519e787412e2';
UPDATE public.questions SET analysis = '依据《食品安全法》及《食品标识管理规定》，正确答案为A,B,C,D。选项A（食品的追溯码、名称、品牌、规格、数量、进货日期、销售日期。）, 选项B（食品的供货者和购货者的名称、地址、联系方式等。）, 选项C（食品的生产企业名称、生产日期或生产批号、检验合格证号、保质期。）, 选项D（食用农产品、水产品的准出合格证、动物检疫等信息。）均符合法规要求。' WHERE id = '5a845cd4-b41b-43ab-8adb-59f099fe5c34';
UPDATE public.questions SET analysis = '依据淀粉制品生产许可审查细则，以红薯淀粉为原料直接生产粉丝时，从和浆环节开始，包括和浆、成型、冷却、干燥等工序。选项C正确。' WHERE id = '5a8875b6-c11f-4b38-82dc-0dad07cf24f4';
UPDATE public.questions SET analysis = '依据《食品经营许可和备案管理办法》第二十八条，许可事项发生变化后应在10个工作日内申请变更经营许可。该表述正确。' WHERE id = '5a8f1489-85b3-45a2-9a86-e8c100294def';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条第一款第（六）项规定，贮存、运输和装卸食品的容器、工具和设备应安全、无害，保持清洁，防止食品污染。该表述正确。' WHERE id = '5a941721-b49e-4b4b-afe6-9f23d972e5d4';
UPDATE public.questions SET analysis = '《中华人民共和国食品安全法》对此有明确规定。正确答案为A,B,C。选项A（A、名称、规格、净含量、生产日期）, 选项B（B、所使用的食品添加剂在国家标准中的通用名称）, 选项C（C、生产者的名称、地址、联系方式）均符合法规要求。' WHERE id = '5aaedbb5-cc7c-4221-973c-eb437e034cbe';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》及相关法规标准规定，正确答案为A,B,C,D。选项A（食品经营企业应当建立健全食品安全管理制度）, 选项B（食品经营企业应当对职工进行食品安全知识培训）, 选项C（食品经营企业应当配备食品安全管理人员，加强对其培训和考核）, 选项D（食品安全监督管理部门应当对企业食品安全管理人员随机进行监督抽查考核并公布考核情况）均符合法规要求。' WHERE id = '5ab11ffb-3eb5-49d4-a576-ed89b2ae1e39';
UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》及《食品安全法》，婴幼儿配方乳粉经营者应严格落实质量安全责任追究制度，建立先行赔偿和追偿制度，按照''谁销售、谁负责''原则对消费者赔偿。该表述正确。' WHERE id = '5ac3e73f-6c7f-4e4c-8976-fff48d42d44d';
UPDATE public.questions SET analysis = '依据《食品生产经营风险分级管理办法》规定，正确答案为A,B,C,D。选项A（A级）, 选项B（B级）, 选项C（C级）, 选项D（D级）均符合法规要求。' WHERE id = '5ace2c17-97b5-4164-876b-cac2ad52e50b';
UPDATE public.questions SET analysis = '依据GB 7718-2011《食品安全国家标准 预包装食品标签通则》第2.1条，预包装食品首先应当预先包装，此外包装上要有统一的质量或体积标示。该表述正确。' WHERE id = '5acfd054-b5f3-4410-aa5e-e852472f4836';
UPDATE public.questions SET analysis = '《食品安全法》第七十六条规定，使用保健食品原料目录以外原料的保健食品和首次进口的保健食品应当注册；使用原料目录内原料的保健食品应当备案。选项A正确。' WHERE id = '5ad45c9b-72f9-4ee6-9d47-5f0b69f0fb49';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》及相关法规标准的规定，正确答案为B（《中华人民共和国食品安全法》）符合法规规定要求。' WHERE id = '5b00f217-8005-4d4c-8958-b73066503fff';
UPDATE public.questions SET analysis = '《食品安全法》第八十九条规定，食品生产企业可自行检验或委托检验机构，自行检验应具备与所检项目适应的检验室和检验能力。该表述正确。' WHERE id = '5b1333d3-c934-48d9-a1fe-5ed7394743d7';
UPDATE public.questions SET analysis = '依据GB 14881及《食品经营许可审查细则》，食品销售、贮存场所应距离粪坑、污水池、暴露垃圾场（站）、旱厕等污染源25米以上。该表述正确。' WHERE id = '5b15cadd-ce19-422a-9ac0-b00aa9edc9d3';
