UPDATE public.questions SET analysis = '依据糕点生产许可审查细则，焙烤过程应控制设备温度和时间，需要贮存的半成品应控制其水分含量，以确保产品质量和微生物安全。选项C正确。' WHERE id = '6432dcc1-6ae5-4b20-837d-de2b7d5e7c9a';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条明确规定禁止生产经营用非食品原料生产的食品或添加食品添加剂以外的化学物质。甲醇（A）、工业乙酸（B）、苏丹红（C）均为非食用物质或有毒有害物质，严禁用于食品生产。小苏打（碳酸氢钠）是GB 2760允许使用的食品添加剂，可用于焙制面包，D正确。' WHERE id = '6435756e-5fc7-4813-8dc2-790cb8bb2f5e';
UPDATE public.questions SET analysis = '根据GB 2760《食品添加剂使用标准》，膨化食品中允许使用的甜味剂有明确规定。三氯蔗糖（A）、糖精钠（B）、安赛蜜（D）在膨化食品中超范围使用是常见风险点。甜蜜素（C）在膨化食品中的使用也有严格限制，但题目所述风险主要针对前三者。' WHERE id = '6436531b-d325-4af4-927b-65f9942ff6eb';
UPDATE public.questions SET analysis = '《食品安全法实施条例》及《餐饮服务食品安全操作规范》规定，感官性状异常的食品可能已发生腐败变质或被污染，加热不能消除某些细菌毒素（如金黄色葡萄球菌肠毒素）和化学危害，存在食品安全风险，应当废弃处理。' WHERE id = '6441a997-76f0-4c72-b051-4f08a0778a10';
UPDATE public.questions SET analysis = '《食品安全法》第一百一十条规定，食品生产经营者应当配合食品安全监督检查，如实提供有关情况，不得拒绝、阻挠、干涉。配合义务包括开放场所、回答询问、提供相关材料、协助检查和抽样检验等。' WHERE id = '64447b09-d868-4e34-990b-68325292d472';
UPDATE public.questions SET analysis = '《食品安全国家标准 速冻面米与调制食品》（GB 19295-2021）及《速冻食品生产和经营卫生规范》规定，速冻食品的贮存、销售温度应控制在-18℃或以下，温度波动应控制在2℃以内，以确保产品品质和安全。' WHERE id = '6449e5e2-b0c0-462a-92e7-539c12f05051';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）规定，个人物品不得带入生产车间，水杯等个人用品应存放于指定区域，不得放在操作台上，以防交叉污染。' WHERE id = '6454d373-46f9-4b51-bb89-0ba8f65dccc8';
UPDATE public.questions SET analysis = '《食品生产经营风险分级管理办法》第七条规定，存在故意违法受行政处罚、监督抽检不合格、造成不良社会影响、发生食品安全事故等情形的，下一年度风险等级将被调高。' WHERE id = '645ef019-4479-462a-af34-1c48566cf4e6';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，被抽样食品生产经营者应当配合抽样工作，提供营业执照、许可证等可追溯信息，开放生产经营场所和库房，提供企业标准文本等。' WHERE id = '64712502-2aeb-42bb-a846-2ca8c9c9f481';
UPDATE public.questions SET analysis = '《食品安全法》第五十条规定，食品生产者应当查验供货者的许可证和产品合格证明，不得采购或使用不符合食品安全标准的食品原料。真菌毒素防控应从原料抓起，D选项''原料不需控制''的观点严重错误。' WHERE id = '647b104b-b4d0-4d28-9beb-92b131732ddd';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》6.4.2规定，应制定和执行虫害控制措施，定期检查和维护防鼠、防蝇等设施，包括纱帘、纱网、防鼠板、防蝇灯等，防止鼠类昆虫侵入。' WHERE id = '64a1dea5-98a8-46cd-b4ad-ebee191c7ed0';
UPDATE public.questions SET analysis = '《食品生产许可分类目录》及相关标准规定，热加工熟肉制品包括熏烧烤肉制品（A）、油炸肉制品（B）、熟肉干制品（C）。腊肉制品（D）属于腌腊肉制品，不属于热加工熟肉制品。' WHERE id = '64a2df38-c990-43b2-b8be-984982586200';
UPDATE public.questions SET analysis = '《盲盒经营行为规范指引（试行）》及市场监管总局相关规定，对有温度、湿度等特殊要求（如冷藏冷冻食品）的食品，不得以盲盒形式销售，以保障食品安全。' WHERE id = '64acf84e-46c4-4f72-85cf-f1f1e7f7d68e';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条第（六）项规定，贮存、运输和装卸食品的容器、工具和设备应当安全、无害，保持清洁，防止食品污染，并不得将食品与有毒、有害物品一同贮存、运输。' WHERE id = '64b0b4be-bac8-4433-98f1-52e9e4bafbcc';
UPDATE public.questions SET analysis = '《食品安全国家标准 预包装食品标签通则》（GB 7718-2011）规定，产品名称应准确反映食品真实属性，不得随意制定。名称应使用国家标准、行业标准或地方标准中的名称，或不会使消费者误解的常用名。' WHERE id = '64bb133f-6e9d-4cab-9a1d-b9a6cc822e35';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）规定，化学性危害主要来自动植物原料及其种养殖环境、加工过程，包括农药残留、兽药残留、重金属、天然毒素等，其控制比生物性危害更复杂。' WHERE id = '64d7a337-b80f-4ab1-a723-9cae09a06bfe';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第六十条规定，食品安全风险监测表明存在隐患的，食品生产经营者应立即自查，发现食品不符合食品安全标准（A）或有证据证明可能危害人体健康（B）的，应依照《食品安全法》第六十三条进行召回等处理。' WHERE id = '64dac20c-783d-4d41-bc7a-4a4aa31cd98f';
UPDATE public.questions SET analysis = 'GB 10136-2015《食品安全国家标准 动物性水产制品》4.5标识要求规定，产品标识除应符合GB 7718外，还应注明食用方法，以确保消费者正确食用，避免因食用方法不当导致食品安全问题。' WHERE id = '64db9b1e-f45a-44ff-8ad9-c2b9b6db7def';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第七十二条规定，食品安全管理人员监督抽查考核不得收取费用，考核工作所需经费应列入同级财政预算，由政府部门承担。' WHERE id = '64e4a577-0f58-4b56-a303-287318ee9962';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第三十七条规定，在复检和异议期间，食品生产经营者不得停止履行风险控制、原因排查、问题整改等义务，应继续采取必要措施控制食品安全风险。' WHERE id = '64f26f7e-b29a-49fb-b2f5-57d803b6aa80';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》6.3.2规定，进入食品生产场所前应整理个人卫生，防止污染食品。生产食品时应当洗净手（A），穿着清洁的工作衣（C），佩戴清洁的工作帽（D），不得将个人物品带入作业区域（B错）。' WHERE id = '64fc3cc8-926e-4739-9d83-7ac909d65223';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第二条及《企业落实食品安全主体责任监督管理规定》要求，食品生产经营者应当落实主体责任，强化道德观念，倡导诚信从业，推动食品安全治理从单一监管向多方参与的综合性治理转变。' WHERE id = '65010c6b-2b7d-4b05-9934-e3f891be2996';
UPDATE public.questions SET analysis = '《食品安全国家标准 动物性水产制品》的标准代号为GB 10136-2015。GB 2762-2022为污染物限量标准，GB 31602-2015为干海参标准，GB 7718-2011为预包装食品标签通则。' WHERE id = '6501ba3f-42d3-4f11-944b-4d4b82d713e1';
UPDATE public.questions SET analysis = 'GB 7718-2011《预包装食品标签通则》3.8.1规定，可以同时使用拼音或少数民族文字，但拼音不得大于相应汉字，以确保汉字的主导地位和消费者的准确理解。' WHERE id = '6507234c-b117-4959-af3a-4343cc70bab7';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》及《餐饮服务食品安全操作规范》要求，连锁食品经营企业总部应对总部（A）、中央厨房（B）、配送中心（C）、门店（D）等各环节全面开展食品安全自查，确保全链条安全管控。' WHERE id = '650757cc-c418-4d25-9fb6-3fb26e79c7b7';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食品安全是指食品无毒、无害，符合应当有的营养要求（B），对人体健康不造成任何急性、亚急性或者慢性危害。食品安全不仅指无毒无害，还包括营养要求。' WHERE id = '6508e33f-34bc-4a52-86cf-4b0d249f71dd';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营企业应当配备专职或者兼职的食品安全专业技术人员（A）、食品安全管理人员（C），负责本单位的食品安全管理工作。' WHERE id = '650ff696-f1cc-4ad6-b155-a512d01b3495';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）及食糖生产许可审查细则规定，食糖生产设备材质应满足抗腐蚀（A）、无毒（B）、无味（C）、不易脱落（D）等要求，以保障食品安全和产品质量。' WHERE id = '651a5282-1486-4610-a6d8-fb3d004bb1bd';
UPDATE public.questions SET analysis = '压片糖果属于普通食品，不得添加中草药（中药材）进行生产销售。根据《食品安全法》和《按照传统既是食品又是中药材的物质目录》，只有列入目录的物质方可用于普通食品生产，中草药的使用需遵循药品管理规定。' WHERE id = '651db10e-b6e5-4a1f-954e-3c412986c3e9';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》4.1.3规定，厂房和车间应根据产品特点、生产工艺、生产特性以及生产过程对清洁程度的要求合理划分作业区，并采取有效分离或分隔。灌装与外包装工序应有效隔离（B正确），清洁作业区与准清洁作业区不得共用（A错），配料室与熟制车间应分隔（C错）。' WHERE id = '6524933a-16f0-45a6-851b-f88c38b4513e';
UPDATE public.questions SET analysis = '《食品安全国家标准 蜂蜜》（GB 14963-2011）3.1规定，蜜蜂采集花蜜不得来源于雷公藤（A）、博落回（B）、狼毒（C）等有毒蜜源植物，以上三种均为有毒蜜源植物，故正确答案为D。' WHERE id = '65345568-b9f2-49ba-af9f-eb3fac8a9ba6';
UPDATE public.questions SET analysis = 'GB/T 17204-2021《饮料酒术语和分类》规定，发酵酒是以粮谷、水果、乳类等为主要原料，经发酵或部分发酵（D）酿制而成的饮料酒，与蒸馏酒以蒸馏工艺为特征相区别。' WHERE id = '65444562-2361-49b0-90a7-8e9834979ac4';
UPDATE public.questions SET analysis = '《食品安全法》第二十六条规定，食品安全标准包括食品添加剂的品种、使用范围、用量（A）；专供婴幼儿等特定人群主辅食品的营养成分要求（B）；食品检验方法与规程（C）；致病性微生物、污染物等限量规定（D）。以上全部正确。' WHERE id = '654f282e-f3d6-4119-8471-44cbd7fe36b4';
UPDATE public.questions SET analysis = '《网络食品安全违法行为查处办法》第十三条规定，网络食品交易第三方平台提供者和通过自建网站交易食品的生产经营者应当记录、保存食品交易信息，保存时间不得少于产品保质期满后六个月；没有明确保质期的，保存时间不得少于二年。' WHERE id = '6567f2c4-1046-4aa5-bf8a-9dfa21474d1b';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，委托餐（饮）具集中消毒服务单位提供清洗消毒服务的，应当查验、留存营业执照复印件和消毒合格证明，保存期限不应少于消毒餐（饮）具使用期限到期后6个月。' WHERE id = '65794042-7033-498b-adf5-b7dfb28c24c4';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条及《食品经营许可管理办法》规定，食品经营应具有合理的设备布局和工艺流程，防止交叉污染，避免食品接触有毒物、不洁物，包括售卖、贮存场所等。' WHERE id = '6589f886-5474-4931-bb04-5c9aa615f10c';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，保健食品审评涉及的试验和检验工作应当由国家食品药品监督管理总局选择符合条件的食品检验机构（B）承担，确保检验结果科学可靠。' WHERE id = '65971c2a-b8f0-4cc0-abdc-c296c45994ac';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品添加剂使用标准》（GB 2760）对干制薯类中漂白剂的使用有严格规定。二氧化硫等漂白剂在薯类制品中有最大使用量限制，''适量使用''说法错误，应严格按标准执行，且许多干制薯类不得使用漂白剂。' WHERE id = '659fad97-3c6e-4597-9e92-f7164fb2af31';
UPDATE public.questions SET analysis = '《学校食品安全与营养健康管理规定》第二十一条规定，学校采购食品及原料应查验许可相关文件：从生产者采购查验许可证和产品合格证明（A）；从经营者采购查验经营许可证（B）；从农产品生产者直接采购查验社会信用代码或身份证（C）；从集中交易市场采购留存购货凭证（D）。' WHERE id = '65a50b26-10a1-429f-80cb-df085f9d4b90';
UPDATE public.questions SET analysis = 'GB 19295-2021《食品安全国家标准 速冻面米与调制食品》规定了感官要求（B）、理化指标包括过氧化值限量（C）、污染物限量（D）以及微生物限量包括菌落总数和大肠菌群（A）。以上四项均符合标准要求。' WHERE id = '65ad5811-c6dc-4cec-b477-2bdd77721cbf';
UPDATE public.questions SET analysis = '《食品安全法》第五十四条及《食品经营许可管理办法》规定，食品经营者应当按照食品标签标示的贮存条件和保质期展售预包装食品，确保食品在销售和贮存过程中符合安全要求。' WHERE id = '65b898ac-0f49-4f42-9c40-82c6e2bc2c11';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》第十条规定，食品安全总监或食品安全员每周至少组织1次风险隐患排查，分析研判食品安全管理情况，形成《每周食品安全排查治理报告》。' WHERE id = '65bb70be-a9a4-4407-8152-b0271c15162a';
UPDATE public.questions SET analysis = '《食品安全法》第四十六条及《食品生产通用卫生规范》规定，食品生产企业应建立严格的生产过程控制制度，包括精确的领料、投料和记录管理。饼干生产同样需要严格遵循，以确保食品添加剂使用合规和产品质量稳定。' WHERE id = '65db9204-d3a3-40e4-b422-05f0602cab27';
UPDATE public.questions SET analysis = '《反食品浪费法》第七条及《餐饮服务食品安全操作规范》规定，餐饮服务经营者应引导消费者按需适量点餐，提升供给质量，合理确定数量和分量，提供小份餐等不同规格选择，减少食品浪费。' WHERE id = '65e4dc9c-02c6-4cc0-879f-0faf9a45e541';
UPDATE public.questions SET analysis = '《食品安全法》第十七条规定，国家建立食品安全风险评估制度（D），运用科学方法，根据食品安全风险监测信息、科学数据以及有关信息，对食品中生物性、化学性和物理性危害因素进行风险评估。' WHERE id = '660345ce-021f-4bfd-a968-a62d36e38458';
UPDATE public.questions SET analysis = '《野生动物保护法》及《食品安全法》规定，食用农产品不包括法律法规禁止食用的野生动物产品及其制品。禁止食用的野生动物不属于合法食用农产品范畴。' WHERE id = '660d34eb-9a4e-4eb9-8612-f20237cdc0a1';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》5.1.8.5规定，清洁剂、消毒剂、杀虫剂等物质应分别安全包装，明确标识，并应与原料、成品、包装材料等分隔放置（不仅仅是分离放置，应有明确分隔措施）。题干表述不够准确，应为''错''。' WHERE id = '66111a52-3d4b-459f-9ff1-8cbcf87d796e';
UPDATE public.questions SET analysis = '《食品安全法》第三十五条规定，国家对食品生产经营实行许可制度。从事食品销售，应当依法取得食品经营许可（C），而非食品卫生许可（已取消）或食品生产许可。' WHERE id = '6614a52f-b89f-4d2c-bbba-8e4c65a3f324';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十五条规定，被吊销许可证的食品生产企业及其法定代表人、直接负责的主管人员和其他直接责任人员自处罚决定作出之日起五年内不得申请食品生产许可，或从事食品生产管理工作、担任食品安全管理人员。' WHERE id = '6642d323-6d3b-41b0-b104-97c3fddf3e4a';
UPDATE public.questions SET analysis = '《食品生产经营风险分级管理办法》第四条规定，风险分级管理是指食品安全监督管理部门以风险分析（A）为基础，结合食品生产经营企业风险特点，确定食品生产经营者风险等级的监管方法。' WHERE id = '6644c6b7-a729-4468-bfae-d9b1d2cc11dd';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第三十四条规定，复检费用包括检验费用和样品递送产生的相关费用，由复检申请人先行垫付，复检结论与原检验结论一致的，由申请人承担；不一致的，由原检验机构承担。' WHERE id = '6651e607-159b-4923-b3a6-4b8757aacd0b';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品添加剂经营者采购食品添加剂，应当查验供货者的许可证（A）和产品合格证明文件（B），建立进货查验记录制度。税务登记证（C）不属于必须查验的范围。' WHERE id = '667579bc-04a7-46ea-b59b-3bd2eee4c33a';
UPDATE public.questions SET analysis = 'GB 2762《食品安全国家标准 食品中污染物限量》、GB 2760《食品添加剂使用标准》、GB 2763《食品中农药最大残留限量》及茶叶产品标准规定，茶叶产品质量安全要求包括污染物限量（A）、食品添加剂（B）、农药残留限量（C）和感官要求（D）。' WHERE id = '6678656a-79bd-4af2-b7c3-fecf1d7371a4';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第三十九条规定，特殊食品不得与普通食品或者药品混放销售，以防止消费者混淆，保障特殊食品消费安全。' WHERE id = '667fdcde-06ee-4faf-9773-1cde2692d00b';
UPDATE public.questions SET analysis = 'GB 2713-2015《食品安全国家标准 淀粉制品》规定，硫酸铝钾、硫酸铝铵是淀粉制品中允许使用的食品添加剂（膨松剂），但投料控制不当会导致成品中铝残留量超标，危害人体健康。' WHERE id = '66a7e842-f844-4be8-bc5a-3990ba56f232';
UPDATE public.questions SET analysis = '《食品安全法》第六十七条及GB 7718-2011《预包装食品标签通则》规定：医学临床证明对特殊群体易造成危害的（A）、经电离辐射处理的（B）、属于转基因食品的（C）以及法律法规规定应标注其他说明的（D），均应标注中文说明。' WHERE id = '66ab4fb4-755a-4958-8f65-c9d4fd78f27b';
UPDATE public.questions SET analysis = '《食品安全法》第三十条规定，国家鼓励食品生产企业制定严于食品安全国家标准或地方标准的企业标准，在本企业适用，并报省、自治区、直辖市人民政府卫生行政部门备案。企业标准需符合法律法规和强制性标准的规定。' WHERE id = '66b5c16f-95d2-44e3-9826-bf986067d876';
UPDATE public.questions SET analysis = '《食品安全法》第二十九条规定，对地方特色食品，没有食品安全国家标准的，省、自治区、直辖市人民政府卫生行政部门可以制定并公布食品安全地方标准。但保健食品、特殊医学用途配方食品、婴幼儿配方食品不得制定地方标准，以防止地方保护。' WHERE id = '66b87398-379f-4f33-ba48-2476a5fd8c87';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条禁止生产经营超范围超限量使用食品添加剂的食品（A）、病死毒死或死因不明的动物肉类制品（B）、被污染的食品（C）、未经检验或检验不合格的肉类制品（D）。以上均属于禁止生产的食品。' WHERE id = '66bafd86-88f4-4237-ba8b-cdf14711b8d7';
UPDATE public.questions SET analysis = 'GB 28050-2011《食品安全国家标准 预包装食品营养标签通则》2.1定义，营养标签是向消费者提供食品营养成分信息和特性的说明，包括营养成分表、营养声称和营养成分功能声称。' WHERE id = '66c69b39-5a8c-4805-ad8f-4dd5799330b0';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第二十二条规定，食品经营许可证分为正本、副本，正本、副本具有同等法律效力。题干说''不具有同等法律效力''是错误的。' WHERE id = '66e2d2b3-077a-4116-bb49-20afd64aef5f';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第四十六条规定，市场监督管理部门应通过政府网站（A）等媒体及时向社会公开监督抽检结果（B）和不合格食品核查处置（C）的相关信息，并记入食品生产经营者信用档案（D）。' WHERE id = '66ebbcd9-8da3-47d4-87d5-76e3a7a0f671';
UPDATE public.questions SET analysis = 'GB 19298-2014《食品安全国家标准 包装饮用水》规定，铜绿假单胞菌是包装饮用水的重要微生物指标。循环使用的大桶清洗消毒不彻底，会导致铜绿假单胞菌超标，引发食品安全风险。' WHERE id = '66ecfab4-6d07-46af-b57e-8630a1c248bf';
UPDATE public.questions SET analysis = '《食品安全法》第七十条规定，食品添加剂应当有标签、说明书和包装，标签、说明书应载明''食品添加剂''字样及使用范围、用量、使用方法，并在标签上载明''食品添加剂''字样。' WHERE id = '66f3286b-5f3c-4de5-af4b-b6838ff6efb8';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，被抽查人对食用农产品检测结果有异议申请复检的，复检应当采用食品安全国家标准规定的检验方法，不得采用快速检测方法。快速检测仅用于初步筛查，不能作为执法依据。' WHERE id = '671664d9-e823-4585-a992-fac3cd265f45';
UPDATE public.questions SET analysis = '《乳品质量安全监督管理条例》及《生鲜乳生产收购管理办法》规定，乳制品生产企业禁止向未取得许可的单位购进生鲜乳（A）、禁止购进兽药残留超标（B）、重金属超标（C）、含致病性微生物（D）等不合格生鲜乳。' WHERE id = '6718011e-ff58-40fd-8b17-15dbb331b734';
UPDATE public.questions SET analysis = '《食品安全法》第五十条规定，食品原料、食品添加剂和食品相关产品进货查验记录、食品出厂检验记录应由记录和审核人员复核签名，记录内容应完整。保存期限不得少于2年（B）。' WHERE id = '675a591d-f29a-47fd-bf7c-9b6f363afbe1';
UPDATE public.questions SET analysis = '《乳品质量安全监督管理条例》第三十条规定，乳制品生产企业应当对出厂的乳制品逐批（D）检验，并保存检验报告，留取样品。乳制品属于高风险食品，必须逐批检验合格后方可出厂。' WHERE id = '67690d32-4a77-4d3f-9136-3c7d980306cd';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》6.3.2规定，进入作业区域不应染指甲、喷洒香水、化淡妆（B不正确）。食品加工人员应保持个人卫生，不得佩戴饰物、手表，不得携带与食品生产无关的个人用品。' WHERE id = '677e5fd5-b49d-4516-accf-98bb12bba72e';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，从事接触直接入口食品工作的食品生产人员应当每年（A）进行健康检查，取得健康证明后方可上岗工作。健康检查每年一次是法定要求。' WHERE id = '678aec10-3581-483b-9f03-ad65621961a7';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，保健食品审评机构提出不予注册建议的，应当同时向注册申请人发出拟不予注册的书面通知（A），告知申请人享有依法申请复审的权利。' WHERE id = '67ad30ff-e587-4cbb-a5b8-5b459b799321';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，飞行检查（B）是指市场监督管理部门根据监督管理工作需要以及问题线索等，对食品生产经营者依法开展的不预先告知的监督检查。' WHERE id = '67c3a102-fd64-4ff9-b6c4-6becb59ddcfb';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品中真菌毒素限量》（GB 2761）规定，小麦粉中脱氧雪腐镰刀菌烯醇（DON，又称呕吐毒素）是主要真菌毒素污染指标，来源于小麦种植和储运过程中的镰刀菌污染。' WHERE id = '67cbe6b9-7e3c-4136-9f26-3d37ec85682d';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品添加剂使用标准》（GB 2760）及酶制剂相关标准规定，酶制剂可通过细菌（A）、放线菌（B）、真菌菌种（C）等微生物发酵提取制得，不包括病毒（D）。' WHERE id = '67d13f42-426c-4118-9a8a-8144e42816f1';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，食品生产经营者对应当召回的食品未依照本法规定召回或者停止经营的，县级以上人民政府食品安全监督管理部门可以责令其召回或者停止经营。' WHERE id = '67d44088-0058-45e4-855f-e65d95dd483a';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》第三条及《餐饮服务食品安全操作规范》规定，餐饮服务提供者应建立食品安全管理人员制度，明确负责人（A）、食品安全总监（B）、食品安全员（C）等岗位职责。' WHERE id = '67de4054-fa46-4832-a718-f8b439208aad';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》自2016年7月1日起施行（A，对应日期42552为Excel日期序列值，转换为2016年7月1日）。该办法规范了特殊医学用途配方食品的注册管理工作。' WHERE id = '67efa219-40ad-4768-8e00-1e980f7ffe08';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》5.1.8规定，废弃物应定期清除，易腐败的废弃物应尽快清除，废弃物堆放处应保持清洁。废弃物堆放在加工车间角落（A）会造成交叉污染，是错误的。' WHERE id = '67f7faea-2a85-4061-be6d-da401f16cff4';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》第四十三条规定，伪造、涂改、倒卖、出租、出借、转让婴幼儿配方乳粉产品配方注册证书的，由县级以上食品药品监督管理部门责令改正，给予警告，并处1万元以下罚款（A）。' WHERE id = '68051c40-016b-4c0a-bf86-beca4ca0ef57';
UPDATE public.questions SET analysis = '《网络食品安全违法行为查处办法》第十一条规定，网络食品交易平台提供者应当对申请进入平台的食品生产经营者实行实名登记和资质（A）审查，建立登记档案并及时核实更新。' WHERE id = '68055bc6-4301-4304-8580-dbb7ea4d3ded';
UPDATE public.questions SET analysis = 'GB 14881-2013规定，食品加工人员上岗前须进行卫生培训（B正确）。A错误（应每年体检），C错误（有皮肤损伤应调离），D错误（个人水杯不得带入车间）。' WHERE id = '68116228-52ed-43e0-a2f4-91c4f3b513c7';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，从业人员在食品处理区内不得戴戒指、耳环和项链，且不得穿工作服进厕所。穿工作服进厕所会将污染物带回食品加工区域，增加交叉污染风险。' WHERE id = '68195add-19a2-40d7-ba41-4b7765004dc9';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》6.3.2规定，食品加工人员工作过程中上厕所后，应洗手并消毒后方可继续从事食品生产活动。仅洗手不消毒不能满足卫生要求。' WHERE id = '681d0909-0cda-4330-b9a2-d726d75ee0ce';
UPDATE public.questions SET analysis = '《食品安全法》第四十七条规定，食品生产经营者应当建立食品安全自查制度，定期对食品安全状况进行检查评价。日常监督检查结果不能替代企业自行开展的食品安全自查结果。' WHERE id = '6871a45a-0e3b-4139-b49f-365986f3b1fa';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十五条规定，被吊销许可证的食品生产企业及其法定代表人、直接负责的主管人员自处罚决定作出之日起五年内不得申请食品生产许可。2017年被吊销，2020年（仅3年）不得重新申请。' WHERE id = '68828de5-2050-4078-987c-ae225cd403bb';
UPDATE public.questions SET analysis = '《保健食品管理办法》及《食品安全法》规定，从事保健食品批发业务的经营企业应建立销售记录制度，记录销售日期（A）、购货者信息（B）、保健食品保质期（D），但不需要记录购货者的食品经营许可证号（C）。' WHERE id = '6886776e-560b-4a09-b183-bbb7ad46d1a5';
UPDATE public.questions SET analysis = '鲜湿产品营养丰富且含水量高，是微生物生长的良好培养基。根据GB 14881及微生物控制相关要求，鲜湿产品易造成微生物（B）超标，需要严格控制生产环境卫生和贮存条件。' WHERE id = '689d1cb5-ccac-4de9-99de-47b47cf20701';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条明确规定禁止生产经营用非食品原料生产的食品或添加食品添加剂以外的化学物质。甲醇（A）、工业乙酸（B）、苏丹红（C）均为非食用物质或有毒有害物质，严禁用于食品生产。小苏打（碳酸氢钠）是GB 2760允许使用的食品添加剂，可用于焙制面包，D正确。' WHERE id = '68a9a6f6-1da6-47b4-b5e2-e9f2602f0f0b';
UPDATE public.questions SET analysis = '《食品安全法》第一百四十七条规定，违反本法规定，造成人身、财产或者其他损害的，依法承担赔偿责任。财产不足以同时承担民事赔偿责任和缴纳罚款、罚金时，先承担民事赔偿责任（B）。' WHERE id = '68b9a8fe-117b-4203-a0cb-b6c38ddcc25d';
UPDATE public.questions SET analysis = '酱腌菜产品可执行的标准包括：《酱腌菜》（SB/T 10439-2007，A）、《食品安全国家标准 酱腌菜》（GB 2714-2015，B）、《榨菜》（GH/T 1011-2007，C）以及企业自行制定的严于国标的企业标准（D）。' WHERE id = '68bb1bb5-3eb6-4ad8-b0fb-f90f69fed4bf';
UPDATE public.questions SET analysis = '国务院有关部门发布的公告包括：''三新食品''目录（A）、食药物质目录（B）、保健食品原料目录（C）、食品中可能违法添加的非食用物质名单（D）等，是食品安全监管的重要依据。' WHERE id = '68dba85c-254b-4b00-9ad6-86e3f207e500';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》第四十条规定，工作人员滥用职权（A）、超越法定职权（B）、对不具备资格的申请人准予注册（D）等情形，可以撤销婴幼儿配方乳粉产品配方注册。企业依法终止（C）属于注销情形。' WHERE id = '68eecad8-2f59-463a-987b-7dbe85ed97a8';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食源性疾病是指食品中致病因素进入人体引起的感染性、中毒性等疾病，不包括过敏性疾病。过敏性疾病是人体免疫系统对食物蛋白的异常反应，与食源性疾病的定义不同。' WHERE id = '68f89ccb-1329-4900-b503-d8cc2954e269';
UPDATE public.questions SET analysis = '《食品安全法》第四十八条规定，国家鼓励食品生产经营企业符合良好生产规范要求，实施危害分析与关键控制点体系（HACCP），对生产过程进行食品安全控制，提高食品安全管理水平。' WHERE id = '690169d0-5e89-43f3-af1d-a2d5e03d4072';
UPDATE public.questions SET analysis = '《食品安全法》第二十九条规定，对地方特色食品，没有食品安全国家标准的，省、自治区、直辖市人民政府卫生行政部门''可以''（而非''应当''）制定并公布食品安全地方标准。是选择性规定而非强制性规定。' WHERE id = '691fcb14-8bda-4610-bb1c-3e9a6fa40930';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》第四十四条规定，参与注册工作的申请受理（A）、专家论证（B）、技术审评（C）、现场核查（D）等机构和人员，应当保守在注册中知悉的商业秘密。' WHERE id = '692697e8-0e89-4aec-a198-f540c069dbea';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第七十五条规定，故意实施违法行为（A）、违法行为性质恶劣（B）、违法行为造成严重后果（C）的，对单位的法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员处以上一年度收入1-10倍罚款。' WHERE id = '693b936f-72eb-42f2-8ba7-7c0c401164da';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》第三十二条规定，食品生产许可证变更后，有效期不变。因迁址、工艺变化等原因变更的，有效期不变；因生产条件发生重大变化需要重新核查的除外。有效期''必须重新计算''说法错误。' WHERE id = '694bb318-b13a-4fc2-b246-ec8764f9f273';
UPDATE public.questions SET analysis = '《大豆肽粉》（GB/T 22492-2008）标准规定，大豆肽粉是以大豆粕或大豆蛋白等为主要原料，用酶解或微生物发酵法生产的，相对分子质量在5000以下（C），主要成分为肽的粉末状物质。' WHERE id = '6957117e-b8be-42bc-a44f-89efbfd90095';
UPDATE public.questions SET analysis = '《食品安全法》第一百二十八条规定，事故单位在发生食品安全事故后隐匿、伪造、毁灭有关证据的，责令停产停业，没收违法所得，并处十万元以上五十万元以下罚款。题干所述''五万元以上二十万元以下''处罚金额不正确。' WHERE id = '69682383-afee-4e23-b386-e672c77ab007';
UPDATE public.questions SET analysis = '《食品生产经营日常监督检查管理办法》第十六条规定，日常监督检查结果分为符合（B）、基本符合（C）、不符合（D）三种形式，没有''完全符合''的评定等级。' WHERE id = '6976ce38-9f78-4170-a38b-9f31d5290567';
UPDATE public.questions SET analysis = 'GB 7718-2011《预包装食品标签通则》4.3.1规定，乙醇含量≥10%的饮料酒、食醋、食用盐、固态食糖类、味精可以免除标示保质期。白砂糖（A）、食用盐（B）、味精（C）、白酒（D，酒精度54%）均可免除标示保质期。' WHERE id = '6976f276-7929-4df9-acc2-e3aaf7a48d2e';
UPDATE public.questions SET analysis = '《食品安全法》第四十条及《食品安全国家标准 食品添加剂使用标准》（GB 2760）规定，食品生产过程中不得超范围超限量使用食品添加剂。粮食加工品生产应严格遵守GB 2760规定。' WHERE id = '6980f164-8375-4b95-afce-93f95517ae1f';
UPDATE public.questions SET analysis = '《食品安全法》及《食品生产经营监督检查管理办法》规定，监督检查（B）是督促食品生产经营企业落实食品安全主体责任的必要方法，通过监督检查促使企业落实主体责任。' WHERE id = '69a67283-1ad3-4a92-b4cb-6b57f42b418c';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》及《食品经营许可审查通则》规定，利用自动设备跨省经营的，应当分别向食品销售者所在地和自动设备放置地点所在地省级市场监督管理部门报告（A），确保跨区域经营的有效监管。' WHERE id = '69c29550-a7f6-438f-9f53-416bfacd7b4e';
UPDATE public.questions SET analysis = '《食品安全法》第三十五条规定，从事食品销售（B）、餐饮服务（C）应当依法取得食品经营许可。食品生产（A）需取得生产许可，食用农产品销售（D）不需要取得经营许可。' WHERE id = '69c5d48c-1439-4396-8940-11592b8d9c53';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，从事食品批发业务的经营企业应当建立食品销售记录制度，记录和凭证保存期限不得少于产品保质期满后六个月；没有明确保质期的，保存期限不得少于二年（A）。' WHERE id = '69ddb2ba-4d0e-415b-b2fe-ac3bbd0f58fe';
UPDATE public.questions SET analysis = 'GB/T 21532-2008《蜂王浆冻干粉》标准规定，蜂王浆冻干粉是指通过真空（A）、冷冻（B）、干燥（C）方法加工制成的脱水蜂王浆粉末。' WHERE id = '69ebb8a3-10a4-4cf0-b02e-5e160500807b';
UPDATE public.questions SET analysis = '《食品生产经营风险分级管理办法》第十六条规定，市场监督管理部门每年对食品生产经营企业进行一次风险等级评定（D），根据评定结果确定下一年度监督检查频次。' WHERE id = '6a0f25bd-6a3d-4e07-b52f-69d3a2b8f21b';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》及《餐饮服务食品安全操作规范》规定，连锁食品经营企业总部依法对企业食品安全负总责，建立健全覆盖从总部到门店（包括直营、合营、加盟等）的食品安全管理体系。' WHERE id = '6a3ee063-6bce-4754-8dd1-4c41628f36d2';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第三十五条规定，被抽查人对快速检测结果有异议的，可以自收到检测结果时起4小时（B）内申请复检。复检不得采用快速检测方法。' WHERE id = '6a496e24-ed5e-4b5d-adbc-2ed07ba91522';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》第四十一条规定，被许可人以欺骗、贿赂等不正当手段取得注册证书的，由国家食品药品监督管理总局撤销注册证书，并处1万元以上3万元以下罚款；申请人在3年（C）内不得再次申请注册。' WHERE id = '6a4c3eff-fcb4-44ad-954b-02eda6f45822';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》5.1.8.4规定，贮存物品应与墙壁、地面保持适当距离（约10cm），以利于空气流通和清洁。食品原料等贮存物品不可直接放置在地面，也不可靠墙放置，以防受潮和虫害。' WHERE id = '6a54c935-5527-4f83-9c62-0dbf197120da';
UPDATE public.questions SET analysis = '《关于依法查处生产经营含金银箔粉食品违法行为的通知》明确规定，金银箔粉不属于食品添加剂，不得用于食品生产经营。食品销售者不得采购含金银箔粉食品及食用农产品，而非''加强进货查验''。' WHERE id = '6a5c7105-5e07-4df6-9403-987e0f8c1fb3';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，飞行检查指市场监督管理部门根据监督管理工作需要以及问题线索等，对食品生产经营者依法开展的不预先告知的监督检查。' WHERE id = '6a6aa37e-e4ff-4b3b-84f6-f59ffb3c9104';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》及连锁食品经营管理规范要求，企业总部统一查验的许可资质证明、产品合格证明文件等信息，门店应能及时查询，确保门店经营的食品来源可追溯。' WHERE id = '6a6b0ac2-cb35-44a4-a5b0-2e954ab32286';
UPDATE public.questions SET analysis = '《食品安全法》第二十五条规定，食品安全标准是强制执行的标准。食品安全标准具有高度专业技术性和科学严谨性，是食品安全领域唯一强制执行的标准，是食品安全监管制度的重要组成部分。' WHERE id = '6a890da4-d9fe-4eff-a623-9364d2dabdec';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》第三条规定，保健食品注册是指食品药品监督管理部门根据注册申请人申请，依照法定程序、条件和要求（C），对申请注册的保健食品的安全性、保健功能和质量可控性等相关申请材料进行系统评价和审评。' WHERE id = '6a919d91-06b0-4151-8d62-281d92017cc4';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条及《餐饮服务食品安全操作规范》规定，接触直接入口食品的从业人员患有痢疾、伤寒、甲肝、戊肝、活动性肺结核、化脓性皮肤病（C）等有碍食品安全疾病的，应立即调离岗位。' WHERE id = '6a982360-9ab4-4157-9ae5-002521a75444';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》第四十三条规定，国产保健食品注册号格式为''国食健注G+4位年代号+4位顺序号''，2016年开始实施新格式。国食健注G20140001（C）为2014年旧编号格式不正确。正确格式如G20160001。' WHERE id = '6a9bebe1-b24b-4d8e-a99c-ed8046baa3a9';
