UPDATE public.questions SET analysis = '《食品生产经营风险分级管理办法》第二十二条规定，市场监督管理部门对生产特殊食品和风险等级为C级、D级（C）的食品生产企业实施重点监督检查，增加监督检查频次。' WHERE id = '6aacedbc-8b02-4667-9b7f-1e656404174f';
