UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》6.4.2规定，应制定和执行虫害控制措施，定期检查和维护防鼠、防蝇等设施，包括纱帘、纱网、防鼠板、防蝇灯等，防止鼠类昆虫侵入。' WHERE id = '6adf4070-4126-4952-98bb-9d01de308821';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条及《食品经营过程卫生规范》（GB 31621-2014）规定，食品销售设施设备风险包括设备与食品品种数量不适应（A）、设备失效（B）、容器混用（C）、清洁剂影响安全（D）等。' WHERE id = '6af2def6-db22-4bc9-acf4-f182d3301748';
