UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》第五条规定，在依法配备食品安全员的基础上，大中型食品销售企业、连锁食品销售企业总部还应当配备食品安全总监，协助主要负责人做好食品安全管理工作。' WHERE id = '6b3d3be5-465f-4766-bf38-7436c2fb1620';
UPDATE public.questions SET analysis = '商业无菌是指食品经过适度的热力杀菌后，不含有致病性微生物，也不含有在通常温度下能在其中繁殖的非致病性微生物。题干中''不含有微生物''表述过于绝对，应为''不含有能繁殖的微生物''，故为错。' WHERE id = '6b55bca9-0159-498e-995a-02b46a214437';
