UPDATE public.questions SET analysis = '《食品生产许可管理办法》第五十条规定，许可申请人隐瞒真实情况或者提供虚假材料申请食品生产许可的，申请人在1年（A）内不得再次申请食品生产许可。' WHERE id = '6b6c3494-8c13-43c4-bbcf-c93a9beb6571';
