UPDATE public.questions SET analysis = '《学校食品安全与营养健康管理规定》第三十六条规定，中小学、幼儿园食堂不得制售冷荤类食品（C）、生食类食品、裱花蛋糕等高风险食品。新鲜水果、鸡蛋（熟制）可以制售。' WHERE id = '6b82a948-b0a7-4d63-9bb7-f8b2f078e33b';
UPDATE public.questions SET analysis = '《食品安全法》第三十五条规定，销售食用农产品（D）不需要取得食品生产许可信息。食品生产、销售和餐饮服务需取得相应许可。' WHERE id = '6b8c7ae1-9455-48dc-988a-d1072a2571c4';
UPDATE public.questions SET analysis = '《食品安全法》及《食品生产经营监督检查管理办法》规定，不合格食品生产经营者要积极配合市场监督管理部门的调查处理，不得拒绝、逃避。拒不配合将依法承担法律责任。' WHERE id = '6b8c7f43-8b7b-4129-8025-0f143e4c2cbc';
