UPDATE public.questions SET analysis = 'GB/T 17204-2021《饮料酒术语和分类》规定，酒类分为发酵酒（A）、蒸馏酒（B）、配制酒（C）、调香白酒（D）、其他酒、食用酒精六大类。' WHERE id = '6bb57152-dc8a-4e25-b88b-b7bb6ba8e17c';
UPDATE public.questions SET analysis = '《食品安全法》第四十二条及《食品生产通用卫生规范》（GB 14881-2013）规定，食品生产企业应建立记录制度，对采购（A）、生产（B）、检验（C）、销售（D）等环节详细记录，确保整个环节都能进行有效追溯。' WHERE id = '6bb82423-a069-4d93-9a17-097fbed43fb8';
UPDATE public.questions SET analysis = '《食品安全法》第三十条规定，国家鼓励食品生产企业制定企业标准，企业标准应符合严于食品安全国家标准或地方标准（B）的要求，在本企业适用。' WHERE id = '6bcfd81d-b79e-4a71-877e-4fae099a914b';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第五十二条规定，散装食品指在经营过程中无食品生产者预先制作的定量包装或者容器、需要称重或计件销售的食品。食品经营者在经营过程中进行的包装，不属于定量包装。' WHERE id = '6bd381d4-f974-469b-adc3-2664b9d8bfb1';
UPDATE public.questions SET analysis = '《食品安全法》第八十一条规定，同一企业不得用同一配方生产不同品牌的婴幼儿配方乳粉，以防止企业通过换牌变相提价或规避监管，确保婴幼儿配方乳粉质量安全。' WHERE id = '6be6f0a7-215b-44b2-99e6-52db19c30358';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条及GB 14881-2013规定，接触食品的设备、工具和容器应由无毒、无味、抗腐蚀、不易脱落的材料（A）制成，并应易于清洁和消毒。' WHERE id = '6bf37504-bc23-4157-bb17-e7f5a475038a';
UPDATE public.questions SET analysis = 'GB/T 10782-2021《蜜饯通则》规定，蜜饯是指以果蔬等为主要原料，添加（或不添加）食品添加剂和其他辅料，经糖（或蜂蜜，A/B/D）腌制等工艺制成的制品。' WHERE id = '6bf76e13-068f-42dc-b830-f2f6d1fda488';
UPDATE public.questions SET analysis = '《标准化法》第二条规定，团体标准是由学会、协会、商会等社会团体协调相关市场主体共同制定的标准，属于市场自主制定的、自愿采用的标准。' WHERE id = '6bfc3405-984a-4bed-975c-89f534cf5b76';
UPDATE public.questions SET analysis = '《食品安全法》第四十八条规定，国家鼓励食品生产企业（A）制定严于食品安全国家标准或地方标准的企业标准（C），实施危害分析与关键控制点体系/HACCP（D），提高食品安全管理水平。建立食品安全追溯体系也是国家鼓励的。' WHERE id = '6c1a5b60-c601-48ff-83b1-84903aaa40b7';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》6.4.2规定，应制定和执行虫害控制措施，定期检查和维护防鼠、防蝇等设施，包括纱帘、纱网、防鼠板、防蝇灯等，防止鼠类昆虫侵入。' WHERE id = '6c1e3e39-4fd5-412f-800e-d37de555967f';
UPDATE public.questions SET analysis = 'GB 29921-2021《食品安全国家标准 预包装食品中致病菌限量》规定，饼干属于烘焙食品（B）类别，其致病菌限量应符合烘焙食品的规定。' WHERE id = '6c1e5f72-9a60-49ec-a81c-bbc5a9dde7ce';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》5.1.2.2规定，排水系统入口应安装带水封的地漏等装置，以防止固体废弃物进入及浊气逸出，保持车间环境卫生。' WHERE id = '6c32d992-25c9-48d1-aa38-7aa50a8de863';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食品安全事故指食源性疾病、食品污染等源于食品，对人体健康有危害或者可能有危害的事故。' WHERE id = '6c39d583-2d1e-443d-9a67-f3e60aafbc8b';
UPDATE public.questions SET analysis = 'GH/T 18796-2012《蜂蜜》是供销合作行业标准（C），属于推荐性标准（D）。该标准规定了蜂蜜的术语定义、产品分类、要求、检验方法等，是蜂蜜产品质量控制的重要依据。' WHERE id = '6c39e28f-440e-4c94-91d3-6b75eae728d9';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第五十三条规定，食品补充检验方法可以用于对食品的抽样检验（A）、食品安全案件调查处置（B）、食品安全风险监测（C）、食品安全事故处置（D）等，作为食品安全监管的技术支撑。' WHERE id = '6c5edfaf-170d-44cb-9c7d-6f9b64059a1a';
UPDATE public.questions SET analysis = '《食品生产许可分类目录》及食用植物油生产许可审查细则规定，可以申请食用植物油生产许可的产品包括花生油、大豆油、菜籽油、橄榄油（B）、茶籽油（C）等，不包括桐油（A，工业用油）和蓖麻油（D，工业/药用）。' WHERE id = '6c705862-5ceb-4ded-9bd5-192837102132';
UPDATE public.questions SET analysis = '《食品生产经营日常监督检查管理办法》第十九条规定，日常监督检查结果为基本符合的食品生产企业应按期进行整改，并将整改情况报告食品安全监督管理部门。' WHERE id = '6c7bfe02-4026-40c9-8376-624ed8c5c3b0';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品经营过程卫生规范》（GB 31621-2014）规定，需冷冻的食品储存环境温度应不高于-18℃（A），以确保冷冻食品的品质和安全。' WHERE id = '6c91db0b-189e-42d3-9724-903106227a94';
UPDATE public.questions SET analysis = '《食品安全法》及《食品生产许可管理办法》规定，委托生产应选择持有有效食品生产许可、食品添加剂生产许可的生产者，其生产许可范围应涵盖受委托产品品种，并具备相应生产能力。' WHERE id = '6ca66d28-2440-4b57-9f79-33213fa86ab3';
UPDATE public.questions SET analysis = 'GB 7718-2011《预包装食品标签通则》4.1规定，预包装食品标签的强制性标识内容包括食品名称、配料表、净含量、生产者信息、生产日期、保质期等。贮存条件（C）在某些情况下可免除标示。' WHERE id = '6ca7bdd9-150c-4d46-b7f0-9d4a4cbbb20d';
UPDATE public.questions SET analysis = '《食品安全法》第四十八条规定，国家鼓励食品生产企业符合良好生产规范要求，实施危害分析与关键控制点体系（HACCP，C），提高食品安全管理水平。' WHERE id = '6cb6649f-cc2d-4ebc-8a94-8a50b848eb0c';
UPDATE public.questions SET analysis = '《学校食品安全与营养健康管理规定》第十二条规定，学校食堂应当建立健全并落实食品安全管理制度，执行经营过程控制（B）、从业人员健康管理（C）、食品安全自查（D）等制度，确保校园食品安全。' WHERE id = '6cd003b0-e5c6-4933-bc14-595384ad94e6';
UPDATE public.questions SET analysis = '《食品安全法》第八十一条及GB 10765-2010《食品安全国家标准 婴儿配方食品》规定，婴幼儿辅助食品生产企业应科学设置产品配方、加工工艺和工艺参数，新产品、新工艺应进行安全性验证，确保有必要措施保障食品安全水平。' WHERE id = '6cd7172b-b858-4e21-bfa1-dab6b9ad3def';
UPDATE public.questions SET analysis = '《食品安全法》第三十五条规定，从事食品生产、食品销售、餐饮服务，应当依法取得许可。销售食用农产品（D）不需要取得许可。' WHERE id = '6d12b58b-64ac-44c8-9135-fcbb959e5d6b';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》第九条规定，生产和进口使用保健食品原料目录以外原料的保健食品（C）、首次进口的保健食品（D，属于补充维生素、矿物质等营养物质的除外）应当申请保健食品注册。' WHERE id = '6d199980-0e61-48da-ac4b-35d8f44fd8ab';
UPDATE public.questions SET analysis = '《网络食品安全违法行为查处办法》规定，通过网络销售保健食品应在经营活动主页面公示产品注册证书或备案凭证、营业执照、食品生产经营许可证等信息。不需要公示生产企业的研发报告（D）。' WHERE id = '6d3a810f-f293-4f76-95c2-f219440dd503';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》4.1.3规定，厂房和车间应根据产品特点、生产工艺、生产特性以及生产过程对清洁程度的要求合理划分作业区，并采取有效分离或分隔。灌装与外包装工序应有效隔离（B正确），清洁作业区与准清洁作业区不得共用（A错），配料室与熟制车间应分隔（C错）。' WHERE id = '6d439113-d2a5-4ade-ad9b-548955f5f92a';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第四十条规定，食品经营者收到监督抽检不合格检验结论后，应在被抽检经营场所显著位置公示相关不合格产品信息，公示时间不少于30日。' WHERE id = '6d5865f4-baee-4700-be2f-d12a342ef8c2';
UPDATE public.questions SET analysis = '《食品安全法》及食糖生产许可审查细则规定，食糖加工企业应通过危害分析（B）明确生产过程中的食糖安全关键环节，并设立相应的控制措施，实施HACCP管理体系。' WHERE id = '6d74596a-4683-4ff5-919e-6b917d1ec05e';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》5.1.8.4规定，仓库内的贮存物品应与墙壁保持10cm以上距离，与地面保持适当距离，以利于空气流通及物品搬运，防止受潮和污染。' WHERE id = '6d786d6b-b40b-4738-897b-d30bb5ff7b84';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》第三条规定，食品生产经营企业应当建立健全主要负责人负总责，食品安全总监、食品安全员分级负责的食品安全责任体系。' WHERE id = '6d9cdf25-dcbe-4834-b45f-e7192d12fb28';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第二十七条规定，食品经营者地址迁移，不在原许可经营场所从事食品经营活动的，应当重新申请食品经营许可，而非申请变更。' WHERE id = '6da9e0ce-aeb7-4408-b7b0-a7bed9dcb229';
UPDATE public.questions SET analysis = 'GB 14880-2012《食品安全国家标准 食品营养强化剂使用标准》规定，巧克力、代可可脂巧克力及其制品中允许强化的维生素有明确规定。维生素A（A）、维生素D（B）、维生素E（C）、维生素K（D）等品种不能用于巧克力及其制品的强化。' WHERE id = '6db47e2d-2d2c-430f-9ee1-fa61d8f2ea4f';
UPDATE public.questions SET analysis = '《食品安全法》第七十三条规定，食品广告不得含有虚假内容，不得涉及疾病预防、治疗功能，不得利用（广告代言人，A/B/C/D）向消费者推荐食品。食品广告应当真实合法，符合食品安全要求。' WHERE id = '6dec1c64-ab07-43e0-8833-7af66cb0d99d';
UPDATE public.questions SET analysis = 'HACCP是Hazard Analysis and Critical Control Point的缩写，即危害分析与关键控制点（D）。HACCP是预防性的食品安全控制体系，通过对原料、加工、储运等各环节的危害分析，确定关键控制点并实施监控。' WHERE id = '6df3d79d-9588-4a0a-a713-9ca5f83fbc38';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条及GB 14881-2013规定，食品生产企业应配备与生产能力相适应的生产设备，并按工艺流程有序排列，避免引起交叉污染，确保食品安全。' WHERE id = '6e0839e6-db53-4747-b666-851f5749d54e';
UPDATE public.questions SET analysis = '《食品生产经营风险分级管理办法》第七条规定，食品生产企业风险等级从低到高划分为A级、B级、C级、D级（A）四个等级，根据静态风险因素、动态风险因素和通用风险因素量化评分确定。' WHERE id = '6e31c10f-4530-4852-9f7b-75d2563c388c';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》2.9和2.10规定，进入专间和存放在专用操作区的食品应为直接入口食品，应避免受到存放在专间和专用操作区的非食品的污染，防止交叉污染。' WHERE id = '6e368207-ab10-41ce-815d-0fc3f9f4ee8d';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》第十三条规定，受理或者不予受理保健食品注册申请，应当出具加盖国家食品药品监督管理总局行政许可受理专用章（D）并注明日期的书面凭证。' WHERE id = '6e37f65e-9953-49d2-b051-4aca4f648660';
UPDATE public.questions SET analysis = 'GB/T 22493-2008《大豆蛋白粉》规定，大豆分离蛋白是通过提取（A）、分离（B）、精制（C）、干燥（D）等工艺，去除或部分去除大豆中的非蛋白成分而制得的产品。' WHERE id = '6e3af5dc-b733-4e2d-92a2-7b590034de62';
UPDATE public.questions SET analysis = 'GB 7718-2011《预包装食品标签通则》4.1.3.1.3规定，如果直接加入食品中的复合配料已有国家标准、行业标准或地方标准，并且其加入量小于食品总量的25%，则不需要标示复合配料的原始配料。' WHERE id = '6e4838f5-a70d-4a8d-b34a-a9a7c5f1f442';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第四十九条规定，食品经营许可证载明的主体业态、经营项目等许可事项发生变化，未按照规定申请变更的，由县级以上地方市场监督管理部门依照《食品安全法》第一百二十二条（D）给予处罚。' WHERE id = '6e5273af-ee90-4118-93a7-f642cfc86c2e';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》2.21定义，餐饮服务管理指为餐饮服务提供者提供食品处理（A）、加工（B）、配送（C）等服务的第三方管理活动。' WHERE id = '6e5dd314-8884-46a4-b335-eb92670382e9';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品的贮存和运输应符合食品安全所需的温度、湿度等要求，不得与有毒有害物品一同贮存运输。食品的贮存和运输必须遵守《食品安全法》的规定。' WHERE id = '6e5f0bd7-fd04-4ce0-9efb-8f2a435b6de9';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品经营者应具有与经营规模相适应的经营场所和设备设施，保持环境整洁。食品经营场所与非食品经营场所未分开设置（C）不符合食品安全要求。' WHERE id = '6e6ccbe5-8338-4e91-8039-9ff13fec78d6';
UPDATE public.questions SET analysis = '《食用农产品市场销售质量安全监督管理办法》第十五条规定，批发市场开办者应当与入场销售者签订食用农产品质量安全协议，未签订协议的，不得进入批发市场进行销售。' WHERE id = '6e6f7aef-1806-421c-bbfb-5f334c03430a';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，跨省承包经营集中用餐单位食堂的，应向集中用餐单位食堂所在地和营业执照标注的住所或主要经营场所所在地县级（A）市场监督管理部门报告。' WHERE id = '6e704a36-6dfd-443f-b86b-de279560cd10';
UPDATE public.questions SET analysis = '《行政处罚法》第七十三条规定，当事人对行政处罚决定不服申请行政复议或提起行政诉讼的，行政处罚不停止执行（法律另有规定的除外）。题干说''中止执行''是错误的。' WHERE id = '6e7a4727-822c-4efd-a295-560a6e5251eb';
UPDATE public.questions SET analysis = '《食品安全法》第四条规定，食品生产经营者是食品安全第一责任人，对其生产经营食品的安全负责。不合格食品生产经营者应深入查找不合格原因，落实整改措施。' WHERE id = '6e8f1c86-9fb0-4826-9b5c-3bf17cb5cbcc';
UPDATE public.questions SET analysis = '《食品安全法》第四十二条及《食品追溯管理办法》规定，追溯食品生产经营者应当按照规定上传准确、规范、完整的电子化追溯信息，确保食品来源可追溯、去向可查证。' WHERE id = '6e95f48f-7c6c-4174-93a5-13e08307eecf';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》2.18定义，集体用餐配送单位指主要服务于集体用餐单位，根据其订购要求，集中加工、分送食品但不提供就餐场所的餐饮服务提供者。题干中''提供就餐场所''说法错误。' WHERE id = '6ea511c4-78a4-4f4f-98ed-1858684c7fc6';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品生产通用卫生规范》6.3规定，食品生产企业卫生管理要求：应制定食品加工人员和卫生管理制度（A）；厂房内各项设施应保持清洁，及时维修或更新（B）；应防止造成食品污染（D）。' WHERE id = '6ea9ab33-c5fc-4014-b22a-d9d4b8ab16b1';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》及GB 31654-2021规定，餐饮服务经营场所应距离粪坑、污水池、暴露垃圾场（站）、旱厕等污染源25米（A）以上，位于粉尘、有害气体、放射性物质和其他扩散性污染源的影响范围外。' WHERE id = '6eb4e71a-19a2-438a-91bf-c458fe12d7ad';
UPDATE public.questions SET analysis = '《食品安全法实施条例》及《企业落实食品安全主体责任监督管理规定》要求，食品安全管理人员应参加企业组织安排的食品安全法律法规、标准和专业知识培训和考核。' WHERE id = '6ed67193-ddde-4053-9fa1-840ef7beee29';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）规定，用于监测、控制、记录的设备，如压力表、温度计、记录仪等，应定期校准（C）、维护，确保数据准确可靠。' WHERE id = '6ee0bc51-869f-46e0-9f8e-3b01bb03e543';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》第六条规定，食品销售企业主要负责人应明确食品安全责任体系、食品安全管理制度、食品安全风险防控机制、食品安全事故处置方案等相关制度机制（D）。' WHERE id = '6ef5c683-836d-41bb-95f4-a04e00e2a34f';
UPDATE public.questions SET analysis = '《食品安全法》第七十三条规定，食品广告内容应真实合法，保健食品广告应经广告审查机关审查。一般食品（如大米、食用油等，D）的广告内容不需经市场监管部门审查批准，但不得含有虚假内容。' WHERE id = '6f03534e-d93e-412f-9d40-0a4df5ff564d';
UPDATE public.questions SET analysis = '《食品安全法》第六十四条规定，食用农产品批发市场（D）应当按照规定设立或委托检测机构，对进场销售的农产品质量安全状况进行抽查检测，发现不符合食品安全标准的，应要求销售者立即停止销售。' WHERE id = '6f2adba7-b79b-45c1-ad45-9bb94227ac52';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》及《食品安全法》规定，一次性餐（饮）具使用后应废弃，不应重复使用，以防交叉污染和疾病传播。' WHERE id = '6f353d67-e50a-4596-bfdf-b46bfcafcc76';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）规定，食品加工设备应采用无毒、无味、抗腐蚀、不易脱落的材料制作。铜制材质易与食品中的成分发生化学反应，产生铜离子溶出，可能危害人体健康，故油炸设备不得使用铜制材质。' WHERE id = '6f3c600e-106c-43b2-b7f0-cf1b2198707c';
UPDATE public.questions SET analysis = '《食品安全法》第五十四条规定，食品经营者应当按照保证食品安全的要求贮存食品，定期检查库存食品，及时清理变质或超过保质期的食品。食品贮存应离地、离墙摆放，而不是落地摆放，以防止受潮、污染和虫害。' WHERE id = '6f5ee541-2e06-4faf-b61c-ae57c0fcc5ad';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》规定，境外生产企业的抽样检验时限根据实际情况确定，不受固定时间限制，因为涉及跨境检验、通关等环节，时间差异较大。' WHERE id = '6f699be1-a31b-4ba6-9139-c5831a62bc90';
UPDATE public.questions SET analysis = '《网络餐饮服务食品安全监督管理办法》第十八条规定，入网餐饮服务提供者应当在自己的加工操作区内加工食品，不得将订单委托其他食品经营者加工制作。这是为了确保食品加工过程的可控性和食品安全责任的明确性。' WHERE id = '6f78214a-1a3d-4a9f-bc15-3a18dff29ef6';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》第四十五条规定，保健食品备案的产品配方、原辅料名称及用量、功效、生产工艺等应当符合法律、法规、规章、强制性标准以及保健食品原料目录技术要求的规定。' WHERE id = '6f802526-90d4-487a-ae4b-62e197bc9438';
UPDATE public.questions SET analysis = '《食品安全国家标准 蛋与蛋制品》（GB 2749-2015）规定了蛋制品的食品安全指标，包括污染物限量（GB 2762）、农药残留（GB 2763）、微生物限量（GB 29921）和兽药残留（GB 31650）等。' WHERE id = '6f948602-41e5-456f-a5ae-1bf38ce41764';
UPDATE public.questions SET analysis = '折光仪用于测定折射率，适用于糖度、可溶性固形物等检测项目。灰分检验需要电热板（碳化）、马弗炉（高温灼烧）和干燥器（冷却称量），不需要折光仪。' WHERE id = '6f94c407-dfca-411f-bbd2-7579a54322a1';
UPDATE public.questions SET analysis = '炒货食品及坚果制品在加工过程中，如卫生条件控制不当，易导致微生物污染，如菌落总数、大肠菌群、霉菌超标。GB 19300-2014《食品安全国家标准 坚果与籽类食品》对微生物限量有明确规定。' WHERE id = '6fb85137-6841-4361-bfbd-6061c4cd8c7c';
UPDATE public.questions SET analysis = '《食品安全国家标准 包装饮用水》（GB 19298-2014）规定，饮用天然水是以水井、山泉、水库、湖泊或高山冰川等自然来源的水，允许采用脱气、曝气、倾析、过滤、臭氧化或紫外线消毒等不改变水基本理化特征的处理工艺。' WHERE id = '6fb95705-7730-4abf-b235-24b6cedd2845';
UPDATE public.questions SET analysis = '《食品安全法》第四十二条规定，食品生产经营者应当依照本法的规定，建立食品安全追溯体系，保证食品可追溯。国家鼓励食品生产经营者采用信息化手段实现食品可追溯。' WHERE id = '7016998d-e2c0-47bb-85ee-1161ded346fc';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》（市场监管总局令第60号）第十二条规定，食品安全总监和食品安全员发现有食品安全事故潜在风险的，应当提出停止相关食品生产经营活动等否决建议，企业应当立即分析研判，采取处置措施，消除风险隐患。' WHERE id = '702dac0b-f667-4cfd-abcc-5f1052101eb8';
UPDATE public.questions SET analysis = '《食品安全法》及相关规定明确，取得食品经营许可证或进行仅销售预包装食品备案的销售者可以委托生产食品、食品添加剂，但委托生产的食品应当符合食品安全标准，委托方对食品安全负责。' WHERE id = '702e5fd8-ecb9-4e79-8222-c8b21754ea9d';
UPDATE public.questions SET analysis = '饮料生产过程中，若加工环境卫生条件不佳、设备清洁消毒不彻底、人员卫生管理不到位等，易导致菌落总数、大肠菌群等微生物指标超标。GB 7101《饮料》对微生物限量有明确规定。' WHERE id = '70608ec6-0ad1-4913-9b62-6ad7be9b47c9';
UPDATE public.questions SET analysis = '《食品安全法》第二十六条规定，食品安全标准包括：致病性微生物、农药残留、兽药残留、生物毒素、重金属等污染物质的限量规定；标签、标志、说明书要求；与食品安全有关的质量要求；食品检验方法与规程等。' WHERE id = '7061ab79-535c-4fed-830d-0c171478121d';
UPDATE public.questions SET analysis = '《食品安全法》第六十七条规定，预包装食品的包装上应当有标签，标签应当标明名称、规格、净含量、生产日期、成分或配料表、生产者名称地址联系方式、保质期、产品标准代号、贮存条件等。' WHERE id = '706314fa-952e-438e-aa34-92dd840b0c84';
UPDATE public.questions SET analysis = '《食品安全法》第七十三条规定，消费者组织不得以收取费用或者其他牟取利益的方式向消费者推荐食品。消费者组织推荐食品应当是公益性质，不得从中获利。' WHERE id = '707906c8-4402-487a-8899-41a3584993fd';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，食品安全信用信息包括食品生产经营者基础信息、行政许可信息、检查信息、食品监督抽检信息、行政处罚信息等，不包括风险分级信息。' WHERE id = '7091cadb-e4d2-4ff8-bcda-219422ba5b4f';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》规定，申请人在产品配方注册后5年内未按照注册配方组织生产的，不予延续注册。这是为了防止注册配方长期闲置。' WHERE id = '7095a933-05bd-4e43-9838-0389c020311d';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，市场监督管理部门对高风险食品生产经营企业实施重点监督检查，并可以根据实际情况增加日常监督检查频次，而非增加体系检查频次。' WHERE id = '7099544e-2cff-4553-aac7-87f4b1172e82';
UPDATE public.questions SET analysis = 'GB 19295-2021《食品安全国家标准 速冻面米与调制食品》适用于速冻面米生制品、速冻面米熟制品和速冻调制食品，不包括速冻水产制品（另有GB 10136标准）。' WHERE id = '70a5420b-a351-4d0f-9f5d-97fd798d7b6f';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》第三十一条规定，食品生产者应当妥善保管食品生产许可证，不得伪造、涂改、倒卖、出租、出借、转让。违反者将受到相应处罚。' WHERE id = '70c0a4e9-8c99-4c81-8fe0-ab92a6fcbde1';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》明确，企业主要负责人对本企业食品安全工作全面负责，而非食品安全管理人员。食品安全管理人员承担日常管理职责，但最终责任由主要负责人承担。' WHERE id = '70da1fe2-13d3-4de4-89cd-489d3a2a2b7a';
UPDATE public.questions SET analysis = '《食品安全法》第五十条第二款规定，食品生产企业应当建立进货查验记录制度，如实记录食品原料、食品添加剂、食品相关产品的名称、规格、数量、生产日期或生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容。' WHERE id = '70da9a46-d4e8-4c23-86fb-c5fa1d5e7ca2';
UPDATE public.questions SET analysis = '黄酒属于发酵酒类，酒精含量较高（一般≥8%），微生物在其中难以生长繁殖，因此不属于微生物风险较高的食品。微生物风险较高的食品通常是水分活度高、营养丰富且pH值接近中性的食品。' WHERE id = '70ea8ee1-aefd-4c16-9b25-a48653246928';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》第十六条规定，食品生产经营企业应当组织对本企业职工进行食品安全知识培训，对食品安全总监、食品安全员进行法律、法规、标准和专业知识培训、考核。' WHERE id = '71022739-23c4-4369-9ac0-34faf7a4a004';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》规定，特定全营养配方食品需要进行临床试验的，由申请人委托符合要求的临床试验机构出具临床试验报告，报告应包括完整的统计分析报告和数据。' WHERE id = '71090700-bb1e-4dbb-929d-c7a20a7b2d3e';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》将体系检查定义为：市场监督管理部门以风险防控为导向，对特殊食品、高风险大宗食品生产企业和大型食品经营企业等的质量管理体系执行情况依法开展的系统性监督检查。' WHERE id = '71179985-21cd-42d7-9d25-a5f40a3167a4';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品添加剂使用标准》（GB 2760）规定，食品生产者不应掩盖食品本身或加工过程中的质量缺陷或以掺杂、掺假、伪造为目的而使用食品添加剂。增加营养不属于禁止使用食品添加剂的目的。' WHERE id = '712a53fc-30ac-4f86-a099-9c4d21204358';
UPDATE public.questions SET analysis = '《乳品安全国家标准》和卫生部公告明确规定，乳制品中三聚氰胺限量≤2.5mg/kg。该限量是为防止人为添加而设定的管理限量，不是天然本底值。' WHERE id = '712befdb-563a-423c-889c-c59c1faf2e2d';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，半成品制售项目仅限于中央厨房申请，其他餐饮服务提供者不得申请半成品制售项目。' WHERE id = '7134f8b3-aadf-4f0a-8d24-287d62419600';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十四条规定，食品生产经营者在一年内累计三次因违反本法规定受到责令停产停业、吊销许可证以外处罚的，由食品安全监督管理部门责令停产停业，直至吊销许可证。题中为"一次"，故错误。' WHERE id = '713cc96b-5168-454f-ab04-9da8673f049f';
UPDATE public.questions SET analysis = '《食品安全国家标准 可可制品》（GB 9678.2）规定，可可制品包括可可粉、可可脂、可可液块、可可饼块等。因此以上选项都是可可制品。' WHERE id = '714b0748-edce-451d-a6f5-06e499a1b394';
UPDATE public.questions SET analysis = '《食品安全法》第二条规定，在中华人民共和国境内从事食品生产和加工、食品添加剂的生产、食品的贮存和运输、食品生产企业使用食品添加剂和食品相关产品等活动，应当遵守本法。' WHERE id = '716837a8-a474-4047-9c0f-dc02bf92b112';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营者采购食品，应当查验供货者的许可证和食品出厂检验合格证或者其他合格证明。从生产单位采购时应查看其生产许可证，核对采购食品是否属于生产许可种类。' WHERE id = '716aa6d1-e23c-471c-bd00-4affa676eacb';
UPDATE public.questions SET analysis = '《食品安全法》第六十八条规定，食品经营者销售散装食品，应当在散装食品的容器、外包装上标明食品的名称、生产日期或者生产批号、保质期以及生产经营者名称、地址、联系方式等内容。' WHERE id = '716de7bb-2bd8-46c9-b620-5760071b40e3';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营应当符合食品安全标准，并符合贮存、运输和装卸食品的容器、工具和设备应当安全、无害，保持清洁，防止食品污染。洗涤剂、消毒剂属于有害物品，不得与食品同场所存放。' WHERE id = '716f845a-3960-4c3c-b31c-f0c3da1add9a';
UPDATE public.questions SET analysis = '《食品安全法》第四十二条规定，食品生产经营者应当依照本法的规定，建立食品安全追溯体系，保证食品可追溯。国家鼓励食品生产经营者采用信息化手段实现食品可追溯。' WHERE id = '7181d6ce-c64a-4bf2-b8a1-90f41fbc6bf2';
UPDATE public.questions SET analysis = '《食品安全法》第三十八条规定，按照传统既是食品又是中药材的物质目录由国务院卫生行政部门会同国务院食品安全监督管理部门制定、公布。食品中可以添加该目录中的物质，而非不得添加。' WHERE id = '718e26d5-3bf6-4fd0-b9cb-c8fa1119730c';
UPDATE public.questions SET analysis = '国务院有关部门发布的相关公告包括：新食品原料、食品添加剂新品种、食品相关产品新品种（统称三新食品）目录，食药物质目录，保健食品原料目录，以及食品中可能违法添加的非食用物质和易滥用的食品添加剂名单等。' WHERE id = '71ccf988-6840-473a-a34e-c23b8c1c7c4f';
UPDATE public.questions SET analysis = '《食品安全法》第四十六条规定，食品生产企业应当就食品的运输和交付控制方面制定并实施控制要求，以保证所生产的食品符合食品安全标准。' WHERE id = '71cea685-63e3-4937-b89e-8feb3b47adc8';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，监督检查结果对消费者有重要影响的，食品生产经营者应当按照规定在食品生产经营场所醒目位置张贴或者公开展示监督检查结果记录表，并保持至下次监督检查。' WHERE id = '71d40100-8010-4770-8da8-4d2c5c8974e6';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第九条规定，申请食品经营许可，应当先行取得营业执照等合法主体资格。企业法人、合伙企业、个人独资企业、个体工商户等应当以营业执照载明的主体作为申请人。' WHERE id = '71dbc643-5ea4-4c51-b686-bcd21cbc49f0';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，日常监督检查结果为不符合，有发生食品安全事故潜在风险的，食品生产经营者应当立即停止食品生产经营活动，确保消费者健康安全。' WHERE id = '71dc465f-144f-419f-9d7e-dcaea77866a0';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第六十七条规定了《食品安全法》第一百二十三条情节严重的情形，包括：货值金额2万元以上、违法行为持续3个月以上、造成食源性疾病并出现死亡病例或30人以上食源性疾病、受到行政处罚后1年内再次实施同类违法行为等。' WHERE id = '71dfc6d5-6c09-4114-b9bb-fc4c55051bf8';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第九条规定，申请食品经营许可，应当先行取得营业执照等合法主体资格，而非税务登记证。税务登记证是税收管理所需，不是食品经营许可的前置条件。' WHERE id = '71e18e40-57a3-4e34-8e7e-acb0b696edb9';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营人员应当保持个人卫生，生产食品时，应当将手洗净，穿戴清洁的工作衣、帽。这是防止人为污染食品的基本要求。' WHERE id = '71f6197f-59cb-495b-8c3e-b5504c569d75';
UPDATE public.questions SET analysis = '酒类产品的关键环节防控措施涵盖原料控制（防止霉变、农药残留）、生产过程控制（防止甲醇、杂醇油超标）、检验控制（出厂检验）以及贮存、运输与交付控制（防止破损、污染）等全流程。' WHERE id = '72012355-5c53-4d3c-83e6-2caaac78b12c';
UPDATE public.questions SET analysis = '《食用农产品市场销售质量安全监督管理办法》规定，集中交易市场开办者应当建立入场销售者档案，销售者档案信息保存期限不少于销售者停止销售后6个月。' WHERE id = '72117693-13c6-4685-b87b-06f4b0aec736';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，具有热、冷、生、固态、液态等多种情形，难以明确归类的食品，应当按照食品安全风险等级最高的情形进行归类，而非最低的情形。' WHERE id = '7211aacb-cd5a-4ddf-ac49-a8ef24153dec';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，半成品指原料经初步或部分加工制作后，尚需进一步加工制作的非直接入口食品，不包括储存的已加工成成品的食品。已加工成成品的食品属于成品而非半成品。' WHERE id = '7214351f-ef28-43cd-88f9-2a98752c82a1';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第三十条规定，食品经营者应当妥善保管食品经营许可证，不得伪造、涂改、倒卖、出租、出借、转让。这是保证许可证管理秩序的法定要求。' WHERE id = '7219f06d-ee5c-47dc-8443-4080f7f32e66';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）要求，食品生产经营企业应当建立防止化学性污染的管理制度，分析可能的污染源和污染途径，制定适当的控制计划和控制程序。' WHERE id = '722da713-8886-49c5-acb9-a453c1e29a4e';
UPDATE public.questions SET analysis = 'GB 14881-2013规定，食品生产企业若发现验收不合格的食品原料，应在指定区域与合格品分开放置，做好明显标记，及时处理，防止误用。这是原料管理的基本要求。' WHERE id = '723ea437-ac7b-406f-810d-9d74c3cb22e3';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食品添加剂指为改善食品品质和色、香、味以及为防腐、保鲜和加工工艺的需要而加入食品中的人工合成或者天然物质，包括营养强化剂。' WHERE id = '7245af1c-6531-487e-a0e0-ee257a63b55a';
UPDATE public.questions SET analysis = 'GB 19295-2021规定，速冻食品标识应注明速冻、生制或熟制、即食或非即食，以及烹调加工方式。这是对消费者正确使用食品的指引要求。' WHERE id = '725a1ee7-5ae2-43c7-9b55-7d9d1fedf0be';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》规定，婴幼儿配方乳粉产品配方注册号格式为：国食注字YP+4位年代号+4位顺序号，YP代表婴幼儿配方乳粉。' WHERE id = '7275791f-258b-41e2-b403-d080296a221f';
UPDATE public.questions SET analysis = '国家市场监督管理总局、国家卫生健康委员会、海关总署联合发布的《关于依法查处生产经营含金银箔粉食品违法行为的通知》明确，金（银）箔、金（银）粉类物质不是食品添加剂，不能用于食品生产经营，商场超市不得售卖。' WHERE id = '727a72f1-8f98-4f2e-a55c-3e3dedf6b985';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，食品抽样检验可以由市场监管部门自行抽样，也可以委托承检机构抽样。委托抽样时，市场监管部门应加强对承检机构的监督管理。' WHERE id = '728f9160-4f28-46bb-b12a-66eb9d6743a1';
UPDATE public.questions SET analysis = 'GB 14881-2013规定，窗户玻璃应使用不易碎裂的材料，或采取必要的防护措施，以防止玻璃破碎后对食品造成污染。因此窗户玻璃材料有特殊要求。' WHERE id = '729761d1-dc70-41d0-9016-507a038d8f99';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》规定，食品安全自查是企业主动开展的内部检查活动，日常监督检查是监管部门的外部检查。企业自查与监管检查性质不同，不能相互替代。' WHERE id = '72a79aae-801e-4a25-b110-a2375a4dca5f';
UPDATE public.questions SET analysis = '常见的生物性危害包括致病性细菌及其产生的毒素、其他产毒生物（如产生真菌毒素的霉菌）、朊病毒、寄生虫和虫害等。这些生物性危害可通过多种途径污染食品，对人体健康造成威胁。' WHERE id = '72ae16f4-ac7a-4260-a849-4700aff86b7f';
UPDATE public.questions SET analysis = '《食品安全法》第七十条规定，食品添加剂应当有标签、说明书和包装，标签上应当载明食品添加剂字样。这是为了与食品区分，便于识别和管理。' WHERE id = '72bff065-1ea6-4ea9-896c-c1706a6b39c4';
UPDATE public.questions SET analysis = '食品生产中交叉污染的可能情形包括：生产车间工艺布局不合理（人流物流交叉）、防虫设施不足或放置不合理（虫害带入污染）、包装材料消毒不彻底（外源性污染）、车间洁净度不够（环境污染）等。' WHERE id = '72c7c812-217e-4643-b51d-b91fb3f8def2';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》规定，审评机构告知需要补正材料的，补正材料的时间不计算在审评时间内。这是为了保障申请人的合法权益，确保审评时间的公平性。' WHERE id = '72ebc2e6-a083-4313-9105-7e563f9014df';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品添加剂使用标准》（GB 2760）规定，使用食品添加剂应当在技术上确有必要，并在达到预期效果的前提下尽可能降低在食品中的使用量。这是食品添加剂使用的必要性和最小量原则。' WHERE id = '7301f2cd-aae1-4d22-8866-1ec130b707c8';
UPDATE public.questions SET analysis = '《食品安全法》第六条规定，县级以上地方人民政府实行食品安全监督管理责任制。上级人民政府负责对下一级人民政府的食品安全监督管理工作进行评议、考核。' WHERE id = '73061eca-24a7-4d0f-9305-d2dce46988da';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，从事接触直接入口食品工作的食品生产经营人员应当每年进行健康检查，取得健康证明后方可上岗工作。若患有国务院卫生行政部门规定的有碍食品安全疾病，不得从事接触直接入口食品的工作。' WHERE id = '730e1b2b-cdc2-4ceb-91e3-71db391000eb';
UPDATE public.questions SET analysis = '《食品安全法》第四十二条规定，食品生产经营者应当依照本法的规定，建立食品安全追溯体系，保证食品可追溯。国家鼓励食品生产经营者采用信息化手段实现食品可追溯。' WHERE id = '732434d1-db25-4ee6-91c2-0c35b08248ec';
UPDATE public.questions SET analysis = '《食品生产经营风险分级管理办法》规定，食品生产经营者动态风险因素包括生产经营条件保持、生产经营过程控制、管理制度建立及运行等。这些因素直接影响食品生产经营的实际风险水平。' WHERE id = '733570f8-bef8-436d-90c9-53316a7ef52c';
UPDATE public.questions SET analysis = 'GB 29921-2021规定，即食豆制品包括非发酵豆制品、发酵豆制品和大豆蛋白类制品，不包括大豆肽粉（属于其他类别）。' WHERE id = '733d3b55-e6fe-4c7b-a457-0ce4ea3d9699';
UPDATE public.questions SET analysis = '《食品安全法》及相关规定要求，食品经营者经营散装食品应有明显区域或隔离措施；经营直接入口的散装食品应防尘遮盖，设置隔离设施；提供专用取用工具等保证散装食品安全的措施。' WHERE id = '734d4c1d-c2a9-48b8-91dd-2ada61cccf8c';
UPDATE public.questions SET analysis = '常见的物理性危害包括金属或零部件碎屑、碎玻璃、碎石、碎骨、放射性物质、包装材料、人员佩戴的饰物以及因不适当的温度、光照等导致的食品性状发生的非预期改变等。' WHERE id = '734e76b2-b112-48f1-a227-b3656548e720';
UPDATE public.questions SET analysis = '《糕点术语》（GB/T 12140）规定，冷加工糕点是指在各种加热熟制工序后，在常温或低温条件下再进行二次加工的糕点。热加工糕点则是指以加热熟制为最终工艺的糕点。' WHERE id = '735544c6-1fd7-4e5a-a79d-7e298d7f81d7';
UPDATE public.questions SET analysis = '《食品安全法》第三十八条规定，按照传统既是食品又是中药材的物质目录由国务院卫生行政部门会同国务院食品安全监督管理部门制定、公布。食品中可以添加按照传统既是食品又是中药材的物质，而非不得添加。' WHERE id = '73555b89-0afd-4c61-8c3c-23f91660e2ef';
UPDATE public.questions SET analysis = '《食品生产许可分类目录》规定，冷冻饮品许可分类目录中品种明细包括：冰淇淋、雪糕、雪泥、冰棍、食用冰、甜味冰、其他冷冻饮品等。' WHERE id = '736a05a1-cc97-404b-aed3-fc71090f0912';
UPDATE public.questions SET analysis = '《碳酸饮料（汽水）》（GB/T 10792）规定，碳酸饮料的二氧化碳应为人工充入，不包括由发酵自身产生的二氧化碳气。由发酵自身产生二氧化碳气的属于发酵饮料。' WHERE id = '737450e4-a0de-404f-a465-96c86278bc0c';
UPDATE public.questions SET analysis = '《食品安全法》第一百一十条规定，县级以上人民政府食品安全监督管理部门对食品生产经营者进行监督检查时，食品生产经营者应当按照监督检查人员要求，在现场检查、询问和抽样检验等文书上签字或者盖章。' WHERE id = '73a13d62-f429-4793-a981-6ce21648959f';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十一条规定，消费者通过网络食品交易第三方平台购买食品，其合法权益受到损害的，可以向入网食品经营者或者食品生产者要求赔偿。网络食品交易第三方平台提供者不能提供入网食品经营者的真实信息的，由平台提供者赔偿。' WHERE id = '73ba011f-55e5-4179-9d02-8548c29e9059';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，对因标签、标志或者说明书不符合食品安全标准而被召回的食品，食品生产者在采取补救措施且能保证食品安全的情况下可以继续销售；销售时应当向消费者明示补救措施。' WHERE id = '73c1f353-6efb-4a08-b359-9b25b78cd28a';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，除注册商标作为商标名、通用名中含有符合国家规定的含字母及数字的原料名外，保健食品名称不得含有人名、地名、汉语拼音、字母及数字等。' WHERE id = '73e2bf35-2af7-486a-affb-b58be9605496';
UPDATE public.questions SET analysis = '食品生产经营者在实践中应根据食品危害的类型（如生物性、化学性、物理性）和特点（如来源、传播途径、危害程度等），选取对应的防控措施，建立有效的食品安全管理体系。' WHERE id = '73f18777-3c70-4aea-90a6-0c321cf7c66e';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》规定，特殊医学用途配方食品生产企业对其提供的标签、说明书的内容负责，应当确保标签、说明书内容真实、准确。' WHERE id = '741f8d18-e120-4442-8ed4-36985b1a06ca';
UPDATE public.questions SET analysis = '《学校食品安全与营养健康管理规定》规定，学校食堂从事接触直接入口食品工作的从业人员应当每年进行健康检查，取得健康证明后方可上岗工作，必要时应当进行临时健康检查。' WHERE id = '74471e17-98ad-49de-ba49-9027c23c8731';
UPDATE public.questions SET analysis = 'GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》鼓励企业应用危害分析与关键控制点体系（HACCP），对食品生产过程中的危害进行识别、评估和控制。' WHERE id = '744ae957-bcf6-4f34-b503-d0f2455e94c2';
UPDATE public.questions SET analysis = '《食品安全法》第六十九条规定，生产经营转基因食品应当按照规定显著标示，保障消费者的知情权和选择权。' WHERE id = '7459bad8-09f9-4f7e-96c6-7dac353da712';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食品保质期指食品在标明的贮存条件下保持品质的期限。超过保质期的食品不得销售。' WHERE id = '7484eac2-c89a-4b4b-9f8d-cec459c338fb';
UPDATE public.questions SET analysis = '《食品安全法》第二十八条规定，食品安全国家标准在发布前，其草案应当向社会公开，广泛征求意见。这是保障标准科学性、合理性和公众参与权的法定程序。' WHERE id = '748a94b8-57fc-4265-9c7d-98d39c8fcc9e';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，境外注册申请人委托境内代理机构办理保健食品注册事项的，应当提交经过公证的委托书原件以及受委托的代理机构营业执照复印件，以确保委托关系的真实性和合法性。' WHERE id = '749ba033-8d65-4287-a569-5e96eaf55ec8';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，食品安全管理人员应当掌握与其岗位相适应的食品安全法律、法规、标准和专业知识，具备食品安全管理能力。' WHERE id = '749ed97c-6ded-4157-9375-2392ebedce58';
UPDATE public.questions SET analysis = '《食品安全法》第一百零九条规定，县级以上人民政府食品安全监督管理部门根据食品安全风险监测和风险评估结果，结合食品生产经营者信用状况，确定监督管理的重点、方式和频次，实施食品安全风险分级管理。' WHERE id = '74a31ab7-4bd0-4160-85d3-6821117bd6f7';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，食品经营许可证发证日期为许可决定作出的日期，有效期为5年。需要延续的应当在届满前90个工作日至10个工作日期间提出申请。' WHERE id = '74c64341-b9dd-4d1f-834b-1c602304de49';
UPDATE public.questions SET analysis = '《食品安全国家标准 巧克力、代可可脂巧克力及其制品》（GB 9678.2）规定的微生物指标主要是沙门氏菌。巧克力类产品因富含油脂和糖分，沙门氏菌是其主要关注的致病菌。' WHERE id = '74ea20d8-3163-4523-90e8-d4d8e54b531e';
UPDATE public.questions SET analysis = '《食品安全国家标准 蛋与蛋制品》（GB 2749-2015）规定，蛋制品的感官指标包括色泽、滋味与气味、状态三个方面，是评价蛋制品质量的重要依据。' WHERE id = '7502ddb4-534e-4f8a-bc97-ab22f671afd6';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条及相关规定要求，餐饮服务企业、中央厨房、集体用餐配送单位、学校（含托幼机构）食堂应如实记录采购的食品、食品添加剂、食品相关产品的详细信息，并保存相关凭证。' WHERE id = '750cdb57-40a5-4469-ae39-49338fe2ed74';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》明确，企业主要负责人对本企业食品安全工作全面负责，应当落实企业食品安全管理制度，加强对食品安全工作的管理。' WHERE id = '7512c792-b361-4c32-b370-166a13511a5f';
UPDATE public.questions SET analysis = '《食品安全国家标准 食醋》（GB 2719-2018）规定，食醋生产使用的粮食类原料包括大米、高粱、玉米、糯米、小麦等。这是传统酿造食醋的主要原料。' WHERE id = '751c57e7-e3be-4524-8b83-1062e24d7f41';
UPDATE public.questions SET analysis = '《食品安全法》第七十九条规定，保健食品广告除应当符合食品安全法律、法规的规定外，还应当经广告主所在地省、自治区、直辖市人民政府确定的广告审查机关批准。保健食品广告不得与其他保健食品进行比较，不得明示或暗示产品为天然、安全等。' WHERE id = '751d8a41-44e6-4d70-a9b0-99187364e7cb';
UPDATE public.questions SET analysis = '《食品标识管理规定》第六条规定，食品标识应当直接标注在食品的最小销售单元或者其包装上。这是保证消费者能够获得食品信息的基本要求。' WHERE id = '752577dd-a4f0-4ab2-962f-adabdfd8565f';
UPDATE public.questions SET analysis = 'GB 14881-2013规定，食品生产企业应制定废弃物存放和清除制度，定期清除废弃物，对于易腐败的废弃物应尽快清除，以防止污染食品、孳生虫害和产生异味。' WHERE id = '753241cf-887c-487d-bf61-ce30df76cc47';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品与非食品、生食与熟食应当分开存放，贮存容器不得混用，固定存放位置并明确标识，防止交叉污染。' WHERE id = '75385150-be2d-46c7-acf5-1a241ea02087';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营者采购食品、食品添加剂，须查验供货者的许可证和食品出厂检验合格证或其他合格证明。这是进货查验制度的法定要求。' WHERE id = '75398f7c-488c-41a1-8418-0de23d575663';
UPDATE public.questions SET analysis = '糖果中不能添加使用的功能性物质包括牛磺酸（保健食品可用成分）、阿司匹林（药品）、二甲双胍（降糖药品）、苯磷硫胺（药品）等。糖果属于普通食品，不得添加药品和仅限保健食品使用的原料。' WHERE id = '7549dfdb-7322-4d29-8059-d6dac11c00d6';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，食品销售经营者食品经营项目分为预包装食品销售、散装食品销售、特殊食品销售、其他类食品销售等。特殊食品销售包括保健食品、特殊医学用途配方食品和婴幼儿配方乳粉等。' WHERE id = '754b96ed-7bf0-4f98-a06b-7a769b9e8334';
UPDATE public.questions SET analysis = '食品销售企业交接环节应当记录交接的运输工具、人员、运输方式等信息，以确保食品在运输过程中的可追溯性和安全性。' WHERE id = '754cc0e5-9f9c-45af-acad-4b6813858d96';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品添加剂使用标准》（GB 2760）规定，食品添加剂在规定的使用范围和限量内使用是安全的。含有合法使用食品添加剂的食品是安全的，不能简单地认为含有食品添加剂就不安全。' WHERE id = '7559c167-30fb-4980-9109-54038cac961e';
UPDATE public.questions SET analysis = '熟肉制品生产过程中，酱卤间、油炸间、发酵间属于熟制加工区域，腌制间属于原料预处理区域，不属于生熟加工区分界区域。生产布局应合理安排生熟加工分区。' WHERE id = '75643e6b-0643-4458-9004-ecbefba0103f';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，餐饮服务场所与外界直接相通的门、窗应安装空气幕、防蝇胶帘、防虫纱窗、防鼠板等设施，防止虫害和鼠害侵入。' WHERE id = '75770504-3dde-4bc9-b93e-efc779288bff';
UPDATE public.questions SET analysis = '方便面的主要工艺流程包括配粉、和面、熟化、压延、切条、蒸煮、油炸或热风干燥、冷却、包装等环节。这是方便面生产的基本工序。' WHERE id = '75805ee7-e19d-490a-80f6-69974cffaa02';
UPDATE public.questions SET analysis = '《食品安全法》第六十七条规定，食品安全国家标准对预包装食品的标签标注事项另有规定的，从其规定。这是特别规定优于一般规定的法律适用原则。' WHERE id = '758673e2-fc43-48a5-ad3c-e8ce93d4f889';
UPDATE public.questions SET analysis = '葡萄酒及果酒的基本生产流程包括原料选择、破碎（压榨）、发酵、分离、陈酿、调配、过滤、灌装等，不包括蒸煮。蒸煮是某些蒸馏酒或黄酒的工艺步骤。' WHERE id = '758d889c-b9ab-48c9-b55c-782e2e21afe0';
UPDATE public.questions SET analysis = '《食品召回管理办法》规定，标签、标识存在瑕疵，食用后不会造成健康损害的食品，食品生产者应当采取补救措施，可以继续销售，但需要向消费者明示补救措施。这属于主动召回的情形，而非自愿召回自愿改正。' WHERE id = '75c09c95-56b0-490f-8ebb-9e260959f069';
UPDATE public.questions SET analysis = 'GB 14881-2013规定，直接接触食品的设备或工具应具有无味、不易脱落、抗腐蚀、无毒等特性，以保证食品安全，防止污染食品。' WHERE id = '75c8c13c-2adf-49e3-ba93-bbf57a339268';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》规定，特殊医学用途配方食品的名称应当反映食品的真实属性，使用食品安全国家标准规定的分类名称或者等效名称。' WHERE id = '75c8f5fd-be25-4998-b349-078e0bb57082';
UPDATE public.questions SET analysis = '《网络食品安全违法行为查处办法》规定，已经取得食品生产许可的食品生产者在其生产加工场所或者通过网络销售其生产的预包装食品的，不需要另行备案。' WHERE id = '75e2ff26-d5dd-49e7-bf49-5fb50a10aa78';
UPDATE public.questions SET analysis = '《新食品原料安全性审查管理办法》规定，新食品原料生产单位应当按照新食品原料公告要求进行生产，保证新食品原料的食用安全。' WHERE id = '75e9ef86-f908-4776-a84f-cde1c8c2db5d';
UPDATE public.questions SET analysis = '《食品安全法》第五十条规定，食品经营者进货时未查验许可证和相关证明文件的记录保存期限不得少于产品保质期满后6个月，没有明确保质期的，保存期限不得少于2年。' WHERE id = '75f261c7-5b5d-4777-9a7d-e1d253d911e6';
UPDATE public.questions SET analysis = '《食品安全法》第一百零三条规定，发生食品安全事故时，食品生产经营者不得隐瞒、谎报、缓报事故，不得隐匿、伪造、毁灭有关证据，不得阻挠事故调查处理。' WHERE id = '75f92310-ce57-4e1a-bae7-56638a6565cb';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》（市场监管总局令第60号）第十条规定，食品生产经营企业应当建立基于食品安全风险防控的动态管理机制，制定食品安全风险管控清单，建立日管控、周排查、月调度工作制度和机制。' WHERE id = '75fddee7-5143-4dcf-905a-25a96d571efa';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，保健食品注册证书有效期为5年，有效期届满需要延续的，保健食品注册人应当在有效期届满6个月前申请延续。' WHERE id = '760dd4ee-6029-409d-8f1f-22751c83c836';
UPDATE public.questions SET analysis = '糖果的主要甜味来源是糖浆（如蔗糖糖浆、果葡糖浆等）。糖浆提供甜味，并赋予糖果适当的质地和口感。淀粉和麦芽糊精主要用作填充剂，果胶用于胶凝。' WHERE id = '761dce6d-8cbe-4bea-a0d8-1cb4619490ff';
UPDATE public.questions SET analysis = '国家市场监督管理总局等部门联合发布的通知明确，金银箔粉既不是食品添加剂，也不是食品原料，不得用于食品生产、销售，不得作为食品添加剂或食品原料使用。' WHERE id = '762127de-c3e7-42fb-887c-548e2c9d8393';
UPDATE public.questions SET analysis = '《食品安全法》第三十五条规定，国家对食品生产经营实行许可制度。销售食用农产品和仅销售预包装食品的，不需要取得许可；仅销售预包装食品的，应当报所在地县级以上地方人民政府食品安全监督管理部门备案。' WHERE id = '764a00fb-d68d-4b78-9880-8a7605f06073';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，保健食品注册是指对申请注册的保健食品的安全性、保健功能和质量可控性等相关申请材料进行系统评价和审评，并决定是否准予其注册的审批过程。均一性不属于注册审评的内容。' WHERE id = '765ba65c-80ad-4ebf-b0c4-fcdb537e6329';
UPDATE public.questions SET analysis = 'GB 14881-2013规定，食品生产企业库房中，汽油、清洁剂、消毒剂、杀虫剂、润滑剂等化学品应与食品成品分隔放置，防止交叉污染。这些化学品均具有潜在的食品安全风险。' WHERE id = '7668a713-3f63-4b5c-a755-4fc7af5c6d4c';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第二十七条规定，食品经营许可证载明的许可事项发生变化的，应当在变化后10个工作日内向原发证的食品药品监督管理部门申请变更经营许可。经营场所发生变化属于许可事项变更，应当重新申请。' WHERE id = '76765b60-b6c4-4f02-9536-8a428cdf59c5';
UPDATE public.questions SET analysis = '《食品生产许可分类目录》规定，生产许可类别编号1502为葡萄酒及果酒，包括葡萄酒、冰葡萄酒、其他特种葡萄酒、发酵型果酒等。' WHERE id = '767e11fc-e96c-41e7-8d07-72e3fa6c1d94';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，食品安全员每日根据风险管控清单进行检查，形成《每日食品安全检查记录》。食品安全总监每周组织排查，形成《每周食品安全排查治理报告》。' WHERE id = '76879494-e2f1-40ad-85d4-f8ac3279c20d';
UPDATE public.questions SET analysis = '《食品安全法》第二十五条规定，食品安全标准是强制执行的标准，食品生产经营者必须执行强制性标准。推荐性标准不是强制执行的，企业可以自愿采用。' WHERE id = '76cec3c6-9d09-4ca8-88eb-bbcb098d35d1';
UPDATE public.questions SET analysis = '花色挂面基本生产工艺为：原辅料预处理、调粉、熟化、压延、切条、干燥、截断、称量、包装。这是挂面生产的标准工艺流程。' WHERE id = '76d0acc8-0162-4bf8-8f1f-bd1f2799b879';
UPDATE public.questions SET analysis = '《食品安全法》第一百一十条规定，县级以上人民政府食品安全监督管理部门履行食品安全监督管理职责，有权进入生产经营场所实施现场检查，对食品进行抽样检验，查阅复制有关资料，查封扣押不符合食品安全标准的食品、工具和设备。' WHERE id = '76e44b8c-b37b-42cc-8cfe-0b8a2b3a0eb2';
UPDATE public.questions SET analysis = '糖果产品的微生物不合格项目主要是菌落总数和大肠菌群。糖果富含糖分，水分活度低，一般微生物难以繁殖，但生产环境控制不当仍可能导致微生物污染。' WHERE id = '76ed9129-482e-4081-9173-252134f4dcd8';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》规定，食品生产许可证有效期为5年。有效期届满需要延续的，应当在届满前90个工作日至10个工作日期间提出申请。' WHERE id = '76f3eec7-c4e8-41a6-818d-38d7db5b685e';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，取得食品生产许可的特殊食品生产者，通过网络销售其生产的特殊食品，不需要取得食品经营许可。这是为生产企业在自有网络渠道销售提供便利。' WHERE id = '76f76646-bbad-4f93-a37c-cd87f8a93a3f';
UPDATE public.questions SET analysis = '《食品安全国家标准 蒸馏酒及其配制酒》（GB 2757）和《食品安全国家标准 发酵酒及其配制酒》（GB 2758）规定，啤酒应以%vol（体积百分比）为单位标识酒精度。' WHERE id = '771cf1b2-6223-4563-8fbe-eddd50d934a9';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十五条规定，被吊销许可证的食品生产经营者及其法定代表人、直接负责的主管人员和其他直接责任人员自处罚决定作出之日起5年内不得申请食品生产经营许可，或从事食品生产经营管理工作。' WHERE id = '77273f5b-f68b-4b63-a6f2-733b9133dece';
UPDATE public.questions SET analysis = '《食品安全法》第八十七条规定，县级以上人民政府食品安全监督管理部门应当对食品进行定期或者不定期的抽样检验，并依据有关规定公布检验结果。这是食品安全监督管理部门的法定职责。' WHERE id = '772f3e85-1319-4199-9388-c0cfc53c7fb3';
UPDATE public.questions SET analysis = 'A型肝炎病毒和诺沃克病毒（诺如病毒）是水生生物容易感染的病毒，病毒可在水生生物体内存活数月，进而通过食用感染消费者。乙肝病毒和柯萨奇病毒不是通过水产品传播的主要病毒。' WHERE id = '774fa0a9-0363-437a-b7b6-d067cc9597c4';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》规定，申请人隐瞒真实情况或者提供虚假材料申请注册的，国家食品药品监督管理总局不予受理或不予注册，给予警告，申请人在1年内不得再次申请注册。' WHERE id = '775c6879-4155-4aa1-af1c-c6562dd9c5a7';
UPDATE public.questions SET analysis = '三新食品是指新食品原料、食品添加剂新品种、食品相关产品新品种。这三类食品原料或产品的安全性需要经过国家有关部门审查批准后方可使用。' WHERE id = '77660ba4-b2f0-4744-9208-99eda11cffeb';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）要求，企业应当采取适当的教育培训、现场管理、风险排查、相互监督等防控措施，防范人为故意造成的食品安全风险。' WHERE id = '7775dc51-a77f-4fd9-b4cd-d10ced21d0a6';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，废弃物存放设施应有盖，能够防止污水渗漏、不良气味溢出和虫害孳生，并易于清洁。废弃物存放设施应及时清洁，必要时消毒。' WHERE id = '777b019d-8610-430d-850c-5caa754da074';
UPDATE public.questions SET analysis = 'GB 14881-2013规定，包装破损的物料不得进入生产区域；企业采购的原辅料必须索要供货者的证明文件；不得将原料仓库用作配料操作间。过期原料应及时清理。因此A、C、D选项不正确。' WHERE id = '7790d874-a2c4-48f7-a439-a961ea1b0a04';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》规定，申请事项依法不需要进行注册的，受理机构应当即时告知申请人不受理；申请材料存在可以当场更正的错误的，应当允许申请人当场更正。' WHERE id = '7793d9c1-5d87-4f3a-850a-19c398f0d435';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，食品生产经营者应当在食品安全抽样文书上签字或者盖章，确认抽样过程和信息的真实性。' WHERE id = '779c2508-b60a-4970-9f94-8c2d41b14256';
UPDATE public.questions SET analysis = '油炸食品生产中，油炸后的产品应及时预冷并防止其在包装内形成冷凝水。冷凝水会导致产品受潮变软、微生物繁殖，影响产品质量和安全。' WHERE id = '779cd84e-a10c-4b96-8abf-fcb075e29628';
UPDATE public.questions SET analysis = '在饼干生产许可发证中，生产饼干碎的，应明确饼干品种（如酥性饼干碎），以便准确归类和管理，确保产品质量标准的适用性。' WHERE id = '77b95808-d549-4864-817d-b8cb6f1700a4';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十五条规定，被吊销许可证的食品生产者及其法定代表人、直接负责的主管人员和其他直接责任人员自处罚决定作出之日起5年内不得申请食品生产经营许可。2017年被吊销，2020年（仅3年后）不得重新申请。' WHERE id = '77c4f159-6914-4d73-8ac0-fcc68c0f52b3';
UPDATE public.questions SET analysis = '《食品添加剂生产许可审查细则》规定，食品添加剂生产中的原料选择时，标准中未作出规定的，企业应选择相应级别或更高质量级别的原料，以确保产品质量和安全。' WHERE id = '77c57447-49f5-456d-9e56-00a0a781a010';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，需要延续食品经营许可有效期的，应当在该食品经营许可有效期届满前九十个工作日至十个工作日期间向原发证的市场监督管理部门提出申请。这是正确的表述。' WHERE id = '77d64700-5077-40ea-a716-53f82fc5a0ce';
UPDATE public.questions SET analysis = '《食品安全国家标准 食用动物油脂》（GB 10146）规定，食用动物油脂是指由动物脂肪组织提炼出的固态或半固态脂类，经加工制成的食用动物油脂，包括猪油、牛油、羊油等。' WHERE id = '77d9d4c7-5e60-4a6b-83f9-740d81487b60';
UPDATE public.questions SET analysis = 'GB 7096-2014《食品安全国家标准 食用菌及其制品》规定，银耳中的米酵菌酸限量不大于0.25mg/kg，而不是木耳。银耳在特定条件下易产生米酵菌酸，是重要的食品安全控制指标。' WHERE id = '77dafab6-5578-4034-bc08-f09680bcca30';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》规定，婴幼儿配方乳粉产品配方注册申请人应当是拟在中华人民共和国境内生产并销售婴幼儿配方乳粉的生产企业，或者拟向中华人民共和国出口婴幼儿配方乳粉的境外生产企业。' WHERE id = '77dde61d-b67a-4cce-b45b-52e4ffdc6b25';
UPDATE public.questions SET analysis = '《食品安全法》第十二条规定，任何组织或者个人有权举报食品安全违法行为，依法向有关部门了解食品安全信息，对食品安全监督管理工作提出意见和建议。' WHERE id = '77f93c59-b816-4775-bf66-75dcfc5d6466';
UPDATE public.questions SET analysis = '《乳品质量安全监督管理条例》规定，乳制品生产企业应当对出厂的乳制品逐批检验，并保存检验报告，留取样品。这是确保每批产品安全合格出厂的法定要求。' WHERE id = '77ff28fc-3fa8-46b3-9e4b-7cb563270a2d';
UPDATE public.questions SET analysis = '非传统食品安全风险虽然防控难度大，但可以通过制定专门的食品防护计划进行预测和预防。食品防护计划是主动识别和控制潜在威胁的有效工具。' WHERE id = '781ef29c-9ca1-47f3-b874-200c5db16b22';
UPDATE public.questions SET analysis = '调味料生产企业生产用厂房应能满足原料处理、加工、调配、杀菌、后处理和包装的完整工艺要求。杀菌是调味料生产的关键步骤，必不可少。' WHERE id = '78236885-c6f0-4996-8459-ac8a2dbd72da';
UPDATE public.questions SET analysis = '淀粉糖生产企业的产品执行标准应为GB/T 20880（食用葡萄糖）、GB/T 20883（麦芽糖）、GB/T 20882.3（结晶果糖）等淀粉糖标准，不应为GB 1886.187（食品添加剂山梨糖醇标准），后者属于食品添加剂而非淀粉糖产品标准。' WHERE id = '7837de35-84e9-41b0-ac99-59a0f3b25328';
UPDATE public.questions SET analysis = '《行政诉讼法》第三条规定，被诉行政机关负责人应当出庭应诉。不能出庭的，应当委托行政机关相应的工作人员出庭。' WHERE id = '783b4cbd-daf6-4e73-b09c-cd02c982021e';
UPDATE public.questions SET analysis = '《食品安全国家标准 饼干》（GB 7100）规定，饼干是以谷类粉（和/或豆类、薯类粉）等为主要原料生产的产品，添加或不添加糖、油脂及其他配料。' WHERE id = '78441509-3519-44f4-9ea8-5b4133d0af94';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，外设仓库地址发生变化的，食品经营者应当在变化后10个工作日内向原发证的市场监督管理部门报告，而非向变化后仓库所在地的市场监督管理部门报告。' WHERE id = '7846b3aa-19c2-4f0c-a490-b52caa3fa5d5';
UPDATE public.questions SET analysis = '白酒中不允许添加甜蜜素。根据GB 2760，白酒（蒸馏酒）中不得使用甜蜜素。甜蜜素属于甜味剂，在白酒中的添加属于违法添加行为，是监管部门重点打击的违规行为。' WHERE id = '784e4a57-3747-4e65-9868-e4a6bd5f86d3';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》第四条规定，食品生产经营企业主要负责人应当落实企业食品安全管理制度，对本企业的食品安全工作全面负责。' WHERE id = '7861cee1-d96e-44d3-86c7-b1da311006c3';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，对因标签、标志或者说明书不符合食品安全标准而被召回的食品，食品生产者在采取补救措施且能保证食品安全的情况下可以继续销售；销售时应当向消费者明示补救措施。' WHERE id = '7862cde2-2e3e-4eb8-884e-8458e6d248a2';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，申请变更国产保健食品注册应提交的材料包括：保健食品注册变更申请表、注册申请人主体登记证明文件复印件、保健食品注册证书及其附件复印件、变更事项的证明材料等。' WHERE id = '78645cd1-d3fa-4bf2-bc69-d1e25c3a212a';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食品添加剂是为改善食品品质和色、香、味以及为防腐、保鲜和加工工艺的需要而加入食品中的人工合成或者天然物质。' WHERE id = '7870b44f-9d16-419b-978b-5329ff3d6d14';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》（市场监管总局令第60号）适用于食品生产经营企业主要负责人、食品安全总监和食品安全员。服务人员不在该规定的适用范围内。' WHERE id = '787a2c50-538a-4dde-95e1-35b3d8e89d4b';
UPDATE public.questions SET analysis = '《食品安全国家标准 味精》（GB 2720）规定，味精是指以碳水化合物（如淀粉、玉米、糖蜜等糖质）为原料，经微生物（谷氨酸棒杆菌等）发酵、提取、中和、结晶、分离、干燥而制成的具有特殊鲜味的调味品。' WHERE id = '787a4075-bf43-4163-af73-895ce4880770';
UPDATE public.questions SET analysis = '水果制品生产企业应加强操作人员的卫生意识培训，促使员工养成自觉的卫生习惯，包括手部清洁、穿戴工作服帽、操作规范等，以防止产品受到微生物污染。' WHERE id = '787c48d9-8cd2-46c1-bf9c-592329a82072';
UPDATE public.questions SET analysis = '《食品安全法》第四十条规定，食品添加剂应当在技术上确有必要且经过风险评估证明安全可靠，方可列入允许使用的范围。食品生产企业应当按照食品安全国家标准使用食品添加剂。' WHERE id = '789c39c0-446a-4e09-9d56-e4d376081d20';
UPDATE public.questions SET analysis = '《中华人民共和国刑法》第一百四十三条规定，生产、销售不符合食品安全标准的食品，对人体健康造成严重危害或者有其他严重情节的，处三年以上七年以下有期徒刑，并处罚金。' WHERE id = '78c118fd-8b43-42cb-96bf-bf056e5e0e71';
UPDATE public.questions SET analysis = '油炸型膨化食品生产过程中应控制油炸温度、时间和真空度及油脂品质变化情况。真空度影响油炸过程中水分的蒸发和产品的酥脆度，是关键工艺参数。' WHERE id = '78cda488-6bcd-4f93-a943-65e30e8077a4';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营者应当采取措施，改善食品储存、运输、加工条件，防止食品变质，降低储存、运输中的损耗。价格不属于此范畴。' WHERE id = '78df3192-aba3-447a-af6e-6f277e78c1d2';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，餐饮服务企业通过对动植物性原料彻底清洗和充分加热、熟制，以及将使用加工制作设备设施生熟分开等方式，消除寄生虫带来的危害风险。' WHERE id = '7902d53c-db86-4e22-b4b9-1004509a3fe7';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第三十九条规定，在经营保健食品的场所应标注保健食品不是药物，不能代替药物治疗疾病等消费提示信息，网络经营保健食品的同样需要标注。' WHERE id = '7909785c-8f71-42c1-a9e1-1c96ddfc237f';
UPDATE public.questions SET analysis = '《食用农产品市场销售质量安全监督管理办法》规定，销售者销售食用农产品，应当在销售场所明显位置或者带包装产品的包装上如实标明食用农产品的名称、产地、生产者的名称或者姓名、销售者的名称或者姓名等信息。' WHERE id = '79138586-72f5-4f7a-8acb-e7e564ef09c9';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第四十七条规定，许可申请人隐瞒真实情况或者提供虚假材料申请食品经营许可的，由县级以上地方食品药品监督管理部门给予警告，申请人在1年内不得再次申请食品经营许可。' WHERE id = '7916216f-c3c1-4f10-8d1b-22db52801473';
UPDATE public.questions SET analysis = '《食品安全法实施条例》是国务院制定的与食品安全相关的行政法规。《食品销售指南》和《农产品经营指南》不是行政法规，《餐饮服务食品安全操作规范》属于部门规章。' WHERE id = '791d9cde-c355-465a-bbc7-f7e94931d6ef';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》第十六条规定，食品生产经营企业应当组织对本企业职工进行食品安全知识培训，对食品安全管理人员进行培训和考核是强制性要求，而非鼓励性规定。' WHERE id = '792b92ff-2f79-499d-beb1-9df56ba6f0a8';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第二十九条规定，食品经营者需要延续依法取得的食品经营许可的有效期的，应当在该食品经营许可有效期届满30个工作日前向原发证部门提出申请。' WHERE id = '793af175-127d-486c-b2c9-196dda44d836';
UPDATE public.questions SET analysis = '浸出法工艺生产的食用植物油使用有机溶剂（如六号溶剂）提取油脂，主要风险是溶剂残留量超标。GB 2716《植物油》对溶剂残留量有严格的限量要求。' WHERE id = '795fc585-0f26-4e6a-a36a-083e0d8a047b';
UPDATE public.questions SET analysis = '《食品安全法》第四条规定，食品生产经营者应当依照法律、法规和食品安全标准从事生产经营活动，保证食品安全，诚信自律，对社会和公众负责，接受社会监督，承担社会责任。产品订单和合同要求不能凌驾于法律法规和标准之上。' WHERE id = '796f7fad-6331-4c3d-a277-d90d62bd4251';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》规定，一个食品生产企业可以同时生产多种类别的食品，只需申请一个食品生产许可证，在许可证书中载明生产的食品类别即可。' WHERE id = '797801af-d885-4410-a99a-c8f55e742889';
UPDATE public.questions SET analysis = 'GB 14881-2013规定，食品加工人员进入作业区域不得佩戴饰物、手表，不应化妆、染指甲、喷洒香水，不得携带或存放与食品生产无关的个人用品。应穿着清洁的工作服，不得穿个人服装进入作业区域。' WHERE id = '7980ab6c-d449-4849-9d14-9f0c6b811fa3';
UPDATE public.questions SET analysis = '焦亚硫酸钠、无水亚硫酸钠、硫磺作为漂白剂，其主要机理是破坏、抑制食品的发色因素，使食品免于褐变（如酶促褐变和非酶促褐变），而不是覆盖食品本身颜色或保持原有色泽。' WHERE id = '7994b8bf-df9a-4b47-8db9-7d36404e75eb';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》第三十一条规定，食品生产者应当妥善保管食品生产许可证，不得伪造、涂改、倒卖、出租、出借、转让。这是食品生产许可证管理的基本规定。' WHERE id = '799cfde5-9ca8-4761-a716-4d61f041b82d';
UPDATE public.questions SET analysis = 'GB 17400-2015《食品安全国家标准 方便面》适用于方便面、方便米粉、方便米线、方便粉丝等以粮食加工为主要原料的方便食品。' WHERE id = '79c06a1d-e909-4fee-af12-fa3b7e369c37';
UPDATE public.questions SET analysis = '《食品安全法》第五十条规定，食品生产企业应当建立食品原料、食品添加剂、食品相关产品进货查验记录制度，如实记录相关内容，并保存相关凭证。' WHERE id = '79c3271b-86a1-48ea-bfa7-d16f83db9922';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产企业应当确保其生产活动符合相应的食品安全标准，GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》是食品生产的基础性标准。' WHERE id = '79c509bf-9cc9-4437-be75-28e9b2757b26';
UPDATE public.questions SET analysis = '冷冻饮品生产中食品添加剂两超是指超限量或超范围使用甜味剂、着色剂、防腐剂。菌落总数超限量属于微生物指标问题，不属于两超范畴。' WHERE id = '79d09604-b2a7-4eab-96aa-e42c310c5b21';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，对因标签、标志或者说明书不符合食品安全标准而被召回的食品，食品生产者可以采取补救措施（如更换标签）后继续销售，而非只能销毁。' WHERE id = '79d399db-553b-4d85-895d-b1ef1a0bd836';
UPDATE public.questions SET analysis = '全脂豆粉是以大豆为原料，未经脱脂制得的产品，其含油量在18%以上。脱脂豆粉的含油量则低于18%。这是区分全脂豆粉和脱脂豆粉的重要指标。' WHERE id = '79e404ea-d5af-4a45-8e63-2bf254f6d176';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营者申请许可，应当具有专职或者兼职的食品安全专业技术人员和食品安全管理人员。这是食品生产经营许可的基本条件。' WHERE id = '79e5ac0d-d187-40b3-9c41-2384b618b2c2';
UPDATE public.questions SET analysis = '《食品安全法》第二十七条规定，食品中农药残留、兽药残留的限量规定及其检验方法与规程由国务院卫生行政部门、国务院农业行政部门会同国务院食品安全监督管理部门制定。' WHERE id = '7a0cab9b-e884-449f-977b-8b3e7c3068a5';
UPDATE public.questions SET analysis = '《食品生产许可审查通则》规定，同一品种不同包装的产品，不受包装规格和包装形式影响的项目可以一并检验。受包装影响的项目（如净含量、标签等）需分别检验。' WHERE id = '7a2bec87-c8f2-40b6-8d19-0f5b02b56203';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，跨省承包经营集中用餐单位食堂的，应向集中用餐单位食堂所在地、营业执照标注的住所、主要经营场所所在地的省级市场监督管理部门报告。' WHERE id = '7a2fd898-03b4-479d-ad28-2035c88cf600';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》规定，注册人变更不影响产品安全性、营养充足性以及特殊医学用途临床效果的事项，未依法申请变更的，由县级以上食品药品监督管理部门责令改正，给予警告；拒不改正的，处1万元以上3万元以下罚款。' WHERE id = '7a4750f8-600f-467e-8b73-98ccf1ae2c12';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，落实周排查制度应重点排查：本周每日检查记录情况、每日发现的食品安全风险隐患及整改情况、前期尚未整改到位的风险隐患整改进展、发现的其他食品安全问题。' WHERE id = '7a4d2158-6cbc-4e32-8945-115787f5468b';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，抽样工作应当由至少2名抽样人员执行，并出示抽样检验告知书及有效身份证明文件。' WHERE id = '7a4e894a-45e5-4df5-9012-fc660a7b2e80';
UPDATE public.questions SET analysis = '瓜子富含油脂，生产车间温度、湿度和工艺控制不当，会加速油脂的氧化变质，造成酸价超标。GB 19300对坚果与籽类食品的酸价有明确的限量要求。' WHERE id = '7a68eff7-aa86-42b6-a078-41de41ea4021';
UPDATE public.questions SET analysis = '《食品安全法》及相关规定要求，冷藏冷冻食品全程温度记录制度明确，冷藏冷冻设施应当设有有效的温度控制设施，以保证食品始终处于适宜的低温环境。' WHERE id = '7a943568-26e3-4453-ab12-e2323e67a228';
UPDATE public.questions SET analysis = '根据GB 2749-2015《食品安全国家标准 蛋与蛋制品》，蛋制品包括液蛋、干蛋、冰蛋、再制蛋等。鲜鸡蛋、鲜鸭蛋、鲜鹌鹑蛋属于鲜蛋，不属于蛋制品。液蛋是将鲜蛋去壳后经加工制成的液态蛋制品。' WHERE id = '7aa5bf76-0594-43e4-bbb8-1af5a77d6b4c';
UPDATE public.questions SET analysis = '根据《食品安全法》第五十三条，食品经营者采购食品，应当查验供货者的许可证和食品出厂检验合格证或者其他合格证明。无论是预包装食品还是散装食品，食品经营者都应当履行查验义务。采购散装食品同样需要查验相关合格证明。' WHERE id = '7ab35748-5c03-44f4-8d3f-236c1d9cd8c1';
UPDATE public.questions SET analysis = '根据《特殊医学用途配方食品注册管理办法》相关规定，申请人申请变更特殊医学用途配方食品注册证书载明事项的，应当提交特殊医学用途配方食品变更注册申请书。其他选项如科研报告、食品成分说明书等不属于变更注册的必备材料。' WHERE id = '7abbba56-e698-451b-b55c-fc56dc034818';
UPDATE public.questions SET analysis = '根据GB/T 317-2018《白砂糖》的规定，白砂糖是以甘蔗或甜菜为原料，经提取糖汁、清净处理、煮炼结晶和分蜜等工艺加工制成的蔗糖结晶。分蜜是糖业生产中的关键工序，用于分离糖膏中的糖结晶与母液。' WHERE id = '7acc0b6b-dec3-4fe4-8964-c48867059bcf';
UPDATE public.questions SET analysis = '根据《食品安全法》第六十七条和GB 7718《预包装食品标签通则》的规定，预包装食品的包装上应当标明：名称、规格、净含量、生产日期；成分或配料表；生产者名称、地址、联系方式；产品标准代号等事项。上述四项均为法定必须标注内容。' WHERE id = '7aea9e46-601c-43b9-95cf-9a11f972b578';
UPDATE public.questions SET analysis = '根据《食品安全法》第四十二条，国家建立食品安全全程追溯制度。食品生产经营者应当依照本法的规定，建立食品安全追溯体系，保证食品可追溯。所有食品经营者均负有建立追溯体系的法定义务。' WHERE id = '7af9a98b-6855-422f-937c-12cedbb146e8';
UPDATE public.questions SET analysis = '根据《餐饮服务食品安全操作规范》的规定，保持食品包装、贮存容器的密闭良好，是防止虫害侵入的重要措施。清洁和卫生虽然也很重要，但针对防止虫害侵入这一特定要求，''密闭''是最直接有效的防控措施。' WHERE id = '7b024cd1-cca4-43dd-a5f1-0769f428514f';
UPDATE public.questions SET analysis = '根据《食品安全法》第四十六条，食品生产企业应当就原料采购、原料验收、投料等原料控制事项制定并实施控制要求，以保证所生产的食品符合食品安全标准。这是食品生产企业落实食品安全主体责任的法定要求。' WHERE id = '7b1ebca1-f9ea-438d-bc16-15a395b93605';
UPDATE public.questions SET analysis = '菌落总数和大肠菌群是评价食品卫生质量的重要微生物指标。菌落总数反映食品被细菌污染的程度，大肠菌群反映食品被粪便污染的可能性。两者直接关系到产品的卫生状况和人体健康安全。' WHERE id = '7b3192c8-a739-4503-9584-5fb0bcae4662';
UPDATE public.questions SET analysis = '根据GB 7101《食品安全国家标准 饮料》的规定，经商业无菌工艺生产的饮料产品应符合商业无菌要求，检验方法按GB 4789.26《食品安全国家标准 食品微生物学检验 商业无菌检验》执行。' WHERE id = '7b37f0f2-d355-482f-ad26-4b6bd44c9fc6';
UPDATE public.questions SET analysis = '根据《食品安全法》第三十条、四十二条、四十三条及相关规定，国家鼓励食品生产企业制定严于国标的企业标准（A）、参加食品安全责任保险（C）、实施HACCP体系（D）。B选项''建立食品安全追溯体系''是法律强制要求，非''鼓励''性质，故不选B。' WHERE id = '7b3d96de-5a47-470d-bb56-45c921b1366f';
UPDATE public.questions SET analysis = '根据《反食品浪费法》第十条的规定，餐饮外卖平台应当以显著方式提示消费者适量点餐。餐饮服务经营者通过餐饮外卖平台提供服务的，应当在平台页面上向消费者提供食品分量、规格或者建议消费人数等信息。' WHERE id = '7b3f5d74-4723-410d-bfb6-c04d89675bce';
UPDATE public.questions SET analysis = '根据GB 14880-2012《食品安全国家标准 食品营养强化剂使用标准》，食用植物油中营养强化剂的使用应符合该标准规定。GB 28050为营养标签通则，GB 2760为食品添加剂使用标准，GB 7718为标签通则，均不直接规定营养强化剂的使用。注意选项中标准编号''CB''应为''GB''的印刷错误。' WHERE id = '7b440909-56f2-44af-a70a-d087ea4666f7';
UPDATE public.questions SET analysis = '虫害侵入食品会带来生物性危害（携带微生物、寄生虫）、化学性危害（自身产生毒素、污染化学物质）和物理性危害（携带异物如毛发、碎片等）。这三种危害类型是食品安全管控的核心内容。' WHERE id = '7b71a4c1-ae81-4aaa-a180-615c7f9308d8';
UPDATE public.questions SET analysis = '根据《食品安全法》第一百三十三条，食品生产经营者拒绝、阻挠、干涉监督检查的，由县级以上食品安全监督管理部门责令停产停业，并处二千元以上五万元以下罚款；情节严重的，吊销许可证。C选项金额错误。' WHERE id = '7b93b60b-f720-46f2-a686-44f71614d2c2';
UPDATE public.questions SET analysis = '根据GB 2762-2022《食品安全国家标准 食品中污染物限量》，可可制品中铅的含量限值为0.5mg/kg。该标准对不同食品类别中的铅含量设定了明确的限量要求。' WHERE id = '7b9a4b93-3f28-442a-a51c-df4252e3bede';
UPDATE public.questions SET analysis = '根据《餐饮服务食品安全操作规范》的规定，原料、半成品、成品的盛放容器和制作工具、设备应分开并有明显的区分标识，以防止交叉污染。包装材料不需要与食品分开放置在同一场所。' WHERE id = '7bac6e4a-06ec-4d79-96f9-8c28f33530b9';
UPDATE public.questions SET analysis = '根据《食品安全法》第七十三条，食品广告不得含有食品安全监督管理部门或者承担食品检验职责的机构、食品行业协会、消费者协会向消费者推荐食品的内容。此类推荐行为在食品广告中被明确禁止。' WHERE id = '7bb586cb-99a7-4c59-9a12-753a5e7b1684';
UPDATE public.questions SET analysis = '根据《食品安全法》第五十三条及相关规定，进货查验记录和凭证保存期限不得少于产品保质期满后六个月；没有明确保质期的，保存期限不得少于二年。' WHERE id = '7bbc9527-32e9-463e-80d3-f1fb9b755123';
UPDATE public.questions SET analysis = '根据GB 31605-2020《食品安全国家标准 食品冷链物流卫生规范》的定义，食品冷链物流指以温度控制为主要手段，使食品从出厂后到销售前始终处于所需温度范围内的物流工程。该定义准确描述了冷链物流的核心特征。' WHERE id = '7bbf90a2-6a6e-423a-954b-2bfe45bfaa48';
UPDATE public.questions SET analysis = '根据《食品安全法》第四十四条，食品生产经营企业应当建立健全食品安全管理制度，对职工进行食品安全知识培训，食品安全管理人员经考核不具备食品安全管理能力的，不得上岗。' WHERE id = '7bc0f76b-5bcf-4a60-823f-bc6704e807af';
UPDATE public.questions SET analysis = '并非所有饮料均需控制氰化物含量。根据GB 7101《饮料》的规定，仅以杏仁等含氰苷原料加工的饮料需控制氰化物含量。普通饮料如碳酸饮料、果汁饮料等无需特别控制氰化物。' WHERE id = '7bca6487-d8fd-4e6a-ad2d-acea7a4e23b4';
UPDATE public.questions SET analysis = '根据GB 7718《预包装食品标签通则》的规定，进口预包装食品标签应标明：名称、配料表、净含量和规格、生产日期和保质期、贮存条件、原产国/地区、境内代理商名称/地址/联系方式等。产品所执行的标准代号不属于进口预包装食品必须标明的事项。' WHERE id = '7bd9f9dc-1d4b-4975-af36-f4a73e7e76ed';
UPDATE public.questions SET analysis = '根据《食用农产品市场销售质量安全监督管理办法》第二条，食用农产品指在农业活动中获得的植物、动物、微生物及其产品。鲜水果、生鱼片、生猪肉均属于食用农产品。水果罐头属于加工食品，不属于食用农产品。' WHERE id = '7bdcbcdc-70dd-4f21-952f-9106661cb285';
UPDATE public.questions SET analysis = '根据《餐饮服务食品安全操作规范》的规定，实行统一配送经营方式的餐饮服务企业，可以由企业总部统一查验供货者的许可证和食品合格证明文件，进行食品进货查验。各门店无需重复查验。' WHERE id = '7bdeea53-9e04-4747-80e9-2448b0fcdd3a';
UPDATE public.questions SET analysis = '根据《食品安全法》第五十二条，食品、食品添加剂、食品相关产品的生产者，应当按照食品安全标准对所生产的产品进行检验，检验合格后方可出厂或者销售。这是生产者的法定检验义务。' WHERE id = '7be52e16-e70a-44fd-8d80-352a174415e3';
UPDATE public.questions SET analysis = '根据《餐饮服务食品安全操作规范》的规定，从业人员每天上岗前应进行健康状况检查。发现患有发热、呕吐、腹泻、咽部严重炎症等病症及皮肤有伤口或感染的，应暂停从事接触直接入口食品的工作，待排除有碍食品安全的疾病后方可重新上岗。' WHERE id = '7c0bd653-f962-4dde-be3e-9adb1ba345b5';
UPDATE public.questions SET analysis = '根据原卫生部《食品中可能违法添加的非食用物质和易滥用的食品添加剂名单》，双氧水（过氧化氢）被列入食品中可能违法添加的非食用物质名单，禁止作为食品加工助剂使用。' WHERE id = '7c19beab-ce5f-4f4d-a7e8-596d26660e05';
UPDATE public.questions SET analysis = '根据《食品安全法》第四十四条，食品安全管理人员应当具备食品安全管理能力，经考核不具备食品安全管理能力的，不得上岗。食品经营企业必须配备经考核合格的食品安全管理人员。' WHERE id = '7c2094b4-45a8-4114-bfec-ae477cb3163d';
UPDATE public.questions SET analysis = '根据《餐饮服务食品安全操作规范》和《学校食品安全与营养健康管理规定》，学校食堂禁止采购、贮存、使用亚硝酸盐（包括亚硝酸钠、亚硝酸钾）。无论条件是否允许，均严禁使用。' WHERE id = '7c50e6ba-4655-41bf-bcc9-15d652bfc4b5';
UPDATE public.questions SET analysis = '根据《食品安全法》第一百零二条，食品生产经营企业应当制定食品安全事故处置方案，定期检查本企业各项食品安全防范措施的落实情况，及时消除事故隐患。该义务适用于所有食品生产经营企业，包括经营企业。' WHERE id = '7c6d048b-d099-4e33-b349-d4303d7e665a';
UPDATE public.questions SET analysis = '根据食品生产许可管理相关规定，食品生产许可实行一企一证原则。生产分装大豆油需取得''大豆油（分装）''的生产许可，仅有大豆油、花生油、玉米油的生产许可不能直接从事分装业务。' WHERE id = '7c8a4ae1-b203-4239-85f9-b3de4611a5ca';
UPDATE public.questions SET analysis = '根据《餐饮服务食品安全操作规范》的规定，制作食用冰、奶茶、果蔬汁的水，应为符合GB 5749《生活饮用水卫生标准》规定的生活饮用水。这是餐饮加工用水安全的基本要求。' WHERE id = '7cacfb20-ccc9-4cf0-ba32-b2d8dcdc80c4';
UPDATE public.questions SET analysis = '根据《食品安全法》第一百零二条，餐饮服务提供者应当制定食品安全突发事件应急处置方案。制定应急处置方案是餐饮服务提供者的法定义务，绝非''没必要''。' WHERE id = '7cbc3a4d-229b-4cdc-9c1a-197d9f193eb1';
UPDATE public.questions SET analysis = 'GB 2712-2014《食品安全国家标准 豆制品》于2014年12月24日发布，2015年5月24日实施。食品安全国家标准通常给予一定的过渡期，方便企业做好实施准备。' WHERE id = '7cbe4993-a171-4742-905e-4590ec0043ce';
UPDATE public.questions SET analysis = '根据《食品安全法实施条例》第二十一条，委托生产食品、食品添加剂的，委托方和受托方应当遵守法律、法规、食品安全标准以及合同约定，委托生产的食品品种、委托期限、委托方对受托方生产行为的监督等情况应单独记录、留档备查。' WHERE id = '7cc8c1aa-b61e-4d1f-a959-4bba13df892a';
UPDATE public.questions SET analysis = '根据《特殊医学用途配方食品注册管理办法》的规定，申请人组织开展多中心临床试验的，应当明确组长单位和统计单位。统计单位负责临床试验数据的统计分析工作。' WHERE id = '7cdacc7a-c2b3-45ee-8679-e8caa0a7d852';
UPDATE public.questions SET analysis = '根据《食用农产品市场销售质量安全监督管理办法》第二十五条，食用农产品贮存服务提供者应当向所在地县级食品药品监督管理部门报告相关信息，查验销售者证明并建立进出货台账，保证贮存设施设备清洁无害，定期检查库存并报告违法行为。以上四项均为法定义务。' WHERE id = '7ce6afc4-279d-4a6d-9835-fea287027734';
UPDATE public.questions SET analysis = '根据《食品安全法》第一百三十五条，因食品安全犯罪被判处有期徒刑以上刑罚的，终身不得从事食品生产经营管理工作，也不得担任食品生产经营企业食品安全管理人员。该禁入期限为终身，非5年。' WHERE id = '7cf2ae3a-c6ea-4ea4-8617-66d82ece7f64';
UPDATE public.questions SET analysis = '菌落总数超标通常与原料、包材或生产加工过程受微生物污染（A），人员和环境的清洗消毒不到位（B），储运条件控制不当（D）等因素有关。C选项''生产工器具等设备设施严格清洗消毒''是防控措施，不会导致菌落总数超标。' WHERE id = '7d0d5769-d0cd-4f55-8630-c61574daebba';
UPDATE public.questions SET analysis = '根据GB 9697-2008《蜂王浆》的规定，蜂王浆按品质分为优等品、合格品等。优等品要求水分含量不大于67.5%（即0.675），合格品要求水分含量不大于68.5%（即0.685）。' WHERE id = '7d0ec245-5415-4f69-af66-8278299f6f3c';
UPDATE public.questions SET analysis = 'GB 10136-2015《食品安全国家标准 动物性水产制品》适用于预制水产干制品、盐渍水产品、腌制生食动物性水产品等，但不适用于动物性水产罐头。水产罐头适用GB 7098《罐头食品》标准。' WHERE id = '7d1468e9-e2e8-45c4-848c-e770bd221c1f';
UPDATE public.questions SET analysis = '根据GB 14881《食品生产通用卫生规范》的规定，企业应综合考虑产品特性（A）、工艺特点（B）、原料控制情况（C）等因素合理确定检验项目和检验频次。生产批次不是确定检验项目的主要因素。' WHERE id = '7d18d3c4-a94c-41c9-b539-5a81a9d5305f';
UPDATE public.questions SET analysis = '根据《食品生产经营日常监督检查管理办法》的规定，日常监督检查结果为不符合，有发生食品安全事故潜在风险的，食品生产企业应当立即停止食品生产活动。这是防止食品安全事故发生的紧急处置措施。' WHERE id = '7d2f0496-a233-464f-ade5-a5435b328d96';
UPDATE public.questions SET analysis = '根据GB 2715-2016《食品安全国家标准 粮食》的规定，小麦热损伤粒含量应≤0.5%（即0.005）。热损伤粒是衡量粮食加工品质和食用品质的重要指标。' WHERE id = '7d2fccd4-1a8c-422c-bbaf-38b7f18c4939';
UPDATE public.questions SET analysis = '根据《特殊医学用途配方食品注册管理办法》的规定，审评机构应当一次告知需要补正的全部内容，申请人应当在6个月内一次补正材料。补正材料的时间不计算在审评时间内。' WHERE id = '7d424e4b-c59c-45cc-979a-17cd963cc670';
UPDATE public.questions SET analysis = '坚果与籽类食品的食品安全国家标准为GB 19300-2014《食品安全国家标准 坚果与籽类食品》。GB 7099为糕点面包标准，GB 19295为速冻面米制品标准，GB 2760为食品添加剂使用标准。' WHERE id = '7d7261be-c7e8-4ceb-a10e-c09650b44132';
UPDATE public.questions SET analysis = '无公害食品是指产地环境、生产过程和产品质量符合国家有关标准和规范的要求，经认证合格获得认证证书并允许使用无公害农产品标志的未经加工或初加工的食用农产品。无公害不等于''最有营养''，两者概念不同。' WHERE id = '7d81c646-3fb7-4fd0-a710-0686afb5aecf';
UPDATE public.questions SET analysis = '根据GB 14880-2012《食品安全国家标准 食品营养强化剂使用标准》的附录，胶基糖果不能使用钙、锌、铁、硒等矿物质类营养强化剂。胶基糖果的基质特性决定了其不适合添加上述矿物质强化剂。' WHERE id = '7d852c8b-e1c8-489a-8274-c246c451b6bb';
UPDATE public.questions SET analysis = '在生产经营场所配置纱帘、纱网、防鼠板、防蝇灯、风幕等装置，是对虫害危害的防控措施。这些设施通过物理方式阻止虫害进入食品加工场所，属于虫害综合管理（IPM）的重要组成部分。' WHERE id = '7d8fe104-de58-4e5d-881e-8356641e48ce';
UPDATE public.questions SET analysis = '根据《餐饮服务食品安全操作规范》的规定，专用操作区应满足以下要求：入口处设置洗手、干手、消毒设施，水龙头非手动开启式；无明沟，地漏带水封；设专用食品容器和工用具；必要时设工具清洗消毒设施和专用冷藏设施。以上四项描述均正确。' WHERE id = '7d98cc09-4e08-4e50-af53-79709c1769c1';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第十条，县级以上地方市场监督管理部门对餐饮服务单位的食品安全总监、食品安全员随机进行监督抽查考核。抽查考核不合格，不再符合经营要求的，企业应当立即采取整改措施。' WHERE id = '7da75842-22a9-4391-9655-9791bb4995b0';
UPDATE public.questions SET analysis = '根据《食用农产品市场销售质量安全监督管理办法》第四条，集中交易市场开办者应当落实食品安全管理制度，对市场的食用农产品质量安全工作全面负责。开办者是市场食品安全管理的第一责任人。' WHERE id = '7da8cb6d-ecf6-4265-a3ce-53a36af7c346';
UPDATE public.questions SET analysis = '根据《食品安全法》第七十条，食品添加剂应当有标签、说明书和包装。标签和说明书应载明名称、规格、净含量、生产日期、成分或配料表、贮存条件、生产许可证编号、使用范围、用量及使用方法等。' WHERE id = '7db3466c-d9c0-4fb8-a1bf-629bde67de09';
UPDATE public.questions SET analysis = '根据《食品安全法》第五十条，食品生产企业应当建立食品原料、食品添加剂、食品相关产品进货查验记录制度，如实记录相关信息。该制度是食品生产企业落实食品安全主体责任的核心制度之一。' WHERE id = '7db9c351-f95d-46ab-bc3d-9eedcb451db1';
UPDATE public.questions SET analysis = '根据《食品安全法》第一百一十条及相关规定，食品生产经营者配合监督检查的义务包括：开放食品生产经营场所、回答相关询问、提供相关合同票据账簿等材料、协助生产经营现场检查和抽样检验。以上四项均为法定义务。' WHERE id = '7ddb6a80-3d70-4fed-83f3-27ff35c01831';
UPDATE public.questions SET analysis = '根据GB 14881《食品生产通用卫生规范》的规定，顶棚应使用无毒、无味、与生产需求相适应的材料建造（A），应易于清洁消毒，结构上不利于冷凝水垂直滴下（C），蒸汽水电等配件管路应避免设置于暴露食品的上方（D）。B选项错误，可以在屋顶内层喷涂涂料作为顶棚，但应使用符合要求的涂料。' WHERE id = '7de43a05-36b6-4163-8d12-81c0cfb2b180';
UPDATE public.questions SET analysis = '根据《食品安全法》第五条和机构改革方案，国务院食品安全委员会负责食品安全工作的统筹协调，其具体工作由国家市场监督管理总局承担。' WHERE id = '7deafd88-53c7-4849-8958-1f577cef3626';
UPDATE public.questions SET analysis = '根据《食品安全法》第六十三条，食品经营企业发现其经营的食品不符合食品安全标准或者有证据证明可能危害人体健康的，应当立即停止经营，通知相关生产经营者和消费者，并记录停止经营和通知情况。销毁问题产品应由生产者负责召回后处理。' WHERE id = '7e00384a-e442-4102-8f03-e95ee0e5bfea';
UPDATE public.questions SET analysis = '根据《食品经营许可管理办法》第十一条，申请食品经营许可应当具有与经营的食品品种、数量相适应的经营设备或者设施，包括消毒、更衣、盥洗、采光、照明、通风、防腐、防尘、防蝇、防鼠、防虫、洗涤以及处理废水、存放垃圾和废弃物的设备或者设施。' WHERE id = '7e087ed8-46c8-404c-a5da-d321d8d7fe20';
UPDATE public.questions SET analysis = '根据《食品生产经营监督检查管理办法》的规定，监督检查结果对消费者有重要影响的，食品生产经营者应当按照规定在食品生产经营场所醒目位置张贴或者公开展示监督检查结果记录表，并保持至下次监督检查。' WHERE id = '7e2a2cac-165f-47df-8456-179e38066327';
UPDATE public.questions SET analysis = '根据《食品安全法》第四十五条，患有国务院卫生行政部门规定的有碍食品安全疾病的人员，不得从事接触直接入口食品的工作。这是防止疾病通过食品传播的重要防控措施。' WHERE id = '7e360aca-bd1b-4b49-9951-99d5c3ae3f33';
UPDATE public.questions SET analysis = '根据《食用农产品市场销售质量安全监督管理办法》第二十四条，销售者贮存食用农产品，应当定期检查库存，及时清理腐败变质、油脂酸败、霉变生虫、污秽不洁或者感官性状异常的食用农产品。' WHERE id = '7e3dd4c7-9dbe-49e9-ab62-d6a9052100e0';
UPDATE public.questions SET analysis = '根据《市场监督管理严重违法失信名单管理办法》的规定，市场监督管理部门将受到较重行政处罚的食品生产经营企业列入严重违法失信名单，依法实施联合惩戒。' WHERE id = '7e414b71-7702-40b6-a426-5a0fafc8cad0';
UPDATE public.questions SET analysis = '根据GB 14881《食品生产通用卫生规范》和肉制品生产许可审查细则的规定，肉制品生产过程中应严格按照配方进行配料和投料，并做好记录。生产记录是食品安全追溯的重要依据，不得省略。' WHERE id = '7e5eb6d6-0723-43e7-9363-cf517e7660c7';
UPDATE public.questions SET analysis = '根据《食品安全法》第三十三条和《食品经营许可管理办法》的规定，食品生产经营者申请许可，应当具有专职或兼职的食品安全专业技术人员和食品安全管理人员。销售员不属于法定要求。' WHERE id = '7e61163a-dd95-4dfa-8a11-8f603fe89e61';
UPDATE public.questions SET analysis = '根据《生猪屠宰管理条例》和《食品安全法》的规定，从事生猪产品销售、肉食品生产加工的单位和个人以及餐饮服务经营者、集中用餐单位生产经营的生猪产品，必须是经肉品品质检验合格和检疫合格的生猪产品。两者缺一不可。' WHERE id = '7e7847c5-2563-4554-a313-15852c21e333';
UPDATE public.questions SET analysis = '根据婴幼儿辅助食品生产许可审查细则的规定，婴幼儿辅助食品原料验收、配料、成型、杀菌等关键工序均需实施质量控制并制定操作规程。这些工序直接影响产品的安全性和营养性。' WHERE id = '7e79630c-a816-4c98-9a2d-2ae869580bef';
UPDATE public.questions SET analysis = '根据《保健食品注册与备案管理办法》第五十六条，保健食品的名称应当准确、科学，不得使用人名、地名、代号及夸大容易误解的名称。题目所述内容违反保健食品命名管理规定。' WHERE id = '7e7eb0d7-c52e-4f87-a6d9-ecc78d39b8b5';
UPDATE public.questions SET analysis = '检测可可粉pH值需要的基本设备为天平（精度0.1g，用于称量样品）和pH计（用于测定pH值）。折光仪用于测定可溶性固形物，电热板用于加热，均不是pH值检测的必需设备。' WHERE id = '7e88241c-a320-4f82-867d-072abdfd64aa';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第十条，食品生产经营企业应当制定食品安全风险管控清单，建立健全''日管控、周排查、月调度''工作制度和机制。这是落实食品安全主体责任的核心制度。' WHERE id = '7e8a760b-800c-47c1-8d97-401de3c20059';
UPDATE public.questions SET analysis = '根据《食品安全法》第六十三条，食品生产企业发现其生产的食品不符合食品安全标准或者有证据证明可能危害人体健康的，应当立即停止生产，召回已经上市销售的食品，通知相关生产经营者和消费者，并记录召回和通知情况。' WHERE id = '7e8fb339-6978-48fa-b118-1eced1ab7e51';
UPDATE public.questions SET analysis = '根据《食品安全法》第七十九条和《保健食品注册与备案管理办法》的规定，保健食品广告应当显著标明''本品不能代替药物''。A、B、C选项均为保健食品广告禁止出现的内容。' WHERE id = '7e9bdc87-c854-48f4-b3b2-f65ae987ff51';
UPDATE public.questions SET analysis = '调味面制品（辣条）主要风险点为过氧化值超标。由于调味面制品含油量较高，油脂在贮存过程中易发生氧化，导致过氧化值升高，影响食品安全。' WHERE id = '7ea8c768-6adf-46f5-a1bb-134fdba0ac3c';
UPDATE public.questions SET analysis = '白酒勾调工序中常见的违规问题包括：违规使用食用酒精、违规添加香精香料、违规使用甜味剂、违规添加色素。上述行为均违反《食品安全法》和白酒生产相关规定，严重影响白酒产品质量安全。' WHERE id = '7eaa1e16-8ea4-49ee-8dc4-baed4e9827ab';
UPDATE public.questions SET analysis = '《食品安全法实施条例》是国务院制定的与食品安全相关的行政法规。B、D选项名称不规范，《餐饮服务食品安全操作规范》属于部门规章/规范性文件，非行政法规。' WHERE id = '7ebd29f2-030a-4be5-b255-30dd68d0dcdf';
UPDATE public.questions SET analysis = '根据GB 14881《食品生产通用卫生规范》的规定，食品生产企业库房中，汽油、清洁剂、消毒剂、杀虫剂、润滑剂等化学品均应与食品成品分隔放置，防止交叉污染。以上四项均需与食品分开存放。' WHERE id = '7ec08c32-8df1-4505-9bed-226080777f61';
UPDATE public.questions SET analysis = '根据《食品生产许可管理办法》第四十条，有下列情形之一的，食品生产许可将被依法注销：许可有效期届满未申请延续的；食品生产者主体资格依法终止的；许可被撤回、撤销或吊销的；因不可抗力导致许可事项无法实施的。以上四项均正确。' WHERE id = '7ec0d77a-3bad-4d0b-b8c0-3045fc61e98b';
UPDATE public.questions SET analysis = '根据《食品安全法》第六十七条，预包装食品的包装上应当有标签。标签是消费者了解食品信息的主要途径，也是食品安全管理的重要手段。预包装食品无标签属于违法行为。' WHERE id = '7eccbb71-805b-4d52-9ede-9be1430ac26b';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第九条，食品安全总监直接对本企业主要负责人负责，承担组织拟定食品安全管理制度、风险防控措施、事故处置方案、管理督促食品安全员等职责。以上四项均为食品安全总监的法定职责。' WHERE id = '7ed853ca-5553-4d66-a779-119d6eb60255';
UPDATE public.questions SET analysis = '根据GB 14881《食品生产通用卫生规范》的规定，清洁消毒制度应包括：清洁消毒的区域、设备或器具名称；清洁消毒方法和频率；清洁消毒效果的验证及不符合的处理；使用的洗涤、消毒剂。以上四项均应为制度内容。' WHERE id = '7edb08ff-0779-43e4-9fa9-8d0b54b4eb44';
UPDATE public.questions SET analysis = '根据GB 7718《预包装食品标签通则》的规定，白砂糖、食用盐、味精等预包装食品可免除标示保质期。啤酒（酒精度4%）不属于可免除标示保质期的食品类别，需标注保质期。' WHERE id = '7ee216ad-6c13-4b50-b851-ad100b064dac';
UPDATE public.questions SET analysis = 'GB 31646-2018适用于速冻食品，不适用于冷冻饮品；规定了冷冻原料解冻要求、速冻后产品周转管控制度、包装段应设置金属检测装置等要求。以上四项均符合该标准的规定。' WHERE id = '7efe3803-6e3d-400a-8350-36f95387312c';
UPDATE public.questions SET analysis = '根据GB 14881《食品生产通用卫生规范》的规定，食品生产企业在生产车间屋顶内层喷涂涂料作为顶棚的，应使用无毒、无味、防霉、不易脱落、易于清洁的涂料。该做法在符合要求的前提下是允许的。' WHERE id = '7f06eb38-83a3-4ff2-a3a8-c17f1974d747';
UPDATE public.questions SET analysis = '根据《食品安全法》第五十三条，食品经营者采购食品，应当查验供货者的许可证和食品出厂检验合格证或者其他合格证明。此规定适用于所有食品，包括散装食品。采购散装食品同样需要查验相关合格证明。' WHERE id = '7f088a08-251c-47a2-9971-e40e4da2aa97';
UPDATE public.questions SET analysis = '根据GB 14881《食品生产通用卫生规范》的规定，食品生产企业在生产车间屋顶内层喷涂涂料作为顶棚时，应使用无毒、无味、防霉、不易脱落、易于清洁的涂料。该做法是允许的，但需满足上述要求。' WHERE id = '7f0c24a8-af6f-4f4b-9d1c-ec911b5b2055';
UPDATE public.questions SET analysis = '根据GB 7718《预包装食品标签通则》的定义，定量包装是指在一定量限范围内具有统一的质量、长度、面积、体积等标识内容的预包装。经营过程中的包装不属于定量包装，而是散装食品销售行为。' WHERE id = '7f12433a-2c4e-42a5-aca0-326d9e7f41e8';
UPDATE public.questions SET analysis = '根据《食品安全法实施条例》第二十五条，非食品生产经营者从事对温度、湿度等有特殊要求的食品贮存业务的，应当自取得营业执照之日起30个工作日内向所在地县级人民政府食品安全监督管理部门备案。' WHERE id = '7f1ee84b-d192-4e2d-a392-8a7f7ea598e4';
UPDATE public.questions SET analysis = '根据GB 2760《食品安全国家标准 食品添加剂使用标准》，被膜剂主要用于瓜果表面，起到保鲜、上光、防止水分蒸发的作用。上色鲜艳不属于被膜剂的法定功能。' WHERE id = '7f31bf4f-2d9f-4438-acad-d783b60aeca9';
UPDATE public.questions SET analysis = '根据食品生产许可分类目录，实施食品生产许可的乳制品分为液体乳、乳粉、其他乳制品三大类。该分类涵盖了乳制品的主要生产类别。' WHERE id = '7f36dd9f-7123-407b-8966-a064df6ba4fe';
UPDATE public.questions SET analysis = '根据《食品安全法》第五十三条，保健食品经营者应当建立进货查验记录制度，如实记录食品的名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容。以上全都需要记录。' WHERE id = '7f3d0646-d2ad-4016-ac6d-633b29344f9f';
UPDATE public.questions SET analysis = '根据《婴幼儿配方乳粉产品配方注册管理办法》第二十条，审评机构应当自收到受理材料之日起60个工作日内完成审评工作。如需补正材料，补正时间不计入审评时限。' WHERE id = '7f4873dc-d76c-4558-96d8-205b27a5dce8';
UPDATE public.questions SET analysis = '根据《食品安全法》第二条，在中华人民共和国境内从事食品的贮存和运输活动，应当遵守本法。食品的贮存和运输是食品安全链条的重要环节，必须遵守《食品安全法》的相关规定。' WHERE id = '7f5b36d8-476e-456b-8365-05345c4b7ddd';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第五条，食品销售企业应当配备专职或兼职食品安全管理人员，食品安全总监、食品安全员等管理人员的数量和能力水平应与企业规模、食品类别、风险水平等相适应。' WHERE id = '7f5bfed1-33b7-4576-9128-90ead417ffef';
UPDATE public.questions SET analysis = '根据《食品安全抽样检验管理办法》第三十五条，市场监督管理部门收到监督抽检不合格检验结论后，应当在5个工作日内将检验报告和抽样检验结果通知书送达被抽检食品生产经营者，并告知其依法享有的权利。' WHERE id = '7f692625-6b6c-45f9-bc10-3c8b73ba1432';
UPDATE public.questions SET analysis = '根据GB 2760《食品安全国家标准 食品添加剂使用标准》，餐饮经营中使用食品添加剂的目的包括：改善食品品质和色、香、味（A），以及防腐、保鲜（B）。食品添加剂不得用于掩盖食品质量缺陷或以掺杂为目的。' WHERE id = '7f98d9f7-0eff-4d3e-a245-f5fd0446a168';
UPDATE public.questions SET analysis = '根据《食品安全抽样检验管理办法》第十四条，抽样人员可以从食品经营者的经营场所、仓库以及食品生产者的成品库待销产品中随机抽取样品。以上三个场所均为合法的产品抽样来源。' WHERE id = '7fdcb47b-7772-4a1a-a369-419b7c65c1c6';
UPDATE public.questions SET analysis = '微生物是食品中最常见、最重要的危害因素之一。食品生产经营中防控微生物的措施包括清洁消毒、加热灭菌、低温贮存、添加防腐剂、建立不利于微生物生存繁殖的环境等。' WHERE id = '7fdd5276-4188-453c-8f81-487770b42b81';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第五条，中央厨房、集体用餐配送单位、集中用餐单位食堂等高风险单位应当配备食品安全总监。这是基于风险管理的差异化配置要求。' WHERE id = '801252ed-411f-4b47-bf8c-d8261b59d005';
UPDATE public.questions SET analysis = '根据《食品安全法》第四十五条，患有痢疾、伤寒、甲型病毒性肝炎、戊型病毒性肝炎等消化道传染病，以及活动性肺结核、化脓性或者渗出性皮肤病等有碍食品安全疾病的人员，不得从事接触直接入口食品的工作。非上述疾病患者可以从事食品加工工作。' WHERE id = '80217535-30a9-48e6-bb98-acb0844b634a';
UPDATE public.questions SET analysis = '根据《食品生产经营日常监督检查管理办法》的规定，监管部门实施日常监督检查应将结果当场告知被检查单位（C），对发现的问题应提出整改要求（D）。检查前应出示执法证件，检查程序应规范合法。' WHERE id = '8028951a-8344-4e6c-a064-ca6a054e25e6';
UPDATE public.questions SET analysis = '根据《特殊医学用途配方食品注册管理办法》第四十一条，有下列情形之一的，国家食品药品监督管理总局可以撤销注册：工作人员滥用职权、玩忽职守的；超越法定职权或违反法定程序的；对不具备申请资格或不符合法定条件的申请人准予注册的；依法可以撤销注册的其他情形。以上四项均正确。' WHERE id = '80332b3a-f4e0-4253-976b-0a730cbaac6a';
UPDATE public.questions SET analysis = '根据《食品经营许可管理办法》第十九条，食品经营许可证有效期为五年。仅销售预包装食品的备案编号无固定有效期限，并非10年有效期。题目表述错误。' WHERE id = '80384e8c-971e-4caa-87a3-3b0081d713d7';
UPDATE public.questions SET analysis = '《食品安全法》第四十四条规定，食品生产经营企业应当建立健全食品安全管理制度，对职工进行食品安全知识培训，加强食品检验工作，依法从事生产经营活动。该条款明确了企业建立食品安全规章制度的法定义务。' WHERE id = '8042fabd-ec4c-468b-9c7c-bdfaacf2dac3';
UPDATE public.questions SET analysis = '根据《食品安全法》第三十四条，禁止在食品加工中添加非食用化学物质和其他可能危害人体健康的物质。非食用物质对人体具有潜在危害，严禁添加到食品中。' WHERE id = '804602af-81df-4222-9a6f-4a3f757f6a5a';
UPDATE public.questions SET analysis = '根据罐头食品生产许可审查细则的规定，罐头食品生产企业应按容器材质和封口形式分别制定封口操作规程。不同材质和封口形式的工艺参数不同，需分别制定操作规程以确保封口质量。' WHERE id = '80699ad4-f0e1-489d-99d2-4f5ebe48712a';
UPDATE public.questions SET analysis = '根据《中央厨房许可审查规范》的规定，中央厨房是指由餐饮单位建立，具有独立场所及设施设备，集中完成食品成品或半成品加工制作并配送给本单位连锁门店的供应机构。其供应对象为本单位连锁门店。' WHERE id = '806f7458-0842-4f59-8cd1-7f11bbc432dc';
UPDATE public.questions SET analysis = '对化学性危害的防控有时比控制生物性危害更加困难，特别是来自于原料及其种养殖环境、加工过程的危害。化学性危害（如农药残留、兽药残留、重金属、环境污染物等）往往难以通过感官发现，且去除困难。' WHERE id = '809c8a8f-e1aa-4f39-b853-60a8ddd65a23';
UPDATE public.questions SET analysis = '食品污染的来源分为三类：生物性污染（微生物、寄生虫等）、物理性污染（异物、放射性物质等）和化学性污染（农药残留、重金属、食品添加剂滥用等）。' WHERE id = '80a00bc7-e4d2-4ca3-a38c-5db26280eb0c';
UPDATE public.questions SET analysis = '虫害侵入食品会带来生物性危害（携带微生物、寄生虫）、化学性危害（自身产生毒素）和物理性危害（携带异物）。这三种危害类型是食品安全危害分析的核心内容。' WHERE id = '80abe9cd-cb0a-4b91-a0ae-2a6d16fd6eb7';
UPDATE public.questions SET analysis = '根据《食品安全法》第四条，食品生产经营者对其生产经营食品的安全负责。食品生产经营者是食品安全的第一责任人，应当依法从事生产经营活动，保证食品安全。' WHERE id = '80ae5f47-898a-4236-9cb2-e1bf109e293e';
UPDATE public.questions SET analysis = '根据GB 31647-2018《食品添加剂生产通用卫生规范》，该标准对设施与设备的设计、布局、材质、维护等均作出了明确要求，以确保食品添加剂的生产过程符合卫生要求。以上四项均正确。' WHERE id = '80b5d3c3-034e-4e8b-9fce-dec8abb242d1';
UPDATE public.questions SET analysis = '根据GB 7718《预包装食品标签通则》的规定，多料包的方便面应按照保质期最早到期的单件食品的保质期标示。这是为了确保产品在最短保质期内被食用，保障食品安全。' WHERE id = '80b698b8-98c3-4912-8322-89353f0c26a7';
UPDATE public.questions SET analysis = '保健食品备案号''食健备G201744000001''中，G表示国产保健食品，2017为年份，44为省代码，000001为序号。备案制适用于使用原料目录内原料的保健食品。题目要求选择''错误''的说法，需根据选项具体内容判断。' WHERE id = '80c4e0f4-ad4e-479f-aafc-ff815cdd74a3';
UPDATE public.questions SET analysis = '根据《食品安全法》第一百二十五条，生产无标签的预包装食品的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品，并可以没收用于违法生产经营的工具、设备、原料等物品。题目要求选择''不正确''的表述。' WHERE id = '80c8fbec-ca0e-4190-b6ff-5d0864b0aa92';
UPDATE public.questions SET analysis = '根据茶叶及相关制品生产许可审查细则，茶叶及相关制品生产许可包括茶叶、边销茶、调味茶和代用茶4类产品。边销茶是茶叶生产许可的重要类别之一。' WHERE id = '80faf3b5-bca1-4818-b410-e856c6114c0f';
UPDATE public.questions SET analysis = '食品安全国家标准分为四大类：产品标准、生产经营规范标准、检验方法标准和基础标准（包括术语、定义、标签等）。以上四类涵盖了食品安全国家标准的完整体系。' WHERE id = '80fba14c-8946-46b4-b8a7-b3a66b31b416';
UPDATE public.questions SET analysis = '工业明胶含有对人体有害的铬等重金属，严禁用于食品生产。根据《食品安全法》第三十四条，禁止使用非食品原料生产的食品或食品添加剂。冷冻饮品配料必须使用食用明胶，不得使用工业明胶。' WHERE id = '8105371c-1ff3-4a87-869a-55731b24d389';
UPDATE public.questions SET analysis = '根据《市场监督管理严重违法失信名单管理办法》，市场监管部门对严重违法失信企业实施市场和行业禁入措施，但对其食品安全总监和食品安全员的禁入需依据《食品安全法》第一百三十五条的专门规定执行，两者适用条件不同。' WHERE id = '81364361-d4bf-4924-9660-410ebb0d2170';
UPDATE public.questions SET analysis = '水产品中的农药残留主要来源于：水体污染（农药通过地表径流、地下水等进入养殖水体）和饵料带入（农药通过饲料进入水产品体内）。这两种途径是水产品农药残留的主要来源。' WHERE id = '814ab956-d3b2-4f7e-b76d-a29cec9f582e';
UPDATE public.questions SET analysis = '根据《食用农产品市场销售质量安全监督管理办法》第二十条，食用农产品批发市场应当配备检验设备和检验人员或者委托符合本法规定的食品检验机构，对进入该批发市场销售的食用农产品进行抽样检验。' WHERE id = '8167c2ce-f11a-41f0-950d-5ea973ed9fa6';
UPDATE public.questions SET analysis = '根据《保健食品注册与备案管理办法》第四十五条，因遗失申请补发的保健食品注册证书应当标注''补发''字样和补发日期。补发证书与原证书具有同等效力。' WHERE id = '817721be-c161-4d0a-8635-139fcb205cd3';
UPDATE public.questions SET analysis = '根据《食品安全法》第四十四条，食品生产经营企业应当建立健全食品安全管理制度，对职工进行食品安全知识培训，加强食品检验工作，依法从事生产经营活动。这是企业的法定义务。' WHERE id = '8182ed0d-c763-4642-9c78-31e0d925a489';
UPDATE public.questions SET analysis = '根据《食品生产许可管理办法》第三十四条，食品生产者需要延续食品生产许可有效期的，应当在该食品生产许可有效期届满30个工作日前，向原发证的市场监督管理部门提出申请。' WHERE id = '81ad3cf5-a4d6-496b-af87-cf903f65d409';
UPDATE public.questions SET analysis = '根据《特殊医学用途配方食品注册管理办法》第四十二条，食品药品监督管理部门及其工作人员在注册审评过程中滥用职权、玩忽职守、徇私舞弊，造成不良后果的，对直接负责的主管人员和其他直接责任人员依法给予处分。' WHERE id = '81c77510-ac37-4efc-8615-e9104809eff4';
UPDATE public.questions SET analysis = '根据《食品安全法》第二十二条，食品安全风险监测结果表明可能存在食品安全隐患的，接到通知的食品生产经营者应当立即进行自查。自查是生产经营者主动排查风险的重要措施。' WHERE id = '81d00ac2-e566-4e0a-84fb-0ee2ade872c3';
UPDATE public.questions SET analysis = '申请注销食品经营许可的，应当向原发证的市场监督管理部门提交食品经营许可注销申请书以及与注销有关的其他材料。但食品经营者取得经营许可后未开展经营活动的，不适用此注销程序。题目表述不完全准确。' WHERE id = '81d13443-b5d4-4363-96e2-d0dc66215e51';
UPDATE public.questions SET analysis = '白酒生产过程中违法添加的物质包括：工业酒精、甲醇、非食用色素、非食用香精香料等。上述物质严禁添加到白酒中，会对人体健康造成严重危害。以上四项均为常见违法添加物。' WHERE id = '81d39111-794d-4d32-a7e4-bae0ccd3c5c2';
UPDATE public.questions SET analysis = '根据《关于办理危害食品安全刑事案件适用法律若干问题的解释》第一条，生产、销售不符合食品安全标准的食品，具有造成严重食物中毒事故、其他严重食源性疾病、重金属超标、农药残留超标等情形的，应当认定为''足以造成严重食物中毒事故''或者其他严重食源性疾病。以上四项均正确。' WHERE id = '81e35192-e99a-455e-be66-319027913fab';
UPDATE public.questions SET analysis = '根据《食品安全法》第五十三条，食品经营企业应当建立食品进货查验记录制度，如实记录食品的名称、规格、数量、生产日期或生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容。以上四项均为法定记录内容。' WHERE id = '820127b4-f3e3-4f42-8021-e2da3138a26d';
UPDATE public.questions SET analysis = '根据《食品安全法》第七十九条，保健食品广告不得含有表示功效、安全性的断言或保证（A），不得声称或暗示为保障健康所必需（C），不得利用广告代言人作推荐、证明（D）。以上三项均为保健食品广告禁止内容。' WHERE id = '82332f56-fcef-4c8b-b9e6-da661dba89a1';
UPDATE public.questions SET analysis = '根据GB 29921《食品安全国家标准 预包装食品中致病菌限量》，即食类预包装淀粉制品的致病菌限量应符合该标准中粮食制品类的规定。GB 29921是预包装食品致病菌限量的通用标准。' WHERE id = '823359bf-1098-4a99-a499-203a45156f21';
UPDATE public.questions SET analysis = '根据《食品经营许可管理办法》第十一条，餐饮服务提供者申请食品经营许可应具有与经营的食品品种、数量相适应的场所，保持环境整洁，与有毒有害场所及其他污染源保持规定距离。以上四项均为场所要求的正确描述。' WHERE id = '82399417-0891-4512-a40a-834be21aa908';
UPDATE public.questions SET analysis = '根据《食品安全法》第七十一条，食品和食品添加剂的标签、说明书，不得含有虚假内容，不得涉及疾病预防、治疗功能。非保健类食品即使确有某些功效，也不得在标签中暗示其保健作用。该行为违反法律规定。' WHERE id = '823a21eb-2173-4a79-92f3-ce02bdd403e6';
UPDATE public.questions SET analysis = '根据《最高人民法院关于审理食品安全民事纠纷案件适用法律若干问题的解释》第三条，消费者因不符合食品安全标准的食品受到损害，依据食品安全法第一百四十八条的规定请求赔偿的，人民法院应予支持。但法律另有规定的除外。题目表述不正确。' WHERE id = '8257a5e9-9a5a-4b33-8227-5643a9ff9218';
UPDATE public.questions SET analysis = '根据《食品召回管理办法》第二十三条，食品生产企业停止生产、召回和处置的不安全食品存在较大风险的，应当在停止生产、召回和处置不安全食品结束后5个工作日内向县级以上地方市场监督管理部门书面报告情况。' WHERE id = '8280ee9f-2c89-4392-8385-b977af0ae389';
UPDATE public.questions SET analysis = '根据《保健食品标注警示用语指南》，保健食品标签设置警示用语区及标注警示用语，警示用语区所占面积不应小于最小销售包装主要展示版面的20%，而非10%。题目表述错误。' WHERE id = '82879150-8c70-4409-b7ab-4415bfa0c626';
UPDATE public.questions SET analysis = '根据《食品安全法》第五条，国务院设立食品安全委员会，其职责由国务院规定。食品安全委员会是国务院统筹协调食品安全工作的议事协调机构。' WHERE id = '828c646e-440e-4fd1-8654-79468d255761';
UPDATE public.questions SET analysis = '根据GB 25190《食品安全国家标准 灭菌乳》的规定，仅以生牛（羊）乳为原料的超高温灭菌乳，应在产品包装主要展示面上紧邻产品名称的位置，使用不小于产品名称字号且字体高度不小于主要展示版面高度五分之一的字体标注''纯牛（羊）奶''或''纯牛（羊）乳''。' WHERE id = '82b2046b-654b-4302-bccb-20e21d978fd3';
UPDATE public.questions SET analysis = '接触白酒酒体的容器、管道等工器具应使用不锈钢、陶瓷、玻璃等食品级材质，不会对酒体造成污染。铁、铜、铝等活泼金属材质可能与酒体发生反应，影响酒质安全。' WHERE id = '82b3163e-c94e-4b78-be02-86a46cd15cc2';
UPDATE public.questions SET analysis = '根据GB/T 1355《小麦粉》的规定，加工精度按标准样品或仪器测定值对照检验麸星。麸星含量是评价小麦粉加工精度的重要指标。' WHERE id = '82b42f7c-a814-4a59-a896-a1d724b51fbf';
UPDATE public.questions SET analysis = '根据《食品经营许可管理办法》，从事散装食品销售活动应当依法取得食品经营许可。散装食品销售属于食品经营行为，必须取得相应的许可方可从事。' WHERE id = '82b73967-270d-4bd6-bce6-9074daa99bfc';
UPDATE public.questions SET analysis = '根据《反不正当竞争法》第八条，保健食品经营者不得对其商品的性能、功能、质量、销售状况、用户评价、曾获荣誉等作虚假或者引人误解的商业宣传，欺骗、误导消费者。以上四项均不得作虚假宣传。' WHERE id = '82bdd6aa-20b9-4936-bc3d-69c5af15c22e';
UPDATE public.questions SET analysis = 'GB 7718《食品安全国家标准 预包装食品标签通则》是强制性国家标准，对预包装食品标签的标注内容、格式等作出了统一规定。所有预包装食品的标签均应符合该标准要求。' WHERE id = '82be1c48-3d35-45ec-9ac4-649a10c77a4e';
UPDATE public.questions SET analysis = '根据《食品安全法》第五十三条，实行统一配送经营方式的食品经营企业，可以由企业总部统一查验供货者的许可证和食品合格证明文件，进行食品进货查验记录。各门店无需独自重复查验。' WHERE id = '82bf02e1-8dce-4ef9-9a68-b36079e8b0d7';
UPDATE public.questions SET analysis = '根据《学校食品安全与营养健康管理规定》第十五条，学校应建立食品安全与营养健康状况自查制度。经营条件发生变化不再符合食品安全要求的，学校食堂应当立即整改。' WHERE id = '82de3992-3d93-4b2c-b279-65c71d7330a8';
UPDATE public.questions SET analysis = '根据GB 14881《食品生产通用卫生规范》的规定，食品生产企业选址应避免污染，厂区环境应整洁。选址时需要综合考虑周边环境对食品生产的影响，不得选址在对食品有显著污染的区域。' WHERE id = '82dfe5c6-b6ed-4401-981e-f8921f8a88b2';
UPDATE public.questions SET analysis = '根据GB 14881《食品生产通用卫生规范》的规定，墙面、隔断应使用无毒、无味的防渗透材料建造，在操作高度范围内的墙面应光滑、不易积累污垢且易于清洁。这是生产车间卫生设计的基本要求。' WHERE id = '82f2d8b7-c33d-4a83-9258-c00adabeee0d';
UPDATE public.questions SET analysis = '食品生产经营企业可以通过对动植物性原料彻底清洗和充分加热、控制温度和时间，以及在生产、销售、餐饮服务过程中将使用加工制作设备设施生熟分开等方式，有效降低食品中致病性微生物污染的风险。' WHERE id = '82f67475-5aae-4ccb-860b-9e9c3d583abe';
UPDATE public.questions SET analysis = '葡萄酒及果酒的生产工艺流程一般包括：原料处理、发酵、陈酿、调配、灌装等工序。具体工艺因产品类型不同而有所差异，但发酵是核心工序。' WHERE id = '83026e27-8a6e-498c-9ec3-8ec5702267e3';
UPDATE public.questions SET analysis = '根据《食品安全法》第四十五条，从事接触直接入口食品工作的食品生产经营人员应当每年进行健康检查，取得健康证明后方可上岗工作。食品销售从业人员中接触直接入口食品的同样需要取得健康证明。' WHERE id = '833a0b30-31c5-4ca5-a05a-032a901e51c0';
UPDATE public.questions SET analysis = '根据《食品安全抽样检验管理办法》第四十条，食品生产经营者收到监督抽检不合格检验结论后，可以在收到检验结论之日起7个工作日内提出复检申请。食品生产者不能自行选择复检机构，应当向组织抽检的市场监管部门提出复检申请。' WHERE id = '834248d5-21d6-4b73-8644-207ca4bb57dc';
UPDATE public.questions SET analysis = '根据《食品安全法》第四十四条，食品生产经营企业应当对职工进行食品安全知识培训，保证食品安全。食品经营企业同样负有对员工进行食品安全培训的义务。' WHERE id = '8343f87b-de63-4e98-88a7-d2f94fd9329d';
UPDATE public.questions SET analysis = '根据《餐饮服务明厨亮灶工作指导意见》,''明厨亮灶''公开的重点内容包括：原料采购与贮存、食品加工操作过程、餐饮具清洗消毒等关键环节。以上三项均为重点公开内容。' WHERE id = '83524680-1030-4b18-861d-66a239253110';
UPDATE public.questions SET analysis = '根据GB 14881《食品生产通用卫生规范》的规定，原料、半成品、成品、包装材料等应依据性质的不同分设贮存场所或分区域码放，并有明确标识，防止交叉污染。这是食品生产物料管理的基本要求。' WHERE id = '8360fd5b-aab3-48fe-b7fe-cbcb3ad08db3';
UPDATE public.questions SET analysis = '食品污染分为生物性污染（微生物、寄生虫）、物理性污染（异物、放射性物质）和化学性污染（农药残留、重金属、食品添加剂滥用等）。天然色素属于食品中允许使用的成分，不属于化学污染。' WHERE id = '83633128-280f-4665-9b93-01262d4c2e54';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第十七条，食品生产经营企业应当对食品安全知识培训、考核情况予以记录，存档备查。记录是证明企业落实培训义务的重要依据。' WHERE id = '8364c7e5-69e3-4bab-8765-711684cc6eef';
UPDATE public.questions SET analysis = '根据《食品安全抽样检验管理办法》第三十七条，复检结论与初检结论一致的，复检费用由复检申请人承担。复检结论与初检结论不一致的，复检费用由初检机构承担。' WHERE id = '837a50f3-a331-4e74-809e-560efeaa9420';
UPDATE public.questions SET analysis = '根据GB 19295-2021《食品安全国家标准 速冻面米与调制食品》的规定，感官要求包括：具有该产品应有的色泽、滋味与气味，无异味；具有该产品应有的形态，无明显异常。题目表述符合标准要求。' WHERE id = '837aa0be-6003-4b35-8956-8af8d9ec0585';
UPDATE public.questions SET analysis = '根据《婴幼儿配方乳粉产品配方注册管理办法》的规定，审评机构应当自受理之日起60个工作日内完成审评工作。现场核查、补正材料等时间不计入审评时限。' WHERE id = '837ba1ad-4492-47ee-b03f-aeb948ab37ee';
UPDATE public.questions SET analysis = '根据GB 14881《食品生产通用卫生规范》的规定，厂房内应有充足的自然采光或人工照明，光泽和亮度应能满足生产和操作需要，光源应使食品呈现真实的颜色。这是生产车间照明的基本要求。' WHERE id = '837c14c3-10ff-4ee8-80a0-2c918a3fd875';
UPDATE public.questions SET analysis = '根据《食用农产品市场销售质量安全监督管理办法》第二条，食用农产品不包括法律法规禁止食用的野生动物产品及其制品。禁止食用的野生动物不受食用农产品法规的保护和规制。' WHERE id = '8383d6c3-ad18-4cbf-a5b3-7f0d8e2487fa';
UPDATE public.questions SET analysis = '根据《食品安全法》第三十三条和《企业落实食品安全主体责任监督管理规定》第五条，食品经营企业应当配备食品安全管理人员并经考核合格。配备合格的食品安全管理人员是企业的法定义务。' WHERE id = '83a1534b-e637-459a-a0aa-c9ddd0873ece';
UPDATE public.questions SET analysis = '根据《食品安全法》第三条，食品安全工作实行预防为主、风险管理、全程控制、社会共治，建立科学、严格的监督管理制度。以上四项是食品安全工作的基本原则。' WHERE id = '83b0a07c-bcaa-437d-801b-3467651087ad';
UPDATE public.questions SET analysis = '根据《食品安全法》第一条，为了保证食品安全，保障公众身体健康和生命安全，制定本法。食品安全是制定该法的核心目的。' WHERE id = '83c5d9a9-52c4-4a6a-ae9b-c2c4123848fb';
UPDATE public.questions SET analysis = '根据《食品安全法》第六十三条，食品生产企业对因标签、标志或者说明书不符合食品安全标准而被召回的食品，采取补救措施且能保证食品安全的情况下可以继续销售。并非只能采取销毁措施。' WHERE id = '83dbd6d1-dc0e-49da-adb1-26c77fea3086';
UPDATE public.questions SET analysis = '根据《食品安全法》第七十四条，特殊食品包括保健食品、特殊医学用途配方食品和婴幼儿配方食品三大类。普通食品不属于特殊食品范畴。' WHERE id = '83e490e3-97ed-4992-93c4-9e5c2974242c';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》，企业食品安全管理人员中，食品安全总监协助主要负责人做好食品安全管理工作，食品安全员协助食品安全总监落实具体管理措施。' WHERE id = '83e55243-3a67-40e6-986b-328135e647a5';
UPDATE public.questions SET analysis = '根据GB 2762-2022《食品安全国家标准 食品中污染物限量》，黄酒中铅的限量值为0.2mg/L。该标准对酒类中的重金属含量设定了明确的限量要求。' WHERE id = '83f04dee-0b0d-4322-b95d-3efe789f278d';
UPDATE public.questions SET analysis = '根据《食品安全法》第四十七条，发生食品安全事故潜在风险的，应当立即停止食品生产经营活动，并向所在地县级人民政府食品安全监督管理部门报告。' WHERE id = '8411bd42-82f2-4d73-82f2-ae77125b8afe';
UPDATE public.questions SET analysis = '砖茶使用茶的成熟叶片、叶梗等含氟量较高的原料加工而成，导致成品砖茶的氟含量较高。根据GB 19965《砖茶含氟量》的规定，砖茶氟含量有专门限量标准。' WHERE id = '841f9110-bc12-4855-88b8-c4e7613cb8c9';
UPDATE public.questions SET analysis = '根据《行政处罚法》第七条，公民、法人或者其他组织对行政机关所给予的行政处罚，享有陈述权、申辩权；对行政处罚不服的，有权依法申请行政复议或提起行政诉讼；因行政机关违法给予行政处罚受到损害的，有权依法提出赔偿要求。以上四项均为法定权利。' WHERE id = '84226b4b-b022-4279-ab7d-95aefcdfb625';
UPDATE public.questions SET analysis = '根据《食品安全法》第六十八条和相关规定，销售散装食品应当在散装食品的容器、外包装上标明食品的名称、生产日期或者生产批号、保质期以及生产经营者名称、地址、联系方式等内容。不需要标示产品标准代号。' WHERE id = '842b9e04-a0d8-4a37-aeb9-3b1519a501fa';
UPDATE public.questions SET analysis = '黄酒的主要生产工艺流程包括：原料处理（浸米、蒸饭）、糖化发酵、压榨、煎酒、陈酿、过滤、灌装等。以上各项均属于黄酒生产工艺流程的环节。' WHERE id = '843fd0e6-fce6-40ea-bf6b-490e0d300f44';
UPDATE public.questions SET analysis = '根据《食品生产经营日常监督检查管理办法》第二十四条，日常监督检查结果为不符合，有发生食品安全事故潜在风险的，食品生产企业应当立即停止食品生产活动，而非三日内停止。' WHERE id = '8440c472-d9c3-4cec-bda0-9f15a600049b';
UPDATE public.questions SET analysis = '根据《乳品质量安全监督管理条例》第三十六条，乳制品生产企业发现其生产的乳制品不符合国家标准、存在危害人体健康危险的，应当立即停止生产，报告监管部门，通知销售者和消费者，召回问题产品，并记录相关情况。以上四项均为法定义务。' WHERE id = '8459d6eb-f9ad-4d4c-9bdb-5f68b6f5385a';
UPDATE public.questions SET analysis = '根据GB 2760《食品安全国家标准 食品添加剂使用标准》，食品添加剂的使用原则是：在达到预期效果的前提下尽可能降低在食品中的使用量。应遵循必要性原则和最小化原则，而非''尽可能增加''。' WHERE id = '845efbe2-cd00-4ab7-a6e9-481f21558154';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第四条，企业主要负责人对本企业食品安全工作全面负责。主要负责人是食品安全的第一责任人。' WHERE id = '8461d0fe-bcc8-4a40-9232-29601d416f5d';
UPDATE public.questions SET analysis = '根据《食品安全法》第七十九条，保健食品广告内容应当经省级以上人民政府食品安全监督管理部门审查批准，取得广告批准文件。特殊医学用途配方食品广告参照药品广告管理。' WHERE id = '847d64e2-be92-4278-99b0-725585bca742';
UPDATE public.questions SET analysis = '根据GB 2760《食品安全国家标准 食品添加剂使用标准》的规定，食品添加剂的使用目的不包括掺杂、掺假、伪造。使用食品添加剂应以改善食品品质、防腐保鲜等正当目的为前提。' WHERE id = '84c04700-a385-4d7b-a2cd-7c661ea3238f';
UPDATE public.questions SET analysis = '肉及肉制品中常见的农药残留主要为有机磷和有机氯农药，主要经过食物链和生物富集作用聚集在动物的脂肪组织，或不法厂家生产过程中违规使用农药处理肉制品所致。' WHERE id = '84c9490e-4bd7-48f2-b288-201a1560fdc7';
UPDATE public.questions SET analysis = '根据HACCP体系相关标准（GB/T 27341等），危害是指食品中所含有的对健康有潜在不良影响的生物性、化学性或物理性因素。这三类危害是HACCP体系分析评估的核心内容。' WHERE id = '84e1e683-f842-4c03-afd2-8e07b7a2fb4b';
UPDATE public.questions SET analysis = '题目要求选择''不正确''的说法。A选项内容需要根据具体选项确定，但题目答案为A，说明A选项的表述不正确。需结合具体选项内容判断。' WHERE id = '84fb6a1a-1484-4f48-8005-f1636c4433aa';
UPDATE public.questions SET analysis = '根据GB 31646-2018《食品安全国家标准 速冻食品生产和经营卫生规范》，冷冻原料解冻应具备专用解冻区域，根据原料特性、形态确定适宜的解冻方法，控制解冻温度和时间。' WHERE id = '85052ab4-a122-49bb-bf39-88c2062cc43a';
UPDATE public.questions SET analysis = '根据《网络餐饮服务食品安全监督管理办法》第十八条，入网餐饮服务提供者加工制作餐饮食品应当符合下列要求：具有与经营的食品品种、数量相适应的加工场所和设备设施；加工过程符合餐饮服务食品安全操作规范；使用无毒、清洁的食品容器和包装材料；保持网络销售的餐饮食品与实体店销售的餐饮食品质量安全一致。' WHERE id = '8515110f-7077-4611-8a8d-cf2256197009';
UPDATE public.questions SET analysis = '根据《标准化法》第二条，行业标准的技术要求不得低于强制性国家标准的相关技术要求。强制性国家标准是技术要求的底线，行业标准、地方标准、企业标准的技术要求均不得低于强制性国家标准。' WHERE id = '851f7f07-ef10-487c-85b0-9cab08bf0b5d';
UPDATE public.questions SET analysis = '根据《食品生产许可管理办法》第四条，食品生产许可实行一企一证原则，同一个食品生产者从事食品生产活动，应当取得一个食品生产许可证。该原则简化了许可管理程序。' WHERE id = '85216ce5-c506-4ba6-b8ce-2a22d42c5f41';
UPDATE public.questions SET analysis = '酒类生产企业应当按照相应的生产许可工艺生产相应类别酒类，优化生产工艺参数，改良生产工器具，确保产品质量安全。优化工艺和工器具是提高产品质量的重要措施。' WHERE id = '853e529c-1ac8-4a68-9b63-c46918135732';
UPDATE public.questions SET analysis = '根据GB 24154-2015《食品安全国家标准 运动营养食品》的规定，运动营养食品的微生物限量要求项目包括菌落总数和大肠菌群（C、D选项），不包括致病菌等其他项目。沙门氏菌和金黄色葡萄球菌在部分运动营养食品中可能有要求，需具体查看标准。' WHERE id = '8545ed57-0256-4301-9536-e29acbd93b3a';
UPDATE public.questions SET analysis = '根据GB 2758《食品安全国家标准 发酵酒及其配制酒》的规定，啤酒中甲醛的限量标准为2.0mg/L。甲醛是发酵酒中可能产生的污染物，需要严格控制。' WHERE id = '8550d270-817f-48c1-bba6-aee1b9a7cac6';
UPDATE public.questions SET analysis = '根据《企业落实食品安全主体责任监督管理规定》第十条，餐饮服务企业应当建立''日管控、周排查、月调度''制度。企业主要负责人每月至少听取1次食品安全总监管理工作情况汇报。' WHERE id = '8555ab8e-4b28-48cb-9b55-61b104880944';
UPDATE public.questions SET analysis = '根据《食品安全法》第三十四条，禁止生产用非食品原料生产的食品、添加食品添加剂以外的化学物质和其他可能危害人体健康物质的食品、用回收食品作为原料生产的食品、腐败变质的食品等。以上四项均为禁止生产的食品。' WHERE id = '8597d44f-6624-4744-94eb-cb34b4fc71b2';
UPDATE public.questions SET analysis = '根据《食品生产经营日常监督检查管理办法》第二十九条，食品生产企业撕毁、涂改日常监督检查结果记录表，或者未保持日常监督检查结果记录表至下次日常监督检查的，由市、县级食品安全监督管理部门责令改正，给予警告，并处2000元以上3万元以下罚款。' WHERE id = '85ac28be-5074-4b52-ad20-6652f8f757a1';
UPDATE public.questions SET analysis = '根据《学校食品安全与营养健康管理规定》第十六条，学校采购食品及原料应当遵循安全、健康、符合营养需要的原则。以上三项均为学校采购食品及原料的基本原则。' WHERE id = '85c05b15-fd51-42ea-b8c4-dc07829c7117';
UPDATE public.questions SET analysis = '饼干生产的主要工艺流程包括：原辅料处理、面团调制、成型、烘烤、冷却、包装等工序。以上各项均属于饼干生产工艺流程的环节。' WHERE id = '85cb72f6-b318-43c4-8a96-35eda25e259a';
UPDATE public.questions SET analysis = '根据《食品经营许可管理办法》的规定，连锁食品销售企业总部作为食品经营活动的组织者和管理者，应当依法申请取得食品经营许可。各连锁门店也需分别取得经营许可。' WHERE id = '85cd9817-5eec-4ebd-ae21-43fea75a6b44';
UPDATE public.questions SET analysis = '采用包装后杀菌工艺的罐头（如玻璃瓶装罐头），其工艺主要包括：装罐、封口、杀菌、冷却等工序。与先杀菌后装罐的工艺不同，包装后杀菌工艺的产品在封口后进行杀菌处理。' WHERE id = '85d373a5-aba9-4d7c-a1e5-36620d079597';
UPDATE public.questions SET analysis = '根据GB 2760《食品安全国家标准 食品添加剂使用标准》的规定，酱腌菜生产中允许使用的食品添加剂品种有限制。部分食品添加剂（如某些色素、防腐剂等）不允许用于酱腌菜生产。需根据标准确定具体禁用品种。' WHERE id = '85d5f84e-c3dc-4d94-bff1-96aaeb1b9aee';
UPDATE public.questions SET analysis = '根据《食品安全法》第六十三条，食品生产经营企业应当建立食品召回制度，对发现的不安全食品实施召回并依法处置。召回制度是保障食品安全的重要措施。' WHERE id = '85f08915-0ae7-4396-b08b-a8fd3c919fae';
UPDATE public.questions SET analysis = '根据《餐饮服务食品安全操作规范》的规定，集体用餐配送单位配送的食品，应在包装、容器或配送箱上标注配送单位信息、加工时间和食用时限。冷藏保存的食品还应标注保存条件和温度要求。' WHERE id = '85f3b360-69da-46ac-b40a-e6eb6e6ec952';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》(总局60号令)要求，食品销售企业应制定食品安全事故处置方案，包括事故分级划分、事故处置程序、事故演练要求和责任追究等内容。' WHERE id = '85fc126e-c4a7-41fa-a167-829adfd7c409';
UPDATE public.questions SET analysis = '《食品经营许可和备案管理办法》规定，已取得食品经营许可增加预包装食品销售的、已取得食品生产许可的食品生产者在其生产加工场所销售的、通过网络销售其生产的预包装食品的，不需要另行备案。但经营场所发生变化需重新备案。' WHERE id = '85ff9e52-fa15-4507-b59a-4a4beb0c4079';
UPDATE public.questions SET analysis = '《食品安全国家标准 蜂蜜》(GB 14963)规定微生物指标包括菌落总数、大肠菌群、金黄色葡萄球菌和霉菌限量，这是保障蜂蜜食用安全的重要指标。' WHERE id = '861326cf-b103-4369-b71c-bee9ff01a7ab';
UPDATE public.questions SET analysis = '《食品安全法》第四十七条规定，食品生产经营者发现有食品安全事故潜在风险的，应当立即停止食品生产经营活动，并向所在地县级人民政府食品安全监督管理部门报告。不可边生产边报告。' WHERE id = '8627eb9c-4705-4e20-b82a-d7cc4b3e115c';
UPDATE public.questions SET analysis = '该说法正确，符合《食品安全法》及相关法规标准的规定。食品生产经营者应当严格遵守该要求，落实食品安全主体责任。' WHERE id = '86310c7d-c2f6-47c7-aadf-3e2901027841';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》明确规定，一次性餐饮具不得重复使用。重复使用一次性餐饮具存在交叉污染和食品安全隐患，违反食品安全基本要求。' WHERE id = '86432b13-4808-421e-a5d8-3afe32f59ab3';
UPDATE public.questions SET analysis = '《食品安全国家标准 糕点、面包》(GB 7099)中菌落总数和大肠菌群指标适用于冷加工糕点，不适用于现制现售产品和含有未熟制发酵配料的产品。' WHERE id = '86550bb6-7447-4e85-a109-fd1093fba89e';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》(总局60号令)要求，食品安全总监和食品安全员应掌握食品安全法律法规和标准，具备识别和防控食品安全风险的专业能力，熟悉本企业工艺流程，能判断风险隐患并采取预防措施。' WHERE id = '86921540-2520-4705-aa2e-3668b60bbc1c';
UPDATE public.questions SET analysis = '正确答案为A,B,C,D。A(农药残留)、B(生物毒素)、C(重金属)、D(致病性微生物)均符合《食品安全法》及相关法规标准的规定。其他选项不符合食品安全相关法律法规要求。' WHERE id = '86ad93dd-b37e-4a2a-93c8-b1fcf02e2d3e';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条及《餐饮服务食品安全操作规范》规定，食品加工用水水质应符合GB 5749《生活饮用水卫生标准》，有特殊要求的应符合相应规定。' WHERE id = '86b3324c-1a7e-4d4c-a643-a2d7cd2ef797';
