UPDATE public.questions SET analysis = '《食品安全国家标准 植物油》(GB 2716)及《食用动物油脂》(GB 10146)规定，单一品种的食用植物油、食用动物油脂不应掺杂其他油脂，以保障产品质量和消费者权益。' WHERE id = '86e736e9-ac04-447e-a6f7-b0d2e9d7c826';
