UPDATE public.questions SET analysis = '《网络餐饮服务食品安全监督管理办法》规定，网络餐饮服务第三方平台提供者应当与入网餐饮服务提供者签订食品安全协议，明确双方食品安全责任。' WHERE id = '86f7c177-338f-4934-85fb-bbddf26a88ed';
