UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，专间和专用操作区使用的食品容器、工具、设备和清洁工具应专用，使用前应清洗消毒并保持清洁，以防止交叉污染。' WHERE id = '8704047b-265b-44a3-81ff-44bf542ae623';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，食品处理区应按原料进入、原料制作、半成品制作、成品供应的流程合理布局，防止食品在存放、加工和传递中发生交叉污染。' WHERE id = '8706cb97-6653-4b78-abd2-de08face6e77';
