UPDATE public.questions SET analysis = '《食品安全法》确立食品安全社会共治原则，调动政府监管部门、食品生产经营者、行业协会、消费者协会乃至公民个人等各方力量，共同参与食品安全工作。' WHERE id = '87c5488a-532c-4452-87f9-a4f8d3c2238c';
UPDATE public.questions SET analysis = '《市场监督管理严重违法失信名单管理办法》规定，对列入严重违法失信名单的企业，市场监管部门应依法依规采取行政性约束和惩戒措施，实施联合惩戒。' WHERE id = '87e7fa71-52a2-4ce5-94b8-fbbef8c9d22d';
UPDATE public.questions SET analysis = '正确答案为C。检验设备和检验人员符合《食品安全法》及相关法规标准的规定。其他选项不符合食品安全相关法律法规要求。' WHERE id = '87eaa701-0b11-48f9-a418-310dd1fa30cc';
