UPDATE public.questions SET analysis = '《食品安全法》第一百三十五条规定，因食品安全犯罪被判处有期徒刑以上刑罚的，终身不得从事食品生产经营管理工作，不得担任食品安全管理人员，不存在五年期限。' WHERE id = '88160e01-a507-41cc-b343-58151e5aaba4';
