UPDATE public.questions SET analysis = '《食品安全法》第一百一十条规定，市场监督管理部门有权进入生产经营场所检查、抽样检验、查阅复制相关资料、查封扣押不符合安全标准的食品和违法生产经营工具设备。' WHERE id = '91386993-9583-49a3-a8f8-b0f4cae97484';
