UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》(总局60号令)要求企业建立基于食品安全风险防控的动态管理机制，而非静态管理机制，需持续改进和更新。' WHERE id = '9190da74-79dc-43d9-bcf2-a618840f1dc0';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 冷冻饮品和制作料》（GB 2759）及《食品生产通用卫生规范》（GB 14881），冷冻饮品生产过程应加强卫生控制和规范操作（A），制定微生物监控计划（B），必要时监测单增李斯特氏菌等致病菌（C），并规范管理食品添加剂使用（D）。四项均为冷冻饮品生产管控的重点内容。' WHERE id = '919eb015-bd13-4c05-acdc-306c54a93500';
UPDATE public.questions SET analysis = '《食品安全法》第九十七条规定：进口的预包装食品、食品添加剂应当有中文标签；依法应当有说明书的，还应当有中文说明书。标签、说明书应当符合本法及我国其他有关法律、行政法规的规定和食品安全国家标准的要求。' WHERE id = '91b772b5-99d3-46ac-9565-c2dda702bb02';
UPDATE public.questions SET analysis = '根据《保健食品注册与备案管理办法》第四十二条规定，保健食品注册证书遗失或者损坏的，保健食品注册人应当向受理机构提出书面申请并说明理由。因涉及证书补发，须以书面形式正式申请。' WHERE id = '91ba6830-daed-47d1-8840-2b20d0641d0e';
UPDATE public.questions SET analysis = '《食品安全国家标准 预包装食品标签通则》（GB 7718）规定，当预包装食品包装物或容器最大表面面积小于10cm²时，可只标示产品名称、净含量、生产者（或经销商）的名称和地址。此为标签豁免条款。' WHERE id = '91d8f81a-1096-4200-8fc3-8ef714518fb7';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 水果制品》（GB 14884）及相关生产许可审查细则，水果制品是以水果为原料，经各种加工工艺和方法制成的产品，包括蜜饯、果酱、果干等。该表述符合标准定义。' WHERE id = '91db8c23-e4b0-4afa-9ab9-d07d39ff69fa';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条明确规定，禁止生产经营超过保质期的食品。超过保质期的食品不可继续销售（A错）、不可降价销售（B错）、不可作处理食品销售（D错），应及时下架处理。' WHERE id = '91db933e-1ab3-4899-ba94-e633513a6d56';
UPDATE public.questions SET analysis = '根据《反食品浪费法》第七条规定，餐饮服务经营者应采取多种措施防止食品浪费：在醒目位置张贴反食品浪费标识（A），服务人员提示引导按需点餐（B），在菜单上标注食品分量、建议消费人数等信息（C）。D选项诱导消费者超量点餐属于违法行为。' WHERE id = '91e0fede-8331-4456-9a5e-e900dbbdbf61';
UPDATE public.questions SET analysis = '《食品生产经营风险分级管理办法》第七条规定，食品生产经营者风险等级从低到高划分为A级风险、B级风险、C级风险、D级风险四个等级。注意是从低到高，不是从高到低。' WHERE id = '91e2e6d3-1642-4de0-bcfd-589cc30d3fb6';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营企业应当建立食品进货查验记录制度；从事保健食品批发业务的经营企业应当建立销售记录制度，如实记录批发食品的名称、规格、数量等内容，并保存相关凭证。' WHERE id = '91e33a80-1231-4104-927f-afa75817e88e';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 餐饮服务通用卫生规范》（GB 31654），冷冻是指将原料、半成品、成品置于冰点温度以下以保持冰冻状态贮存的过程，冷冻温度范围宜低于-12℃（A正确），而非-8℃、-10℃或0℃。' WHERE id = '91e6567c-0655-4a21-b76b-ef6f296b30ea';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 发酵乳》（GB 19302），发酵乳对酵母和霉菌有微生物限量要求。巴氏杀菌乳（GB 19645）和调制乳（GB 25191）标准中无酵母和霉菌限量要求。' WHERE id = '91fd7ed3-9094-4475-ba70-f0b4cf7adbe5';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》（总局令第60号）要求企业建立健全食品安全管理制度，落实食品安全责任制，配备食品安全管理人员，制定食品安全风险管控清单，落实日管控、周排查、月调度工作机制，以防控食品安全风险。' WHERE id = '92180b3f-5c08-40e4-83f0-74f6193bda58';
UPDATE public.questions SET analysis = '《食品安全法》第五十条规定，食品生产者采购食品原料、食品添加剂、食品相关产品，应当查验供货者的许可证和产品合格证明。食品生产企业应建立完整的采购、验收、运输和贮存管理制度。' WHERE id = '921cf5f3-59c8-49c5-910a-199e5a783f40';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》第十条规定，企业法人、合伙企业、个人独资企业、个体工商户等，以营业执照载明的主体作为申请人。营业执照是申请食品生产经营许可的法定身份证明文件。' WHERE id = '921d169d-5c6d-4cbd-9b13-b939abc60294';
UPDATE public.questions SET analysis = '《关于''三新食品''目录及适用的食品安全标准的公告》（2023年第4号）由国家卫生健康委员会发布。新食品原料、食品添加剂新品种和食品相关产品新品种的安全性评估及公告发布属于国家卫健委职责。' WHERE id = '92213ecc-abee-478f-9264-a63b94d874df';
UPDATE public.questions SET analysis = '《食品安全法》第五十一条及《食品生产通用卫生规范》（GB 14881）规定，食品生产企业应如实记录：食品加工过程（A）、产品贮存情况（B）、食品原料相关信息（C）、产品检验信息（D）等内容。记录应真实、完整，保存期限不少于产品保质期满后六个月。' WHERE id = '92618b53-4347-4287-adb0-e8cd5402da19';
UPDATE public.questions SET analysis = '《食用农产品市场销售质量安全监督管理办法》规定，批发市场开办者印制的统一格式销售凭证应载明：食用农产品名称与产地（A）、数量及销售日期（B）、销售者名称地址和联系方式（D）。储存条件及保质期（C）非销售凭证必须载明内容。' WHERE id = '926291d3-d0a9-4344-a305-efff2b11cde2';
UPDATE public.questions SET analysis = '《食品安全法》第三十条规定，国家鼓励食品生产企业制定严于食品安全国家标准或者地方标准的企业标准，在本企业适用，并报省、自治区、直辖市人民政府卫生行政部门备案。' WHERE id = '926c9e9e-6586-4bfc-bb63-597578b4a008';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条禁止标注虚假生产日期。根据《食品生产通用卫生规范》（GB 14881），生产日期应为食品成为最终产品的日期，即包装或灌装日期。2018年1月10日完成包装的产品不得标注2018年3月6日为生产日期。' WHERE id = '92984b3c-f915-4da9-9e5f-b7db142cced3';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 蜂王浆》（GB 9697），蜂王浆是指工蜂咽下腺和上腭腺分泌的，主要用于饲喂蜂王和蜂幼虫的浆状物质，经取浆、过滤（B正确）等工艺加工而成的产品。不需要稀释或调配。' WHERE id = '92bbdebd-9757-4504-9571-007fe408f10c';
UPDATE public.questions SET analysis = '《食品召回管理办法》第二十五条规定，对因标签、标识或说明书不符合食品安全标准而被召回的食品，食品生产者在采取补救措施且能保证食品安全的情况下可以继续销售（C正确），但销售时应当向消费者明示补救措施。' WHERE id = '92bf22f4-46fc-48f1-8d90-17d8ddce8e67';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，从事接触直接入口食品工作的食品生产经营人员应当每年进行健康检查，取得健康证明后方可上岗工作。同时，《食品生产通用卫生规范》（GB 14881）要求食品加工人员应经过卫生培训后方可上岗。' WHERE id = '92c158bf-eda3-475f-99ee-2987ec3b459b';
UPDATE public.questions SET analysis = '食用植物油农药残留限量应符合《食品安全国家标准 食品中农药最大残留限量》（GB 2763）。GB 2760为食品添加剂使用标准，GB 2761为真菌毒素限量标准，GB 2762为污染物限量标准。' WHERE id = '92cf45c0-773b-4939-b45e-56cfdcdcb5d2';
UPDATE public.questions SET analysis = '《食品安全法》第四十七条规定了食品生产经营者自查制度，要求定期对食品安全状况进行检查评价，发现不符合食品安全要求的应立即整改；有发生食品安全事故潜在风险的，应立即停止食品生产经营活动并向所在地食品安全监督管理部门报告。' WHERE id = '92d9ba31-e665-4520-82aa-71d3b0b81a1b';
UPDATE public.questions SET analysis = '《刑法》第一百四十四条规定，在生产、销售的食品中掺入有毒、有害的非食品原料的，对人体健康造成严重危害或有其他严重情节的，处五年以上十年以下有期徒刑（D正确），并处罚金。' WHERE id = '92f485a2-2a2f-414d-bc8b-67a2a1361cce';
UPDATE public.questions SET analysis = '《食品生产经营风险分级管理办法》第七条规定，食品生产经营者的风险等级从低到高分为A级、B级、C级、D级四个等级，而非从高到低排列。该表述顺序错误。' WHERE id = '92f90801-3cc5-405d-b657-03f9f76de98c';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 蒸馏酒及其配制酒》（GB 2757），啤酒应以%vol为单位标识酒精度，而非%。%vol是国际标准体积百分比表示法，%仅表示百分比，表述不准确。' WHERE id = '93256c05-6757-4f7a-855e-1c22def27329';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求食品生产经营企业建立的食品安全管理制度至少包括：日管控、周排查、月调度制度（A），食品安全管理人员培训考核制度（B），从业人员健康管理制度（C），进货查验记录制度（D）。' WHERE id = '932fb696-bb46-4963-9e07-26c4c4a06bdb';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，食品生产经营者应配合监督检查工作，协助监管部门进行现场检查（C）和抽样检验（D）。风险监测和隐患排查不属于食品生产经营者协助的具体检查类型。' WHERE id = '932fecce-0062-4258-a496-7481ee9bd601';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》第五条规定，国家食品药品监督管理总局应当加强信息化建设，提高特殊医学用途配方食品注册管理信息化水平。此处为法定义务，用''应当''。' WHERE id = '933a358e-9a9f-41d4-8234-42cdb6afa27c';
UPDATE public.questions SET analysis = '《广告法》第四条规定，广告不得含有虚假或者引人误解的内容，不得欺骗（B）、误导（C）消费者。广告主应当对广告内容的真实性负责。''诱导''和''欺诈''非广告法原文表述。' WHERE id = '934ab527-0705-4565-b6b4-f7af4aa1b04d';
UPDATE public.questions SET analysis = '《乳制品良好生产规范》（GB 12693）规定，乳制品生产车间内的温度和湿度（C正确）均应符合乳制品加工要求。不同乳制品加工对温度和湿度均有特定要求。' WHERE id = '9372cf43-1102-4b20-bdc7-b8f900d6d09d';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 淀粉糖》（GB 15203），固体淀粉糖产品一般色泽为白色（B）或略带浅黄色（D），因原料和加工工艺不同可能略有差异，无色（A）和棕黄色（C）不符合标准要求。' WHERE id = '939eb253-8414-476c-ad18-fbc3c02662f6';
UPDATE public.questions SET analysis = '《广告法》第二条第五款规定，广告代言人是指广告主以外的，在广告中以自己的名义或者形象对商品、服务作推荐、证明的自然人、法人或者其他组织。该表述符合法律规定。' WHERE id = '93a3b213-2896-42ef-9d8e-d352c3d9fc43';
UPDATE public.questions SET analysis = '《食品安全国家标准 蒸馏酒及其配制酒》（GB 2757）及《预包装饮料酒标签通则》规定，酒精度大于等于10%vol的饮料酒可以免除标示保质期。高酒精度可抑制微生物生长。' WHERE id = '93be53b0-a537-435f-99b0-d7adf6e45dd2';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，外设仓库地址发生变化的，食品经营者应当在变化后10个工作日内向原发证部门报告；食品经营者终止经营或许可证被吊销的，应当在30个工作日内申请办理注销手续。' WHERE id = '93d35cc7-17f2-4994-ba71-06a522f43b13';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定食品经营者应当按照保证食品安全的要求贮存食品。食品经营者应按照食品安全要求而非供货商的要求销售食品，当供货商要求与食品安全要求冲突时，以食品安全要求为准。' WHERE id = '93e32fd1-e280-4cf6-8fcd-b65847674cb9';
UPDATE public.questions SET analysis = '《食品安全国家标准 豆制品》（GB 2712-2014）第3.2条感官要求包括：色泽（A）、滋味（B）、气味（C）、状态（D）四项内容。该标准对豆制品的感官质量有全面规定。' WHERE id = '93e4f3f8-ed5f-4276-b957-0df7bef64d56';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，食品经营者发现其经营的食品不符合食品安全标准，或者有证据证明可能危害人体健康的，应当立即停止经营，通知相关生产经营者和消费者，并记录停止经营和通知情况。' WHERE id = '93f1800d-712e-4c74-ae9a-521c34440493';
UPDATE public.questions SET analysis = '《食品安全法》第九十一条规定，国家出入境检验检疫部门（现海关）对进出口食品安全实施监督管理。该表述符合法律规定。' WHERE id = '93f76a7f-4692-44eb-a24f-b0fe29f0b9a0';
UPDATE public.questions SET analysis = '根据《食品生产许可分类目录》，食用油脂制品包括起酥油（A）、植脂末（B）、代可可脂（D）等。食用动物调和油脂（C）属于食用动物油脂类，不属于食用油脂制品类。' WHERE id = '941648e2-732c-4b3b-976a-c596ce01605a';
UPDATE public.questions SET analysis = '《食盐质量安全监督管理办法》及GB 2721《食用盐》规定，未加碘食盐的标签应当在显著位置标注''未加碘''字样。不标注属于违法行为。' WHERE id = '941c1d3b-5944-4dbe-81c6-b8c94ba70820';
UPDATE public.questions SET analysis = '《食品生产通用卫生规范》（GB 14881）规定，不同清洁要求的同一设备不同部位应分开清洁，并使用不同的清洁工器具，以防止交叉污染。该表述符合规范要求。' WHERE id = '94306436-7734-48ca-b632-faa131a55733';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，保健食品备案的产品配方、原辅料名称及用量、功效、生产工艺等应当符合法律（A）、法规（B）、强制性标准（C）及保健食品原料目录技术要求（D）的规定。' WHERE id = '94362aae-3928-4beb-b9ee-2ae711f6917d';
UPDATE public.questions SET analysis = '根据《食品生产许可分类目录》，速冻调制食品生产许可类别编号为1102（B正确），包括生制品和熟制品。1101为速冻面米制品，1103、1104为其他速冻食品类别。' WHERE id = '943aeb18-c4c8-4a44-b327-9930da49f68f';
UPDATE public.questions SET analysis = '《食品安全法》第一百四十八条第二款规定，生产不符合食品安全标准的食品，消费者除要求赔偿损失外，还可向生产者要求支付价款十倍或者损失三倍的赔偿金（A正确）；增加赔偿的金额不足一千元的，为一千元。' WHERE id = '943b1d6f-ab3b-4725-b89d-b5d81e8c0a3a';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食品添加剂使用标准》（GB 2760），糖精钠（甜蜜素类）不得用于糖果生产。糖果中允许使用的甜味剂不包括糖精钠。' WHERE id = '94553c70-c973-4483-bdf5-6b5e049be7fe';
UPDATE public.questions SET analysis = '《食品安全法》第四十六条规定，食品生产企业应当就以下事项制定并实施控制要求：原料采购、验收、投料等原料控制（A），原料检验、半成品检验、成品出厂检验等检验控制（B），生产工序、设备、贮存、包装等关键环节控制（C），运输和交付控制（D）。' WHERE id = '9458fa6e-06df-4b35-b183-d6a16fbf5a90';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第三十一条规定，复检备份样品超过保质期的，不予复检。因超过保质期后样品已不能代表被抽检产品原始状态，复检结果无参考价值。' WHERE id = '946b0263-1c4d-4577-8b18-62c0377846f5';
UPDATE public.questions SET analysis = '《食品安全国家标准 果冻》（GB 19299）规定微生物指标包括菌落总数（C正确）、大肠菌群、霉菌和酵母。标准未对沙门氏菌和金黄色葡萄球菌作单独要求，枯草芽孢杆菌非指标菌。' WHERE id = '94763014-1365-4980-8eef-585bd020bf4f';
UPDATE public.questions SET analysis = '《食品安全法》第五十四条及《食品经营过程卫生规范》规定，食品经营者应及时清理变质或超过保质期等情形的食品。存在感官性状异常、超过保质期的食品应及时清理下架。' WHERE id = '94995e43-b767-4fea-84d0-df1d3299d6ef';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》明确了食品安全员的职责：检查制度执行情况（A），开展日管控、周排查、月调度（B），督促过程控制、管理记录材料（C），对不安全食品采取整改措施并报告（D），管理从业人员健康和卫生状况（E），配合调查处理食品安全事故（F）。' WHERE id = '94995fca-e591-404c-90fc-56fce9bd50e4';
UPDATE public.questions SET analysis = '《食品安全国家标准 蜂蜜》（GB 14963）及蜂产品制品相关规定明确，以蜂蜜为原料生产蜂产品制品不得添加淀粉糖、糖浆、食糖等物质。添加后产品不能称为纯蜂蜜或蜂产品制品。' WHERE id = '94b38c7a-3d92-4728-9745-edbc65df34cd';
UPDATE public.questions SET analysis = '《食品生产通用卫生规范》（GB 14881）及运输管理规定，食品贮存运输过程中的污染途径包括：不清洁容器带来的污染（A），前运货物带来的污染（B），货物混运带来的交叉污染（C），运输工具卫生状况差（D）。四项均为常见污染途径。' WHERE id = '94b55c53-8a67-4b4d-87b7-f041ef84f92c';
UPDATE public.questions SET analysis = '《未成年人保护法》第五十九条规定，学校、幼儿园周边不得设置烟、酒、彩票销售网点。同时，学校内也不得销售烟酒。该表述错误。' WHERE id = '94bcf7c3-b3b4-4601-a507-3df5bee2dd81';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，日管控制度包括：食品安全员每日按风险管控清单检查（A），记录风险隐患并分析原因明确整改措施（B），检查前一日隐患整改情况（C），及时上报食品安全总监或主要负责人（D），在《每日食品安全检查记录》中如实记录，实行零风险报告（E）。' WHERE id = '94c5efb1-305e-4ee6-9b56-6690bb0d1744';
UPDATE public.questions SET analysis = '根据《食品安全国家标准 食糖》（GB 13104）及食糖生产许可审查细则，白砂糖产品生产在包装区域（D正确）入口应按需设置换鞋设施或工作鞋靴消毒设施。包装区为清洁度要求最高的区域。' WHERE id = '94cc0a94-ee74-44fc-bd22-85e74d062db5';
UPDATE public.questions SET analysis = '《食品安全国家标准 餐饮服务通用卫生规范》（GB 31654）规定，餐饮服务提供者应建立餐饮具清洗消毒管理制度，规范清洗、消毒、保洁流程。该表述符合标准要求。' WHERE id = '94cfa34a-10fc-471c-98f0-527ba1d19da6';
UPDATE public.questions SET analysis = '《集中用餐单位食品安全管理规定》并未将被列入经营异常名录的企业列为不得承包集中用餐单位食堂的绝对禁止情形。需结合具体违法违规情况判断。该表述过于绝对，为错误。' WHERE id = '94f05dbb-61c0-4401-a32e-beee6d686b47';
UPDATE public.questions SET analysis = '根据《食品生产许可分类目录》及大米生产许可审查细则，实施食品生产许可证管理的大米产品包括大米（B）、特殊大米（A）、糙米类产品（C）及其他（D）大米制品。' WHERE id = '94f20151-2065-45a6-ab70-365acac22fca';
UPDATE public.questions SET analysis = '《食品安全国家标准 预包装食品营养标签通则》（GB 28050）规定，营养标签强制标示内容包括能量以及蛋白质、脂肪、碳水化合物和钠4种核心营养素的含量值，及其占营养素参考值（NRV）的百分比。该表述符合标准要求。' WHERE id = '950dddbd-8e96-4150-8376-47c41f832281';
UPDATE public.questions SET analysis = '《食品安全国家标准 方便面》（GB 17400）规定，油炸面饼水分限量≤8.0g/100g，非油炸面饼水分限量≤14.0g/100g或≤12.0g/100g（视产品类型），两者限量值不同。该表述错误。' WHERE id = '9512023b-bc03-41a5-a4a2-25f71b47ae43';
UPDATE public.questions SET analysis = '《食品生产通用卫生规范》（GB 14881）要求食品生产企业应保持食品包装、贮存容器的密闭良好，防止在加工、贮存、销售等环节的虫害侵入。该表述符合规范要求。' WHERE id = '951f2ec8-0067-416a-b51c-db25dc891190';
UPDATE public.questions SET analysis = '《食用农产品市场销售质量安全监督管理办法》规定，县级以上食品药品监督管理部门应当按照当地人民政府制定的本行政区域食品安全年度监督管理计划，开展食用农产品市场销售质量安全监督管理工作。县级（D正确）为最基层监管部门。' WHERE id = '952aaee5-59ce-47d5-ae89-261b7ae1b6fc';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，日常监督检查指市级、县级市场监督管理部门按照年度食品生产经营监督检查计划，对本行政区域内食品生产经营者开展的常规性检查。该表述符合规定。' WHERE id = '95443e7d-911f-4bf7-a50b-c223ee0b906f';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》第八条规定，申请人应当设立研发机构，配备专职的产品研发人员（B正确）、食品安全管理人员和食品安全专业技术人员。' WHERE id = '954f43d1-2e88-4fe3-a6f5-2583cf3bb50b';
UPDATE public.questions SET analysis = '《乳品质量安全监督管理条例》规定，乳制品生产企业禁止向未取得生鲜乳收购许可证的单位和个人购进生鲜乳（A），禁止购进兽药等化学物质残留超标（B）、含有重金属等有毒有害物质（C）以及含有致病性寄生虫和微生物等不符合乳品质量安全国家标准的生鲜乳（D）。' WHERE id = '95538e57-fcdd-4e48-a326-11cc41ad3d36';
UPDATE public.questions SET analysis = '《食品生产通用卫生规范》（GB 14881）规定，手部清洗后的消毒方法包括：消毒液浸泡（B）和涂擦消毒剂（C）。干手机烘干（A）和热水冲洗（D）属于清洁措施而非消毒方法。' WHERE id = '956969b2-7d79-4d58-981a-ecef2d3ffbd8';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条及《食品经营许可管理办法》规定，餐饮服务提供者应具有与经营品种、数量相适应的设备设施（A），有相应的消毒、更衣、通风、防尘防蝇等设施（B），采购的食品相关产品应符合食品安全国家标准（C），直接接触食品的设备材质应无毒无味易于清洁（D）。' WHERE id = '9580c306-573f-4589-bd1c-f09f308b7269';
UPDATE public.questions SET analysis = '非传统食品安全风险是指人为因素导致的风险，包括人为故意污染（A）和人为蓄意破坏（B）。生产过程中人流、物流带入的污染（C、D）属于传统食品安全风险。' WHERE id = '9585c7e0-54a6-4280-ad31-1bb61c2f8e82';
UPDATE public.questions SET analysis = '冷冻饮品生产过程执行产品配方管控时，应确定配方并进行食品添加剂合规性审查（A），确定可使用的食品添加剂品种和添加量（B）。C选项公示全部配方内容和D选项操作人员自行修改配方均不符合管理要求。' WHERE id = '959625e3-9dc6-4c07-9ded-5e9a0151358a';
UPDATE public.questions SET analysis = '调味品生产过程中，使用大肠菌群超标的酱油、食醋等原料（A正确）属于生物性危害。B选项属于化学性危害（超范围使用添加剂），C选项属于物理性危害（异物），D选项属于掺假造假行为。' WHERE id = '959d1518-d95e-446a-a903-0239736192d5';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，市场监督管理部门每两年（B正确）对本行政区域内所有食品生产经营者至少进行一次覆盖全部检查要点的监督检查。' WHERE id = '959fceab-3976-47d9-88d9-90bdc7bdea7f';
UPDATE public.questions SET analysis = '《食品安全国家标准 餐饮服务通用卫生规范》（GB 31654）规定，中央厨房和集体用餐配送单位应自行或委托有资质的第三方检验机构，对食品和加工环境（C正确）等进行检验。' WHERE id = '95b424c5-bbbc-402a-88f5-17ed9eba30e1';
UPDATE public.questions SET analysis = '《食品安全国家标准 膨化食品》（GB 17401）规定，膨化食品的水分含量因产品类型不同而异，并非统一要求≤8g/100g。含油型和非含油型水分限量不同，该表述过于笼统，为错误。' WHERE id = '95b881fb-8dc3-497d-afd7-c40ccefeefa4';
UPDATE public.questions SET analysis = '《电子商务法》第十二条规定，电子商务经营者从事经营活动，依法需要取得相关行政许可的，应当依法取得行政许可。该表述符合法律规定。' WHERE id = '95bfa0d8-ebfc-4136-84ed-f1657eec79d2';
UPDATE public.questions SET analysis = '单核细胞增生李斯特菌是一种嗜冷致病菌，在4℃以下的环境中仍可生长繁殖，是冷藏即食食品的主要安全风险之一。该表述正确。' WHERE id = '95c8eab4-3adf-4b8e-910e-f3efab8da652';
UPDATE public.questions SET analysis = '《食品经营许可和备案管理办法》规定，仅销售预包装食品办理备案后，增加散装食品销售、餐饮服务、食品经营管理等应取得许可的经营项目的，应当依法取得食品经营许可。该表述符合规定。' WHERE id = '95de0725-101b-4a98-8760-1b00ab390410';
UPDATE public.questions SET analysis = '《食品召回管理办法》规定，食品生产经营者发现其生产经营的食品属于不安全食品的，应当立即停止生产经营（A），采取通知或公告方式告知相关方停止生产经营、消费者停止食用（B），并采取必要措施防控食品安全风险（C）。D选项主动停产停业表述不准确。' WHERE id = '95e93e11-8f59-4493-ac72-e50b46533cc9';
UPDATE public.questions SET analysis = '《食品经营许可和备案管理办法》规定，半成品制售（C正确）仅限于中央厨房申请。生食类食品制售、自制饮品销售、冷食类食品制售普通餐饮服务提供者也可申请。' WHERE id = '95eef974-2ec3-4b4d-a9d0-32149ef1954a';
UPDATE public.questions SET analysis = '《食品安全法实施条例》及市场监管总局规定，食品补充检验方法适用于可能掺杂掺假的物质（C正确）的检测。农药、兽药、食品添加剂已有相应国家标准检测方法。' WHERE id = '95f0ddce-f09b-4159-b5dd-e000811256a4';
UPDATE public.questions SET analysis = '《食品安全国家标准 餐饮服务通用卫生规范》（GB 31654）规定，食品处理区内动物性食品原料（A）、植物性食品原料（B）、水产品原料（C）应分别设置清洗水池，防止交叉污染。' WHERE id = '95f54089-d34f-45ae-b69c-d7bac0aab56b';
UPDATE public.questions SET analysis = '《食品安全法》第八十四条规定，食品生产企业可以委托检验，但企业应具备相应的检验能力（包括自检或委托检验的管理能力）。《食品生产通用卫生规范》要求企业应具备检验能力，并非完全不需要检测能力。该表述错误。' WHERE id = '95ffda8b-56e5-4bc2-a0ab-5d4d719cac72';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，患有国务院卫生行政部门规定的有碍食品安全疾病（B正确）的人员，不得从事接触直接入口食品的工作。''有碍食品安全疾病''是法定用语，包含痢疾、伤寒、病毒性肝炎等。' WHERE id = '96035a1b-0d6e-4b46-be90-18412c236426';
UPDATE public.questions SET analysis = '《食品安全法》第四十二条规定，食品生产经营者应当建立食品安全追溯体系，保证食品可追溯。国家鼓励食品生产经营者采用信息化手段实现食品可追溯。该表述符合法律规定。' WHERE id = '96039839-fa00-4c8d-801b-aa0d05a4807f';
UPDATE public.questions SET analysis = '《食品生产通用卫生规范》（GB 14881）及速冻食品生产许可审查细则要求，速冻食品生产应加强过程控制，避免冻结过程控制不当导致产品变色、变味及营养成分损失。该表述符合规范要求。' WHERE id = '96066924-0a81-4354-9381-59de9f0cf5e2';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十条规定，集中交易市场的开办者（A）、柜台出租者（C）、展销会举办者（D）允许未依法取得许可的食品经营者进入市场销售食品，或者未履行检查、报告等义务的，由监管部门责令改正，没收违法所得，并处五万元以上二十万元以下罚款。房屋出租者（B）不在此列。' WHERE id = '960710e8-e19c-4c41-b1bd-c584bab868b2';
UPDATE public.questions SET analysis = '《行政诉讼法》第十二条规定，人民法院受理公民、法人或者其他组织对行政处罚不服（A）、行政许可决定不服（B）、行政强制措施不服（C）以及法律、法规规定可以提起诉讼的其他行政案件（D）。' WHERE id = '960a1aa4-de3c-4da0-841a-7e28e3895a08';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，食品生产经营企业应当收集食品安全风险（A正确）信息，建立基于食品安全风险防控的动态管理机制，制定食品安全风险管控清单，建立健全日管控、周排查、月调度工作制度。' WHERE id = '960b5fa0-9665-4b99-b588-5b3ddeb8c37e';
UPDATE public.questions SET analysis = '《食品安全法》第五十四条及《食品生产通用卫生规范》（GB 14881）规定，食品原料仓库出货顺序应遵循先进先出（A正确）原则，必要时应根据不同原料特性确定出货顺序。' WHERE id = '96129a3b-0662-4602-8bc6-fcd041727fe4';
UPDATE public.questions SET analysis = '《食品安全法》及食品追溯相关规定中，''一品一码''是指同一品种批次的食品和食用农产品按照规定的追溯编码规则赋予唯一的识别追溯码。该表述符合追溯体系建设要求。' WHERE id = '9627803b-25fe-4946-84d3-6b327502bec5';
UPDATE public.questions SET analysis = '生食类食品不仅包括生食植物性水产品（海产品），还包括生食动物性水产品和其他生食类食品。该表述范围过窄，为错误。' WHERE id = '9635ce85-bc66-419b-bae8-0159a4a2d7cb';
