UPDATE public.questions SET analysis = '《食品安全国家标准 腌腊肉制品》（GB 2730）规定，腌腊禽制品过氧化值（以脂肪计）限量为≤1.5g/100g（C正确）。腌腊肉制品≤0.5g/100g，其他腌腊制品限量不同。' WHERE id = '96460a42-e929-47e5-b795-c1c6a58c3941';
