UPDATE public.questions SET analysis = '干制水产品是指以鲜、冻动物性水产品或海水藻类为原料，经相应工艺加工制成的产品。干贝（D正确）属于干制水产品。鱿鱼丝属于熟制水产品，鱼松属于鱼糜制品，海苔属于藻类制品。' WHERE id = '96d26409-0528-4655-b7df-24f55453048a';
UPDATE public.questions SET analysis = '《关于完善跨境电子商务零售进口监管有关工作的通知》规定，对于已购买的跨境电商零售进口商品，不得再次销售。该表述符合跨境电商管理规定。' WHERE id = '96d4858b-d9f4-4fbb-96b5-fe8ee4073977';
