UPDATE public.questions SET analysis = '《食品生产通用卫生规范》（GB 14881）规定，对生物性危害的防控措施主要包括：对微生物的控制（A），对寄生虫的控制（B），对虫害的控制（C），对真菌及真菌毒素的控制（D）。' WHERE id = '96faca49-6afe-4e63-bf92-a9802e6340a5';
