UPDATE public.questions SET analysis = '《食品安全国家标准 餐饮服务通用卫生规范》（GB 31654）规定，热食保温运输时保温温度应保持在60℃以上（B正确）。70℃为再加热中心温度要求。' WHERE id = '973743fc-8f4c-4389-8622-710e6491892d';
