UPDATE public.questions SET analysis = '可可粉灰分检测需要电热板（A）用于碳化样品，马弗炉（B）用于高温灼烧，干燥器（C）用于冷却称量。恒温仪（D）非灰分检测必需设备。' WHERE id = '97d57136-655f-4149-a2cb-32a94c67f132';
