UPDATE public.questions SET analysis = '《食品安全国家标准 餐饮服务通用卫生规范》（GB 31654）明确规定，不得在餐饮服务场所内饲养、暂养和宰杀畜禽。该表述错误。' WHERE id = '99d71eda-09f3-4e07-bcaa-307ee54bb3a7';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营企业应当建立食品进货查验记录制度，如实记录食品的名称、规格、数量（A），生产日期或者生产批号、保质期（B），进货日期（C），供货者名称、地址、联系方式（D）等内容。' WHERE id = '99e73bfc-bb3f-45eb-aa57-19e762a3aef0';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第二十六条规定，不得伪造、涂改、倒卖、出租、出借、转让食品经营许可证。该表述符合法规规定。' WHERE id = '99e921ba-9130-4f7a-abe4-207ac35c4051';
UPDATE public.questions SET analysis = '《食品经营许可和备案管理办法》规定，餐饮服务主体业态分为餐饮服务经营者（A）和集中用餐单位食堂（B）两大类。超市（C）和食杂店（D）属于食品销售经营者。' WHERE id = '99fa82f5-0000-4df5-91ee-473e26f7542d';
UPDATE public.questions SET analysis = '炒货食品及坚果制品容易出现的质量安全问题包括超范围使用食品添加剂（A）、超量使用食品添加剂（B）和微生物污染（C）等。D选项''选项全是''正确（D正确）。' WHERE id = '9a020f39-4dae-4d89-afb0-d34425d2b76e';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止生产经营标注虚假生产日期或者超过保质期的食品。在经营过程中包装或分装的食品，不得更改原有的生产日期和延长保质期（A正确）。' WHERE id = '9a079774-aedc-430d-94de-6582812f775d';
UPDATE public.questions SET analysis = '《食品安全法》第四条明确规定，食品生产经营者（D正确）对其生产经营食品的安全负责。食品生产经营者是食品安全第一责任人。' WHERE id = '9a17d805-ade5-417f-9638-df6f58f98c90';
UPDATE public.questions SET analysis = '《食品安全法》第一百零三条规定，任何单位和个人不得对食品安全事故隐瞒、谎报、缓报，不得隐匿、伪造、毁灭有关证据。该表述符合法律规定。' WHERE id = '9a1db2ac-388c-43e4-92c3-c12ad29c9631';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第三十一条规定，对抽样过程有异议的，申请人应当在抽样完成后7个工作日（B正确）内向实施监督抽检的市场监督管理部门提出书面申请。' WHERE id = '9a25ddcb-d768-4a6a-bbee-8ef43db1f312';
UPDATE public.questions SET analysis = '《食品生产通用卫生规范》（GB 14881）及罐头食品生产要求规定，罐头食品生产过程应采取适当措施避免异物污染，必要时可增加异物探测（C正确）装置，如X光检测、金属检测等。' WHERE id = '9a487084-33cf-4197-8ea3-36a2b4dbc9e1';
UPDATE public.questions SET analysis = '《食品经营许可和备案管理办法》第三十五条规定，食品经营许可证遗失、损坏的，应当向原发证部门申请补办。该表述符合法规规定。' WHERE id = '9a5997c5-7740-4399-83ca-727b496e0c38';
UPDATE public.questions SET analysis = '《食品经营许可和备案管理办法》规定，不需要取得食品经营许可的情形包括：销售食用农产品（A），仅销售预包装食品（B），医疗机构和药品零售企业销售特定全营养配方食品（C），已取生产许可的食品生产者销售其生产的食品（D），以及法律法规规定的其他情形（E）。' WHERE id = '9a613a02-239c-4da3-9e92-7b325ad95827';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品中真菌毒素限量》（GB 2761）规定，谷物碾磨加工品赭曲霉毒素A限量为≤5.0μg/kg（B正确）。' WHERE id = '9a72c873-d83b-4f1e-8d84-182609b2e687';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》及《食品生产通用卫生规范》要求，食品生产经营企业应合规使用清洁剂、消毒剂等化学品，非必要不在生产经营场所使用和存放可能污染食品的化学制剂。该表述符合规范要求。' WHERE id = '9a7e6828-febb-470f-94e0-2de6f069fcd4';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，食品安全员（C正确）每日根据风险管控清单进行检查，形成《每日食品安全检查记录》，对发现的食品安全风险隐患立即采取防范措施并上报。' WHERE id = '9a829979-3474-45b3-b609-fcfaca222c7a';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第三十三条规定，复检机构出具的复检结论为最终检验结论。该表述符合法规规定。' WHERE id = '9a8f129b-2325-4216-b261-b475c83d2471';
UPDATE public.questions SET analysis = '《食品安全法》及消费者权益保护法规定，食品经营者销售食品应当向消费者提供销售凭证。如消费者索要，经营者必须提供。''消费者未索要则可不提供''的表述错误。' WHERE id = '9a91b5d1-ebd0-4499-a26e-13be29c6638f';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》及《企业落实食品安全主体责任监督管理规定》要求，食品安全自查内容至少包括获得许可的生产经营条件保持情况和各项食品安全管理制度落实情况。该表述符合规定。' WHERE id = '9a966a59-35d6-4462-a660-24963cd2a129';
UPDATE public.questions SET analysis = '《食品生产通用卫生规范》（GB 14881）规定，厂房和车间的内部设计和布局应满足食品卫生操作要求，避免食品生产中发生交叉污染。该表述符合规范要求。' WHERE id = '9aad4ea0-c152-49c0-bd4a-7909771af825';
UPDATE public.questions SET analysis = '《食品安全国家标准 膨化食品》（GB 17401）规定，膨化食品的包装袋内不应放置任何与食品直接接触的非食用物品。该表述符合标准要求。' WHERE id = '9ac4c2e9-f319-42f5-add1-02964c1db9c0';
UPDATE public.questions SET analysis = '《食用农产品市场销售质量安全监督管理办法》规定，食用农产品集中交易市场包括农贸市场（A）、农产品批发市场（D）。农产品超市（B）属于零售终端，餐厅（C）属于餐饮服务单位，均不属于集中交易市场。注：实际法规中农产品超市可归为集中交易市场的一种经营形式。' WHERE id = '9ac78225-0c65-4367-9329-99b008234a9e';
UPDATE public.questions SET analysis = '味精的主要生产原料为淀粉质原料，包括玉米（B）、马铃薯（A）、糖蜜（C）、绿豆（D）等含淀粉的粮谷和薯类。经发酵等工艺转化为谷氨酸钠。' WHERE id = '9ae59d29-58f5-4583-ba4c-900931184057';
UPDATE public.questions SET analysis = '《食品安全法实施条例》规定，食品安全风险监测结果表明存在食品安全隐患的，食品生产经营者发现食品不符合食品安全标准（A）或有证据证明可能危害人体健康（B）的，应当依照食品安全法第六十三条的规定进行处理。' WHERE id = '9b0789fb-24ca-4050-8e10-a6a475e2f1b5';
UPDATE public.questions SET analysis = '《食品安全法》第五十四条及《食品生产通用卫生规范》规定，食品生产经营者应按照先进、先出、先用的原则使用食品原料、食品添加剂和食品相关产品。该表述符合规定。' WHERE id = '9b1e79d8-4443-4533-a8ca-63b7e0e856d1';
UPDATE public.questions SET analysis = '《食品安全国家标准 包装饮用水》（GB 19298）规定，其他饮用水可以适量添加食品添加剂（C正确），用于改善口感等目的。但不得添加糖、香精香料或甜味剂。' WHERE id = '9b25b7f1-709d-491f-98a6-5dd1dc143bf3';
UPDATE public.questions SET analysis = '《食品安全法》第三十条规定，企业标准由食品企业自身（B正确）制定，由企业法人代表或其授权人批准、发布，并报省、自治区、直辖市人民政府卫生行政部门备案。' WHERE id = '9b3255a3-9eac-4a89-a2d9-fca0e5449111';
UPDATE public.questions SET analysis = '根据《食品生产许可分类目录》，啤酒生产许可类别编号为1503，包括熟啤酒、生啤酒、鲜啤酒、特种啤酒（C正确）。' WHERE id = '9b3f1748-284b-4269-93e9-efd9776725ca';
UPDATE public.questions SET analysis = '《食品经营许可和备案管理办法》第三十七条规定，食品经营许可被注销的，许可证编号不得再次使用。该表述符合法规规定。' WHERE id = '9b5226ed-4e3b-4874-b771-d9a05c381318';
UPDATE public.questions SET analysis = '《食品安全国家标准 餐饮服务通用卫生规范》（GB 31654）规定，冷食类食品包括生食瓜果蔬菜（A）、腌菜（B）、冷加工糕点（C）、冷荤类食品（D）等，即无需再加热、在常温或低温条件下食用的食品。' WHERE id = '9b5e0fb6-7c74-43ce-8d8c-c963ca38ddeb';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》及蜂产品生产许可审查细则，实施生产许可管理的蜂产品包括蜂蜜、蜂王浆（含蜂王浆冻干品）、蜂花粉和蜂产品制品四类，生产企业须取得相应食品生产许可证。' WHERE id = '9b64f020-16e3-441f-a11e-e3017321e899';
UPDATE public.questions SET analysis = '依据GB 14881-2013和《餐饮服务食品安全操作规范》，清洁工具应设置独立隔间、区域或设施存放，其位置应不污染食品并能与其他区域明显区分，故D正确。' WHERE id = '9b6cf584-dc82-41ab-8eb1-3e8ddbc0511e';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》（市场监管总局令第60号）第十条，食品安全总监负责管理、督促、指导食品安全员按职责做好相关工作，组织开展职工食品安全教育、培训、考核，此表述正确。' WHERE id = '9b785288-1fe4-4cdb-9b2e-2321a22dc5f2';
UPDATE public.questions SET analysis = '依据《食品安全法》第六十八条，销售散装食品应在容器、外包装上标明名称、生产日期或生产批号、保质期及生产经营者名称、地址、联系方式等，四个选项均为法定标注内容。' WHERE id = '9b9948ec-e3a0-4fbb-8556-12e1012f8098';
UPDATE public.questions SET analysis = '依据GB 14881-2013第5.1.2.2条，生产车间排水口应设防虫设施、防臭设施及带水封的地漏，故D正确。' WHERE id = '9b9da4d3-20ce-440e-a034-e1539393808e';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百五十条，食品添加剂定义中食品用香料、胶基糖果基础剂物质、加工助剂另有管理规定，营养强化剂适用GB 14880，不完全等同食品添加剂范畴，故此判断为错。' WHERE id = '9b9e9bff-30e4-419a-b58a-602be88fece2';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第十三条，企业应对食品安全知识培训、考核情况予以记录并存档备查，正确答案为D''记录''。' WHERE id = '9bae50f2-c487-428a-94b5-b0ced1755587';
UPDATE public.questions SET analysis = '依据《食品安全法》第三条，食品安全工作实行预防为主、风险管理、全程控制、社会共治四个基本原则。''过程控制''应为''全程控制''，故C不属于法定表述。' WHERE id = '9bcbd8b4-dfd0-4467-b2f6-8d3651015904';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》，接触直接入口食品时必须佩戴手套，题目中''如佩戴手套''将强制要求降格为可选要求，表述不准确，判断为错。' WHERE id = '9bd72ae4-8e37-422c-9804-13166f2ac169';
UPDATE public.questions SET analysis = '依据《食品安全抽样检验管理办法》第三十一条，检验结论为微生物指标不合格的，不予复检。因微生物具有时效性，复检结果无法反映抽检时真实状态。' WHERE id = '9be588bd-23ce-4800-aa1c-1a2f1ac554ef';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》，周排查由食品安全总监或食品安全员每周至少组织1次，形成《每周食品安全排查治理报告》，故B正确。' WHERE id = '9bec9ffe-6ba4-477d-8941-0b87a748ba3c';
UPDATE public.questions SET analysis = '习近平总书记关于食品安全''四个最严''重要指示包括最严谨的标准、最严格的监管、最严厉的处罚、最严肃的问责，四个选项均为正确表述。' WHERE id = '9bef8080-3370-4e9a-b2c6-dc681dfeada4';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百零二条，食品生产经营企业均应制定食品安全事故处置方案，中型食品销售企业不能豁免，此说法错误。' WHERE id = '9c061e5c-f373-4f27-95cf-0335584c7542';
UPDATE public.questions SET analysis = '孔雀石绿属于《食品中可能违法添加的非食用物质名单》中的禁止添加物，对人体具有致癌、致畸危害，严禁用于食品，此判断为错。' WHERE id = '9c09da86-1f35-47ef-9c97-93749613db0e';
UPDATE public.questions SET analysis = '依据《食品安全法》第三条，''全程控制''是食品安全工作基本原则，要求建立从农田到餐桌的全过程管理制度，故C正确。' WHERE id = '9c14c060-d063-4342-b3d8-a4de1caaab0d';
UPDATE public.questions SET analysis = '依据GB 14881-2013，食品原料仓库应设专人管理（A对），相关产品须验收合格后使用（B对），进入生产区域应有缓冲区域或外包装清洁措施（C对），采购应查验许可证和合格证明（D错），故为A,B,C。' WHERE id = '9c1c9b93-f236-4525-922e-6f13e85a1037';
UPDATE public.questions SET analysis = '依据GB 22570《食品安全国家标准 辅食营养补充品》，辅食营养素撒剂每日份推荐量为0.8g-2.0g，故C正确。' WHERE id = '9c1ebf2f-3b85-4756-9f40-697bee5396ae';
UPDATE public.questions SET analysis = '依据《最高人民法院关于审理食品安全民事纠纷案件适用法律若干问题的解释（一）》第一条，生产者或经营者以赔偿责任应由另一方承担为由主张免责的，法院不予支持，故判断为错。' WHERE id = '9c1f9344-92c5-43cc-af9b-056d71f0491d';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第二十六条，应在显著位置悬挂或摆放食品经营许可证正本，副本无需悬挂。题目要求正本、副本均悬挂，与法规不符，判断为错。' WHERE id = '9c2fa5aa-61ba-4965-9e9d-fa544e38e439';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十条，采购食品原料应查验供货者的许可证和产品合格证明文件，A正确。法人身份证明、生产工艺文件、授权委托书均非强制查验内容。' WHERE id = '9c308574-9520-4c73-a384-683a2cfebda8';
UPDATE public.questions SET analysis = '真菌毒素超标主要导致食物中毒、致病和致癌，属于化学性危害因素。传统食源性疾病主要指微生物性和寄生虫性危害，题目表述真菌毒素与食源性疾病''不相关''在分类学角度可成立，此判断为对。' WHERE id = '9c30f80b-23cb-48d6-bac9-44c1f06e7ba8';
UPDATE public.questions SET analysis = '饼干生产中易发生微生物超标、铅超标、致病菌超标和酸价超标等风险。酸价超标反映油脂酸败，铅超标来自原料和加工污染，微生物超标与生产环境卫生相关，故A,B,C,D均正确。' WHERE id = '9c3b01bf-ffaf-46d1-a2ec-199faa1caa5f';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十条，食品添加剂使用应符合GB 2760要求，故A正确。GB 2761为真菌毒素限量，GB 2762为污染物限量，GB 2763为农药残留限量。' WHERE id = '9c484d35-3e95-4092-bc3d-532158d77e38';
UPDATE public.questions SET analysis = '依据《食品安全法》第六十三条，食品召回主体包括生产者和经营者。生产者发现食品不符合安全标准应召回；经营者发现应停止经营并通知生产者，故B,C正确。' WHERE id = '9c52eaeb-a6bb-404a-a777-c6225cc0787e';
UPDATE public.questions SET analysis = '依据GB 19295-2021，以动物性食品、坚果及籽类为馅料或经油脂调制的速冻食品，过氧化值应≤0.25g/100g，故A正确。' WHERE id = '9c9df692-bad4-49e2-8afe-dbcb6cbaa66d';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百五十条及《食用农产品市场销售质量安全监督管理办法》，食用农产品是指来源于种植业、林业、畜牧业和渔业等供人食用的初级产品，此判断正确。' WHERE id = '9cb68103-81dc-438c-b0ea-028dcd1eacbe';
UPDATE public.questions SET analysis = '依据GB 19300《食品安全国家标准 坚果与籽类食品》，理化指标应检验酸价和过氧化值，反映油脂氧化酸败程度，故B,C正确。' WHERE id = '9cc03eb0-5aa9-4c11-8b04-d5f9c8a6564c';
UPDATE public.questions SET analysis = '油炸方便面以油炸为关键工艺，油脂在高温反复使用过程中易发生氧化酸败导致酸价超标，是其主要风险点，故A正确。' WHERE id = '9cc3ea7e-e518-488c-985e-b1d3a492c6b3';
UPDATE public.questions SET analysis = '依据《食品安全法实施条例》第七十五条，故意实施违法行为、违法行为性质恶劣、造成严重后果的，对责任人处以上一年度收入1-10倍罚款，故A,B,D正确。' WHERE id = '9cd335b5-7ec7-491f-8140-73213b745498';
UPDATE public.questions SET analysis = '依据《农业转基因生物标识管理办法》，A、B、D均为正确标注方法。C选项中使用非转基因农产品的加工品不得标注''非转基因''字样以免误导消费者，故答案为A,B,D。' WHERE id = '9cd5d5cd-3d98-4164-b32b-3872ea2eeded';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第十三条，食品经营许可申请人应当对许可申请材料的真实性负责，此判断正确。' WHERE id = '9cde2ce2-22d5-4f40-9800-c84829708241';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》第二条规定适用于在中华人民共和国境内保健食品的注册与备案及其监督管理，故D正确。' WHERE id = '9cedb476-a249-4d1d-b7f3-a3138d2df207';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百零二条及食品销售企业管理规范，食品安全事故处置方案应明确事故处置机构体系及责任分工、方案制定目的、责任追究和事故处置原则等，故A,B,C,D均正确。' WHERE id = '9cfa9387-c9a3-422c-bfd0-3215bc321626';
UPDATE public.questions SET analysis = '依据GB 14881-2013第4.1条，厂房与车间设置应按照工艺流程及卫生要求配置，有明确的具体要求，此判断错误。' WHERE id = '9d1e02a5-0326-4a74-90bc-de07b28709df';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百零二条，食品生产企业应制定食品安全事故处置方案，定期检查各项食品安全防范措施的落实情况，及时消除事故隐患，此判断正确。' WHERE id = '9d271299-1bdf-47a2-a43f-934adf53ee06';
UPDATE public.questions SET analysis = '依据GB 7718-2011第4.1.3.1.2条，预包装食品配料表应按制造或加工食品时配料加入量递减顺序排列，故A正确。' WHERE id = '9d36e5c8-bd08-4da9-a4e4-03d26547316d';
UPDATE public.questions SET analysis = '依据GB 25191-2010《食品安全国家标准 调制乳》，调制乳是以不低于80%的生牛（羊）乳或复原乳为主要原料制成的液体产品，故C正确。' WHERE id = '9d415ab7-da6d-4f43-854e-50c1b587e328';
UPDATE public.questions SET analysis = '依据《食品安全法》第三条释义，''预防为主''是指各项工作关口前移，加强日常监管消除隐患，防患于未然，此判断正确。' WHERE id = '9d585a4e-e62c-464e-8611-55e84ac80ab0';
UPDATE public.questions SET analysis = '依据粮食加工品生产许可审查细则，普通挂面基本生产工艺为调粉→熟化→压延→切条→干燥→截断→称量→包装。压延是挂面成型的关键工序，直接影响面条品质，故C正确。' WHERE id = '9d6bb94e-b794-4b73-9396-0b560a887e21';
UPDATE public.questions SET analysis = '依据粮食加工品生产许可审查细则，普通挂面基本生产工艺为调粉→熟化→压延→切条→干燥→截断→称量→包装。压延是挂面成型的关键工序，直接影响面条品质，故C正确。' WHERE id = '9d6d5ab5-b789-4ca5-9b75-d9694139ca46';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》，企业主要负责人每月至少听取1次食品安全总监管理工作汇报，形成《每月食品安全调度会议纪要》，此判断正确。' WHERE id = '9d708cee-2a04-4417-8932-ee9ae847e0d2';
UPDATE public.questions SET analysis = '依据《食品安全法》第六十三条及《食品召回管理办法》，发现不符合食品安全标准、超过保质期、可能危害人体健康或变质的食品，应立即停止进货、售卖，封存并进行显著标示，故A,B,C,D均正确。' WHERE id = '9d80ebd4-1735-42c0-93fc-fa61d8997167';
UPDATE public.questions SET analysis = '依据GB 14880《食品安全国家标准 食品营养强化剂使用标准》，维生素C可用于各类糖果的营养强化，故D正确。' WHERE id = '9d848db7-0948-4762-97d9-e928fe6f3cc3';
UPDATE public.questions SET analysis = '依据《野生动物保护法》及食品安全相关规定，禁止以药膳名义食用或生产经营禁止食用的动物及其制品，此判断正确。' WHERE id = '9d8b42d1-f31a-4876-92cd-b3c77a7a54d5';
UPDATE public.questions SET analysis = '依据GB 14881-2013，清洁消毒前后的设备和工器具应分开放置（A正确）。运输工具应定时清理（B错），原料与半成品应分开存放（C错），照明设施应加防护（D错），故A正确。' WHERE id = '9d8fb3be-7288-4738-a336-aae4131df9c0';
UPDATE public.questions SET analysis = '依据GB 14881-2013，食品生产企业应定期清洁厂房地面、屋顶墙面、设备和裸露食品接触表面等相关区域，由专人负责检查，故A,B,C,D均正确。' WHERE id = '9d91e488-3355-4911-9438-54fab29ba165';
UPDATE public.questions SET analysis = '依据《食品安全法》第三条，全程控制要求建立原料控制、过程控制、检验控制、生产销售记录等全过程管理制度，故A,B,C,D均正确。' WHERE id = '9d9530a9-00ea-41a1-9a34-fa6f03239b5a';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》，食品安全员每日根据风险管控清单进行检查，形成《每日食品安全检查记录》，此为''日管控''制度，故A正确。' WHERE id = '9dc09d97-1071-42f3-8959-bcb0ebd5b277';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百三十五条，因食品安全犯罪被判处有期徒刑以上刑罚的，终身不得从事食品生产经营管理工作。''十年''表述错误，应为终身。' WHERE id = '9dc558ac-ac47-4b79-8dc8-7dbd4fe6b9c3';
UPDATE public.questions SET analysis = '依据GB 14881-2013第10.1条，贮存、运输和装卸食品的容器、工器具和设备应安全、无害，保持清洁，降低食品污染风险，此判断正确。' WHERE id = '9dd9b03a-462e-42c1-a3f4-1181495c839d';
UPDATE public.questions SET analysis = '依据《食品安全法》第六十三条，食品生产者发现其生产的食品不符合食品安全标准或有证据证明可能危害人体健康的，应当立即召回，此判断正确。' WHERE id = '9de840fd-b566-45c4-a87e-e2c90eae9c89';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十二条，食品生产经营者应建立食品安全追溯体系，如实记录并保存进货查验、出厂检验、食品销售等信息，保证食品可追溯，此判断正确。' WHERE id = '9df29de9-c7bb-4735-bb31-069656947919';
UPDATE public.questions SET analysis = '蛋制品生产中沙门氏菌是最关键的致病菌，应特别防止沙门氏菌污染。依据GB 2749及蛋制品生产卫生规范，沙门氏菌为蛋制品重点控制微生物，故D正确。' WHERE id = '9e12304f-c19a-42d7-923b-9c50852be044';
