UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》，婴幼儿配方乳粉产品配方注册应遵循科学、严格、公平、公正原则，故A,B,C,D均正确。' WHERE id = '9e3dda2d-2bd5-42c1-a923-64f89e164efb';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百三十五条，因食品安全犯罪被判处有期徒刑以上刑罚的，终身不得从事食品生产管理工作，故D正确。' WHERE id = '9e4e305e-d77d-4b60-870c-38b6e91ac7d2';
