UPDATE public.questions SET analysis = '依据《中华人民共和国反食品浪费法》第七条，餐饮服务经营者应主动对消费者进行防止食品浪费提示和提醒，包括张贴反食品浪费标识、引导按需点餐等措施，故A,C正确。' WHERE id = '9f682614-34fb-47e6-81bb-17aab8592886';
UPDATE public.questions SET analysis = '依据《中华人民共和国反食品浪费法》第七条，餐饮服务经营者应主动对消费者进行防止食品浪费提示和提醒，包括张贴反食品浪费标识、引导按需点餐等措施，故A,C正确。' WHERE id = '9f9fb8e3-77d2-4cd7-b421-7975fdd7fc7d';
UPDATE public.questions SET analysis = '依据GB 2762-2022《食品安全国家标准 食品中污染物限量》，炒货食品及坚果制品的铅限量为≤0.2mg/kg。铅是重点控制的污染物，主要来自原料种植环境的土壤污染，故D正确。' WHERE id = '9fa1cccd-ea4e-4571-bd4d-b47e3b09d10b';
UPDATE public.questions SET analysis = '依据GB 2762-2022《食品安全国家标准 食品中污染物限量》，炒货食品及坚果制品的铅限量为≤0.2mg/kg。铅是重点控制的污染物，主要来自原料种植环境的土壤污染，故D正确。' WHERE id = '9fbafcd4-df2a-4594-828e-2f5cbf72bad2';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第十一条，食品经营场所和贮存场所不得设在易受污染区域，距离粪坑、污水池、暴露垃圾场（站）、旱厕等污染源应在25米以上，故A,B,C,D均正确。' WHERE id = '9fcb5955-4b59-4c65-8c84-cb092ecba47a';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》第五十三条，食品生产企业未按规定悬挂或摆放食品生产许可证的，由县级以上监管部门责令改正，拒不改正的给予警告，此判断正确。' WHERE id = '9fce0709-9b7a-4d73-93b4-4e6daf9e5b43';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十七条，使用新的食品原料、食品添加剂新品种、食品相关产品新品种应向国务院卫生行政部门提交安全性评估材料，故A正确。' WHERE id = '9fd09285-b7c4-4a2e-9eb0-70cdd8530df8';
UPDATE public.questions SET analysis = '依据《食品安全法》第二条，食用农产品是指在农业活动中获得的供人食用的植物、动物、微生物及其产品，故B正确。' WHERE id = '9fd9fa72-c5e1-4251-8fe3-d0974ff794cf';
UPDATE public.questions SET analysis = '依据GB 14881-2013第7.2.2条，食品原料仓库应设专人管理，定期检查质量和卫生情况，及时清理变质或超过保质期的原料，此判断正确。' WHERE id = '9fda6b1c-882a-4a71-9342-ae5dff9c1895';
UPDATE public.questions SET analysis = '依据《农业农村部职能配置规定》，农业农村部负责农产品质量安全监督管理，组织开展监测、追溯、风险评估，参与制定国家标准，指导农业检验检测体系建设，此判断正确。' WHERE id = '9fe4eac4-72af-42ef-bd1e-17b22483d02b';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百零九条，监督检查是督促食品生产经营企业落实食品安全主体责任的必要方法，故B正确。' WHERE id = '9ff58afd-efd9-429d-9980-3c981864f2a2';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十四条，食品经营企业应对''所有''职工（包括临时从事食品安全工作的职工）进行食品安全知识培训，题目说''无需对临时职工培训''错误。' WHERE id = 'a003fe7d-f989-40f7-b7f2-9bc330c61857';
UPDATE public.questions SET analysis = '依据《特殊医学用途配方食品注册管理办法》第十九条，特殊医学用途配方食品注册证书有效期限为5年。注册证书到期需继续生产的，应在有效期届满6个月前申请延续注册，故C正确。' WHERE id = 'a00e4660-26d1-4e96-97d4-8dd3da43b50b';
UPDATE public.questions SET analysis = '依据《特殊医学用途配方食品注册管理办法》第十九条，特殊医学用途配方食品注册证书有效期限为5年。注册证书到期需继续生产的，应在有效期届满6个月前申请延续注册，故C正确。' WHERE id = 'a0119a0c-6c2c-4495-8b3e-01e584e2c174';
UPDATE public.questions SET analysis = '依据GB 13104《食品安全国家标准 食糖》，生物指标仅规定螨一项限量要求。螨是食糖中特有的生物性污染物指标，反映食糖在生产、贮存过程中的卫生状况，故D正确。' WHERE id = 'a01a447b-cd11-48ae-885c-bb360197e3d3';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百三十条，集中交易市场开办者未履行义务导致食品安全事故的，应承担连带责任。题目说''不需要承担''错误。' WHERE id = 'a02c39df-9c11-486e-9b28-51e2ed122e0c';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第四条，食品经营许可实行一地一证原则，一个经营场所应取得一个食品经营许可证，此判断正确。' WHERE id = 'a03aa103-f2be-4502-adc1-fc843cd4a484';
UPDATE public.questions SET analysis = '依据《食品召回管理办法》第二十三条，食品生产经营者对召回食品进行无害化处理、销毁前应向监管部门报告时间、地点，不能先销毁后报告，此判断错误。' WHERE id = 'a03b29af-14f1-45e7-8309-c631dbfe0f64';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十五条，食品生产经营从业人员应每年进行健康检查，取得健康证明后方可上岗。题目说''每两年''与法定要求不符，故此判断为错。' WHERE id = 'a048ce04-8439-4641-9b0d-e227db3cec38';
UPDATE public.questions SET analysis = '依据《食品安全法》第四十五条，食品生产经营从业人员应每年进行健康检查，取得健康证明后方可上岗。题目说''每两年''与法定要求不符，故此判断为错。' WHERE id = 'a04d375b-b6ab-4f1d-b3be-2d64307cde2c';
UPDATE public.questions SET analysis = '生食水产制品原料应检验致病菌、病毒和寄生虫及其虫卵。菌落总数为常规卫生指标，非原料专项检验项目，故A,B,D正确。' WHERE id = 'a0595188-2d53-4a25-8d01-15da3f898ec5';
UPDATE public.questions SET analysis = '依据《保健食品经营监督管理规定》，实行统一配送经营方式的保健食品经营企业，可由企业总部统一查验供货者的许可证和食品合格证明文件，此判断正确。' WHERE id = 'a0603957-e7b4-444e-abad-a0c1ea889737';
UPDATE public.questions SET analysis = '依据GB 5420《食品安全国家标准 干酪》及干酪制品相关标准，干酪制品以干酪比例15%-50%为主要原料，故B正确。' WHERE id = 'a063e4cf-1714-44cf-acab-ba3993f7bdae';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》，接触直接入口食品的从业人员应佩戴口罩和手套，但''必须戴一次性手套''表述过于绝对，可重复使用的手套经消毒后也可使用，此判断错误。' WHERE id = 'a075c1bb-b496-4c7a-88cb-652bcff40ae5';
UPDATE public.questions SET analysis = '依据《市场监督管理投诉举报处理暂行办法》，消费者投诉举报电话统一为12315，故C正确。12369为环保热线，12331已整合入12315。' WHERE id = 'a09bf736-1f91-4865-92c2-03af6a431593';
UPDATE public.questions SET analysis = '依据《关于办理危害食品安全刑事案件适用法律若干问题的解释》，含有严重超标致病性微生物、农药残留、重金属等，属于病死、死因不明动物肉类，国家明令禁止生产销售，婴幼儿食品营养成分严重不达标等情形，均应认定为''足以造成严重食物中毒''，故A,B,C,D均正确。' WHERE id = 'a0ab19ee-bf99-4388-ab07-76324e85d9c7';
UPDATE public.questions SET analysis = '国家卫生健康委员会印发《按照传统既是食品又是中药材的物质目录管理规定》，明确了食药物质的动态调整和管理规范，此判断正确。' WHERE id = 'a0bb0b7a-004f-4024-ae70-78f893aa9cfc';
UPDATE public.questions SET analysis = '依据《学校食品安全与营养健康管理规定》，学校食堂从业人员的健康证明应在学校食堂显著位置统一公示，故B正确。' WHERE id = 'a0bb2f23-3a2d-4477-a4cf-5799101d6a78';
UPDATE public.questions SET analysis = '依据《食品安全法》第五十三条，食品经营企业进货查验记录和凭证保存期限不得少于产品保质期满后6个月，故B正确。' WHERE id = 'a0c7bf12-9576-41fa-99dd-89927d9c3321';
UPDATE public.questions SET analysis = '依据《食品经营许可审查通则》，难以明确归类的食品应按照食品安全风险等级最高的情形进行归类，故C正确。' WHERE id = 'a0c8c9b4-4a92-4858-a625-eaf470bd40a6';
UPDATE public.questions SET analysis = '依据GB 2718《食品安全国家标准 酿造酱》，酿造酱中大肠菌群限量为n=5,c=2,m=10CFU/g,M=100CFU/g，故C正确。' WHERE id = 'a0d3b84f-69a8-480f-a5e0-655d12a5b7de';
UPDATE public.questions SET analysis = '依据《关于''三新食品''目录及适用的食品安全标准的公告》（2023年第4号），新食品原料目录的食品安全标准设置18个月过渡期，故C正确。' WHERE id = 'a0d93105-5ed5-4136-a604-2722be6f7625';
UPDATE public.questions SET analysis = '依据《食品安全抽样检验管理办法》第四十条，食品生产经营者收到监督抽检不合格检验结论后，应立即采取封存不合格食品、暂停生产经营、通知相关方、召回已上市食品等措施，故A,B,C,D均正确。' WHERE id = 'a1137f18-16d2-4601-8d46-2bbbd89ea7d9';
UPDATE public.questions SET analysis = '依据《保健食品消费提示》相关规定，保健食品不是药物不能代替治疗疾病；选购应认准标志和批准文号；注册信息可在国家市场监督管理总局网站查询；应到正规经营单位购买并索要发票，故A,B,C,D均正确。' WHERE id = 'a113d294-3609-4976-b2de-f7d948b651e6';
UPDATE public.questions SET analysis = '依据GB/T 35888《食品安全国家标准 方糖》，方糖是由粒度适中的白砂糖加入少量水或糖浆，经压铸等工艺制成的小方块糖，故A正确。' WHERE id = 'a11be0b7-ab45-4c09-bd90-260e629ce762';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》，传菜员传菜时应避免说话，打喷嚏等有碍食品安全的事项时要立刻远离食品，但并非必须都戴口罩（视具体情况），故B正确。' WHERE id = 'a12616a6-bff7-4db6-aaa5-ccf3bec9d102';
UPDATE public.questions SET analysis = '依据GB 14881-2013第12.1条，食品生产企业应根据不同岗位需求制定培训计划（A正确），应对人员进行培训并考核（B错误，不能不考试），应做好培训记录（C正确），法律法规更新时应及时培训（D正确）。故B不正确。' WHERE id = 'a128badf-957c-4060-9777-d41db01da758';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十三条，食品生产企业应具有合理的设备布局和工艺流程，以防止待加工食品与直接入口食品交叉污染、避免食品接触不洁物、防止原料与成品交叉污染、避免食品接触有毒物，故A,B,C,D均正确。' WHERE id = 'a128fda5-5eb7-426d-9304-9815085ef90b';
UPDATE public.questions SET analysis = 'GB 14881-2013是《食品安全国家标准 食品生产通用卫生规范》，故C正确。HACCP为危害分析临界控制点体系，GB 12693为乳制品良好生产规范。' WHERE id = 'a1363453-6ec2-4924-9c0f-43dd3f35d327';
UPDATE public.questions SET analysis = '依据《食品安全法实施条例》第二十一条，委托生产食品、食品添加剂的，委托方、受托方应遵守法律法规和食品安全标准，将委托情况单独记录留档备查，此判断正确。' WHERE id = 'a15eed86-2138-4b82-9b60-cbf3ef0e4cff';
UPDATE public.questions SET analysis = '依据《食品安全法》第二十五条、第三十条，食品安全标准为强制性标准，食品生产企业必须执行。推荐性标准自愿采用，非必须执行，此判断错误。' WHERE id = 'a16daccd-25ba-4d47-b48c-ef19ff432fd2';
UPDATE public.questions SET analysis = '依据GB 8537《食品安全国家标准 饮用天然矿泉水》，饮用天然泉水的生产用源水是以地下自然涌出或经钻井采集的未经公共供水系统的自然来源水，此判断正确。' WHERE id = 'a16ecb80-9e79-4ea6-967d-d2bca2bbd533';
UPDATE public.questions SET analysis = '依据《食品安全法》第十七条，国家建立食品安全风险评估制度，运用科学方法对生物性、化学性和物理性危害因素进行风险评估，故D正确。' WHERE id = 'a16f256b-567d-441e-a9f2-bea4bb111b65';
UPDATE public.questions SET analysis = '依据《学校食品安全与营养健康管理规定》，学校应与供餐单位签订供餐合同（或协议），明确双方食品安全与营养健康的权利和义务，存档备查，此判断正确。' WHERE id = 'a1b70175-defe-4139-b0a5-ea679cb5c8b6';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》，食品安全员对食品安全总监或企业主要负责人负责，从事食品安全管理具体工作，故D正确。' WHERE id = 'a1b73c8e-9a50-4e6c-9057-5520b5eda523';
UPDATE public.questions SET analysis = '依据《茶叶生产许可审查细则》，茶叶申证类别包括绿茶、红茶、乌龙茶、黄茶、白茶、黑茶、花茶、袋泡茶、紧压茶，故C正确。' WHERE id = 'a1b80123-c149-4333-8c20-37c71c565cbb';
UPDATE public.questions SET analysis = '依据《食品经营过程卫生规范》（GB 31621），食品与地面间距不少于10厘米，冷藏冷冻食品与墙壁间距不少于10厘米，其他食品与墙壁间距宜不少于10厘米，此判断正确。' WHERE id = 'a1b8fa90-7514-49b0-9090-136fc8b0155f';
UPDATE public.questions SET analysis = '依据《反食品浪费法》第八条，设有食堂的单位应建立健全食堂用餐管理制度，制定并实施防止食品浪费措施，故C正确。' WHERE id = 'a1e459d7-a87c-4cf1-94c4-83acc4dc2726';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十五条，国家对食品生产经营实行许可制度，从事食品销售、餐饮服务应依法取得食品经营许可，故B正确。' WHERE id = 'a1f4bd77-c561-4191-81d0-42163fc40d01';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》，''日管控''由食品安全员每日根据风险管控清单检查，形成《每日食品安全检查记录》，故A正确。' WHERE id = 'a1f9cc8a-39a0-40b7-acdc-0a519a837352';
UPDATE public.questions SET analysis = '依据GB 2712《食品安全国家标准 豆制品》，熏制豆腐干是以豆腐干为原料，经烟熏及相关工艺加工而成的具有薰香味的产品，此判断正确。' WHERE id = 'a20eb21b-e0ba-4b14-af7a-ebf19de321ad';
UPDATE public.questions SET analysis = '依据GB 14881-2013，对微生物的控制可设置科学合理的灭菌温度、时间等工艺参数，杀灭原料、成品和包装材料中的微生物，故A,B正确。' WHERE id = 'a21e1b93-de31-4de4-9ea2-d48d6661b24c';
UPDATE public.questions SET analysis = '依据GB 2707《食品安全国家标准 鲜（冻）畜、禽产品》，冷冻畜、禽产品应贮藏在低于-18℃的冷冻肉储藏库中，故B正确。' WHERE id = 'a22cb560-57a6-4b31-ae45-dffb9ac97ae3';
UPDATE public.questions SET analysis = '依据《食品召回管理办法》第二十三条，食品生产经营者对召回食品进行无害化处理、销毁的，应当提前报告时间、地点，监管部门认为必要的应实施现场监督。题目说''应当实施现场监督''表述绝对，判断为错。' WHERE id = 'a2381225-0491-4705-907e-3a4ec5e3be6f';
UPDATE public.questions SET analysis = '依据GB 14881-2013第5.1.5条，车间个人卫生设施应保证工作服与个人服装分开放置、设置鞋套或工作鞋靴消毒设施、卫生间内设置洗手设施、水龙头开关为非手动式，故A,B,C,D均正确。' WHERE id = 'a24358e5-68b8-44ef-b4f4-b544b76a5e9a';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十六条，农民个人销售其自产的食用农产品，不需要取得食品销售许可。但销售者应对所售食用农产品的质量安全负责，此判断正确。' WHERE id = 'a25d2739-a69c-4df8-8743-cf6654d9f1b4';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十六条，农民个人销售其自产的食用农产品，不需要取得食品销售许可。但销售者应对所售食用农产品的质量安全负责，此判断正确。' WHERE id = 'a26707c5-2a93-498f-8413-8bd0b0fd53bc';
UPDATE public.questions SET analysis = '依据GB 14881-2013第6.4.2条，食品生产企业应保持食品包装、贮存容器的密闭良好，防止在加工、贮存、销售等环节的虫害侵入，此判断正确。' WHERE id = 'a2693122-9bdc-41b0-9427-1cdd8e378314';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第三十五条，食品经营许可证遗失、损坏的，应向原发证部门申请补办，提交补办申请书、书面遗失声明或受损坏的许可证，此判断正确。' WHERE id = 'a2714e79-00ae-4b57-9faa-1a7a61565056';
UPDATE public.questions SET analysis = '依据《葡萄酒生产卫生规范》，葡萄酒生产过程应减少或不使用塑料、锡、铅、铝等材质工器具，使过程污染物含量降至最低，此判断正确。' WHERE id = 'a2725b08-f054-4cf5-aa4d-8e0b0f6d75fe';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百零三条，食品生产经营者不得隐匿、伪造、毁灭与食品安全事故有关的资料。用编造记录替代原始记录属于违法行为，此判断错误。' WHERE id = 'a2819f5f-592f-4c7e-ad11-723ec2bedd6d';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》及方便食品审查细则，调味面制品属于方便食品类别，故B正确。罐头属于罐头食品，火腿肠属于肉制品，牛奶属于乳制品。' WHERE id = 'a284b0f3-c5d8-43d1-8a9a-ebe1bfa86776';
UPDATE public.questions SET analysis = '依据《食品安全法》第二条和第五十条，食品生产者采购农产品等食品原料，应依照《中华人民共和国食品安全法》的规定查验许可证和合格证明，故A正确。' WHERE id = 'a28f8d7d-3bc5-4078-b5b5-4a5740951f04';
UPDATE public.questions SET analysis = '黄酒煎酒过程中不仅监控温度，还需监控时间、压力等参数，题目说''主要监控煎酒温度''表述不全面，此判断错误。' WHERE id = 'a296b113-1fb8-4a88-95e9-bc40811ebe2c';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》，食品安全总监、食品安全员发现有食品安全事故潜在风险的，有权提出停止相关食品生产经营活动等否决建议，题目说''无权''错误。' WHERE id = 'a2a68455-7faf-4ff4-8fc7-5029dfab7302';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第十一条，从事食品经营管理应具备与其经营规模相适应的食品安全管理能力，建立健全食品安全管理制度，配备食品安全管理人员，对经营的食品安全负责，故A,B,C,D均正确。' WHERE id = 'a2ab1f6d-721f-4698-9898-3a2a5809c71c';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第十二条，申请材料存在可当场更正错误的应允许当场更正（A正确），不齐全或不符法定形式的应5个工作日内一次告知补正（B正确），D选项缺少''5个工作日内''表述不准确，故A,B正确。' WHERE id = 'a2c3d090-c9d3-441a-a19b-89158744b5f5';
UPDATE public.questions SET analysis = '依据《食品安全法》第二十五条和第三十条，食品安全标准是强制执行的标准。除食品安全标准外，不得制定其他食品强制性标准，故D正确。' WHERE id = 'a2cc572d-2d50-4d3d-a99f-113f556da337';
UPDATE public.questions SET analysis = '依据《食品安全法》第二十五条和第三十条，食品安全标准是强制执行的标准。除食品安全标准外，不得制定其他食品强制性标准，故D正确。' WHERE id = 'a2d961d1-4e01-4075-b72d-80429dc09afc';
UPDATE public.questions SET analysis = '依据GB 2763《食品安全国家标准 食品中农药最大残留限量》及茶叶农药使用规定，硫丹、三氯杀螨醇、氰戊菊酯、灭多威均为茶园禁用农药，故A,B,C,D均正确。' WHERE id = 'a2e0bbea-830e-4aad-9115-f290d9325acb';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》，运输食品时应根据食品特点选择适宜运输工具，必要时需保温、冷藏冷冻、保鲜保湿等设施，故D正确。' WHERE id = 'a2ec6ef1-a59f-4326-bd7a-901c1a1262c3';
UPDATE public.questions SET analysis = '烘炒类炒货食品及坚果制品包括炒瓜子、炒花生、炒豌豆等。油炸青豆属于油炸类，不属于烘炒类，故B,C,D正确。' WHERE id = 'a2f7b0fc-d6e0-4621-8294-c8d4a35f3194';
UPDATE public.questions SET analysis = '依据GB 2759-2015《食品安全国家标准 冷冻饮品和制作料》，该标准适用于冷冻饮品和制作料，不适用于现制现售的冷冻饮品，此判断错误。' WHERE id = 'a305ea76-2a00-4c69-90e3-e1053e5ebdae';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》，集体用餐配送单位是集中加工、分送食品但不提供就餐场所的餐饮服务提供者，故B正确。' WHERE id = 'a30fcf28-3c1e-4f26-b2a7-f541fadd8f8e';
UPDATE public.questions SET analysis = '依据《生猪屠宰管理条例》第二十九条，从事生猪产品销售、肉食品生产加工的单位和个人以及餐饮服务经营者、集中用餐单位生产经营的生猪产品，必须是经检疫和肉品品质检验合格的生猪产品，此判断正确。' WHERE id = 'a3222705-c91a-45d6-9fe8-5503da903648';
UPDATE public.questions SET analysis = '依据《食品安全法》及《餐饮服务食品安全操作规范》，食品生产经营过程中存在因经济利益驱动导致的掺杂使假、蓄意破坏等人为故意造成的食品安全风险，故A正确。' WHERE id = 'a32a6b90-9147-4210-ba12-972bc5008621';
UPDATE public.questions SET analysis = '依据《最高人民法院关于审理食品安全民事纠纷案件适用法律若干问题的解释（一）》第一条，生产者或经营者以赔偿责任应由另一方承担为由主张免责的，法院不予支持，此判断错误。' WHERE id = 'a32bb0fe-2384-41fd-8c5f-7ced619aa7ef';
UPDATE public.questions SET analysis = '依据GB 2726《食品安全国家标准 熟肉制品》，发酵肉灌制品因含有活性发酵微生物，无需检测菌落总数项目，故B正确。' WHERE id = 'a33f7ae3-08c7-4680-926d-eda643dc822e';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》，专间入口处应设独立洗手、消毒、干手、更衣设施，水龙头非手动开启（A正确）；专间门坚固、不吸水、易清洗、能自动关闭（B正确）；专间内设独立空调、专用清洗消毒设施、冷藏设施和空气消毒设施（C正确）；水龙头和废弃物容器盖子为非手动开启式（D正确），故A,B,C,D均正确。' WHERE id = 'a3426c8f-6cd5-4052-9437-07057b0f84b8';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》，连锁餐饮服务企业总部应督促中央厨房、配送中心、门店严格执行食品安全管理制度和操作规程，此判断正确。' WHERE id = 'a3703ece-c046-48cd-a1f3-5f86d5aa6ae3';
UPDATE public.questions SET analysis = '依据《食品安全法实施条例》第三十九条，特殊食品不得与普通食品或药品混放销售（A正确）；医疗机构、药品零售企业销售特定全营养配方食品不需取得经营许可（B正确）；保健食品经营场所应标注消费提示（C正确）；特定全营养配方食品需按规定渠道销售（D错误），故A,B,C正确。' WHERE id = 'a377ff5a-7807-44a2-92cb-7141af861f58';
UPDATE public.questions SET analysis = '依据GB 14881-2013，对食品添加剂以及清洁剂、消毒剂、润滑剂等应明确标识、分类管理、妥善保存，故A正确。' WHERE id = 'a399435a-a91e-4efc-b074-2db9fc2d35ab';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第六十九条，注册申请人隐瞒真实情况或提供虚假材料申请注册的，不予受理或不予注册，给予警告，1年内不得再次申请，故B正确。' WHERE id = 'a3a1af3c-eee6-4363-963a-fce65483b8cd';
UPDATE public.questions SET analysis = '大豆膳食纤维粉是大豆加工过程中产生的大豆皮和大豆渣，经提纯、分离、干燥、粉碎（全部通过孔径0.15mm筛）等处理而成的产品，故A,B,C,D均正确。' WHERE id = 'a3ae514f-5efd-4cc5-b4c9-3d91d7c3baaa';
UPDATE public.questions SET analysis = '依据《食品安全抽样检验管理办法》第三十一条，复检备份样品超过保质期的，不予复检。因超过保质期的样品不能代表抽检时的产品质量状态，故判断为对。' WHERE id = 'a3b13a16-ad32-4d92-a72c-54a4d920747c';
UPDATE public.questions SET analysis = '依据《食品安全抽样检验管理办法》第三十一条，复检备份样品超过保质期的，不予复检。因超过保质期的样品不能代表抽检时的产品质量状态，故判断为对。' WHERE id = 'a3b1f666-2b92-45d0-9bb2-557ef171ae54';
UPDATE public.questions SET analysis = '依据《食盐质量安全监督管理办法》第九条，未加碘食盐的标签应当在显著位置标注''未加碘''字样。题目说''可以不标注''错误。' WHERE id = 'a3ba4472-e8b3-4e99-9ec4-9a9f3ffb02cd';
UPDATE public.questions SET analysis = '依据《食品安全法》第三十三条，食品生产企业应确保生产活动符合GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》等相应食品安全标准，此判断正确。' WHERE id = 'a3dd839d-a9bb-43ff-a964-73dcec5e1f6a';
UPDATE public.questions SET analysis = '依据《食品经营许可管理办法》第十二条，申请食品经营许可应提交食品经营许可申请书、营业执照复印件、主要设备设施和经营布局文件、食品安全规章制度目录清单等，故A,B,C,D均正确。' WHERE id = 'a3df1f1d-862e-4e9e-a3f0-4e0ee474af89';
UPDATE public.questions SET analysis = '依据GB 2762-2022《食品安全国家标准 食品中污染物限量》，蒸馏酒和配制酒（白酒）铅限量为0.5mg/kg，而非2.0mg/L，此判断错误。' WHERE id = 'a3e94ae7-fdf0-4f84-aeab-dd30adaeff64';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》，企业应结合实际情况制定食品安全风险管控清单，建立健全日管控、周排查、月调度工作制度和机制，故A,B,C正确。' WHERE id = 'a3f8040f-6885-4cce-9179-2163d8a9e782';
UPDATE public.questions SET analysis = '依据GB 14881-2013，水果制品生产企业应注意生产过程中清洗、干燥等环节的卫生管理，避免交叉污染，故A正确。' WHERE id = 'a40e4eb5-5ec1-4360-b904-65994cd603bb';
UPDATE public.questions SET analysis = '依据《行政许可法》第五条，有关行政许可的规定应当公布，未经公布的不得作为实施行政许可的依据，此判断正确。' WHERE id = 'a413e224-75bd-44fa-8ad1-9fdde7f0ec9b';
UPDATE public.questions SET analysis = '依据《国务院关于加强食品等产品安全监督管理的特别规定》第三条，生产经营者不再符合法定条件继续生产经营的，由原发证部门吊销许可证照并公告，构成犯罪的追究刑事责任，故A,B,C正确。' WHERE id = 'a436cdf0-4363-443f-94cf-6b709b088da4';
UPDATE public.questions SET analysis = '依据《关于办理危害食品安全刑事案件适用法律若干问题的解释》第二条，造成轻伤以上伤害、轻度或中度残疾、器官功能障碍、十人以上严重食物中毒等情形，应认定为''对人体健康造成严重危害''，故A,B,C,D均正确。' WHERE id = 'a437f699-99ac-416a-8225-33c632643335';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第四十五条，首次进口的属于保健食品原料目录的补充维生素、矿物质等营养物质的保健食品应依法备案，故A,C,D正确。' WHERE id = 'a43fc5ec-d60e-4373-92b7-1dc689227bf6';
UPDATE public.questions SET analysis = '食用植物油受加工温度等关键参数影响，苯并[a]芘、酸价、过氧化值容易超标。苯并[a]芘与高温加工有关，酸价和过氧化值反映油脂氧化酸败，故B,C,D正确。' WHERE id = 'a444135b-64ef-4873-92f6-fb2dd344404b';
UPDATE public.questions SET analysis = '正常合格液体淀粉糖外观为黏稠状透明液体，粉末状态和结晶状态为固体淀粉糖特征，不发黏无发霉为质量要求而非外观形态，故B正确。' WHERE id = 'a456b0a6-cc11-4dfb-82d0-10dd0c604466';
UPDATE public.questions SET analysis = '依据GB/T 9833《紧压茶》及茶叶分类标准，茯砖茶是以黑毛茶为主要原料，经渥堆、压制、发花等工艺加工而成的紧压茶品种，属于黑茶类紧压茶的主要品种之一，故D正确。' WHERE id = 'a4576afe-4445-40e6-8d02-5a56457792db';
UPDATE public.questions SET analysis = '依据GB/T 9833《紧压茶》及茶叶分类标准，茯砖茶是以黑毛茶为主要原料，经渥堆、压制、发花等工艺加工而成的紧压茶品种，属于黑茶类紧压茶的主要品种之一，故D正确。' WHERE id = 'a45a57c5-74b5-4116-a3d8-aec6391edaa3';
UPDATE public.questions SET analysis = '依据《食品添加剂标识通则》，提供给消费者直接使用的食品添加剂标识应注明''零售''字样，复配食品添加剂应在配料表中标明各单一品种及含量，此判断正确。' WHERE id = 'a46012eb-96e3-467b-bdde-567977eb7858';
UPDATE public.questions SET analysis = '依据GB 7718-2011，食品标识上的注册商标可以使用外文，不必须使用中文。题目说''必须使用中文''错误。' WHERE id = 'a4635942-a846-4250-8081-24afcdc5c068';
UPDATE public.questions SET analysis = '依据GB 8950《食品安全国家标准 罐头食品生产卫生规范》，罐头食品加工中密封后的半成品应在2小时内进行杀菌，故B正确。' WHERE id = 'a47635ba-d89a-42c5-8205-f78ba79ccd67';
UPDATE public.questions SET analysis = '依据GB 2758《食品安全国家标准 发酵酒及其配制酒》，啤酒中甲醛有限量要求。甲醇、苯并芘、N-二甲基亚硝胺非啤酒的常规限量指标，故D正确。' WHERE id = 'a483b0d6-281a-46b3-a49a-8a69665441f5';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》，防鼠板高度不低于60cm但门缝隙应小于6mm（A错误）；防蝇胶帘覆盖整个门框底部离地小于2cm（B正确）；相邻胶帘条重叠不少于2cm（C正确）；通风口加装不小于16目防虫筛网（D正确），故B,C,D正确。' WHERE id = 'a4914f7b-48bc-4137-9ff5-d9d7aa352046';
UPDATE public.questions SET analysis = '依据《食品安全法实施条例》第十八条，企业食品安全管理人员监督抽查考核指南由国务院食品安全监督管理部门制定、公布，故B正确。' WHERE id = 'a4929e70-46f6-4e47-b3a5-80cefdedd036';
UPDATE public.questions SET analysis = '依据《食品安全法》第一百三十五条，因食品安全犯罪被判处有期徒刑的，终身不得从事食品生产管理工作。题目说''五年后可从事''错误。' WHERE id = 'a4a36d4c-b46e-4ef3-abf8-63f093fadbb6';
UPDATE public.questions SET analysis = '依据《食用农产品市场销售质量安全监督管理办法》第二十五条，销售未包装食用农产品应在摊位明显位置公布名称、产地、生产者或销售者名称等信息，故A正确。' WHERE id = 'a4a71143-a8a5-4985-b5bb-09c0b81650b6';
UPDATE public.questions SET analysis = '依据《食品召回管理办法》第二十五条，食品生产经营者对不安全食品进行无害化处理、销毁时，相关记录保存期限不得少于二年，以备监管部门查验追溯，故A正确。' WHERE id = 'a4b5eae0-5ffa-4dde-bbd4-52d7bf758009';
UPDATE public.questions SET analysis = '依据《食品召回管理办法》第二十五条，食品生产经营者对不安全食品进行无害化处理、销毁时，相关记录保存期限不得少于二年，以备监管部门查验追溯，故A正确。' WHERE id = 'a4cc1b3d-fae3-43ac-ab7c-101231ba08ca';
UPDATE public.questions SET analysis = '依据《食品安全法》第二十九条，对地方特色食品没有国家标准的，省级卫生行政部门可以制定地方标准，报国务院卫生行政部门备案。国家标准制定后地方标准即行废止，此判断正确。' WHERE id = 'a4d90935-ec5e-4f0c-99a2-6931cdf16f2c';
UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》，受理后3个工作日内送交审评（A正确），审评机构60个工作日内完成审评（B正确），核查机构20个工作日内完成核查（C错误，应为20日非30日），10个工作日内发出证书（D正确），故A,B,D正确。' WHERE id = 'a4eabcbb-2404-4793-b3c2-c4d6c015ce14';
UPDATE public.questions SET analysis = '依据GB 2760及茶叶生产规范，绿茶、紧压茶等不得使用食品用香精香料，混合代用茶和袋泡调味茶可以使用，故B,C正确。' WHERE id = 'a4fb8865-7dbe-4bef-9462-38b69d037c30';
UPDATE public.questions SET analysis = '依据《学校食品安全与营养健康管理规定》，学校需要现场分餐的，可以在教室分餐，但应符合卫生要求。题目说''不可以在教室分餐''错误。' WHERE id = 'a50ad289-f2ee-4d70-b95e-0817c4f59cb5';
UPDATE public.questions SET analysis = '依据《刑法》第一百四十四条，在生产、销售食品中掺入有毒有害非食品原料的，处五年以下有期徒刑并处罚金；造成严重危害的处五年以上十年以下有期徒刑；致人死亡的处十年以上有期徒刑、无期徒刑或死刑，故B,C,D正确。' WHERE id = 'a50e3b19-231e-4654-a52d-d241d21ba47c';
UPDATE public.questions SET analysis = '依据GB 19301-2010《食品安全国家标准 生乳》，蛋白质≥2.8g/100g为生鲜乳质量要求之一，此判断正确。' WHERE id = 'a5185c21-bfb7-41a5-8797-458db423b804';
UPDATE public.questions SET analysis = '《食品安全法》最近一次修订时间为2021年4月29日（第十三届全国人大常委会第二十八次会议），故C正确。' WHERE id = 'a51d7fcf-339e-4340-904e-42c90bb5f3a0';
UPDATE public.questions SET analysis = '依据《食品安全法》第七十一条，食品和食品添加剂标签、说明书不得含虚假内容，不得涉及疾病预防、治疗功能，生产经营者对其提供的标签、说明书内容负责，故D正确。' WHERE id = 'a5270c91-f029-4554-9799-6aa00b231e20';
UPDATE public.questions SET analysis = '依据《特殊医学用途配方食品注册管理办法》，审评机构应对特殊医学用途配方食品注册申请材料进行审查，并根据需要组织现场核查、抽样检验、临床试验核查和专家论证，故D正确。' WHERE id = 'a52809a5-1bd6-484a-898b-7d944bd2aff0';
UPDATE public.questions SET analysis = '《食品安全法》第四条明确规定，食品生产经营者应当依照法律、法规和食品安全标准从事生产经营活动，保证食品安全，诚信自律，对社会和公众负责，接受社会监督，承担社会责任。' WHERE id = 'a531800a-7316-4c36-9538-7ba9c19f2b41';
UPDATE public.questions SET analysis = '根据《婴幼儿配方乳粉产品配方注册管理办法》及其实践，境外生产企业现场核查需考虑国际行程、签证安排、企业配合度等多种因素，因此时限根据实际情况确定，而非固定期限。' WHERE id = 'a53701f1-128a-42b2-8478-4022f620ebb3';
UPDATE public.questions SET analysis = '冷冻饮品后期添加巧克力涂层属于后加工工序，涂层制作温度较高且暴露于环境中，可能引入微生物污染。依据GB 14881《食品生产通用卫生规范》，后期加工环节应严格控制微生物风险。' WHERE id = 'a53b0179-7305-45d9-ab21-5d6837f916b6';
UPDATE public.questions SET analysis = '《食品安全法》第五十四条及GB 7718《预包装食品标签通则》规定，食品经营者应当按照标签标示的贮存条件贮存和展售食品，不得自行改变贮存条件和保质期。' WHERE id = 'a53e55c3-7cdd-45da-8bf6-b61ffd95fd87';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，从事接触直接入口食品工作的食品生产经营人员应当每年进行健康检查，取得健康证明后方可上岗工作。必须先取得健康证明才能上岗，A、C、D选项均违反法律规定。' WHERE id = 'a541eeb0-d5f5-482b-93d9-43166d1eaef1';
UPDATE public.questions SET analysis = '依据《食品经营过程卫生规范》（GB 31621）及相关冷链管理要求，需冷藏的食品运输和贮存温度应控制在0℃~10℃。B、C、D选项温度范围过窄或不准确。' WHERE id = 'a55e5ca4-cbfe-49dc-bcd8-0235f11d5364';
UPDATE public.questions SET analysis = '《食品安全法》第三十条规定，国家鼓励食品生产企业制定严于食品安全国家标准或地方标准的企业标准，在本企业适用，并报省、自治区、直辖市人民政府卫生行政部门备案。' WHERE id = 'a55ed6cb-5e45-46fa-a6b2-bc671fff9714';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条明确规定，从事接触直接入口食品工作的食品生产经营人员应当每年进行健康检查，取得健康证明后方可上岗工作。' WHERE id = 'a5643b01-b83d-4896-984f-8260c44d8cf3';
UPDATE public.questions SET analysis = '依据《速冻食品生产和经营卫生规范》（GB 31646-2018），冷冻薯类产品的标准工艺流程包括漂烫（ blanching）工序，用于灭酶活、固定色泽并降低微生物负荷。' WHERE id = 'a56ab59a-6c84-45df-be11-779b1550dea7';
UPDATE public.questions SET analysis = '熟啤酒生产工艺流程为：原料→糖化→发酵→过滤→灌装封盖→杀菌→成品。发酵是啤酒酿造的核心工序，将麦汁中的糖分转化为酒精和二氧化碳。' WHERE id = 'a57812ab-52f2-488c-9eb1-6662e6a77300';
UPDATE public.questions SET analysis = '根据《学校食品安全与营养健康管理规定》及《食品经营许可管理办法》，学校食堂、托幼机构食堂不得申请生食类食品制售项目，不得申请冷食类食品中的冷荤类食品制售、冷加工糕点制售等高风险食品制售项目。该表述符合现行法规要求，应为''对''。' WHERE id = 'a57f3650-3ca2-46df-8e1c-8562339f3bba';
UPDATE public.questions SET analysis = '依据GB 7718《预包装食品标签通则》4.3.1条规定，酒精度大于等于10%的饮料酒可以免除标示保质期。高酒精度可抑制微生物生长，产品稳定性较好。' WHERE id = 'a587311a-b154-4545-b1fb-2e8942ef2c8d';
UPDATE public.questions SET analysis = '《食品安全法》及《食品经营许可管理办法》规定，经营保健食品须依法取得食品经营许可证，且经营项目中须包含''保健食品销售''。' WHERE id = 'a58ea377-f151-4f88-95dc-2a47d2aa7e57';
UPDATE public.questions SET analysis = '《网络餐饮服务食品安全监督管理办法》第九条规定，入网餐饮服务提供者应当在网上公示餐饮服务提供者的名称、地址、量化分级信息等。法人和食品安全员不属于强制公示内容。' WHERE id = 'a5a3b0ec-abf5-469b-9144-9e6f6405bf19';
UPDATE public.questions SET analysis = '依据《食品经营过程卫生规范》（GB 31621），需冷藏的食品运输和贮存温度应为0℃~10℃，而非0℃~5℃。0℃~5℃是冷冻食品的常见温度要求。' WHERE id = 'a5aa3f05-9ee1-4991-8ed9-639e31c9d396';
UPDATE public.questions SET analysis = '《食品安全法》第一百二十六条规定，A、B、D选项违法行为拒不改正的，处五千元以上五万元以下罚款。C选项''生产经营标注虚假生产日期、保质期或者超过保质期的食品''依据第124条处罚，处罚更重。' WHERE id = 'a5b4c3e8-0c28-42e7-843e-803ac5230e30';
UPDATE public.questions SET analysis = '依据GB 14881《食品生产通用卫生规范》及食品接触材料相关标准，食品生产设备的常用材质包括食品级不锈钢、食品级密胺树脂塑料、食品级聚乙烯（PE）和食品级聚丙烯（PP），均须符合食品安全国家标准要求。' WHERE id = 'a5dfae0c-8317-4e29-8e8a-7213cd693246';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》规定，延续注册应提交：产品营养、安全方面的跟踪评价情况，申请人主体资质证明文件，企业生产质量管理体系自查报告等。不需要总局的延续注册意见书。' WHERE id = 'a5e044b0-8065-4658-bc75-7d88f3425975';
UPDATE public.questions SET analysis = '依据GB 2760《食品添加剂使用标准》及计量管理要求，食品生产企业应对食品添加剂称量设备进行''校准''，确保投料准确。''校准''是计量学规范用语，指在规定条件下确定测量仪器示值与标准值关系的一组操作。' WHERE id = 'a5e7f5f7-a6a7-46fb-b7e6-2cbf5978fd8f';
UPDATE public.questions SET analysis = '《食品安全法》第六十八条规定，散装食品应在容器、外包装上标明食品名称、生产日期或生产批号、保质期、生产者名称及联系方式等内容。净含量不是散装食品必须标示的事项。' WHERE id = 'a5f3817d-f424-47e4-a602-a69c86328a5a';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，应设置专用保洁设施或场所存放消毒后的餐用具，防止餐用具受到二次污染，确保餐饮具卫生安全。' WHERE id = 'a5fbac06-08b0-4a5d-935e-c6e3a1fc8f8d';
UPDATE public.questions SET analysis = '《食品安全法》确立的全程控制原则要求建立从原料到餐桌的全过程管理制度，包括原料控制、过程控制、检验控制、生产销售记录等制度，确保食品安全全程可追溯。' WHERE id = 'a5fe2066-3c85-41c5-9e00-c6d04b7d974a';
UPDATE public.questions SET analysis = '鲭鱼、沙丁鱼、金枪鱼、秋刀鱼等青皮红肉海水鱼含有较高水平的组氨酸，在不当贮存条件下易转化为组胺，被称为高组胺鱼。GB 2733《鲜、冻动物性水产品》对组胺含量有明确限量。' WHERE id = 'a608796e-85aa-40cc-a2a7-1d9105af7cb8';
UPDATE public.questions SET analysis = '《食品安全法》第四十四条规定，食品生产经营企业应当建立健全食品安全管理制度，对职工进行食品安全知识培训，加强食品检验工作，依法从事生产经营活动。培训对象为全体职工。' WHERE id = 'a61f4547-f31e-4cb1-8605-49cbf8b54e8a';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食品安全指食品无毒、无害，符合应当有的营养要求，对人体健康不造成任何急性、亚急性或者慢性危害。' WHERE id = 'a63f9d06-91a6-4882-835e-f28215e86f49';
UPDATE public.questions SET analysis = '《粮食质量安全监管办法》及粮食加工品相关标准要求，粮食加工品企业应对赤霉病高发重点区域、重点年份的原料加大验收检验频次，严防脱氧雪腐镰刀菌烯醇（DON）等真菌毒素超标。' WHERE id = 'a6504ff6-e625-4b84-ae75-5edb8738569f';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，食品销售企业主要负责人应建立食品安全责任制，落实月调度、食品安全自查、追溯体系建立、供货者管理、进货查验、经营过程控制等制度，并听取食品安全管理人员汇报。' WHERE id = 'a65cf4a0-7f60-4ff2-8955-09540771c1c3';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》自2019年10月1日起施行（日期编码42644对应2016年9月9日有误，应以官方发布版本为准）。该办法规范了婴幼儿配方乳粉的注册管理。' WHERE id = 'a68268c9-d73b-41dc-9817-11279afdbc7a';
UPDATE public.questions SET analysis = '《中华人民共和国广告法》第四条规定，广告不得含有虚假或者引人误解的内容，不得欺骗、误导消费者。广告主应当对广告内容的真实性负责。' WHERE id = 'a68f7bc1-7e3a-4add-b6cf-76ec07d30536';
UPDATE public.questions SET analysis = '《食品经营过程卫生规范》（GB 31621）及冷链管理相关规定要求，冷藏冷冻设施设备应设有有效的温度控制装置，设有可正确显示内部温度的温度监测设备，并定期校准、维护，确保准确有效。' WHERE id = 'a6980ed0-d8dc-4eb6-bd21-53d1d7647418';
UPDATE public.questions SET analysis = 'GB 2758《食品安全国家标准 发酵酒及其配制酒》中对葡萄酒、果酒等规定了甲醇限量，但对啤酒没有甲醇限量要求。啤酒的甲醇含量极低，不属于该标准重点控制指标。' WHERE id = 'a6b7a53e-a29d-4562-8348-5c10ba0b4858';
UPDATE public.questions SET analysis = '《食品安全法》第三十五条及《食品经营许可管理办法》规定，仅销售预包装食品的，不需要取得食品经营许可，但应当报所在地县级以上地方人民政府食品安全监督管理部门备案。' WHERE id = 'a6c3d35a-89d6-41a9-b685-e74e6c3731d4';
UPDATE public.questions SET analysis = '《食品安全国家标准 速冻食品生产和经营卫生规范》（GB 31646-2018）规定，速冻食品生产中包装段应设置金属检测装置，以防控物理性危害，防止金属异物混入产品。' WHERE id = 'a6cceaa0-e6d3-4a7b-9eb9-7a91f9535c72';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，食品安全风险管控清单制定应广泛收集外部和内部风险信息，包括企业管理制度、配方工艺、设备人员情况、国外风险预警信息、相关法律法规标准等。' WHERE id = 'a6ce94d2-4787-4264-a2b0-5b2dc0a08e72';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营者采购食品，应当查验供货者的许可证和食品出厂检验合格证或者其他合格证明，并建立食品进货查验记录制度。保健食品经营企业同样适用该规定。' WHERE id = 'a6f4c241-19dd-49ef-b67e-d22d785c40e4';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》第二十四条规定，食品生产许可证发证日期为许可决定作出的日期，有效期为5年。' WHERE id = 'a6f9e185-0baa-467a-8d76-4e5d6706113c';
UPDATE public.questions SET analysis = '其他食品因种类繁多、原料复杂、个体差异大，存在的主要风险包括：产品分类不明确导致监管混乱、缺乏统一标准导致质量安全问题、标准不一致导致添加剂超范围超限量使用、标签标识混乱误导消费者等。' WHERE id = 'a7033f3a-3566-484e-821e-1edfd88bd04f';
UPDATE public.questions SET analysis = 'GB 7718《预包装食品标签通则》4.1.4.1规定，如果在食品标签上特别强调添加了某种成分，应标示所强调配料的添加量或在成品中的含量。' WHERE id = 'a70ddb37-c7f4-4ade-81fd-5f58fc407d9f';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第四十六条规定，许可申请人隐瞒真实情况或提供虚假材料申请食品经营许可的，由县级以上地方食品药品监督管理部门给予警告。申请人在1年内不得再次申请食品经营许可。原题''处一万元以上三万元以下罚款''表述有误。' WHERE id = 'a717d1fd-ce1b-43fa-8241-fe2d41328e18';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，连锁食品销售企业总部应当配备食品安全总监，建立健全食品安全管理制度，落实食品安全主体责任。' WHERE id = 'a71a1189-9bb0-44bc-bfa1-fe66fe53c549';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》规定，餐饮服务连锁企业总部应根据其经营模式和规模，配备专职食品安全总监、专职食品安全员等食品安全管理人员，落实食品安全主体责任。' WHERE id = 'a71e65a3-9e57-4693-8f7e-2678fda8eb18';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十五条规定，因食品安全犯罪被判处有期徒刑以上刑罚的，终身不得从事食品生产经营管理工作，也不得担任食品生产经营企业食品安全管理人员。' WHERE id = 'a72a79df-c350-469e-b22d-2b69dd9e7ea5';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止生产经营超过保质期的食品。超过保质期限的保健食品无论以何种方式均不得销售，包括降价销售或作为处理食品销售。' WHERE id = 'a733ac51-082b-4df8-8db1-f21b5b11e168';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，患有国务院卫生行政部门规定的有碍食品安全疾病的人员，不得从事接触直接入口食品的工作。有碍食品安全疾病包括痢疾、伤寒、病毒性肝炎等消化道传染病及活动性肺结核等。' WHERE id = 'a7391b96-4b60-4e06-b703-b86c952877b6';
UPDATE public.questions SET analysis = 'GB 14881《食品生产通用卫生规范》规定，清洁消毒前后的设备和工器具应分开放置，防止交叉污染；B选项工具和容器需定期清理，C选项原料半成品不得混放，D选项照明设施应有防护罩。' WHERE id = 'a73dfc05-230a-48ab-aa2c-92aefaf05f15';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，许可申请人隐瞒真实情况或提供虚假材料申请食品经营许可的，由县级以上地方食品药品监督管理部门给予警告。申请人在1年内不得再次申请食品经营许可。' WHERE id = 'a748cbd3-e8c9-4118-8a01-d7607b5dbeaf';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，食品处理区内从业人员不应留长指甲、涂指甲油，不应化妆；工作时佩戴的饰物不应外露；应戴清洁的工作帽，避免头发掉落污染食品。原题表述均为肯定语气，应为正确做法。' WHERE id = 'a757244a-7949-4db5-a9fb-c21aad2a18d7';
UPDATE public.questions SET analysis = '《广告法》第十八条及《保健食品注册与备案管理办法》规定，保健食品广告不得涉及疾病预防、治疗功能，不得与药品、其他保健食品进行比较。' WHERE id = 'a75c16f3-1202-4afd-b1a0-951b126f0c4d';
UPDATE public.questions SET analysis = '《食品安全法》及《行政处罚法》规定，单位从事食品药品违法行为的，除对单位进行处罚外，还要依法追究单位直接负责的主管人员和其他直接责任人员责任，实行''双罚制''。' WHERE id = 'a7784253-3474-4282-80ab-f6494d6480c3';
UPDATE public.questions SET analysis = '《关于加强婴幼儿配方乳粉质量安全工作的意见》要求，经营者要对距离保质期不足一个月的婴幼儿配方乳粉及时采取醒目提示或提前下架等处理措施，防止过期产品销售。' WHERE id = 'a794d379-b630-4545-9783-2af6ec6c32e2';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第三十一条规定，复检备份样品超过保质期的，不予复检。因超过保质期后样品状态已改变，检验结果不能反映抽样时的真实状况。' WHERE id = 'a79657b0-653f-4ba1-88bf-dcf700978e21';
UPDATE public.questions SET analysis = '《食品安全法》第三十五条规定，从事食品销售和餐饮服务活动，应当依法取得食品经营许可。食品生产和食品运输分别适用不同的许可或管理规定。' WHERE id = 'a7a59c1b-2a20-4e01-aab2-f8bcc95f0206';
UPDATE public.questions SET analysis = '《学校食品安全与营养健康管理规定》及《餐饮服务食品安全操作规范》要求，高等学校食堂加工制作的大型活动集体用餐，热食、冷食类食品和生食类食品应当按规定留样，以备食品安全事件追溯调查。' WHERE id = 'a7b3b2a4-c383-40f6-9496-79515bac8da7';
UPDATE public.questions SET analysis = '《网络餐饮服务食品安全监督管理办法》及各地规定鼓励使用食安封签，但并非所有外卖都必须使用。''所有''一词表述过于绝对，目前为鼓励性而非强制性统一要求。' WHERE id = 'a7b5255f-8101-4453-8a9c-cdf22856fe06';
UPDATE public.questions SET analysis = '《食品安全法》第一百零九条规定，县级以上人民政府食品安全监督管理部门根据食品安全风险监测、风险评估结果和食品安全状况等，确定监督管理的重点、方式和频次，实施食品安全风险分级管理。' WHERE id = 'a7c0f71c-169e-47e4-93b7-644b702c2a8f';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》第一条规定，立法目的包括规范特殊医学用途配方食品注册行为，保证特殊医学用途配方食品质量安全，保障特定人群营养需求。' WHERE id = 'a7c6595d-29f3-49f9-b794-4b56498bceda';
UPDATE public.questions SET analysis = 'GB 14881《食品生产通用卫生规范》5.1.1.3规定，食品加工用水与其他不与食品接触的用水（如间接冷却水、污水等）应以完全分离的管路输送，避免交叉污染，避免逆流或相互沟通。' WHERE id = 'a7ca1320-f8bc-4bb5-ba9b-959962388a35';
UPDATE public.questions SET analysis = '《食品安全法》第七十九条及《广告法》第十八条规定，保健食品广告不得涉及疾病预防、治疗功能。保健食品不是药品，不能宣称具有疾病预防或治疗作用。' WHERE id = 'a7e04ec2-0602-4e07-91b1-c770056253f4';
UPDATE public.questions SET analysis = '再制蛋（如皮蛋、咸蛋）的生产工艺为：选蛋→清洗→配料→腌制→检验→包装。题中描述的是蛋粉类产品的生产工艺，不是再制蛋的工艺。' WHERE id = 'a7e3920e-b547-46bc-bc2b-6ef3548cab87';
UPDATE public.questions SET analysis = '《广告法》第十八条明确规定，保健食品广告不得含有表示功效、安全性的断言或保证，不得涉及疾病预防、治疗功能。' WHERE id = 'a7e3a05f-c7ef-4f00-9ec8-1ed005a7351a';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条明确规定，禁止生产经营标注虚假生产日期、保质期或超过保质期的食品、食品添加剂。' WHERE id = 'a7ed9536-ea05-4513-89dc-adbba8ac0c15';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，患有国务院卫生行政部门规定的有碍食品安全疾病的人员，不得从事接触直接入口食品的工作，而非不得从事食品生产经营的所有工作。表述过于绝对。' WHERE id = 'a7ee9edb-b9b7-4785-82cf-63c9c3e52bb8';
UPDATE public.questions SET analysis = '依据GB 14880《食品营养强化剂使用标准》，钙、锌、镁不能用于糖果（胶基糖果除外）的矿物质强化，铁可以按规定使用。' WHERE id = 'a7f35fc9-5490-4f1f-acdb-33841a4a9065';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产企业选择生产场所时，应与有毒、有害场所以及其他污染源保持规定的距离；具有与生产的食品品种、数量相适应的食品原料处理、加工、包装、贮存场所。与供货商距离无关。' WHERE id = 'a7fb1b8f-f971-4ddb-8c22-4a4c3d5a3851';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》及《企业落实食品安全主体责任监督管理规定》要求，餐饮服务提供者可以自行开展食品安全自查，也可以委托第三方专业机构开展，并非''必须''委托第三方。' WHERE id = 'a7fb2583-3d45-4530-990e-8645828ac065';
UPDATE public.questions SET analysis = '龙井茶是中国十大名茶之一，产于浙江杭州西湖一带，属于绿茶类，具有''色绿、香郁、味甘、形美''四绝。' WHERE id = 'a7fe116e-80ed-4430-be0a-b877227e20d1';
UPDATE public.questions SET analysis = 'GB 14881《食品生产通用卫生规范》及《餐饮服务食品安全操作规范》要求，食品生产经营企业应合规使用清洁剂、消毒剂等化学品，非必要不在生产经营场所使用和存放可能污染食品的化学制剂。' WHERE id = 'a8033089-609c-4296-8864-c42c05e55b9b';
UPDATE public.questions SET analysis = '《食品安全法》第六十八条规定，散装食品标识应当标明食品的名称、生产日期、保质期、生产者经营者名称及联系方式等内容。' WHERE id = 'a8044074-8b85-4fd2-82e4-a2cb31b1dc80';
UPDATE public.questions SET analysis = '《食品安全法实施条例》及《企业落实食品安全主体责任监督管理规定》要求，食品生产经营企业应通过风险信息收集、风险排查等预防措施防止或消除食品危害，建立风险防控体系。' WHERE id = 'a80c2e97-33d0-42d1-9e80-c2e60845892a';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，监督抽检中的样品分为检验样品和复检备份样品，以满足检验和复检的需要。复检备份样品由被抽样单位或抽样单位妥善保存。' WHERE id = 'a81baf75-f25e-44eb-9ac8-033bfe16b9b3';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，冷荤类食品制售、冷加工糕点制售、生食类食品制售应设置专间；热食类食品制售可不设专间。专间设置针对高风险冷食类操作。' WHERE id = 'a829ce92-905b-4758-be0f-9702603c0174';
UPDATE public.questions SET analysis = 'GB 14881《食品生产通用卫生规范》8.4.3规定，应采取设置筛网、捕集器、磁铁、金属检查器等装置，降低原料、设备、人员在加工过程中带入的金属或其他异物污染食品的风险。' WHERE id = 'a85f9c58-dde5-46d3-a8a1-ebdb9af0289f';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》及《学校食品安全与营养健康管理规定》要求，中央厨房、集体用餐配送单位、集中用餐单位食堂和从事食品经营管理的企业还应建立原料供货商管理评价制度以及退出机制。' WHERE id = 'a8634d13-174c-417d-b39f-c5bcba6aaca9';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第二十六条规定，食品经营者应当在经营场所的显著位置悬挂或摆放食品经营许可证正本，便于监督检查和消费者知晓。' WHERE id = 'a872abf0-a66d-4a04-9341-2aaaaeb2c20f';
UPDATE public.questions SET analysis = '《食品安全法》第一百零二条规定，食品生产企业应当制定食品安全事故处置方案，定期检查本企业各项食品安全防范措施的落实情况，及时消除事故隐患。' WHERE id = 'a88cd35a-3101-4eb7-a776-043ebcf2cf6a';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，市场监督管理部门应通过政府网站等媒体及时向社会公开监督抽检结果和不合格食品核查处置的相关信息，并记入食品生产经营者信用档案。' WHERE id = 'a8ae828f-dd9e-4eb6-bcd0-abaa4ad10d3b';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十五条规定，因食品安全犯罪被判处有期徒刑以上刑罚的人员，终身不得担任食品安全总监、食品安全员等食品安全管理人员。' WHERE id = 'a8b565a4-d1eb-4541-9138-8a09aed9e583';
UPDATE public.questions SET analysis = '《食品安全法》第十四条规定，国家建立食品安全风险监测制度，对食源性疾病、食品污染以及食品中的有害因素进行监测。' WHERE id = 'a8bc6ab1-ac47-4549-87a6-aa8701128007';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第二十九条规定，食品经营者需要延续依法取得的食品经营许可有效期的，应当在该食品经营许可有效期届满30个工作日前向原发证部门提出申请。' WHERE id = 'a8c0d681-b86e-443a-808f-6dc38ad8fc2d';
UPDATE public.questions SET analysis = '《行政处罚法》第三十二条规定，当事人主动消除或减轻违法行为危害后果、受他人胁迫有违法行为、配合行政机关查处违法行为有立功表现等情形的，应当依法从轻或减轻行政处罚。' WHERE id = 'a8c7b09c-1862-4c3b-877e-0a00fe23a1cf';
UPDATE public.questions SET analysis = 'GB 14881《食品生产通用卫生规范》8.1.1规定，鼓励采用危害分析与关键控制点（HACCP）体系对生产过程进行食品安全控制，建立完善的食品安全管理体系。' WHERE id = 'a8c8d725-6bf5-4792-8899-6745a9014f70';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第十四条规定，抽样人员应经培训合格后开展抽样工作，由至少2名抽样人员出示抽样检验告知书及有效身份证明文件后进行抽样。' WHERE id = 'a8d0fd7c-715e-43aa-9ae8-185e6ca4d22c';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》规定，特殊医学用途配方食品注册证书有效期届满需延续的，应在有效期届满6个月前向国家市场监督管理总局提出延续注册申请。' WHERE id = 'a8d499e5-843d-4151-8510-07a1594ad039';
UPDATE public.questions SET analysis = '《食品安全法》及GB 2760《食品添加剂使用标准》规定，食品添加剂在规定的使用范围和限量内使用是安全的。食品添加剂经过严格的安全评估，合规使用不会对人体健康造成危害。' WHERE id = 'a8d5a6a2-2b2c-4880-83d1-b5bf720dc516';
UPDATE public.questions SET analysis = '《食品生产经营风险分级管理办法》规定，风险分级管理以风险分析为基础，结合食品生产经营企业风险特点，确定食品生产经营者风险等级，从低到高分为A、B、C、D四个等级。' WHERE id = 'a8e604ad-3845-4307-bc01-02f5bcfab77b';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第七十五条规定，直接负责的主管人员是指在违法行为中负有直接管理责任的人员，包括食品安全总监等企业管理人员，实行''双罚制''追究责任。' WHERE id = 'a8e905bf-4e1b-4c6e-b637-c940773e576f';
UPDATE public.questions SET analysis = 'GB 7718《预包装食品标签通则》4.1.3.1.5规定，在加工过程中已挥发的水或其他挥发性配料不需要标示。如饼干中的水分在烘焙过程中已蒸发，无需在配料表中标示。' WHERE id = 'a8fea0a9-025f-4c1a-b838-11680c48b57e';
UPDATE public.questions SET analysis = '《网络食品安全违法行为查处办法》第十五条规定，网络食品交易第三方平台发现入网食品经营者有涉嫌食品安全犯罪、被判刑罚、被公安机关拘留或治安管理处罚、被吊销许可证等严重违法行为的，应立即停止提供网络交易平台服务。' WHERE id = 'a9364197-eb6f-4ab3-b5b0-e7fc8f4bb856';
UPDATE public.questions SET analysis = '手工面的基本生产工艺为：调粉→熟化→搓条→拉吊→干燥→截断→称量→包装。拉吊是手工面制作特有的工序，形成面条的细长形状和独特口感。' WHERE id = 'a9371963-c602-4884-a24a-95d42ede64dc';
UPDATE public.questions SET analysis = '《食品中可能违法添加的非食用物质和易滥用的食品添加剂名单》由原卫生部及后续相关部门发布，食品生产经营环节应坚决杜绝违法添加名单中的物质，确保食品安全。' WHERE id = 'a9536a26-9f1c-44e3-b5db-396b98b67ff9';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止生产经营无标签的预包装食品、以病死肉类为原料的食品、以回收食品为原料生产的食品。以按照传统既是食品又是中药材的物质为原料生产的食品是合法的。' WHERE id = 'a9582a1f-11d6-4ff1-a0b5-4779c8a7dbd9';
UPDATE public.questions SET analysis = '依据GB 2762《食品中污染物限量》，苹果干中铅的限量为0.5mg/kg。水果干制品的污染物限量应严格符合国家标准要求。' WHERE id = 'a969f911-407a-4934-94de-e7f85b5c7e33';
UPDATE public.questions SET analysis = '水果制品的原料及生产加工过程中受到微生物污染，可导致菌落总数、霉菌等微生物超标。依据GB 14881，应加强原料验收和生产过程卫生控制，防止微生物污染。' WHERE id = 'a988b072-4bba-4966-bd72-bcd9504eca9c';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，复检费用包括检验费用和样品递送产生的相关费用，由申请人先行支付，复检结论表明食品不合格的由申请人承担，合格的由实施抽样检验的市场监督管理部门承担。' WHERE id = 'a99d3da2-cbed-4b7f-85ce-56ca39975f67';
UPDATE public.questions SET analysis = 'GB 19300《食品安全国家标准 坚果与籽类食品》规定，带壳产品的霉变粒限量因产品类型而异，一般≤0.5%至2%不等，具体应按标准中不同产品的规定执行。' WHERE id = 'a9b9aa22-243f-43c4-9d5c-816f5f136ff4';
UPDATE public.questions SET analysis = '《食品生产经营日常监督检查管理办法》规定，食品生产企业应将张贴的日常监督检查结果记录表保持至下次日常监督检查，便于消费者查阅和监督。' WHERE id = 'a9d57860-4158-4b16-a21c-09d4e9e2c711';
UPDATE public.questions SET analysis = '再制蛋（如皮蛋、咸蛋等）加工过程中，反复使用的料液应定期检测，防止料液中盐分、碱度等指标偏离工艺要求，影响产品质量和安全。' WHERE id = 'a9dffd0a-b475-4668-8c92-91d5d4ce9768';
UPDATE public.questions SET analysis = 'GB 7718《预包装食品标签通则》3.8.2规定，预包装食品标签可同时使用外文，但所用外文字号不得大于相应的汉字字号，确保中文信息的突出地位。' WHERE id = 'a9f09593-36bf-4a14-99c6-8010dc86556d';
UPDATE public.questions SET analysis = 'GB 7718《预包装食品标签通则》4.1.5.1规定，净含量的标示应由净含量、数字和法定计量单位组成（如''净含量：500克''）。成分不属于净含量标示的组成部分。' WHERE id = 'a9f9b793-3d34-4f2e-b640-5b8c479d9833';
UPDATE public.questions SET analysis = '《食品安全法》第一百零三条规定，食品安全事故发生单位应当及时向事故发生地县级人民政府卫生健康部门和 market 监督管理部门报告，不得隐瞒、谎报、缓报。' WHERE id = 'aa23a577-091c-4237-8147-806af3b203b0';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》第十二条规定，受理机构对申请材料不齐全或不符合法定形式的，应当当场或在5个工作日内一次告知申请人需要补正的全部内容。' WHERE id = 'aa2afd6d-81bb-4ad6-b2d7-da652547ef36';
UPDATE public.questions SET analysis = '《食品安全法》第五十条规定，食品原料、食品添加剂、食品相关产品进货查验记录应当真实，保存期限不得少于产品保质期满后6个月；没有明确保质期的，保存期限不得少于2年。原题答案为2年。' WHERE id = 'aa3a770f-df1b-4848-95d7-371f86137c3b';
UPDATE public.questions SET analysis = '酒类产品的重要安全指标包括：污染物限量（GB 2762）、致病菌限量（发酵酒适用GB 29921）、真菌毒素限量（如山楂酒适用GB 2761）、食品添加剂使用（GB 2760）等。' WHERE id = 'aa3dd00d-e68d-4bd9-9f4d-e0864b043234';
UPDATE public.questions SET analysis = '方便食品产品配方和执行标准管控中，应明确产品在GB 2760中的食品类别定位，进行食品添加剂合规性审查，确定可使用的食品添加剂品种和最大使用量，防止超范围超限量使用。' WHERE id = 'aa47ea6a-5f2f-46f7-bf46-90b4566c81e7';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十五条规定，被吊销许可证的食品生产经营者及其法定代表人、直接负责的主管人员和其他直接责任人员自处罚决定作出之日起五年内不得申请食品生产经营许可，原题''三年内''表述有误。' WHERE id = 'aa48c68c-2c9d-4933-880e-61ba3873452e';
UPDATE public.questions SET analysis = '依据GB 2760及生产管理要求，水果制品生产企业应对食品添加剂称量设备进行校准，确保称量准确，防止因称量偏差导致食品添加剂超量使用。' WHERE id = 'aa87e643-7e95-4c70-b670-10a21275bf21';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，食品生产经营者对召回的食品应采取无害化处理、销毁等措施，防止其再次流入市场。对责令召回或停止经营仍拒不执行的，可依据第124条查处。' WHERE id = 'aab21315-8dfb-49e6-9ae1-cd7da80d97d9';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，保健食品经营企业进货查验记录和凭证保存期限不得少于产品保质期满后6个月。' WHERE id = 'aac19e0f-22f6-4bd9-a6b5-97ec892f71ba';
UPDATE public.questions SET analysis = '《农产品质量安全法》规定，经检测不符合农产品质量安全标准的农产品，应及时采取管控措施，不得销售，应依法进行无害化处理或销毁。' WHERE id = 'aad3ff9e-ac0a-4776-afa8-e1dca6496c9a';
UPDATE public.questions SET analysis = '《食品安全法》第一百四十八条规定，接到消费者赔偿要求的食品生产企业，应当实行首负责任制，先行赔付，不得推诿。属于生产者责任的，经营者赔偿后有权向生产者追偿。' WHERE id = 'aadc4c87-0e9c-4441-95e5-d227991d4c17';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，加工制作即食食品（如切即食牛肉）时从业人员应佩戴口罩，防止飞沫污染。处理生食品时戴口罩要求相对宽松。' WHERE id = 'aae39b1c-8f26-4bd3-b0a7-8379134a99db';
UPDATE public.questions SET analysis = '对生物性危害的防控措施包括对微生物的控制（如温度、时间控制）、对寄生虫的控制（如冷冻处理）、对虫害的控制（如防虫设施）、对真菌及真菌毒素的控制（如原料筛选、防潮）等。' WHERE id = 'aaeffd81-6e72-45d0-b66f-6ac5937ef98a';
UPDATE public.questions SET analysis = 'GB 2758《食品安全国家标准 发酵酒及其配制酒》规定，啤酒是以麦芽、水为主要原料，加啤酒花（包括酒花制品），经酵母发酵酿制而成的、含有二氧化碳的、起泡的低酒精度发酵酒。' WHERE id = 'aaf0c47c-cff3-4031-9aa2-1d96b7fe7c8f';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食品安全事故指食源性疾病、食品污染等源于食品，对人体健康有危害或者可能有危害的事故。' WHERE id = 'aaf7c7e9-d977-4a25-95e1-06b085ffda5a';
UPDATE public.questions SET analysis = '《食品安全法》第三十五条规定，从事散装食品销售和餐饮服务，应当依法取得食品经营许可。仅销售预包装食品的实行备案管理，食品运输不需要食品经营许可。' WHERE id = 'aafa1b0b-54a2-4eaa-bb0e-616a9cd690b6';
UPDATE public.questions SET analysis = '真菌毒素超标易导致食物中毒、致病、致癌，与食源性疾病密切相关。黄曲霉毒素、脱氧雪腐镰刀菌烯醇等真菌毒素是重要的食源性危害因素。原题表述有误。' WHERE id = 'aafb1525-14a1-4044-91bc-9cd77d7363b8';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》及企业标准备案管理要求，食品生产企业对报备的企业标准负责，是企业标准的第一责任人，应确保企业标准严于食品安全国家标准或地方标准。' WHERE id = 'ab007f0f-49a8-4e71-a3dc-9891548660c0';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，销售无包装的直接入口食品时，应当使用无毒、清洁的容器、售货工具和设备，确保食品安全。' WHERE id = 'ab05f479-d674-45a7-935d-d17f0c718c14';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，列入其他类食品销售和其他类食品制售的具体品种应当报省级食品药品监督管理部门批准后执行，而非国家食品药品监督管理总局。' WHERE id = 'ab1b762e-fe79-4521-837e-8e0ce227fa4b';
UPDATE public.questions SET analysis = 'GB 14881《食品生产通用卫生规范》7.2.2规定，食品添加剂应专柜存放、专人管理，不得与其他原辅材料混放，防止交叉污染和误用。' WHERE id = 'ab35ce2b-f50a-41a9-b38f-bd90298ff471';
UPDATE public.questions SET analysis = '《乳品质量安全监督管理条例》规定，乳制品生产企业不得向未取得生鲜乳收购许可证的单位和个人购进生鲜乳，确保奶源安全可追溯。' WHERE id = 'ab463cc8-e880-4ea2-bf49-5a27ca113a3c';
UPDATE public.questions SET analysis = 'GB/T 20821《液态法白酒》及白酒生产许可相关规定允许液态法白酒使用食用酒精作为原料。白酒按生产工艺分为固态法、液态法和固液法白酒。' WHERE id = 'ab4b61a3-437f-4a1d-bb9a-46f3cb8c7140';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，食品安全抽样检验可以由市场监督管理部门自行抽样，也可以委托具有法定资质的承检机构进行抽样。' WHERE id = 'ab57902b-4b7c-4b6c-8e19-fcdea9ee80e0';
UPDATE public.questions SET analysis = 'GB 2719《食品安全国家标准 食醋》规定，食醋中总酸含量应≥3.50g/100mL。总酸是食醋的重要质量指标，反映产品的发酵程度和品质。' WHERE id = 'ab8523d3-1ab4-433a-8929-64881519bb5c';
UPDATE public.questions SET analysis = '可可制品包括可可液块、可可脂、可可粉等。巧克力是以可可制品为主要原料添加糖等制成的糖果制品，不属于可可制品的生产许可范围。' WHERE id = 'ab989d15-cc5e-436d-ae62-1e4b5cdf2f95';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营者采购进口食品应查看海关出具的入境货物检验检疫证明，并确保每一批次货证相符。不逐批次查验属于违法行为。' WHERE id = 'ab98eeb0-0f12-490c-88fd-cd950bfaed40';
UPDATE public.questions SET analysis = '《食品安全法》第一百一十四条规定，食品生产过程中存在食品安全隐患未及时采取措施消除的，县级以上人民政府食品安全监督管理部门可以对食品生产企业法定代表人或主要负责人进行责任约谈。' WHERE id = 'aba75a42-7e12-4606-88f6-2604d62ebd14';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，需要对召回的食品进行无害化处理、销毁的，应当提前报告时间、地点，食品安全监督管理部门认为必要的可以实施现场监督。原题''事后报告''表述有误。' WHERE id = 'abaa5364-c9e1-4aac-b879-4019e21ae1e0';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营者采购食品应当查验供货者的许可证和食品出厂检验合格证或者其他合格证明。' WHERE id = 'abae623d-0c1c-4b0d-bf72-f2b2314e1080';
UPDATE public.questions SET analysis = '蜜饯属于水果制品，其污染物限量应符合GB 2762《食品中污染物限量》的规定。GB 2760是食品添加剂标准，GB 2761是真菌毒素标准，GB 2763是农药残留标准。' WHERE id = 'abc8d8e4-b347-4af5-a2f4-d7a60d259308';
UPDATE public.questions SET analysis = 'GB 14881《食品生产通用卫生规范》4.1.1规定，厂房和车间的内部设计和布局应满足食品卫生操作要求，避免食品生产中发生交叉污染。' WHERE id = 'abf3101e-a0ef-4c9c-b047-c8475d452dc9';
UPDATE public.questions SET analysis = '《网络餐饮服务食品安全监督管理办法》第五条规定，网络餐饮服务第三方平台提供者应当在通信主管部门批准后30个工作日内，向所在地省级食品药品监督管理部门备案。' WHERE id = 'ac2103c7-3d19-45ce-8e60-afb71e2ddeb3';
UPDATE public.questions SET analysis = '《食品安全法》第八条规定，县级以上地方人民政府实行食品安全监督管理责任制，统一领导、组织、协调本行政区域的食品安全监督管理工作。' WHERE id = 'ac283500-5d60-4d0f-8e04-0554d9daa82a';
UPDATE public.questions SET analysis = '《食品安全法》及《企业落实食品安全主体责任监督管理规定》明确，食品企业标准是由食品企业自身制定，由企业法人代表或其授权人批准、发布的食品安全标准。' WHERE id = 'ac32bfda-6a1b-4d98-8746-a856f05baad3';
UPDATE public.questions SET analysis = '《农产品质量安全法》第三十四条规定，农产品销售企业应当建立健全进货检查验收制度，查验农产品产地证明、检测报告等合格证明文件。' WHERE id = 'ac3a38e3-174e-405a-853c-0db0e20b5aa2';
UPDATE public.questions SET analysis = '《食品安全法》第四条规定，食品生产经营者对其生产经营食品的安全负责，应当依照法律、法规和食品安全标准从事生产经营活动，保证食品安全，诚信自律，对社会和公众负责，接受社会监督，承担社会责任。' WHERE id = 'ac3b1ed4-6cde-4922-8c08-69d72eb8d88e';
UPDATE public.questions SET analysis = '《食品安全法》及GB 14881规定，食品生产企业应严控原料来源，通过严格进货查验降低采购的食品原料、食品添加剂和食品包装材料等自身的微生物危害风险。' WHERE id = 'ac3f8612-61e4-42b9-9953-f44956de5eb8';
UPDATE public.questions SET analysis = '《食品安全法》第一百零八条规定，任何单位或者个人不得阻挠、干涉食品安全事故的调查处理，确保事故调查依法顺利进行。' WHERE id = 'ac51e170-8238-46fb-b3a8-91c35acc383c';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，食品生产者发现其生产的食品不符合食品安全标准或有证据证明可能危害人体健康的，应当立即停止生产，召回已经上市销售的食品。食品生产者认为应当召回的食品应当立即召回。' WHERE id = 'ac5282ac-aad7-4aad-b994-befd6d0db56c';
UPDATE public.questions SET analysis = 'GB 2712《食品安全国家标准 豆制品》规定，豆制品的污染物限量应符合GB 2762，真菌毒素限量应符合GB 2761，致病菌限量应符合GB 29921，食品添加剂使用应符合GB 2760。' WHERE id = 'ac692ec4-7ecc-452d-a61b-725361bebb73';
UPDATE public.questions SET analysis = '《网络食品安全违法行为查处办法》第十七条规定，入网食品经营者不得网上刊载的食品名称与标签标识不一致、非保健食品信息明示或暗示保健功能、对有特殊贮存要求的食品未予以说明或提示等违法行为。' WHERE id = 'ac696c84-7b3e-4ad9-9494-de2dcbcf3223';
UPDATE public.questions SET analysis = 'GB 7718《预包装食品标签通则》4.1.5.7规定，同一预包装内含有多个单件预包装食品时，大包装应标示净含量和规格。' WHERE id = 'ac6fed93-146d-4b29-b681-c23a7c96abc1';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，用容器盛放开封后的食品添加剂的，应在容器上标明食品添加剂名称、生产日期或批号、使用期限等信息，并保留食品添加剂原包装。' WHERE id = 'ac7df5aa-c22e-4816-9305-22418f88656e';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第三十九条规定，普通食品与特殊食品之间、与药品之间应当有明显的隔离标识或保持一定距离摆放，不得混放销售，防止误导消费者。' WHERE id = 'ac8b8ce4-9542-44c1-8d52-183abcb97592';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品进货查验记录和相关凭证的保存期限不得少于产品保质期满后6个月；没有明确保质期的，保存期限不得少于2年。原题''一年''表述有误。' WHERE id = 'aca621c2-f5ca-40ec-9818-e0932e46582e';
UPDATE public.questions SET analysis = '《学校食品安全与营养健康管理规定》要求，学校进货查验记录和相关凭证保存期限不得少于产品保质期满后6个月。' WHERE id = 'acb76a4d-02d4-4fed-9d3f-ff85701b29ed';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第四条规定，食品经营许可实行一地一证原则，即食品经营者在一个经营场所从事食品经营活动，应当取得一个食品经营许可证。' WHERE id = 'acbd5fc9-5210-447c-a0b1-ff0e6e08e3fa';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营者申请许可，应当具有专职或兼职的食品安全专业技术人员和食品安全管理人员。' WHERE id = 'acc5f28d-b1b1-49cc-bb33-a4eeb435a71a';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》2.10规定，集中用餐单位食堂指设于机关、事业单位、社会团体、民办非企业单位、企业等，供应内部职工、学生等集中就餐的餐饮服务提供者。' WHERE id = 'acf67278-aa96-4620-8b1e-e633b2abdfcd';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》第十三条及《食品生产许可审查通则》规定，申请人委托他人办理食品生产许可申请的，代理人应当提交授权委托书以及代理人的身份证明文件。' WHERE id = 'ad0234d6-aa9b-474f-a394-ea462fb492c7';
UPDATE public.questions SET analysis = '可可制品的食品生产许可范围包括可可液块、可可脂、可可粉。可可酱不属于可可制品的标准分类，未纳入可可制品的食品生产许可范围。' WHERE id = 'ad15378a-8c7b-4bc2-b6c2-5fdecb45f3ea';
UPDATE public.questions SET analysis = '《乳品质量安全监督管理条例》第二条规定，乳制品是指使用乳（生乳、复原乳等）为主要原料，经加工制成的产品。生乳本身不属于乳制品，题中表述不准确。' WHERE id = 'ad16361b-933a-44e3-8d07-e8aa58a3916c';
UPDATE public.questions SET analysis = '压片糖果属于普通食品，不得添加保健食品原料进行生产销售。保健食品原料目录中的物质仅可用于保健食品生产，不得用于普通食品。' WHERE id = 'ad28cac4-c147-4410-924f-d4c9cb18c24b';
UPDATE public.questions SET analysis = '《食品安全法》第一百一十三条规定，县级以上人民政府食品安全监督管理部门应当建立食品生产经营者食品安全信用档案，对有不良信用记录的食品经营者应增加监督检查频次。' WHERE id = 'ad2ca073-6040-4dc0-a603-f2a047b622dd';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》未要求所有从业人员必须配戴手套加工食品。接触直接入口食品时应配戴清洁的手套或洗净消毒手部即可，并非''必须''戴手套。' WHERE id = 'ad352c14-de1e-495f-a706-50123d9f5da6';
UPDATE public.questions SET analysis = '《食品安全法》第一百零二条规定，发生食品安全事故潜在风险的，应立即停止食品生产经营活动，并向所在地县级以上食品安全监督管理部门报告。' WHERE id = 'ad458ac1-5f72-4665-929f-2e4eeeb0e35d';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，食品生产经营者应在食品安全抽样文书上签字或盖章，确认抽样过程合法合规。' WHERE id = 'ad55700d-7109-456c-b399-7c6fdce6c1d9';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》第三十二条规定，食品生产许可证副本载明的同一食品类别内的事项发生变化，应向原发证部门报告。猪油和鸡油同属食用动物油脂，向原发证部门报告即可。' WHERE id = 'ad5c4283-c5d5-4830-bdcd-33684b21f0ca';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，食品生产经营企业应当建立并执行从业人员健康管理制度，组织从业人员每年进行健康检查，取得健康证明后方可上岗。' WHERE id = 'ad603366-58d3-4d01-a2e8-45f69888a500';
UPDATE public.questions SET analysis = 'GB 17323《瓶装饮用纯净水》及GB 5749《生活饮用水卫生标准》规定，饮用纯净水的生产用源水水质应符合GB 5749的规定，可使用公共供水系统或非公共供水系统的地表水或地下水。' WHERE id = 'ad60edf3-3e8a-4356-8a9c-96d677dd7a7f';
UPDATE public.questions SET analysis = 'GB 14881《食品生产通用卫生规范》5.1.1.2规定，食品加工用水（包括制冰用水）的水质应符合GB 5749的规定。清洗地面用水、设备冷却水、厕所用水不需要符合GB 5749。' WHERE id = 'ad70bf0f-f0c9-4092-ba4d-bfc68da0ca74';
UPDATE public.questions SET analysis = '《食品安全法》及GB 14881规定，食品生产经营企业可通过严格原料进货查验（或检验），避免从污染区域采购原料等措施，降低原料带来的化学性危害风险。' WHERE id = 'ad739ce9-85d0-416e-9019-97c5bf8c8073';
UPDATE public.questions SET analysis = 'GB 2712《食品安全国家标准 豆制品》适用于以大豆或杂豆为主要原料制成的豆制品，不包括大豆蛋白粉。大豆蛋白粉属于其他食品类别。' WHERE id = 'ad79c461-c17b-44b8-bef9-fa9e44cc39df';
UPDATE public.questions SET analysis = '《中华人民共和国标准化法》第十一条规定，对满足基础通用、与强制性国家标准配套、对各有关行业起引领作用等需要的技术要求，可以制定推荐性国家标准。' WHERE id = 'ad82c0fe-d309-4c17-a81f-08a50f4ef162';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，餐饮服务场所、设施、设备应定期维护，出现问题及时维修或更换，确保设施设备正常运转和食品安全。' WHERE id = 'ad9735fb-9688-4868-b08f-5d42b072024c';
UPDATE public.questions SET analysis = '食品工业用浓缩乳生产工艺包括热浓缩（如蒸发浓缩）和非热浓缩（如膜过滤浓缩）两种方式，具体选择取决于产品特性和工艺需求。' WHERE id = 'ad9c7db9-5465-4687-aa22-eaf6f6332d49';
UPDATE public.questions SET analysis = '《食品安全法》及《食品经营过程卫生规范》规定，直接接触直接入口散装食品的工具、容器和包装材料等应当具有符合食品安全标准的产品合格证明，确保安全无毒。' WHERE id = 'ad9d8e08-9168-4003-a2de-73fcaa111cbf';
UPDATE public.questions SET analysis = '天然肠衣的生产工艺包括刮制、上盐、腌渍等环节。上盐是天然肠衣加工的关键工序，用于防腐保存和定型。蒸煮、滚揉、发酵不属于天然肠衣的典型工艺。' WHERE id = 'adbd507c-74c8-492e-bda9-141bafb1e29d';
UPDATE public.questions SET analysis = '《食品安全法》第三十五条规定，国家对食品生产经营实行许可制度。从事食品生产、食品销售、餐饮服务，应当依法取得许可。' WHERE id = 'adc13f8d-9159-4634-ba49-d536b2cdd0c3';
UPDATE public.questions SET analysis = 'GB 2761《食品安全国家标准 食品中真菌毒素限量》规定了葡萄酒中赭曲霉毒素A等真菌毒素的限量。GB 2760是食品添加剂标准，GB 2762是污染物标准，GB 2763是农药残留标准。' WHERE id = 'adc6e432-411d-4fbf-80f5-b450a38b8d36';
UPDATE public.questions SET analysis = 'GB 14881《食品生产通用卫生规范》规定，对食品添加剂以及清洁剂、消毒剂、润滑剂等明确标示、分类管理、妥善保存，可有效防范加工过程中带来的化学性危害。' WHERE id = 'adcf4995-8df1-4e65-a3ba-c05bc28e4b6e';
UPDATE public.questions SET analysis = '《食品安全法》第五十一条规定，食品生产企业应建立食品出厂检验记录制度，查验出厂食品的检验合格证和安全状况。未经检验合格的产品不得出厂销售。' WHERE id = 'adf027a7-fa6d-432f-9935-10eb62558bad';
UPDATE public.questions SET analysis = 'GB 7718《预包装食品标签通则》4.1.2.1.2规定，无国家标准、行业标准或地方标准规定的名称时，应使用不使消费者误解或混淆的常用名称或通俗名称。' WHERE id = 'ae085582-3f83-48a7-ba01-8a4d92b88c43';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》第十二条规定，负责现场核查的机构应自接到审评机构通知之日起20个工作日内完成对申请人的研发能力、生产能力、检验能力等情况的现场核查。' WHERE id = 'ae099af9-e59c-4c04-9108-2b3e9d87553b';
UPDATE public.questions SET analysis = '《学校食品安全与营养健康管理规定》要求，有条件的中小学、幼儿园应当每周公布学生餐带量食谱和营养素供给量，接受家长和社会监督。' WHERE id = 'ae1e3019-1aca-4f25-8ca1-cc097f1f564b';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，食品生产经营企业应按照食品安全法律法规、规章、标准和规范性文件，建立相关食品安全管理制度，落实企业食品安全主体责任。' WHERE id = 'ae2b5957-4217-4124-a6b2-b954ba2a1917';
UPDATE public.questions SET analysis = '《农产品质量安全法》及《野生动物保护法》规定，食用农产品不包括法律法规禁止食用的野生动物产品及其制品。禁止食用野生动物是维护公共卫生安全的重要举措。' WHERE id = 'ae2cadcd-e7dc-4d07-8b52-6889d12bb449';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，配送过程中，原料、半成品、成品、食品包装材料等应使用容器或独立包装等进行分隔，包装应完整、清洁，防止交叉污染。' WHERE id = 'ae30842d-5869-4537-91f6-d10bc158facd';
UPDATE public.questions SET analysis = '保健食品经营者采购保健食品时，应查验并索取《保健食品批准证书》（或注册凭证）和产品检验合格证复印件，确保产品来源合法、质量合格。' WHERE id = 'ae3ed9d6-c76a-4844-8bdf-1747af2c6478';
UPDATE public.questions SET analysis = 'GB 2749《食品安全国家标准 蛋与蛋制品》规定，蛋制品是以禽蛋为原料，经加工制成的产品。蛇蛋、乌龟蛋、人造蛋均不属于蛋制品的标准定义范围。' WHERE id = 'ae49dc1d-eace-4065-b5f0-38155e38557b';
UPDATE public.questions SET analysis = 'GB 7100《食品安全国家标准 饼干》及生产实际表明，饼干可以添加奶油、巧克力等配料制作不同口味和品种。奶油饼干、巧克力饼干是常见的饼干品种。' WHERE id = 'ae6a5059-503a-4dce-aeec-5ec06d2fcf3c';
UPDATE public.questions SET analysis = 'GB 7096《食品安全国家标准 食用菌及其制品》规定，食用菌制品包括干制食用菌制品、腌制食用菌制品、即食食用菌制品、速冻食用菌制品等。' WHERE id = 'ae7240d6-704b-4dd0-b782-8f074c9ec5f2';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，从事接触直接入口食品工作的食品生产经营人员应当每年进行健康检查，取得健康证明后方可上岗工作。' WHERE id = 'ae75151e-ea10-43f1-b77d-840c54df721e';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》及GB 14881要求，食品生产经营企业应建立防止化学性污染的管理制度，分析可能的污染源和污染途径，制定适当的控制计划和控制程序。' WHERE id = 'ae7f0b40-0773-4c13-8ddf-468babdb02fc';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止生产经营用非食品原料生产的食品。食品生产企业不得采购非食用物质作为生产加工物料。' WHERE id = 'ae7f398a-39c6-4bc2-9ec1-d7d3fe71fa28';
UPDATE public.questions SET analysis = '水果制品中食品添加剂的使用应符合GB 2760《食品安全国家标准 食品添加剂使用标准》的规定。GB 2762是污染物标准，GB 2761是真菌毒素标准，GB 2763是农药残留标准。' WHERE id = 'ae8dfe5c-0918-4c9e-a78f-8bf4b7acb367';
UPDATE public.questions SET analysis = 'GB 14881《食品生产通用卫生规范》及水产品加工规范要求，贝类在加工前应进行贝类净化处理，去除体内毒素和污染物。原题表述为''错''可能有误，贝类净化是必要工序。' WHERE id = 'ae9dab80-b788-4941-8332-4a7d117fdaed';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》第二十四条规定，食品生产许可证有效期为5年。有效期届满需继续生产的，应在有效期届满前申请延续。' WHERE id = 'aea207e5-fba5-4b75-9221-fcd425cfcb58';
UPDATE public.questions SET analysis = 'GB 13432《食品安全国家标准 预包装特殊膳食用食品标签》定义，特殊膳食用食品是指为满足特殊的身体或生理状况和（或）满足疾病、紊乱等状态下的特殊膳食需求，专门加工或配方的食品。' WHERE id = 'aea32fe9-c66b-4f1d-b679-a1db5f0dd029';
UPDATE public.questions SET analysis = 'GB 26687《食品安全国家标准 复配食品添加剂通则》规定，该标准不适用于食品用香精。食品用香精另有GB 30616标准进行管理。' WHERE id = 'aeaa41d4-a571-4594-a905-4f7a4a28da05';
UPDATE public.questions SET analysis = 'GB 2715《食品安全国家标准 粮食》规定，大豆霉变粒≤1.0%。霉变粒是反映粮食品质的重要指标，应严格控制。' WHERE id = 'aeaca581-273f-46d3-aceb-f99126e656ad';
UPDATE public.questions SET analysis = '《食品生产经营风险分级管理办法》规定，食品生产经营者的风险等级从低到高分为A级风险、B级风险、C级风险、D级风险四个等级。原题''从高到低''表述有误。' WHERE id = 'aeba97be-9088-4d4e-ac73-36d63ffd9a86';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》明确，食品安全管理人员监督抽查考核不得收取费用，由市场监督管理部门组织实施。' WHERE id = 'aecabda2-3408-49d7-8175-dc5354f0a66d';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条规定，患有国务院卫生行政部门规定的有碍食品安全疾病的人员，不得从事接触直接入口食品的工作。' WHERE id = 'aed898db-4ee7-4208-a6ad-1c4ae063d95c';
UPDATE public.questions SET analysis = '《中华人民共和国标准化法》第二十一条规定，推荐性国家标准、行业标准、地方标准、团体标准、企业标准的技术要求不得低于强制性国家标准的相关技术要求。' WHERE id = 'aedb1452-8a23-45d9-a2bd-40364ed26716';
UPDATE public.questions SET analysis = '现行《中华人民共和国食品安全法》于2021年4月29日经第十三届全国人民代表大会常务委员会第二十八次会议修订通过并施行，这是最新的修正版本。' WHERE id = 'aedcb29a-6277-4fa5-bae4-0f6e937cf862';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》规定，企业食品安全管理人员抽查考核不合格的，应在考核合格后方能任职，而非直接免去职务。原题表述有误。' WHERE id = 'aedd930f-8404-463d-9508-0d286a2585d0';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，食品生产经营者应依法配合市场监督管理部门组织实施的食品安全抽样检验工作，不得拒绝、阻挠或干涉抽样工作。' WHERE id = 'aeded1f8-e2de-4584-977d-1e6c72cd1d7a';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》4.2.1规定，从事冷荤类食品制售、冷加工糕点制售、生食类食品制售，以及中央厨房和集体用餐配送单位进行直接入口易腐食品的冷却和分装、分切操作的（封闭自动设备除外），应分别设置相应的专间。' WHERE id = 'aef46871-edb2-401c-9b57-22a8ad8da52e';
UPDATE public.questions SET analysis = 'GB 14881《食品生产通用卫生规范》6.5.1规定，车间内存放废弃物的设施和容器应标识清晰、易于清洁，不得与盛装原辅料的容器混用，防止交叉污染。' WHERE id = 'af02bfdc-a58b-422e-a4c9-b9bfb94ee78c';
UPDATE public.questions SET analysis = '《食品安全法》第三十五条规定，国家对食品生产经营实行许可制度。选项A"许可"正确。选项B备案适用于仅销售预包装食品的情形；选项C行业管理不是法定制度；选项D注册适用于特殊食品。' WHERE id = 'af0b522f-a640-4130-bb9d-914bf0600850';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》及相关法规和标准规定，本题正确答案为A。予以撤销是符合法律法规要求的正确选项。' WHERE id = 'af24e4cb-76d2-4efb-a2b8-caf698432318';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求企业建立基于食品安全风险防控的动态管理机制，制定食品安全风险管控清单，建立健全日管控、周排查、月调度工作制度和机制。' WHERE id = 'af37448a-18dc-455e-996b-4a577bcd9c12';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》及相关法规和标准规定，本题正确答案为D。推荐性国家标准是符合法律法规要求的正确选项。' WHERE id = 'af485b03-9b8e-44af-bb99-17d67304ce9e';
UPDATE public.questions SET analysis = '《食品安全法》第四十四条规定，食品生产经营企业应当建立健全食品安全管理制度，对职工进行食品安全知识培训，加强食品检验工作，依法从事生产经营活动。' WHERE id = 'af4ca2b4-f5b3-4842-b5ad-41dd8beaf23d';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》要求中央厨房应设有冷却和分装、分切直接入口易腐食品等的专间，在封闭的自动设备中操作的除外，以防止交叉污染。' WHERE id = 'af50bbe9-447c-4b26-9632-9324cd3ad645';
UPDATE public.questions SET analysis = '膨化食品蒸煮、揉练过程中应严格控制温度、时间和压力等关键工艺参数，以确保产品质量和食品安全。选项A、B、C正确。' WHERE id = 'af568fed-60ea-4133-a3b5-46b2dd197390';
UPDATE public.questions SET analysis = '根据《可可脂质量要求》（GB/T 20707-2021），可可脂出厂检验项目包括水分及挥发物、游离脂肪酸、皂化价等。细度不是可可脂的出厂检验项目。选项D正确。' WHERE id = 'af696a3d-681a-4473-b492-a26cf4909777';
