UPDATE public.questions SET analysis = '《食品安全法》第四条规定，食品生产经营者对其生产经营食品的安全负责，应依照法律法规和标准从事生产经营，保证食品安全，诚信自律，对社会公众负责。选项A、B、C、D均正确。' WHERE id = 'b9416123-394e-470c-8ded-2462bed6d0bc';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》及相关法规和标准规定，本题正确答案为A,B,D（选项A、选项B、选项D）。各选项均符合法律法规和相关标准的要求。' WHERE id = 'b949cb8b-32c0-4d03-8e33-68476dd1da0f';
UPDATE public.questions SET analysis = '代用茶产品主要食品安全风险包括农药残留超标、污染物超标、添加剂超量和使用非食品原料。选项A、B、C、D均正确。' WHERE id = 'b94d4fc2-ebb1-4e64-b2b0-77c04d4aec32';
UPDATE public.questions SET analysis = '食糖中污染物限量标准为GB 2762《食品安全国家标准 食品中污染物限量》。GB 2760为食品添加剂使用标准，GB 2761为真菌毒素限量，GB 2763为农药最大残留限量。选项C正确。' WHERE id = 'b94eb983-1c8f-4182-8eed-bd4576e9ca92';
UPDATE public.questions SET analysis = '食品添加剂既有人工合成的，也有天然的，如柠檬酸、维生素E等。《食品安全国家标准 食品添加剂使用标准》（GB 2760）中收录的食品添加剂包括天然和人工合成两大类。' WHERE id = 'b96bc6fc-52c0-4b0c-aa74-9f63d153c789';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》及相关法规和标准规定，本题正确答案为B。登载于变更信息中是符合法律法规要求的正确选项。' WHERE id = 'b97e4f49-9dc8-40ae-b151-d2f9f519d750';
UPDATE public.questions SET analysis = '《食品安全法》第四十条规定，食品添加剂的使用必须符合GB 2760的规定，按照规定的范围和限量使用，不能根据经验按需添加。选项B正确。' WHERE id = 'b981eff7-5052-4d76-a6be-cc17c2bb40be';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食品安全是指食品无毒、无害，符合应当有的营养要求，对人体健康不造成任何急性、亚急性或者慢性危害。选项B正确。' WHERE id = 'b982c4c8-5092-423a-8417-67ebeef29037';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》及相关法规规定，本判断题的表述错误。在生产经营场所配置纱帘、纱网、防鼠板、防蝇灯、风幕等装置，可不符合食品安全法律法规和标准要求。' WHERE id = 'b9a225d5-aa6f-4655-8f7b-158fd9681ca5';
UPDATE public.questions SET analysis = '《食品安全法》第九十七条规定，进口的食品添加剂应当有中文标签、中文说明书。标签、说明书应当符合本法及我国其他有关法律、行政法规的规定和食品安全国家标准的要求。' WHERE id = 'b9c79003-a7eb-4815-8100-28c08d8a50da';
UPDATE public.questions SET analysis = '根据《中华人民共和国食品安全法》及相关法规和标准规定，本题正确答案为A,B,C（选项A、选项B、选项C）。各选项均符合法律法规和相关标准的要求。' WHERE id = 'b9cdc953-f4b9-4969-a0a7-c7d2980b78af';
UPDATE public.questions SET analysis = '《食品安全法》第四十七条规定，发生食品安全事故潜在风险的，应当立即停止食品生产经营活动，并向所在地食品安全监督管理部门报告，不得继续生产经营。' WHERE id = 'b9d265aa-f8c5-4467-b03d-897cdcb8f7cf';
UPDATE public.questions SET analysis = '选A、B、C。依据《餐饮服务食品安全操作规范》及GB 14881，食品半成品、成品及清洁的餐用具暴露区域上方的天花板应能避免灰尘散落，结构上不利于冷凝水垂直下落。D选项专用保洁设施为封闭设施，不在此要求范围内。' WHERE id = 'b9eb7164-bff5-46c0-9d3e-c8c9f26cce50';
UPDATE public.questions SET analysis = '选A。依据《食品安全法》第四条，食品生产经营者对其生产经营食品的安全负责。食品生产经营者应当依照法律、法规和食品安全标准从事生产经营活动，保证食品安全，诚信自律，对社会和公众负责。B、C、D选项均为企业内部的特定岗位人员，而食品生产经营者是责任主体。' WHERE id = 'b9ef617f-8196-4254-b5b7-2ca71725506e';
UPDATE public.questions SET analysis = '错误。非传统食品安全风险虽具有随机性大、防控难度大的特点，但企业仍可通过制定食品防护计划（Food Defense Plan）进行预测和预防。《食品安全法》要求食品生产经营者建立食品安全风险防控体系，食品防护计划是其中的重要组成部分。' WHERE id = 'ba016b76-3633-44d4-a659-64c5782e7d7a';
UPDATE public.questions SET analysis = '选D。依据《食品经营许可和备案管理办法》第十三条，申请人应当对申请材料的真实性负责，并在申请书等材料上签名或者盖章。申请人包括企业、个体工商户、法人等各类申请主体。' WHERE id = 'ba0ca8e6-40dc-41ec-aa01-52c919041a7e';
UPDATE public.questions SET analysis = '选A、B、C。依据《食品召回管理办法》第八条，食品生产经营者发现其生产经营的食品属于不安全食品的，应当立即停止生产经营（A）、采取通知或公告方式告知相关方（B）、采取必要措施防控风险（C）。D选项主动停产停业过于笼统，非法定表述。' WHERE id = 'ba4bb97d-2893-4915-8e15-fe0f1c572f56';
UPDATE public.questions SET analysis = '选A。依据《食品安全法》第七十五条，保健食品原料目录和允许保健食品声称的保健功能目录，由国务院食品安全监督管理部门会同国务院卫生行政部门、国家中医药管理部门制定、调整并公布。' WHERE id = 'ba6109ce-cc41-490d-8569-6825d649c7fa';
UPDATE public.questions SET analysis = '选A。《标准化法》第十二条规定，对没有推荐性国家标准、需要在全国某个行业范围内统一的技术要求，可以制定行业标准。行业标准由国务院有关行政主管部门制定。' WHERE id = 'baa77f01-1465-4f0c-ac12-8c8fe6ba95d9';
UPDATE public.questions SET analysis = '选A。自产氮气未获得许可是饮料企业的典型许可风险点。根据《食品生产许可管理办法》，食品生产中使用的加工工艺及原料（包括自产气体）应纳入许可范围，未取得相应许可即生产属于违法行为。' WHERE id = 'bab32d81-4eb0-4dcd-899b-0058ec506048';
UPDATE public.questions SET analysis = '选A、B、C、D。依据GB 2719-2018《食品安全国家标准 食醋》及GB/T 18187《酿造食醋》，食醋生产原料包括高粱、大米、麦麸、谷糠等含淀粉质原料，以及麸皮、谷糠等辅料，经发酵酿制而成。' WHERE id = 'bab8a01e-7314-4c51-afdf-08402a9f9b8a';
UPDATE public.questions SET analysis = '错误。根据《食品安全法》第十四条及《食品安全抽样检验管理办法》，风险监测是对尚无食品安全标准的风险因素开展的监测活动；对有食品安全标准的风险因素开展的是监督抽检。两者性质和目的不同。' WHERE id = 'bac24eaa-ca5b-4592-b450-d24f29334dce';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《食品召回管理办法》第八条，食品生产者通过自检自查、公众投诉举报、经营者告知、监督管理部门通知等多种途径知悉其食品属于不安全食品的，均应当启动召回程序。' WHERE id = 'badb2b0d-3189-4b9f-843b-404eb83ffac7';
UPDATE public.questions SET analysis = '选A、C。食品添加剂应符合GB 2760《食品安全国家标准 食品添加剂使用标准》的规定；营养强化剂应符合GB 14880《食品安全国家标准 食品营养强化剂使用标准》的规定。GB 2763为农药残留限量标准，GB 14881为食品生产通用卫生规范。' WHERE id = 'baf9c75e-297c-4b9b-a7fc-a27b8ac3f8d1';
UPDATE public.questions SET analysis = '选B、C、D。罐头内壁材料（如马口铁）不合格时，内容物中的蛋白质分解产生的硫化氢可能与铁反应生成硫化铁（B），马口铁镀锡层不合格会导致锡溶出（C），某些涂层材料含双酚A（D）可能迁移至食品中。二噁英（A）与罐头内壁材料无直接关系。' WHERE id = 'bb171e4b-b3d4-452f-bc65-1fae19d856a5';
UPDATE public.questions SET analysis = '正确。依据《食品安全法》第八十八条及《食品安全抽样检验管理办法》第三十条规定，复检机构应当与初检机构非同一家，且不得存在隶属关系或其他利害关系，以确保复检结果的客观公正。' WHERE id = 'bb2914df-6c47-4564-9e80-1ae8ef491d5f';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《婴幼儿配方乳粉产品配方注册管理办法》第四十一条，企业申请注销、注册被撤销/撤回/吊销、有效期届满未延续、企业依法终止等情形，均应注销配方注册。' WHERE id = 'bb3bc444-d166-47b8-b49b-adac38fc55b0';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《餐饮服务食品安全操作规范》及《餐饮服务许可审查规范》，食品处理区应按照原料进入、原料制作、半成品制作、成品供应的流程合理布局，遵循生进熟出的单一流向原则，防止交叉污染。' WHERE id = 'bb4413f7-4d0d-49f9-9b3a-22fc0470f098';
UPDATE public.questions SET analysis = '选C。依据GB 19300-2014《食品安全国家标准 坚果与籽类食品》，熟制葵花籽的过氧化值限量为小于等于0.80g/100g。过氧化值是反映油脂氧化程度的重要指标。' WHERE id = 'bb5a6d03-0566-455b-a18e-b282193775bf';
UPDATE public.questions SET analysis = '选A、B、C。依据《食品经营许可和备案管理办法》第十条，食品经营主体业态分为食品销售经营者、餐饮服务经营者、单位食堂三类，涵盖所有食品经营活动类型。' WHERE id = 'bb5bbffd-5a5d-48ba-8f58-fa2d90f62bcf';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《保健食品注册与备案管理办法》第四章，进口保健食品注册和备案应提交中文材料（A），中文译本经公证（B），质量标准符合中国格式（C），境外证明文件经公证和领事认证（D）。' WHERE id = 'bb5f0fd2-e046-4666-931b-6312d37ee738';
UPDATE public.questions SET analysis = '选B。依据《食品安全法》第四十四条及《企业落实食品安全主体责任监督管理规定》，企业食品安全管理人员监督抽查考核指南由国务院食品安全监督管理部门制定、公布。' WHERE id = 'bb5fdc49-2064-4bf3-87ee-493333e0ad80';
UPDATE public.questions SET analysis = '选C。盐渍或调味（腌渍）是酱腌菜的核心工艺和必需的基本生产流程，是产品形成特有风味的关键步骤。脱盐、切分、杀菌等工艺视具体产品类型而定，并非所有酱腌菜的必需工序。' WHERE id = 'bb652b6b-cb93-4003-b747-34b589c7ae04';
UPDATE public.questions SET analysis = '选C。依据《食品生产经营监督检查管理办法》第十四条，体系检查是指市场监督管理部门以风险防控为导向，对特殊食品、高风险大宗食品生产企业和大型食品经营企业等的质量管理体系执行情况依法开展的系统性监督检查。' WHERE id = 'bb79120e-fceb-4c4a-b7ab-79ecc191d730';
UPDATE public.questions SET analysis = '选A、B、C、D。依据食品安全相关法律法规及国家标准的规定，上述选项均为正确内容。' WHERE id = 'bb88cfea-9529-49a1-aa22-3ef280315cb1';
UPDATE public.questions SET analysis = '选A、B、D。依据食品安全相关法律法规及国家标准的规定，上述选项均为正确内容。' WHERE id = 'bb8cb874-62f8-449d-96dc-fc9a724bdcc0';
UPDATE public.questions SET analysis = '正确。《食品安全法》第二十九条规定，对地方特色食品，没有食品安全国家标准的，省、自治区、直辖市人民政府卫生行政部门可以制定并公布食品安全地方标准，报国务院卫生行政部门备案。食品安全国家标准制定后，该地方标准即行废止。' WHERE id = 'bb8dc567-c82e-4a8f-8e91-5a088241f526';
UPDATE public.questions SET analysis = '选B。依据《食品安全法》第一百五十条，食品安全是指食品无毒、无害，符合应当有的营养要求。A错误，高温灭菌不能杀灭所有微生物（如耐热芽孢）；C错误，原料天然不代表不含人工合成物质；D错误，超过保质期的食品不得销售。' WHERE id = 'bb90fb6f-e102-43fe-be71-527dd2140b90';
UPDATE public.questions SET analysis = '错误。根据《食品安全法》第三十五条及《食品经营许可和备案管理办法》，仅销售预包装食品的，应当报所在地县级以上地方人民政府食品安全监督管理部门备案，不需要取得食品经营许可。' WHERE id = 'bbb33295-fef5-4bc6-8111-e122c3dcbf31';
UPDATE public.questions SET analysis = '选C。审核查验机构符合食品安全相关法律法规及国家标准的规定，其他选项不符合法定要求。' WHERE id = 'bbc40376-4e5c-45f0-bb0d-f7977fcd4243';
UPDATE public.questions SET analysis = '选A、B、C、D。依据食品安全相关法律法规及国家标准的规定，上述选项均为正确内容。' WHERE id = 'bbd2d274-e89e-482c-bedf-1e900038e7b3';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《保健食品注册与备案管理办法》第四十二条，保健食品注册证书应载明产品名称、注册人信息、注册号和有效期、保健功能、功效成分及含量、产品规格、保质期、适宜人群、不适宜人群、注意事项等全部内容。' WHERE id = 'bbdb5f0d-70f0-4895-b496-76ece1b7422d';
UPDATE public.questions SET analysis = '正确。依据GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》第8.3.4条，食品生产企业应建立清洁剂、消毒剂等化学品的使用制度，明确使用范围、使用方法、使用量，并做好使用记录，防止对食品造成污染。' WHERE id = 'bbfaa430-9757-4b5c-93c6-8108ec4ebd45';
UPDATE public.questions SET analysis = '选D。依据《企业落实食品安全主体责任监督管理规定》第二条，食品生产经营企业的主要负责人、食品安全总监、食品安全员依法落实食品安全责任的行为及其监督管理，均适用该规定。' WHERE id = 'bc1695b6-c439-4d23-b7c8-3544311e0171';
UPDATE public.questions SET analysis = '错误。《未成年人保护法》第五十九条明确规定，学校、幼儿园周边不得设置烟、酒、彩票销售网点，禁止向未成年人销售烟、酒、彩票。向未成年人销售啤酒属于违法行为。' WHERE id = 'bc273963-b775-4e59-8819-4443233a193c';
UPDATE public.questions SET analysis = '选D。依据《企业落实食品安全主体责任监督管理规定》第十条、第十一条、第十二条，食品生产经营企业应当建立日管控、周排查、月调度工作机制，形成《每日食品安全检查记录》《每周食品安全排查治理报告》《每月食品安全调度会议纪要》。' WHERE id = 'bc317d81-6551-4962-95b5-3048e36eb047';
UPDATE public.questions SET analysis = '错误。根据《企业落实食品安全主体责任监督管理规定》，食品安全总监是直接负责的主管人员，而非间接负责的主管人员。直接负责的主管人员是指在违法行为中起直接决策、指挥作用的人员。' WHERE id = 'bc4a7a10-a2a4-4030-ac91-2fc9229daae5';
UPDATE public.questions SET analysis = '选A、B、D。依据GB 14881-2013第4.2.4条，生产车间门窗应闭合严密（A），窗户玻璃应使用不易碎材料（B），可开启的窗户应装有易于清洁的防虫害窗纱（D）。C错误，门应使用坚固、易清洁的材料，不得使用任意材料。' WHERE id = 'bc4ad16b-ce21-454a-ab86-616d52b994c5';
UPDATE public.questions SET analysis = '错误。该表述不符合食品安全相关法律法规或国家标准的规定，食品生产经营者应当按照法律法规和标准要求规范生产经营行为。' WHERE id = 'bc4b95f1-e231-4919-97d0-ec570abc3cb4';
UPDATE public.questions SET analysis = '选A、D。依据《市场监督管理严重违法失信名单管理办法》第十五条，市场监管部门应对列入严重违法失信名单的企业依法依规采取行政性约束（A）和惩戒（D）措施，实施联合惩戒。' WHERE id = 'bc6da31b-5a4f-48dd-9b3b-8048cb658f02';
UPDATE public.questions SET analysis = '正确。根据《食品经营许可和备案管理办法》第五条，仅销售预包装食品的备案不设有效期，备案编号长期有效。但备案信息发生变化时，备案人应当自变化之日起15个工作日内进行备案变更。' WHERE id = 'bc887fd1-d6af-4044-a3a5-cc300e4836ca';
UPDATE public.questions SET analysis = '选A、B、C。依据《食品经营许可和备案管理办法》第十条，连锁餐饮服务企业总部对门店实施统一的采购配送、质量管理、经营指导或品牌管理等规范化管理的，需取得餐饮服务连锁管理经营项目。' WHERE id = 'bc8b46b6-e1bd-449a-b7c8-514d8c3ce0aa';
UPDATE public.questions SET analysis = '错误。根据GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》6.4.2条，虫害控制应优先采用物理方法（如防鼠板、防蝇灯、纱网等），化学方法应作为最后手段，且不得在食品加工区域使用可能污染食品的杀虫剂。' WHERE id = 'bca0a514-8bb9-42be-b59e-3c120d2bccff';
UPDATE public.questions SET analysis = '选A、B、C、D。传统食品安全风险主要通过人流、物流、环境、设备等途径自然带入食品中。非传统风险则主要由人为故意破坏导致，两者防控方式不同。' WHERE id = 'bcab6219-3389-4384-b6a9-9cbc6f6f0bea';
UPDATE public.questions SET analysis = '选A、B、C、D。依据GB 14881-2013第8.2.1条，清洁消毒制度应包括清洁消毒的区域/设备/器具名称（A）、方法和频率（B）、效果验证及不合格处理（C）、使用的洗涤消毒剂（D）等全部内容。' WHERE id = 'bcb7afc8-4b26-40fa-9b8e-0a0b55c5ec9f';
UPDATE public.questions SET analysis = '选A、B、C。可可脂的基本生产工艺流程包括焙炒、破碎、压榨等工序。碱化是生产可可粉的可选工艺，不是可可脂生产的必需流程。' WHERE id = 'bcc70faa-aac0-4c08-a4d8-3e07146d6789';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《食品安全法》第三十四条及第七十八条，添加非食品原料、致病性微生物超标、无标签的预包装食品、超过保质期的保健食品均禁止销售。' WHERE id = 'bcca1e33-56d7-44af-af37-fc328aec6b01';
UPDATE public.questions SET analysis = '正确。依据《食品经营许可和备案管理办法》第十条，申请食品经营许可，应当先行取得营业执照等合法主体资格。营业执照是申请食品经营许可的前置条件。' WHERE id = 'bcd5c9f5-9434-493c-ae21-b20332da9691';
UPDATE public.questions SET analysis = '选C。依据《婴幼儿配方乳粉产品配方注册管理办法》第七条，省级食品药品监督管理部门负责配合国家总局开展本行政区域婴幼儿配方乳粉产品配方注册的现场核查工作。' WHERE id = 'bce5a320-7a02-4bc3-a465-aaf89fe07cc2';
UPDATE public.questions SET analysis = '选B。依据GB 14880-2012《食品安全国家标准 食品营养强化剂使用标准》，营养强化剂的使用范围、使用量等应符合该标准的规定。GB 2760是食品添加剂使用标准，不适用于营养强化剂。' WHERE id = 'bcf15bc4-3fda-4b51-9511-f185ad34f4ed';
UPDATE public.questions SET analysis = '选D。销售食用农产品符合食品安全相关法律法规及国家标准的规定，其他选项不符合法定要求。' WHERE id = 'bcffd789-df13-422f-81fe-2f37f3989d5b';
UPDATE public.questions SET analysis = '错误。液蛋制品加工应采用正确的打蛋工艺，挤压破壳法易造成蛋壳碎屑混入蛋液，增加沙门氏菌等微生物污染风险。应采用专业的打蛋设备，确保蛋液与蛋壳充分分离。' WHERE id = 'bd07748c-2be9-4d3c-be4b-bc6fc65ec2b2';
UPDATE public.questions SET analysis = '正确。根据《粮食流通管理条例》及《食品安全法》相关规定，国家粮食和物资储备局负责粮食流通的监督检查，负责粮食收购、储存、运输环节粮食质量安全和原粮卫生的监督管理。' WHERE id = 'bd1e76fa-5b76-48d0-b887-637d3b9e5907';
UPDATE public.questions SET analysis = '选A。中央厨房符合食品安全相关法律法规及国家标准的规定，其他选项不符合法定要求。' WHERE id = 'bd247282-9256-46e3-b741-07d9b5dcb4a9';
UPDATE public.questions SET analysis = '选C。依据GB 7098-2015《食品安全国家标准 罐头食品》，沙丁鱼罐头中组胺含量应不高于100mg/100g。组胺是鱼类产品中重要的生物胺指标，控制组胺含量对保障产品安全至关重要。' WHERE id = 'bd26a818-84bf-40b7-bd96-147808b78c9b';
UPDATE public.questions SET analysis = '选C。C、生产经营者符合食品安全相关法律法规及国家标准的规定，其他选项不符合法定要求。' WHERE id = 'bd277cdc-c7d2-4fdf-bdea-2045c0862c92';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《食品安全法》及食品安全全程控制理念，应建立原料控制（A）、过程控制（B）、检验控制（C）、生产销售记录（D）等全过程管理制度，实现食品可追溯。' WHERE id = 'bd29308f-c746-4d1e-8da6-8807e311bc5c';
UPDATE public.questions SET analysis = '选A、C。依据《反食品浪费法》第七条，餐饮服务经营者应主动对消费者进行防止食品浪费提示提醒（A、C），在醒目位置张贴或者摆放反食品浪费标识，不得使用警示、警告等强制性语言。' WHERE id = 'bd39afd5-815b-4067-af7b-388b564828dd';
UPDATE public.questions SET analysis = '选B、D。依据《婴幼儿配方乳粉产品配方注册管理办法》，A错误，应在有效期届满6个月前申请延续；C错误，准予延续的注册证书有效期自原有效期届满次日起计算，非重新计算。B、D为正确表述。' WHERE id = 'bd458825-f1d9-4336-a615-e26ac310ae03';
UPDATE public.questions SET analysis = '选A。依据《食品生产经营风险分级管理办法》第七条，食品生产企业风险等级从低到高划分为A级、B级、C级、D级四个等级，实施动态管理。' WHERE id = 'bd4a22a7-f641-4c6d-a8b5-6aed5502427c';
UPDATE public.questions SET analysis = '错误。根据《食品安全法》第三十四条及GB 7718-2011《预包装食品标签通则》，生产日期应为食品完成最终销售的日期，不得虚假标注。2018年1月10日完成包装，生产日期应标注为2018年1月10日。' WHERE id = 'bd4d33ef-490b-41bf-9180-cdd76c4f2bb5';
UPDATE public.questions SET analysis = '正确。河豚鱼等水产品含有天然生物毒素（如河豚毒素），加工前必须进行严格的毒素检测，确保毒素含量符合安全标准后方可加工。《食品安全法》第三十四条禁止经营未经检验的此类产品。' WHERE id = 'bd5056c6-7143-4f16-93e3-e68e46d8e10e';
UPDATE public.questions SET analysis = '正确。《电子商务法》第二十七条及《网络食品安全违法行为查处办法》规定，电子商务平台经营者应当核验、登记入网经营者的身份信息、行政许可等，建立登记档案并定期核验更新。' WHERE id = 'bd655cf5-66bb-4873-9875-b240cdc3e970';
UPDATE public.questions SET analysis = '选A、B。依据食品安全相关法律法规及国家标准的规定，上述选项均为正确内容。' WHERE id = 'bd6ee824-43d1-4c2e-b1ed-1519647b4070';
UPDATE public.questions SET analysis = '选A、B、C、D。即食淀粉制品为直接入口食品，人员（A）、工具（B）、环境（C）、包装材料（D）任何一个环节的卫生条件失控，均可能导致产品微生物超标。' WHERE id = 'bd8068b9-e439-4959-8a5c-69393bd0eda7';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《关于办理危害食品安全刑事案件适用法律若干问题的解释》第三条，致人死亡或重度残疾（A）、三人以上重伤（B）、十人以上轻伤（C）、三十人以上严重食物中毒（D）等情形均属于后果特别严重。' WHERE id = 'bd91b229-f243-47a7-9e2d-1fd22bf442b8';
UPDATE public.questions SET analysis = '选A。我国食品安全国家标准符合食品安全相关法律法规及国家标准的规定，其他选项不符合法定要求。' WHERE id = 'bd94e6d8-6adb-4ab3-b0f0-458a1f9977f8';
UPDATE public.questions SET analysis = '错误。取得食品生产许可的食品生产者在其生产加工场所销售其生产的食品，或在网络销售其生产的预包装食品，不需要另行备案。但在生产加工场所之外实体销售预包装食品需依法办理经营许可或备案。' WHERE id = 'bdac8eb2-6ecb-48df-8116-692773830a48';
UPDATE public.questions SET analysis = '选A、D。依据《学校食品安全与营养健康管理规定》第十条及《食品安全法》第三十五条，学校食堂应当依法取得食品经营许可证（A），并在食堂显著位置（D）悬挂或摆放许可证。' WHERE id = 'bdbaecc8-a76c-488a-9ed2-159a4b03f786';
UPDATE public.questions SET analysis = '选A。依据《食品安全法》第三十五条及《食品经营许可和备案管理办法》，在境内销售保健食品应当依法取得食品经营许可证。保健食品属于特殊食品，销售需取得相应许可。' WHERE id = 'bdbcffb6-f0ab-46cc-89e0-47b6f9534d32';
UPDATE public.questions SET analysis = '选D。依据《餐饮服务食品安全操作规范》及肉制品加工卫生要求，熟肉制品加工人员手套应每4小时更换一次，或在手套破损、污染时及时更换，以防止微生物交叉污染。' WHERE id = 'bdc57eb8-c2b1-4dfb-961f-a9f88f351779';
UPDATE public.questions SET analysis = '选D。依据GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》第5.1.8条，食品生产企业仓储设施应符合A、B、C全部要求：与生产数量相适应、以无毒坚固材料建成、易于维护和清洁并防止虫害侵入。' WHERE id = 'bdd5b6f3-37a3-407f-98b4-816e4da6382a';
UPDATE public.questions SET analysis = '正确。依据《食品安全法》第八十八条，复检机构出具的复检结论为最终检验结论。当事人对复检结论仍有异议的，可依法通过行政复议或行政诉讼等途径寻求救济，但复检结论本身具有最终性。' WHERE id = 'bdde30f2-d91f-4dfc-8759-47f7881140be';
UPDATE public.questions SET analysis = '选A。根据GB/T 20705-2023《可可液块及可可饼块质量要求》，可可仁中的可可壳和胚芽含量总和，按非脂干物质计算不应高于5%，或可可仁中可可壳含量按未碱化干物质计算不应高于1.75%。' WHERE id = 'bddec664-8bf3-4ec6-a543-d350f9e41186';
UPDATE public.questions SET analysis = '选A、B、C。依据《食品安全法》第五十三条及《保健食品管理办法》，经营者采购保健食品应查验供货者的许可证（A）、食品出厂检验合格证（B）、产品批准证明文件（C），即注册证书或备案凭证。' WHERE id = 'bddff684-c83e-4ea8-9051-4e5f8e19baf4';
UPDATE public.questions SET analysis = '正确。依据GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》第5.2.2条，用于食品生产监控的计量器具（如温度计、压力表等）应定期校准、维护，确保测量数据准确可靠。' WHERE id = 'bdfb73de-b17e-448f-9097-c09bf78a89b9';
UPDATE public.questions SET analysis = '正确。依据GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》，厂房和车间应合理设计，防止微生物孳生及污染，特别是应防止沙门氏菌等致病性微生物的污染。' WHERE id = 'be18ca50-22d5-4c4c-9eff-14146e72dfba';
UPDATE public.questions SET analysis = '选A、B、C。依据《保健食品注册与备案管理办法》第四十五条，变更产品规格、保质期、生产工艺等，应提供证明变更后产品的安全性、保健功能和质量可控性与原注册内容实质等同的材料、依据及变更后3批样品全项目检验报告。' WHERE id = 'be2d0f28-a6c1-4d1c-8d47-1a438d467159';
UPDATE public.questions SET analysis = '选A、B、C。依据《食品安全法》第七十四条，特殊食品包括保健食品（A）、特殊医学用途配方食品（B）、婴幼儿配方食品（C）。膨化食品（D）属于普通食品。' WHERE id = 'be2f69ed-5399-4edf-ae55-f232fbdfa2e2';
UPDATE public.questions SET analysis = '选A、B、C。依据GB 2758《食品安全国家标准 发酵酒及其配制酒》及《酒类标识管理办法》，玻璃瓶装啤酒应标示过量饮酒有害健康（A）、切勿撞击（B）、防止爆瓶（C）等警示语。' WHERE id = 'be43e27b-8e59-4a92-9ece-13a05253ecae';
UPDATE public.questions SET analysis = '选A、C。依据GB 10765-2010《食品安全国家标准 婴儿配方食品》及婴幼儿辅助食品生产许可审查细则，调整工艺流程及关键设备时，应进行必要性（A）和安全性（C）评估验证。' WHERE id = 'be43e45b-fa38-40fb-88ab-1afe126a5ec6';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《食品安全法》第四十四条及《企业落实食品安全主体责任监督管理规定》，食品安全管理人员应掌握食品安全法律（A）、法规（B）、标准（C）、专业知识（D），具备食品安全管理能力。' WHERE id = 'be47d0d4-3036-44cd-9e33-d9742b1a5da5';
UPDATE public.questions SET analysis = '选D。依据《保健食品注册与备案管理办法》及《保健食品命名指南》，备案保健食品通用名应当以规范的原料名称命名，不得使用自行编造的名称。' WHERE id = 'be4b8a50-76ed-4658-852d-fd2b4cc639b2';
UPDATE public.questions SET analysis = '选A、B、C、D。依据GB/T 13662《黄酒》及酿造工艺，黄酒生产原料包括稻米（A）、小麦（B）、玉米（C）、小米（D）等含淀粉质的粮谷类原料，经蒸煮、糖化、发酵酿制而成。' WHERE id = 'be52b5bc-0772-489a-859b-e2b4b59b9d17';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《特殊医学用途配方食品注册管理办法》第三十三条，注册证书及附件应载明产品名称、产品标签及说明书、产品配方、生产工艺等全部事项。' WHERE id = 'be78fdbc-49f8-4cb7-9379-7792514dbcf4';
UPDATE public.questions SET analysis = '选D。依据GB 2717-2018《食品安全国家标准 酱油》，酱油中氨基酸态氮含量应大于等于0.4g/100mL。氨基酸态氮是衡量酱油品质等级的重要指标。' WHERE id = 'be8251b3-05db-4a1e-8671-06e0bcf04cb7';
UPDATE public.questions SET analysis = '错误。《食品安全法》第七十条明确规定，食品添加剂应当有标签、说明书和包装。标签、说明书应当载明名称、规格、净含量、生产日期、保质期、使用范围、用量、生产许可证编号等事项。' WHERE id = 'be83867f-ea20-4b47-a02c-34f58915b7fb';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《行政许可法》第七十条，行政许可有效期届满未延续（A）、法人或其他组织终止（B）、许可被撤销/撤回/吊销（C）、因不可抗力无法实施（D）等情形，均应注销行政许可。' WHERE id = 'be9427dc-1a18-4e8b-8308-fc6b13a35666';
UPDATE public.questions SET analysis = '选C。依据《食品安全法》第六十三条，食品召回应当先向所在地县级人民政府食品安全监督管理部门报告召回计划，然后对召回的食品进行无害化处理、销毁，而非先处理后报告。A、B、D均为正确表述。' WHERE id = 'be982320-1c7b-4963-909a-7a3a61d77ffa';
UPDATE public.questions SET analysis = '正确。根据《蜂产品生产许可审查细则（2022版）》及GB 7718《预包装食品标签通则》，蜂产品制品标签上的配料表应如实标明蜂蜜、蜂王浆（含蜂王浆冻干品）、蜂花粉或其混合物的添加量或在成品中的含量，不得虚假标注。' WHERE id = 'beaa511c-04f8-407e-9394-d6cff44a6e4b';
UPDATE public.questions SET analysis = '正确。《食品安全法》第一百零三条明确规定，任何单位和个人不得对食品安全事故隐瞒、谎报、缓报，不得隐匿、伪造、毁灭有关证据。发生食品安全事故的单位应立即采取措施，防止事故扩大。' WHERE id = 'bed1fc2e-62d5-45e9-84ee-51e7d69d7b14';
UPDATE public.questions SET analysis = '错误。依据《食品安全法》第四十五条，从事接触直接入口食品工作的人员（包括餐用具清洗消毒人员）应当每年进行健康检查，取得健康证明后方可上岗工作。' WHERE id = 'bee17d19-1f1c-445d-af81-7d48b338ac23';
UPDATE public.questions SET analysis = '正确。茶树对重金属元素（如铅、镉等）具有较强的富集能力，随着茶叶成熟度增加，重金属含量可能升高。因此，茶叶原料的选择和质量控制尤为重要，需符合GB 2762《食品中污染物限量》的要求。' WHERE id = 'bee292c8-8000-486f-970f-1040af932975';
UPDATE public.questions SET analysis = '选D。依据《食品安全法》第一百二十三条，用非食品原料生产食品的，县级以上人民政府食品安全监督管理部门有权没收违法所得、违法生产的食品及用于违法生产的工具、设备、原料等物品，并处罚款。' WHERE id = 'bef19fc3-47f6-4000-82d2-6d93b40b4e4a';
UPDATE public.questions SET analysis = '错误。依据《食品安全法》第一百二十六条，食品经营企业未制定食品安全事故处置方案的，责令改正、给予警告；拒不改正的，处五千元以上五万元以下罚款；情节严重的，责令停产停业，直至吊销许可证。' WHERE id = 'befb4669-4e0f-4326-a412-7cf6cd7084a7';
UPDATE public.questions SET analysis = '选A、B、C、D。依据食品安全相关法律法规及国家标准的规定，上述选项均为正确内容。' WHERE id = 'befee04c-1829-432b-9ca4-4f0d2ba9f035';
UPDATE public.questions SET analysis = '正确。根据《食品经营许可和备案管理办法》第三十二条，食品经营许可证变更的，新证编号与原证一致，发证日期为作出变更许可决定的日期，有效期与原证书一致。' WHERE id = 'bf030623-552f-46cd-9f82-35ae4868fd75';
UPDATE public.questions SET analysis = '正确。淀粉产品水分含量过高会促进微生物生长繁殖，导致产品发霉变质。GB/T 8885《食用玉米淀粉》等标准对各类淀粉的水分含量有明确限量要求。' WHERE id = 'bf097dcb-25fd-42f0-a0df-330b2845b147';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《食品安全法》第五十条，食品生产经营企业应当对食品原料（A）、食品添加剂（B）、食品相关产品（C）和食品（D）进行进货查验，并留存查验记录。' WHERE id = 'bf13a2d7-fb2e-4755-a5fb-4b4cfbb09d9d';
UPDATE public.questions SET analysis = '正确。该表述符合食品安全相关法律法规及国家标准的规定，食品生产经营者应当严格遵守执行。' WHERE id = 'bf2e63d2-a478-43ba-97d5-5d17698c711f';
UPDATE public.questions SET analysis = '选D。依据《食品安全法》第六十三条及《食品生产经营监督检查管理办法》，不合格食品应进行显著标示或单独存放，及时采取无害化处理、销毁等措施，如实记录处置情况，不得销售给第三方。' WHERE id = 'bf332eef-741d-4c1d-b78a-b30d5aecacb3';
UPDATE public.questions SET analysis = '选A、B、C、D。依据GB 14963-2011《食品安全国家标准 蜂蜜》，蜂蜜中不得添加任何其他物质。常见的蜂蜜掺假方式包括掺加蔗糖、果葡糖浆、淀粉糖、玉米糖浆等。' WHERE id = 'bf36de30-20b1-4804-bf94-106b3ab1780d';
UPDATE public.questions SET analysis = '错误。根据GB 28050-2011《预包装食品营养标签通则》第3.2条，预包装食品营养标签如同时使用外文标示，其内容应当与中文相对应，外文字号不得大于中文字号，以确保消费者能够准确获取营养信息。' WHERE id = 'bf432cbc-6c90-4e88-b439-94efb032bb31';
UPDATE public.questions SET analysis = '正确。依据《食品安全抽样检验管理办法》第十九条，抽样人员应当当场向被抽样食品生产经营者告知依法享有的权利和应当承担的义务，被抽样食品生产经营者应当在食品安全抽样文书上签字或者盖章。' WHERE id = 'bf463e2f-51d4-486f-b55b-350589140e62';
UPDATE public.questions SET analysis = '选A、B、C、D。依据食品安全相关法律法规及国家标准的规定，上述选项均为正确内容。' WHERE id = 'bf47e77b-b16b-4274-bf57-71e4983c12cb';
UPDATE public.questions SET analysis = '错误。依据《市场监督管理严重违法失信名单管理办法》，市场监管部门对列入严重违法失信名单的企业实施联合惩戒，但并未明确规定对企业食品安全总监和食品安全员实施市场和行业禁入措施。' WHERE id = 'bf52c623-9864-496b-9b7a-ad16b6b80304';
UPDATE public.questions SET analysis = '正确。该表述符合食品安全相关法律法规及国家标准的规定，食品生产经营者应当严格遵守执行。' WHERE id = 'bfa9fc6b-b5fd-476d-a755-9a007b50a7a7';
UPDATE public.questions SET analysis = '选A、B、C、D。白酒生产中常用的发酵剂包括大曲（A）、小曲（B）、麸曲（C），以及酶制剂和酵母（D）等，不同发酵剂赋予白酒不同的风味特征。' WHERE id = 'bfaaffb4-f625-431a-916a-d5d90ed02d70';
UPDATE public.questions SET analysis = '选C。依据《食品经营许可和备案管理办法》及GB 14881的规定，食品经营场所和贮存场所应距离粪坑、污水池、暴露垃圾场（站）、旱厕等污染源25米以上。' WHERE id = 'bfbf80b5-9203-427a-b5ce-1f8d4e46a646';
UPDATE public.questions SET analysis = '正确。依据GB 14881-2013第8.5条及《食品安全法》第三十三条，食品生产企业应建立食品出厂检验记录制度及运输交付控制制度，确保食品在运输过程中符合食品安全要求。' WHERE id = 'bfc6d0b9-38ae-4c86-ac3b-2469831a3053';
UPDATE public.questions SET analysis = '错误。根据《食品安全法》第十四条及《食品安全抽样检验管理办法》，风险监测是对尚无食品安全标准的风险因素开展的监测活动；对有食品安全标准的风险因素开展的是监督抽检。两者性质和目的不同。' WHERE id = 'bfc7062c-cc05-430c-b7cd-b617ca31e6d2';
UPDATE public.questions SET analysis = '正确。依据《餐饮服务食品安全操作规范》及《明厨亮灶工作规范》，明厨亮灶是指餐饮服务提供者采用透明玻璃幕墙、视频显示、网络展示等方式，向社会公众展示餐饮服务相关过程的形式，目的是强化社会监督。' WHERE id = 'bfd6b9da-80ff-43d8-b77e-cde8be1db6cc';
UPDATE public.questions SET analysis = '错误。根据《食品安全法》第八十四条，食品检验机构的资质认定条件和检验规范由国务院食品安全监督管理部门规定，而非卫生行政部门。' WHERE id = 'bfe0726a-687b-48d0-b37d-b30ac31b1ea3';
UPDATE public.questions SET analysis = '正确。依据《食品安全法》第八十八条及《食品安全抽样检验管理办法》第三十条，复检机构不得与初检机构为同一机构，以保证复检结果的独立性和公正性。' WHERE id = 'bfead3f1-3919-43b9-a5e1-b1a63f852414';
UPDATE public.questions SET analysis = '选A、B、C、D。依据GB 14881-2013第8.4条及HACCP体系要求，设备维护（A）、卫生管理（B）、外来人员管理（C）、加工过程监督（D）均为降低异物污染风险的有效措施。' WHERE id = 'bfff8346-a171-4c27-9fc0-11f9143de28d';
UPDATE public.questions SET analysis = '选B。依据《食品安全法》第三十八条，生产经营的食品中不得添加药品，但是可以添加按照传统既是食品又是中药材的物质。A错误，无标签预包装食品禁止生产经营；C、D错误，病死肉类和回收食品均禁止作为原料。' WHERE id = 'c005ff0c-3978-4eb7-923e-d728046ed72b';
UPDATE public.questions SET analysis = '正确。该表述符合食品安全相关法律法规及国家标准的规定，食品生产经营者应当严格遵守执行。' WHERE id = 'c0119feb-aa54-4a34-a464-393486cad5bd';
UPDATE public.questions SET analysis = '错误。依据《食品安全法》第七十一条及GB 7718，普通食品不得宣传保健功能或疾病预防、治疗功能。加入既是食品又是中药材的物质，不得以此在标签上标识功效。保健食品须经注册或备案后方可声称保健功能。' WHERE id = 'c025e686-9fb6-46d6-be5a-f1b017b602c8';
UPDATE public.questions SET analysis = '正确。该表述符合食品安全相关法律法规及国家标准的规定，食品生产经营者应当严格遵守执行。' WHERE id = 'c02ed2a0-c2b7-4171-b7e0-ba056fda127b';
UPDATE public.questions SET analysis = '选B、C、D。依据《食品经营许可和备案管理办法》第十二条，主体业态后应以括号标注的内容包括：建立中央厨房（B）、通过网络经营（C）、集体用餐配送（D）等。自助餐厅（A）属于经营形式，不需特别标注。' WHERE id = 'c03a8f28-3a07-4dae-a4ca-dbe0d5c2cecc';
UPDATE public.questions SET analysis = '错误。《食品安全法》第七十九条及《保健食品广告审查暂行规定》明确禁止保健食品广告声称或暗示商品为保障健康所必需，不得使用绝对化用语夸大功效。' WHERE id = 'c047d623-5f80-44cb-84da-e6ed80b44e4e';
UPDATE public.questions SET analysis = '选A。0－12个月龄符合食品安全相关法律法规及国家标准的规定，其他选项不符合法定要求。' WHERE id = 'c06ab68b-acb7-4d5b-ba43-89c75e89ad71';
UPDATE public.questions SET analysis = '选A、C。依据《农产品质量安全法》第五十一条，农产品批发市场发现不符合农产品质量安全标准的，应当要求销售者立即停止销售，并向所在地市场监督管理部门（A）和农业农村部门（C）报告。' WHERE id = 'c070eb58-f132-40ba-b598-2bc32d263f28';
UPDATE public.questions SET analysis = '正确。《食品安全法》第一百五十条对食品安全的定义为：食品无毒、无害，符合应当有的营养要求，对人体健康不造成任何急性、亚急性或者慢性危害。' WHERE id = 'c08e5289-ed74-4fbb-a8eb-43e602f09a8a';
UPDATE public.questions SET analysis = '选A。依据GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》第5.1.1条，食品加工用水的水质应符合GB 5749《生活饮用水卫生标准》的规定。' WHERE id = 'c0ae8d2c-3832-4b19-9864-6837d9d47882';
UPDATE public.questions SET analysis = '错误。根据《食品安全法》第一百三十五条，被吊销许可证的食品生产经营者及其法定代表人、直接负责的主管人员和其他直接责任人员自处罚决定作出之日起五年内不得申请食品生产经营许可，而非三年。' WHERE id = 'c0b89e13-f265-480d-bd71-5323970af665';
UPDATE public.questions SET analysis = '选A、B。依据《学校食品安全与营养健康管理规定》第三十二条，有条件的地方应为中小学、幼儿园配备营养专业人员，对膳食营养均衡（A）进行咨询指导，推广科学配餐、膳食营养（B）等理念。' WHERE id = 'c0bcfe9a-2ed8-4c86-86ff-4949fc0c5901';
UPDATE public.questions SET analysis = '正确。依据《企业落实食品安全主体责任监督管理规定》第三条，食品生产经营企业应当建立健全主要负责人负总责，食品安全总监、食品安全员分级负责的食品安全责任体系。' WHERE id = 'c0d531e6-f46a-484c-ae15-857a3a6ddf83';
UPDATE public.questions SET analysis = '选B。依据GB 25192-2022《食品安全国家标准 再制干酪和干酪制品》，再制干酪是以干酪比例大于50%为主要原料，添加其他原料和食品添加剂，经加热、搅拌、乳化等工艺制成的产品。' WHERE id = 'c0ef54de-a0e1-4fcf-acd8-09bc61412d15';
UPDATE public.questions SET analysis = '选D。依据《食品生产经营风险分级管理办法》第二十三条，市场监督管理部门应根据上一年度风险等级及规定条件，对食品生产经营企业下一年度的风险等级进行调整，实行动态管理。' WHERE id = 'c0ef8756-6953-42f0-b061-5b19ecfd20f7';
UPDATE public.questions SET analysis = '正确。《食品安全法》第四十八条鼓励食品生产经营企业符合良好生产规范（GMP）要求，实施危害分析与关键控制点体系（HACCP），提高食品安全管理水平。' WHERE id = 'c0f432e6-3488-42ee-abca-2525fb097578';
UPDATE public.questions SET analysis = '正确。该表述符合食品安全相关法律法规及国家标准的规定，食品生产经营者应当严格遵守执行。' WHERE id = 'c0fe7093-0093-4d19-95ce-6aa0ab6febf5';
UPDATE public.questions SET analysis = '选B、C、D。依据《餐饮服务许可审查规范》，中央厨房和集体用餐配送单位应具备自行或委托检验条件（B），不具备自行检验能力的应提交委托协议（C），检验项目包括农药残留、致病性微生物等（D）。A选项非强制性要求。' WHERE id = 'c102668c-e31d-409e-9890-8fe21d051b2c';
UPDATE public.questions SET analysis = '选A。食品营养符合食品安全相关法律法规及国家标准的规定，其他选项不符合法定要求。' WHERE id = 'c110809f-263c-4bd2-8f0d-c19e09b4b3b0';
UPDATE public.questions SET analysis = '选A、C、D。依据《蜂产品生产许可审查细则（2022版）》及GB 7718，蜂蜜产品名称可根据蜜源植物命名（A）；蜂产品制品应标示蜂产品制品（C）；配料表应如实标明添加量或含量（D）。B错误，蜂产品制品不得命名为蜂蜜膏。' WHERE id = 'c113add2-6344-4798-8ec3-8d6645dfda2d';
UPDATE public.questions SET analysis = '正确。根据《餐饮服务食品安全操作规范》，冷食类食品是指最后一道工艺在常温或低温条件下进行（包括解冻、切配、调制等），加工后在常温或低温条件下即可食用的食品。' WHERE id = 'c11754df-df1d-4c73-9c51-c94482d63b61';
UPDATE public.questions SET analysis = '错误。该表述不符合食品安全相关法律法规或国家标准的规定，食品生产经营者应当按照法律法规和标准要求规范生产经营行为。' WHERE id = 'c11ab89d-7e7b-4dfa-ab14-ccc502128272';
UPDATE public.questions SET analysis = '选A。依据GB 2761-2017《食品安全国家标准 食品中真菌毒素限量》，玉米面中玉米赤霉烯酮的限量为小于等于60μg/kg。玉米赤霉烯酮是玉米及其制品中重要的真菌毒素指标。' WHERE id = 'c1398604-25b7-4365-9142-f59ab5a263ab';
UPDATE public.questions SET analysis = '选B。油炸方便面是采用油炸脱水工艺干燥的方便面，面条经蒸煮后进行油炸脱水，水分含量低，保质期较长。热风干燥方便面则采用热风干燥工艺。' WHERE id = 'c149e9fc-971b-4efa-aefe-3bfb80e6eb73';
UPDATE public.questions SET analysis = '错误。根据GB 2758-2012《食品安全国家标准 发酵酒及其配制酒》，发酵酒是以粮谷、水果、乳类等为主要原料，经发酵酿制而成的饮料酒，不经蒸馏。蒸馏酒才是经蒸馏工艺酿制的。' WHERE id = 'c14aa04f-3fc5-4df9-a357-5af0bf958584';
UPDATE public.questions SET analysis = '错误。根据《食品生产许可管理办法》第四条，食品生产许可实行一企一证原则，同一个食品生产者从事食品生产活动，应当取得一个食品生产许可证。生产多种类别食品的，可在同一个许可证上载明多个食品类别。' WHERE id = 'c1529e1d-06ce-42b3-90ac-2a2a9f928032';
UPDATE public.questions SET analysis = '错误。根据《食品经营许可和备案管理办法》，经营场所、主体业态、经营项目属于许可事项，住所不属于许可事项。住所是市场主体登记事项，而非食品经营许可事项。' WHERE id = 'c1767ada-569c-4abe-abca-6d81a30a2922';
UPDATE public.questions SET analysis = '选D。依据GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》，食品原料、包装材料等应分类分区存放，码放在一起易引起交叉污染。A、B、C均为防止交叉污染的正确措施。' WHERE id = 'c19d1575-c791-43c0-bdd4-0cb52870ee9f';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《企业落实食品安全主体责任监督管理规定》第十五条，食品安全总监、食品安全员应掌握食品安全法律法规和标准（A）、具备识别和防控风险的专业知识（B）、熟悉本企业生产经营过程控制要求（C）、参加培训并通过考核（D）。' WHERE id = 'c1b0bdd3-e665-497d-b382-31b4c87c112e';
UPDATE public.questions SET analysis = '选C。GB 1352-2023《大豆》的实施日期为2023年12月1日。该标准替代了GB 1352-2011《大豆》，对大豆的分类、质量要求等进行了修订。' WHERE id = 'c1b491c7-3381-4bdf-bd6d-34b587666a49';
UPDATE public.questions SET analysis = '错误。根据《食品安全法》第四十七条，食品生产经营者应当建立食品安全自查制度，定期对食品安全状况进行检查评价。定期检查是法定义务，不定期检查不符合法律要求。' WHERE id = 'c1b8f4f9-68f0-4b81-a37f-40d0ec6b8ec6';
UPDATE public.questions SET analysis = '选A、B、C、D。依据GB 19301-2010《食品安全国家标准 生乳》及乳制品安全标准，生鲜乳中的化学污染包括兽药残留（A）、农药残留（B）、黄曲霉毒素污染（C）、重金属污染（D）等。' WHERE id = 'c1bd17a4-59ba-4ba6-be1c-5d30aec4c737';
UPDATE public.questions SET analysis = '选B。依据《食品经营许可和备案管理办法》第五条，仅销售预包装食品的，在办理市场主体登记注册时，一并提交仅销售预包装食品备案信息采集表即可进行备案。' WHERE id = 'c1bec794-79fe-4e03-827a-8edaa1de764d';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《食品安全法》第三十四条，禁止生产经营病死、毒死或者死因不明的禽、畜、兽、水产动物肉类（A、B、C），以及未经检验或者检疫不合格的肉类（D）。' WHERE id = 'c1c1cc3e-b1b4-449a-a8e6-a86d9baeadba';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《食品安全法》第四十九条及《农药管理条例》，剧毒、高毒农药不得用于瓜果（A）、蔬菜（B）、茶叶（C）、中草药材（D）等农作物。' WHERE id = 'c1c8d76d-29ce-4cbe-8961-6e583aa21137';
UPDATE public.questions SET analysis = '选D。依据GB 14881-2013第5.1.5条，与消毒设施配套的水龙头开关应为非手动式（如感应式、脚踏式等），以避免交叉污染。手动式开关不符合食品安全要求。A、B、C均为正确表述。' WHERE id = 'c1d9ee55-e129-4538-a1ca-e7060b9853ac';
UPDATE public.questions SET analysis = '选A、B、C、D。依据食品安全相关法律法规及国家标准的规定，上述选项均为正确内容。' WHERE id = 'c1ed630c-02fe-4158-aac7-e079344c63c1';
UPDATE public.questions SET analysis = '正确。依据GB 14881-2013《食品安全国家标准 食品生产通用卫生规范》及《餐饮服务食品安全操作规范》，生食与熟食应分开存放，防止交叉污染，这是食品安全的基本要求。' WHERE id = 'c22449d0-01fd-4f8f-8988-8b7751093bb4';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《食品安全法》第六十三条及《食品召回管理办法》，发现食品不符合安全标准的，应立即停止生产（A）、召回已上市销售的食品（B）、通知相关方（C）、记录召回和通知情况（D）。' WHERE id = 'c2355d1a-6361-42c7-8698-dce45b4ffcf5';
UPDATE public.questions SET analysis = '正确。《食品安全法》第五十五条及《餐饮服务食品安全操作规范》要求，餐饮服务提供者应当制定并实施原料控制要求，不得采购不符合食品安全标准的食品原料，并倡导公示食品原料及来源信息。' WHERE id = 'c23bc16d-8030-44ef-a98b-846e44c253da';
UPDATE public.questions SET analysis = '选A、B、C。依据食品安全相关法律法规及国家标准的规定，上述选项均为正确内容。' WHERE id = 'c2415bff-30bc-45d0-aecb-25cc01871589';
UPDATE public.questions SET analysis = '错误。根据《学校食品安全与营养健康管理规定》，集中用餐陪餐制度要求陪餐人员对饭菜进行客观评价，对食堂环境卫生、从业人员工作情况等进行监督，做好陪餐记录，而非留样记录。留样是另一项独立制度要求。' WHERE id = 'c24f590b-e92d-4b65-9b99-ec67acf0b0ce';
UPDATE public.questions SET analysis = '选B、C、D。依据《食品安全法实施条例》第九条，食品生产经营者自查确认存在风险隐患的，应当停止生产经营（B）、实施食品召回（C）、向市场监管部门报告（D），不得继续销售。' WHERE id = 'c27b46af-ab4f-4012-ab7c-4fb7af277544';
UPDATE public.questions SET analysis = '正确。《食品安全法》及其实施条例明确规定，食品销售企业应落实食品安全主体责任，食品安全管理人员应掌握相关法律法规的重要条款，切实履行管理职责。' WHERE id = 'c2a3130e-1a0e-4497-bc11-87d1da8b33b8';
UPDATE public.questions SET analysis = '选B。依据《特殊医学用途配方食品注册管理办法》第十八条，申请人对拟不予注册通知有异议的，应当自收到通知之日起20个工作日内向审评机构提出书面复审申请并说明复审理由。' WHERE id = 'c2a4f28c-2f2d-4455-ab51-25efce8a8ab4';
UPDATE public.questions SET analysis = '选A、B、C、D。依据《食品经营监督检查要点表》及食品安全监管实践，售卖过程中的风险点包括：未按要求冷藏冷冻（A）、未记录销售情况（B）、场所布局不合理（C）、未明示散装食品信息（D）等。' WHERE id = 'c2b8b41a-dfbe-4840-b768-d70b65f553e5';
UPDATE public.questions SET analysis = '选A、B、C。依据GB 14881-2013第6.3.2条，未经洗手消毒直接进入作业区域（A）、将私人物品带入作业区域（B）、在作业区域内吸烟饮食（C）均不符合卫生要求。D为正确做法。' WHERE id = 'c2d14cad-2c27-4a3f-96d8-0d16ef31770e';
UPDATE public.questions SET analysis = '选A、B、C。依据GB 14881-2013第7.1-7.5条，食品原料仓库应设专人管理（A），食品相关产品须验收合格后使用（B），进入生产区域应有缓冲区域或外包装清洁措施（C）。D错误，采购原料必须查验许可证和产品合格证明。' WHERE id = 'c2df6785-4b0c-4e66-bb04-30bb193ea64f';
UPDATE public.questions SET analysis = '错误。根据《食品经营许可和备案管理办法》及《餐饮服务食品安全操作规范》，自制饮品包括现场制作的各种饮料、冰淇淋、雪糕等冷冻饮品，不仅限于液态饮料。' WHERE id = 'c2ec122c-607d-49d5-9b51-327424df3e5a';
UPDATE public.questions SET analysis = '选C。DEHP（邻苯二甲酸二(2-乙基己基)酯）是常见的塑化剂，易从含邻苯二甲酸酯类物质的塑料管道和包装材料中迁移至酒中，导致塑化剂超标。TBHQ、BHT、BHA为抗氧化剂。' WHERE id = 'c30f40d2-991a-4fd0-83d5-7a250292f580';
UPDATE public.questions SET analysis = '正确。依据《网络餐饮服务食品安全监督管理办法》第九条，入网餐饮服务提供者应当在餐饮服务经营活动主页面公示食品经营许可证、名称、地址等信息，信息应当真实并及时更新。' WHERE id = 'c32fc069-a2b8-4bb1-973a-66ebdc75b441';
UPDATE public.questions SET analysis = '错误。《食品安全法》第七十八条及《保健食品注册与备案管理办法》明确规定，保健食品标签、说明书应符合法律规定，预包装保健食品无标签的不得上市销售。' WHERE id = 'c34cf565-8399-428e-94c7-a997cacc8ee9';
UPDATE public.questions SET analysis = '正确。食品抽样检验是食品安全监管的重要手段，通过监督抽检和风险监测，能够有效推动落实食品安全属地管理责任和企业主体责任，排查风险隐患，提升食品安全整体水平。' WHERE id = 'c3556712-bf46-4a4a-9d9e-13ed30a061a9';
UPDATE public.questions SET analysis = '选A、B、D。依据《食品安全信用信息管理办法》，食品安全信用信息包括基础信息（A）、行政许可信息（B）、检查信息（D）、监督抽检信息、行政处罚信息等。风险分级信息（C）属于风险评估信息。' WHERE id = 'c3688dfb-cca4-4c09-b79a-d5dfad4f0c32';
UPDATE public.questions SET analysis = '错误。《食品安全法》第六十三条第三款规定，对因标签、标志或者说明书不符合食品安全标准而被召回的食品，食品生产者在采取补救措施且能保证食品安全的情况下可以继续销售。销售时应向消费者明示补救措施。' WHERE id = 'c36e354d-c48c-41f0-82df-eacab2956fae';
UPDATE public.questions SET analysis = '选D。水果脆片属于果蔬脆片类产品，根据相关产品标准，水分含量应小于等于5%（0.05），以保持产品的酥脆口感并抑制微生物生长。' WHERE id = 'c36e97bf-b862-43e6-a776-14253254e8c9';
UPDATE public.questions SET analysis = '选A。依据GB 19645-2010《食品安全国家标准 巴氏杀菌乳》，只有巴氏杀菌乳可以标注为鲜牛羊乳。灭菌乳、调制乳等不得使用鲜字标识。' WHERE id = 'c371903d-42db-47da-be51-e16f4e3171c1';
