UPDATE public.questions SET analysis = '选A。2符合食品安全相关法律法规及国家标准的规定，其他选项不符合法定要求。' WHERE id = 'c40f3658-efff-4d8e-8f4f-f5b2b18e5e85';
UPDATE public.questions SET analysis = '正确。依据《行政许可法》第五十条，行政机关应当根据被许可人的申请，在该行政许可有效期届满前作出是否准予延续的决定；逾期未作决定的，视为准予延续。' WHERE id = 'c410c74b-b7c4-46cf-8fc2-325422e5a6b5';
UPDATE public.questions SET analysis = '选B。依据《食品经营许可和备案管理办法》第五十二条，终止食品经营或食品经营许可被撤回、撤销、吊销，未按规定申请办理注销手续的，责令改正，拒不改正的，给予警告，并处2000元以下罚款。' WHERE id = 'c41780e7-5743-4081-a97a-f42dd640701a';
UPDATE public.questions SET analysis = '选D。依据GB 29921-2021《食品安全国家标准 预包装食品中致病菌限量》，冲调谷物制品中致病菌限量应符合该标准中粮食制品的规定。' WHERE id = 'c41b2034-32b7-42e4-a209-8d61dce3c001';
UPDATE public.questions SET analysis = '选A。依据《餐饮服务食品安全操作规范》及病媒生物防制要求，防蝇胶帘应覆盖整个门框，底部离地距离小于2cm，以防止蝇虫侵入。' WHERE id = 'c423c98a-ab88-428f-8b08-d5a3c957366f';
UPDATE public.questions SET analysis = '选B。依据《食品安全法》第八十七条及《食品安全抽样检验管理办法》第三条，食品安全抽样检验工作由市场监督管理部门负责组织实施。' WHERE id = 'c42e9388-4029-40bc-abd1-eb0ca6f633b5';
UPDATE public.questions SET analysis = '选A、D。依据《学校食品安全与营养健康管理规定》第十二条，学校应当配备专（兼）职食品安全管理人员（A）和营养健康管理人员（D），建立集中用餐岗位责任制度。' WHERE id = 'c43fe083-1397-4eb7-af1d-3f72bf432b4d';
UPDATE public.questions SET analysis = '选A、B、D。依据《企业落实食品安全主体责任监督管理规定》第十六条，企业应对食品安全总监、食品安全员进行法律（A）、法规（B）、标准（D）和专业知识培训、考核。' WHERE id = 'c45461be-024a-4d5e-9b60-fcf32d3a00a8';
UPDATE public.questions SET analysis = '正确。《食盐专营办法》及《食品安全国家标准 食用盐》（GB 2721）规定，加碘食盐应当有明显标识并标明碘含量；未加碘食盐应在标签显著位置标注''未加碘''字样。' WHERE id = 'c465b546-6cb1-4181-bb61-61781ef7d880';
UPDATE public.questions SET analysis = '选A、B。依据《食品安全法》第三十三条，食品生产企业应有专职或者兼职的食品安全专业技术人员、食品安全管理人员。不得使用临时（C）或业余（D）人员承担食品安全管理职责。' WHERE id = 'c46d6c00-e4b7-4cd9-8ec6-d7b0c8ad283d';
UPDATE public.questions SET analysis = '选B。依据《食品安全法》第八十七条，县级以上食品安全监督管理部门进行抽样检验，应当购买抽取的样品，不得向食品生产经营者收取检验费和其他费用。' WHERE id = 'c47e3d66-4adf-431c-b231-d37b689a7700';
UPDATE public.questions SET analysis = '选A、B、C、D。依据食品安全相关法律法规及国家标准的规定，上述选项均为正确内容。' WHERE id = 'c47edccf-7a05-4f93-95aa-1f4353accd65';
UPDATE public.questions SET analysis = '选A。依据《食品安全法》第五十三条，食品经营企业应当建立食品进货查验记录制度，如实记录食品的名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容。' WHERE id = 'c49837a1-ab97-48a5-b356-7498ac0867e3';
UPDATE public.questions SET analysis = '错误。该表述不符合食品安全相关法律法规或国家标准的规定，食品生产经营者应当按照法律法规和标准要求规范生产经营行为。' WHERE id = 'c49b3035-f3f0-463b-9398-a8075a7379df';
UPDATE public.questions SET analysis = '选B。依据《餐饮服务食品安全操作规范》及食品贮存要求，食品冷藏温度应在0-10℃之间，冷冻温度应在-20℃至-1℃之间。' WHERE id = 'c49d07a8-d6ab-4141-b39a-cc23f48ff648';
UPDATE public.questions SET analysis = '正确。《食品安全法》第三十四条明确禁止在食品中添加食品添加剂以外的化学物质和其他可能危害人体健康的物质。《食品中可能违法添加的非食用物质名单》对此类行为进行了严格管控。' WHERE id = 'c4bc1ced-55ce-4d97-ab43-17d05e901be5';
