UPDATE public.questions SET analysis = '选C。出厂检验合格符合食品安全相关法律法规及国家标准的规定，其他选项不符合法定要求。' WHERE id = 'c4dfac98-81f1-4b55-9dc1-a4f3528f1f6c';
UPDATE public.questions SET analysis = '选D。依据《婴幼儿配方乳粉产品配方注册管理办法》第九条，每个企业原则上不得超过3个配方系列9种产品配方。这是为了防止企业过度开发配方，确保产品质量安全。' WHERE id = 'c51c57c5-b211-4f3f-bd85-42afe4077871';
