UPDATE public.questions SET analysis = '答案A,B,C,D正确。薯类食品按加工工艺主要分为干制薯类、冷冻薯类、薯泥（酱）类、薯粉类和其他薯类。' WHERE id = 'c5eed121-0a65-405e-8094-a90e8427bb4b';
