UPDATE public.questions SET analysis = '正确。GB 8537《饮用天然矿泉水》规定，饮用天然矿泉水必须在水源点附近进行包装，不应用容器将水源水运至异地灌装。' WHERE id = 'cdad71b8-eafe-42f1-b373-5ec46861c31d';
UPDATE public.questions SET analysis = '该表述正确。根据《中华人民共和国食品安全法》及相关法规标准的规定，所述内容符合法律法规要求。' WHERE id = 'cdb0e7ea-b619-4092-877a-166ec7d578e9';
UPDATE public.questions SET analysis = '答案D正确。《食用农产品市场销售质量安全监督管理办法》规定，食用农产品是指在农业活动中获得的供人食用的植物、动物、微生物及其产品。' WHERE id = 'cdcfb0ce-22a9-40df-ba21-3faad5fa8da3';
UPDATE public.questions SET analysis = '正确。GB 14881规定，清洁消毒前后的食品生产设备和工器具应分开放置妥善保管，防止交叉污染。' WHERE id = 'cdd1599a-239e-4e7e-95c0-13e479aa5b87';
UPDATE public.questions SET analysis = '答案A正确。根据《中华人民共和国食品安全法》及相关法规标准的规定，1次符合法律法规要求。其他选项不符合相关规定。' WHERE id = 'cde6f725-dce9-4b8e-8a29-8e0c40127397';
UPDATE public.questions SET analysis = '答案C正确。《食品安全法》明确的食品安全工作四个基本原则是：预防为主、风险管理、全程控制、社会共治，不包括''过程控制''的单独表述。' WHERE id = 'cdef955c-2e5e-4f93-b1e1-8f84478cfc37';
UPDATE public.questions SET analysis = '该表述正确。根据《中华人民共和国食品安全法》及相关法规标准的规定，所述内容符合法律法规要求。' WHERE id = 'ce0995de-313c-4872-98c6-5c3e621b85e9';
UPDATE public.questions SET analysis = '答案D正确。GB 2761规定，大米黄曲霉毒素B1的限量要求为≤10μg/kg。' WHERE id = 'ce1ac45b-da94-4c3b-a8d9-98c4a6b61fee';
UPDATE public.questions SET analysis = '错误。GB 14880《食品营养强化剂使用标准》允许使用人工合成的营养素作为营养强化剂，如叶酸、维生素C等。' WHERE id = 'ce1df66c-b7d9-425d-945a-c7429d01c249';
UPDATE public.questions SET analysis = '错误。企业食品安全管理人员抽查考核不合格的，应当进行再培训或调整岗位，而非直接''免去职务''。' WHERE id = 'ce2131b2-7d09-4c2a-99cc-ab3054b88eac';
UPDATE public.questions SET analysis = '错误。《网络餐饮服务食品安全监督管理办法》规定，网络外卖配送需冷藏食品应使用保温措施配送，不得常温配送，以保证食品在配送过程中的温度符合食品安全要求。' WHERE id = 'ce21668f-4a91-4507-b5f4-de844e752fa5';
UPDATE public.questions SET analysis = '答案A正确。GB 14880《食品安全国家标准 食品营养强化剂使用标准》规定，糖果（胶基糖果除外）中可以强化的矿物质是铁，铁是人体必需的微量元素之一。' WHERE id = 'ce27deaf-2f18-4290-8405-445ae7c96fef';
UPDATE public.questions SET analysis = '该表述正确。根据《中华人民共和国食品安全法》及相关法规标准的规定，所述内容符合法律法规要求。' WHERE id = 'ce39e35e-d725-4370-866a-fbda11fdc946';
UPDATE public.questions SET analysis = '依据《食用农产品市场销售质量安全监督管理办法》第二十一条规定，批发市场开办者应当印制统一格式的销售凭证，载明食用农产品名称、产地、数量、销售日期以及销售者名称、地址、联系方式等项目。' WHERE id = 'ce3ba99b-a0a8-400c-83fb-c4bd171fe7ac';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 淀粉糖》（GB 15203-2014），淀粉糖是以淀粉或淀粉质为原料，经酶法、酸法或酸酶法加工制成的液（固）态产品。湿热处理法不是标准规定的淀粉糖加工方法。' WHERE id = 'ce8d5c8c-a03b-405b-be32-744759eb7c23';
UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》第十九条规定，婴幼儿配方乳粉产品配方注册证书及附件应当载明产品配方、产品名称、注册号、批准日期及有效期等事项。委托方联系方式及产品营养成分表不属于必须载明事项。' WHERE id = 'ce920ca6-cc06-460f-b9cf-f1764e85a014';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）及相关危害分析要求，生物性危害包括致病性细菌及其产生的毒素、真菌毒素、朊病毒、寄生虫、虫害及其他产毒生物。' WHERE id = 'ce989d68-44d3-4354-9d94-52009e198b9a';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 乳粉》（GB 19644-2010），乳粉是以单一品种的生乳为原料，经加工制成的粉状产品。此处''品种''指牛乳、羊乳等不同乳源品种。' WHERE id = 'ce99f54b-b938-438f-91f3-731082dbc826';
UPDATE public.questions SET analysis = '依据《婴幼儿辅助食品生产许可审查细则》规定，婴幼儿辅助食品生产企业的研发人员应至少掌握食品生产工艺、营养、质量安全等相关专业知识。' WHERE id = 'cec0fbc2-c18c-474c-8f20-0cdcfde58eb0';
UPDATE public.questions SET analysis = '依据《食品安全抽样检验管理办法》第三十九条规定，在不合格食品复检和异议期间，食品生产经营者不得停止履行风险控制、原因排查、问题整改等义务。' WHERE id = 'cec62ac7-7b06-48f8-96ff-3aa4e45476eb';
UPDATE public.questions SET analysis = '依据《中华人民共和国广告法》第十八条和《保健食品广告审查暂行规定》，保健食品广告不得声称或者暗示广告商品为保障健康所必需，不得涉及疾病预防、治疗功能。' WHERE id = 'cecc6754-4207-488c-b6b4-8f4cdc6d44ac';
UPDATE public.questions SET analysis = '依据《食品经营许可和备案管理办法》第二十一条规定，食品经营许可证有效期为五年。题目中''八年''的说法错误。' WHERE id = 'ced79d74-03b5-45e9-928c-eaa1a2f381c7';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第9.3条规定，食品生产企业检验室应妥善保存检验报告和原始记录，并留存样品。产品留样是食品安全管理的重要环节。' WHERE id = 'cf0a56fe-0d0e-4d89-8bfb-d56b95426157';
UPDATE public.questions SET analysis = '依据《食品标识管理规定》第八条，食品标识上的注册商标可以使用中文、汉语拼音、少数民族文字或外文。注册商标不强制要求使用中文，但应当符合相关语言文字规定。' WHERE id = 'cf0b5b20-52e8-4eb1-a273-4e24b8d8bbaa';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013），新不锈钢设备、容器在使用前应进行酸洗和钝化处理，去除表面氧化层和污染物，防止重金属迁移污染食品。' WHERE id = 'cf0ff6cc-deed-4208-be7b-043c535868c6';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》及《食品生产许可审查通则》，其他食品的生产工艺应当根据具体的食品品种来确定主要原辅料和生产工艺流程，确保工艺科学、合理、安全。' WHERE id = 'cf1ef93f-19ae-4cd5-ba60-0685ee2846c1';
UPDATE public.questions SET analysis = '依据GB 14881-2013，物料传递口常开会导致交叉污染；垃圾未密闭加盖会导致虫害和微生物污染；原料仓库无通风设施会导致原料变质。成品离地离墙存放是正确做法，符合规范要求。' WHERE id = 'cf3396e4-753e-45dc-9bcd-37328799c529';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 发酵酒及其配制酒》（GB 2758-2012）4.3条规定，啤酒应标示原麦汁浓度，以''原麦汁浓度''为标题，以柏拉图度符号''°P''为单位。' WHERE id = 'cf354199-ccd2-4ed2-9888-a8a7320563d4';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 糖果》（GB 17399-2016）及《预包装食品营养标签通则》（GB 28050-2011），无糖糖果是指含糖量（以单糖和双糖计）≤0.5%的糖果。' WHERE id = 'cf4d1d57-f913-4200-9580-bf3d68cf8fca';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第一百零五条规定，发生食品安全事故的单位应当对导致或可能导致食品安全事故的原料、工具、设备、设施以及食品等采取封存等控制措施，防止事故扩大。' WHERE id = 'cf8041da-4a06-4f08-a835-1dccc8e3c927';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》及《食品经营许可和备案管理办法》，从事冷食类食品制售中的冷加工糕点制售和冷荤类食品制售的，经市场监督管理部门审核同意后，在《食品经营许可证》经营项目后以括号标注。' WHERE id = 'cf9873e4-ba4b-4a6c-b6e1-e0dac04193b0';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第7.2.2条规定，食品原料必须经过验收合格后方可使用，经验收不合格的食品原料应在指定区域与合格品分开放置并做好明显标记，及时退、换货等处理。' WHERE id = 'cf99f87d-40db-411a-b4ce-2a01275fea33';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第三十四条，禁止用甲醇生产白酒、禁止用工业用乙酸勾兑食醋、禁止添加苏丹红等非食用物质。小苏打（碳酸氢钠）是GB 2760允许使用的食品添加剂，可在焙制面包时按标准限量使用。' WHERE id = 'cfa12683-2aef-4813-b9cf-e00ea510f6a4';
UPDATE public.questions SET analysis = '《食品经营许可和备案管理办法》经国家市场监督管理总局2023年6月7日第10次局务会议审议通过，自2023年12月1日起施行。' WHERE id = 'cfbe468a-f21f-454a-b3cc-e2e9f4a8ee30';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 冲调谷物制品》（GB 19640-2016），冲调谷物食品是以谷物或其他淀粉质类原料为主，添加或不添加辅料，经熟制和（或）膨化等工艺加工制成的即食食品，包括麦片、芝麻糊、莲子羮、藕粉等。' WHERE id = 'cfbf0fdf-34db-4018-997a-175545c9ba14';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 动物性水产制品》（GB 10136-2014）及相关分类标准，烤鱼片属于熟制水产品；虾米属于干制水产品，干海参属于盐干/淡干水产品，盐渍海带属于盐渍水产品。' WHERE id = 'cfd88e6c-e3c7-406e-be95-db60969dc63c';
UPDATE public.questions SET analysis = '依据GB 14881-2013及果冻产品生产工艺分析，果冻产品霉菌和酵母超标常见原因包括原料受霉菌污染、生产环境卫生控制不当、产品存储和运输条件失控导致二次污染等。' WHERE id = 'cfe77bcc-7087-442a-bbb8-3b727b763da8';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第五十条及GB 14881-2013规定，食品生产者应当如实记录食品原料、食品添加剂和食品包装材料等食品相关产品的名称、规格、数量、供货者名称及联系方式、进货日期等内容。' WHERE id = 'cff1a183-71c0-4416-a888-c66edbcc7f8a';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第五十三条规定，从事食品批发的销售企业应当建立食品销售记录制度，如实记录批发食品的名称、规格、数量、生产日期或者生产批号、保质期、销售日期以及购货者名称、地址、联系方式等内容。' WHERE id = 'cff67556-fdb0-4c9d-bcf1-aa8e57f6d102';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第五十三条规定，从事食品批发业务的经营企业应当建立食品进货查验记录制度，如实记录食品的名称、规格、数量、生产日期、生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容。' WHERE id = 'd00c259a-0222-4556-ad95-1c28795857d9';
UPDATE public.questions SET analysis = '依据《食品经营许可和备案管理办法》第三十条规定，外设仓库地址、经营种类、销售方式以及网络经营情况、使用自动设备情况、连锁经营情况等备案信息发生变化的，应当自发生变化后15个工作日内向原备案部门进行备案信息更新。' WHERE id = 'd0109062-2b0e-42f4-89ff-3295415821d8';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第四条及《餐饮服务食品安全操作规范》规定，餐饮服务经营者应当依照法律、法规和食品安全标准从事餐饮服务活动，对社会和公众负责，保证食品安全。' WHERE id = 'd025db9a-d1e9-46db-b78d-bdc5d1584070';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 腌腊肉制品》（GB 2730-2015），火腿、腊肉、咸肉、香（腊）肠的过氧化值（以脂肪计）限量为≤0.5g/100g。' WHERE id = 'd0390ee7-6c2b-44b1-a455-43c2ccbf8ba0';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》及《企业落实食品安全主体责任监督管理规定》，餐饮服务提供者应当建立包括食品安全信息追溯管理、消费者投诉处理、从业人员健康管理、食品安全自查等在内的食品安全管理制度体系。' WHERE id = 'd05cd869-06ff-4bab-b2cf-ace73aaf5fa7';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第六条，食品安全管理人员应当掌握与其岗位相适应的食品安全法律、法规、标准和专业知识，具备食品安全管理能力，并经考核合格。' WHERE id = 'd05e3f2e-204b-4d9b-9e92-4b32a68cfc97';
UPDATE public.questions SET analysis = '依据《特殊医学用途配方食品注册管理办法》第九条规定，申请特殊医学用途配方食品注册，应当提交注册申请书、产品研发报告和产品配方设计及其依据、生产工艺资料、产品标准要求等材料。' WHERE id = 'd065cc47-3d50-445d-900b-68d195179504';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》第三十一条规定，食品生产者应当妥善保管食品生产许可证，不得伪造、涂改、倒卖、出租、出借、转让。违反规定的将被责令改正，给予警告，并处1万元以下罚款。' WHERE id = 'd08375bb-11e5-4ca5-8d1d-e4ab9b6f8ee0';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第四十三条第二款规定，国家鼓励食品生产经营企业参加食品安全责任保险。连锁餐饮服务企业购买食品安全责任保险属于鼓励性措施，非强制性要求。' WHERE id = 'd084da36-8f5d-492b-832e-00639a19e4ca';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 婴幼儿谷类辅助食品》（GB 10769-2010），婴幼儿谷物辅助食品中黄曲霉毒素B1的限量指标为≤0.5μg/kg（微克/千克），而非0.5mg/kg（毫克/千克），两者相差1000倍。' WHERE id = 'd091c840-073f-4fae-b55a-03b2f0d7cd23';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品中米酵菌酸测定》（GB 5009.189-2016）及相关食品安全知识，长时间发酵或浸泡的淀粉制品（如凉皮、河粉等）容易被椰毒假单胞菌污染，产生米酵菌酸毒素，可导致严重食物中毒甚至死亡。' WHERE id = 'd09eace4-3f75-4636-bf84-83a37a60d542';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》，专间（如凉菜间、裱花间）和专用操作区应当配备专用工作服，且外观上应与一般区域工作服有明显颜色或款式区分，以防止交叉污染。' WHERE id = 'd0a886e0-5486-46ce-a306-b8a5c5f806d7';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品中真菌毒素限量》（GB 2761-2017），霉菌毒素是霉菌在生长繁殖过程中产生的有毒次级代谢产物，如黄曲霉毒素、赭曲霉毒素等，对人体具有急慢性毒性、致癌性等危害。' WHERE id = 'd0aeaef0-6be0-4bb1-8c3b-19bb1156d73e';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第六条规定，省级以上食品药品监督管理部门应当加强信息化建设，提高保健食品注册与备案管理信息化水平，逐步实现电子化注册与备案。' WHERE id = 'd0b7a07a-dc15-4749-9f5b-5958a95e4134';
UPDATE public.questions SET analysis = '依据《中华人民共和国反食品浪费法》第八条及《餐饮服务食品安全操作规范》规定，单位食堂应当改进供餐方式，在醒目位置张贴或摆放反食品浪费标识，引导用餐人员适量点餐、取餐，对有浪费行为的及时提醒纠正。' WHERE id = 'd0c2f2f7-5a8b-4b33-940d-dfa48b0ff626';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）及罐头食品生产工艺，罐头食品的重金属污染主要来源于原料（如水产品中的汞、铅）和加工用水，而非生产加工设备。设备材质通常符合食品安全要求。' WHERE id = 'd0d30a49-9371-4c96-9f93-f3d3527d58f9';
UPDATE public.questions SET analysis = '依据《中华人民共和国反食品浪费法》第七条规定，餐饮服务经营者应当采取多种措施防止食品浪费，包括张贴反浪费标识、提升供给质量、提供小份餐、主动对消费者进行提示提醒等。连锁食品经营企业总部应制定细化措施。' WHERE id = 'd0f47c5d-7ba6-482f-9eb8-b4716ea87480';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》第十三条第一款规定，申请人委托他人办理食品生产许可申请的，代理人应当提交授权委托书以及代理人的身份证明文件。' WHERE id = 'd0f7f5ec-8346-44d6-ba65-81f951c26eb0';
UPDATE public.questions SET analysis = '依据《网络食品安全违法行为查处办法》第十八条规定，通过第三方平台进行交易的食品经营者应当在其经营活动主页面显著位置公示其食品经营许可证。相关信息应当画面清晰，容易辨识。' WHERE id = 'd10943be-b6ab-4138-8da9-fc3eafe1b0a4';
UPDATE public.questions SET analysis = '依据GB 14881-2013第6.3.2条规定，食品加工人员工作过程中如厕后，重新进入食品生产区域前应当洗手、消毒，穿戴洁净的工作服帽。仅洗手不消毒不符合卫生操作要求。' WHERE id = 'd113f60a-bd4a-424a-b5bb-e30e20100842';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》，方便食品许可范围包括方便面、其他方便食品和调味面制品三个类别。饮料属于单独的许可类别，不属于方便食品。' WHERE id = 'd1211b93-bce7-4690-8eed-367634c0a051';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第十条及《中共中央 国务院关于深化改革加强食品安全工作的意见》，食品安全社会共治是指调动政府监管部门、食品生产经营者、行业协会、消费者协会乃至公民个人等社会各方力量共同参与食品安全工作。' WHERE id = 'd14fe0e0-fd31-4f4e-982e-ca590ba1f495';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品添加剂使用标准》（GB 2760-2014）及《餐饮服务食品安全操作规范》，食品添加剂的使用必须按照GB 2760规定的使用范围和使用限量准确计量添加，不得凭经验或感觉随意添加。' WHERE id = 'd162ea16-a9e5-4f96-8501-bc596f1a948e';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 豆制品》（GB 2712-2014），腐皮是指从熟豆浆表面揭起的凝结薄膜，经干燥或不干燥后折叠压制而成的产品。题目描述遗漏了''经干燥或不干燥''这一关键工艺特征。' WHERE id = 'd1663369-7a42-4910-8a50-5df3153b5e63';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》第三条规定，同一个食品生产者从事食品生产活动，应当取得一个食品生产许可证。一个生产主体只能持有一个食品生产许可证。' WHERE id = 'd16c0759-92e2-4e01-9094-459d93112d91';
UPDATE public.questions SET analysis = '依据《中华人民共和国广告法》第十八条规定，保健食品广告不得含有表示功效、安全性的断言或者保证，不得涉及疾病预防、治疗功能。保健食品广告有特殊限制，区别于一般食品广告。' WHERE id = 'd16c90c7-7d76-4381-bb23-600d56c34b04';
UPDATE public.questions SET analysis = '依据《食品经营过程卫生规范》（GB 31621-2014）及《食品经营许可审查通则》，冷藏冷冻设施设备无论品牌，均应定期除霜、清洁和维护，以保证设施正常运行和食品质量安全。' WHERE id = 'd17552e0-2d2b-4858-9dd9-e14b45d7ad86';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第7.2.6条规定，食品原料仓库出货顺序应遵循先进先出的原则，必要时应根据不同食品原料的特性确定出货顺序。' WHERE id = 'd1959080-e462-4b51-8398-99afc7764541';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 发酵酒及其配制酒》（GB 2758-2012），发酵型果酒属于发酵酒，其沙门氏菌限量应符合GB 2758的规定。GB 2757为蒸馏酒标准，GB 2762为污染物限量标准，GB 2763为农药残留限量标准。' WHERE id = 'd199c453-901e-4013-b4de-a585ea837fe2';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 蜂蜜》（GB 14963-2011），常温下蜂蜜的状态可能为全部结晶状态、粘稠流体状态或部分结晶状态。蜂蜜结晶是葡萄糖析出的正常现象，不影响品质。' WHERE id = 'd19c7a9a-e4c1-4218-9cc0-aa9ad64570a0';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第六十三条规定，需要对召回的食品进行无害化处理、销毁的，应当提前报告时间、地点，食品安全监督管理部门认为必要的可以实施现场监督。题目中''事后报告''的说法错误。' WHERE id = 'd1b2f60a-cb2d-4af6-8357-a65a9be30ab2';
UPDATE public.questions SET analysis = '依据《茶叶分类》（GB/T 30766-2014）及食品生产许可分类标准，袋泡烘青茉莉花茶属于袋泡茶类。袋泡茶是以茶叶为原料，加工制成的用过滤材料包装的产品。' WHERE id = 'd1bfca85-2ada-433d-9bfc-4dcaba4cbc05';
UPDATE public.questions SET analysis = '依据《中华人民共和国立法法》及我国食品安全法律法规体系，法律效力层次从高到低依次为：食品安全法律、食品安全行政法规、食品安全部门规章、食品安全标准。其中食品安全法律（如《食品安全法》）效力最高。' WHERE id = 'd1d9f990-62f1-49b6-bd6e-ea8768c09e64';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 碳酸饮料（汽水）》（GB/T 10792-2008），碳酸饮料分为果汁型、果味型、可乐型和其他型四类。各类别按原料和风味特征划分。' WHERE id = 'd1e0bbaa-d6a3-4eb2-a4b8-3af9eb80a7a0';
UPDATE public.questions SET analysis = '依据《食品生产经营监督检查管理办法》第三条规定，日常监督检查（含''双随机''抽查检查）是指市级、县级市场监督管理部门按照年度监督检查计划对本行政区域内食品生产经营者开展的常规性检查。' WHERE id = 'd1e6b91e-d323-44c3-a270-1651d226246f';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第三十三条及《企业落实食品安全主体责任监督管理规定》，食品生产经营企业应当配备食品安全管理人员，加强对其培训和考核，经考核不具备食品安全管理能力的不得上岗。' WHERE id = 'd1e7e831-5b61-481e-abce-bbcf8720dd3f';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第三十四条规定，禁止生产经营用超过保质期的食品原料、食品添加剂生产的食品；超范围、超限量使用食品添加剂的食品；腐败变质等感官性状异常的食品；未按规定检疫或检疫不合格的肉类等。' WHERE id = 'd1f0285c-428a-473b-a3ee-dca3f754c059';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第五十三条及《保健食品经营管理规范》，保健食品经营者采购保健食品应当查验供货者的食品经营许可证、保健食品注册或备案证书、产品出厂检验合格证等证明文件，无需查验供货商个人身份证明。' WHERE id = 'd1f4c99f-ef9f-4b93-93aa-ebfe3c59e1d9';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第十条，''周排查''是由食品安全总监或食品安全员每周至少组织1次风险隐患排查，形成《每周食品安全排查治理报告》。题目表述不完整，缺少具体报告名称要求。' WHERE id = 'd1f57396-d445-4633-be68-bc00286d1bc3';
UPDATE public.questions SET analysis = '依据《中华人民共和国农产品质量安全法》第三十六条规定，经检测不符合农产品质量安全标准的农产品，不得销售，应当及时采取管控措施，进行无害化处理或者销毁。' WHERE id = 'd216d7fb-a881-472d-aa99-0d96ff7b63b5';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第5.2.1.2.1条，与原料、半成品、成品接触的设备与用具，应使用无毒、无味、耐酸、耐碱、耐高温、不易脱落的材料制作，并应易于清洁和保养。' WHERE id = 'd21b7392-46dc-4be4-adb8-ac627d6b2cb5';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 预包装食品标签通则》（GB 7718-2011）4.1.7.2条，销售单元包含若干标示了生产日期及保质期的独立包装食品时，外包装上标示生产日期可选择最早生产日期或外包装形成日期，保质期按最早到期单件标示，或分别标示各单件信息。' WHERE id = 'd2225d97-8aa3-4e50-94dc-458773c9f314';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》，实施食品生产许可的速冻食品分为：速冻面米制品、速冻调制食品、速冻其他食品三个类别。' WHERE id = 'd229756f-0481-4dbc-9e88-6ec9505b8a71';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第四条第一款规定，食品生产经营者对其生产经营食品的安全负责。食品生产经营者应当依照法律、法规和食品安全标准从事生产经营活动，保证食品安全。' WHERE id = 'd2331e58-e14b-4638-8f7a-8d664577afda';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第5.1.8.3条，食品原料、半成品、成品应分隔或者分离贮存，并有明确标识，防止交叉污染和混淆。' WHERE id = 'd24195c2-8015-4f1b-adaa-bc7430acb53a';
UPDATE public.questions SET analysis = '依据《食品生产经营监督检查管理办法》及《食品安全信用信息管理办法》，食品安全信用信息包括食品生产经营者基础信息、行政许可信息、检查信息、食品监督抽检信息、行政处罚信息等。' WHERE id = 'd2568059-727d-4b65-9120-096a357098cb';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》第五十三条规定，食品生产者伪造、涂改、倒卖、出租、出借、转让食品生产许可证的，由县级以上地方食品安全监督管理部门责令改正，给予警告，并处1万元以下罚款；情节严重的，处1万元以上3万元以下罚款。' WHERE id = 'd26400c9-c769-4b5f-9e7c-d5f0858212a1';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第三十四条及《餐饮服务食品安全操作规范》规定，禁止经营腐败变质等感官性状异常的食品；病死、毒死或死因不明的动物肉类及其制品；未按规定检疫或检疫不合格的肉类；标注虚假生产日期或超过保质期的食品。' WHERE id = 'd272d488-d1ea-4c81-af2d-fdcd490522a9';
UPDATE public.questions SET analysis = '依据《中华人民共和国产品质量法》第四十九条规定，生产、销售不符合保障人体健康和人身、财产安全的国家标准、行业标准的产品的，责令停止生产、销售，没收违法生产、销售的产品，并处违法生产、销售产品货值金额等值以上三倍以下的罚款。' WHERE id = 'd2743bc0-c123-4d8b-8610-ce82006c9b5b';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第十二条，食品安全总监等食品安全管理人员每月应向企业主要负责人汇报本月食品安全管理情况、发现的食品安全风险隐患及整改情况、前期未整改到位的隐患进展、存在的突出问题及其原因、下一步工作意见建议及其他需要汇报的相关情况。' WHERE id = 'd284c3d4-e756-447d-8819-c2ee433a0da1';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 预包装食品标签通则》（GB 7718-2011）3.11条规定，若外包装物（容器）能清晰识别内包装物（容器）上所有或部分强制标示内容，可不在外包装上重复标示相应内容，但需确保消费者能获取完整标签信息。' WHERE id = 'd294d0a7-7de7-4277-8e4a-10bd23384f2d';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第四十五条及《餐饮服务食品安全操作规范》规定，从事接触直接入口食品工作的人员（包括切菜、配菜、烹饪、传菜、餐用具清洗消毒、散装食品销售等岗位）应当每年进行健康检查，取得健康证明后方可上岗。' WHERE id = 'd2b3ec94-9cd7-45f4-80dc-049d2618088b';
UPDATE public.questions SET analysis = '依据《食品生产许可审查通则》及调味料生产许可审查细则，调味料生产企业生产用厂房应能满足原料处理、加工、杀菌、后处理和包装等全过程的工艺要求，并按照生产工艺流程合理布局。' WHERE id = 'd30bf6b1-50d4-4608-9b0a-f08183d14ab1';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第五十四条规定，食品经营者应当按照保证食品安全的要求贮存食品，定期检查库存食品，及时清理变质或者超过保质期的食品。低温冷藏仅为部分食品的特定贮存要求。' WHERE id = 'd318aea3-58e4-4df1-acf9-e43f52cbc7bd';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第一百一十条规定，食品安全监管部门实施日常监督检查，有权采取查封违法生产经营场所、扣押用于违法生产经营的工具、设备、原料等物品的措施。刑拘和撤销职务不属于食品安全监管部门的权限。' WHERE id = 'd346fa70-7375-4cc0-8d77-0c905959f6ff';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 预包装食品标签通则》（GB 7718-2011），食糖定型包装产品的外包装标签应当符合GB 7718的规定，包括食品名称、配料表、净含量、生产者信息、生产日期、保质期等强制标示内容。' WHERE id = 'd350c086-d164-47c2-a8df-3ce4f6c996d0';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品添加剂使用标准》（GB 2760-2014）3.1条，食品添加剂使用时不应掩盖食品腐败变质，不应掩盖食品本身或加工过程中的质量缺陷，不应降低食品本身的营养价值。改善食品品质是允许使用食品添加剂的目的之一。' WHERE id = 'd359d8c1-8acd-4ff2-a25f-c9d768fec61f';
UPDATE public.questions SET analysis = '依据《白酒工业术语》（GB/T 15109-2021），液态法白酒是以粮谷为原料，采用液态发酵工艺所得的基酒，可用香醅串香或用食品添加剂调香调味的白酒。题目中''使用食用酒精添加食品添加剂勾调''的表述不准确，液态法白酒也需以粮谷为原料发酵。' WHERE id = 'd369f823-7f95-48bc-87b1-f3ad3d0dbf44';
UPDATE public.questions SET analysis = '依据《学校食品安全与营养健康管理规定》第二条，幼儿园集中用餐的食品安全与营养健康管理适用本规定。该规定适用于实施学历教育的各级各类学校、幼儿园。' WHERE id = 'd3740575-e352-4609-b776-74ddf739390d';
UPDATE public.questions SET analysis = '依据《食品冷链物流卫生规范》（GB 31605-2020）及冷藏冷冻管理要求，温度传感器或温度记录仪应放置在能准确反映食品温度的位置（如冷库的冷点），而非最能反映平均温度的位置。' WHERE id = 'd3894f7f-5674-4f43-ba44-53e997b85ee4';
UPDATE public.questions SET analysis = '依据《肉制品生产许可审查细则》及HACCP原理，肉制品生产过程关键控制点应至少包括腌腊肉制品的腌制过程、热加工熟肉制品的热加工过程、发酵肉制品的发酵过程等温度和时间控制环节。' WHERE id = 'd398792f-923e-485b-9557-8ccea096869d';
UPDATE public.questions SET analysis = '依据《食品经营过程卫生规范》（GB 31621-2014）及《餐饮服务食品安全操作规范》，经营水产品的区域应与其他食品经营区域分开设置，防止水产品带来的交叉污染。' WHERE id = 'd3991414-1773-4430-bd92-cc2f5b0d1296';
UPDATE public.questions SET analysis = '依据《食品经营许可和备案管理办法》第三十一条规定，终止仅销售预包装食品经营活动的，应当自经营活动终止之日起15个工作日内办理备案注销。主体资格依法终止的，市场监管部门可依职权办理备案注销。' WHERE id = 'd39e12bd-bb04-4dde-a4e9-ad3b30abc7d2';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》及《食品经营过程卫生规范》，销售直接入口散装食品的从业人员，应当在每天上岗前进行健康状况检查并记录，患有有碍食品安全疾病的人员不得从事接触直接入口食品的工作。' WHERE id = 'd39e3486-f707-4a1b-80cd-4012826de0bc';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013），木薯淀粉生产企业应配备与生产能力相适应的生产设备，并按照工艺流程有序排列，避免交叉污染。' WHERE id = 'd3a09034-88fe-4cd4-8392-fbf021b36b55';
UPDATE public.questions SET analysis = '依据《薯类食品生产许可审查细则》，切片型马铃薯片生产工艺包括：鲜薯验收、清洗去皮、切分成型、漂烫、冷却、油炸或焙烤、调味（或不调味）、包装等工艺。漂烫是去除表面淀粉、防止褐变的关键工序。' WHERE id = 'd3ab59cc-21de-4a44-8c62-c599c5f6b2d5';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第六十三条规定，食品经营者发现其经营的食品不符合食品安全标准或者有证据证明可能危害人体健康的，应当立即停止经营，通知相关生产经营者和消费者，并记录停止经营和通知情况。' WHERE id = 'd3bcb9ab-9408-4bdc-b5af-1c23a85e0774';
UPDATE public.questions SET analysis = '依据《食品生产许可审查通则》及相关细则，原料水果、蔬菜的品种、成熟度、新鲜度应符合加工要求，病虫害和变质水果、蔬菜在整批原料中所占比例不得超过5%，以保证产品质量安全。' WHERE id = 'd3dd64cd-bfed-426c-9646-6e3740ba267d';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第五条，餐饮服务企业应当依法配备与企业规模、食品类别、风险等级、管理水平等相适应的食品安全管理人员，明确企业主要负责人、食品安全总监、食品安全员等的岗位职责。' WHERE id = 'd3e347bf-2235-4c3e-96ba-1ced1280246f';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 发酵酒及其配制酒》（GB 2758-2012）4.5条规定，酒精度大于等于10%vol的发酵酒及其配制酒可免于标示保质期。' WHERE id = 'd3e91f56-b550-4f41-b3c6-e3fd1c3a3a1e';
UPDATE public.questions SET analysis = '依据《食品经营许可和备案管理办法》及《仅销售预包装食品备案办事指南》，仅销售预包装食品的备案人应当取得营业执照等合法主体资格，并具备与销售的食品品种、数量等相适应的经营条件。' WHERE id = 'd3f5ec9c-95f6-44b9-8fb1-7b9b3be53b13';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第五十六条规定，一个保健食品产品只能使用一个商标名。保健食品名称由商标名、通用名和属性名组成，商标名使用应符合国家有关规定。' WHERE id = 'd4064d79-bc16-4b19-bf27-3565999ce00d';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》，配送过程中，直接入口食品和非直接入口食品、需低温保存的食品和热食品应分隔存放，防止直接入口食品污染，并采取有效措施保证食品温度符合食品安全要求。' WHERE id = 'd416b9a6-ba88-4bc2-a0cd-e6ac944d89bf';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第四十四条第一款规定，食品生产经营企业的主要负责人应当落实企业食品安全管理制度，对本企业的食品安全工作全面负责。' WHERE id = 'd41a96f1-3535-48cf-90e6-2793523ed327';
UPDATE public.questions SET analysis = '依据《食品经营许可和备案管理办法》第三十条规定，食品经营者应当妥善保管食品经营许可证，不得伪造、涂改、倒卖、出租、出借、转让。违反规定的将被责令改正并处罚款。' WHERE id = 'd4370d74-a3a5-4693-8dd5-74ad9e840793';
UPDATE public.questions SET analysis = '依据《新食品原料安全性审查管理办法》第二条规定，新食品原料是指在我国无传统食用习惯的以下物品：动物、植物和微生物；从动物、植物和微生物中分离的成分；原有结构发生改变的食品成分；其他新研制的食品原料。' WHERE id = 'd444196a-1944-44ba-b22f-0f95f7ca983e';
UPDATE public.questions SET analysis = '依据GB 14881-2013，应在洗手设施旁标示洗手方法；与消毒设施配套的水龙头开关应为非手动式。选项A和B的表述不正确，符合题目要求选择''不正确''的选项。' WHERE id = 'd45409ae-c0f1-4de2-925d-385ed9f4e4b1';
UPDATE public.questions SET analysis = '依据《食品安全法》第六十八条规定，在散装食品贮存位置应当标明食品的名称、生产日期或者生产批号、保质期、生产者名称及联系方式等内容。' WHERE id = 'd457357e-9bea-4023-b796-572bdeb1a1ea';
UPDATE public.questions SET analysis = '依据《中华人民共和国反食品浪费法》第十五条，食品生产经营者应当采取措施，改善食品储存、运输、加工条件，防止食品变质，降低储存、运输中的损耗。' WHERE id = 'd45d0696-fb09-4fd1-a400-9558f49dff4d';
UPDATE public.questions SET analysis = '依据《食品经营许可和备案管理办法》第十二条，简单制售食品安全风险较低食品的，在符合食品经营许可审查通用要求的同时，应取得相应食品经营项目许可，可以适当简化设备设施、专门区域等审查内容。题目表述基本正确。' WHERE id = 'd45e7d65-2929-4f11-b3a3-7cfcfd479cd5';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》，健康晨检发现从业人员有发热、腹泻、皮肤伤口或感染、咽部炎症等有碍食品安全病症的，应立即调离接触直接入口食品的工作岗位，待查明原因并将有碍食品安全的疾病治愈后方可重新上岗。' WHERE id = 'd476a928-6a48-4eec-a128-6f740ce84737';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第8.5.2条规定，食品生产企业使用包装材料时应核对标识，避免误用，如实记录包装材料的使用情况。' WHERE id = 'd47b9db5-69fe-4df0-b837-e29035706985';
UPDATE public.questions SET analysis = '依据《新食品原料安全性审查管理办法》规定，新食品原料生产单位应当按照新食品原料公告要求进行生产，保证新食品原料的食用安全。' WHERE id = 'd47fca7c-5986-4ec6-adbc-2b838de51c1d';
UPDATE public.questions SET analysis = '依据《黄酒生产许可审查细则》及黄酒生产HACCP应用指南，黄酒加工过程建议对微生物进行监控，其中菌落总数是反映生产过程卫生状况的重要指标。' WHERE id = 'd48253a7-a499-478b-9e5a-f4c0e9ed8f12';
UPDATE public.questions SET analysis = '依据GB 2760-2014及《餐饮服务食品安全操作规范》，食品添加剂的使用必须按照标准规定的使用范围和使用限量准确计量添加，严禁凭经验、凭感觉添加。' WHERE id = 'd4893e75-6049-43e1-b58d-ef8b66bd2542';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第三十三条及《食品经营过程卫生规范》（GB 31621-2014），对有湿度要求的食品，应当按照其特性满足相应的温湿度要求贮存。' WHERE id = 'd490498a-4a75-4fdb-b8e0-3b67272b04ea';
UPDATE public.questions SET analysis = '依据GB 14881-2013，物料传递口常开会导致交叉污染；垃圾未密闭会导致虫害和微生物污染；仓库无通风设施会导致原料变质。成品离地离墙存放是正确做法，不属于风险隐患。' WHERE id = 'd49ace38-9b91-4abf-a304-7e297598e664';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》，蔬菜制品许可范围包括酱腌菜、蔬菜干制品、食用菌制品和其他蔬菜制品四个类别。' WHERE id = 'd49b6465-eec4-4789-b54e-a22a6eb9a2ec';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 预包装食品标签通则》（GB 7718-2011）2.1条，预包装食品是指预先定量包装或者制作在包装材料和容器中的食品，包括预先定量包装以及预先定量制作在包装材料和容器中并且在一定量限范围内具有统一的质量或体积标识的食品。仅有预先包装不一定属于预包装食品。' WHERE id = 'd49f3b9b-82c7-4053-80f0-33377a0cddec';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》及茶叶相关生产许可审查细则，茶叶茶氨酸生产按茶制品生产许可管理。' WHERE id = 'd49fd98e-32a2-4039-a95f-9fab9523022d';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第三十四条，肉制品生产过程中使用非食品原料、回收食品、食品添加剂以外的化学物质、超过保质期的食品原料和食品添加剂均属于非法添加行为，严格禁止。' WHERE id = 'd4b6635e-6dba-40d5-b6d5-7a818ea96eba';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 动物性水产制品》（GB 10136-2014）及水产制品生产规范，经冷冻后进行包装时，包装操作应在温度可控的环境中进行，确保冷冻制品中心温度低于-18℃。' WHERE id = 'd4ddffbf-58cf-4c05-ac34-bd78e00756db';
UPDATE public.questions SET analysis = '依据《关于''三新食品''目录及适用的食品安全标准的公告》（2023年第4号），该公告由国家卫生健康委员会发布，汇总整理了新食品原料、食品添加剂新品种和食品相关产品新品种目录及适用的食品安全标准。' WHERE id = 'd502f9d7-2149-4e37-899e-a6f53838c8d9';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第四十五条第二款规定，从事接触直接入口食品工作的食品生产经营人员应当每年进行健康检查，取得健康证明后方可上岗工作。' WHERE id = 'd516a71e-a034-4617-9b3d-f64a40afa54e';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第四十条第一款规定，食品添加剂应当在技术上确有必要且经过风险评估证明安全可靠，方可列入允许使用的范围。' WHERE id = 'd5194d9c-f858-4909-8b44-6dd66a479bf3';
UPDATE public.questions SET analysis = '依据《食品安全抽样检验管理办法》第十一条规定，抽样人员应按照''随机选取抽样对象、随机确定抽样人员''的要求，由至少2名抽样人员出示抽样检验告知书及有效身份证明文件后开展抽样工作。' WHERE id = 'd5254490-d8cd-4607-842f-e3856a346b40';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食用动物油脂》（GB 10146-2015）第3.1条规定，未按规定进行检疫或者检疫不合格的肉类不得作为食用动物油脂原料。' WHERE id = 'd542b726-528e-44b0-a498-7fd0712b55a0';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第三条，食品生产经营企业应当收集食品安全风险信息，建立基于食品安全风险防控的动态管理机制，结合自身实际，落实自查要求，制定食品安全风险管控清单。' WHERE id = 'd55fd1ac-722f-4815-9c03-a68cb7e5f7a9';
UPDATE public.questions SET analysis = '依据《茶叶加工技术规程》及茶叶分类标准，白茶的基本加工工艺为萎凋和干燥，不经过杀青工序。杀青是绿茶加工的基本工艺。' WHERE id = 'd590ae16-f6a0-4354-8d6f-47c04134c21a';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品中农药最大残留限量》（GB 2763-2021），该标准对茶叶产品规定了106项农药残留限量要求，是我国茶叶农药残留管控的重要标准依据。' WHERE id = 'd5915f3d-9033-4970-9d98-de8974bd0e16';
UPDATE public.questions SET analysis = '依据《蛋制品生产许可审查细则》及食品安全国家标准，蛋制品生产过程应严格执行杀菌工序，这是保证蛋制品食用安全、防止沙门氏菌等致病菌污染的关键控制环节。' WHERE id = 'd5b5810b-8908-4bf5-aabd-fe1f42e7c170';
UPDATE public.questions SET analysis = '依据《食品生产许可审查通则》及水果制品生产规范，生产水果制品所用的原料除应符合农产品相关标准外，还应符合相应的食品安全国家标准和行业标准，题目表述不够全面。' WHERE id = 'd5daafed-6eb8-46ae-a455-bcecfcdc14de';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第七十一条规定，注册申请人以欺骗、贿赂等不正当手段取得保健食品注册证书的，由国家食品药品监督管理总局撤销保健食品注册证书，并处1万元以上3万元以下罚款。' WHERE id = 'd5dc5a8f-92e7-4489-97b9-4776c02aaad6';
UPDATE public.questions SET analysis = '依据《特殊医学用途配方食品注册管理办法》第二条第三款规定，医疗机构配制的供病人食用的营养餐不属于特殊医学用途配方食品。特殊医学用途配方食品是指为满足进食受限等特定疾病状态人群对营养素或膳食的特殊需要而加工配制的配方食品。' WHERE id = 'd5dfa489-41ad-478b-a490-4ef5598c890f';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》，加工制作现榨果蔬汁、食用冰等的用水，应为预包装饮用水、使用符合相关规定的水净化设备或设施处理后的直饮水或煮沸冷却后的生活饮用水。' WHERE id = 'd5ec1ed9-2cfe-4e00-b406-3d07e4ba3c0f';
UPDATE public.questions SET analysis = '依据《食品经营过程卫生规范》及《特殊食品销售监管指引》，特殊食品销售区域应当设立提示牌，注明''****销售专区（或专柜）''字样，提示牌为绿底白字（绿底白字为保健食品销售专区的统一标识要求）。' WHERE id = 'd6031f10-335c-4e99-813f-db0712930dac';
UPDATE public.questions SET analysis = '依据《特殊医学用途配方食品注册管理办法》第二十条规定，注册审评机构认为申请材料真实、产品科学安全、生产工艺合理可行和质量可控、技术要求和检验方法科学的，应当提出予以注册的建议。' WHERE id = 'd60a2d8a-2260-46a9-ad43-c98f7de2c595';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 孕妇及乳母营养补充品》（GB 31601-2015），孕妇及乳母营养补充品的原料中优质蛋白应来源于大豆、大豆制品、乳类、乳制品中的一种或一种以上。' WHERE id = 'd60b7835-133d-4536-bb99-f8c8fbc4a865';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 预包装食品标签通则》（GB 7718-2011）4.1.7.2条，当同一包装内含有多个标示了生产日期及保质期的单件食品添加剂时，外包装上标示的保质期应按最早到期的单件食品添加剂的保质期计算。' WHERE id = 'd639cc1d-7f13-454c-b2d7-1a008b50e49b';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013），应保持食品包装、贮存容器的密闭良好，防止在加工、贮存、销售等环节的虫害侵入。' WHERE id = 'd63e492d-a50f-4f07-92c2-69d23561fea2';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》及食品安全标准体系相关规定，强制性食品安全标准是食品标准体系的核心和底线，具有强制执行力，食品生产经营者必须严格执行。' WHERE id = 'd648ba5e-458a-4e22-a9dd-f0fcb895bdcc';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）及食品贮运管理要求，食品贮存运输过程中的污染途径包括不清洁容器带来的污染、前运货物带来的污染、货物混运带来的污染以及运输工具卫生状况差等。' WHERE id = 'd651ad39-f6f8-4ef0-8e53-f5fe1451a837';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 酱腌菜》（GB 2714-2015），非灭菌发酵型酱腌菜不需要检测大肠菌群，只需检测沙门氏菌和金黄色葡萄球菌。大肠菌群指标仅适用于灭菌发酵型酱腌菜。' WHERE id = 'd660bc90-6778-4a51-b29a-ffede28a20f9';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品中污染物限量》（GB 2762-2022），酱腌菜中铅限量为0.5mg/kg。' WHERE id = 'd66236b0-f553-4ee6-9621-c9bcf75eba02';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 稀奶油、奶油和无水奶油》（GB 19646-2010），奶油（黄油）是以乳和（或）稀奶油（经发酵或不发酵）为原料，添加或不添加其他原料、食品添加剂和营养强化剂，经加工制成的脂肪含量不小于80.0%的产品。' WHERE id = 'd6689a83-a37e-4798-a429-68c56866681e';
UPDATE public.questions SET analysis = '依据《食品经营过程卫生规范》（GB 31621-2014）及《食品经营许可审查通则》，销售场所应布局合理，食品销售区域和非食品销售区域分开、生食和熟食区域分开、待加工食品与直接入口食品区域分开、水产品区域与其他食品经营区域分开。' WHERE id = 'd66c9212-63a5-4ecb-98ae-c8cbb55e09a8';
UPDATE public.questions SET analysis = '依据《薯类食品生产许可审查细则》及相关食品安全标准，薯类食品中容易出现的食品安全问题主要有微生物指标超标、超范围超限量使用食品添加剂、油炸产品酸价和过氧化值超标等。' WHERE id = 'd672557b-a973-48fc-85db-89992bfd69eb';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 预包装食品营养标签通则》（GB 28050-2011），营养标签强制标示内容包括能量、蛋白质、脂肪、碳水化合物和钠等核心营养素的含量值及其占营养素参考值（NRV）的百分比。' WHERE id = 'd673d11a-cad8-4622-bf9e-1a5bbc70ab5f';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》，其他罐头（类别编号0903）包括果仁类罐头、八宝粥罐头等。肉酱类罐头属于畜禽水产罐头，豆类罐头和食用菌罐头属于蔬菜罐头。' WHERE id = 'd677b87a-abe8-4a0d-b587-a832bd5f979e';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》及食品安全法律法规体系，食品生产经营者应按照食品安全法律法规、规章、标准和规范性文件建立相关食品安全管理制度，这是落实企业食品安全主体责任的基本要求和保障措施。' WHERE id = 'd6801a40-3323-4168-ad82-0d20a91f199c';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 果冻》（GB 19299-2015），果冻的微生物指标包括大肠菌群、霉菌和酵母、致病菌（沙门氏菌）。其中霉菌是果冻产品重点控制的微生物指标之一。' WHERE id = 'd6802af0-36a7-477d-8819-82acd29527c5';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）及食品贮存管理要求，环境温湿度控制不当和包装密封性不良，易造成半成品或成品在生产或贮存过程中吸湿水分超标，引起产品霉变。' WHERE id = 'd6808f58-b2a1-44d9-9dd6-275c7892c580';
UPDATE public.questions SET analysis = '依据《网络餐饮服务食品安全监督管理办法》规定，从事网络餐饮经营的餐饮服务提供者应网上公示信息与实际一致、送餐食品包装严密防止污染、有温度要求的食品采取相应措施、可委托具备相应能力的企业送餐。' WHERE id = 'd6840ec2-0334-4100-9684-b4d09a58b32c';
UPDATE public.questions SET analysis = '依据市场监管总局关于压片糖果产品的抽检监测情况及消费提示，压片糖果产品常见的问题是违法添加非食用物质或药物成分，如某些声称具有特定功能的压片糖果非法添加西药成分。' WHERE id = 'd688ba08-34a0-4023-b88c-79ac77b025ac';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 预包装食品标签通则》（GB 7718-2011）2.2条，食品标签包括食品包装上的文字、图形、符号及一切说明物。' WHERE id = 'd6893e57-1c2a-43fa-8d2f-7709f5c33d4b';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第十四条，食品安全监督管理部门应当公布食品安全管理人员监督抽查考核结果，并建立食品安全管理人员信用档案。考核结果应当公布。' WHERE id = 'd68d4f6c-6af1-4a56-b931-088a4b057e75';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 蒸馏酒及其配制酒》（GB 2757-2012）及啤酒相关标准，啤酒的食品安全限量指标包括铅、甲醛和二氧化硫等。高级醇和展青霉素不属于啤酒的食品安全限量指标。' WHERE id = 'd6a7f1fd-9dab-426f-a45a-8439d0293fbc';
UPDATE public.questions SET analysis = '依据国家卫生健康委员会《关于依法查处生产经营含金银箔粉食品违法行为的通知》，金银箔粉未列入GB 2760，不属于食品添加剂，不是食品原料，不能用于食品生产经营。' WHERE id = 'd6bf9e5e-d772-4fde-9bab-c44aef231025';
UPDATE public.questions SET analysis = '依据《食品中可能违法添加的非食用物质和易滥用的食品添加剂名单》（整顿办函〔2011〕1号等），该名单中的物质在食品生产经营环节应坚决杜绝违法添加，违反者将依法追究法律责任。' WHERE id = 'd6c33110-7185-4164-b93a-25d04e9f1609';
UPDATE public.questions SET analysis = '依据《黄酒生产许可审查细则》及黄酒生产工艺要求，黄酒勾兑完成的半成品酒不宜存放时间过长，必要时应进行冷冻处理，以去除酒中的悬浮物和沉淀物，提高酒的稳定性。' WHERE id = 'd6cc6996-1257-40fd-8df9-9bb182e31d16';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第一百三十五条第二款规定，因食品安全犯罪被判处有期徒刑以上刑罚的，终身不得从事食品生产经营管理工作，也不得担任食品生产经营企业食品安全管理人员。' WHERE id = 'd6d485f9-fba5-4a57-8be1-1782d616b8dc';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 水产调味品》（GB 10133-2014），水产调味品中大肠菌群的限量为n=5，c=2，m=10CFU/g(mL)，M=100CFU/g(mL)。' WHERE id = 'd6dddd7a-248c-45ef-b181-dab8667987fc';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品添加剂使用标准》（GB 2760-2014），葡萄酒中食品添加剂（如二氧化硫等）的限量应符合GB 2760的规定。GB 2761为真菌毒素限量标准，GB 2762为污染物限量标准，GB 2763为农药残留限量标准。' WHERE id = 'd6df8e38-1e55-4978-b01f-4d3c1b1c94b2';
UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》第四十条规定，企业依法终止、注册证书有效期届满未延续、注册依法被撤销撤回或注册证书被吊销的，应当注销婴幼儿配方乳粉产品配方注册。' WHERE id = 'd7105f37-661d-46de-bdd0-33ead8818fbb';
UPDATE public.questions SET analysis = '依据《黄酒生产许可审查细则》，根据生产工艺需要，黄酒生产区应设置原料仓库、制曲、制酒、灌装、贮存陈酿等区域，各区域应布局合理，防止交叉污染。' WHERE id = 'd710a6ad-3cad-41d1-80a1-115c83e8e01a';
UPDATE public.questions SET analysis = '依据《食品经营过程卫生规范》（GB 31621-2014）及冷藏冷冻管理要求，食品销售场所应使用具有封闭结构的冷藏冷冻设施设备，不宜使用敞开式设备，以保持冷藏冷冻效果并防止食品污染。' WHERE id = 'd738a04c-0984-40e5-9964-667ea4b2e108';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食糖》（GB 13104-2014），赤砂糖是以甘蔗为原料，经提取糖汁、清净处理等工艺加工制成的带蜜的棕红色或黄褐色砂糖。' WHERE id = 'd74e6a66-e675-4db7-acb5-138d111c6d6a';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》及《企业落实食品安全主体责任监督管理规定》，连锁餐饮服务企业总部要结合实际和舆情反映，依法定期对总部、中央厨房、配送中心、门店等各环节全面开展食品安全自查。' WHERE id = 'd779f5fc-bd6c-4bb5-a848-eb8c0f77bfec';
UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》第八条，申请婴幼儿配方乳粉产品配方注册应当提交注册申请书和产品检验报告。生产流程说明和产品配方策划报告不属于必须提交的材料。' WHERE id = 'd7915b32-1b51-48aa-bd05-2fbc34cda24f';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 饼干》（GB 7100-2015），饼干的主要食品安全指标包括酸价、过氧化值、菌落总数、大肠菌群和霉菌等，涉及油脂氧化指标和微生物指标。' WHERE id = 'd796b952-b9ba-4c75-a56e-4a6b225f228e';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第二十五条及食品安全标准体系相关规定，强制性食品安全标准是食品标准体系的核心和底线，是保障公众身体健康的技术要求，具有法律强制力。' WHERE id = 'd7985d7d-8056-48e4-a4e5-0e8b0fa17a27';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第四十三条规定，保健食品注册证书因遗失申请补发的，应当在省、自治区、直辖市食品药品监督管理部门网站上发布遗失声明；因损坏申请补发的，应当交回注册证书原件。' WHERE id = 'd7a1814f-41cf-4130-9433-46687817483a';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第三十四条第一款第（十一）项及第六十七条规定，禁止生产经营无标签的预包装食品、食品添加剂。预包装食品必须具有标签。' WHERE id = 'd7a2ccdc-22b5-41f8-ae6c-8174761937a1';
UPDATE public.questions SET analysis = '依据《中华人民共和国行政许可法》第十四条、第十五条规定，法律可以设定行政许可；尚未制定法律的，行政法规可以设定；必要时国务院可采用发布决定的方式设定；地方性法规可设定；省级政府规章可设定临时性行政许可。' WHERE id = 'd7c7e24b-016a-4b1f-b039-0cd7b44c18d8';
UPDATE public.questions SET analysis = '依据GB 14881-2013第6.3.2.2条规定，进入作业区域不应佩戴饰物、手表，不应化妆、染指甲、喷洒香水；不得携带或存放与食品生产无关的个人用品。不得穿个人服装进入作业区域。' WHERE id = 'd7eb7258-e308-4fda-8836-312241e71d62';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》第三条规定，同一个食品生产者从事食品生产活动，只能取得一个食品生产许可证。同一主体不得持有多个食品生产许可证。' WHERE id = 'd7f4a29c-2395-4c58-89bb-582ed5bbe437';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品中农药最大残留限量》（GB 2763-2021），大豆中2,4-滴丁酯的最大残留限量为0.05mg/kg。' WHERE id = 'd7fa6422-e99a-49e7-bd99-f87938cf8806';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 饮用天然矿泉水》（GB 8537-2018），锂、锶、锌、偏硅酸、硒、游离二氧化碳、溶解性总固体属于界限指标，是区分矿泉水与普通饮用水的重要特征指标。' WHERE id = 'd7fc50ec-c250-45ef-a1ea-ea6c4ffcfde8';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第三条，食品安全工作实行预防为主、风险管理、全程控制、社会共治的原则，建立科学、严格的监督管理制度。这四项原则是食品安全治理的基本方针。' WHERE id = 'd8127a17-2ba7-411c-a683-ef5a538c9f0f';
UPDATE public.questions SET analysis = '依据《餐饮服务食品安全操作规范》及《餐饮服务许可审查规范》，餐饮服务场所的相邻胶帘条的重叠部分不少于2cm，以防止虫害侵入。' WHERE id = 'd832f0e8-efe7-4184-965a-d6fe8f3d653f';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》第三条规定，同一个食品生产者从事食品生产活动，应当取得一个食品生产许可证。生产饮料及酒类的同一企业只需申请一个食品生产许可证，许可证上载明多个食品类别即可。' WHERE id = 'd84cc1f0-9859-4821-93d7-8ee4d0d7218e';
UPDATE public.questions SET analysis = '依据《中华人民共和国消费者权益保护法》第六条规定，保护消费者的合法权益是全社会的共同责任。国家鼓励、支持一切组织和个人对损害消费者合法权益的行为进行社会监督。' WHERE id = 'd85c4176-1e30-4bc2-9a8e-d80c3ef4cd52';
UPDATE public.questions SET analysis = '依据《食品经营许可和备案管理办法》及《学校食品安全与营养健康管理规定》，职业学校、普通中等学校、小学、特殊教育学校、托幼机构的食堂原则上不得申请冷食类、生食类食品制售，可以申请制售自制饮品。' WHERE id = 'd86b240c-dcbc-4b67-9c48-dbbb81484657';
UPDATE public.questions SET analysis = '依据《学校食品安全与营养健康管理规定》第十七条，学校食堂用于保存食品的冷藏冷冻设备应当贴有标识，原料、半成品和成品应当分柜存放。食品库房不得存放有毒、有害物品。' WHERE id = 'd87dfb01-b47e-4e80-94ee-1cd951cf3381';
UPDATE public.questions SET analysis = '依据《食品经营许可和备案管理办法》第二十一条规定，食品经营许可证发证日期为许可决定作出的日期，有效期为五年。题目中''有效期为3年''的说法错误。' WHERE id = 'd887a52b-cb3d-48c8-844b-0747f55916e1';
UPDATE public.questions SET analysis = '依据市场监管总局关于凝胶糖果产品的抽检监测情况及消费提示，凝胶糖果产品常见的问题是夸大虚假等宣传，如声称具有减肥、降血糖、壮阳等功能但实际为普通食品。' WHERE id = 'd88dae3e-4dad-4250-aa44-d039b7d78e56';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第三十三条、第四十四条、第四十五条及GB 14881-2013，食品生产企业依法应当保持生产场所和条件持续符合食品安全要求；建立健全食品安全管理制度，配备食品安全管理人员；组织职工进行食品安全知识培训；组织接触直接入口食品的人员进行健康检查。' WHERE id = 'd89882c7-fe8c-4f9f-a366-eeb4b755d967';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第三十五条第三款规定，仅销售预包装食品的，应当报所在地县级以上地方人民政府食品安全监督管理部门备案。' WHERE id = 'd8e52271-aa84-4917-b362-b83a5b3e0ccc';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）及危害分析相关要求，常见的物理性危害包括金属或零部件碎屑、碎玻璃、碎石、碎骨、放射性物质、包装材料、人员佩戴饰物以及温度、光照等导致的食品性状非预期改变。' WHERE id = 'd8f3d99a-da59-46fa-9551-254983653c4a';
UPDATE public.questions SET analysis = '依据《乳制品良好生产规范》（GB 12693-2010）及HACCP原理，乳制品生产过程中的风险包括生物性风险（微生物污染）、化学性风险（清洗剂残留、重金属等）和物理性风险（异物、玻璃碎片等）。' WHERE id = 'd8f7e4af-e98b-4f38-98a5-010f8962f87e';
UPDATE public.questions SET analysis = '依据《婴幼儿配方乳粉产品配方注册管理办法》第三十四条，婴幼儿配方乳粉标签应当标注注册证号、适用月龄（可同时使用''1段、2段、3段''标注），营养成分表应按标准规定的顺序列出。不得标注功能性表述如''益智、增加抵抗力''等。' WHERE id = 'd8fbf720-7dde-4cc8-863d-66d67c6a290c';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》，实施食品生产许可证管理的食用油、油脂及其制品包括食用植物油、食用油脂制品和食用动物油脂三个类别。' WHERE id = 'd8ffa436-63fd-4881-8855-e16a3435782c';
UPDATE public.questions SET analysis = '依据《市场监督管理严重违法失信名单管理办法》第二条，对违反法律、行政法规，性质恶劣、情节严重、社会危害较大，受到市场监督管理部门较重行政处罚的食品生产经营企业，列入严重违法失信名单。' WHERE id = 'd904ceaa-d9f5-4664-a819-7226e14c44cb';
UPDATE public.questions SET analysis = '依据《食品生产许可管理办法》第五十条规定，许可申请人隐瞒真实情况或者提供虚假材料申请食品生产许可的，由县级以上地方市场监督管理部门给予警告，申请人在1年内不得再次申请食品生产许可。' WHERE id = 'd90c8b14-0f90-4913-8ab2-4c10b6706caa';
UPDATE public.questions SET analysis = '依据《企业落实食品安全主体责任监督管理规定》第五条，大中型食品销售企业、连锁食品销售企业总部、大中型食品生产企业等企业应当细化制定《食品安全总监职责》《食品安全员守则》等制度文件。' WHERE id = 'd9138b9e-a53d-439d-ab07-11d982fbd6c0';
UPDATE public.questions SET analysis = '依据《食品生产许可分类目录》，蜂产品许可范围包括蜂蜜、蜂花粉、蜂王浆（含冻干品）、蜂产品制品。巢蜜不属于单独的生产许可类别，可按蜂蜜类别管理。' WHERE id = 'd921f034-8da4-4858-bb88-1e731c0a66be';
UPDATE public.questions SET analysis = '依据《葡萄酒及果酒生产许可审查细则》，葡萄酒及果酒加工灌装的基本生产流程包括澄清处理、调配、除菌、灌装等工序。' WHERE id = 'd9220c4a-9bb8-4bf7-905a-cd48c71673f3';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第五十三条，进货查验记录应当如实记录食品的名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容。' WHERE id = 'd923ae30-a443-4ab9-8327-0db1663115c4';
UPDATE public.questions SET analysis = '依据《保健食品注册与备案管理办法》第五十七条规定，变更保健食品注册申请的理由依据充分合理，不影响产品安全性、保健功能和质量可控性的，予以变更注册。' WHERE id = 'd93401b5-d059-412c-9cbc-1cc18f8e6880';
UPDATE public.questions SET analysis = '依据《中华人民共和国行政处罚法》第六十三条规定，行政机关作出责令停产停业、吊销许可证或者执照、较大数额罚款等行政处罚决定之前，应当告知当事人有要求举行听证的权利。' WHERE id = 'd9343651-b153-4d09-a390-f2738a9c8190';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第二十九条，保健食品、食品添加剂、婴幼儿配方食品等特殊食品不得制定食品安全地方标准。地方标准仅适用于地方特色食品。' WHERE id = 'd9599a5f-fc9f-4f00-9916-a9584774129f';
UPDATE public.questions SET analysis = '依据《食用农产品市场销售质量安全监督管理办法》第十二条规定，集中交易市场开办者应当查验入场食用农产品的进货凭证和产品质量合格凭证，与入场销售者签订质量安全协议。' WHERE id = 'd96856df-9113-40f5-b367-eaeae5016775';
UPDATE public.questions SET analysis = '依据《食品安全国家标准 方便面》（GB 17400-2015），方便面的感官要求中滋味、气味应为无异味、无异嗅。' WHERE id = 'd96cace1-1db5-4942-83d0-8a02e1efe68c';
UPDATE public.questions SET analysis = '依据《中华人民共和国食品安全法》第七十四条及《特殊食品销售监管指引》，销售特殊食品应当核对食品标签、说明书内容是否与注册或者备案的标签、说明书一致，不一致的不得销售。' WHERE id = 'd97737b0-7a5b-4c3e-8e35-3c9785d918d0';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，从业人员操作前必须洗手消毒，佩戴手套不能替代手部清洗消毒。手套本身可能存在破损或污染风险，且佩戴前后均需保持手部清洁，否则仍会造成食品污染。' WHERE id = 'd97a9b9d-1b7d-472f-959d-bd8d12cbbcca';
UPDATE public.questions SET analysis = '《食品安全法》第三十五条规定，从事食品生产经营活动应当依法取得许可，未取得食品生产经营许可从事食品生产经营活动的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品，并处罚款。应先取得许可后从事经营活动。' WHERE id = 'd97ba76a-8b4d-4091-a91d-9f626302ee39';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第四十条规定，食品生产经营者收到监督抽检不合格检验结论后，应当立即采取封存不合格食品、暂停生产经营不合格食品、通知相关生产经营者和消费者、召回已上市销售的不合格食品等风险控制措施。' WHERE id = 'd990f298-8ae3-4a2d-a1d3-5386c853b488';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，监督检查结果对消费者有重要影响的，食品生产经营者应当在食品生产经营场所醒目位置张贴或公开展示监督检查结果记录表，并保持至下次监督检查。这是保障消费者知情权的重要制度。' WHERE id = 'd9994023-c529-478d-9655-115db0b39d42';
UPDATE public.questions SET analysis = '《食品安全法》第八条明确规定，县级以上地方人民政府实行食品安全监督管理责任制，上级人民政府负责对下一级人民政府的食品安全监督管理工作进行评议、考核。该表述正确。' WHERE id = 'd99d3c0d-a2d4-4d98-8a59-9f13e850459f';
UPDATE public.questions SET analysis = '《食用农产品市场销售质量安全监督管理办法》规定，销售获得无公害农产品、绿色食品、有机农产品认证的食用农产品以及省级以上农业行政部门规定的其他需要包装销售的食用农产品应当包装，并标注相应标志和发证机构。三种认证均需要包装标注。' WHERE id = 'd99d67f1-b542-4eed-a52e-24640882a644';
UPDATE public.questions SET analysis = 'GB 29921-2021《食品安全国家标准 预包装食品中致病菌限量》适用于预包装食品，包括冷冻饮品。该标准对冷冻饮品中的沙门氏菌、单核细胞增生李斯特氏菌等致病菌指标有明确限量要求，故题目说法错误。' WHERE id = 'd9a3249f-9a66-4e61-87e8-11cc834747e8';
UPDATE public.questions SET analysis = '虫害侵入食品或食品加工环境会带来生物性危害（携带微生物、寄生虫）、化学性危害（自身产生毒素）和物理性危害（携带异物）。这三种危害类型是食品安全风险评估的基本分类。选项D毒理性不属于独立危害类别。' WHERE id = 'd9a8f251-005a-4def-879c-2466a558b239';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》规定，其他食品的许可范围为其他食品一个类别，许可明细为其他食品（具体品种明细）。该表述符合食品生产许可分类管理的规定，说法正确。' WHERE id = 'd9b23e13-d70f-41e1-8a10-fe43217e56c4';
UPDATE public.questions SET analysis = '根据GB 30616《食品安全国家标准 食品用香精》及GB 2760规定，生姜精油属于食品用香料（天然香料），是从植物中提取的具有香味的物质，可用于食品调香。它不属于食品用香精（混合物）、增味剂或抗氧化剂。' WHERE id = 'd9c67fd7-2ac2-4e18-baf7-e351426daf92';
UPDATE public.questions SET analysis = '《食品安全法》及《保健食品经营管理规定》明确，保健食品经营企业不得经营无检验合格报告、无进口检疫合格证明、感官性状异常、超过保质期的保健食品。以上四种情形均属于禁止经营的范畴。' WHERE id = 'd9cfebed-4de2-4a9f-9fd1-c3d5c8868432';
UPDATE public.questions SET analysis = '根据GB 14880《食品安全国家标准 食品营养强化剂使用标准》，钙、锌、铁、硒均不能用于巧克力、代可可脂巧克力及其制品的矿物质强化。该类产品并非允许强化的食品类别。' WHERE id = 'd9e5ec4a-f2bc-493f-b1cb-eefb46d625cd';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第二十九条规定，经营单位应当对过期、报废或者回收的特殊食品进行显著标示或者单独存放在有明显标志的场所，及时采取无害化处理、销毁等措施并记录。该表述正确。' WHERE id = 'd9fb940d-c42f-43e1-8d72-76beb4f89af9';
UPDATE public.questions SET analysis = '《食品安全法》第八十七条规定，食品抽样检验是食品安全监督管理部门的法定职责。卫生健康行政部门负责风险监测和标准制定，农业行政部门负责农产品质量安全监管，生态环境部门负责环境保护。' WHERE id = 'da07ce30-e16f-4536-89c8-d5d0881417f8';
UPDATE public.questions SET analysis = 'GB 19300《食品安全国家标准 坚果与籽类食品》规定，霉菌≤25 CFU/g适用于经油炸或烘焙等熟制加工工艺的坚果与籽类食品，不限于仅油炸工艺。题目缩小了适用范围，故说法错误。' WHERE id = 'da0a5876-03c8-4d28-9715-af6c3bc5a423';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，食品生产经营企业应当配合监督检查，按要求开放食品生产经营场所，回答相关询问，提供相关合同、票据、账簿以及前次监督检查结果和整改情况等资料。选项C不属于法定配合义务。' WHERE id = 'da0ff1bb-58a4-4c5a-bcfa-9f6ef1d24a28';
UPDATE public.questions SET analysis = '《食品安全法》及GB 2760规定，食品添加剂的主要作用包括改善食品品质、防腐、保鲜等。降低成本不是食品添加剂的法定使用目的，超范围或超量使用以降低成本属于违法行为。' WHERE id = 'da2c0577-ccfb-4498-a4c3-afd8d72190f4';
UPDATE public.questions SET analysis = '《食品生产许可分类目录》规定，糖果制品实施生产许可的类别包括：糖果、巧克力及巧克力制品、代可可脂巧克力及代可可脂巧克力制品、果冻。以上四项均需取得生产许可。' WHERE id = 'da2cb73f-0097-4c10-bb82-ce9920eba31e';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，从业人员使用卫生间、接触可能污染食品的物品后，从事接触直接入口食品工作的，应重新消毒手部。仅重新洗手不足以消除微生物污染风险，必须消毒。' WHERE id = 'da321270-4893-4eed-9f72-ef9a21605d6c';
UPDATE public.questions SET analysis = '《农产品质量安全法》规定，农产品生产企业和农民专业合作社应当根据质量安全控制要求自行或委托检测机构对农产品质量安全进行检测。农业社会化服务组织和销售农产品的个人不属于法定检测主体。' WHERE id = 'da4c9c4a-d18b-4a70-96cf-5aeb892cf1d8';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营者采购食品应当查验供货者的许可证和食品出厂检验合格证或其他合格证明。采购进口食品的，还应查验海关出具的入境货物检验检疫证明。该表述符合法规要求，说法正确。' WHERE id = 'da7bba5b-552b-4d08-8914-4c560aa61bbe';
UPDATE public.questions SET analysis = 'GB 10770《食品安全国家标准 婴幼儿罐装辅助食品》规定，产品分类包括泥（糊）状罐装食品、颗粒状罐装食品和汁类罐装食品。以上三类均属于婴幼儿罐装辅助食品的法定分类。' WHERE id = 'da7c8ded-1171-43f3-bd1c-9116e1fdde27';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，保健食品注册申请人或备案人应当协助食品药品监督管理部门开展与注册或备案相关的现场核查、样品抽样、复核检验、监督管理等工作。以上四项均属于协助义务。' WHERE id = 'da85d1a6-9b0d-41e0-9e82-1a7ae186272f';
UPDATE public.questions SET analysis = '肉制品生产中存在将廉价肉类、不可食用肉类、水及非肉类物质掺入高价肉品（如牛羊肉及其制品）中以获取高额利益的风险，这属于典型的掺杂使假行为，违反《食品安全法》第三十四条。该表述正确。' WHERE id = 'da881507-f34f-464f-83ce-7b0139161df0';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，具有热、冷、生、固态、液态等多种情形，难以明确归类的食品，应当按照食品安全风险等级最高的情形进行归类。这是从严管理原则的体现。' WHERE id = 'da8bdb2d-f132-4073-a0e5-22716fd8406c';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，市场监督管理部门每两年对本行政区域内所有食品生产经营者至少进行一次覆盖全部检查要点的监督检查。对高风险企业应增加检查频次。' WHERE id = 'daa09c80-ef4d-43ac-8608-0448c8155e47';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》鼓励企业建立对食品安全总监、食品安全员的激励机制，对工作成效显著的给予表彰和奖励。该表述符合法规精神，说法正确。' WHERE id = 'daba5889-1366-401c-9f67-a75f164b792c';
UPDATE public.questions SET analysis = '《食品安全法》第一百零三条规定，发生食品安全事故的单位应当立即采取措施，防止事故扩大。该表述符合法律规定，说法正确。' WHERE id = 'dacc003c-db23-4cf7-a90e-fa656e9b54ae';
UPDATE public.questions SET analysis = '国家卫生健康委员会印发的《按照传统既是食品又是中药材的物质目录管理规定》明确了食药物质的动态调整原则、纳入条件和管理规范。该表述正确。' WHERE id = 'dae2eac0-ba97-41d9-8e4e-edc9edd4a41b';
UPDATE public.questions SET analysis = '粮食加工品生产中确实存在超范围或超限量使用食品添加剂、非法添加等风险，如面粉中非法添加过氧化苯甲酰（已禁用）、大米中添加香精等。该表述正确。' WHERE id = 'daf18eb7-511e-438e-af1e-6836ebb6eec9';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，不合格食品生产经营者应当积极配合市场监督管理部门的调查处理，不得拒绝、逃避。该表述符合法律规定，说法正确。' WHERE id = 'daf50ace-de46-4161-976b-45737c4d93d9';
UPDATE public.questions SET analysis = 'GB 14881《食品安全国家标准 食品生产通用卫生规范》规定，厂区内道路应铺设混凝土、沥青或其他硬质材料，不应使用沙石等易产生扬尘的材料，以防污染食品。沙石路面易产生灰尘，不符合卫生要求。' WHERE id = 'daf776fb-40c3-4ca1-b2ec-6b5074052027';
UPDATE public.questions SET analysis = 'GB 14881规定，食品生产企业墙面应使用无毒、无味的防渗透材料建造，不易积累污垢，易于清洁，涂料不易脱落。以上四项均是食品生产企业墙面的基本要求。' WHERE id = 'daff8f52-9e5e-4e89-9b0f-8a2e00ac863d';
UPDATE public.questions SET analysis = 'GB 14881及《餐饮服务食品安全操作规范》规定，虫害控制应优先采用物理方法（如纱窗、粘鼠板、灭蝇灯等），化学消杀仅作为辅助手段且不得在食品处理区使用化学杀虫剂。优先使用化学方法可能导致食品污染。该说法错误。' WHERE id = 'db0e016b-3d0e-4892-a0a8-7df8fab78a3a';
UPDATE public.questions SET analysis = '吊白块（甲醛合次硫酸氢钠）是国家明令禁止在食品中使用的非食用物质，属于非法添加物。鸡精、白砂糖、淀粉均为合法食品原料。《食品中可能违法添加的非食用物质名单》明确禁止吊白块用于食品加工。' WHERE id = 'db0ea587-e973-4488-8f42-e52c3a7f8a73';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第二十六条规定，食品经营者应当在经营场所的显著位置悬挂或者摆放食品经营许可证正本，便于消费者监督查验。' WHERE id = 'db25ae89-47a1-4f95-896f-6ad01b9c7930';
UPDATE public.questions SET analysis = '饮料产品为改善口感、色泽或抑制微生物生长，存在超范围或超限量使用甜味剂（如糖精钠）、防腐剂（如苯甲酸）、着色剂（如柠檬黄）等风险。抗氧化剂在饮料中使用风险相对较低。' WHERE id = 'db41ca4e-e2e8-42f1-be2a-2ada6237cee0';
UPDATE public.questions SET analysis = '《食品安全法》第二十九条规定，对地方特色食品，没有食品安全国家标准的，省、自治区、直辖市人民政府卫生行政部门可以制定食品安全地方标准。食品安全国家标准制定后，该地方标准即行废止。该表述正确。' WHERE id = 'db50e167-2ebe-494a-8421-f0a4fa9873d8';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，拟从事仅销售预包装食品活动的，在办理市场主体登记注册时，可以一并进行仅销售预包装食品备案，提交仅销售预包装食品备案信息采集表即可。' WHERE id = 'db6f1bec-b53e-47ec-81dc-96ff716fd10b';
UPDATE public.questions SET analysis = 'GB 13104《食品安全国家标准 食糖》规定，红糖是以甘蔗为原料，经提取糖汁、清净处理后，直接煮制不经分蜜的棕红色或黄褐色的糖。清净处理是红糖生产的关键工艺步骤。' WHERE id = 'db7ec22a-a793-49b7-8726-4d8c17db5555';
UPDATE public.questions SET analysis = '水产调味品生产必备设备包括原料清洗设施、粉碎设备、搅拌设施、盐渍设施、发酵设施、洗瓶机、杀菌设备、包装设备等。盐渍是水产调味品加工的核心工艺设备。' WHERE id = 'db80f429-c57b-40f7-9a4c-ea138be9d3d0';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》第三十四条规定，复检结论与初检结论不一致的，复检费用由实施监督抽检的市场监督管理部门承担。该表述正确。' WHERE id = 'db913fd6-d8ff-4bce-a39f-329c81b84c22';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第四十七条规定，餐饮服务提供者伪造、涂改、倒卖、出租、出借、转让许可的，由县级以上地方市场监督管理部门责令改正，给予警告，并处1万元以上3万元以下罚款。该表述正确。' WHERE id = 'db9f63b1-ffe8-4cb4-9d85-e3b68de11b6c';
UPDATE public.questions SET analysis = 'GB 2760《食品安全国家标准 食品添加剂使用标准》规定，使用食品添加剂不应掩盖食品腐败变质，不应掩盖食品本身或加工过程中的质量缺陷，不应降低食品本身的营养价值。改善食品品质是食品添加剂的合法使用目的。' WHERE id = 'dbb1842a-d47b-4bba-9723-253091024160';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》及GB 31654规定，外卖餐配送前应对配送工具和盛装食品的容器（一次性容器除外）进行清洁，接触直接入口食品的还应消毒，防止食品受到污染。该表述正确。' WHERE id = 'dbb9d6ee-6606-41b7-9962-180a55fbeaa3';
UPDATE public.questions SET analysis = '《行政复议法》第二十五条规定，行政复议决定作出前，申请人要求撤回行政复议申请的，经说明理由，可以撤回；撤回行政复议申请的，行政复议终止。该表述正确。' WHERE id = 'dbd0ce88-26d4-42c3-a5ea-47b08cef5a6b';
UPDATE public.questions SET analysis = '《食品生产许可分类目录》规定，实施生产许可管理的蔬菜制品是指以蔬菜、食用菌为主要原料，采用腌渍、脱水等相关工艺加工而成的各种制品。食用菌是蔬菜制品的重要原料类别。' WHERE id = 'dbe5526d-c49a-4bbe-8cab-c7f6243cc254';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》规定，申请人申请企业名称变更、生产地址名称变更等不影响产品配方科学性、安全性的变更事项，审评机构应当自受理之日起10个工作日内作出结论。' WHERE id = 'dbe71093-0b36-449f-8228-056016c9e476';
UPDATE public.questions SET analysis = '《食品补充检验方法工作规定》明确，食品补充检验方法主要针对可能掺杂掺假的物质、食品安全标准检验方法未覆盖的项目等。农药、兽药、食品添加剂已有相应的国家标准检验方法。' WHERE id = 'dbf9cb12-36df-4a5d-83f0-ab89cdbec723';
UPDATE public.questions SET analysis = '除常见生物性、化学性、物理性危害外，食品生产经营过程中还存在因经济利益驱动导致的掺杂使假、蓄意破坏等人为故意造成的食品安全风险。这是非传统食品安全风险的重要表现形式。' WHERE id = 'dbfed825-ef0c-4ba9-8363-885c4255e99d';
UPDATE public.questions SET analysis = 'GB 2717《食品安全国家标准 酱油》及传统酿造工艺规定，酱油原料主要包括大豆（或脱脂大豆）、小麦（或面粉）、麸皮等。玉米不是酱油的传统酿造原料。' WHERE id = 'dc136648-5cd3-4f06-a221-2c8fffb89a92';
UPDATE public.questions SET analysis = '《食品安全法》第四十四条规定，食品生产经营企业应当组织对本企业职工进行食品安全知识培训。培训对象覆盖全体职工，而非仅限于法人、负责人或高管。' WHERE id = 'dc17f127-0e92-4b75-8d3a-53d43f029f29';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》规定，食品生产许可证正本和副本具有同等法律效力。副本主要用于企业日常经营活动中的证明，正本用于悬挂公示。' WHERE id = 'dc233a51-fc38-4c3b-82e0-35c451f739f2';
UPDATE public.questions SET analysis = '《食品安全法》第五十一条规定，食品生产企业应当建立食品出厂检验记录制度，查验出厂食品的检验合格证和安全状况，如实记录食品的名称、规格、数量、生产日期等内容，并保存相关凭证。出具合格报告后不留存原始检验记录违反法律规定。该说法错误。' WHERE id = 'dc25a046-7a48-433c-8e16-75fc6dfbf099';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》规定，注册证书及附件应当载明产品名称、注册号、批准日期及有效期、产品配方、生产工艺、产品标签和说明书等内容。企业质量负责人不属于注册证书载明事项。' WHERE id = 'dc2be0b9-66f9-4fc2-8816-f3c925a49498';
UPDATE public.questions SET analysis = '《食品安全法实施条例》是国务院颁布的与食品安全直接相关的行政法规。《餐饮服务食品安全操作规范》是部门规章/规范性文件，《食品销售指南》《农产品经营指南》不属于食品安全行政法规。' WHERE id = 'dc3622ad-fc79-4b84-9eba-07d0319847a0';
UPDATE public.questions SET analysis = '《食品安全法》第五十四条规定，食品经营者贮存散装食品应当在贮存位置标明食品的名称、生产日期或生产批号、保质期、生产者名称及联系方式等内容。品牌不属于法定标明事项。' WHERE id = 'dc4f3de7-5945-4fd3-bf03-b2e8e80c2f9f';
UPDATE public.questions SET analysis = '《刑法》第一百四十三条规定，生产、销售不符合食品安全标准的食品，对人体健康造成严重危害或者有其他严重情节的，处三年以上七年以下有期徒刑，并处罚金。后果特别严重的处七年以上有期徒刑或无期徒刑。' WHERE id = 'dc79f8f2-a545-4780-907f-369d06eace5f';
UPDATE public.questions SET analysis = '《食品添加剂生产监督管理规定》明确，并非所有食品添加剂均可申请生产许可。国家禁止使用的食品添加剂不得生产，部分食品添加剂已被列入禁用名单。该说法错误。' WHERE id = 'dc7cfede-1c18-4551-b548-63b61dcad887';
UPDATE public.questions SET analysis = '《农产品质量安全法》第四十条规定，农产品批发市场发现不符合农产品质量安全标准的，应当要求销售者立即停止销售，并向所在地市场监督管理部门和农业农村部门报告。' WHERE id = 'dc8876f4-e3e9-4007-bd3e-1b24d43fef68';
UPDATE public.questions SET analysis = '干制水产品应严格控制干燥时间、干燥温度和环境湿度，以确保干制品的水分活度在安全范围内，防止微生物生长。包装时间对水分活度控制影响较小。' WHERE id = 'dc988a77-e895-4186-a92c-6d121c8211d7';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，市场监督管理部门对高风险食品生产经营企业实施重点监督检查，但应根据实际情况增加日常监督检查频次而非体系检查频次。体系检查适用于特定情形。该表述错误。' WHERE id = 'dca1011a-90a0-4710-bb77-02ae6f93a7e6';
UPDATE public.questions SET analysis = '《食品安全法实施条例》规定，食品生产经营企业应当收集食品安全风险信息，建立基于食品安全风险防控的动态管理机制。这一义务适用于所有食品生产经营企业。' WHERE id = 'dca245bf-2814-4185-b8bb-a1989540464d';
UPDATE public.questions SET analysis = 'GB 31621及《餐饮服务食品安全操作规范》规定，冷藏冷冻设施设备应设有有效的温度控制装置，设有可正确显示内部温度的温度监测设备，并应定期校准、维护。题目中的''可以设有''''视情况校准''表述错误。' WHERE id = 'dcc43290-3ca4-459b-b961-2b96d1e34bdc';
UPDATE public.questions SET analysis = '《食品安全法》第五十条规定，食品生产企业采购食品原料、食品添加剂、食品相关产品，对无法提供合格证明的食品原料，应当按照食品安全标准进行检验，检验合格后方可使用。不得先行使用或凭经验判断。' WHERE id = 'dccc76f7-63eb-4b9c-a257-54116ba58b40';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十五条规定，因食品安全违法被吊销许可证的企业，其法定代表人、直接负责的主管人员和其他直接责任人员，自处罚决定作出之日起5年内不得担任食品安全总监、食品安全员。' WHERE id = 'dccc7d48-7b0d-4165-a653-f441b16d73b7';
UPDATE public.questions SET analysis = 'GB 2758《食品安全国家标准 发酵酒及其配制酒》规定，啤酒的食品安全限量指标包括甲醛等。高级醇、N-二甲基亚硝胺、杂醇油、总砷不属于啤酒的食品安全限量指标范畴。' WHERE id = 'dcd271b5-abf0-442d-80ae-0aef5b0339d9';
UPDATE public.questions SET analysis = '《食品生产许可管理办法》规定，食品生产许可证遗失、损坏的，应当向原发证的市场监督管理部门申请补办。食品生产许可证遗失后依法可以申请补办，并非无法补办。该说法错误。' WHERE id = 'dce2019d-a05f-43a9-b7ba-8aba5c72bcb6';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》规定，食品经营许可证遗失、损坏应向原发证部门申请补办，提交补办申请书、遗失声明或受损许可证。补办许可证编号不变，发证日期和有效期与原证书一致。该表述正确。' WHERE id = 'dce4bd36-e972-40a6-8401-b9c8f691e6cb';
UPDATE public.questions SET analysis = '《关于''三新食品''目录及适用的食品安全标准的公告》（2023年第4号）规定，新食品原料目录的食品安全标准设置18个月过渡期，给予企业充分时间调整产品和生产工艺。' WHERE id = 'dd0440a7-1a59-4bdb-af8b-a18621d06f4c';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》规定，申请首次进口保健食品注册和办理进口保健食品备案及其变更的，境外机构出具的证明文件应当经生产国（地区）的公证机构公证和中国驻所在国使领馆确认。' WHERE id = 'dd090739-5eaf-4931-94ed-ff46e5327660';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，发现不符合食品安全标准或者有证据证明可能危害人体健康的食品，食品经营者应当立即停止经营，通知相关生产经营者和消费者，并记录停止经营和通知情况。该表述正确。' WHERE id = 'dd2610d1-a6c2-4a6f-9e76-0fefd1133cd8';
UPDATE public.questions SET analysis = 'GB 2761《食品安全国家标准 食品中真菌毒素限量》规定，原料中包含苹果或山楂的水果罐头需要检测展青霉素。展青霉素主要存在于霉变苹果和山楂中。' WHERE id = 'dd29acf8-5137-4a45-a25a-f9ae302a2bf7';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止生产经营超过保质期的食品。更改保质期和降价销售均属于违法行为。正确的处置措施是禁止销售和销毁。' WHERE id = 'dd3ce8b4-59a3-43fc-a40a-4faedfb36bd1';
UPDATE public.questions SET analysis = '《食品安全抽样检验管理办法》规定，为了满足检验和复检的要求，监督抽检中的样品分为检验样品和复检备份样品。复检备份样品用于对检验结论有异议时申请复检。' WHERE id = 'dd3e249f-59d3-468b-89dc-215c0036e77e';
UPDATE public.questions SET analysis = '《食品安全法》第三十八条明确规定，生产经营的食品中不得添加药品，但是可以添加按照传统既是食品又是中药材的物质。在食品中添加普通药品属于违法行为。该说法错误。' WHERE id = 'dd3eb942-da10-4631-aa4a-805d259d89fb';
UPDATE public.questions SET analysis = '水果制品生产企业应严格按照GB 2760规定使用食品添加剂，按期对食品添加剂称量设备等进行校准，确保投料的准确性，防止超范围或超限量使用。' WHERE id = 'dd477d81-48f7-40af-b4aa-dfd83f7dca8f';
UPDATE public.questions SET analysis = '《食品安全法》第一百一十条规定，食品生产经营者应当配合食品安全监督检查，不得拒绝、阻挠、干涉。拒绝监督检查的，将依法受到处罚。该说法错误。' WHERE id = 'dd739d9c-f2b9-46d8-84a4-fda78264f316';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止用非食品原料生产食品，禁止超范围超限量使用食品添加剂，禁止用回收食品作为原料生产食品。添加按照传统既是食品又是中药材的物质的食品属于合法食品。' WHERE id = 'dd7bbd4b-6a60-4a2c-904e-5d5f8d743c8c';
UPDATE public.questions SET analysis = 'GB/T 15109《白酒工业术语》规定，固液法白酒是以固态法白酒（不低于30%）与液态法白酒勾调而成的白酒，并非半固态发酵、蒸馏的白酒。半固态发酵是米香型白酒等的发酵方式。该说法错误。' WHERE id = 'dd831105-7904-4f86-924a-d8b06411d752';
UPDATE public.questions SET analysis = '《食品安全法》第一百五十条规定，食源性疾病是指食品中致病因素进入人体引起的感染性、中毒性等疾病，不包括过敏性疾病。过敏性疾病属于食物过敏范畴。该说法错误。' WHERE id = 'dd929773-f763-434d-b67e-3d3ce54aba40';
UPDATE public.questions SET analysis = '《保健食品经营管理规定》要求，保健食品应当在经营场所划定专门的区域、柜台或货架摆放、销售，不得与普通食品或其他产品混放。这是防止误导消费者的重要措施。' WHERE id = 'dda8a31e-627d-472d-8a35-7e3226c1a52b';
UPDATE public.questions SET analysis = '《保健食品经营管理规定》要求，购进保健食品需要核对标签说明书内容与批准或备案内容的一致性，包括批准文号、保健功能、证书持有人信息、原辅料、规格、功效成分、保质期、适宜人群、食用方法等。以上各项均需核对。' WHERE id = 'ddb5c4de-9704-4bb3-8e52-2e2c28bf5b75';
UPDATE public.questions SET analysis = '根据风险评估理论，食品安全风险可分为传统食品安全风险（如微生物污染、天然毒素等）和非传统食品安全风险（如人为故意污染、蓄意破坏、食品掺假等）。' WHERE id = 'ddc81d69-193a-4ca9-a11a-880d50e18504';
UPDATE public.questions SET analysis = '《食品安全法》第六十二条规定，网络食品交易第三方平台提供者应当对入网食品经营者进行实名登记，明确其食品安全管理责任。网络食品交易第三方平台对入网经营者负有管理责任。该说法错误。' WHERE id = 'ddd40efd-8ad9-4bcd-8aac-942e6ab4b048';
UPDATE public.questions SET analysis = '《食品安全法》第七十一条规定，食品和食品添加剂与其标签、说明书所载明的内容不符的，不得上市销售。标签内容必须与食品实际情况一致。' WHERE id = 'dddae064-6dfa-487b-aae1-50d70d43819b';
UPDATE public.questions SET analysis = '《乳品质量安全监督管理条例》规定，乳制品生产企业对召回的乳制品应当采取销毁、无害化处理等措施，防止其再次流入市场。改良后重新销售和作为其他食品原料均属于违法行为。' WHERE id = 'dde8299b-d527-48a0-98d6-6a2dc625b933';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》要求，企业应当建立食品安全月调度制度，企业主要负责人每月至少听取1次食品安全总监管理工作情况汇报，形成《每月食品安全调度会议纪要》。' WHERE id = 'dde95886-0867-420a-a94d-04a18f05d71e';
UPDATE public.questions SET analysis = 'GB 10769《食品安全国家标准 婴幼儿谷物辅助食品》规定，产品营养成分表的标示应增加''100千焦（100kJ）''含量的标示，以便科学评估婴幼儿能量摄入。' WHERE id = 'dde9c99b-1585-42c9-97d7-040c7991d272';
