UPDATE public.questions SET analysis = 'GB 19644《食品安全国家标准 乳粉》规定，调制乳粉是以单一品种的生乳和（或）其全乳（或脱脂及部分脱脂）加工制品为主要原料，添加其他原料，添加或不添加食品添加剂和营养强化剂，经加工制成的乳固体含量不低于70%的粉状产品。' WHERE id = 'e18084b6-4d7e-4459-a41a-1156eff16b3a';
UPDATE public.questions SET analysis = '超范围使用食品添加剂是指在不允许添加的食品中使用了食品添加剂，超限量使用是指超过了GB 2760规定的最大使用量。按照GB 2760规定范围和使用量使用食品添加剂不属于超范围超限量使用。' WHERE id = 'e1817bc7-b7a8-4e08-8a37-b746db1ee7da';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产中使用的洗涤剂、消毒剂应当对人体安全、无害，防止对食品产生污染。使用前应充分清洗，避免残留。该表述正确。' WHERE id = 'e1943c0e-85d0-46b3-b153-10da7705f98d';
UPDATE public.questions SET analysis = '《食品生产许可分类目录》规定，炒货食品及坚果制品是以果蔬籽、果仁、坚果等为主要原料，添加或不添加辅料，经烘炒、油炸、蒸煮等工艺加工制成的制品。糖果和膨化食品不属于炒货食品及坚果制品的原料。' WHERE id = 'e19d13b7-0daa-43f6-8016-93d98f298f65';
UPDATE public.questions SET analysis = 'GB 14884《食品安全国家标准 蜜饯》规定，蜜饯产品应无霉变，无正常视力可见的外来异物，具有该产品应有的色泽、气味和滋味。该表述符合标准规定，说法正确。' WHERE id = 'e19d6136-250d-46aa-9e36-e3f18ddb129d';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第三十六条规定，医疗机构和药品零售企业之外的单位或者个人不得向消费者销售特殊医学用途配方食品中的特定全营养配方食品。该表述正确。' WHERE id = 'e1b01dd4-059e-408e-99d1-1f2e92306ba4';
UPDATE public.questions SET analysis = 'GB 17400《食品安全国家标准 方便面》及相关标准规定，方便食品是指部分或完全熟制，不经烹调或仅需简单加热、冲调就能食用的食品。冲调是方便食品的重要食用方式。' WHERE id = 'e1bfda36-c22b-4779-8058-168a78a8407c';
UPDATE public.questions SET analysis = '《食品生产经营监督检查管理办法》规定，日常监督检查结果为不符合，有发生食品安全事故潜在风险的，食品生产企业应当立即停止食品生产经营活动。这是防止食品安全事故发生的重要措施。' WHERE id = 'e1c0a868-e727-408a-bd79-cab8ce60a19c';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，与餐（饮）具的食品接触面或者食品接触的垫纸、垫布、餐具托、口布等物品应一客一换，防止交叉污染。该表述正确。' WHERE id = 'e1c1fbba-7824-4ee0-883e-28b073d8e07a';
UPDATE public.questions SET analysis = '水果制品化学性危害包括原料水果种植过程中农药残留、污染物超标，以及加工过程中超范围超限量使用食品添加剂等。种植环节的农药残留是主要化学性危害来源。' WHERE id = 'e1e624e1-45a5-45a4-9fa2-115a688f16e4';
UPDATE public.questions SET analysis = 'GB 2761规定，苹果发酵酒（如苹果酒、 cider）中存在展青霉素污染的可能。展青霉素是由扩展青霉等霉菌产生的真菌毒素，主要污染霉变苹果及其制品。' WHERE id = 'e1fcbf2b-6748-457f-9939-458d54a57e59';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条规定，禁止标注虚假生产日期。产品应在生产当天标注生产日期，不能待出厂时才标注当天日期。这种标注方式属于虚假标注生产日期，是违法行为。该说法错误。' WHERE id = 'e1fdaf24-02d6-4cfd-b063-7ebce977fd2d';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条明确禁止生产经营超过保质期的食品。使用过期的冷冻肉品加工成肉饼属于严重违法行为，无论出于何种目的均不允许。该说法错误。' WHERE id = 'e205c127-1881-436f-9e82-51095ad1b849';
UPDATE public.questions SET analysis = '《食品安全法》第五十条规定，食品生产企业应当建立食品原料、食品添加剂、食品相关产品进货查验记录制度，如实记录相关内容并保存凭证。以上三项均属于法定查验范围。' WHERE id = 'e21b46e0-d15a-40d9-bbfb-581248d98f51';
UPDATE public.questions SET analysis = 'GB 7718《食品安全国家标准 预包装食品标签通则》规定，食品标签不应与食品或者其包装物（容器）分离。标签应牢固附着于包装物上，确保消费者在购买时能看到完整标签信息。该表述正确。' WHERE id = 'e234062e-11a4-457c-90ab-92950b6c89de';
UPDATE public.questions SET analysis = '《食品安全法》及食品生产许可审查细则规定，食糖出厂检验由企业自行检验的，应由具有相应检验能力或资质的检验人员按规定的检验方法检验，确保出厂产品符合标准要求。' WHERE id = 'e23459ce-ab96-4238-995c-78362f8f3869';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》规定，用餐时就餐区应避免受到扬尘活动的影响（如施工、打扫等），防止灰尘落入食品中造成污染。该表述正确。' WHERE id = 'e272f899-6597-45b6-9cd7-ac8c51b04748';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品经营企业应当配备专职或者兼职食品安全管理人员，做好对所经营食品的检验工作，依法从事食品经营活动。该表述正确。' WHERE id = 'e28e0734-5e76-45c2-b621-975b6983c0b1';
UPDATE public.questions SET analysis = '《食品安全法》第九十一条规定，国家出入境检验检疫部门（海关）对进出口食品安全实施监督管理。该表述符合法律规定，说法正确。' WHERE id = 'e2ad15eb-6616-4438-a9ef-31afd73723ed';
UPDATE public.questions SET analysis = '多菌灵是广谱杀菌剂，葡萄酒原料（葡萄）中多菌灵残留超标会导致葡萄酒产品中多菌灵超标，因为多菌灵在酿造过程中不易降解。企业应严格控制原料中农药残留。该说法错误。' WHERE id = 'e2b40ebe-2c08-40c3-bfea-985411920541';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第七十五条规定，其他直接责任人员是指具体实施违法行为并起较大作用的人员，既可以是单位的生产经营管理人员，也可以是普通员工。该表述正确。' WHERE id = 'e2b74e61-4faa-4b1b-a5e1-61761488b2ff';
UPDATE public.questions SET analysis = '碳酸饮料的生产工艺一般包括水处理、糖浆调配、碳酸化、灌装封盖、杀菌（或无菌灌装）、包装等环节。以上各项均属于碳酸饮料的生产工艺步骤。' WHERE id = 'e2c4518d-8bcc-42b0-9475-0ca4dd23dce6';
UPDATE public.questions SET analysis = '淀粉制品生产企业不得采购腐败变质、霉变、生虫、污秽不洁等不合格原料进行生产。合格的淀粉原料应符合相应的食品安全标准要求。使用不合格原料属于违法行为。' WHERE id = 'e2ea7fee-85e6-4c40-b3b4-e1b676252b09';
UPDATE public.questions SET analysis = '《食品安全法实施条例》规定，传统意义的滋补类中药材及其饮片、药食两用物质等不得与特殊食品混放销售，不得放置于特殊食品销售区域，防止误导消费者。该表述正确。' WHERE id = 'e2fc78f2-00d9-41f0-81dd-c7d78fd85f68';
UPDATE public.questions SET analysis = 'GB 2713《食品安全国家标准 淀粉制品》规定，即食类淀粉制品须符合菌落总数、大肠菌群、致病菌（沙门氏菌、金黄色葡萄球菌）等微生物指标的相关要求。以上各项均为必检指标。' WHERE id = 'e3089a6c-68f1-41e8-b7ee-53721dcf955e';
UPDATE public.questions SET analysis = '《食品安全法》第一百四十条规定，对食品作虚假宣传且情节严重的，由省级以上人民政府食品安全监督管理部门决定暂停销售该食品，并向社会公布。省级以上部门有权作出此类处罚决定。' WHERE id = 'e30a1c27-e1d0-4979-924c-fdc60aa24273';
UPDATE public.questions SET analysis = '调味品中化学性危害主要包括原料贮存不当发生霉变产生的生物毒素（如黄曲霉毒素B1）污染风险。选项A、C、D属于物理性或非法添加风险。原料霉变产生的毒素属于化学性危害。' WHERE id = 'e30ea2fc-be82-4fe6-b034-97bd49fba011';
UPDATE public.questions SET analysis = 'GB 14881《食品安全国家标准 食品生产通用卫生规范》规定，食品生产企业应建立设备保养和维修制度，加强设备的日常维护和保养，确保设备正常运行，防止设备故障导致食品安全风险。该表述正确。' WHERE id = 'e31011ca-8ccb-4413-9ad1-fbf09c101f98';
UPDATE public.questions SET analysis = '《网络交易监督管理办法》规定，网络交易经营者应当在其网站首页或者从事经营活动的主页面显著位置，持续公示经营者主体信息或者该信息的链接标识，便于消费者查询和监督。' WHERE id = 'e315884c-bd85-44c4-909b-68c94e761966';
UPDATE public.questions SET analysis = 'GB 14881规定，食品生产企业应加强生产过程中的卫生控制和规范操作，制定并实施微生物监控计划，对生产环境、设备表面、人员进行微生物监测，确保食品安全。' WHERE id = 'e318720f-3419-4eed-b10c-bcdfba58eead';
UPDATE public.questions SET analysis = '《食品安全法》第三十四条明确规定，禁止在食品加工中添加食品添加剂以外的非食用化学物质和其他可能危害人体健康的物质。该表述符合法律规定，说法正确。' WHERE id = 'e329a671-2aaf-41e3-a09a-8bfc500dec32';
UPDATE public.questions SET analysis = '《餐饮服务食品安全操作规范》和《食品经营许可审查通则》规定，销售生鲜畜禽、水产品与散装直接入口食品应有一定距离的物理隔离，防止交叉污染。该表述正确。' WHERE id = 'e32aefa3-8656-4a18-a921-ead55ccadc02';
UPDATE public.questions SET analysis = 'GB 31654《食品安全国家标准 餐饮服务通用卫生规范》于2022年2月22日正式实施（对应Excel日期序列44614）。该标准替代了原《餐饮服务食品安全操作规范》中的基础性卫生要求。' WHERE id = 'e347f15b-f7ba-4c88-bc2f-204b7c59ec42';
