UPDATE public.questions SET analysis = '《食品安全法》第三条明确规定，食品安全工作实行预防为主、风险管理、全程控制、社会共治，建立科学、严格的监督管理制度。四项原则缺一不可，构成了中国食品安全治理的基本方针。' WHERE id = 'fa82e4db-6f8f-4d61-8218-6ec2f5d07f59';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第6.4.2条规定，人员、货物进出通道应设有防鼠板，门的缝隙应小于6mm。这是防止鼠类等有害生物侵入的有效物理屏障措施，适用于餐饮服务场所和食品生产场所。' WHERE id = 'fa97f90f-ae46-4e75-9ff9-6e8cf3cb1909';
UPDATE public.questions SET analysis = '《食品安全法》第四十三条第二款规定，国家鼓励食品生产经营企业参加食品安全责任保险。该条款明确国家持鼓励态度而非限制态度，食品生产企业可自愿参保，通过保险机制分散食品安全风险。' WHERE id = 'fac83d85-a6d5-4cb2-9922-8add10dab29a';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条第二款规定，食品经营企业应当建立食品进货查验记录制度，如实记录食品的名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容，并保存相关凭证。四项内容均为法定必录项。' WHERE id = 'fad5bb76-2e83-43d3-badf-7140a565a6aa';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第四十一条规定，对风险监测结果表明存在食品安全隐患的，食品生产经营者自查确认存在风险隐患的，应当依照食品安全法第六十三条的规定，停止生产、经营，实施食品召回，并向市场监管部门报告相关情况。选项A（继续销售）违反食品安全法。' WHERE id = 'fad5ea36-5aea-4e58-bfe3-4a97bd3ac336';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条第四款规定，实行统一配送经营方式的食品经营企业，可以由企业总部统一查验供货者的许可证和食品合格证明文件，进行食品进货查验记录。该规定考虑了连锁经营的实际特点，允许总部统一查验以提高效率。' WHERE id = 'fadbfbd4-7d30-463b-94db-2b7fb8b880ec';
UPDATE public.questions SET analysis = '《农产品质量安全法》第二条规定，食用农产品是指来源于种植业、林业、畜牧业和渔业等供人食用的初级产品，即在农业活动中获得的供人食用的植物、动物、微生物及其产品。该定义明确了食用农产品的来源范围和产品形态。' WHERE id = 'faef6fe3-4681-4b68-bc4d-4f4f1bbfafdf';
UPDATE public.questions SET analysis = '《食品安全国家标准 蒸馏酒及其配制酒》（GB 2757）规定，白酒重金属限量指标为铅（以Pb计）≤0.5mg/L。铅是白酒中主要的重金属污染物，来源于蒸馏设备、管道和储存容器。镉、铬、镍不是白酒常规限量指标。' WHERE id = 'fb068909-cce7-4dc1-ac8e-f826fb1e7b96';
UPDATE public.questions SET analysis = '《食品安全法》第三十七条规定，利用新的食品原料生产食品，或者生产食品添加剂新品种、食品相关产品新品种，应当向国务院卫生行政部门提交相关产品的安全性评估材料。选项A为监管部门而非评估部门，B负责农业，D负责进出口。' WHERE id = 'fb11e25f-4dc8-4ba1-8001-9a6173923913';
UPDATE public.questions SET analysis = '《食品生产许可分类目录》规定，实施食品生产许可的肉制品分为：热加工熟肉制品、发酵肉制品、预制调理肉制品、腌腊肉制品和可食用动物肠衣。该分类涵盖肉制品全部许可类别。' WHERE id = 'fb17b7ce-67f0-4811-913f-17242b71db4d';
UPDATE public.questions SET analysis = '《食品安全法》第一百一十四条规定，食品生产经营过程中存在食品安全隐患，未及时采取措施消除的，县级以上人民政府食品安全监督管理部门可以对食品生产经营者的法定代表人或者主要负责人进行责任约谈。责任约谈情况和整改情况应当纳入食品安全信用档案。' WHERE id = 'fb1da00d-679e-4867-a664-8107938a5cd4';
UPDATE public.questions SET analysis = '《特殊医学用途配方食品注册管理办法》第十六条规定，国家食品药品监督管理总局应当自受理申请之日起20个工作日内对特殊医学用途配方食品注册申请作出是否准予注册的决定。20个工作日为法定审查时限。' WHERE id = 'fb29462d-a719-406f-8315-fb451b4821e1';
UPDATE public.questions SET analysis = '《食品安全国家标准 鲜、冻动物性水产品》（GB 2733）是动物性水产原料应符合的食品安全国家标准。GB 19295为速冻面米制品标准，GB 20941为水产制品生产卫生规范，GB 19643为藻类制品标准。' WHERE id = 'fb2a485f-f0aa-42c9-a688-09ca66137fda';
UPDATE public.questions SET analysis = '《食品安全法》第一百四十八条第二款规定，生产不符合食品安全标准的食品或者经营明知是不符合食品安全标准的食品，消费者除要求赔偿损失外，还可以向生产者或者经营者要求支付价款十倍或者损失三倍的赔偿金。十倍赔偿为惩罚性赔偿，体现了对明知销售行为的严厉惩戒。' WHERE id = 'fb3b2397-756a-4934-ad0e-d419ab16b9c0';
UPDATE public.questions SET analysis = '《食品安全法》第五条及农业农村部三定方案规定，农业农村部负责农产品质量安全监督管理，组织开展农产品质量安全监测、追溯、风险评估，提出技术性贸易措施建议，参与制定农产品质量安全国家标准并会同有关部门组织实施，指导农业检验检测体系建设。' WHERE id = 'fb3e076d-18a9-455d-8585-db9631ae487e';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第十条第二款规定，取得食品生产许可的食品生产者，在其生产加工场所或者通过网络销售其生产的食品的，不需要取得食品经营许可。但有股权关系的线下连锁/非连锁经营主体销售则需另行取得许可。' WHERE id = 'fb618c4e-23f5-43fd-b79c-bd50c2a24ee7';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》（总局令第60号）第六条规定，食品生产经营企业主要负责人应当支持和保障食品安全总监、食品安全员依法开展食品安全管理工作。在作出涉及食品安全的重大决策前，应当充分听取食品安全总监和食品安全员的意见和建议。' WHERE id = 'fb8eadd8-8457-4607-85df-7d649c68f92f';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条第二款规定，食品进货查验记录应当如实记录食品的名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容。供应商信息是追溯链条的关键环节。' WHERE id = 'fba128d4-092f-41aa-9516-935c4545f0af';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》第四十二条规定，保健食品注册证书有效期为5年。注册人应当在有效期届满前6个月申请延续注册。5年有效期兼顾了产品安全性再评估和监管需要。' WHERE id = 'fbad0bac-1401-40e4-9202-22898a6eda8d';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第十六条规定，核查人员应当自接受现场核查任务之日起5个工作日内，完成对经营场所的现场核查。5个工作日为法定核查时限。' WHERE id = 'fbb46335-a62d-4fbe-8f1d-14f4de3a5877';
UPDATE public.questions SET analysis = '《反食品浪费法》第十二条规定，超市、商场等食品经营者应当对其经营的食品加强日常检查，对临近保质期的食品分类管理，作特别标示或者集中陈列出售。以优惠价格销售是常见的促销方式，选项D（封存等待退货）不属于常规管理措施。' WHERE id = 'fbd5cbc1-6677-4c0c-aed0-416ff765b086';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第三十九条规定，特殊食品不得与普通食品或者药品混放销售。保健食品、特殊医学用途配方食品和婴幼儿配方乳粉应当设立专柜或者专区销售，并设置提示牌，以保障消费者的知情权和选择权。' WHERE id = 'fbe38114-be5d-4d86-a43a-f965a7b67abe';
UPDATE public.questions SET analysis = '《食品安全法》第七十条规定，食品添加剂应当有标签、说明书和包装，标签上载明''食品添加剂''字样。《食品添加剂生产监督管理规定》明确营养强化剂属于食品添加剂，需有标签、包装，并标注''食品添加剂''字样。但不得标注疾病预防、治疗功能。' WHERE id = 'fbefc163-c5ec-4df6-972c-60f090dfe7cf';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第二十七条第一款规定，食品经营许可证载明的许可事项发生变化的，食品经营者应当在变化后10个工作日内向原发证的市场监督管理部门申请变更经营许可。' WHERE id = 'fc0c0691-35fc-47cd-9491-94377fba2253';
UPDATE public.questions SET analysis = '《食品安全法》第六十八条规定，散装食品对保存条件和食用方式有特殊要求的，应当在标签上注明。如需要冷藏、加热后食用等提示，以保障消费者正确食用，避免因不当食用引发食品安全问题。' WHERE id = 'fc0c2f2c-3349-49d2-83ff-7315e75eb391';
UPDATE public.questions SET analysis = '《食品安全国家标准 蒸馏酒及其配制酒》（GB 2757）及《白酒》（GB/T 10781）规定，固形物是白酒的重要品质指标。白酒中固形物超标是常见的不合格品质指标。甜蜜素、安赛蜜为甜味剂，属食品添加剂，不是品质指标。' WHERE id = 'fc13eae8-79d8-44ac-8bc3-d681b92a0ac9';
UPDATE public.questions SET analysis = '《农产品质量安全法》第三十五条规定，农产品销售企业对其销售的农产品，应当建立健全进货检查验收制度。该法条明确主体为''农产品销售企业''，个人销售者、生产企业和农民专业合作社适用不同的管理规定。' WHERE id = 'fc1867a6-bca6-494e-8c33-0be6a8459dd6';
UPDATE public.questions SET analysis = '《食品安全法》第四十四条第三款规定，食品生产经营企业应当配备食品安全管理人员，加强对其培训和考试。经考核不具备食品安全管理能力的，不得上岗。这是保障食品安全管理专业化、规范化的重要制度安排。' WHERE id = 'fc5ffba5-7e48-4ee8-89cd-8f82504a5441';
UPDATE public.questions SET analysis = '《食品安全法》第六十八条规定，食品经营者销售散装食品，应当在散装食品的容器、外包装上标明食品的名称、生产日期或者生产批号、保质期以及生产经营者名称、地址、联系方式等内容。保质期是保障散装食品食用安全的关键信息。' WHERE id = 'fc679437-559f-4a7e-b7a4-05edc5c598cd';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第4.2.3.3条规定，蒸汽、水、电等配件管路应尽量避免设置于暴露食品的上方；如确需设置，应有能防止灰尘散落及水滴掉落的装置或措施，避免对食品造成物理和生物污染。' WHERE id = 'fc835e59-36f8-4e3c-9d92-ba80390fc257';
UPDATE public.questions SET analysis = '《食品安全法》第三十条规定，国家鼓励食品生产企业制定严于食品安全国家标准或者地方标准的企业标准，在本企业适用，并报省、自治区、直辖市人民政府卫生行政部门备案。严于国标的企业标准有助于提升企业产品质量竞争力。' WHERE id = 'fc8e64a8-2c18-4f5a-9e25-c9787dce6347';
UPDATE public.questions SET analysis = '《食品安全国家标准 可可粉》（GB/T 20706）规定，碱化可可粉的pH值应在6.2-7.5范围内（因碱化程度不同而异），并非''6.8以上''。天然可可粉pH值约5.0-5.8，碱化后pH值升高。题目说法过于绝对，不符合标准规定。' WHERE id = 'fc92a1a3-a736-418e-9ed5-baab90454eb8';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》（总局令第60号）第六条规定，因食品安全犯罪被判处有期徒刑以上刑罚的人员，终身不得担任食品安全总监、食品安全员。这是最为严厉的从业禁止规定，体现了对食品安全犯罪的零容忍。' WHERE id = 'fc9676fd-9ae2-4d85-923f-fcc772402915';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》第二十二条规定，审评机构应当自收到受理材料之日起60个工作日内根据核查报告、检验报告以及专家意见完成技术审评工作，并作出审查结论。60个工作日为法定审评时限。' WHERE id = 'fc97d197-91c2-4c46-a716-0df0c4010e6e';
UPDATE public.questions SET analysis = '《食品安全国家标准 果冻》（GB 19299）规定微生物指标包括大肠菌群（MPN法）≤10CFU/g。沙门氏菌和金黄色葡萄球菌不是果冻的常规微生物指标。枯草芽孢杆菌不是标准致病菌指标。' WHERE id = 'fca74384-bbd8-4daa-b3fc-b7ea3b9432ff';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》第四十二条规定，企业依法终止的，由国家市场监督管理总局注销其婴幼儿配方乳粉产品配方注册。选项B、C、D属于应当''撤销''注册的情形，而非''注销''。注销适用于企业主体灭失等客观情形。' WHERE id = 'fcbd9703-daa6-44fb-951a-1aabfdb1f2ea';
UPDATE public.questions SET analysis = '《食品安全法》第四十六条规定，食品生产企业应当就以下方面制定并实施控制要求：原料采购、验收、投料等原料控制；生产工序、设备、贮存、包装等关键环节控制；原料检验、半成品检验、成品出厂检验等检验控制；运输和交付控制。四项均为法定必选项。' WHERE id = 'fcd48a2a-f76e-4f72-b1bd-c8faa367545e';
UPDATE public.questions SET analysis = '《食品安全国家标准 预包装食品标签通则》（GB 7718-2011）第4.3.2条规定，当预包装食品包装物或包装容器的最大表面面积小于10cm²时（而非20cm²），可以只标示产品名称、净含量、生产者（或经销商）的名称和地址，但仍需标示配料表。20cm²的阈值不符合标准要求。' WHERE id = 'fcd73450-010c-4079-902d-f5e6056f3c4f';
UPDATE public.questions SET analysis = '《食品安全法》第一百二十三条规定，生产经营营养成分不符合标准的婴幼儿食品、生产经营国家明令禁止的食品、生产经营添加药品的食品，情节严重尚不构成犯罪的，可由公安机关处5-15日拘留。选项C（污染物超标）适用第一百二十四条，但不在拘留条款范围内。' WHERE id = 'fcd923d5-9cb0-400f-bd82-c007d491b7ef';
UPDATE public.questions SET analysis = '鲜蛋中可能存在的致病微生物主要包括沙门氏菌（禽类肠道常见菌，可污染蛋壳或进入蛋内）、大肠杆菌（蛋壳表面及肠道污染）和弯曲杆菌（禽类携带）。菌落总数是卫生指标而非特定致病微生物。' WHERE id = 'fcdb4abb-33e4-4718-b1bc-dd386c7373eb';
UPDATE public.questions SET analysis = '《农产品质量安全法》第三条规定，农产品生产经营者应当对其生产经营的农产品质量安全负责。农产品生产经营者是农产品质量安全的第一责任人，应依照法律法规从事生产经营活动，保证农产品质量安全。' WHERE id = 'fcdbb6c8-4165-44ad-bfc2-27ef10523975';
UPDATE public.questions SET analysis = '《食品安全法》第三十三条规定，食品生产经营企业应配备专职或兼职食品安全管理人员；第四十四条规定应加强培训和考试；第一百三十五条规定被吊销许可证的直接责任人员五年内不得担任食品安全管理人员。因食品安全犯罪被判处刑罚的人员终身不得从事食品安全管理工作，选项D错误。' WHERE id = 'fce66ea5-1c5e-4e31-a506-40b00770c1aa';
UPDATE public.questions SET analysis = '《复配食品添加剂通则》（GB 26687-2011）规定：由单一功能复配的品种应按终端功能命名；不应产生健康危害；应尽可能降低用量。但生产管理制度必须制定各种食品添加剂的含量和检验方法，选项C错误。' WHERE id = 'fcf34490-66c5-4aee-9cc2-4ea0e7bbbbfc';
UPDATE public.questions SET analysis = '《食品安全法》第一百三十四条规定，食品经营者在一年内累计三次因违反本法规定受到责令停产停业、吊销许可证以外处罚的，由食品安全监督管理部门责令停产停业，直至吊销许可证。3次是法定累计次数。' WHERE id = 'fd01f56f-a278-4aca-a3dd-01425991d626';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品添加剂使用标准》（GB 2760）规定，黄酒生产中允许使用的焦糖色包括普通法、氨法和亚硫酸铵法生产的焦糖色，不得使用苛性硫酸盐法生产的焦糖色。苛性硫酸盐法焦糖色含4-甲基咪唑等风险物质。' WHERE id = 'fd1abaa0-1a02-42f5-8d94-d14f1ebd1058';
UPDATE public.questions SET analysis = '《食品安全法》第四十八条规定，国家鼓励食品生产经营企业符合良好生产规范要求，实施危害分析与关键控制点体系，提高食品安全管理水平。企业可按照GMP和HACCP体系对生产过程进行食品安全控制，预防食品安全风险。' WHERE id = 'fd252774-3426-4a0e-837b-b5a9b07cd3a0';
UPDATE public.questions SET analysis = '《食品安全法》及食品安全风险评估技术指南将故意添加非食用物质、超范围超限量使用添加剂、故意使用回收食品等行为定义为''非传统风险''（即人为故意风险），区别于自然产生的传统风险，需采取更严厉的监管措施。' WHERE id = 'fd2d1d9e-4449-4b2b-9d12-864d8fa50afa';
UPDATE public.questions SET analysis = '《食品安全法》第九十二条规定，进口的食品、食品添加剂应当经出入境检验检疫机构依照进出口商品检验相关法律、行政法规的规定检验合格。验证进口食品添加剂每批应查验出入境检验部门的检测报告（入境货物检验检疫证明）。' WHERE id = 'fd32d2dd-6263-4e74-aced-d83ff53d2381';
UPDATE public.questions SET analysis = '《食品经营许可管理办法》第十二条规定，食品经营许可证载明的许可事项包括：经营者名称、社会信用代码、法定代表人（负责人）、住所、经营场所、主体业态、经营项目、许可证编号、有效期、日常监督管理机构、日常监督管理人员、投诉举报电话、发证机关、签发人、发证日期和二维码。''其他事项''不属于许可事项。' WHERE id = 'fd45e039-d6fc-45f2-96a5-4c433aee9ae6';
UPDATE public.questions SET analysis = '《食品安全法》第五十三条规定，食品经营者采购食品，应当查验供货者的许可证和食品出厂检验合格证或者其他合格证明。营业执照用于确认经营主体资格，也是应当查验的证照。健康证是食品从业人员的健康证明，不是供货商必备证照。' WHERE id = 'fd488949-b785-4e7f-82b0-6a3f80d2a4e2';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，食品生产者发现其生产的食品不符合食品安全标准或者有证据证明可能危害人体健康的，应当立即停止生产，召回已经上市销售的食品。技术落后和食品滞销不属于召回法定情形。' WHERE id = 'fd79a019-8a33-451f-9139-cbe2cc1285ee';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条规定，对召回的食品应采取无害化处理、销毁等措施；标签不合格食品经补救可继续销售并明示补救措施；应向市场监管部门报告召回和处理情况；需要无害化处理、销毁的应提前报告时间、地点。四项均为法定要求。' WHERE id = 'fd99d894-fb05-44ad-934d-2517ab7e953b';
UPDATE public.questions SET analysis = '《保健食品经营监督管理办法》规定，保健食品经营场所应设置''保健食品专区''提示牌、公示投诉举报电话和日常监督检查结果记录表。进货查验记录是企业内部管理档案，无需在经营场所公示。' WHERE id = 'fd9d56ac-b2c6-4ba5-8d42-b002e41b507e';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》第四十九条规定，改变产品标签、说明书的变更申请，应当提供拟变更的保健食品标签、说明书样稿。不需提供图片、检验报告或样品。' WHERE id = 'fda0c5cb-5125-4382-8cb3-67df1c12db52';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》于2016年2月4日经国家食品药品监督管理总局局务会议审议通过，自2016年7月1日起施行。该办法是保健食品注册与备案管理的纲领性文件。' WHERE id = 'fda726b1-6309-4740-bf34-806447667da4';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》第十四条规定，食品安全管理人员监督抽查考核结果应当公布，考核不合格的，应当立即停止食品安全管理人员履职，并进行培训考核，合格后方可继续履职。考核结果应向社会公开，以促进食品安全管理人员履职。' WHERE id = 'fdac23cd-6244-4f2b-be70-e90f03b4e4ae';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》第三十四条规定，婴幼儿配方乳粉标签和说明书不得涉及疾病预防、治疗功能；不得明示或暗示保健作用；不得明示或暗示益智等功能性表述；不得以''不添加''''不含有''等字样强调未使用不应含有的物质。四项均为禁止内容。' WHERE id = 'fdae03a4-0d87-4d82-a043-2dd9964e8322';
UPDATE public.questions SET analysis = '《食品安全法》第五十条及《食品生产通用卫生规范》（GB 14881）规定，食品原料、食品添加剂和食品相关产品进货查验记录、食品出厂检验记录应当由记录人员和审核人员签名或签章，并标注记录日期。仅记录人员签名不符合标准要求。' WHERE id = 'fdaf3337-c379-4fee-90a4-12b093646f28';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第8.4.2条规定，生产线监控应避免使用水银温度计，以免破损后造成玻璃异物污染以及汞化学污染。应使用电子温度计或红外测温仪等替代设备。' WHERE id = 'fdba6a8e-ef0a-4924-bf42-8b0f11a54dac';
UPDATE public.questions SET analysis = '《食品安全法》第一百零三条规定，任何单位和个人不得对食品安全事故隐瞒、谎报、缓报，不得隐匿、伪造、毁灭有关证据，不得阻挠、干涉食品安全事故的调查处理。四项行为均为法律明令禁止。' WHERE id = 'fdbdfe21-4bd5-4f99-8fb7-1782cb15bf2a';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第四十一条规定，对责令召回或者停止经营，仍拒不执行的食品生产经营者，市场监管部门可以依据《食品安全法》第一百二十四条实施查处，依法给予行政处罚。' WHERE id = 'fdced6cc-b6dc-4ed7-b9ce-34811c1caf02';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品接触材料及制品用添加剂使用标准》（GB 9685）及风险评估研究表明，发酵酒生产过程中塑料材质工器具的使用是导致酒中存在塑化剂（邻苯二甲酸酯类）的主要因素。应尽量减少塑料制品的使用，采用不锈钢等替代材料。' WHERE id = 'fdcfee0f-dcf0-4142-9e4f-91f9eb0e764f';
UPDATE public.questions SET analysis = '《婴幼儿配方乳粉产品配方注册管理办法》第三十二条规定，申请人对审评机构不予注册审评结论有异议的，应当自收到通知之日起20个工作日内向审评机构提出书面复审申请。20个工作日为法定申请期限。' WHERE id = 'fdd31d96-b4a6-45e8-8465-9305fedad7b3';
UPDATE public.questions SET analysis = '《食品安全法》第六十三条第三款规定，对因标签、标志或者说明书不符合食品安全标准而被召回的食品，食品生产者在采取补救措施且能保证食品安全的情况下可以继续销售；销售时应当向消费者明示补救措施。' WHERE id = 'fe022ddf-b30f-4f08-b45d-abb4f96ea309';
UPDATE public.questions SET analysis = '《食品安全国家标准 蛋与蛋制品》（GB 2749）是蛋制品原料控制环节对鲜蛋进行感官查验的依据标准。GB 21710为蛋与蛋制品生产卫生规范，GB 2760为食品添加剂使用标准，GB 29921为食品中致病菌限量标准。' WHERE id = 'fe040f2f-02ef-413f-a33b-fd042897fced';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第2.6条规定，分隔是指通过设置物理阻断如墙壁、屏障、遮板等方式，将物品、设施、区域进行隔离。仅留空间不属于分隔，不能有效防止交叉污染。' WHERE id = 'fe133a5f-c99b-4811-8b30-e132c0b3a71e';
UPDATE public.questions SET analysis = '华枝睾吸虫（肝吸虫）是鱼体和贝类中最常见的寄生虫，人因食用含有活囊蚴的淡水鱼虾而感染。阔节裂头绦虫主要存在于淡水鱼类，异形吸虫存在于鱼类，无饰线虫存在于海洋鱼类。华枝睾吸虫感染是全球最常见的食源性寄生虫病之一。' WHERE id = 'fe1af5c7-ecb3-4bc4-8cea-baebc00daa6c';
UPDATE public.questions SET analysis = '《企业落实食品安全主体责任监督管理规定》第六条规定，因食品安全违法被吊销许可证的企业，其法定代表人、直接负责的主管人员和其他直接责任人员，自处罚决定作出之日起五年内不得担任食品安全总监、食品安全员。' WHERE id = 'fe1efdf8-ef32-4959-b18c-ea229521365d';
UPDATE public.questions SET analysis = '《食品安全法》第七十九条规定，保健食品广告应当声明''本品不能代替药物''；《广告法》第十八条规定，保健食品广告应当显著标明''本品不能代替药物''。该声明是保健食品广告的法定必备内容。' WHERE id = 'fe1fab3c-7123-442e-a393-13276fb91281';
UPDATE public.questions SET analysis = '《刑法》第一百四十四条规定，在生产、销售的食品中掺入有毒、有害的非食品原料的，对人体健康造成严重危害或者有其他严重情节的，处五年以上十年以下有期徒刑，并处罚金。这是生产、销售有毒有害食品罪的加重处罚情节。' WHERE id = 'fe2777c1-b927-4acc-b45d-22b26fb2a165';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第6.3.2条规定，进入作业区域应规范穿着洁净的工作服，并按要求洗手、消毒。不得携带私人物品，不得在作业区域吸烟、饮食。选项A、B、C均为不符合卫生要求的行为。' WHERE id = 'fe36fde2-8ca3-4eeb-a7e6-930eef7f60fb';
UPDATE public.questions SET analysis = '《刑法》第一百四十四条规定，在生产、销售的食品中掺入有毒、有害的非食品原料的，或者销售明知掺有有毒、有害的非食品原料的食品的，处五年以下有期徒刑，并处罚金。这是生产、销售有毒有害食品罪的基本刑。' WHERE id = 'fe58bc95-c893-4f7b-8f3b-fb49322bcc92';
UPDATE public.questions SET analysis = '《食品安全法》第四十四条、第四十七条及《特殊食品经营监督管理办法》规定，特殊食品经营企业应当建立健全索票索证和进货查验记录制度、从业人员健康管理制度、食品安全培训制度、不安全食品处置制度等。四项均为法定要求。' WHERE id = 'fe882e90-1ce1-4c61-b88f-10b0f969e772';
UPDATE public.questions SET analysis = '《食品安全法实施条例》第七十五条规定，直接负责的主管人员是指在违法行为中负有直接管理责任的人员，包括食品安全总监等。该定义为追究食品安全违法行为法律责任提供了明确的认定标准。' WHERE id = 'fea03e6f-352d-4554-b3b9-5d47e2088c28';
UPDATE public.questions SET analysis = '《食品安全法》第四十八条规定，认证机构实施跟踪调查不得收取费用。认证机构对通过GMP和HACCP体系认证的食品生产经营企业依法实施跟踪调查，属于认证后续监管义务，不得额外收费。' WHERE id = 'feb6a8ce-9146-4492-a495-c420c62b843a';
UPDATE public.questions SET analysis = '《食品安全国家标准 膨化食品》（GB 17401）及生产工艺要求，油炸型膨化食品的工艺流程包括配料、蒸煮、揉练、成型、干燥、油炸、赋味、包装等。揉练是将淀粉糊化物进行揉搓练制的重要工序，影响产品质地和膨化效果。' WHERE id = 'febdf848-5783-44dd-9874-ed89b8799447';
UPDATE public.questions SET analysis = '《食品安全法》第八十七条规定，县级以上人民政府食品安全监督管理部门（市场监督管理部门）应当对食品进行定期或者不定期的抽样检验，并依据有关规定公布检验结果。市场监督管理部门是实施食品安全抽样检验的法定主体。' WHERE id = 'fed8141b-28e6-4491-8164-f720c7a31807';
UPDATE public.questions SET analysis = '《刑法》第一百四十三条规定，生产、销售不符合食品安全标准的食品，足以造成严重食物中毒事故或者其他严重食源性疾病的，处三年以下有期徒刑或者拘役，并处罚金。这是生产、销售不符合安全标准食品罪的基本刑。' WHERE id = 'fedb3624-e589-44fa-81c0-42e01e94f3d5';
UPDATE public.questions SET analysis = '食品安全风险评估研究表明，膨化食品生产过程中加热温度、时间等控制不当，易产生丙烯酰胺。丙烯酰胺是美拉德反应的产物，在高温（>120℃）加工富含淀粉的食品时容易生成，被IARC列为2A类可能致癌物。' WHERE id = 'fef5770d-0da1-4da5-b79d-bda0f8a061d5';
UPDATE public.questions SET analysis = '《生猪屠宰管理条例》第二条规定，国家实行生猪定点屠宰、集中检疫制度。从事生猪产品销售、肉食品生产加工的单位和个人以及餐饮服务经营者、集中用餐单位生产经营的生猪产品，必须是生猪定点屠宰厂（场）经检疫和肉品品质检验合格的生猪产品。' WHERE id = 'fefeaa8d-6d3a-4838-8a64-7b76777f5371';
UPDATE public.questions SET analysis = '《未成年人保护法》第五十九条规定，学校、幼儿园周边不得设置烟、酒销售网点；禁止向未成年人销售烟、酒；经营者应设置不向未成年人销售的标志；任何人不得在学校、幼儿园和其他未成年人集中活动的公共场所吸烟、饮酒。四项均为法定要求。' WHERE id = 'ff0b5a61-ff78-4de3-8903-8873b0e812b9';
UPDATE public.questions SET analysis = '速冻食品生产中可能存在生产环境不达标、加工过程中加热熟制不彻底及储运过程中温度控制不严等问题，导致产品微生物超标。根据《食品安全国家标准 速冻面米与调制食品》（GB 19295-2021），速冻食品应在-18℃以下储运，且加工过程需严格控制微生物污染。' WHERE id = 'ff114c6f-e402-42c3-9fa7-feb813cf5555';
UPDATE public.questions SET analysis = '《食品安全法》第四十八条规定，国家鼓励食品生产经营企业符合良好生产规范要求，实施危害分析与关键控制点体系，提高食品安全管理水平。GMP和HACCP是国际上公认的先进食品安全管理体系。' WHERE id = 'ff139602-1ffc-4594-8d7f-0b0d9476109d';
UPDATE public.questions SET analysis = '《食品安全法》第四十五条及国家卫健委《有碍食品安全的疾病目录》规定，霍乱、细菌性和阿米巴性痢疾、伤寒和副伤寒、病毒性肝炎（甲型、戊型）、活动性肺结核、化脓性或者渗出性皮肤病等有碍食品安全的疾病患者，不得从事接触直接入口食品的工作。' WHERE id = 'ff15c06b-62f2-4bc5-814e-ca7b7e272d9c';
UPDATE public.questions SET analysis = '《网络食品安全违法行为查处办法》第二条规定，本办法适用于网络食品交易第三方平台提供者、通过第三方平台进行交易的食品生产经营者、通过自建网站进行交易的食品生产经营者违反食品安全法律、法规、规章或者食品安全标准行为的查处。适用范围涵盖所有网络食品经营主体。' WHERE id = 'ff2fe462-7242-47d2-8bd3-58c1cc1158d5';
UPDATE public.questions SET analysis = '《食品生产经营风险分级管理办法》第七条规定，食品生产经营者的风险等级从低到高分为A级风险、B级风险、C级风险、D级风险四个等级。市场监管部门根据静态风险因素、动态风险因素和通用风险因素量化分值确定风险等级。' WHERE id = 'ff30e0b8-9edb-4723-9fb1-722dad91203b';
UPDATE public.questions SET analysis = '《食品安全国家标准 茶叶》（GB/T 30766）及茶叶分类标准规定，青砖茶属于紧压茶类，是以老青茶为原料经压制成型的茶类。紧压茶是通过蒸压成型的工艺制成的块状或饼状茶叶。' WHERE id = 'ff475b45-1217-4d61-8b91-7a82e3273fb3';
UPDATE public.questions SET analysis = '《消费者权益保护法》第三十九条规定，消费者和经营者发生消费者权益争议的，可以通过下列途径解决：与经营者协商和解；请求消费者协会或者依法成立的其他调解组织调解；向有关行政部门投诉；根据与经营者达成的仲裁协议提请仲裁机构仲裁；向人民法院提起诉讼。四项均为法定解决途径。' WHERE id = 'ff52f6fb-1186-4048-9acd-925f9c6b6c15';
UPDATE public.questions SET analysis = '《食品安全国家标准 罐头食品生产卫生规范》规定，罐头杀菌锅应配备温度时间自动记录仪器，其温度应与水银温度计一致（而非略高于），以确保杀菌效果和产品安全。温度偏高可能导致杀菌过度影响品质，偏低则可能导致杀菌不彻底引发安全风险。' WHERE id = 'ff623961-bc77-4431-8a67-81ba820d0e07';
UPDATE public.questions SET analysis = '《食品生产经营风险分级管理办法》第七条规定，食品生产经营者的风险等级从低到高分为A级风险、B级风险、C级风险、D级风险四个等级，而非''好、中、差''三个等级。题目表述与法规规定不符。' WHERE id = 'ff6840ce-590c-46d1-9cc9-9c43bffc5671';
UPDATE public.questions SET analysis = '《食品安全国家标准 较大婴儿配方食品》（GB 10766）规定，较大婴儿配方乳粉为2段，适用月龄为6-12月龄。1段为婴儿配方乳粉（0-6月龄），3段为幼儿配方乳粉（12-36月龄）。' WHERE id = 'ff74cc51-ea41-47b3-bbb8-17705903b65b';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品生产通用卫生规范》（GB 14881-2013）第4.2.2.1条规定，顶棚应使用无毒、无味材料建造，易于清洁消毒，不利于冷凝水垂直滴下；第4.2.2.3条规定蒸汽、水、电等管路应避免设置于暴露食品上方。屋顶内层喷涂涂料可作为顶棚，选项B错误。' WHERE id = 'ff9a20cb-c801-41ba-afe3-7d34a51a5960';
UPDATE public.questions SET analysis = '原料水果的化学性风险点主要包括农药残留（种植过程中使用的杀虫剂、杀菌剂等残留）和污染物（如重金属、持久性有机污染物等）。微生物属于生物性风险，金属异物属于物理性风险，均不属于化学性风险。' WHERE id = 'ffa232eb-6eff-4bdd-86a5-97df396482a7';
UPDATE public.questions SET analysis = '《食品安全国家标准 食品添加剂使用标准》（GB 2760）规定，罐头食品应严格控制食品添加剂使用，防止超范围、超限量（超剂量）使用。超范围是指使用了不该用的添加剂，超限量是指使用量超过了最大使用量。两项均为罐头食品生产中的重点监管内容。' WHERE id = 'ffa26a1f-ec48-4c78-be96-931790a99947';
UPDATE public.questions SET analysis = '《食品安全法》第四十七条规定，食品生产经营企业应当建立食品安全自查制度，定期对食品安全状况进行检查评价。''不定期''检查不符合法定要求，企业应当制定定期自查计划，确保食品安全管理的持续性和规范性。' WHERE id = 'ffb1b929-8df7-412a-8080-1f9773990b8e';
UPDATE public.questions SET analysis = '《食品安全法》第三十七条规定，使用现在允许之外的食品、食品添加剂、食品相关产品新品种或新范围等，需向国务院卫生行政部门提交''三新食品''的注册和审批材料，审批通过后方可按规定使用。国务院卫生行政部门负责食品安全风险评估和新品种审批。' WHERE id = 'ffc60eac-a651-43e2-b4ee-565cd1ceef07';
UPDATE public.questions SET analysis = '《保健食品注册与备案管理办法》第六十八条规定，备案材料虚假、备案产品存在安全性问题、保健食品生产企业生产许可被依法吊销或注销的、备案人申请取消备案的，食品药品监督管理部门应当取消保健食品备案。四项均为法定取消备案情形。' WHERE id = 'ffe69b1f-b1af-457b-ac5c-7dfd7ce2f98d';
UPDATE public.questions SET analysis = '《食品安全国家标准 速冻面米与调制食品》（GB 19295-2021）适用于速冻面米食品和速冻调制食品，不适用于速冻动物性水产制品。速冻动物性水产制品适用《食品安全国家标准 动物性水产制品》（GB 10136）。' WHERE id = 'fff1e99b-f38c-4a4a-a4d7-0b6ec812aacb';
UPDATE public.questions SET analysis = '《食品安全法》第四十八条第三款规定，鼓励食品生产企业选择食品安全第三方专业机构对自身的食品生产管理体系进行评价，评价结果作为日常监督检查的参考。第三方评价有助于企业发现管理漏洞，提升食品安全管理水平。' WHERE id = 'fffa1d83-329e-4cd6-a55f-66e8a3533fce';

